// ---------------------------------------------------------------------------
// Error types
// ---------------------------------------------------------------------------

/// Errors that can occur during compilation through the [`Compiler`] API.
#[derive(Debug, Error)]
pub enum CompileError {
    #[error(transparent)]
    JitIdentityEncoding(#[from] crate::jit_cert::JitIdentityEncodingError),
    /// A typed Core installation continuation lacks a required existing contract.
    #[error("Core installation contract refused: {0}")]
    CoreInstallationContract(String),
    #[error("invalid execution resource budget: {0}")]
    ResourceBudget(#[from] trust_cg_process_env::resource_budget::ResourceBudgetError),
    /// trust_ir to LIR adapter translation failed.
    #[error("adapter error: {0}")]
    Adapter(#[from] trust_cg_lower::AdapterError),

    /// WS7.3: trust-ir's own codegen validator refused the module at an
    /// ingestion entry ([`crate::ingest::admit_module`]). Carries every
    /// finding; the message names the first three and the count.
    #[error("{0}")]
    InvalidTrustIr(trust_cg_lower::InvalidTrustIr),

    /// An optimization pass changed the function's VOLATILE ACCESS TRACE.
    ///
    /// A volatile access is observable: the program asked for exactly these
    /// accesses, at these widths, in these directions. A pass that elides,
    /// duplicates, widens, narrows, redirects or reorders one has produced
    /// wrong code, and there is no byte-level check downstream that would
    /// catch it — the emitted bytes of a volatile MOV are identical to the
    /// plain form's. So the compile FAILS CLOSED here.
    #[error("volatile access trace changed in `{function}`: {violation}")]
    VolatileTraceChanged {
        /// The function whose trace changed.
        function: String,
        /// Which hazard, in the obligation's own words.
        violation: String,
    },

    /// AOT compilation found an ordinary direct call to a bodied
    /// Internal/Private function, but the selected object path cannot yet
    /// prove a local/non-preemptible binding for that target. Only the
    /// AArch64 ELF and Mach-O and the x86-64 ELF object paths bind such
    /// references locally ([`Compiler::object_binds_module_local_functions`],
    /// x86-64 ELF since ruling OD-X86-ELF-LOCAL-BINDING-20261027); every other
    /// target refuses them here.
    #[error(
        "AOT direct module-function binding is unsupported for target {target}: refusing \
         {call_count} non-preemptible direct call(s) before object emission"
    )]
    AotDirectModuleFunctionBindingUnsupported {
        /// Exact object target whose writer lacks end-to-end binding authority.
        target: String,
        /// Non-preemptible direct edges that would otherwise be interposable.
        call_count: usize,
    },

    /// AOT compilation found a materialized in-module function identity, but
    /// the selected object path cannot yet prove that the target is bound
    /// locally/non-preemptibly. Emitting an `FnDef` or capture-free `Closure`
    /// through an ordinary global relocation would let the linker replace the
    /// identity the source module names, even when the value escapes or feeds
    /// an incompatible/dynamically selected call. A `SymbolAddr` constant
    /// whose string names such a function counts as one too
    /// ([`trust_cg_lower::ModuleLocalFunctionIdentityCensus::symbol_addresses`]):
    /// the object resolves the string through the definition's own symbol.
    /// As for direct calls, only the AArch64 ELF and Mach-O and the x86-64 ELF
    /// object paths are exempt.
    #[error(
        "AOT static function identity is not yet binding-safe for target {target}: \
         refusing {candidate_count} in-module function identity materialization(s) before object \
         emission"
    )]
    AotStaticFunctionIdentityBindingUnsupported {
        /// Exact object target whose writers lack end-to-end binding authority.
        target: String,
        /// Materialized local function identities whose binding would be at risk.
        candidate_count: usize,
    },

    /// The module defines a bodied Internal/Private function named like a
    /// symbol the backend references or interprets by name on its own: one of
    /// the [`trust_cg_lower::RuntimeSymbol`] list (`memcpy`, `fmod`,
    /// `__divti3`, `_Unwind_Resume`, `__stack_chk_fail`, `malloc`,
    /// `__rust_alloc`, `__sincos_stret`, `calloc`, ...). Every object writer
    /// and the JIT resolve such a reference through the module's own symbols
    /// first (and the module inliner may splice the body in), so the module
    /// is refused before lowering, on every target and in the JIT, whether or
    /// not this module makes that reference ([`trust_cg_lower::backend_symbol_shadow`]).
    /// On an Apple AArch64 object it is also a module-local `sin` or `cos`
    /// that a body references: the Darwin `sincos-merge` pass interprets
    /// those calls by name and would replace them with libm's
    /// ([`refuse_darwin_sincos_merge_shadow`]).
    #[error(
        "module-local function `{function}` on target {target} is named like a runtime symbol \
         the backend references or interprets by that name; such a reference would bind to the \
         module's body, or the module's call would be replaced (fail-closed)"
    )]
    ModuleLocalFunctionShadowsRuntimeSymbol {
        /// Compile target.
        target: String,
        /// The Internal/Private function.
        function: String,
    },

    /// The module defines DATA that a reference the backend makes by name on
    /// its own would reach ([`trust_cg_lower::backend_symbol_shadow`]):
    /// Internal/Private data named like any [`trust_cg_lower::RuntimeSymbol`]
    /// or like the EH personality the module selects, or any other data
    /// definition named like a listed runtime ROUTINE, like either EH
    /// personality or like either personality's `DW.ref` slot
    /// ([`trust_cg_lower::is_eh_personality_slot_name`]). A runtime call would
    /// branch into that data, the unwinder would call it as the personality,
    /// and every unwind table's slot of that name would resolve to it, so the
    /// module is refused before lowering, on every target and in the JIT,
    /// whether or not this module makes that reference.
    #[error(
        "data `{global}` on target {target} is named like a symbol the backend references by \
         that name (a runtime routine, an EH personality or its `DW.ref` slot); such a \
         reference would bind to the data (fail-closed)"
    )]
    DataShadowsBackendSymbol {
        /// Compile target.
        target: String,
        /// The global.
        global: String,
    },

    /// An AArch64 ELF or Mach-O object resolves a reference that must reach
    /// code to a defined location outside every executable section
    /// ([`check_elf_code_references_reach_code`],
    /// [`check_aarch64_macho_code_references_reach_code`]): a branch
    /// (`CALL26`/`JUMP26`, `ARM64_RELOC_BRANCH26`), or a personality
    /// reference (the word in a `DW.ref.*` slot; a Mach-O `__eh_frame` or
    /// `__compact_unwind` personality). The emitters resolve references by
    /// name, so this is a runtime call or a personality bound to same-named
    /// data; the object is refused after emission.
    #[error(
        "AArch64 object for target {target} resolves a reference that must reach code to \
         data: {detail} (fail-closed)"
    )]
    AotCodeReferenceReachesData {
        /// Object target.
        target: String,
        /// What the independent object reader found.
        detail: String,
    },

    /// An AArch64 ELF or Mach-O object `Compiler::compile` produced (or took
    /// from the artifact cache) reaches a bodied Internal/Private function
    /// other than through that function's own local definition (ELF
    /// `STB_LOCAL`; Mach-O `N_SECT` with `N_EXT` and `N_PEXT` clear, rules in
    /// [`check_aarch64_macho_module_local_function_binding`]), as the
    /// independent object reader sees it. On ELF
    /// ([`check_elf_module_local_function_binding`]): a symbol
    /// spelling the function's name (a versioned `name@...` spelling
    /// included) that is not a defined `STB_LOCAL` `STT_FUNC` in an
    /// executable section; a non-local symbol whose range overlaps the local
    /// definition (an exported alias); a relocation reaching the definition
    /// through a non-local symbol; a data slot holding the function's address
    /// that is labelled by a non-local symbol the module did not declare
    /// (a compiler-synthesized slot another object could replace, such as a
    /// weak `DW.ref.<personality>` cell); or a text relocation the module's
    /// bodies do not make (a backend reference by the same name). Such
    /// references would let the linker or loader substitute another object's
    /// definition or run the module's body where the backend meant a runtime
    /// routine, so the object is refused after emission instead of shipped.
    /// This is the check behind the AArch64 ELF and Mach-O and the x86-64 ELF
    /// exemption from the two refusals above. It reads symbol names,
    /// addresses and bindings; a reference made through a section symbol is
    /// identified by address. An x86-64 (ELF, Mach-O, COFF) or RISC-V object
    /// whose module-local definition is not one local function symbol is
    /// refused with it too ([`check_object_function_bindings`]).
    #[error(
        "object for target {target} does not bind module-local function `{function}` \
         locally: {detail} (fail-closed)"
    )]
    AotModuleLocalFunctionBindingViolated {
        /// Object target.
        target: String,
        /// The Internal/Private function whose symbol or reference is not local.
        function: String,
        /// What the independent object reader found.
        detail: String,
    },

    /// An AArch64 ELF or Mach-O object `Compiler::compile` produced (or took
    /// from the artifact cache) breaks the object's symbol discipline, as the
    /// independent object reader sees it
    /// ([`check_aarch64_object_symbol_discipline`]): an emitted function
    /// without exactly one definition symbol in an instruction section, or
    /// whose symbol's binding is not the one its trust-ir linkage and
    /// visibility dictate (Mach-O `N_EXT`, `N_PEXT` and `N_WEAK_DEF`; ELF
    /// `STB_*`, `STV_*` and `STT_FUNC`); a symbol in an instruction section
    /// that is not one of those definitions (a label, a mapping symbol, data,
    /// an alias); two symbols at one address; text before a section's first
    /// symbol; an ELF `st_size` running past the next symbol, or non-padding
    /// bytes after it; or, for a fresh object, a function symbol away from
    /// the start the emitter reports, or non-padding bytes outside every
    /// encoded body. A consumer that partitions the text by symbols (the
    /// extent of a function is `[its symbol, the next symbol or the section
    /// end)`) would otherwise attribute bytes to the wrong function, or to
    /// none, so the object is refused after emission instead of shipped.
    /// An x86-64 (ELF, Mach-O, COFF) or RISC-V object is refused with it when
    /// an emitted function's definition symbol does not carry the binding its
    /// trust-ir linkage asks for ([`check_object_function_bindings`]).
    #[error("object for target {target} breaks symbol discipline: {detail} (fail-closed)")]
    AotObjectSymbolDisciplineViolated {
        /// Object target.
        target: String,
        /// What the independent object reader found.
        detail: String,
    },

    /// The configured relocation model has no implemented access-model
    /// contract on this compile route. Only AArch64 ELF object emission
    /// implements `pie`/`pic`; Mach-O, COFF, other ELF architectures and the
    /// in-process JIT accept only the default `static` model instead of
    /// silently compiling code for a different link contract.
    #[error(
        "relocation model `{model}` is not supported for target {target}: {reason} (fail-closed)"
    )]
    RelocationModelUnsupported {
        /// Target triple or route that refused the model.
        target: String,
        /// The configured relocation model.
        model: RelocationModel,
        /// Why this route cannot honor it.
        reason: &'static str,
    },

    /// An explicit AArch64 optional-ISA profile
    /// ([`CompilerConfig::aarch64_isa_profile`]) was configured on a route
    /// that cannot honor it: a non-AArch64 target, or in-process JIT code,
    /// whose admission is exactly the host CPU's detected features.
    #[error(
        "explicit AArch64 ISA profile `{profile}` is not supported for {target}: {reason} \
         (fail-closed)"
    )]
    Aarch64IsaProfileUnsupported {
        /// Target triple or route that refused the profile.
        target: String,
        /// The configured profile.
        profile: AArch64IsaProfile,
        /// Why this route cannot honor it.
        reason: &'static str,
    },

    /// An AArch64 object frame-pointer policy was requested on a route
    /// that cannot honor it. It must never be silently discarded.
    #[error("forced AArch64 frame pointers are not supported for {target}: {reason}")]
    Aarch64FramePointersUnsupported {
        target: String,
        reason: &'static str,
    },

    /// [`CompilerConfig::eh_frames_cannot_unwind`] was configured on a route
    /// with no modeled non-unwinding exception frame: a non-AArch64 target,
    /// or in-process JIT code.
    #[error(
        "non-unwinding exception frames are not supported for {target}: {reason} (fail-closed)"
    )]
    EhFramesCannotUnwindUnsupported {
        /// Target triple or route that refused the control.
        target: String,
        /// Why this route cannot honor it.
        reason: &'static str,
    },

    /// Pre-adapter trust_ir dialect lowering failed (unknown dialect op, pass
    /// error, or fixpoint not reached). See `dialect_pipeline` module.
    /// Tracked under #433 / trust_ir #428.
    #[error("dialect pipeline error: {0}")]
    DialectPipeline(#[from] DialectPipelineError),

    /// Pipeline compilation failed (ISel, regalloc, encoding, etc.).
    #[error("pipeline error: {0}")]
    Pipeline(#[from] PipelineError),

    /// A certified opt pass run failed before the compiler could synthesize a
    /// checked production pass chain.
    #[error("certified pass execution failed for {pass_name} in {function_name}: {detail}")]
    CertifiedPassExecutionFailed {
        /// Certified pass identity.
        pass_name: String,
        /// Function whose pass run failed.
        function_name: String,
        /// Fail-closed detail.
        detail: String,
    },

    /// Certified pass-chain validation failed while attaching production pass
    /// certificates.
    #[cfg(feature = "verify")]
    #[error("certified pass chain validation failed: {0}")]
    CertifiedPassChain(#[from] trust_cg_verify::CertifiedPassChainError),

    /// The carrier-hygiene invariant (`trust_cg_verify::carrier_hygiene`) was
    /// violated on an emitted x86-64 ISel function: a wide-reading consumer
    /// (`SAR`/`IDIV` / `SHR`/`DIV`) read its source across the full 32/64-bit
    /// carrier without a proven (width-aware) sign/zero extension. This is the
    /// MISCOMPILE #51 / #66 hazard (a 32-bit `NOT`/`NEG`/`SUB` of a narrow
    /// i8/i16 value leaves dirty high carrier bits). The pure-lattice checker
    /// runs UNCONDITIONALLY (not behind the `verify` feature) over every
    /// optimized x86 function, so a regression in the ISel extension guards
    /// fails the compile closed instead of silently shipping wrong code.
    #[error(
        "carrier-hygiene violation in {function_name}: {opcode:?} (block {block}, \
         inst {inst_index}) reads vreg {operand:?} across the full carrier without \
         a proven {required:?} extension (proven state: {actual:?}). {detail}"
    )]
    CarrierHygiene {
        /// Function whose emitted ISel stream violated the invariant.
        function_name: String,
        /// Block id (`X86ISelBlock` key) of the violating instruction.
        block: u32,
        /// Index of the violating instruction within its block.
        inst_index: usize,
        /// The wide-reading consumer opcode (`Idiv`/`Div`/`SarRI`/`ShrRR`/...).
        opcode: trust_cg_ir::x86_64_ops::X86Opcode,
        /// Source operand vreg whose carrier hygiene could not be proven.
        operand: trust_cg_ir::regs::VReg,
        /// Extension the consumer's semantics require (`Sign`/`Zero`).
        required: trust_cg_verify::carrier_hygiene::RequiredExtension,
        /// Proven lattice state of `operand` at the consumer.
        actual: trust_cg_verify::carrier_hygiene::HighBits,
        /// Human-readable explanation referencing the historical miscompile class.
        detail: String,
    },

    /// A per-pass translation validator
    /// (`trust_cg_verify::pass_validators`) rejected a glue-pass expansion the
    /// x86-64 pipeline relies on. Today this guards the overflow / checked-arith
    /// expansion (MISCOMPILE #67): the live division-free wide-multiply
    /// expansion is re-proven equivalent for the x86-64 trap semantics, and a
    /// regression to the AArch64-only `SDIV`-identity expansion (which SIGFPEs
    /// on x86 `IDIV`-by-zero) is rejected. Runs UNCONDITIONALLY (not behind the
    /// `verify` feature).
    #[error(
        "per-pass validation rejected for x86-64 pass `{pass_name}` (obligation \
         `{obligation_name}`): {reason}"
    )]
    PassValidationRejected {
        /// Pass whose expansion failed translation validation.
        pass_name: String,
        /// Name of the rejected proof obligation.
        obligation_name: String,
        /// Fail-closed rejection detail (counterexample / reason).
        reason: String,
    },

    /// Compile artifact cache I/O or validation failed.
    #[error("compile artifact cache error: {0}")]
    CompileArtifactCache(#[from] std::io::Error),

    /// Profile-use input could not be encoded into the compile artifact key.
    #[error("profile-use input cannot be encoded for compile artifact cache identity: {0}")]
    ProfileUseCacheIdentity(#[from] trust_cg_opt::pgo::ProfDataError),

    /// Compile artifact cache identity JSON could not be serialized.
    #[error("compile artifact cache identity JSON serialization failed for {component}: {source}")]
    CompileArtifactCacheIdentityJson {
        /// Identity component being serialized.
        component: &'static str,
        /// Underlying JSON serialization error.
        #[source]
        source: serde_json::Error,
    },

    /// Module contains no functions.
    #[error("empty module: no functions to compile")]
    EmptyModule,

    /// A per-target dispatcher (`compile_x86_64`, `compile_riscv`) was handed
    /// no LIR function. A driver refusal like [`Self::EmptyModule`], but raised
    /// inside the dispatcher, so it keeps the dispatcher's own message.
    #[error("{dispatcher} dispatcher received an empty module")]
    DispatcherEmptyModule {
        /// The dispatcher that refused (`x86_64` or `RISC-V`).
        dispatcher: &'static str,
    },

    /// AOT PGO profile-generate was requested for a target whose preparation
    /// pipeline does not insert the instrumentation. Refused before codegen
    /// rather than returning an object that silently carries no counters.
    #[error("PGO profile-generate is only supported for the AArch64 AOT pipeline, not {target:?}")]
    ProfileGenerateTargetUnsupported {
        /// Target the request selected.
        target: Target,
    },

    /// The proof-certificate lane needs the whole-module LIR, but the
    /// memory-streaming lane had released part of it. Without it the
    /// per-function certificate zip would silently cover no function, so the
    /// certificate bundle is refused instead.
    #[error(
        "[MEM-STREAM] the proof-certificate lane requires the whole-module LIR, but only \
         {retained} of {required} LIR functions were retained; refusing to emit a certificate \
         bundle that would silently cover no function"
    )]
    ProofLaneLirIncomplete {
        /// LIR functions still retained.
        retained: usize,
        /// Functions the certificate lane must cover.
        required: usize,
    },

    /// The shared trust-ir-level inliner (OPT-4) structural self-check detected
    /// that the inlined result dropped or duplicated an instruction relative to
    /// `caller ⊎ renamed-callee`. Fail the compile CLOSED rather than emit a
    /// substitution that fails its own structural check. Passing that check is
    /// not a semantic validation (a wrong argument binding passes it), which
    /// is why a compile that claims proofs runs no inliner (ruling OD-225).
    #[error("trust-ir inliner self-check failed: {detail}")]
    IrInline {
        /// Fail-closed detail (which opcode multiset diverged, in which fn).
        detail: String,
    },

    /// JIT compilation failed while producing executable memory.
    #[error("JIT compilation failed: {0}")]
    Jit(#[from] crate::jit::JitError),

    /// No per-function machine-code evidence was available from which to
    /// derive the selected host-JIT codegen profile.
    #[error("x86 host-JIT selected-codegen profile has no per-function machine-code evidence")]
    HostJitSelectedCodegenFeaturesMissing,

    /// A function's actual machine-code target features differed from the
    /// target features captured from the pipeline that compiled it.
    #[error(
        "x86 host-JIT function `{function_name}` selected codegen features `{actual}` but the captured pipeline selected `{expected}`"
    )]
    HostJitSelectedCodegenFeaturesPipelineMismatch {
        /// Function carrying the mismatched evidence.
        function_name: String,
        /// Captured pipeline target features.
        expected: String,
        /// Function's actual machine-code target features.
        actual: String,
    },

    /// Functions in one executable buffer reported different actual
    /// machine-code target-feature sets.
    #[error(
        "x86 host-JIT selected-codegen features are nonuniform: `{reference_function}` selected `{reference_features}`, but `{function_name}` selected `{actual_features}`"
    )]
    HostJitSelectedCodegenFeaturesNonUniform {
        /// First function establishing the selected profile.
        reference_function: String,
        /// First function's selected features.
        reference_features: String,
        /// Later function carrying different evidence.
        function_name: String,
        /// Later function's selected features.
        actual_features: String,
    },

    /// The uniform actual selection could not form a self-consistent profile.
    #[error("x86 host-JIT selected-codegen profile error: {0}")]
    HostJitSelectedCodegenProfile(#[from] HostJitSelectedCodegenProfileError),

    /// AArch64 preparation completed without the final machine-code evidence
    /// needed to bind executable bytes to the target-machine contract.
    #[error(
        "AArch64 JIT function `{function_name}` has no final machine-code target-feature evidence"
    )]
    Aarch64MachineCodeEvidenceMissing {
        /// Function whose preparation omitted evidence, or `<module>` when no
        /// per-function evidence was supplied at all.
        function_name: String,
    },

    /// Per-function AArch64 evidence was produced under a target machine other
    /// than the one compiling the containing executable buffer.
    #[error(
        "AArch64 JIT function `{function_name}` carries machine-code evidence for target `{actual_target}` with admission `{actual_admitted}`, but its pipeline captured target `{expected_target}` with admission `{expected_admitted}`"
    )]
    Aarch64MachineCodeEvidencePipelineMismatch {
        /// Function carrying the mismatched evidence.
        function_name: String,
        /// Immutable target identity captured by the module pipeline.
        expected_target: TargetSpec,
        /// Immutable target identity captured by the function evidence.
        actual_target: TargetSpec,
        /// Feature admission captured by the module pipeline.
        expected_admitted: AArch64IsaProfile,
        /// Feature admission captured by the function evidence.
        actual_admitted: AArch64IsaProfile,
    },

    /// The validated per-function AArch64 requirements could not form one
    /// aggregate evidence record for the executable buffer.
    #[error("AArch64 JIT module machine-code evidence is invalid: {detail}")]
    Aarch64MachineCodeEvidenceInvalid {
        /// Target-machine validation failure.
        detail: String,
    },

    /// Caller attempted to JIT-compile code for an ISA that does not match
    /// the current host process.
    #[error(
        "host JIT target mismatch: config target {target:?} does not match \
         host {host:?}; use CompilerConfig::for_host_jit() or \
         Compiler::for_host() for in-process JIT"
    )]
    JitTargetMismatch {
        /// Target selected by the caller's compiler configuration.
        target: Target,
        /// Target architecture of the current host process.
        host: Target,
    },

    /// Caller selected the host ISA, but requested a different OS/ABI target
    /// spec than the current process can execute in-process.
    #[error(
        "host JIT target spec mismatch: requested {requested} but host JIT ABI \
         is {host}; cross-OS/ABI JIT execution is not supported"
    )]
    JitTargetSpecMismatch {
        /// OS/ABI target spec requested by the caller.
        requested: TargetSpec,
        /// OS/ABI target spec for the current host process.
        host: TargetSpec,
    },

    /// Caller selected the host target, but the high-level Compiler JIT path
    /// does not yet have a backend wired for that target.
    #[error(
        "Compiler::compile_module_to_jit does not yet support host target \
         {target:?}; refusing to emit a different ISA for in-process execution"
    )]
    JitTargetUnsupported {
        /// Host target that is not yet supported by `compile_module_to_jit`.
        target: Target,
    },

    /// `compile_ir_function` currently accepts the AArch64-flavoured canonical
    /// MachFunction only; feeding it to another target pipeline would emit the
    /// wrong ISA (or a mislabeled object) rather than dispatching per target.
    #[error(
        "Compiler::compile_ir_function accepts prebuilt AArch64 MachIR only; configured target {target:?} is unsupported"
    )]
    PrebuiltIrTargetUnsupported { target: Target },

    /// Caller requested proof certificates (`config.emit_proofs == true`) for
    /// a target or build configuration that does not yet produce
    /// per-instruction proof certificates through a target-specific function
    /// verifier.
    ///
    /// Returned instead of silently producing `proofs: None` so embedders that
    /// opt into a verified-codegen attestation workflow learn the truth at the
    /// public API boundary rather than trusting a silent lie. Today this fires
    /// for `Target::Riscv64` unconditionally, and for AArch64 / x86-64 proof
    /// requests when the `verify` feature is disabled. With `verify` on, the
    /// x86-64 path produces real certs via
    /// `trust_cg_verify::x86_64_function_verifier` — see #465. The AArch64 path
    /// likewise requires the `verify` feature.
    ///
    /// Tracking: #465 (x86-64 proofs; landed for default `verify` builds),
    /// RISC-V proofs (TBD).
    #[error(
        "proof certificates are not yet supported for target {target:?} in \
         this build; set config.emit_proofs = false, or enable the `verify` \
         feature for AArch64/x86-64 proof generation. Tracking: #465 \
         (x86-64 proofs), RISC-V proofs (TBD)."
    )]
    ProofsUnsupportedForTarget {
        /// The target that requested proofs but cannot produce them.
        target: Target,
    },

    /// A proof-required object compile would promote exception-handling
    /// tables. The LSDA, the personality reference and the unwind tables that
    /// register them carry structural checks and native execution tests but
    /// no proof obligation (trusted base TB-12), so no certified route
    /// promotes an object containing them ([`ExceptionTableCensus`]).
    ///
    /// On AArch64 Darwin every emitted object and JIT image with exception
    /// tables must also pass the exception-table obligations of ledger
    /// L03-P14 (`trust_cg_verify::eh_obligations`: call-site coverage,
    /// landing pads, action tables, personality, LSDA binding and the unwind
    /// description at every call). Those are exact decisions made in
    /// process, which is testing-grade evidence and never promotion credit
    /// under the evidence policy (decision record OD-139: an in-process
    /// decision is never credit), and no Clean-checked certificate of them
    /// exists, so this refusal stands for those objects too.
    #[error(
        "[TCG-EH-UNPROVED] proof promotion rejected for target {target:?}: exception tables carry no proof obligation; {}, which is trusted base TB-12 (structural checks, native tests and, for AArch64 Darwin objects and JIT images, the exception-table obligations of L03-P14 decided in process: testing grade, never promotion credit), so a proof-required object that contains them is not promoted",
        exception_table_subject(.function, .walk_through)
    )]
    ExceptionTablesUnproved {
        /// Target whose compiled artifact was being promoted.
        target: Target,
        /// The first function whose object form carries exception tables.
        function: String,
        /// The tables are whole-program `panic=unwind` walk-through tables (a
        /// filler LSDA and a personality reference) that an x86-64 emitter adds
        /// to a function with no exception-handling structure of its own.
        walk_through: bool,
    },

    /// A caller requested proof-backed install/promotion, but the public proof
    /// status surface did not prove every emitted entry.
    #[error("proof promotion rejected for target {target:?}: {reason}")]
    ProofPromotionRejected {
        /// Target whose compiled artifact was being promoted.
        target: Target,
        /// Fail-closed rejection detail.
        reason: String,
    },

    /// L09-P3: a route that publishes proof-grade code met a function a
    /// TrustIR-bound legalization check covers whose composed transition
    /// record does not compose (a missing, unestablished or mismatched
    /// link) or does not end at the bytes the route publishes
    /// ([`crate::composed_transition`]).
    #[error("composed transition refused for target {target:?}: {refusal}")]
    ComposedTransitionRefused {
        /// Target whose compiled artifact was being published.
        target: Target,
        /// The named refusal.
        refusal: Box<trust_cg_verify::composed_transition::CompositionRefusal>,
    },

    /// The resolved JIT validation mode is [`JitValidationMode::Unchecked`] on
    /// an arch whose default is a verifying mode, but no explicit opt-in was
    /// given. Executing uncertified JIT bytes on such a default path requires
    /// `TCG_JIT_UNCHECKED=1` (or an explicit `jit_validation_mode_override`).
    #[error(
        "JIT compile for target {target:?} would execute UNCERTIFIED bytes: the \
         default validation mode is verifying, so reaching Unchecked requires the \
         explicit opt-in TCG_JIT_UNCHECKED=1 (or CompilerConfig::for_host_jit_unchecked / \
         jit_validation_mode_override = Some(Unchecked))"
    )]
    JitUncertifiedBytesRequireOptIn {
        /// Target whose JIT compile was fail-closed.
        target: Target,
    },

    /// Caller requested public x86-64 AOT object emission for an OS whose
    /// native object format is not implemented yet, or named an explicit
    /// triple whose unknown OS selects no object format.
    #[error(
        "x86-64 AOT object format is unsupported for target OS {target_os}: \
         {required_format} emission is not implemented; {context}"
    )]
    X86AotObjectFormatUnsupported {
        /// The OS the target names (`unknown` for an explicit
        /// `x86_64-unknown-unknown`), or the host OS (`std::env::consts::OS`)
        /// for an architecture-only request.
        target_os: &'static str,
        /// Native object format needed for this OS.
        required_format: &'static str,
        /// Human-readable fail-closed detail.
        context: &'static str,
    },
}

impl CompileError {
    /// The ingestion-admission error mapping (WS7.3): a validator refusal
    /// with no named adapter arm is [`CompileError::InvalidTrustIr`]; a named
    /// one keeps its adapter refusal.
    pub fn from_admission(error: trust_cg_lower::AdapterError) -> Self {
        match error {
            trust_cg_lower::AdapterError::InvalidTrustIrModule(refusal) => {
                CompileError::InvalidTrustIr(refusal)
            }
            other => CompileError::Adapter(other),
        }
    }
}

/// VOL-1. The optimizer must not change a function's VOLATILE ACCESS TRACE.
///
/// Called with the trace taken BEFORE the x86 optimization passes and the
/// function AFTER them. A volatile access is observable — the program asked for
/// exactly these accesses, at these widths, in these directions — so a pass
/// that elides, duplicates, widens, narrows, redirects or reorders one has
/// produced wrong code.
///
/// This is the ONLY place that can catch it. A volatile MOV encodes
/// byte-identically to its plain sibling, so `decode_check` sees nothing wrong
/// with the bytes of a function whose volatile load was deleted; the defect is
/// in what is ABSENT, and only a before/after comparison can see an absence.
///
/// ORDER IS COMPARED ONLY WHEN THE BLOCK STRUCTURE SURVIVED, and that is a
/// statement about what is provable rather than a weakening chosen for
/// convenience. Block merging legitimately changes the block count, and when it
/// has, the per-block correspondence this obligation compares positions within
/// no longer exists. The MULTISET is compared unconditionally and is invariant
/// under any CFG change, so elision, duplication, widening, narrowing,
/// redirection and reclassification are caught either way; only intra-block
/// REORDERING goes unchecked on a compile whose blocks were merged, and
/// `x86_block_merge` is a pure concatenation that reorders nothing.
fn check_volatile_trace_preserved(
    function: &str,
    before: &trust_cg_verify::x86_volatile_trace::VolatileTrace,
    after_func: &trust_cg_lower::x86_64_isel::X86ISelFunction,
) -> Result<(), CompileError> {
    use trust_cg_verify::x86_volatile_trace as vt;

    // Costs nothing on the overwhelming majority of functions: a function with
    // no volatile access has an empty trace and there is nothing to compare.
    if before.is_empty() {
        let after = vt::machine_volatile_trace(after_func);
        if after.is_empty() {
            return Ok(());
        }
        return Err(CompileError::VolatileTraceChanged {
            function: function.to_string(),
            violation: format!(
                "the optimizer INTRODUCED {} volatile access(es) into a function that had none",
                after.len()
            ),
        });
    }

    let after = vt::machine_volatile_trace(after_func);
    let compare_order = before.per_block.len() == after.per_block.len();
    vt::volatile_trace_holds(before, &after, compare_order).map_err(|violation| {
        CompileError::VolatileTraceChanged {
            function: function.to_string(),
            violation: violation.to_string(),
        }
    })?;
    Ok(())
}

/// Fail-closed errors from the consuming identity-Core JIT planning route.
///
/// This is separate from [`CompileError`] because it also protects the owner
/// handoff and the sealed effective-policy boundary before machine codegen.
#[derive(Debug, Error)]
pub enum CoreJitPlanningError {
    #[error(transparent)]
    RetainedIdentity(#[from] trust_cg_lower::RetainedIdentityError),
    #[error(transparent)]
    CoreIntegrity(#[from] CoreConsumptionIntegrityError),
    #[error(transparent)]
    NativeRuntimeCatalog(#[from] CoreNativeRuntimeCatalogError),
    #[error(transparent)]
    NativeDependencyReferences(#[from] CoreNativeDependencyReferenceMapError),
    #[error(transparent)]
    LirNativeDependencyBindings(#[from] CoreLirNativeDependencyBindingError),
    #[error(
        "Core target {admitted} differs from compiler target {compiler}; the admitted target must be reused exactly"
    )]
    TargetMismatch {
        admitted: TargetSpec,
        compiler: TargetSpec,
    },
    #[error(
        "Core machine profile architecture {profile:?} differs from compiler target {compiler:?}"
    )]
    MachineProfileArchitectureMismatch { profile: Target, compiler: Target },
    #[error(
        "the compiler previously captured JIT validation policy {captured:?}, but the sealed explicit configuration resolves to {configured:?}"
    )]
    CapturedValidationPolicyMismatch {
        captured: JitValidationMode,
        configured: JitValidationMode,
    },
    #[error("Core JIT planning refuses unkeyed ambient compiler controls: {controls:?}")]
    UnkeyedAmbientCompilerControls { controls: Vec<OsString> },
    #[error("Core JIT planning could not acquire a stable compiler-environment permit")]
    CompilerEnvironmentPermitUnavailable,
    #[error("Core JIT planning observed compiler-control drift before returning its plan")]
    CompilerEnvironmentChanged,
    #[error(
        "Core JIT planning does not yet bind compiler attachment {attachment}; construct a fresh compiler without it"
    )]
    UnsupportedCompilerAttachment { attachment: &'static str },
    #[error(
        "Core JIT planning accepts only the static relocation model; in-process JIT code is never linked (configured `{model}`)"
    )]
    RelocationModelUnsupported { model: RelocationModel },
    #[error(
        "Core JIT planning admits exactly the host CPU's AArch64 features; an explicit object ISA profile (`{profile}`) cannot apply"
    )]
    Aarch64IsaProfileUnsupported { profile: AArch64IsaProfile },
    #[error(transparent)]
    CompilePolicy(#[from] CompilePolicyError),
    #[error(transparent)]
    Compile(#[from] CompileError),
    /// This compiler's trust-ir v41 codegen-license policy
    /// ([`Compiler::with_codegen_license`]) refused a body of the admitted
    /// module. Admission lowered under the license FLOOR (`Ungated`,
    /// unrecognized authorities, and `Gated` bodies without their evidence or
    /// refuted in-module refused; claim-less bodies DEFERRED under the named
    /// `CoreAdmissionFloor` exception); the compiler re-decides the whole
    /// license on the admitted module here, before any plan is built —
    /// refusing claim-less bodies unless its own policy permits them — so its
    /// policy is never bypassed by an admission that pre-dates it.
    #[error(transparent)]
    CodegenLicense(trust_cg_lower::AdapterError),
}

/// Recoverable failed attempt to build a consuming Core JIT plan.
///
/// Every planning failure returns the original admitted owner intact. Callers
/// may inspect the reason, retry with a corrected compiler, or recover both
/// values with [`Self::into_parts`].
pub struct CoreJitPlanningFailure {
    error: CoreJitPlanningError,
    core: CoreAdmittedModule,
}

impl std::fmt::Debug for CoreJitPlanningFailure {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("CoreJitPlanningFailure")
            .field("error", &self.error)
            .field("module_name", &self.core.module_name())
            .field("module_digest", &self.core.module_digest())
            .finish_non_exhaustive()
    }
}

impl std::fmt::Display for CoreJitPlanningFailure {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        std::fmt::Display::fmt(&self.error, f)
    }
}

impl std::error::Error for CoreJitPlanningFailure {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        Some(&self.error)
    }
}

impl CoreJitPlanningFailure {
    #[must_use]
    pub const fn reason(&self) -> &CoreJitPlanningError {
        &self.error
    }

    #[must_use]
    pub const fn core(&self) -> &CoreAdmittedModule {
        &self.core
    }

    #[must_use]
    pub fn into_parts(self) -> (CoreJitPlanningError, CoreAdmittedModule) {
        (self.error, self.core)
    }
}

/// Fail-closed reason why a sealed Core JIT plan is not eligible for a later
/// proof-grade machine-compilation transition.
///
/// Qualification is deliberately narrower than successful compilation. It
/// checks that every currently exposed compiler and JIT policy field has the
/// production-safe closed value, that the target/profile and canonical
/// identities remain intact, and then changes only the Rust ownership type.
/// It does not run a compiler, discharge a proof, resolve a fixup, allocate
/// executable memory, or authorize installation.
#[derive(Debug, Error)]
pub enum CoreJitProofGradeQualificationError {
    #[error(transparent)]
    RetainedPlanIntegrity(#[from] CoreJitPlanIntegrityError),
    #[error("effective Core JIT target {effective} differs from admitted target {admitted}")]
    EffectiveTargetMismatch {
        effective: TargetSpec,
        admitted: TargetSpec,
    },
    #[error(
        "effective Core JIT machine profile {effective:?} differs from admitted profile {admitted:?}"
    )]
    EffectiveMachineProfileMismatch {
        effective: CoreHostJitMachineProfile,
        admitted: CoreHostJitMachineProfile,
    },
    #[error(
        "effective machine profile architecture {profile:?} differs from target architecture {target:?}"
    )]
    MachineProfileArchitectureMismatch { profile: Target, target: Target },
    #[error(
        "compiler target architecture {compiler:?} differs from exact target architecture {target:?}"
    )]
    CompilerTargetMismatch { compiler: Target, target: Target },
    #[error("proof-grade Core JIT qualification requires AlwaysVerify, found {actual:?}")]
    ValidationMode { actual: JitValidationMode },
    #[error(
        "proof-grade Core JIT qualification requires an explicit Some(AlwaysVerify) override, found {actual:?}"
    )]
    ValidationOverride { actual: Option<JitValidationMode> },
    #[error("proof-grade Core JIT qualification requires compiler proof emission")]
    ProofEmissionDisabled,
    #[error("proof-grade Core JIT qualification requires trace=None, found {actual:?}")]
    TraceEnabled { actual: CompilerTraceLevel },
    #[error("proof-grade Core JIT qualification requires debug emission to be disabled")]
    DebugEmissionEnabled,
    #[error("proof-grade Core JIT qualification requires serial compilation")]
    ParallelCompilationEnabled,
    #[error(
        "proof-grade Core JIT qualification requires CEGIS to be disabled, found budget {budget_sec}s"
    )]
    CegisEnabled { budget_sec: u64 },
    #[error("proof-grade Core JIT qualification requires fsym preflight to be disabled")]
    FsymPreflightEnabled,
    #[error("proof-grade Core JIT qualification requires panic-unwind mode to be disabled")]
    PanicUnwindEnabled,
    #[error(
        "proof-grade Core JIT qualification requires the static relocation model, found {actual}"
    )]
    RelocationModel { actual: RelocationModel },
    #[error(
        "proof-grade Core JIT qualification requires the function-sections object policy to be disabled"
    )]
    FunctionSectionsEnabled,
    #[error(
        "proof-grade Core JIT qualification requires the non-unwinding exception-frame policy to be disabled"
    )]
    EhFramesCannotUnwindEnabled,
    #[error(
        "proof-grade Core JIT qualification requires the host-derived AArch64 ISA profile, found explicit `{actual}`"
    )]
    ExplicitAarch64IsaProfile { actual: AArch64IsaProfile },
    #[error("proof-grade Core JIT qualification has no forced-frame-pointer policy")]
    ForcedAarch64FramePointers,
    #[error(
        "proof-grade Core JIT qualification requires an empty never-inline set, found {count} name(s)"
    )]
    NeverInlineSet { count: usize },
    #[error(
        "proof-grade Core JIT qualification requires an empty link-unit definition set, found {count} name(s)"
    )]
    LinkUnitDefinitionsSet { count: usize },
    #[error("proof-grade Core JIT qualification has no x86-64 certificate-free allocation policy")]
    X86CertificateFreeAllocation,
    #[error("compiler external-symbol policy must be ExplicitOnly, found {actual:?}")]
    CompilerExternalSymbolResolution {
        actual: JitExternalSymbolResolutionPolicy,
    },
    #[error("JIT optimization {jit:?} differs from the sealed compiler optimization {compiler:?}")]
    JitOptimizationMismatch { compiler: OptLevel, jit: OptLevel },
    #[error("proof-grade Core JIT qualification requires JIT verification")]
    JitVerificationDisabled,
    #[error(
        "proof-grade Core JIT qualification requires ErrorOnFailure dispatch verification, found {actual:?}"
    )]
    JitDispatchVerification {
        actual: crate::pipeline::DispatchVerifyMode,
    },
    #[error(
        "proof-grade Core JIT qualification requires profile hooks to be disabled, found {actual:?}"
    )]
    JitProfileHooks { actual: crate::jit::ProfileHookMode },
    #[error("proof-grade Core JIT qualification requires entry counters to be disabled")]
    JitEntryCountersEnabled,
    #[error("proof-grade Core JIT qualification requires the certificate cache to be disabled")]
    JitCertificateCacheEnabled,
    #[error("JIT external-symbol policy must be ExplicitOnly, found {actual:?}")]
    JitExternalSymbolResolution {
        actual: JitExternalSymbolResolutionPolicy,
    },
    #[error(transparent)]
    CompilePolicy(#[from] CompilePolicyError),
    #[error("the retained canonical compile policy no longer matches its exact options")]
    CompilePolicyIdentityMismatch,
    #[error("the retained Core JIT plan identity no longer matches its exact inputs")]
    PlanIdentityMismatch,
}

/// Recoverable failed proof-grade qualification of a Core JIT plan.
///
/// The exact input plan is retained without cloning or peeling its TrustIR or
/// strict LIR. A caller may correct the policy at an earlier ownership stage or
/// recover both values with [`Self::into_parts`].
pub struct CoreJitProofGradeQualificationFailure {
    error: CoreJitProofGradeQualificationError,
    plan: CoreJitCompilationPlan,
}

impl std::fmt::Debug for CoreJitProofGradeQualificationFailure {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("CoreJitProofGradeQualificationFailure")
            .field("error", &self.error)
            .field("module_name", &self.plan.module_name())
            .field("module_digest", &self.plan.module_digest())
            .field("plan_identity", &self.plan.identity())
            .finish_non_exhaustive()
    }
}

impl std::fmt::Display for CoreJitProofGradeQualificationFailure {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        std::fmt::Display::fmt(&self.error, f)
    }
}

impl std::error::Error for CoreJitProofGradeQualificationFailure {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        Some(&self.error)
    }
}

impl CoreJitProofGradeQualificationFailure {
    #[must_use]
    pub const fn reason(&self) -> &CoreJitProofGradeQualificationError {
        &self.error
    }

    #[must_use]
    pub const fn plan(&self) -> &CoreJitCompilationPlan {
        &self.plan
    }

    #[must_use]
    pub fn into_parts(self) -> (CoreJitProofGradeQualificationError, CoreJitCompilationPlan) {
        (self.error, self.plan)
    }
}

/// Fail-closed reason why a policy-qualified Core plan did not become an
/// address-free machine artifact.
///
/// Every error is reported before executable memory is allocated or a runtime
/// address is accepted.  The accompanying
/// [`CoreAddressFreeMachineCompilationFailure`] retains the exact input owner.
#[derive(Debug, Error)]
pub enum CoreAddressFreeMachineCompilationError {
    /// The sealed plan no longer passes the complete proof-grade policy and
    /// retained-input check.
    #[error("qualified Core plan failed fresh integrity reauthentication: {0}")]
    PlanIntegrity(#[from] CoreJitProofGradeQualificationError),
    #[error("address-free Core compilation could not acquire a stable compiler-environment permit")]
    CompilationEnvironmentPermitUnavailable,
    #[error("compiler controls changed while address-free Core compilation was in progress")]
    CompilationEnvironmentChanged,
    #[error("address-free Core machine compilation is not implemented for target {target:?}")]
    TargetUnsupported { target: Target },
    #[error("defined Core function symbol {symbol:?} is ambiguous")]
    DuplicateDefinedFunctionSymbol { symbol: String },
    #[error("retained LIR function {symbol:?} has no exact defined TrustIR identity")]
    MissingDefinedFunctionIdentity { symbol: String },
    #[error(
        "final AArch64 bytes for Core function {function:?} do not match its retained source: {reason}"
    )]
    AffineBytesRejected {
        function: String,
        reason: trust_cg_verify::aarch64_affine_lowering::AffineByteError,
    },
    #[error(
        "source-checked affine Core function {function:?} has {count} pending fixup(s); its checked bytes must remain unchanged"
    )]
    AffineBytesHaveFixups { function: String, count: usize },
    #[error(
        "retained LIR call from {caller:?} to {callee:?} still has unsealed binding {binding:?}"
    )]
    UnsealedLirCall {
        caller: String,
        callee: String,
        binding: trust_cg_lower::instructions::DirectCallBinding,
    },
    #[error("encoded fixup in {caller:?} at byte {offset} has unsupported Core target {target:?}")]
    UnsupportedFixupTarget {
        caller: String,
        offset: u32,
        target: crate::macho::fixup::FixupTarget,
    },
    #[error("encoded fixup in {caller:?} at byte {offset} is outside its {code_len}-byte function")]
    FixupOutOfBounds {
        caller: String,
        offset: u32,
        code_len: usize,
    },
    #[error(
        "encoded fixup in {caller:?} at byte {offset} has unsupported Core relocation details: kind={kind:?}, tls={tls:?}, addend={addend}"
    )]
    UnsupportedFixupEncoding {
        caller: String,
        offset: u32,
        kind: crate::macho::reloc::AArch64RelocKind,
        tls: Option<trust_cg_ir::TlsModel>,
        addend: i64,
    },
    #[error("exact-module machine fixup in {caller:?} names missing definition {target:?}")]
    MissingExactModuleFixupTarget { caller: String, target: String },
    #[error(
        "ordinary named machine fixup in {caller:?} aliases module definition {target:?}; exact binding was lost"
    )]
    InterposableModuleFixup { caller: String, target: String },
    #[error(
        "machine fixup in {caller:?} names {target:?}, which is absent from the sealed native catalog"
    )]
    MissingNativeFixupTarget { caller: String, target: String },
    #[error(
        "encoded fixup in {caller:?} at byte {offset} is not the exact retained LIR call occurrence: {detail}"
    )]
    FixupOccurrenceMismatch {
        caller: String,
        offset: u32,
        detail: String,
    },
    #[error(
        "machine fixup binding coverage differs from retained LIR: expected {expected} edge(s), encoded {actual}; first difference {first_difference}"
    )]
    FixupBindingCoverageMismatch {
        expected: usize,
        actual: usize,
        first_difference: String,
    },
    #[error(
        "machine certificate for {function:?} is not replayable proof-grade evidence: \
         verified={certificate_verified}, replayable={certificate_replayable}, total={total}, \
         genuine={genuinely_verified}, degenerate={degenerate_verified}, \
         unverified={unverified} (sampled={sampled_uncredited}, registry-name={registry_name_lookup}, \
         instruction-derived={instruction_derived}), \
         skipped={skipped}, failed={failed}; {inventory_verdict}{}",
        request_ay_refusal_suffix(.ay_refusal_note.as_deref())
    )]
    MachineCertificateRejected {
        function: String,
        certificate_verified: bool,
        certificate_replayable: bool,
        total: usize,
        genuinely_verified: usize,
        degenerate_verified: usize,
        /// Unverified instructions whose obligation discharged only by sampling.
        sampled_uncredited: usize,
        /// Unverified instructions whose only candidate was a registry theorem
        /// selected by name (withdrawn substring/representative credit).
        registry_name_lookup: usize,
        /// Unverified instructions whose evidence is an uncertified
        /// instruction-derived obligation (L07-P2).
        instruction_derived: usize,
        unverified: usize,
        skipped: usize,
        failed: usize,
        inventory_verdict: String,
        /// The AY refusal note the rejected certificate carried
        /// ([`crate::jit_cert::JitCertificate::ay_refusal_note`]): the
        /// function-verification request its report came from had no AY
        /// bound. A refusal over evidence names the note that evidence
        /// carried, never a fresh resolution (LD-66).
        ay_refusal_note: Option<String>,
    },
    #[error("address-free Core machine identity length overflow")]
    IdentityLengthOverflow,
    #[error("address-free Core machine identity framing failed: {0}")]
    IdentityStream(#[from] trust_ir::proof::ProofDigestStreamError),
    #[error("address-free Core machine code-size accounting overflow")]
    CodeSizeOverflow,
    #[error(transparent)]
    Compile(#[from] CompileError),
}

/// `"; <note>"` for a refusal whose evidence carried a request's AY refusal
/// note, else nothing (the rendering of
/// `trust_cg_verify::ay_bridge::with_request_refusal_note`, which a build
/// without the `verify` feature cannot name).
fn request_ay_refusal_suffix(note: Option<&str>) -> String {
    note.map(|note| format!("; {note}")).unwrap_or_default()
}

/// Recoverable failed address-free compilation.
///
/// Compilation borrows the qualified plan until every fallible machine,
/// proof, fixup-closure, identity, and environment check succeeds.  A caller
/// therefore gets the exact predecessor allocations back on every error.
pub struct CoreAddressFreeMachineCompilationFailure {
    error: CoreAddressFreeMachineCompilationError,
    plan: PolicyQualifiedCoreJitCompilationPlan,
    machine_rejection: Option<CoreMachineProofRejection>,
}

/// Actual rejected machine input retained without reconstructing its operands
/// from an opcode inventory. This is diagnostic custody, never proof, a
/// compiled artifact, or permission to install or execute these bytes.
///
/// The compiler moves its existing machine, layout and encoded allocations here
/// only when proof promotion refuses. The exact LIR/source predecessor remains
/// in [`CoreAddressFreeMachineCompilationFailure::plan`]. No successful compile
/// retains a second machine graph, and no verifier or resource budget is reset.
pub struct CoreMachineProofRejection {
    source_function: trust_ir::FuncId,
    machine: trust_cg_ir::MachFunction,
    frame_layout: Option<crate::frame::FrameLayout>,
    bytes: Vec<u8>,
    fixup_sites: Vec<crate::pipeline::EncodedAarch64FixupSite>,
    prior_functions: Vec<CoreAddressFreeMachineFunction>,
    #[cfg(feature = "verify")]
    captured: trust_cg_verify::CapturedFunctionVerificationReport,
    #[cfg(feature = "verify")]
    request: trust_cg_verify::FunctionVerificationRequest,
}

/// A diagnostic callee reattachment failed. No variant grants caller, frame,
/// storage, final-link or executable authority.
#[cfg(feature = "verify")]
#[derive(Debug, Error)]
pub enum CoreDefinedCalleeReplayError {
    #[error("Core refusal has no earlier replayed callee FuncId({function})")]
    MissingCallee { function: u32 },
    #[error("Core callee FuncId({function}) has no checked scalar summary: {reason}")]
    SummaryRefused { function: u32, reason: String },
    #[error("Core refusal lost the exact retained LIR for FuncId({function})")]
    MissingLir { function: u32 },
    #[error(transparent)]
    SourceModules(#[from] trust_cg_verify::SourceModuleHasNoWireImage),
    #[error(transparent)]
    Attachment(#[from] trust_cg_verify::aarch64_affine_lowering::DefinedAffineCalleeError),
}

impl std::fmt::Debug for CoreMachineProofRejection {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let mut debug = f.debug_struct("CoreMachineProofRejection");
        debug
            .field("source_function", &self.source_function)
            .field("machine", &self.machine)
            .field("frame_layout", &self.frame_layout)
            .field("bytes", &self.bytes)
            .field("fixup_sites", &self.fixup_sites)
            .field("prior_replayed_function_count", &self.prior_functions.len());
        #[cfg(feature = "verify")]
        debug.field("captured", &self.captured);
        debug.finish()
    }
}

impl CoreMachineProofRejection {
    pub const fn source_function(&self) -> trust_ir::FuncId {
        self.source_function
    }
    pub const fn machine(&self) -> &trust_cg_ir::MachFunction {
        &self.machine
    }
    pub fn frame_layout(&self) -> Option<&crate::frame::FrameLayout> {
        self.frame_layout.as_ref()
    }
    pub fn bytes(&self) -> &[u8] {
        &self.bytes
    }
    pub fn fixup_sites(&self) -> impl ExactSizeIterator<Item = (trust_cg_ir::InstId, u32)> + '_ {
        self.fixup_sites.iter().map(|site| (site.inst, site.offset))
    }
    /// Earlier functions that passed the same compilation's ordinary proof
    /// gates. Retained diagnostic endpoints do not authorize the failed caller
    /// or confer an installed entry point. No machine graph is cloned here.
    pub fn prior_replayed_functions(
        &self,
    ) -> impl ExactSizeIterator<
        Item = (
            trust_ir::FuncId,
            &str,
            &[u8],
            &crate::jit_cert::JitCertificate,
        ),
    > + '_ {
        self.prior_functions.iter().map(|function| {
            (
                function.source_function,
                function.name.as_str(),
                function.code.as_slice(),
                &function.certificate,
            )
        })
    }
    #[cfg(feature = "verify")]
    pub const fn captured(&self) -> &trust_cg_verify::CapturedFunctionVerificationReport {
        &self.captured
    }
}

impl std::fmt::Debug for CoreAddressFreeMachineCompilationFailure {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("CoreAddressFreeMachineCompilationFailure")
            .field("error", &self.error)
            .field("module_name", &self.plan.module_name())
            .field("module_digest", &self.plan.module_digest())
            .field("plan_identity", &self.plan.identity())
            .finish_non_exhaustive()
    }
}

impl std::fmt::Display for CoreAddressFreeMachineCompilationFailure {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        std::fmt::Display::fmt(&self.error, f)
    }
}

impl std::error::Error for CoreAddressFreeMachineCompilationFailure {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        Some(&self.error)
    }
}

impl CoreAddressFreeMachineCompilationFailure {
    /// Consume a genuine earlier callee's finite return/effect evidence against
    /// this same failed compilation's exact immutable source, strict LIR, bytes
    /// and original request. This explicitly rehashes source custody and runs
    /// the existing callee byte checker; it is diagnostic/prerequisite work,
    /// never a cheap proof step or a caller/installation license.
    #[cfg(feature = "verify")]
    pub fn reattach_replayed_defined_callee(
        &self,
        function: trust_ir::FuncId,
    ) -> Result<
        trust_cg_verify::aarch64_affine_lowering::AttachedDefinedAffineCallee<'_>,
        CoreDefinedCalleeReplayError,
    > {
        let missing = || CoreDefinedCalleeReplayError::MissingCallee {
            function: function.index(),
        };
        let rejected = self.machine_rejection.as_ref().ok_or_else(missing)?;
        let prior = rejected
            .prior_functions
            .iter()
            .find(|prior| prior.source_function == function)
            .ok_or_else(missing)?;
        let summary = match &prior.defined_callee {
            Ok(Some(summary)) => summary,
            Ok(None) => return Err(missing()),
            Err(reason) => {
                return Err(CoreDefinedCalleeReplayError::SummaryRefused {
                    function: function.index(),
                    reason: reason.to_string(),
                });
            }
        };
        let module = &self.plan.plan.parts.module;
        let source = module.function_by_id(function).ok_or_else(missing)?;
        let lir = self
            .plan
            .plan
            .parts
            .lir_functions
            .iter()
            .find(|(lir, _)| lir.name == source.name)
            .map(|(lir, _)| lir)
            .ok_or(CoreDefinedCalleeReplayError::MissingLir {
                function: function.index(),
            })?;
        let modules = trust_cg_verify::FunctionSourceModules::capture(module, module)?;
        Ok(summary.attach(&modules, &rejected.request, function, lir, &prior.code)?)
    }

    /// The actual allocated input and captured report when the ordinary proof
    /// gate refused. Earlier refusals have no such input and return `None`.
    pub fn machine_rejection(&self) -> Option<&CoreMachineProofRejection> {
        self.machine_rejection.as_ref()
    }

    #[must_use]
    pub const fn reason(&self) -> &CoreAddressFreeMachineCompilationError {
        &self.error
    }

    #[must_use]
    pub const fn plan(&self) -> &PolicyQualifiedCoreJitCompilationPlan {
        &self.plan
    }

    #[must_use]
    pub fn into_parts(
        self,
    ) -> (
        CoreAddressFreeMachineCompilationError,
        PolicyQualifiedCoreJitCompilationPlan,
    ) {
        (self.error, self.plan)
    }
}

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

/// Verbosity level for the compiler's timing trace.
///
/// Distinct from [`trust_cg_ir::TraceLevel`] which controls structured event
/// logging. This enum controls per-phase timing output in the compiler API.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CompilerTraceLevel {
    /// No trace output.
    None,
    /// Summary: total time and pass counts.
    Summary,
    /// Full: per-phase timing and per-function details.
    Full,
}

/// Verification policy the high-level compiler applies when it lowers a
/// [`CompilerConfig`] into a [`crate::jit::JitConfig`].
///
/// The three modes form the JIT-5 validation ladder:
///
/// | mode              | function semantics              | discharge cost            |
/// |-------------------|-----------------------------------|---------------------------|
/// | [`Self::Unchecked`]      | no proof evidence (dev)           | none                      |
/// | [`Self::CachedVerified`] | proof-grade evidence per function | amortized (content cache) |
/// | [`Self::AlwaysVerify`]   | proof-grade evidence per function | full, every compile       |
///
/// `Unchecked` is loudly labeled and, on any arch whose default is a verifying
/// mode (x86-64 after JIT-5), reachable only via the explicit
/// `TCG_JIT_UNCHECKED=1` env opt-in or an explicit
/// [`CompilerConfig::jit_validation_mode_override`]. Both `CachedVerified` and
/// `AlwaysVerify` are fail-closed by construction: a cache miss re-verifies
/// (never skips) and a verification failure rejects the compile. Exact
/// published-image integrity is checked separately from semantic evidence.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum JitValidationMode {
    /// Dev-only low-latency JIT mode. No JIT proof certificates are requested
    /// and executed function semantics are NOT backed by proof evidence. Loudly
    /// labeled in every artifact; reaching it on a verifying-default arch
    /// requires an explicit opt-in (`TCG_JIT_UNCHECKED=1` or an explicit mode
    /// override).
    Unchecked,
    /// Target default (JIT-5): every function must carry non-vacuous,
    /// proof-grade semantic evidence, but the expensive discharge may be satisfied
    /// from a content-addressed certificate cache keyed by
    /// (canonical trust-ir/machine content hash x config fingerprint). A cache
    /// MISS falls back to FULL verification (never to skip); a verification
    /// FAILURE fails closed. Warm latency stays ~free while soundness matches
    /// [`Self::AlwaysVerify`].
    CachedVerified,
    /// Paranoid/CI fail-closed JIT mode. The executable buffer must be
    /// compiled with JIT verification enabled — every compile re-discharges,
    /// bypassing the certificate cache — so proof consumers cannot observe an
    /// empty certificate map as a vacuous success. Formerly `ProofRequired`.
    AlwaysVerify,
}

impl JitValidationMode {
    /// Whether this mode requires [`crate::jit::JitConfig::verify`] — i.e.
    /// every function must carry proof-grade semantic evidence.
    pub fn requires_jit_verification(self) -> bool {
        matches!(self, Self::CachedVerified | Self::AlwaysVerify)
    }

    /// Whether this mode may satisfy the verification obligation from the
    /// content-addressed certificate cache (warm-hit fast path). Only
    /// [`Self::CachedVerified`] consults the cache; [`Self::AlwaysVerify`]
    /// always re-discharges.
    pub fn uses_certificate_cache(self) -> bool {
        matches!(self, Self::CachedVerified)
    }

    /// Whether executed bytes are left uncertified (dev-only escape hatch).
    pub fn is_unchecked(self) -> bool {
        matches!(self, Self::Unchecked)
    }

    /// Stable lowercase label for metrics / replay metadata / diagnostics.
    pub fn label(self) -> &'static str {
        match self {
            Self::Unchecked => "unchecked",
            Self::CachedVerified => "cached-verified",
            Self::AlwaysVerify => "always-verify",
        }
    }

    fn ensure_supported(self, target: Target) -> Result<(), CompileError> {
        match self {
            Self::Unchecked => Ok(()),
            Self::CachedVerified | Self::AlwaysVerify if target == Target::Riscv64 => {
                Err(CompileError::ProofsUnsupportedForTarget { target })
            }
            Self::CachedVerified | Self::AlwaysVerify => {
                #[cfg(feature = "verify")]
                {
                    let _ = target;
                    Ok(())
                }
                #[cfg(not(feature = "verify"))]
                {
                    Err(CompileError::ProofsUnsupportedForTarget { target })
                }
            }
        }
    }
}

/// Environment escape hatch: setting `TCG_JIT_UNCHECKED=1` downgrades an
/// otherwise-verifying default JIT validation mode to [`JitValidationMode::Unchecked`].
///
/// This is the ONLY way to execute uncertified JIT bytes on the default path
/// of a verifying-default arch (x86-64 after JIT-5). It is loudly labeled: a
/// stderr marker is emitted the first time the downgrade takes effect, and the
/// resolved mode is recorded in every [`JitCompilationResult`] provenance.
pub(crate) const JIT_UNCHECKED_ENV: &str = "TCG_JIT_UNCHECKED";

/// The default JIT validation mode for a target arch, before any explicit
/// override or `emit_proofs` back-compat mapping is applied.
///
/// JIT-5 flips x86-64 to [`JitValidationMode::CachedVerified`]. AArch64 stays
/// [`JitValidationMode::Unchecked`] pending the production flip (JIT-11 /
/// A64-8, an M-series lane). RISC-V has no verifier and stays `Unchecked`.
/// In a build without the `verify` feature no mode can verify, so every arch
/// defaults to `Unchecked` (the mode is still selectable but degrades to
/// dev-only).
pub(crate) fn arch_default_jit_validation_mode(target: Target) -> JitValidationMode {
    #[cfg(feature = "verify")]
    {
        match target {
            // JIT-5: x86-64 host JIT executes only cert-covered bytes by default.
            Target::X86_64 => JitValidationMode::CachedVerified,
            // aarch64 default flip is JIT-11/A64-8 (M-series); riscv has no verifier.
            _ => JitValidationMode::Unchecked,
        }
    }
    #[cfg(not(feature = "verify"))]
    {
        let _ = target;
        JitValidationMode::Unchecked
    }
}

/// Whether the `TCG_JIT_UNCHECKED=1` env escape hatch is engaged.
fn jit_unchecked_env_engaged() -> bool {
    crate::env_lock::var(JIT_UNCHECKED_ENV)
        .ok()
        .map(|v| v == "1")
        .unwrap_or(false)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct JitValidationResolution {
    mode: JitValidationMode,
    warning_via_env: Option<bool>,
}

/// Emit the loud one-time marker when an Unchecked downgrade takes effect, so
/// executing functions without proof evidence can never be silent.
fn warn_jit_unchecked_engaged(target: Target, via_env: bool) {
    use std::sync::atomic::{AtomicBool, Ordering};
    static WARNED: AtomicBool = AtomicBool::new(false);
    if !WARNED.swap(true, Ordering::Relaxed) {
        let how = if via_env {
            "TCG_JIT_UNCHECKED=1"
        } else {
            "explicit jit_validation_mode_override"
        };
        eprintln!(
            "[trust-cg][JIT][UNCHECKED] executing JIT functions without proof evidence on \
             {target:?} (validation downgraded to Unchecked via {how}); the published image \
             remains integrity-sealed but function semantics are not verified"
        );
    }
}

/// The allocation-quality policy of an x86-64 object compile: a compile that
/// emits proof certificates keeps the historical allocation whatever a driver
/// installed or requested (`Withheld`); one that emits none and requests it
/// (`CompilerConfig::x86_certificate_free_allocation`, which a TY
/// ahead-of-time driver sets) gets the allocation-quality changes unless an
/// installed policy opted out of one (`CertificateFree`); any other compile
/// follows the installed process policy alone (`Installed`), so a default
/// configuration emits the same bytes with and without certificates
/// ([`crate::x86_64::pipeline::X86AllocationQuality`]).
pub(crate) fn x86_object_allocation_quality(
    emit_proofs: bool,
    certificate_free_requested: bool,
) -> crate::x86_64::pipeline::X86AllocationQuality {
    use crate::x86_64::pipeline::X86AllocationQuality;
    if emit_proofs {
        X86AllocationQuality::Withheld
    } else if certificate_free_requested {
        X86AllocationQuality::CertificateFree
    } else {
        X86AllocationQuality::Installed
    }
}

#[cfg(test)]
mod x86_object_allocation_quality_tests {
    use super::x86_object_allocation_quality;
    use crate::x86_64::pipeline::X86AllocationQuality;

    #[test]
    fn a_certificate_keeping_compile_keeps_the_historical_allocation() {
        // Certificates kept: withheld, even when certificate-free is requested.
        assert_eq!(
            x86_object_allocation_quality(true, true),
            X86AllocationQuality::Withheld
        );
        assert_eq!(
            x86_object_allocation_quality(true, false),
            X86AllocationQuality::Withheld
        );
        // Only an explicit request makes a compile certificate-free.
        assert_eq!(
            x86_object_allocation_quality(false, true),
            X86AllocationQuality::CertificateFree
        );
        // The default configuration follows the installed policy, so
        // `emit_proofs` alone never changes the allocation.
        assert_eq!(
            x86_object_allocation_quality(false, false),
            X86AllocationQuality::Installed
        );
        assert!(!super::CompilerConfig::default().x86_certificate_free_allocation);
    }
}

/// Configuration for the [`Compiler`].
#[derive(Debug, Clone)]
pub struct CompilerConfig {
    /// Optimization level (O0 through O3).
    pub opt_level: OptLevel,
    /// Target architecture.
    ///
    /// `CompilerConfig::default()` intentionally preserves Trust Codegen's legacy
    /// object-code default of [`Target::Aarch64`]. It is not a host-JIT
    /// default. In-process JIT callers should use
    /// [`CompilerConfig::for_host_jit()`] or [`Compiler::for_host()`].
    pub target: Target,
    /// Whether to emit proof certificates for each compiled function.
    ///
    /// Requests target-specific instruction and object evidence reports. A
    /// verified entry rests on exhaustive or solver/checker-backed evidence;
    /// emitting a [`ProofCertificate`] does not itself make it a formal proof.
    /// Promotion admits no negative report: sampled evidence and registry
    /// theorems selected by name are reported as unverified entries and block
    /// like any other gap. Verifying JIT modes additionally require non-vacuous
    /// per-function evidence.
    pub emit_proofs: bool,
    /// Compilation trace verbosity.
    pub trace_level: CompilerTraceLevel,
    /// Whether to emit DWARF debug info sections in the output object file.
    ///
    /// When true, AArch64 objects carry DWARF 4 `.debug_abbrev`, `.debug_info`,
    /// `.debug_str` and `.debug_line` sections (`__DWARF,__debug_*` on
    /// Mach-O), plus `.debug_loc` when a variable uses a location list.
    pub emit_debug: bool,
    /// Whether to compile functions in parallel using rayon.
    ///
    /// When true and the module contains 2+ functions, the per-function
    /// compilation phases (ISel, optimization, register allocation, frame
    /// lowering, branch resolution) run in parallel across a rayon thread
    /// pool. The final Mach-O emission phase remains sequential since it
    /// builds a single combined `__text` section.
    ///
    /// Default: `true`.
    pub parallel: bool,
    /// Per-function budget, in seconds, for the CEGIS superopt pass.
    ///
    /// When `Some(n)`, the pipeline runs [`trust_cg_verify::CegisSuperoptPass`]
    /// with `budget_sec = n` during optimization. The budget is wall-clock
    /// time for solver-backed verifications only: its clock starts at the
    /// function's first solver-backed query, and no further query starts once
    /// it has elapsed. A search left with unverified candidates is a hard
    /// [`crate::pipeline::PipelineError::CegisIncomplete`] error. Results are
    /// keyed into the compilation cache so repeat compilations reuse proven
    /// rewrites. When `None` (default), the pass is not scheduled. The CLI flag
    /// `--cegis-superopt=<secs>` sets this field.
    ///
    /// Issue: #395. Default: `None` (off).
    pub cegis_superopt_budget_sec: Option<u64>,
    /// Run the bounded trust_ir fsym preflight from the real compiler pipeline.
    ///
    /// This is diagnostic-only: concrete UB diagnostics, bounded skips, and
    /// unknown obligations are surfaced through [`CompilationMetrics`], but
    /// the compiler does not reject code here. Rejection policy remains owned
    /// by frontends such as `trust-cg --fsym=error`.
    ///
    /// Issue: #377. Default: `false` (off).
    pub enable_fsym_trust_ir_preflight: bool,
    /// Use the JIT-latency register allocator profile.
    ///
    /// When `true`, register allocation runs
    /// [`trust_cg_regalloc::AllocConfig::jit_latency_aarch64`] — the LinearScan
    /// core with quality features disabled (no coalescing, no splitting, no
    /// slot reuse). Targeted at the BCP/parent-loop JIT shapes where compile
    /// latency dominates code quality.
    ///
    /// [`CompilerConfig::for_host_jit`] turns this on. The default and
    /// AOT object-code paths leave it off so the existing
    /// [`AllocStrategy::LinearScan`] code-quality features remain in play.
    pub enable_jit_fast_regalloc: bool,
    /// Explicit override for the JIT validation mode (JIT-5).
    ///
    /// When `None` (the default) the mode is derived from `emit_proofs` and
    /// the target's arch default via [`Self::jit_validation_mode`]. When
    /// `Some(mode)` the override wins over both — an in-code opt-in that, for
    /// [`JitValidationMode::Unchecked`], is an explicit and loudly-labeled
    /// alternative to the `TCG_JIT_UNCHECKED=1` env escape hatch.
    ///
    /// This exists so that:
    /// - callers who need dev-only raw codegen (e.g. exercising opcodes whose
    ///   proofs are still pending) can request `Unchecked` without the env; and
    /// - CI can pin `AlwaysVerify` regardless of arch default.
    pub jit_validation_mode_override: Option<JitValidationMode>,
    /// Address source for unresolved JIT external symbols.
    ///
    /// The compatibility default checks the explicit symbol map first and
    /// then the current process. [`JitExternalSymbolResolutionPolicy::ExplicitOnly`]
    /// disables ambient process lookup, so every external capability must be
    /// supplied by the caller.
    pub jit_external_symbol_resolution: JitExternalSymbolResolutionPolicy,
    /// Whole-program `panic=unwind` mode (FUZZ-7 / EH Lane 5, cross-object).
    ///
    /// A panic unwinds across object boundaries; a pass-through frame in an
    /// object with no local landing pad would otherwise stop phase-1 unwind
    /// dead (`_URC_END_OF_STACK`), skipping every cleanup Drop. The frontend
    /// sets this from `tcx.sess.panic_strategy()`. What it changes, per output:
    ///
    /// * x86-64 Mach-O: every frame-covered function gets a compact-unwind
    ///   entry and a zPLR FDE with an all-filler LSDA ("keep walking, never
    ///   dispatch") under the module's personality GOT slot, even in an object
    ///   with no exception-handling function.
    /// * x86-64 ELF: the module gets the exception-handling unwind surface —
    ///   `.gcc_except_table`, a zPLR `.eh_frame` with an FDE and an LSDA (the
    ///   filler for functions without EH) for EVERY function, and the
    ///   `DW.ref.<personality>` slot — whenever any function has a frame.
    ///   `Compiler` lowers every x86-64 function with a frame, so every
    ///   non-empty x86-64 object carries exception tables under this flag.
    /// * x86-64 COFF and raw bytes, and every AArch64 object (ELF and Mach-O):
    ///   not read; the object is byte-identical either way.
    /// * The unchecked AArch64 JIT: every published frame gets registered
    ///   in-memory unwind tables (`crate::jit_unwind`); proof-grade JIT
    ///   requests refuse the flag by name.
    ///
    /// Exception tables carry no proof obligation, so a proof-required
    /// (`emit_proofs`) x86-64 Mach-O or ELF compile with this flag is refused
    /// for every non-empty module (`CompileError::ExceptionTablesUnproved`):
    /// certified x86-64 Mach-O and ELF objects need `panic=abort`. A certified
    /// x86-64 COFF compile is refused either way, by its relocation inventory
    /// (no proof lane is registered for COFF relocations), which this flag
    /// does not change. When false the objects are byte-identical to before
    /// this field existed.
    pub panic_unwind: bool,
    /// ELF relocation model for object emission (see [`RelocationModel`]).
    ///
    /// `Static` (the default) and `Pie` compile for an executable image:
    /// defined symbols are addressed PC-relatively and thread-locals use
    /// local-exec (definitions) or initial-exec (imports). `Pic` compiles for
    /// a shared object: preemptible default-visibility definitions are
    /// addressed through the GOT, calls to them keep `CALL26` relocations the
    /// linker routes through the PLT, preemptible functions are never inlined,
    /// and thread-locals use general-dynamic TLS descriptors. Only AArch64 ELF
    /// object emission implements `Pie`/`Pic`; every other route refuses them
    /// with [`CompileError::RelocationModelUnsupported`]. Recorded in the
    /// compile policy's artifact projection and the artifact-cache identity.
    pub relocation_model: RelocationModel,
    /// Place every function in its own `.text.<symbol>` section (the
    /// `-ffunction-sections` policy) so `ld --gc-sections` can drop unused
    /// functions individually.
    ///
    /// Read only by the AArch64 ELF object emitters; Mach-O dead-strips at
    /// atom granularity already and x86-64/RISC-V ignore it. `false` (the
    /// default) keeps every non-COMDAT function in one `.text` section, byte
    /// for byte as before this field existed. Recorded in the compile policy
    /// (Artifact partition) and in the compile-artifact cache identity, both
    /// only when `true`, so every default-policy digest is unchanged.
    pub function_sections: bool,
    /// Explicit AArch64 optional-ISA admission for object emission.
    ///
    /// `None` (the default) uses the target contract,
    /// [`AArch64IsaProfile::for_aot_target`]: Apple arm64 admits LSE, DotProd
    /// and FEAT_FP16; generic Linux and unknown AArch64 targets admit none,
    /// so their FEAT_FP16 scalar forms are refused by name. `Some(profile)`
    /// replaces that contract with exactly `profile` — the only route by
    /// which a generic Linux object admits FEAT_FP16 — and is recorded, never
    /// applied silently: in the compile policy's Artifact partition, in the
    /// compile-artifact cache identity (both only when `Some`, so every
    /// default digest is unchanged), in the compile service's target
    /// descriptor features and artifact identity, and in the per-function
    /// AArch64 machine-code evidence. Nothing checks that the CPU which later
    /// runs the object has the features; that is the caller's contract.
    /// Refused ([`CompileError::Aarch64IsaProfileUnsupported`]) for
    /// non-AArch64 targets and for in-process JIT compilation, whose
    /// admission is the host CPU's detected features.
    pub aarch64_isa_profile: Option<AArch64IsaProfile>,
    /// Keep an entry frame pointer in every AArch64 object function.
    ///
    /// Disables the red zone, zero-storage frame omission and shrink-wrapping.
    /// This is an object-code policy; non-AArch64 and JIT routes refuse it.
    /// `false` preserves the existing target and proof-owner frame decisions.
    pub aarch64_force_frame_pointers: bool,
    /// Function names the module inliner never splices into a caller: every
    /// call to one stays a call (rustc's `#[inline(never)]`, LLVM `noinline`;
    /// trust-ir `FuncAttrs` carries no such fact, so a producer supplies the
    /// names here).
    ///
    /// The set is unioned into the names OPT-4 already withholds
    /// (load-time preemptible and static-link replaceable definitions,
    /// `inliner_interposable_function_names`) at the AOT pre-dispatch seam of
    /// [`Compiler::compile`], so every target inherits it, and into the
    /// in-process JIT's module step. A named inline-only
    /// (`AvailableExternally`) body is never spliced either. A name the
    /// module does not define has no effect. OPT-4 is the only inliner a
    /// compile runs (the machine-level `inline` pass is registered with no
    /// callee). Empty (the default) changes nothing. Recorded in the compile
    /// policy (Artifact partition) and in the compile-artifact cache
    /// identity, both only when non-empty, so every default digest is
    /// unchanged; refused at the closed-JIT Core proof-grade boundary like
    /// every other non-default control.
    pub never_inline: BTreeSet<String>,
    /// The frontend's statement that no exception may propagate out of any
    /// function this compile defines. rustc's `fn_can_unwind` makes this true
    /// of every Rust-defined function under `-C panic=abort`, an
    /// `extern "C-unwind"` export included: rustc declares each such function
    /// `nounwind` to LLVM.
    ///
    /// The AArch64 LSDA of every exception-handling function then applies the
    /// region rule of the table LLVM builds for a `nounwind` function
    /// (`EHStreamer::computeCallSiteTable`,
    /// [`crate::pipeline::EhPropagation::NounwindFrame`]) to this backend's
    /// calls; it is not a handlers-only table: the explicit `Invoke` handler
    /// ranges, plus a "keep unwinding" entry for each region between them that
    /// contains an indirect call or a direct call to a symbol outside
    /// [`Self::eh_nounwind_callees`]. A region whose every call names a
    /// `nounwind` callee is left out, so a phase-one search reaching one of its
    /// call sites (a second panic raised through an abort-defined cleanup
    /// `Drop` call, say) is reported by the Rust personality as
    /// `_URC_FATAL_PHASE1_ERROR` instead of searching on to an outer handler. A
    /// search reaching a region that holds an indirect call continues. Self
    /// and sibling tail-call optimization is disabled for these EH frames;
    /// a tail exit surviving to final EH layout is refused because it would
    /// remove the frame before its table can be consulted. `false`
    /// (the default) keeps the full-coverage propagation filler, byte for byte
    /// as before this field existed.
    ///
    /// The coverage is LLVM's only where the two instruction streams agree on
    /// which calls a region holds, and they often do not: LLVM inlines helpers
    /// that hold indirect calls, calls `memcpy` / `memcmp` for copies and
    /// compares this backend expands inline, places cold and noreturn blocks
    /// elsewhere, and turns self-recursion into a loop. Each leaves a region
    /// covered under LLVM that is a gap here, so a search LLVM continues (to a
    /// termination pad, or through the frame to a handler that may catch it)
    /// aborts here in phase one: every divergence this policy adds over the
    /// filler aborts earlier, never later. The reverse (LLVM devirtualises an
    /// indirect call or lays a region out differently, so its region is the
    /// gap) searches on here to a termination pad, as the filler did. The
    /// measured counts, and the follow-up that would close the class, are on
    /// [`crate::pipeline::EhPropagation::NounwindFrame`]. A symbol the frontend
    /// did not name is treated as one that may unwind. LLVM's merge of adjacent
    /// invokes that share a landing pad is not modeled (rustc gives every
    /// foreign call in a nounwind body its own pad, so it does not arise
    /// there).
    ///
    /// Only `rust_eh_personality` frames on AArch64 are modeled: another
    /// personality is refused by the pipeline, and a non-AArch64 target or
    /// in-process JIT code by [`CompileError::EhFramesCannotUnwindUnsupported`].
    /// Recorded in the compile policy (Artifact partition) and in the
    /// compile-artifact cache identity, both only when `true`, so every
    /// default-policy digest is unchanged.
    pub eh_frames_cannot_unwind: bool,
    /// The callee symbols the frontend states cannot unwind: those LLVM would
    /// treat as `nounwind` (rustc adds the attribute to a declaration exactly
    /// when the callee's `FnAbi::can_unwind` is false, and LLVM infers it for
    /// a library function such as `memcmp` only above O0), and the frontend's
    /// own runtime calls where LLVM has no call that may unwind at the same
    /// point. Read only with [`Self::eh_frames_cannot_unwind`], whose region
    /// rule treats a direct call to any other symbol, like every indirect
    /// call, as one that may unwind; a module compile adds the runtime
    /// routines this backend itself calls where LLVM has none
    /// ([`crate::pipeline::backend_expansion_nounwind_callees`]). Names are the
    /// module's final function names, the operands of the encoded calls.
    /// Ignored (and unrecorded) when that policy is off; recorded in the
    /// compile policy and cache identity with it.
    pub eh_nounwind_callees: BTreeSet<String>,
    /// The trusted runtime routines that another compile unit of this
    /// module's link unit defines, by link-time symbol, as the frontend
    /// states (ruling OD-216): for the rustc bridge, every such routine any
    /// codegen unit of the crate defines (`#[no_mangle]`/`#[export_name]`
    /// items included).
    ///
    /// The x86-64 body theorem trusts the contract of the routine a call
    /// binds to (an `I128` division's `__udivti3`, `__divti3`, `__umodti3` or
    /// `__modti3`; an LIR `Memcpy`'s, `Memmove`'s or `Memset`'s `memcpy`,
    /// `memmove` or `memset`) only where nothing in the link unit under proof
    /// defines it: OD-210 reads the module's own definitions
    /// (`trust_cg_verify::X86ModuleDefinitions::of_trust_ir_module`), and
    /// these name the rest of the link unit
    /// (`trust_cg_verify::X86ModuleDefinitions::with_link_unit`), so a body
    /// whose call binds to such a definition gets no theorem. Any other name
    /// is ignored (`trust_cg_verify::X86ModuleDefinitions::trusted_routine`).
    /// It only withholds body-theorem credit, never adds any, and changes no
    /// emitted byte. Empty (the default): the module is its own link unit,
    /// as before. Recorded in the compile policy (Evidence partition) and in
    /// the compile-artifact cache identity, both only when non-empty, so every
    /// default digest is unchanged; refused at the closed-JIT Core proof-grade
    /// boundary like every other non-default control.
    pub link_unit_definitions: BTreeSet<String>,
    /// Give an x86-64 object compile the code-quality changes the rustc
    /// bridge installs for `no-proof-certs`: the register-allocation changes
    /// (ABI copy hints, caller-saved-first order, cold-call weighting, the
    /// conditional-call split), frameless leaves in an object without unwind
    /// tables, the O2 machine-pass fixpoint and the certificate-free IMUL
    /// reductions, each unless an installed process policy opted out of it
    /// ([`crate::x86_64::pipeline::X86AllocationQuality::CertificateFree`]).
    /// The name predates everything but the allocation changes and is kept
    /// because it is a compile-policy Artifact field
    /// (`TAG_COMPILER_X86_CERTIFICATE_FREE_ALLOCATION`): it requests the
    /// certificate-free code-quality policy as a whole.
    ///
    /// A driver that keeps no proof certificates and installs no policy (the
    /// TY ahead-of-time path) sets this to get them. It changes emitted bytes,
    /// so it is an Artifact field of the compile policy (present only when
    /// on), and the compile's bytes are then NOT the bytes a certificate-
    /// keeping compile of the same module emits. With `emit_proofs` set it is
    /// overridden: a certificate-keeping compile keeps the historical
    /// allocation whatever this says or a driver installed
    /// (`X86AllocationQuality::Withheld`). Refused at the closed-JIT Core
    /// proof-grade boundary. Ignored for other targets. Default: `false`, the
    /// process policy alone (`X86AllocationQuality::Installed`).
    pub x86_certificate_free_allocation: bool,
}

impl Default for CompilerConfig {
    fn default() -> Self {
        Self {
            opt_level: OptLevel::O2,
            target: Target::Aarch64,
            emit_proofs: false,
            trace_level: CompilerTraceLevel::None,
            emit_debug: false,
            parallel: true,
            cegis_superopt_budget_sec: None,
            enable_fsym_trust_ir_preflight: false,
            enable_jit_fast_regalloc: false,
            jit_validation_mode_override: None,
            jit_external_symbol_resolution: JitExternalSymbolResolutionPolicy::default(),
            panic_unwind: false,
            relocation_model: RelocationModel::Static,
            function_sections: false,
            aarch64_isa_profile: None,
            aarch64_force_frame_pointers: false,
            never_inline: BTreeSet::new(),
            eh_frames_cannot_unwind: false,
            eh_nounwind_callees: BTreeSet::new(),
            link_unit_definitions: BTreeSet::new(),
            x86_certificate_free_allocation: false,
        }
    }
}

impl CompilerConfig {
    /// Host-safe profile for in-process JIT compilation.
    ///
    /// This is equivalent to [`CompilerConfig::jit_fast`] with
    /// [`Target::host`]. Use this when generated code will be placed in
    /// executable memory and called by the current process. It deliberately
    /// avoids inheriting [`CompilerConfig::default`]'s concrete AArch64 target.
    pub fn for_host_jit() -> Self {
        Self::jit_fast(Target::host())
    }

    /// Low-latency profile for tiny JIT modules.
    ///
    /// Solver and runtime specializers often compile one small function whose
    /// first-use latency matters more than peak standalone code quality. This
    /// profile keeps the API explicit for those consumers instead of requiring
    /// each embedder to rediscover the same knobs.
    ///
    /// The `target` argument is explicit. For in-process execution, prefer
    /// [`CompilerConfig::for_host_jit`] so the selected target matches
    /// [`Target::host`].
    pub fn jit_fast(target: Target) -> Self {
        Self {
            opt_level: OptLevel::O1,
            target,
            emit_proofs: false,
            trace_level: CompilerTraceLevel::None,
            emit_debug: false,
            parallel: false,
            cegis_superopt_budget_sec: None,
            enable_fsym_trust_ir_preflight: false,
            // The jit_fast profile is the canonical home for the new
            // latency-tuned regalloc strategy. Tests and AOT compiles that
            // need the full quality features keep the Default profile.
            enable_jit_fast_regalloc: true,
            // JIT-5: leave the mode unset so it resolves to the target's arch
            // default (x86-64 -> CachedVerified; aarch64 -> Unchecked pending
            // JIT-11). Callers that need a dev-only raw JIT set the override.
            jit_validation_mode_override: None,
            jit_external_symbol_resolution: JitExternalSymbolResolutionPolicy::default(),
            // No walk-through unwind tables unless requested. Functions that
            // carry EH metadata get their tables either way (Unchecked only).
            panic_unwind: false,
            // JIT code is never linked; only the static model is accepted.
            relocation_model: RelocationModel::Static,
            function_sections: false,
            // JIT admission is the host CPU's detected features.
            aarch64_isa_profile: None,
            aarch64_force_frame_pointers: false,
            never_inline: BTreeSet::new(),
            // In-process JIT code has no modeled non-unwinding frame LSDA.
            eh_frames_cannot_unwind: false,
            eh_nounwind_callees: BTreeSet::new(),
            // The module is its own link unit.
            link_unit_definitions: BTreeSet::new(),
            x86_certificate_free_allocation: false,
        }
    }

    /// Dev-only host-JIT profile that executes UNCERTIFIED bytes.
    ///
    /// Equivalent to [`Self::for_host_jit`] but with an explicit
    /// [`JitValidationMode::Unchecked`] override, the loud in-code opt-in that
    /// bypasses the JIT-5 cert-coverage requirement without needing the
    /// `TCG_JIT_UNCHECKED=1` env var. Use only for exercising codegen whose
    /// instruction proofs are still pending (e.g. SIMD lanes); never in a
    /// production execution path.
    pub fn for_host_jit_unchecked() -> Self {
        Self {
            jit_validation_mode_override: Some(JitValidationMode::Unchecked),
            ..Self::for_host_jit()
        }
    }

    /// JIT validation policy implied by this compiler configuration.
    ///
    /// Resolution order (JIT-5), env-independent:
    /// 1. an explicit [`Self::jit_validation_mode_override`] wins;
    /// 2. otherwise `emit_proofs == true` maps to [`JitValidationMode::AlwaysVerify`]
    ///    (back-compat: the former `ProofRequired`);
    /// 3. otherwise the target's arch default
    ///    ([`arch_default_jit_validation_mode`]): x86-64 -> `CachedVerified`,
    ///    others -> `Unchecked`.
    ///
    /// This is the *configured* mode. The env escape hatch
    /// (`TCG_JIT_UNCHECKED=1`) is applied separately at compile time by
    /// [`Self::resolve_jit_validation_mode`] so a pure config query stays
    /// deterministic (the M4 gate asserts `for_host_jit().jit_validation_mode()`
    /// == `CachedVerified` on x86-64 without consulting the environment).
    pub fn jit_validation_mode(&self) -> JitValidationMode {
        if let Some(mode) = self.jit_validation_mode_override {
            return mode;
        }
        if self.emit_proofs {
            return JitValidationMode::AlwaysVerify;
        }
        arch_default_jit_validation_mode(self.target)
    }

    /// Compile-time resolution of the JIT validation mode, applying the
    /// `TCG_JIT_UNCHECKED=1` env escape hatch and the fail-closed downgrade
    /// gate.
    ///
    /// - If the configured mode ([`Self::jit_validation_mode`]) is a verifying
    ///   mode, it is returned unchanged (unless the env downgrades an
    ///   *arch-default* verifying mode to Unchecked).
    /// - If the configured mode is `Unchecked`, it is permitted only when the
    ///   arch's own default is already `Unchecked` (e.g. aarch64 pending
    ///   JIT-11), OR the caller set an explicit override, OR the
    ///   `TCG_JIT_UNCHECKED=1` env var is engaged. Otherwise — an implicit
    ///   Unchecked on a verifying-default arch — this FAILS CLOSED: executing
    ///   functions without semantic proof evidence requires the explicit opt-in.
    ///
    /// Any resolved `Unchecked` is loudly labeled (a one-time stderr marker).
    pub fn resolve_jit_validation_mode(&self) -> Result<JitValidationMode, CompileError> {
        let resolution = self
            .jit_validation_resolution()
            .map_err(|target| CompileError::JitUncertifiedBytesRequireOptIn { target })?;
        if let Some(via_env) = resolution.warning_via_env {
            warn_jit_unchecked_engaged(self.target, via_env);
        }
        Ok(resolution.mode)
    }

    fn jit_validation_resolution(&self) -> Result<JitValidationResolution, Target> {
        self.jit_validation_resolution_with(jit_unchecked_env_engaged)
    }

    /// Resolve compatibility validation policy while delaying the legacy
    /// environment query until it can affect the answer.
    ///
    /// An explicit override and the `emit_proofs` compatibility spelling are
    /// complete policies. Neither path may consult `TCG_JIT_UNCHECKED`, even
    /// to rediscover that the value cannot override them. Keeping the reader
    /// injected also lets tests prove those branches are ambient-read-free.
    fn jit_validation_resolution_with(
        &self,
        read_jit_unchecked_env: impl FnOnce() -> bool,
    ) -> Result<JitValidationResolution, Target> {
        let arch_default = arch_default_jit_validation_mode(self.target);

        if let Some(mode) = self.jit_validation_mode_override {
            return if mode.is_unchecked() && !arch_default.is_unchecked() {
                Ok(JitValidationResolution {
                    mode,
                    warning_via_env: Some(false),
                })
            } else {
                Ok(JitValidationResolution {
                    mode,
                    warning_via_env: None,
                })
            };
        }

        if self.emit_proofs {
            return Ok(JitValidationResolution {
                mode: JitValidationMode::AlwaysVerify,
                warning_via_env: None,
            });
        }

        if arch_default.is_unchecked() {
            // The legacy escape hatch cannot change an already-Unchecked
            // default. Return before querying it so no-default-feature and
            // not-yet-verifying architectures stay ambient-read-free too.
            return Ok(JitValidationResolution {
                mode: JitValidationMode::Unchecked,
                warning_via_env: None,
            });
        }

        let env_engaged = read_jit_unchecked_env();

        // The env escape hatch downgrades an arch-default verifying mode to
        // Unchecked (the "execute without semantic proof evidence on the default path"
        // opt-in). Explicit overrides and `emit_proofs` returned before the
        // compatibility environment was read.
        if env_engaged {
            return Ok(JitValidationResolution {
                mode: JitValidationMode::Unchecked,
                warning_via_env: Some(true),
            });
        }

        Ok(JitValidationResolution {
            mode: arch_default,
            warning_via_env: None,
        })
    }

    /// Proof-policy partition used by the compile artifact cache.
    pub fn compile_artifact_proof_policy(&self) -> CompileArtifactProofPolicy {
        if self.jit_validation_mode().requires_jit_verification() {
            CompileArtifactProofPolicy::ProofTvFull
        } else {
            CompileArtifactProofPolicy::Unchecked
        }
    }

    /// Convert this high-level compiler configuration into the lower-level
    /// JIT configuration, preserving fail-closed proof requirements.
    pub fn to_jit_config(
        &self,
        profile_hooks: crate::jit::ProfileHookMode,
    ) -> Result<crate::jit::JitConfig, CompileError> {
        let validation_mode = self.resolve_jit_validation_mode()?;
        self.to_jit_config_with_validation_mode(profile_hooks, validation_mode)
    }

    fn to_jit_config_with_validation_mode(
        &self,
        profile_hooks: crate::jit::ProfileHookMode,
        validation_mode: JitValidationMode,
    ) -> Result<crate::jit::JitConfig, CompileError> {
        validation_mode.ensure_supported(self.target)?;
        Ok(crate::jit::JitConfig {
            opt_level: self.opt_level,
            verify: validation_mode.requires_jit_verification(),
            // JIT-5: only CachedVerified consults the certificate cache;
            // AlwaysVerify re-discharges every compile.
            cache_certificates: validation_mode.uses_certificate_cache(),
            profile_hooks,
            external_symbol_resolution: self.jit_external_symbol_resolution,
            // #375: Inherit the JitConfig default (ErrorOnFailure) so
            // dispatch verification failures surface here too rather than
            // being silently rewritten to a CPU-only plan. compile_raw does
            // not currently invoke the dispatch verifier, so this is mostly
            // defensive wiring for future heterogeneous-aware code paths.
            ..Default::default()
        })
    }
}

// ---------------------------------------------------------------------------
// Result types
// ---------------------------------------------------------------------------

/// Metrics collected during compilation.
#[derive(Debug, Clone, Default)]
pub struct CompilationMetrics {
    /// Total size of emitted machine code in bytes.
    pub code_size_bytes: usize,
    /// Total number of machine instructions emitted (across all functions).
    pub instruction_count: usize,
    /// Number of functions compiled.
    pub function_count: usize,
    /// Number of optimization passes executed.
    pub optimization_passes_run: usize,
    /// Summary of proof-optimization certificate citations observed while
    /// preparing codegen artifacts.
    pub proof_optimizations: ProofOptimizationMetrics,
    /// Bounded trust_ir fsym preflight diagnostics observed while preparing
    /// codegen artifacts.
    pub fsym_trust_ir: FsymTrustIrMetrics,
    /// Per-pass translation-validation verdicts of the AArch64 optimizer and
    /// scheduler runs, merged over the compiled functions
    /// ([`trust_cg_opt::pass_validation`]). Under the default diagnostic
    /// policy this is where a refuted or unproved run reaches the caller
    /// (beside a `trust-cg: warning:` line on standard error); a refusing
    /// policy fails the compile instead. Empty for routes that run no
    /// AArch64 optimizer.
    pub pass_validation: trust_cg_opt::PassValidationSummary,
    /// Each AArch64 function's composed transition record (L09-P3,
    /// [`crate::composed_transition`]), in function order, when the
    /// preparation built one: always on the proof-grade routes (the
    /// verifying JIT, `--emit-proofs` objects), which refuse a function a
    /// TrustIR-bound legalization check covers unless its record composes
    /// and reaches the bytes they publish. Empty otherwise.
    pub composed_transitions: Vec<trust_cg_verify::composed_transition::TransitionRecord>,
    /// Functions whose composed chain the route required and bound to the
    /// bytes it published (the `--emit-proofs` object's symbol extents, the
    /// verifying JIT's installed ranges): the count of publication checks
    /// that actually ran. Zero on routes that require no composition.
    pub composed_publications: usize,
}

/// Public aggregate of bounded trust_ir fsym preflight output.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct FsymTrustIrMetrics {
    /// Functions scanned by the bounded preflight.
    pub scanned_functions: usize,
    /// Functions skipped because they exceeded the bounded preflight scope.
    pub skipped_functions: usize,
    /// Concrete UB diagnostics reported by the bounded preflight.
    pub concrete_ub_diagnostics: usize,
    /// Unknown obligations that need a stronger backend or solver.
    pub unknown_obligations: usize,
    /// Total warning records that a caller could surface.
    pub warnings: usize,
}

/// Compact public summary of proof-optimization transform certificates.
///
/// This is derived from [`ProofOptimizationCertificateCitation`] values that
/// codegen already exposes, not from `trust-cg-opt` pass internals.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct ProofOptimizationMetrics {
    /// Total proof-optimization certificates cited by the compile.
    pub certificate_count: usize,
    /// Certificates whose cited transform was applied.
    pub applied_count: usize,
    /// Certificates whose cited transform was rejected.
    pub rejected_count: usize,
    /// Applied guard-elimination transforms.
    pub guard_eliminated_count: usize,
    /// Rejected guard-elimination transforms.
    pub guard_rejected_count: usize,
    /// Applied division-by-zero guard eliminations justified by NonZeroDivisor.
    pub non_zero_divisor_guard_eliminated_count: usize,
    /// Applied shift-range guard eliminations justified by ValidShift.
    pub valid_shift_guard_eliminated_count: usize,
    /// Rejected NonZeroDivisor guard-elimination attempts.
    pub non_zero_divisor_guard_rejected_count: usize,
    /// Rejected ValidShift guard-elimination attempts.
    pub valid_shift_guard_rejected_count: usize,
}

/// Per-function code-quality metrics. Surfaced through
/// [`JitCompilationResult::per_function_metrics`] so callers can identify
/// functions with high spill pressure, unusual branch density, etc.
///
/// See issue #364 item 3.
#[derive(Debug, Clone, Default)]
pub struct FunctionQualityMetrics {
    pub name: String,
    /// Per-function code bytes. The x86 JIT reports the exact encoded symbol
    /// span; fixed-width non-x86 paths report instruction-stream bytes.
    pub code_size_bytes: usize,
    /// Real (non-pseudo) machine instructions emitted.
    pub instruction_count: usize,
    /// Number of stack slots allocated by register allocation for spills.
    /// Not the sum of spill stores emitted — this counts distinct spill
    /// slots; each slot can be reused when spills don't overlap
    /// (`enable_spill_slot_reuse`).
    pub spill_slot_count: usize,
    /// Number of branch-terminator instructions (B, B.cond, CBZ, TBZ, BL
    /// for tail calls, RET). Used as a coarse branch-density proxy.
    pub branch_count: usize,
    /// x86-only low-cost opcode evidence from the final codegen instruction
    /// stream. Non-x86 targets leave this as zeroed/default.
    pub x86_machine_code: X86MachineCodeEvidence,
    /// AArch64 optional-ISA evidence captured from the final post-register-
    /// allocation machine stream. Non-AArch64 targets report `None`.
    pub aarch64_machine_code: Option<AArch64MachineCodeEvidence>,
    /// Phase timings captured during `prepare_function_with_metrics`.
    pub phase_timings: crate::pipeline::PhaseTimings,
    /// Existing static frame-layout observation, including explicit dynamic
    /// allocation/red-zone flags. `None` is unknown (including targets not yet
    /// reporting layouts), not zero and not a whole-call-stack bound.
    pub static_stack_frame: Option<crate::StaticStackFrameReport>,
    /// The U10 stack-limit acknowledgment for a function that requested a
    /// prologue check; `None` for every other function (and on targets with
    /// no stack-limit lowering, which refuse a request instead).
    pub stack_limit: Option<StackLimitFunctionSummary>,
}

/// The positive acknowledgment of one function's U10 stack-limit request
/// (`docs/u10-prologue-stack-limit.md` §6), from the `[TCG-A64-STACK-LIMIT]`
/// net's certificate on its final stream. A consumer that tagged a function
/// and finds no summary for it must treat the check as absent: a backend from
/// before U10 drops the tag as an unknown proof annotation.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StackLimitFunctionSummary {
    /// The function's symbol.
    pub name: String,
    /// The function requested a check (always true for a summary).
    pub requested: bool,
    /// `true`: the check is present and verified. `false`: the function has
    /// no stack storage and makes no non-tail call, and the elision is
    /// certified.
    pub checked: bool,
    /// Callee-saved bytes written before the check (0 when elided).
    pub csa: u32,
    /// The frame the check guarantees lies at or above the limit (0 when
    /// elided).
    pub total: u32,
    /// The overflow handler (`None` for a `Trap` request or an elision).
    pub handler: Option<String>,
    /// The handler's own frame depth, when the handler is in this module.
    pub handler_total: Option<u32>,
    /// The net's certificate.
    pub certificate: trust_cg_verify::aarch64_stack_limit::StackLimitCertificate,
}

/// Every U10 acknowledgment of one compile and the module reserve bound R
/// (`docs/u10-prologue-stack-limit.md` §5): reported on the JIT and AOT
/// results of any module in which some function requested a check.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StackLimitModuleReport {
    /// One summary per requesting function, in emission order.
    pub functions: Vec<StackLimitFunctionSummary>,
    /// The bound R between consecutive checks.
    pub bound: trust_cg_verify::aarch64_stack_limit::StackLimitModuleBound,
}

/// Build the U10 report from the final functions and their preparation
/// metrics (paired by position). `None` when no function requested a check.
pub(crate) fn aarch64_stack_limit_report(
    prepared: &[trust_cg_ir::MachFunction],
    certificates: &[Option<&trust_cg_verify::aarch64_stack_limit::StackLimitCertificate>],
    external_allowance: u64,
) -> Option<StackLimitModuleReport> {
    use trust_cg_verify::aarch64_stack_limit::{
        StackLimitOutcome, function_stack_facts, module_bound,
    };
    if certificates.iter().all(Option::is_none) {
        return None;
    }
    let facts: Vec<_> = prepared
        .iter()
        .zip(certificates)
        .map(|(func, certificate)| function_stack_facts(func, *certificate))
        .collect();
    let frame_of = |symbol: &str| {
        facts
            .iter()
            .find(|f| f.name == symbol)
            .and_then(|f| f.frame)
    };
    let functions = prepared
        .iter()
        .zip(certificates)
        .filter_map(|(func, certificate)| {
            let certificate = (*certificate)?;
            let (checked, csa, total, handler) = match &certificate.outcome {
                StackLimitOutcome::Checked(checked) => (
                    true,
                    checked.csa,
                    checked.total,
                    match &checked.overflow {
                        trust_cg_ir::StackLimitOverflow::Handler { symbol } => Some(symbol.clone()),
                        trust_cg_ir::StackLimitOverflow::Trap => None,
                    },
                ),
                StackLimitOutcome::Elided => (false, 0, 0, None),
            };
            Some(StackLimitFunctionSummary {
                name: func.name.clone(),
                requested: true,
                checked,
                csa,
                total,
                handler_total: handler.as_deref().and_then(frame_of),
                handler,
                certificate: certificate.clone(),
            })
        })
        .collect();
    Some(StackLimitModuleReport {
        functions,
        bound: module_bound(&facts, external_allowance),
    })
}

/// A single phase entry in a compilation trace.
#[derive(Debug, Clone)]
pub struct TraceEntry {
    /// Name of the compilation phase (e.g., "adapter", "isel", "regalloc").
    pub phase: String,
    /// Wall-clock duration of this phase.
    pub duration: Duration,
    /// Optional detail (e.g., function name being compiled).
    pub detail: Option<String>,
}

/// Compiler-level trace containing per-phase timing information.
///
/// Distinct from [`trust_cg_ir::CompilationTrace`] which is a thread-safe
/// structured event collector for instruction-level provenance.
/// This struct is a simple timing log for the compiler API.
#[derive(Debug, Clone, Default)]
pub struct CompilerTrace {
    /// Ordered list of phase entries.
    pub entries: Vec<TraceEntry>,
    /// Total wall-clock compilation time.
    pub total_duration: Duration,
}

/// A proof/export report for a single instruction lowering.
///
/// Successful entries record the result of verifying one instruction's
/// lowering against its proof obligation from the [`ProofDatabase`]. Entries
/// with `verified == false` are also surfaced for failed or unverified
/// verifier reports so downstream certified-output paths cannot
/// accidentally attest to a filtered subset of the function.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProofCertificate {
    /// Exact verifier-owned arithmetic theorem for export. This payload cannot
    /// replace independent replay or the compiler's final source/byte checks.
    #[cfg(feature = "verify")]
    pub source_bound_obligation: Option<trust_cg_verify::SourceBoundArithmeticObligation>,
    /// Name of the lowering rule, or a synthetic verifier-gap report id.
    pub rule_name: String,
    /// Whether the proof was successfully verified.
    pub verified: bool,
    /// Proof category (e.g., Arithmetic), or verifier-gap status.
    pub category: String,
    /// Verification strength achieved, or fail-closed gap detail.
    pub strength: String,
    /// Name of the function this instruction belongs to.
    pub function_name: String,
    /// When the function-verification request this entry came from had no AY
    /// bound: the note a proof-promotion refusal over this entry carries, that
    /// request's own `TCG-AY-IDENTITY-*` refusal, resolved once when the
    /// request was captured
    /// (`trust_cg_verify::FunctionVerificationRequest::ay_refusal_note`).
    /// `None` when an AY was bound, when the build records no AY, and for an
    /// entry no request produced. A refusal never resolves AY again for its
    /// note: under a cache path another user can re-point, a later resolution
    /// can differ from the one the evidence was produced under (X-HOST-P13
    /// fourth closure audit). A diagnostic only: part of no digest, cache key
    /// or verdict.
    pub ay_refusal_note: Option<String>,
}

/// Serializable metadata for a checker-validated certified pass chain.
///
/// This is intentionally a compact attachment rather than a pass execution
/// hook. Callers may supply an already validated
/// `trust_cg_verify::CertifiedPassChain`, or opt into the production
/// certified-pass execution slice when the `verify` feature is enabled.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CertifiedPassChainAttachment {
    /// Compilation unit shared by all pass certificates in the chain.
    pub compilation_unit: String,
    /// Validated entries in certificate order.
    pub entries: Vec<CertifiedPassChainEntryAttachment>,
}

impl CertifiedPassChainAttachment {
    #[cfg(feature = "verify")]
    fn from_checked_chain(
        chain: &trust_cg_verify::CertifiedPassChain,
    ) -> Result<Self, trust_cg_verify::CertifiedPassChainError> {
        chain.validate()?;

        let compilation_unit = chain.compilation_unit().to_string();
        let mut entries = Vec::with_capacity(chain.entries().len());
        for (entry_index, entry) in chain.entries().iter().enumerate() {
            let certificate_index = entry.certificate_index().ok_or(
                trust_cg_verify::CertifiedPassChainError::MissingCertificateField {
                    entry_index,
                    field: "chain.certificate_index",
                },
            )?;
            let pass_name = entry.pass_name().ok_or(
                trust_cg_verify::CertifiedPassChainError::MissingCertificateField {
                    entry_index,
                    field: "pass.name",
                },
            )?;
            let pass_version = required_attachment_certificate_string(
                &entry.request.certificate,
                &["pass", "version"],
                entry_index,
                "pass.version",
            )?;
            let pass_instance_id = required_attachment_certificate_string(
                &entry.request.certificate,
                &["pass", "instance_id"],
                entry_index,
                "pass.instance_id",
            )?;
            let provenance = required_attachment_certificate_value(
                &entry.request.certificate,
                &["provenance"],
                entry_index,
                "provenance",
            )?;
            let checker_kind = required_attachment_certificate_string(
                &entry.request.certificate,
                &["checker", "kind"],
                entry_index,
                "checker.kind",
            )?;
            let checker_name = required_attachment_certificate_string(
                &entry.request.certificate,
                &["checker", "name"],
                entry_index,
                "checker.name",
            )?;
            let checker_version = required_attachment_certificate_string(
                &entry.request.certificate,
                &["checker", "version"],
                entry_index,
                "checker.version",
            )?;
            let must_be_verified = required_attachment_certificate_bool(
                &entry.request.certificate,
                &["chain", "must_be_verified"],
                entry_index,
                "chain.must_be_verified",
            )?;
            let report = serde_json::to_value(&entry.report).map_err(|source| {
                trust_cg_verify::CertifiedPassChainError::TamperedReportSummary {
                    entry_index,
                    reason: format!("checker report JSON serialization failed: {source}"),
                }
            })?;
            let checker_status =
                required_attachment_report_string(&report, &["result", "status"], entry_index)?;
            let replay_mode =
                required_attachment_report_string(&report, &["replay", "mode"], entry_index)?;
            let replay_fail_closed =
                required_attachment_report_bool(&report, &["replay", "fail_closed"], entry_index)?;
            let replay_inputs = required_attachment_report_array(
                &report,
                &["replay", "replay_inputs"],
                entry_index,
            )?;
            let proof_artifact = report.get("proof_artifact").cloned();
            entries.push(CertifiedPassChainEntryAttachment {
                compilation_unit: compilation_unit.clone(),
                certificate_index,
                pass_name: pass_name.to_string(),
                pass_version: pass_version.to_string(),
                pass_instance_id: pass_instance_id.to_string(),
                obligation_hash: entry.request.obligation_hash.clone(),
                provenance,
                checker_kind: checker_kind.to_string(),
                checker_name: checker_name.to_string(),
                checker_version: checker_version.to_string(),
                checker_status,
                replay_mode,
                replay_fail_closed,
                replay_inputs,
                proof_artifact,
                must_be_verified,
                certificate: entry.request.certificate.clone(),
                report,
            });
        }

        Ok(Self {
            compilation_unit,
            entries,
        })
    }
}

#[cfg(feature = "verify")]
fn required_attachment_certificate_string<'a>(
    certificate: &'a serde_json::Value,
    path: &[&str],
    entry_index: usize,
    field: &'static str,
) -> Result<&'a str, trust_cg_verify::CertifiedPassChainError> {
    certificate_path(certificate, path)
        .and_then(serde_json::Value::as_str)
        .ok_or(
            trust_cg_verify::CertifiedPassChainError::MissingCertificateField {
                entry_index,
                field,
            },
        )
}

#[cfg(feature = "verify")]
fn required_attachment_certificate_bool(
    certificate: &serde_json::Value,
    path: &[&str],
    entry_index: usize,
    field: &'static str,
) -> Result<bool, trust_cg_verify::CertifiedPassChainError> {
    certificate_path(certificate, path)
        .and_then(serde_json::Value::as_bool)
        .ok_or(
            trust_cg_verify::CertifiedPassChainError::MissingCertificateField {
                entry_index,
                field,
            },
        )
}

#[cfg(feature = "verify")]
fn required_attachment_certificate_value(
    certificate: &serde_json::Value,
    path: &[&str],
    entry_index: usize,
    field: &'static str,
) -> Result<serde_json::Value, trust_cg_verify::CertifiedPassChainError> {
    certificate_path(certificate, path).cloned().ok_or(
        trust_cg_verify::CertifiedPassChainError::MissingCertificateField { entry_index, field },
    )
}

#[cfg(feature = "verify")]
fn certificate_path<'a>(
    certificate: &'a serde_json::Value,
    path: &[&str],
) -> Option<&'a serde_json::Value> {
    let mut cursor = certificate;
    for segment in path {
        cursor = cursor.get(*segment)?;
    }
    Some(cursor)
}

#[cfg(feature = "verify")]
fn required_attachment_report_string(
    report: &serde_json::Value,
    path: &[&str],
    entry_index: usize,
) -> Result<String, trust_cg_verify::CertifiedPassChainError> {
    report_path(report, path)
        .and_then(serde_json::Value::as_str)
        .map(str::to_string)
        .ok_or_else(|| attachment_report_missing(entry_index, path))
}

#[cfg(feature = "verify")]
fn required_attachment_report_bool(
    report: &serde_json::Value,
    path: &[&str],
    entry_index: usize,
) -> Result<bool, trust_cg_verify::CertifiedPassChainError> {
    report_path(report, path)
        .and_then(serde_json::Value::as_bool)
        .ok_or_else(|| attachment_report_missing(entry_index, path))
}

#[cfg(feature = "verify")]
fn required_attachment_report_array(
    report: &serde_json::Value,
    path: &[&str],
    entry_index: usize,
) -> Result<Vec<serde_json::Value>, trust_cg_verify::CertifiedPassChainError> {
    report_path(report, path)
        .and_then(serde_json::Value::as_array)
        .cloned()
        .ok_or_else(|| attachment_report_missing(entry_index, path))
}

#[cfg(feature = "verify")]
fn report_path<'a>(report: &'a serde_json::Value, path: &[&str]) -> Option<&'a serde_json::Value> {
    let mut cursor = report;
    for segment in path {
        cursor = cursor.get(*segment)?;
    }
    Some(cursor)
}

#[cfg(feature = "verify")]
fn attachment_report_missing(
    entry_index: usize,
    path: &[&str],
) -> trust_cg_verify::CertifiedPassChainError {
    trust_cg_verify::CertifiedPassChainError::TamperedReportSummary {
        entry_index,
        reason: format!("report.{} is missing or has the wrong type", path.join(".")),
    }
}

/// Serializable metadata for one checker-validated certified pass entry.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CertifiedPassChainEntryAttachment {
    /// Compilation unit declared by the validated chain.
    pub compilation_unit: String,
    /// Zero-based position declared by `certificate.chain.certificate_index`.
    pub certificate_index: u64,
    /// Pass identity declared by `certificate.pass.name`.
    pub pass_name: String,
    /// Pass implementation version declared by `certificate.pass.version`.
    #[serde(default)]
    pub pass_version: String,
    /// Stable pass instance id declared by `certificate.pass.instance_id`.
    #[serde(default)]
    pub pass_instance_id: String,
    /// Stable pass obligation hash agreed across request, certificate, and report.
    pub obligation_hash: String,
    /// Source/rewrite provenance declared by the validated certificate.
    #[serde(default)]
    pub provenance: serde_json::Value,
    /// Checker kind declared by `certificate.checker.kind`.
    #[serde(default)]
    pub checker_kind: String,
    /// Checker name declared by `certificate.checker.name`.
    #[serde(default)]
    pub checker_name: String,
    /// Checker version declared by `certificate.checker.version`.
    #[serde(default)]
    pub checker_version: String,
    /// Checker status reported by the replay result.
    #[serde(default)]
    pub checker_status: String,
    /// Replay mode reported by the checker.
    #[serde(default)]
    pub replay_mode: String,
    /// Fail-closed replay policy reported by the checker.
    #[serde(default)]
    pub replay_fail_closed: bool,
    /// Replay artifacts considered by the checker.
    #[serde(default)]
    pub replay_inputs: Vec<serde_json::Value>,
    /// Proof artifact identity selected by the checker report.
    #[serde(default)]
    pub proof_artifact: Option<serde_json::Value>,
    /// Whether this chain entry was required to be verified.
    #[serde(default)]
    pub must_be_verified: bool,
    /// Full `trust-cg.certified_pass.v1` certificate JSON.
    pub certificate: serde_json::Value,
    /// Full checker report JSON.
    pub report: serde_json::Value,
}

/// The result of compiling a trust_ir module through the Trust Codegen pipeline.
#[derive(Debug, Clone)]
pub struct CompilationResult {
    /// Object file bytes containing all compiled functions.
    ///
    /// The format is the target's: Mach-O for Apple triples, ELF for Linux
    /// triples, COFF for x86-64 Windows. Only an architecture-only request
    /// takes its OS, and so its format, from the host
    /// ([`TargetSelectionOrigin::HostDerived`]); an explicit triple with an
    /// unknown OS selects no format and is refused on every host.
    pub object_code: Vec<u8>,
    /// Actual AArch64 AOT frame-preparation inputs, in function order.
    /// Empty on other routes. These observations grant no frame, source-memory
    /// or execution proof; missing layouts remain explicitly unknown.
    pub aarch64_frame_inputs: Vec<crate::aot_frame_inputs::AotFrameLayoutObservation>,
    /// Compilation metrics.
    pub metrics: CompilationMetrics,
    /// Optional compiler trace (populated when trace_level != None).
    pub trace: Option<CompilerTrace>,
    /// Optional proof certificates (populated when emit_proofs is true).
    pub proofs: Option<Vec<ProofCertificate>>,
    /// Checker-validated certified pass chain supplied by the caller or
    /// produced through the non-default certified-pass execution path.
    pub certified_pass_chain: Option<CertifiedPassChainAttachment>,
    /// Proof-optimization certificate citations emitted by `trust-cg-opt` while
    /// preparing production codegen artifacts.
    pub proof_optimization_certificates: Vec<ProofOptimizationCertificateCitation>,
    /// Compile artifact cache telemetry emitted by production lookup/store paths.
    pub compile_artifact_cache_telemetry: Vec<CompileArtifactCacheTelemetry>,
    /// The target this object was compiled for and how it was chosen. A
    /// [`TargetSelectionOrigin::HostDerived`] record means the caller named
    /// only an architecture and the OS/ABI -- hence the object format and
    /// calling convention -- came from the host.
    pub target_selection: CompilerTargetSelection,
    /// Inline-only (`AvailableExternally`) bodies this object's code rests on:
    /// every body spliced is a DISCLOSED one-definition-rule premise — the
    /// body computes what the definition the linker binds its symbol to
    /// computes — not checked by this compile ([`crate::lir_module_prep`]);
    /// withheld bodies stayed calls to their symbols.
    pub inline_only_bodies: crate::lir_module_prep::InlineOnlyBodyEvidence,
    /// U10 stack-limit acknowledgments and the module reserve bound; `None`
    /// when no function requested a check.
    pub stack_limits: Option<StackLimitModuleReport>,
    /// The dialect legalization this object's module went through
    /// ([`crate::dialect_legalization`]): one receipt per legalized dialect
    /// op site and nominal type, naming the dialect, its version, the op or
    /// type, the rule applied and that rule's evidence class. `None` when the
    /// module carried no dialect construct.
    pub dialect_legalization: Option<DialectLegalizationReport>,
}

/// How a [`Compiler`]'s target OS/ABI was chosen.
///
/// The OS/ABI decides the object format (Mach-O, ELF, COFF) and the calling
/// convention (DarwinPCS vs AAPCS64, SysV vs Win64), so a host-derived choice
/// is a real authority decision, not a cosmetic default: it is recorded on
/// every [`CompilationResult`] and exposed by [`Compiler::target_selection`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TargetSelectionOrigin {
    /// The caller named the OS/ABI (a full triple or explicit components).
    Explicit,
    /// The caller named only an x86-64 or AArch64 architecture
    /// ([`Compiler::new`], or an architecture alias passed to
    /// [`Compiler::new_for_target_spec`]); the OS/ABI was derived from the
    /// host operating system `host_os` (`std::env::consts::OS`).
    HostDerived { host_os: &'static str },
    /// The caller named only the RISC-V architecture, which keeps the
    /// historical `riscv64-unknown-unknown` identity rather than the host's.
    ArchitectureDefault,
}

/// The effective target triple of a [`Compiler`] and how it was selected.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CompilerTargetSelection {
    /// The triple every lowering, ABI and object-format decision uses.
    pub triple: String,
    /// Whether the caller named it or it was derived.
    pub origin: TargetSelectionOrigin,
}

fn architecture_only_target_origin(architecture: Target) -> TargetSelectionOrigin {
    match architecture {
        Target::X86_64 | Target::Aarch64 => TargetSelectionOrigin::HostDerived {
            host_os: compiler_host_target_os(),
        },
        Target::Riscv64 => TargetSelectionOrigin::ArchitectureDefault,
    }
}

/// Native pointer size in bytes for the supported 64-bit targets.
///
/// trust-cg targets x86_64, aarch64, and riscv64 — all LP64/64-bit — so a
/// `Constant::SymbolAddr` element occupies 8 bytes. (No 32-bit target is
/// supported; if one is added, this must become target-derived.)
const GLOBAL_POINTER_SIZE: usize = 8;

/// Storage alignment (bytes, power of two >= 1) for a module global's object
/// section slot.
///
/// Prefers the trust-ir `Global.align` (an explicit `#[repr(align(N))]` / SIMD
/// over-alignment request the producer stamped); otherwise derives it from the
/// global's type layout (`align_bits`). Falls back to 1 when neither is known —
/// a byte blob is byte-aligned, and 1 never over-constrains a reader (the
/// section-offset alignment below only ever widens it). A non-power-of-two or
/// zero request is rejected here too: this public conversion can be called
/// independently of the full module validator.
fn object_global_align(
    module: &trust_ir::Module,
    global: &trust_ir::Global,
) -> Result<u32, PipelineError> {
    let typed_align =
        if aggregate_type_is_decomposable(&global.ty) && global.initializer.is_some() {
            Some(
                u32::try_from(global_init_layout(module, &global.name, &global.ty, 0)?.align)
                    .map_err(|_| {
                        global_initializer_error(
                            &global.name,
                            "initializer alignment exceeds object format",
                        )
                    })?,
            )
        } else {
            None
        };
    let raw = match global.align {
        // An EXPLICIT producer request is honored exactly (down to 1 — each
        // global self-aligns in the section, so a small-aligned static never
        // under-aligns a later strictly-aligned one).
        Some(a)
            if a == 0
                || !a.is_power_of_two()
                || typed_align.is_some_and(|required| a < required) =>
        {
            return Err(global_initializer_error(
                &global.name,
                "invalid or insufficient global alignment",
            ));
        }
        Some(a) => a,
        // No explicit request: derive from the type layout, but floor at the
        // pointer-size default (8). A producer that lowers a pointer- or
        // atomic-bearing const image to a flat `Array(U8, N)` erases its true
        // alignment to 1; the historical section default 8-aligned every such
        // global, and an under-aligned `AtomicUsize` image faults on AArch64
        // `ldxr`. The floor preserves that guarantee; a genuinely stricter
        // type-derived alignment (e.g. a 16-aligned struct) still wins.
        None => typed_align
            .or_else(|| {
                module
                    .ty_layout_shape(&global.ty)
                    .ok()
                    .and_then(|shape| shape.align_bits)
                    .and_then(|bits| u32::try_from(bits / 8).ok())
            })
            .unwrap_or(0)
            .max(GLOBAL_POINTER_SIZE as u32),
    };
    Ok(raw)
}

/// Environment variable under which the compiler's AArch64 JIT links its
/// prepared functions unsealed: the encoder then runs every function's
/// final-stream check a second time, as before sealing. The emitted bytes are
/// the same either way; this is the same-binary switch for measuring the
/// saving, and a kill switch.
pub const SEALED_JIT_LINK_KILL_SWITCH: &str = "TCG_NO_SEALED_JIT_LINK";

/// [`SEALED_JIT_LINK_KILL_SWITCH`], read through the thread-scoped override
/// layer like every `TCG_*` control.
fn sealed_jit_link_disabled() -> bool {
    crate::env_lock::var_os(SEALED_JIT_LINK_KILL_SWITCH).is_some()
}

/// Encode the module globals carried by a validated Trust-IR module into the
/// exact object-emitter representation used by Compiler.
///
/// This is the single canonical conversion boundary for both the standalone
/// Trust Codegen compiler and rustc's Trust-IR-first bridge. Keeping it public
/// prevents the bridge from growing a second initializer/layout/relocation
/// implementation that could disagree with the emitter it ultimately calls.
///
/// Every unsupported initializer, layout, alignment, linkage, or relocation
/// shape is returned as PipelineError; callers must not drop a failed global
/// and continue with function-only emission.
pub fn module_object_globals(
    module: &trust_ir::Module,
) -> Result<Vec<ObjectGlobal>, PipelineError> {
    // Target byte order for multi-byte scalar initializers. Both supported
    // targets (x86_64, aarch64) are little-endian, so a module that declines to
    // declare its target (`target_info: None`) is treated as little-endian; an
    // explicitly big-endian module fails closed on multi-byte emission below,
    // since no supported backend exercises that byte order.
    let endian = module
        .target_info
        .as_ref()
        .map(|t| t.endianness)
        .unwrap_or(trust_ir::Endianness::Little);
    module
        .globals
        .iter()
        // The reserved EH type table binds landing-pad catch type indices to
        // typeinfo symbols. The lowering adapter consumes it and the LSDA
        // emitter relocates the symbols it names directly; the table is a
        // compiler input, not an object definition.
        .filter(|global| global.name != trust_cg_lower::function::EH_TYPE_TABLE_GLOBAL)
        .map(|global| {
            // Thread-local globals route to the target's TLS object sections.
            // On AArch64 Mach-O (Darwin) a thread-local lowers to the dynamic TLV
            // model: an initial-value template in `__thread_data` plus a
            // `tlv_descriptor` in `__thread_vars` that the read addresses via
            // `ARM64_RELOC_TLVP_LOAD_PAGE21`/`PAGEOFF12`. We carry only an
            // `is_thread_local` flag here; the target object emitter owns the
            // descriptor/template sections. AArch64 ELF definitions instead use
            // `.tdata` (all-zero templates: SHT_NOBITS `.tbss`) with declared
            // alignment and STT_TLS symbols; imports are undefined STT_TLS
            // references, not another template definition.
            //
            // On DARWIN, trust-ir TLS models collapse to the TLV descriptor for
            // AOT object emission: the adapter's `translate_global_addr` lowers
            // a Darwin `GlobalAddr` of a TLS
            // global to `Opcode::TlsRef { model: Tlv, local_exec_offset: None }`,
            // i.e. a `tlv_get_addr` through a `__thread_vars` descriptor. Mach-O
            // has no distinct local-exec object ABI — clang lowers `_Thread_local`
            // to TLV regardless — so a `LocalExec`-marked global (the JIT's fast
            // static model, which the AOT read never uses) MUST also become a TLV
            // descriptor for its read to resolve. Admitting it here is therefore
            // required for consistency, not a relaxation: it flows through the same
            // `is_thread_local` descriptor path as the dynamic models below.
            // ELF read-side model selection is separate: the relocation model
            // selects local-exec/initial-exec (executables) or TLSDESC (`pic`).
            let is_thread_local = global.tls.is_some();
            // Mirror the trust-ir linkage to the object symbol's binding,
            // EXHAUSTIVELY (a new `Linkage` kind must be classified here before
            // it compiles): `(is_external, is_weak, always_import)`.
            //
            // External / weak / link-once are exported (resolvable from another
            // object); Internal / Private stay module-local. A `MonoItem::Static`
            // emitted under its own symbol relies on this to be linkable.
            //
            // A `Weak` / `LinkOnce` DEFINITION — and, since trust-ir v41, its
            // one-definition-rule twins `WeakOdr` / `LinkOnceOdr` — is emitted
            // with the Mach-O `N_WEAK_DEF` / ELF `STB_WEAK` flag so that multiple
            // objects each defining the symbol COALESCE to one at link time
            // instead of a duplicate-strong-definition error. This is only
            // applied to an actual definition below (the import arms keep strong
            // undefined references, exactly as today).
            //
            // `AvailableExternally` (v41) is NEVER emitted as a definition, with
            // or without an initializer: the definition lives elsewhere, so it is
            // a cross-object import here. `ExternalWeak` (v41) is a WEAK import
            // (`is_import && is_weak`): only an initializer-less, non-TLS global
            // is a weak declaration. Only the AArch64 ELF emitters spell it
            // (`STB_WEAK` undefined); every other object path refuses a weak
            // import rather than emit a strong reference in place of
            // null-on-missing semantics.
            let (is_external, is_weak, always_import) = match global.linkage {
                trust_ir::Linkage::External => (true, false, false),
                trust_ir::Linkage::Weak
                | trust_ir::Linkage::LinkOnce
                | trust_ir::Linkage::WeakOdr
                | trust_ir::Linkage::LinkOnceOdr => (true, true, false),
                trust_ir::Linkage::Internal | trust_ir::Linkage::Private => (false, false, false),
                trust_ir::Linkage::AvailableExternally => (true, false, true),
                trust_ir::Linkage::ExternalWeak if global.initializer.is_some() => {
                    return Err(PipelineError::ObjectEmission(format!(
                        "trust-ir global {} unsupported: linkage `external_weak` (trust-ir v41) is a weak declaration, but the global carries an initializer (fail-closed)",
                        global.name
                    )));
                }
                trust_ir::Linkage::ExternalWeak if is_thread_local => {
                    return Err(PipelineError::ObjectEmission(format!(
                        "trust-ir global {} unsupported: a thread-local `external_weak` (trust-ir v41) needs a weak undefined TLS reference, which no object emitter spells (fail-closed)",
                        global.name
                    )));
                }
                trust_ir::Linkage::ExternalWeak => (true, true, true),
            };
            // Weakness of a REFERENCE: only `ExternalWeak` imports are weak;
            // every other import stays a strong undefined reference.
            let is_weak_import = global.linkage == trust_ir::Linkage::ExternalWeak;
            // A COMDAT definition (the link-once / one-definition-rule weak
            // forms) is placed in its own section inside a `GRP_COMDAT` group
            // on ELF, so the linker keeps one copy of its BYTES; plain `Weak`
            // stays an ordinary weak definition. Only meaningful for a
            // definition: the import arms below clear it.
            let comdat = matches!(
                global.linkage,
                trust_ir::Linkage::LinkOnce
                    | trust_ir::Linkage::LinkOnceOdr
                    | trust_ir::Linkage::WeakOdr
            );
            let is_import = always_import
                || (global.initializer.is_none() && (is_thread_local || is_external));
            // An import's visibility and `#[used]` retention (a declaration
            // LLVM lists in `@llvm.used`) ride on its `ObjectGlobal`, and each
            // object path decides them. The AArch64 ELF emitters spell the
            // visibility on the undefined symbol; every other object path
            // refuses a non-default one (the adapter's
            // `DataImportVisibilityPolicy`, then
            // `validate_aarch64_object_globals_with` and the x86-64 emission's
            // `ImportVisibilityUnsupported`). The AArch64 and x86-64 ELF
            // emitters write nothing for the retention, as llc's ELF writer
            // does, and so does the RISC-V path, which emits no module data;
            // the Mach-O, COFF, JIT and Wasm paths refuse a retained import
            // (llc's Mach-O writer gives it an `N_NO_DEAD_STRIP` undefined
            // symbol, its COFF writer a `/INCLUDE:` directive, even when
            // nothing references it). See `ObjectGlobal::retained`.
            // trust-ir v41 `Global.section` is a DEFINITION attribute: the
            // target object emitter honors or refuses it by name (see
            // `crate::object_sections`). An import places no bytes here, so a
            // section on it could only be dropped — refuse instead.
            if is_import && let Some(section) = &global.section {
                return Err(PipelineError::ExplicitSectionUnsupported {
                    global: global.name.clone(),
                    section: section.clone(),
                    format: "object",
                    code: crate::object_sections::SectionRefusal::Import,
                    reason: "a cross-object import places no bytes in this object".to_string(),
                });
            }
            // Storage alignment for this global's section slot (explicit
            // `Global.align`, else type-derived). Imports carry no bytes, but
            // the field is set uniformly for a stable ObjectGlobal shape.
            let align = object_global_align(module, global)?;

            // An initializer-less THREAD-LOCAL global is a cross-object IMPORT: a
            // reference to a `tlv_descriptor` DEFINED in another object. It
            // contributes no descriptor / template section bytes here (which would
            // be a duplicate definition of the program-wide thread-local); its
            // sole effect is that the `__text` TLVP relocation resolves to an
            // undefined-external symbol the linker satisfies from the defining
            // object. See `ObjectGlobal::is_import`.
            //
            // Such an import is ALWAYS emitted External, regardless of the
            // trust-ir linkage the producer stamped. Unlike a non-TLS global (an
            // initializer-less Internal/Private one is a valid zero-fill BSS
            // DEFINITION — handled below), a thread-local has NO zero-fill
            // definition path in this model: a TLS definition is only expressible
            // through the TLV descriptor + init-value template, which requires an
            // initializer. So an initializer-less TLS global cannot be a
            // definition — its only coherent meaning is an import — and an import
            // is necessarily External (a module-local Internal/Private symbol with
            // no bytes here cannot be satisfied by another object). The
            // Internal/Private linkage the frontend stamps on such a bodyless TLS
            // REFERENCE (e.g. the monomorphized `RandomState::new::KEYS`
            // thread-local, defined in std and merely read here) is a
            // classification artifact of carrying a static's own-symbol linkage
            // onto a mere reference, not a real request for module-local storage.
            // Promoting it to an External import is fail-closed: were it ever
            // genuinely meant to be defined here, the unresolved undefined-external
            // surfaces as a LINK-TIME error, never a silently wrong TLS value.
            // DEFINITIONS (initializer present) and non-TLS globals are untouched.
            if is_thread_local && (always_import || global.initializer.is_none()) {
                return Ok(ObjectGlobal {
                    name: global.name.clone(),
                    data: Vec::new(),
                    mutable: global.mutable,
                    is_external: true,
                    symbol_refs: Vec::new(),
                    is_thread_local: true,
                    is_import: true,
                    // An import is a strong undefined reference (not a weak def).
                    is_weak: false,
                    align,
                    visibility: global.visibility,
                    retained: global.retained,
                    section: None,
                    comdat: false,
                });
            }

            // An initializer-less NON-thread-local global with External linkage is a
            // plain cross-object DATA IMPORT: a reference to a `static` (e.g. a
            // `static mut`) DEFINED in another object. Like the TLS import above it
            // contributes no section bytes here; the data relocation resolves to the
            // undefined-external symbol the linker satisfies from the defining object.
            if !is_thread_local && (always_import || (global.initializer.is_none() && is_external))
            {
                return Ok(ObjectGlobal {
                    name: global.name.clone(),
                    data: Vec::new(),
                    mutable: global.mutable,
                    is_external: true,
                    symbol_refs: Vec::new(),
                    is_thread_local: false,
                    is_import: true,
                    // A strong undefined reference, or a weak one for
                    // `ExternalWeak` (never a weak DEFINITION).
                    is_weak: is_weak_import,
                    align,
                    visibility: global.visibility,
                    retained: global.retained,
                    section: None,
                    comdat: false,
                });
            }

            // An INITIALIZER-LESS internal/private global is a zero-initialized
            // (BSS) static. (The external/import cases returned above; a TLS
            // no-initializer symbol is handled — and an internal one rejected —
            // earlier.) Emit `size` zero bytes: the object emitter decides the
            // zero-fill placement (ELF puts writable all-zero definitions in
            // SHT_NOBITS `.bss`; Mach-O keeps them in `__DATA,__data`, which the
            // loader observes as the same zeroed image). Either way the symbol
            // stays a real in-object definition other objects can bind to. The
            // size is the type's canonical layout;
            // if it is not computable we FAIL CLOSED rather than emit a
            // wrong-sized (overlapping / truncated) symbol.
            let initializer = match global.initializer.as_ref() {
                Some(init) => init,
                None => {
                    let size = module
                        .ty_layout_shape(&global.ty)
                        .ok()
                        .and_then(|shape| shape.size_bytes())
                        .ok_or_else(|| {
                            PipelineError::ObjectEmission(format!(
                                "trust-ir global {} unsupported: initializer is missing and its type {:?} has no computable layout size for a BSS/zero-fill definition",
                                global.name, global.ty
                            ))
                        })?;
                    return Ok(ObjectGlobal {
                        name: global.name.clone(),
                        data: vec![0u8; size as usize],
                        mutable: global.mutable,
                        is_external,
                        symbol_refs: Vec::new(),
                        is_thread_local,
                        is_import: false,
                        is_weak,
                        align,
                        visibility: global.visibility,
                        retained: global.retained,
                        section: global.section.clone(),
                        comdat,
                    });
                }
            };
            let (data, symbol_refs) =
                trust_ir_global_initializer_data(module, global, initializer, endian)?;
            Ok(ObjectGlobal {
                name: global.name.clone(),
                data,
                mutable: global.mutable,
                is_external,
                symbol_refs,
                is_thread_local,
                is_import: false,
                // Weak only applies to a DEFINITION; coalesced across objects.
                is_weak,
                align,
                visibility: global.visibility,
                retained: global.retained,
                section: global.section.clone(),
                comdat,
            })
        })
        .collect()
}

/// Lower a global's initializer to its raw data bytes plus any embedded
/// symbol-address relocations.
///
/// A `Constant::Aggregate`'s `Constant::Int` elements are laid out at their
/// DECLARED element WIDTH, taken from the global's aggregate `Ty`:
///
/// * When the global type DECOMPOSES into per-position element types — an
///   `Array`/`Tuple`/`Struct`/`Vector` — each `Int` element occupies the byte
///   width of its element type (a `Usize`/`U64`/`Ptr` slot is 8 bytes, a `U32`
///   slot 4, a `U8` slot 1). This is what keeps a Rust vtable's pointer-word
///   `drop`/`size`/`align` slots at their natural width so the following
///   method-pointer `SymbolAddr` relocations land at pointer-aligned offsets
///   (the historic 1-byte-per-`Int` layout shoved them off alignment — `ld:
///   pointer not aligned`). If an element's width is not computable from the
///   type (an unresolved element type, or a non-scalar element type) the global
///   FAILS CLOSED rather than emit a wrong-width, misaligning slot.
/// * When the global type is a SCALAR/opaque type (`I64`/`I32`/`Ptr`/…) that
///   does not decompose, the aggregate is the historic flat BYTE IMAGE: one
///   literal byte (range-checked to `u8`) per `Int` element — how a producer
///   spells a pointer-width scalar global as its little-endian byte sequence.
///
/// For each `Constant::SymbolAddr` element the layout is width-independent:
/// [`GLOBAL_POINTER_SIZE`] zero bytes plus a [`crate::pipeline::GlobalSymbolRef`]
/// recorded at that offset (the linker fills in the address via a data
/// relocation). This is what places a function/data address inside a vtable or
/// `static FNS: [fn(); N]`. Scalar `U8`/`I8`/`Bool` initializers contribute
/// their single byte and carry no relocations.
///
/// Fail-closed: every other initializer or aggregate-element shape returns an
/// `Err` so an unsupported global is never silently miscompiled into wrong
/// bytes (nor silently dropped — see the `module_object_globals_fail_closed_*`
/// tests).
/// Byte width and signedness of a scalar integer `Ty`, or `None` for a
/// non-integer type.
fn integer_ty_width_signed(ty: &trust_ir::Ty) -> Option<(usize, bool)> {
    Some(match ty {
        trust_ir::Ty::I8 => (1, true),
        trust_ir::Ty::I16 => (2, true),
        trust_ir::Ty::I32 => (4, true),
        trust_ir::Ty::I64 => (8, true),
        trust_ir::Ty::I128 => (16, true),
        trust_ir::Ty::U8 => (1, false),
        trust_ir::Ty::U16 => (2, false),
        trust_ir::Ty::U32 => (4, false),
        trust_ir::Ty::U64 => (8, false),
        trust_ir::Ty::U128 => (16, false),
        _ => return None,
    })
}

/// Encode a scalar integer initializer as `width` target-endian bytes.
///
/// The literal is range-checked against the declared type first, so truncating
/// the `i128` to `width` bytes never silently drops information. The bytes are
/// the two's-complement little-endian encoding (identical for signed and
/// unsigned values that are in range) -- bit-for-bit what clang emits for the
/// same typed global. Big-endian multi-byte emission is refused because no
/// supported target exercises it.
fn scalar_int_initializer_bytes(
    name: &str,
    ty: &trust_ir::Ty,
    value: i128,
    width: usize,
    signed: bool,
    endian: trust_ir::Endianness,
) -> Result<Vec<u8>, PipelineError> {
    let in_range = if signed {
        // Every 16-byte signed value fits an i128.
        width == 16 || {
            let bits = (width * 8) as u32;
            let min = -(1i128 << (bits - 1));
            let max = (1i128 << (bits - 1)) - 1;
            value >= min && value <= max
        }
    } else {
        value >= 0
            && (width == 16 || {
                let bits = (width * 8) as u32;
                (value as u128) < (1u128 << bits)
            })
    };
    if !in_range {
        return Err(PipelineError::ObjectEmission(format!(
            "trust-ir global {name} unsupported: scalar initializer value {value} is outside {ty:?} range",
        )));
    }
    if *ty == trust_ir::Ty::Char && char::from_u32(value as u32).is_none() {
        return Err(global_initializer_error(
            name,
            "initializer is not a Unicode scalar value",
        ));
    }
    scalar_uint_bits_bytes(name, (value as u128) & width_mask(width), width, endian)
}

/// Low `width` bytes of `bits` in `endian` order. Big-endian multi-byte
/// emission fails closed (unverified on the supported little-endian targets).
fn scalar_uint_bits_bytes(
    name: &str,
    bits: u128,
    width: usize,
    endian: trust_ir::Endianness,
) -> Result<Vec<u8>, PipelineError> {
    if matches!(endian, trust_ir::Endianness::Big) && width > 1 {
        return Err(PipelineError::ObjectEmission(format!(
            "trust-ir global {name} unsupported: big-endian multi-byte scalar emission is not verified for any supported target",
        )));
    }
    Ok(bits.to_le_bytes()[..width].to_vec())
}

/// Mask selecting the low `width` bytes (`width` in 1..=16).
fn width_mask(width: usize) -> u128 {
    if width >= 16 {
        u128::MAX
    } else {
        (1u128 << (width * 8)) - 1
    }
}

/// Whether a global's declared `Ty` DECOMPOSES into per-position element types,
/// so an aggregate `Int` element can be laid out at its declared element width
/// (a vtable slot). A scalar/opaque type does not decompose; its aggregate
/// initializer is the historic flat byte image instead.
fn aggregate_type_is_decomposable(ty: &trust_ir::Ty) -> bool {
    matches!(
        ty,
        trust_ir::Ty::Array(..)
            | trust_ir::Ty::Tuple(..)
            | trust_ir::Ty::Struct(..)
            | trust_ir::Ty::Vector(..)
            | trust_ir::Ty::Enum(..)
            | trust_ir::Ty::Record(..)
    )
}

/// Byte width and signedness of the SCALAR element type an aggregate
/// `Constant::Int` element occupies, or `None` if the element type is not a
/// scalar with a fixed layout width (so the caller fails closed rather than
/// emit a wrong-width slot).
///
/// Integer types use their fixed width; `Isize`/`Usize` and every
/// pointer-shaped element type (`Ptr`, `&T`/`&mut T`, `*const/*mut T`, `Rc<T>`,
/// a function pointer) use the target pointer width — a vtable's
/// `drop`/`size`/`align`/method slots are all one pointer word wide; `Char` is
/// the 4-byte Unicode scalar carrier.
fn aggregate_int_element_width_signed(ty: &trust_ir::Ty) -> Option<(usize, bool)> {
    if let Some(width_signed) = integer_ty_width_signed(ty) {
        return Some(width_signed);
    }
    Some(match ty {
        trust_ir::Ty::Isize => (GLOBAL_POINTER_SIZE, true),
        trust_ir::Ty::Usize => (GLOBAL_POINTER_SIZE, false),
        trust_ir::Ty::Char => (4, false),
        trust_ir::Ty::Ptr
        | trust_ir::Ty::Ref(_)
        | trust_ir::Ty::RefMut(_)
        | trust_ir::Ty::PtrConst(_)
        | trust_ir::Ty::PtrMut(_)
        | trust_ir::Ty::Rc(_)
        | trust_ir::Ty::Func(_) => (GLOBAL_POINTER_SIZE, false),
        _ => return None,
    })
}

/// A typed initializer uses the SAME layout authority as aggregate loads and
/// stores. An array keeps one element layout, not `len` copies of a type tree.
struct GlobalInitLayout<'a> {
    ty: &'a trust_ir::Ty,
    size: usize,
    align: usize,
    shape: GlobalInitShape<'a>,
}

enum GlobalInitShape<'a> {
    Scalar,
    Fields(Vec<(usize, GlobalInitLayout<'a>)>),
    /// A `Ty::Record` (L05-P5): positional fields at the natural-C offsets of
    /// the LIR struct the byte path lays the record out as, plus the declared
    /// field names so a `Constant::Record` initializer can be put in
    /// declaration order.
    Record {
        fields: Vec<(usize, GlobalInitLayout<'a>)>,
        names: Vec<&'a str>,
    },
    Repeated {
        len: usize,
        element: Box<GlobalInitLayout<'a>>,
    },
    /// A direct-tag `Ty::Enum` (L05-P5): the tag lane at `tag_offset`, of the
    /// enum's canonical tag type, and each variant's fields at the offsets of
    /// the same [`trust_cg_lower::direct_enum::DirectEnumImage`] the code
    /// path addresses. The initializer's head names the variant by its
    /// effective DISCRIMINANT VALUE (trust-ir's contract), never by index.
    Enum {
        tag_offset: usize,
        tag_ty: trust_ir::Ty,
        tag_width: usize,
        tag_signed: bool,
        discriminants: Vec<i128>,
        variants: Vec<Vec<(usize, GlobalInitLayout<'a>)>>,
    },
}

fn global_initializer_error(name: &str, reason: impl std::fmt::Display) -> PipelineError {
    PipelineError::ObjectEmission(format!("trust-ir global {name} unsupported: {reason}"))
}

fn scalar_layout_in_aggregate_path(name: &str) -> PipelineError {
    global_initializer_error(name, "scalar layout reached the aggregate initializer path")
}

fn enum_layout_in_aggregate_path(name: &str) -> PipelineError {
    global_initializer_error(
        name,
        "enum layout reached the positional aggregate initializer path",
    )
}

/// Every payload field of a direct-tag enum variant, laid out for the global
/// image at the offsets the [`trust_cg_lower::direct_enum::DirectEnumImage`]
/// states. Each child's own extent must be the image's extent for that field
/// (the code path copies exactly that many bytes), must stay inside the
/// image, and must overlap neither the tag lane nor a sibling.
fn global_enum_variant_layout<'a>(
    module: &'a trust_ir::Module,
    name: &str,
    fields: &[trust_cg_lower::direct_enum::DirectEnumField],
    field_tys: &'a [trust_ir::Ty],
    size: usize,
    tag_lane: (usize, usize),
    depth: usize,
) -> Result<Vec<(usize, GlobalInitLayout<'a>)>, PipelineError> {
    if fields.len() != field_tys.len() {
        return Err(global_initializer_error(
            name,
            "enum image and enum definition disagree on a variant's field count",
        ));
    }
    let overlaps = |a: usize, a_len: usize, b: usize, b_len: usize| {
        a_len != 0 && b_len != 0 && a < b.saturating_add(b_len) && b < a.saturating_add(a_len)
    };
    let mut laid: Vec<(usize, GlobalInitLayout<'a>)> = Vec::with_capacity(fields.len());
    for (field, field_ty) in fields.iter().zip(field_tys) {
        let child = global_init_layout(module, name, field_ty, depth + 1)?;
        let offset = usize::try_from(field.offset).map_err(|_| {
            global_initializer_error(name, "enum field offset exceeds host address space")
        })?;
        if u64::try_from(child.size).ok() != Some(field.extent) {
            return Err(global_initializer_error(
                name,
                format!(
                    "enum field emitted layout ({} bytes) disagrees with the enum image ({} bytes)",
                    child.size, field.extent
                ),
            ));
        }
        if !offset.is_multiple_of(child.align)
            || offset.checked_add(child.size).is_none_or(|end| end > size)
        {
            return Err(global_initializer_error(
                name,
                "enum field offset is misaligned or exceeds the enum image",
            ));
        }
        if overlaps(tag_lane.0, tag_lane.1, offset, child.size) {
            return Err(global_initializer_error(
                name,
                "enum field overlaps the tag lane",
            ));
        }
        for (previous_offset, previous) in &laid {
            if overlaps(*previous_offset, previous.size, offset, child.size) {
                return Err(global_initializer_error(
                    name,
                    "overlapping enum variant fields",
                ));
            }
        }
        laid.push((offset, child));
    }
    Ok(laid)
}

fn global_init_layout<'a>(
    module: &'a trust_ir::Module,
    name: &str,
    ty: &'a trust_ir::Ty,
    depth: usize,
) -> Result<GlobalInitLayout<'a>, PipelineError> {
    use trust_cg_lower::declared_layout::{LayoutTables, emitted_struct_layout};
    use trust_ir::Ty;
    if depth >= 128 {
        return Err(global_initializer_error(
            name,
            "initializer type nesting exceeds 128",
        ));
    }
    let size_align = |size: u64, align: u64| -> Result<(usize, usize), PipelineError> {
        if size > u64::from(u32::MAX) || align == 0 || !align.is_power_of_two() {
            return Err(global_initializer_error(
                name,
                "unrepresentable initializer layout",
            ));
        }
        Ok((
            size as usize,
            usize::try_from(align).map_err(|_| {
                global_initializer_error(name, "initializer alignment exceeds host address space")
            })?,
        ))
    };
    let (size, align, shape) = match ty {
        Ty::Struct(id) => {
            let sdef = module
                .struct_def(*id)
                .ok_or_else(|| global_initializer_error(name, format!("missing struct {id:?}")))?;
            let tables = LayoutTables {
                structs: &module.structs,
                types: &module.types,
                enums: &module.enums,
                records: &module.records,
                closures: &module.closure_types,
            };
            let layout = emitted_struct_layout(sdef, tables)
                .map_err(|error| global_initializer_error(name, error))?;
            // Do not allow the code path's natural-C fallback to erase an
            // incomplete, incoherent or differently-sized producer layout.
            let stated = sdef.size.is_some()
                || sdef.align.is_some()
                || sdef.fields.iter().any(|field| field.offset.is_some());
            if stated
                && (sdef.size != Some(layout.size)
                    || sdef.align != Some(layout.align)
                    || sdef
                        .fields
                        .iter()
                        .zip(&layout.offsets)
                        .any(|(field, offset)| field.offset != Some(*offset)))
            {
                return Err(global_initializer_error(
                    name,
                    "declared struct layout is incomplete or disagrees with emitted layout",
                ));
            }
            let (size, align) = size_align(layout.size, layout.align)?;
            let clamp = match sdef.repr {
                trust_ir::StructRepr::Packed(n) if n != 0 && n.is_power_of_two() => n as usize,
                trust_ir::StructRepr::Packed(_) => {
                    return Err(global_initializer_error(name, "invalid packed alignment"));
                }
                _ => usize::MAX,
            };
            let mut fields = Vec::with_capacity(sdef.fields.len());
            for (field, offset) in sdef.fields.iter().zip(layout.offsets) {
                let child = global_init_layout(module, name, &field.ty, depth + 1)?;
                let offset = usize::try_from(offset).map_err(|_| {
                    global_initializer_error(name, "field offset exceeds host address space")
                })?;
                let field_align = child.align.min(clamp);
                if !offset.is_multiple_of(field_align)
                    || field_align > align
                    || offset.checked_add(child.size).is_none_or(|end| end > size)
                {
                    return Err(global_initializer_error(
                        name,
                        "invalid declared field alignment or extent",
                    ));
                }
                for (previous_offset, previous) in &fields {
                    let previous: &GlobalInitLayout<'_> = previous;
                    if child.size != 0
                        && previous.size != 0
                        && offset < previous_offset + previous.size
                        && *previous_offset < offset + child.size
                    {
                        return Err(global_initializer_error(
                            name,
                            "overlapping declared initializer fields",
                        ));
                    }
                }
                fields.push((offset, child));
            }
            (size, align, GlobalInitShape::Fields(fields))
        }
        Ty::Tuple(types) => {
            if let Some(declared) = module
                .tuple_layout_descriptor(ty)
                .map_err(|error| global_initializer_error(name, error))?
            {
                // Canonical validation checks target, field count, overlap,
                // alignment and bounds. Never silently replace producer order
                // with the adapter's natural-C compatibility layout.
                module
                    .ty_layout_shape(ty)
                    .map_err(|error| global_initializer_error(name, error))?;
                let (size, align) = size_align(declared.size, declared.align)?;
                let mut fields = Vec::with_capacity(types.len());
                for (field, offset) in types.iter().zip(&declared.field_offsets) {
                    let child = global_init_layout(module, name, field, depth + 1)?;
                    let canonical = module
                        .ty_layout_shape(field)
                        .map_err(|error| global_initializer_error(name, error))?;
                    if canonical.size_bytes() != Some(child.size as u64)
                        || canonical.align_bits != Some(child.align as u64 * 8)
                    {
                        return Err(global_initializer_error(
                            name,
                            "tuple child emitted layout disagrees with canonical layout",
                        ));
                    }
                    let offset = usize::try_from(*offset).map_err(|_| {
                        global_initializer_error(name, "tuple offset exceeds host address space")
                    })?;
                    fields.push((offset, child));
                }
                return Ok(GlobalInitLayout {
                    ty,
                    size,
                    align,
                    shape: GlobalInitShape::Fields(fields),
                });
            }
            // Without a descriptor retain the explicit natural-C compatibility
            // policy, including its existing vtable lane.
            let lir = trust_cg_lower::adapter::translate_type_with_tables(
                ty,
                &module.structs,
                &module.types,
            )
            .map_err(|error| global_initializer_error(name, error))?;
            let (size, align) = size_align(u64::from(lir.bytes()), u64::from(lir.align()))?;
            let fields = types
                .iter()
                .enumerate()
                .map(|(index, field)| {
                    let offset = lir
                        .offset_of(index)
                        .ok_or_else(|| global_initializer_error(name, "missing tuple offset"))?
                        as usize;
                    let child = global_init_layout(module, name, field, depth + 1)?;
                    if offset.checked_add(child.size).is_none_or(|end| end > size) {
                        return Err(global_initializer_error(
                            name,
                            "tuple field exceeds emitted extent",
                        ));
                    }
                    Ok((offset, child))
                })
                .collect::<Result<Vec<_>, PipelineError>>()?;
            (size, align, GlobalInitShape::Fields(fields))
        }
        Ty::Array(id, len) => {
            let elem = module
                .ty(*id)
                .ok_or_else(|| global_initializer_error(name, "missing array element type"))?;
            let element = global_init_layout(module, name, elem, depth + 1)?;
            let size = (element.size as u64).checked_mul(*len).ok_or_else(|| {
                global_initializer_error(name, "array initializer extent overflow")
            })?;
            let (size, align) = size_align(size, element.align as u64)?;
            let len = usize::try_from(*len).map_err(|_| {
                global_initializer_error(name, "array count exceeds host address space")
            })?;
            (
                size,
                align,
                GlobalInitShape::Repeated {
                    len,
                    element: Box::new(element),
                },
            )
        }
        Ty::Vector(elem, lanes) => {
            if !matches!(
                elem.as_ref(),
                Ty::I8
                    | Ty::I16
                    | Ty::I32
                    | Ty::I64
                    | Ty::U8
                    | Ty::U16
                    | Ty::U32
                    | Ty::U64
                    | Ty::F16
                    | Ty::F32
                    | Ty::F64
            ) {
                return Err(global_initializer_error(
                    name,
                    "unsupported short-vector lane type",
                ));
            }
            let element = global_init_layout(module, name, elem, depth + 1)?;
            if !matches!(element.shape, GlobalInitShape::Scalar) {
                return Err(global_initializer_error(name, "non-scalar vector element"));
            }
            let size = (element.size as u64)
                .checked_mul(u64::from(*lanes))
                .ok_or_else(|| {
                    global_initializer_error(name, "vector initializer extent overflow")
                })?;
            // The admitted short-vector carrier has vector-width alignment,
            // unlike the scalar-lane alignment in TrustIR's generic shape.
            if size != 8 && size != 16 {
                return Err(global_initializer_error(
                    name,
                    "only 64/128-bit vector global layouts are admitted",
                ));
            }
            (
                size as usize,
                size as usize,
                GlobalInitShape::Repeated {
                    len: *lanes as usize,
                    element: Box::new(element),
                },
            )
        }
        Ty::Record(rid) => {
            // Records are structurally-typed labeled tuples with no producer
            // layout. The byte path lays one out as the natural-C
            // `Type::Struct` of its fields in declaration order and addresses
            // it with `StructGep` (`adapter.rs`, `Ty::Record`), so that LIR
            // type — resolved with the module's own tables — is the authority
            // here too.
            let rdef = module
                .records
                .iter()
                .find(|def| def.id == *rid)
                .ok_or_else(|| global_initializer_error(name, format!("missing record {rid:?}")))?;
            let lir = trust_cg_lower::adapter::translate_type_in_module(module, ty)
                .map_err(|error| global_initializer_error(name, error))?;
            let (size, align) = size_align(u64::from(lir.bytes()), u64::from(lir.align()))?;
            let mut fields = Vec::with_capacity(rdef.fields.len());
            let mut names = Vec::with_capacity(rdef.fields.len());
            for (index, field) in rdef.fields.iter().enumerate() {
                let offset = lir
                    .offset_of(index)
                    .ok_or_else(|| global_initializer_error(name, "missing record field offset"))?
                    as usize;
                let child = global_init_layout(module, name, &field.ty, depth + 1)?;
                if offset.checked_add(child.size).is_none_or(|end| end > size) {
                    return Err(global_initializer_error(
                        name,
                        "record field exceeds emitted extent",
                    ));
                }
                if names.contains(&field.name.as_str()) {
                    return Err(global_initializer_error(
                        name,
                        format!("record declares field {:?} twice", field.name),
                    ));
                }
                names.push(field.name.as_str());
                fields.push((offset, child));
            }
            (size, align, GlobalInitShape::Record { fields, names })
        }
        Ty::Enum(id) => {
            let edef = module
                .enums
                .iter()
                .find(|def| def.id == *id)
                .ok_or_else(|| global_initializer_error(name, format!("missing enum {id:?}")))?;
            // A tag-free image (niche or untagged) has its own carrier on the
            // code path and no global renderer yet: refused by name rather
            // than emitted as a tag word the layout does not have.
            if let Some(layout) = edef.layout.as_ref()
                && !matches!(
                    layout.encoding,
                    trust_ir::ty::EnumTagEncoding::Direct { .. }
                )
            {
                return Err(global_initializer_error(
                    name,
                    format!(
                        "enum-typed global `{}` with a niche or untagged producer layout \
                         (tag-free image emission for globals not yet wired)",
                        edef.name
                    ),
                ));
            }
            // THE SAME IMAGE THE CODE PATH ADDRESSES (L05-P5): the producer's
            // descriptor read verbatim, else the canonical `Type::Enum` after
            // trust-ir's `enum_layout_shape` agreed with it. A global's bytes
            // and the native code that reads them come from one authority.
            let image = trust_cg_lower::direct_enum::module_direct_enum_image(module, *id)
                .map_err(|error| global_initializer_error(name, error))?;
            let (size, align) = size_align(image.size, image.align)?;
            let tag_offset = usize::try_from(image.tag_offset).map_err(|_| {
                global_initializer_error(name, "enum tag offset exceeds host address space")
            })?;
            let (tag_width, tag_signed) =
                integer_ty_width_signed(&image.tag.ty).ok_or_else(|| {
                    global_initializer_error(
                        name,
                        format!(
                            "enum tag type {:?} is not a fixed-width integer",
                            image.tag.ty
                        ),
                    )
                })?;
            if tag_offset
                .checked_add(tag_width)
                .is_none_or(|end| end > size)
            {
                return Err(global_initializer_error(
                    name,
                    "enum tag lane exceeds the enum image",
                ));
            }
            if image.variants.len() != edef.variants.len() {
                return Err(global_initializer_error(
                    name,
                    "enum image and enum definition disagree on the variant count",
                ));
            }
            let mut variants = Vec::with_capacity(image.variants.len());
            for (fields, variant) in image.variants.iter().zip(&edef.variants) {
                variants.push(global_enum_variant_layout(
                    module,
                    name,
                    fields,
                    &variant.fields,
                    size,
                    (tag_offset, tag_width),
                    depth,
                )?);
            }
            (
                size,
                align,
                GlobalInitShape::Enum {
                    tag_offset,
                    tag_ty: image.tag.ty.clone(),
                    tag_width,
                    tag_signed,
                    discriminants: image.tag.discriminants.clone(),
                    variants,
                },
            )
        }
        _ => {
            let layout = module
                .ty_layout_shape(ty)
                .map_err(|error| global_initializer_error(name, error))?;
            let size = layout
                .size_bytes()
                .ok_or_else(|| global_initializer_error(name, "non-byte initializer size"))?;
            let align = layout
                .align_bits
                .filter(|bits| bits.is_multiple_of(8))
                .map(|bits| bits / 8)
                .ok_or_else(|| {
                    global_initializer_error(name, "missing byte initializer alignment")
                })?;
            let (size, align) = size_align(size, align)?;
            (size, align, GlobalInitShape::Scalar)
        }
    };
    Ok(GlobalInitLayout {
        ty,
        size,
        align,
        shape,
    })
}

fn typed_global_initializer_data(
    module: &trust_ir::Module,
    name: &str,
    ty: &trust_ir::Ty,
    initializer: &trust_ir::Constant,
    endian: trust_ir::Endianness,
) -> Result<(Vec<u8>, Vec<crate::pipeline::GlobalSymbolRef>), PipelineError> {
    let layout = global_init_layout(module, name, ty, 0)?;
    render_global_initializer(name, &layout, initializer, endian)
}

fn render_global_initializer(
    name: &str,
    layout: &GlobalInitLayout<'_>,
    initializer: &trust_ir::Constant,
    endian: trust_ir::Endianness,
) -> Result<(Vec<u8>, Vec<crate::pipeline::GlobalSymbolRef>), PipelineError> {
    use crate::pipeline::GlobalSymbolRef;
    use trust_ir::{Constant, Ty};
    if let Constant::Bytes { data, utf8 } = initializer {
        // This typed leaf path is distinct from the legacy top-level raw
        // image route. A byte payload cannot stand in for an equally sized
        // tuple, vector, scalar or non-U8 array.
        let Ty::Array(_, declared_len) = layout.ty else {
            return Err(global_initializer_error(
                name,
                "nested Bytes requires a [u8; N] array type",
            ));
        };
        let GlobalInitShape::Repeated { len, element } = &layout.shape else {
            return Err(global_initializer_error(
                name,
                "nested Bytes requires a resolved repeated array layout",
            ));
        };
        if *element.ty != Ty::U8
            || !matches!(element.shape, GlobalInitShape::Scalar)
            || element.size != 1
            || element.align != 1
            || layout.align != 1
        {
            return Err(global_initializer_error(
                name,
                "nested Bytes requires a resolved U8 element with byte size and alignment",
            ));
        }
        if u64::try_from(data.len()).ok() != Some(*declared_len)
            || *len != data.len()
            || layout.size != data.len()
        {
            return Err(global_initializer_error(
                name,
                "nested Bytes length disagrees with its declared array count or layout extent",
            ));
        }
        if *utf8 && std::str::from_utf8(data).is_err() {
            return Err(global_initializer_error(
                name,
                "nested Bytes carries an invalid UTF-8 claim",
            ));
        }
        return Ok((data.clone(), Vec::new()));
    }
    if let Constant::Splat { elem, len } = initializer {
        return render_global_splat_initializer(name, layout, elem, *len, endian);
    }
    if let GlobalInitShape::Scalar = layout.shape {
        if !initializer.shape_matches_ty(layout.ty) {
            return Err(global_initializer_error(
                name,
                format!(
                    "initializer {initializer:?} does not match typed field {:?}",
                    layout.ty
                ),
            ));
        }
        let data = match initializer {
            Constant::Int(value) => {
                let (width, signed) =
                    aggregate_int_element_width_signed(layout.ty).ok_or_else(|| {
                        global_initializer_error(
                            name,
                            format!("integer initializer for non-integer type {:?}", layout.ty),
                        )
                    })?;
                scalar_int_initializer_bytes(name, layout.ty, *value, width, signed, endian)?
            }
            Constant::U128(value) if *layout.ty == Ty::U128 && *value > i128::MAX as u128 => {
                scalar_uint_bits_bytes(name, *value, 16, endian)?
            }
            Constant::Bool(value) if *layout.ty == Ty::Bool => vec![u8::from(*value)],
            Constant::Float(value) if *layout.ty == Ty::F32 => {
                scalar_uint_bits_bytes(name, (*value as f32).to_bits() as u128, 4, endian)?
            }
            Constant::Float(value) if *layout.ty == Ty::F64 => {
                scalar_uint_bits_bytes(name, value.to_bits() as u128, 8, endian)?
            }
            Constant::SymbolAddr { symbol, addend }
                if matches!(layout.ty, Ty::Ptr | Ty::Func(_)) =>
            {
                if symbol.is_empty()
                    || symbol.contains('\0')
                    || layout.size != GLOBAL_POINTER_SIZE
                    || endian != trust_ir::Endianness::Little
                {
                    return Err(global_initializer_error(
                        name,
                        "invalid symbol address or unsupported pointer layout",
                    ));
                }
                return Ok((
                    vec![0; GLOBAL_POINTER_SIZE],
                    vec![GlobalSymbolRef {
                        offset: 0,
                        symbol: symbol.clone(),
                        addend: *addend,
                    }],
                ));
            }
            Constant::PhantomData if *layout.ty == Ty::Unit => Vec::new(),
            other => {
                return Err(global_initializer_error(
                    name,
                    format!(
                        "initializer {other:?} does not match typed field {:?}",
                        layout.ty
                    ),
                ));
            }
        };
        if data.len() != layout.size {
            return Err(global_initializer_error(
                name,
                "scalar carrier width disagrees with initializer layout",
            ));
        }
        return Ok((data, Vec::new()));
    }
    if let GlobalInitShape::Enum {
        tag_offset,
        tag_ty,
        tag_width,
        tag_signed,
        discriminants,
        variants,
    } = &layout.shape
    {
        return render_global_enum_initializer(
            name,
            layout,
            (*tag_offset, tag_ty, *tag_width, *tag_signed),
            discriminants,
            variants,
            initializer,
            endian,
        );
    }
    // A `Constant::Record` names its fields; put them in declaration order so
    // the positional walk below places each at its field's offset. A missing,
    // unknown or repeated name is refused, never zero-filled.
    let ordered: Vec<Constant>;
    let values: &[Constant] = match (initializer, &layout.shape) {
        (Constant::Record(named), GlobalInitShape::Record { names, .. }) => {
            if named.len() != names.len() {
                return Err(global_initializer_error(
                    name,
                    format!(
                        "record initializer names {} fields, the record declares {}",
                        named.len(),
                        names.len()
                    ),
                ));
            }
            ordered = names
                .iter()
                .map(|declared| {
                    let mut found = named.iter().filter(|(given, _)| given == declared);
                    match (found.next(), found.next()) {
                        (Some((_, value)), None) => Ok(value.clone()),
                        (None, _) => Err(global_initializer_error(
                            name,
                            format!("record initializer omits field {declared:?}"),
                        )),
                        (Some(_), Some(_)) => Err(global_initializer_error(
                            name,
                            format!("record initializer repeats field {declared:?}"),
                        )),
                    }
                })
                .collect::<Result<Vec<_>, PipelineError>>()?;
            &ordered
        }
        (Constant::Aggregate(values), _) => values,
        (Constant::Array(values), _) if matches!(layout.ty, Ty::Array(..)) => values,
        (Constant::Vector(values), _) if matches!(layout.ty, Ty::Vector(..)) => values,
        _ => {
            return Err(global_initializer_error(
                name,
                "typed aggregate requires a matching aggregate initializer",
            ));
        }
    };
    // The scalar leaf and the enum image returned above; the arms below refuse
    // rather than panic if those early returns are ever reordered.
    let expected = match &layout.shape {
        GlobalInitShape::Fields(fields) | GlobalInitShape::Record { fields, .. } => fields.len(),
        GlobalInitShape::Repeated { len, .. } => *len,
        GlobalInitShape::Scalar => return Err(scalar_layout_in_aggregate_path(name)),
        GlobalInitShape::Enum { .. } => return Err(enum_layout_in_aggregate_path(name)),
    };
    if values.len() != expected {
        return Err(global_initializer_error(
            name,
            format!(
                "aggregate initializer element count {} does not match declared count {expected}",
                values.len()
            ),
        ));
    }
    let mut data = Vec::new();
    data.try_reserve_exact(layout.size)
        .map_err(|error| global_initializer_error(name, error))?;
    data.resize(layout.size, 0);
    let mut refs = Vec::new();
    for (index, value) in values.iter().enumerate() {
        let (offset, child) = match &layout.shape {
            GlobalInitShape::Fields(fields) | GlobalInitShape::Record { fields, .. } => {
                (fields[index].0, &fields[index].1)
            }
            GlobalInitShape::Repeated { element, .. } => (index * element.size, element.as_ref()),
            GlobalInitShape::Scalar => return Err(scalar_layout_in_aggregate_path(name)),
            GlobalInitShape::Enum { .. } => return Err(enum_layout_in_aggregate_path(name)),
        };
        let (bytes, child_refs) = render_global_initializer(name, child, value, endian)?;
        let end = offset
            .checked_add(bytes.len())
            .ok_or_else(|| global_initializer_error(name, "initializer field offset overflow"))?;
        let destination = data
            .get_mut(offset..end)
            .ok_or_else(|| global_initializer_error(name, "initializer field exceeds layout"))?;
        destination.copy_from_slice(&bytes);
        for mut reference in child_refs {
            reference.offset = reference.offset.checked_add(offset as u64).ok_or_else(|| {
                global_initializer_error(name, "initializer relocation offset overflow")
            })?;
            refs.push(reference);
        }
    }
    Ok((data, refs))
}

/// Render a trust-ir v50 `Constant::Splat { elem, len }` at array layout
/// `layout`: `len` copies of `elem`'s image at the element stride.
///
/// The element is rendered ONCE, through the same typed walk as every other
/// leaf, so it is checked exactly as a list element would be; the image is
/// then its bytes repeated (a doubling copy). The object's bytes are the
/// output, so their count is inherent to it — but the constant walk never
/// repeats, and an element that carries no relocation adds none. Each lane of
/// an element that does carry one relocates its own copy, since the linker
/// must patch every lane.
fn render_global_splat_initializer(
    name: &str,
    layout: &GlobalInitLayout<'_>,
    elem: &trust_ir::Constant,
    len: u64,
    endian: trust_ir::Endianness,
) -> Result<(Vec<u8>, Vec<crate::pipeline::GlobalSymbolRef>), PipelineError> {
    use crate::pipeline::GlobalSymbolRef;
    let (
        trust_ir::Ty::Array(_, declared_len),
        GlobalInitShape::Repeated {
            len: lanes,
            element,
        },
    ) = (layout.ty, &layout.shape)
    else {
        return Err(global_initializer_error(
            name,
            format!(
                "Constant::Splat requires an array type with a repeated layout, got {:?}",
                layout.ty
            ),
        ));
    };
    if len != *declared_len || u64::try_from(*lanes).ok() != Some(len) {
        return Err(global_initializer_error(
            name,
            format!(
                "Constant::Splat has {len} lane(s), but its declared array type has \
                 {declared_len}"
            ),
        ));
    }
    let (lane, lane_refs) = render_global_initializer(name, element, elem, endian)?;
    if lane.len() != element.size
        || element
            .size
            .checked_mul(*lanes)
            .is_none_or(|total| total != layout.size)
    {
        return Err(global_initializer_error(
            name,
            "Constant::Splat element image disagrees with its array layout",
        ));
    }
    let mut data = Vec::new();
    data.try_reserve_exact(layout.size)
        .map_err(|error| global_initializer_error(name, error))?;
    if lane.iter().all(|byte| *byte == 0) {
        data.resize(layout.size, 0);
    } else {
        data.extend_from_slice(&lane);
        while data.len() < layout.size {
            let chunk = data.len().min(layout.size - data.len());
            data.extend_from_within(..chunk);
        }
    }
    let mut refs = Vec::new();
    if !lane_refs.is_empty() {
        let stride = element.size as u64;
        refs.try_reserve_exact(lane_refs.len().saturating_mul(*lanes))
            .map_err(|error| global_initializer_error(name, error))?;
        for index in 0..len {
            let base = index.checked_mul(stride).ok_or_else(|| {
                global_initializer_error(name, "initializer relocation offset overflow")
            })?;
            for reference in &lane_refs {
                refs.push(GlobalSymbolRef {
                    offset: reference.offset.checked_add(base).ok_or_else(|| {
                        global_initializer_error(name, "initializer relocation offset overflow")
                    })?,
                    symbol: reference.symbol.clone(),
                    addend: reference.addend,
                });
            }
        }
    }
    Ok((data, refs))
}

/// Render a direct-tag enum global (L05-P5): `[discriminant, fields..]` of
/// the active variant, the tag word written as the discriminant VALUE in the
/// enum's canonical tag type (two's complement for a signed repr), and each
/// field at the image's own offset, relocations included.
fn render_global_enum_initializer(
    name: &str,
    layout: &GlobalInitLayout<'_>,
    (tag_offset, tag_ty, tag_width, tag_signed): (usize, &trust_ir::Ty, usize, bool),
    discriminants: &[i128],
    variants: &[Vec<(usize, GlobalInitLayout<'_>)>],
    initializer: &trust_ir::Constant,
    endian: trust_ir::Endianness,
) -> Result<(Vec<u8>, Vec<crate::pipeline::GlobalSymbolRef>), PipelineError> {
    use trust_ir::Constant;
    let Constant::Aggregate(values) = initializer else {
        return Err(global_initializer_error(
            name,
            "enum initializer requires a [discriminant, fields..] aggregate",
        ));
    };
    let Some(Constant::Int(disc)) = values.first() else {
        return Err(global_initializer_error(
            name,
            "enum initializer needs an integer discriminant at element 0",
        ));
    };
    let variant = discriminants
        .iter()
        .position(|value| value == disc)
        .ok_or_else(|| {
            global_initializer_error(
                name,
                format!(
                    "enum initializer discriminant {disc} names no variant (variants carry \
                     {discriminants:?})"
                ),
            )
        })?;
    let fields = variants.get(variant).ok_or_else(|| {
        global_initializer_error(name, format!("enum image lays out no variant {variant}"))
    })?;
    if values.len() != 1 + fields.len() {
        return Err(global_initializer_error(
            name,
            format!(
                "enum initializer for discriminant {disc} carries {} payload fields, the variant \
                 has {}",
                values.len().saturating_sub(1),
                fields.len()
            ),
        ));
    }
    let mut data = Vec::new();
    data.try_reserve_exact(layout.size)
        .map_err(|error| global_initializer_error(name, error))?;
    data.resize(layout.size, 0);
    let tag_bytes =
        scalar_int_initializer_bytes(name, tag_ty, *disc, tag_width, tag_signed, endian)?;
    let tag_end = tag_offset
        .checked_add(tag_bytes.len())
        .ok_or_else(|| global_initializer_error(name, "enum tag offset overflow"))?;
    data.get_mut(tag_offset..tag_end)
        .ok_or_else(|| global_initializer_error(name, "enum tag lane exceeds the enum image"))?
        .copy_from_slice(&tag_bytes);
    let mut refs = Vec::new();
    for ((offset, child), value) in fields.iter().zip(&values[1..]) {
        let (bytes, child_refs) = render_global_initializer(name, child, value, endian)?;
        let end = offset
            .checked_add(bytes.len())
            .ok_or_else(|| global_initializer_error(name, "enum field offset overflow"))?;
        data.get_mut(*offset..end)
            .ok_or_else(|| global_initializer_error(name, "enum field exceeds the enum image"))?
            .copy_from_slice(&bytes);
        for mut reference in child_refs {
            reference.offset = reference
                .offset
                .checked_add(*offset as u64)
                .ok_or_else(|| {
                    global_initializer_error(name, "enum field relocation offset overflow")
                })?;
            refs.push(reference);
        }
    }
    Ok((data, refs))
}

fn trust_ir_global_initializer_data(
    module: &trust_ir::Module,
    global: &trust_ir::Global,
    initializer: &trust_ir::Constant,
    endian: trust_ir::Endianness,
) -> Result<(Vec<u8>, Vec<crate::pipeline::GlobalSymbolRef>), PipelineError> {
    use crate::pipeline::GlobalSymbolRef;

    if aggregate_type_is_decomposable(&global.ty)
        && !matches!(initializer, trust_ir::Constant::Bytes { .. })
    {
        return typed_global_initializer_data(
            module,
            &global.name,
            &global.ty,
            initializer,
            endian,
        );
    }

    match initializer {
        trust_ir::Constant::SymbolAddr { .. }
        | trust_ir::Constant::U128(_)
        | trust_ir::Constant::PhantomData => {
            typed_global_initializer_data(module, &global.name, &global.ty, initializer, endian)
        }
        trust_ir::Constant::Aggregate(elems) => {
            // Enum- and record-typed globals took the typed path above
            // (L05-P5): an enum `Constant::Aggregate` is the tag+payload
            // convention (element 0 = discriminant VALUE), which the flat byte
            // image below could never place.
            let mut data: Vec<u8> = Vec::with_capacity(elems.len());
            let mut symbol_refs: Vec<GlobalSymbolRef> = Vec::new();
            // Typed aggregates returned above. Scalar/opaque globals retain
            // the explicit legacy flat byte/symbol-address image spelling.
            for (index, elem) in elems.iter().enumerate() {
                match elem {
                    trust_ir::Constant::Int(byte) => {
                        // Historic flat byte image: one literal byte per `Int`.
                        data.push(u8::try_from(*byte).map_err(|_| {
                            PipelineError::ObjectEmission(format!(
                                "trust-ir global {} unsupported: byte aggregate element {index} value {byte} is outside u8 range",
                                global.name
                            ))
                        })?);
                    }
                    trust_ir::Constant::SymbolAddr { symbol, addend } => {
                        // A symbol address is a pointer, always pointer-width and
                        // relocated regardless of the declared element type.
                        if symbol.is_empty() || symbol.contains('\0') {
                            return Err(global_initializer_error(
                                &global.name,
                                "invalid symbol address",
                            ));
                        }
                        let offset = data.len() as u64;
                        data.extend(std::iter::repeat_n(0u8, GLOBAL_POINTER_SIZE));
                        symbol_refs.push(GlobalSymbolRef {
                            offset,
                            symbol: symbol.clone(),
                            addend: *addend,
                        });
                    }
                    other => {
                        return Err(PipelineError::ObjectEmission(format!(
                            "trust-ir global {} unsupported: only integer and symbol-address aggregate elements are admitted in this slice; element {index} is {other:?}",
                            global.name
                        )));
                    }
                }
            }
            Ok((data, symbol_refs))
        }
        trust_ir::Constant::Int(value) => {
            if matches!(
                global.ty,
                trust_ir::Ty::Char | trust_ir::Ty::Isize | trust_ir::Ty::Usize
            ) {
                typed_global_initializer_data(module, &global.name, &global.ty, initializer, endian)
            } else if let Some((width, signed)) = integer_ty_width_signed(&global.ty) {
                scalar_int_initializer_bytes(
                    &global.name,
                    &global.ty,
                    *value,
                    width,
                    signed,
                    endian,
                )
                .map(|bytes| (bytes, Vec::new()))
            } else if global.ty == trust_ir::Ty::Bool {
                // A Bool global wants a `Constant::Bool`; an integer literal is a
                // shape mismatch we refuse rather than guess the truth value of.
                Err(PipelineError::ObjectEmission(format!(
                    "trust-ir global {} unsupported: scalar integer initializer for Bool needs target-endian typed data emission; a Bool global must carry a Bool initializer",
                    global.name
                )))
            } else {
                Err(PipelineError::ObjectEmission(format!(
                    "trust-ir global {} unsupported: integer initializer for non-integer type {:?}",
                    global.name, global.ty
                )))
            }
        }
        trust_ir::Constant::Float(value) => match global.ty {
            // F64 stores the exact IEEE-754 double bit pattern.
            trust_ir::Ty::F64 => {
                scalar_uint_bits_bytes(&global.name, value.to_bits() as u128, 8, endian)
                    .map(|bytes| (bytes, Vec::new()))
            }
            // F32 stores the round-to-nearest-even single-precision encoding of
            // the literal -- identical to what a C compiler emits for
            // `float x = <double-constant>;`.
            trust_ir::Ty::F32 => {
                scalar_uint_bits_bytes(&global.name, (*value as f32).to_bits() as u128, 4, endian)
                    .map(|bytes| (bytes, Vec::new()))
            }
            _ => Err(PipelineError::ObjectEmission(format!(
                "trust-ir global {} unsupported: float initializer for {:?} (only F32/F64 scalar float globals are wired; F16 and non-float types are refused)",
                global.name, global.ty
            ))),
        },
        trust_ir::Constant::Bool(value) if global.ty == trust_ir::Ty::Bool => {
            Ok((vec![u8::from(*value)], Vec::new()))
        }
        // The v25 byte-array carrier: an initializer whose value IS a raw byte
        // sequence (a `&[u8]` / `&str` backing store, a SipHash key table, a
        // `RawTableInner` control-byte buffer). The bytes are emitted verbatim —
        // they are already the target-endian object image and carry no embedded
        // symbol-address relocations (the `utf8` flag is a producer-side claim
        // about the contents, not a layout distinction). This mirrors the
        // `Constant::Aggregate` byte path, one byte per element, but without the
        // per-element `Int` round-trip.
        trust_ir::Constant::Bytes { data, utf8 } => {
            if *utf8 && std::str::from_utf8(data).is_err() {
                return Err(global_initializer_error(
                    &global.name,
                    "invalid UTF-8 byte initializer",
                ));
            }
            if aggregate_type_is_decomposable(&global.ty)
                && data.len() != global_init_layout(module, &global.name, &global.ty, 0)?.size
            {
                return Err(global_initializer_error(
                    &global.name,
                    "byte initializer length does not match declared layout",
                ));
            }
            Ok((data.clone(), Vec::new()))
        }
        other => Err(PipelineError::ObjectEmission(format!(
            "trust-ir global {} unsupported: only byte/symbol-address aggregate and byte-sized scalar initializers are admitted in this slice; initializer is {other:?}",
            global.name
        ))),
    }
}

/// Runs `scans` — a loop preparing (and fsym-scanning) the functions of
/// `module` — inside an fsym module scope, so the bounded fsym preflight of
/// each function decides the module-level facts once for all of them; runs
/// it directly when fsym is not compiled in.
fn with_fsym_module_scope<R>(module: &trust_ir::Module, scans: impl FnOnce() -> R) -> R {
    #[cfg(feature = "verify")]
    {
        trust_cg_verify::fsym_trust_ir::with_fsym_module_scope(module, scans)
    }
    #[cfg(not(feature = "verify"))]
    {
        let _ = module;
        scans()
    }
}

fn trust_ir_functions_for_lir<'a>(
    module: &'a trust_ir::Module,
    lir_functions: &[(trust_cg_lower::Function, trust_cg_lower::ProofContext)],
) -> Vec<Option<&'a trust_ir::Function>> {
    // Lowering has already rejected duplicate symbol names. Keep this helper
    // fail-closed if another caller ever bypasses that gate: an ambiguous name
    // maps to no TrustIR proof context rather than whichever definition happened
    // to appear first. Building the index once also avoids the former O(F * L)
    // name scan for F TrustIR and L lowered functions.
    let mut functions_by_name: HashMap<&str, Option<&trust_ir::Function>> =
        HashMap::with_capacity(module.functions.len());
    for function in module
        .functions
        .iter()
        .filter(|function| !function.blocks.is_empty())
    {
        functions_by_name
            .entry(function.name.as_str())
            .and_modify(|entry| *entry = None)
            .or_insert(Some(function));
    }

    lir_functions
        .iter()
        .map(|(lir_function, _)| {
            functions_by_name
                .get(lir_function.name.as_str())
                .copied()
                .flatten()
        })
        .collect()
}

/// The object-symbol linkage an AArch64 ELF or Mach-O module emission carries:
/// each emitted function's binding from its trust-ir linkage and v45
/// visibility (1:1 with `functions`), its COMDAT membership, its v45 explicit
/// section, every bodyless `ExternalWeak` declaration as a weak undefined
/// reference, every codegen declaration's non-default v45 visibility on
/// its undefined reference, and the weak or visible declarations (functions
/// and data) whose undefined symbols the ELF emitters write even when
/// nothing references them. The Mach-O emitter refuses weak references,
/// visible undefined references and explicit function sections by name; the
/// adapter admits non-default function visibility and sections for the
/// AArch64 ELF path, and hidden `External` definitions (`N_PEXT`) alone for
/// the AArch64 Mach-O path.
///
/// `sources` is [`trust_ir_functions_for_lir`] for the same functions. An
/// emitted function without a unique trust-ir definition, whose linkage is
/// declaration-only, or whose visibility contradicts a local linkage, has no
/// binding to carry and fails closed.
fn aarch64_module_symbol_linkage(
    module: &trust_ir::Module,
    functions: &[trust_cg_ir::MachFunction],
    sources: &[Option<&trust_ir::Function>],
) -> Result<ModuleSymbolLinkage, PipelineError> {
    if functions.len() != sources.len() {
        return Err(PipelineError::ObjectEmission(format!(
            "AArch64 object symbol linkage: {} emitted function(s) but {} trust-ir source slot(s) (fail-closed)",
            functions.len(),
            sources.len()
        )));
    }
    let bindings = functions
        .iter()
        .zip(sources)
        .map(|(function, source)| {
            let source = source.filter(|source| source.name == function.name).ok_or_else(|| {
                PipelineError::ObjectEmission(format!(
                    "AArch64 object symbol linkage: emitted function `{}` has no unique trust-ir definition to bind (fail-closed)",
                    function.name
                ))
            })?;
            FunctionSymbolBinding::for_trust_ir_definition(source.linkage, source.visibility)
                .map_err(|reason| {
                    PipelineError::ObjectEmission(format!(
                        "AArch64 object symbol linkage: emitted function `{}` has linkage `{}` and visibility `{}`: {reason} (fail-closed)",
                        function.name, source.linkage, source.visibility
                    ))
                })
        })
        .collect::<Result<Vec<_>, _>>()?;
    // Undefined references follow the adapter's one classification of what an
    // object only references (`SymbolBinding::for_trust_ir_function`): weak
    // for a bodyless `ExternalWeak` function, and each carries its
    // declaration's non-default v45 visibility.
    let undefined_references = module.functions.iter().filter_map(|function| {
        match trust_cg_lower::SymbolBinding::for_trust_ir_function(function) {
            trust_cg_lower::SymbolBinding::Undefined { weak } => Some((function, weak)),
            trust_cg_lower::SymbolBinding::Defined(_) => None,
        }
    });
    let weak_undefined_functions = undefined_references
        .clone()
        .filter(|(_, weak)| *weak)
        .map(|(function, _)| function.name.clone())
        .collect();
    let undefined_function_visibility: std::collections::BTreeMap<String, trust_ir::Visibility> =
        undefined_references
            .clone()
            .filter(|(function, _)| function.visibility != trust_ir::Visibility::Default)
            .map(|(function, _)| (function.name.clone(), function.visibility))
            .collect();
    // The declarations llc 22 writes as undefined symbols even when nothing
    // references them: its `AsmPrinter` states an `extern_weak`
    // declaration's linkage and a declaration's non-default visibility on
    // the symbol, which puts it in the symbol table. That is every function
    // declaration (bodyless or `available_externally`) and every non-TLS
    // data declaration (`external`/`extern_weak` without an initializer)
    // that is `extern_weak` or states hidden or protected visibility. An
    // `available_externally` GLOBAL is not one: llc writes nothing for it
    // unless something references it. A thread-local import is written by
    // the ELF emitters in any case (undefined `STT_TLS`).
    let declared_functions = undefined_references
        .filter(|(function, weak)| *weak || function.visibility != trust_ir::Visibility::Default)
        .map(|(function, _)| function.name.clone());
    let declared_data = module
        .globals
        .iter()
        .filter(|global| {
            global.initializer.is_none()
                && global.tls.is_none()
                && matches!(
                    global.linkage,
                    trust_ir::Linkage::External | trust_ir::Linkage::ExternalWeak
                )
                && (global.linkage == trust_ir::Linkage::ExternalWeak
                    || global.visibility != trust_ir::Visibility::Default)
        })
        .map(|global| global.name.clone());
    let declared_undefined_symbols = declared_functions.chain(declared_data).collect();
    // COMDAT placement follows the same trust-ir linkage classification as the
    // binding above: only the one-definition-rule forms get their own grouped
    // `.text.<symbol>` section (see
    // `FunctionSymbolBinding::trust_ir_definition_is_comdat`).
    let comdat_functions = functions
        .iter()
        .zip(sources)
        .filter(|(_, source)| {
            source.is_some_and(|source| {
                FunctionSymbolBinding::trust_ir_definition_is_comdat(source.linkage)
            })
        })
        .map(|(function, _)| function.name.clone())
        .collect();
    // The explicit section of each emitted definition, validated for the
    // object format by the emitter.
    let explicit_function_sections = functions
        .iter()
        .zip(sources)
        .filter_map(|(function, source)| {
            source
                .and_then(|source| source.section.clone())
                .map(|section| (function.name.clone(), section))
        })
        .collect();
    Ok(ModuleSymbolLinkage::new(bindings, weak_undefined_functions)
        .with_undefined_function_visibility(undefined_function_visibility)
        .with_comdat_functions(comdat_functions)
        .with_explicit_function_sections(explicit_function_sections)
        .with_declared_undefined_symbols(declared_undefined_symbols))
}

/// Names of bodied definitions another object's definition may replace at
/// STATIC link ([`trust_cg_lower::definition_is_link_replaceable`]:
/// `Weak`, `LinkOnce`), so no caller may absorb their body. Their ODR twins
/// (`WeakOdr`, `LinkOnceOdr`) promise equivalent definitions and stay
/// inlinable. Structural purity inference reads the same predicate.
fn interposable_weak_definitions(module: &trust_ir::Module) -> std::collections::HashSet<String> {
    module
        .functions
        .iter()
        .filter(|function| {
            !function.blocks.is_empty()
                && trust_cg_lower::definition_is_link_replaceable(function.linkage)
        })
        .map(|function| function.name.clone())
        .collect()
}

/// Names of the module's bodied function definitions the module inliner must
/// not splice into a caller, because another module may replace the body.
/// Each shared predicate carries its own target scope:
///
/// * load-time preemption ([`preemptible_function_names`]) applies on every
///   target; only AArch64 ELF admits `pic`, so it is empty elsewhere;
/// * static-link replacement ([`interposable_weak_definitions`]) applies on
///   every target: the AArch64 and x86-64 ELF and Mach-O writers and the
///   RISC-V module object emit `Weak`/`LinkOnce` definitions weak
///   ([`weak_function_definitions`]), and the x86-64 COFF emitter
///   refuses them ([`refuse_coff_weak_function_definitions`]).
///
/// Structural purity inference (`trust_cg_lower`'s
/// `definition_body_is_replaceable`) applies both predicates on every target.
fn inliner_interposable_function_names(
    module: &trust_ir::Module,
    relocation_model: RelocationModel,
    target: Target,
) -> std::collections::HashSet<String> {
    let mut names = preemptible_function_names(module, relocation_model);
    if matches!(target, Target::Aarch64 | Target::X86_64 | Target::Riscv64) {
        names.extend(interposable_weak_definitions(module));
    }
    names
}

/// The bodied function definitions an x86-64 Mach-O or ELF object binds weak
/// ([`crate::x86_64::X86PipelineConfig::weak_function_definitions`]) and the
/// RISC-V module object binds `STB_WEAK` ([`riscv_module_object`]): exactly
/// those whose trust-ir linkage [`FunctionSymbolBinding::for_trust_ir_definition`]
/// classifies weak (`Weak`, `LinkOnce`, `WeakOdr`, `LinkOnceOdr`), as the
/// AArch64 writers bind them. The x86-64 COFF emitter spells none and refuses
/// them ([`refuse_coff_weak_function_definitions`]).
fn weak_function_definitions(module: &trust_ir::Module) -> std::collections::BTreeSet<String> {
    module
        .functions
        .iter()
        .filter(|function| !function.blocks.is_empty() && linkage_binds_weak(function.linkage))
        .map(|function| function.name.clone())
        .collect()
}

/// Whether a bodied definition of `linkage` is a weak (coalescable)
/// definition in every object writer that spells one: `Weak`, `LinkOnce` and
/// their ODR twins.
fn linkage_binds_weak(linkage: trust_ir::Linkage) -> bool {
    matches!(
        linkage,
        trust_ir::Linkage::Weak
            | trust_ir::Linkage::LinkOnce
            | trust_ir::Linkage::WeakOdr
            | trust_ir::Linkage::LinkOnceOdr
    )
}

/// The bodied module-local (`Internal`/`Private`) function definitions
/// ([`trust_cg_lower::is_module_local_function_definition`], the
/// classification the identity census counts references to, pinned equal to
/// `FunctionSymbolBinding::for_trust_ir_definition`'s local arm by
/// `module_local_census_classification_matches_the_elf_local_binding`) that
/// the RISC-V module object binds `STB_LOCAL` ([`riscv_module_object`]). The
/// x86-64 emitters take the same binding from their facts
/// ([`x86_64_function_symbol_facts`]). On RISC-V every trust-ir REFERENCE to
/// such a definition (a call, a function identity, a `SymbolAddr`) stays
/// refused before lowering (the census, `Compiler::compile`); binding the
/// unreferenced body local is what keeps another object's reference or weak
/// definition from binding to it. A reference that names another symbol
/// never reaches it either: the emitter binds a reference to the symbol its
/// own name spells.
fn module_local_function_definitions(
    module: &trust_ir::Module,
) -> std::collections::BTreeSet<String> {
    module
        .functions
        .iter()
        .filter(|function| trust_cg_lower::is_module_local_function_definition(function))
        .map(|function| function.name.clone())
        .collect()
}

/// Refuse a module with a bodied weak or link-once function definition
/// ([`linkage_binds_weak`]) when the x86-64 object is COFF: the COFF module
/// emitter places every function in one `.text` section and writes no COMDAT
/// section (`IMAGE_COMDAT_SELECT_ANY`) or weak external, so the definition
/// would be a strong `IMAGE_SYM_CLASS_EXTERNAL` symbol and the requested
/// binding would be dropped. The emitter refuses it too, as a backstop.
fn refuse_coff_weak_function_definitions(
    module: &trust_ir::Module,
    output_format: crate::x86_64::X86OutputFormat,
) -> Result<(), CompileError> {
    if output_format != crate::x86_64::X86OutputFormat::Coff {
        return Ok(());
    }
    match module
        .functions
        .iter()
        .find(|function| !function.blocks.is_empty() && linkage_binds_weak(function.linkage))
    {
        Some(function) => Err(CompileError::Adapter(
            trust_cg_lower::AdapterError::UnsupportedLinkage {
                symbol: function.name.clone(),
                linkage: function.linkage,
                reason: "the x86-64 COFF module emitter places every function in one `.text` \
                         section and writes no COMDAT section or weak external, so a weak or \
                         link-once definition would be a strong IMAGE_SYM_CLASS_EXTERNAL symbol",
            },
        )),
        None => Ok(()),
    }
}

/// Per-function JIT validation provenance (JIT-5).
///
/// Records, for one published function, whether its verifier-visible semantics
/// carry instruction proofs or an exact AArch64 source/ABI structural-return
/// check, the verifier-input identity, the exact published
/// callable-range hash, and whether the verdict came from the content-addressed
/// certificate cache (warm hit) or a fresh discharge. Auxiliary prefix/pool
/// bytes inside the callable range are integrity-bound but are not represented
/// as instruction-lowering proofs.
#[derive(Debug, Clone)]
pub struct JitFunctionValidation {
    /// Function name.
    pub function: String,
    /// Whether this function has non-vacuous instruction proofs or an exact
    /// AArch64 source/ABI structural-return check. The attached certificate
    /// distinguishes these classes; structural checking is not Formal credit.
    /// `false` appears on the Unchecked path; a verifying mode fails the whole
    /// compile closed before publishing an unverified function.
    pub verified: bool,
    /// SHA-256 (hex) of the canonical verifier input. This binds proof-visible
    /// IR/provenance semantics independently of relocation placeholder bytes.
    /// Empty only when that input was deliberately not evaluated on an
    /// unchecked or verifier-disabled path.
    pub verifier_input_sha256: String,
    /// SHA-256 (hex) of this function's exact callable range in the sealed,
    /// published executable image, after relocations and runtime profile-pointer
    /// patches. This proves integrity, not source-lowering semantics by itself.
    pub bytes_sha256: String,
    /// Whether the verdict was served from the certificate cache without
    /// re-running the verifier (warm hit).
    pub cache_hit: bool,
}

/// Whole-buffer JIT validation provenance (JIT-5).
///
/// Attached to every [`JitCompilationResult`] so the executed validation mode
/// is always auditable — Unchecked can never be silent — and so a consumer can
/// confirm every published function has a verified semantic certificate and
/// that its exact executable bytes belong to the sealed published image
/// (JIT-7's publish check).
#[derive(Debug, Clone)]
pub struct JitValidationProvenance {
    /// The resolved validation mode this buffer was published under.
    pub mode: JitValidationMode,
    /// SHA-256 (hex) of the full published executable image (JIT-7).
    pub published_image_sha256: String,
    /// Per-function coverage records. Unchecked rows are present but marked
    /// unverified, with no verifier-input digest.
    pub functions: Vec<JitFunctionValidation>,
}

impl JitValidationProvenance {
    /// Whether every published function carries checked semantic evidence:
    /// non-vacuous instruction proofs or an exact AArch64 source/ABI check for
    /// a RET-only body (true only in a verifying mode with a non-empty
    /// function set). Exact callable ranges, linker-created veneers, pointer
    /// slots, profiling prefixes, and constant-pool tails are integrity-bound by
    /// the reported hashes, but are not all claimed to be lowering-proved
    /// instructions. On x86-64 a body with no value-semantics row at all is NOT
    /// counted here, under either exemption (LIMITATIONS.md, x86-64): its only
    /// certificates are structural — the named `call_only_body` exemption and
    /// the `covered_elsewhere` certificates of its CALL/JMP/RET rows — and
    /// [`x86_certificates_show_verified_semantics`] excludes both because
    /// neither discharges an obligation. (Until 2026-09-28 it counted
    /// `covered_elsewhere`, so certification of a `call f; ud2` body and an
    /// empty `ret` body returned Ok with per-function `verified = true` and
    /// nothing discharged — measured on arm64 through the uncached path only;
    /// that such an Ok reaches this flag and publication is by reading the code.)
    pub fn every_function_semantics_verified(&self) -> bool {
        self.mode.requires_jit_verification()
            && !self.functions.is_empty()
            && self.functions.iter().all(|f| f.verified)
    }

    /// Compatibility spelling for [`Self::every_function_semantics_verified`].
    ///
    /// The historical name means semantic certification per function, not a
    /// proof for every auxiliary byte in the callable range.
    pub fn every_function_certified(&self) -> bool {
        self.every_function_semantics_verified()
    }

    /// Compatibility spelling for [`Self::every_function_semantics_verified`].
    ///
    /// Despite the historical name, this does not assert that auxiliary
    /// linker-generated bytes outside published function ranges carry lowering
    /// proofs; their exact sealed-image integrity is reported separately.
    pub fn every_byte_certified(&self) -> bool {
        self.every_function_semantics_verified()
    }

    /// Number of functions whose verdict was served from the cache.
    pub fn cache_hits(&self) -> usize {
        self.functions.iter().filter(|f| f.cache_hit).count()
    }
}

/// The result of compiling a trust_ir module through the Trust Codegen pipeline to
/// executable memory for JIT execution.
///
/// Unlike [`CompilationResult`] which produces Mach-O object file bytes,
/// this result contains an [`ExecutableBuffer`](crate::jit::ExecutableBuffer)
/// with all functions linked and ready for immediate execution.
pub struct JitCompilationResult {
    /// Executable memory buffer containing all compiled functions.
    pub buffer: crate::jit::ExecutableBuffer,
    /// Compilation metrics.
    pub metrics: CompilationMetrics,
    /// Optional compiler trace (populated when trace_level != None).
    pub trace: Option<CompilerTrace>,
    /// Optional proof certificates (populated when emit_proofs is true).
    pub proofs: Option<Vec<ProofCertificate>>,
    /// Proof-optimization certificate citations emitted by `trust-cg-opt` while
    /// preparing the executable buffer.
    pub proof_optimization_certificates: Vec<ProofOptimizationCertificateCitation>,
    /// Per-function code-quality and phase-timing metrics. See #364.
    /// Always populated (one entry per compiled function).
    pub per_function_metrics: Vec<FunctionQualityMetrics>,
    /// Actual x86 host-JIT target-feature profile derived from every
    /// function's final machine-code evidence. Non-x86 JIT paths report
    /// `None`.
    pub host_jit_selected_codegen_profile: Option<HostJitSelectedCodegenProfile>,
    /// Aggregate AArch64 optional-ISA evidence for every function in the
    /// executable buffer. Derived from the already-captured per-function
    /// evidence without rescanning machine instructions. Non-AArch64 JIT paths
    /// report `None`.
    pub aarch64_machine_code: Option<AArch64MachineCodeEvidence>,
    /// JIT-5 validation provenance: the resolved mode, the published-image
    /// hash the certificates bind to, and per-function coverage/cache
    /// provenance. `None` only for legacy result constructions that predate
    /// JIT-5; the JIT module path always populates it.
    pub validation: Option<JitValidationProvenance>,
    /// Inline-only (`AvailableExternally`) bodies this buffer's code rests on:
    /// every body spliced is a DISCLOSED one-definition-rule premise, not
    /// checked by this compile ([`crate::lir_module_prep`]); withheld bodies
    /// stayed external calls.
    pub inline_only_bodies: crate::lir_module_prep::InlineOnlyBodyEvidence,
    /// U10 stack-limit acknowledgments and the module reserve bound; `None`
    /// when no function requested a check.
    pub stack_limits: Option<StackLimitModuleReport>,
    /// The dialect legalization this buffer's module went through, as on
    /// [`CompilationResult::dialect_legalization`].
    pub dialect_legalization: Option<DialectLegalizationReport>,
}

impl std::fmt::Debug for JitCompilationResult {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("JitCompilationResult")
            .field("buffer_size", &self.buffer.allocated_size())
            .field("symbol_count", &self.buffer.symbol_count())
            .field("metrics", &self.metrics)
            .field("trace", &self.trace)
            .field("proofs", &self.proofs)
            .field(
                "proof_optimization_certificate_count",
                &self.proof_optimization_certificates.len(),
            )
            .field(
                "per_function_metrics_count",
                &self.per_function_metrics.len(),
            )
            .field(
                "host_jit_selected_codegen_profile_sha256",
                &self
                    .host_jit_selected_codegen_profile
                    .as_ref()
                    .map(HostJitSelectedCodegenProfile::profile_sha256),
            )
            .field("aarch64_machine_code", &self.aarch64_machine_code)
            .field("inline_only_bodies", &self.inline_only_bodies)
            .finish()
    }
}

/// Sealed effective options reserved by one consuming Core JIT plan.
///
/// This owner privately retains both the complete normalized compiler config
/// and the corresponding lower-level JIT config; the canonical policy is an
/// identity for those values, not a substitute from which later code must try
/// to reconstruct them. External resolution is forcibly narrowed to
/// [`JitExternalSymbolResolutionPolicy::ExplicitOnly`]. The machine profile
/// comes from Core admission rather than a second feature-policy selection.
/// Planning does not execute these options; a future compile-only owner must
/// consume this exact snapshot without ambient re-resolution.
#[derive(Clone)]
pub struct CoreJitEffectiveOptions {
    target_spec: TargetSpec,
    machine_profile: CoreHostJitMachineProfile,
    validation_mode: JitValidationMode,
    compiler_config: CompilerConfig,
    jit_config: crate::jit::JitConfig,
    compile_policy: CompilePolicy,
}

impl std::fmt::Debug for CoreJitEffectiveOptions {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("CoreJitEffectiveOptions")
            .field("target_spec", &self.target_spec)
            .field("machine_profile", &self.machine_profile)
            .field("validation_mode", &self.validation_mode)
            .field("opt_level", &self.compiler_config.opt_level)
            .field("emit_proofs", &self.compiler_config.emit_proofs)
            .field("emit_debug", &self.compiler_config.emit_debug)
            .field("parallel", &self.compiler_config.parallel)
            .field(
                "enable_jit_fast_regalloc",
                &self.compiler_config.enable_jit_fast_regalloc,
            )
            .field(
                "external_symbol_resolution",
                &self.jit_config.external_symbol_resolution,
            )
            .field("compile_policy_digests", &self.compile_policy.digests())
            .finish_non_exhaustive()
    }
}

impl PartialEq for CoreJitEffectiveOptions {
    fn eq(&self, other: &Self) -> bool {
        self.target_spec == other.target_spec
            && self.machine_profile == other.machine_profile
            && self.validation_mode == other.validation_mode
            && self.compile_policy == other.compile_policy
    }
}

