struct CoreAddressFreeMachineFunction {
    source_function: trust_ir::FuncId,
    name: String,
    text_align_log2: u8,
    // Deliberately no public byte accessor: only a later consuming typed-link
    // transition may move these normalized bytes toward executable memory.
    #[allow(dead_code)]
    code: Vec<u8>,
    normalized_code_digest: trust_ir::proof::ProofDigest,
    symbolic_fixup_manifest_digest: trust_ir::proof::ProofDigest,
    certificate_digest: trust_ir::proof::ProofDigest,
    certificate: crate::jit_cert::JitCertificate,
    /// The function's own stated target features
    /// (`MachFunction::function_target_features`); its evidence admits
    /// exactly the profile plus these. Read by the module evidence fold,
    /// which only the `verify` build compiles.
    #[cfg_attr(not(feature = "verify"), allow(dead_code))]
    function_target_features: TargetFeatureSet<AArch64IsaFeature>,
    machine_code_evidence: AArch64MachineCodeEvidence,
    /// Checked scalar callee prerequisites only. An unsupported/refused summary
    /// is retained honestly and changes no ordinary report or promotion grade.
    /// No caller instruction can obtain credit from this field alone.
    #[cfg(feature = "verify")]
    defined_callee: Result<
        Option<trust_cg_verify::aarch64_affine_lowering::DefinedAffineCallee>,
        trust_cg_verify::aarch64_affine_lowering::DefinedAffineCalleeError,
    >,
}

/// Move-only, non-callable output of policy-qualified Core machine
/// compilation.
///
/// The artifact contains normalized AArch64 bytes, a complete typed symbolic
/// fixup inventory, post-register-allocation feature evidence, and one
/// proof-grade certificate per function.  It contains no process addresses,
/// executable mapping, raw symbol resolver, or callable pointer.  The source
/// TrustIR share, strict LIR, and proof contexts are dropped on the successful
/// ownership transition; another immutable owner may still retain the TrustIR
/// graph. Failure returns the exact predecessor plan.
///
/// This is still not installation authority.  A later transition must bind
/// typed runtime providers, perform final layout/fixup patching, verify the
/// published image, and mint a distinct callable owner.
///
/// ```compile_fail
/// use trust_cg_codegen::CoreAddressFreeMachineArtifact;
///
/// fn requires_clone<T: Clone>() {}
/// requires_clone::<CoreAddressFreeMachineArtifact>();
/// ```
pub struct CoreAddressFreeMachineArtifact {
    receipt: IdentityTransformReceipt,
    target_contract: CoreTargetContract,
    declared_import_manifest: CoreDeclaredImportManifest,
    effective_options: CoreJitEffectiveOptions,
    native_runtime_catalog: CoreNativeRuntimeCatalog,
    native_dependency_references: CoreNativeDependencyReferenceMap,
    lir_native_dependency_bindings: CoreLirNativeDependencyBindings,
    retained_lir_proof_context_digest: trust_ir::proof::ProofDigest,
    predecessor_identity: CoreJitPlanIdentity,
    functions: Vec<CoreAddressFreeMachineFunction>,
    fixup_inventory: CoreAddressFreeFixupInventory,
    proof_optimization_certificates: Vec<ProofOptimizationCertificateCitation>,
    proof_report_count: usize,
    proof_bundle_digest: trust_ir::proof::ProofDigest,
    code_size_bytes: usize,
    machine_code_evidence: AArch64MachineCodeEvidence,
    identity: CoreAddressFreeMachineIdentity,
}

impl std::fmt::Debug for CoreAddressFreeMachineArtifact {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("CoreAddressFreeMachineArtifact")
            .field("module_digest", &self.module_digest())
            .field("target", &self.target_contract.target_spec())
            .field("function_count", &self.functions.len())
            .field("code_size_bytes", &self.code_size_bytes)
            .field("fixup_count", &self.fixup_inventory.entries.len())
            .field("proof_report_count", &self.proof_report_count)
            .field(
                "proof_optimization_certificate_count",
                &self.proof_optimization_certificates.len(),
            )
            .field("predecessor_identity", &self.predecessor_identity)
            .field("identity", &self.identity)
            .finish_non_exhaustive()
    }
}

