impl std::fmt::Debug for CoreJitCompilationPlan {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("CoreJitCompilationPlan")
            .field("module_name", &self.parts.module.name)
            .field("module_digest", &self.parts.receipt.core_module_digest())
            .field("retained_function_count", &self.parts.lir_functions.len())
            .field("effective_options", &self.effective_options)
            .field("native_runtime_catalog", &self.native_runtime_catalog)
            .field(
                "native_dependency_references",
                &self.native_dependency_references,
            )
            .field(
                "lir_native_dependency_bindings",
                &self.lir_native_dependency_bindings,
            )
            .field(
                "retained_lir_proof_context_digest",
                &self.retained_lir_proof_context_digest,
            )
            .field("identity", &self.identity)
            .finish_non_exhaustive()
    }
}

impl CoreJitCompilationPlan {
    /// Consume this sealed plan into the narrow policy owner required by a
    /// future proof-grade Core machine compiler.
    ///
    /// This transition is a pure, exhaustive policy and identity check. It
    /// performs no compilation and consults no process environment. On every
    /// rejection the exact input plan is returned in the failure, including
    /// its original TrustIR and strict-LIR allocations. Success means the
    /// complete retained strict LIR and every paired proof context still match
    /// the structured digest minted by planning.
    pub fn qualify_for_proof_grade_compilation(
        self,
    ) -> Result<PolicyQualifiedCoreJitCompilationPlan, CoreJitProofGradeQualificationFailure> {
        match qualify_proof_grade_core_jit_plan(&self) {
            Ok(fast_regalloc) => Ok(PolicyQualifiedCoreJitCompilationPlan {
                plan: self,
                fast_regalloc,
            }),
            Err(error) => Err(CoreJitProofGradeQualificationFailure { error, plan: self }),
        }
    }

    #[must_use]
    pub fn module_name(&self) -> &str {
        &self.parts.module.name
    }

    #[must_use]
    pub const fn module_digest(&self) -> trust_ir::proof::ProofDigest {
        self.parts.receipt.core_module_digest()
    }

    #[must_use]
    pub const fn permitted_native_mode(&self) -> CorePermittedNativeMode {
        self.parts.receipt.permitted_native_mode()
    }

    #[must_use]
    pub const fn target_contract(&self) -> &CoreTargetContract {
        &self.parts.target_contract
    }

    #[must_use]
    pub const fn declared_import_manifest(&self) -> &CoreDeclaredImportManifest {
        &self.parts.declared_import_manifest
    }

    #[must_use]
    pub const fn admission_receipt(&self) -> &IdentityTransformReceipt {
        &self.parts.receipt
    }

    #[must_use]
    pub const fn effective_options(&self) -> &CoreJitEffectiveOptions {
        &self.effective_options
    }

    /// Typed, address-free dependency catalog seed for machine compilation.
    ///
    /// This covers declared TrustIR imports only. A compile-only successor must
    /// add every backend-synthesized helper and prove final fixup closure before
    /// this can become a binding or installation manifest.
    #[must_use]
    pub const fn native_runtime_catalog(&self) -> &CoreNativeRuntimeCatalog {
        &self.native_runtime_catalog
    }

    /// Digest-bound imported `FuncId` to catalog dependency-ID sidecar.
    ///
    /// This is carried beside the retained strict LIR without exposing it. It
    /// contains no names or addresses and covers imported TrustIR function
    /// identities only; final LIR/fixup coverage remains a later transition.
    #[must_use]
    pub const fn native_dependency_references(&self) -> &CoreNativeDependencyReferenceMap {
        &self.native_dependency_references
    }

    /// Exhaustive, digest-bound strict-LIR call-site bindings for declared
    /// TrustIR imports. This does not claim backend-synthesized fixup closure.
    #[must_use]
    pub const fn lir_native_dependency_bindings(&self) -> &CoreLirNativeDependencyBindings {
        &self.lir_native_dependency_bindings
    }

    /// Complete, address-free identity of the retained strict LIR and every
    /// paired proof context, in retained function order.
    #[must_use]
    pub const fn retained_lir_proof_context_digest(&self) -> trust_ir::proof::ProofDigest {
        self.retained_lir_proof_context_digest
    }

    #[must_use]
    pub const fn identity(&self) -> CoreJitPlanIdentity {
        self.identity
    }

    #[must_use]
    pub fn retained_strict_function_count(&self) -> usize {
        self.parts.lir_functions.len()
    }

    #[must_use]
    pub const fn retained_exact_module_call_count(&self) -> usize {
        self.parts.receipt.exact_module_call_count()
    }

    #[must_use]
    pub const fn retained_declared_external_call_count(&self) -> usize {
        self.parts.receipt.declared_external_call_count()
    }
}

/// Check the complete currently exposed Core JIT policy without ambient
/// resolution. Destructuring the configuration owners without `..` makes a
/// newly added option a compile-time obligation for this boundary.
fn qualify_proof_grade_core_jit_plan(
    plan: &CoreJitCompilationPlan,
) -> Result<CoreJitFastRegallocSelection, CoreJitProofGradeQualificationError> {
    plan.parts.check_planned_integrity(
        &plan.native_runtime_catalog,
        &plan.native_dependency_references,
        &plan.lir_native_dependency_bindings,
    )?;
    // Keep the detailed source/catalog replay diagnostics above, then close
    // every remaining LIR and proof-context field before changing ownership.
    plan.parts
        .check_retained_lir_proof_context_integrity(plan.retained_lir_proof_context_digest)?;

    let CoreJitEffectiveOptions {
        target_spec,
        machine_profile,
        validation_mode,
        compiler_config,
        jit_config,
        compile_policy,
    } = &plan.effective_options;
    let admitted_target = plan.parts.target_contract.target_spec();
    if *target_spec != admitted_target {
        return Err(
            CoreJitProofGradeQualificationError::EffectiveTargetMismatch {
                effective: *target_spec,
                admitted: admitted_target,
            },
        );
    }
    let admitted_profile = plan.parts.target_contract.host_jit_machine_profile();
    if machine_profile.architecture() != target_spec.architecture {
        return Err(
            CoreJitProofGradeQualificationError::MachineProfileArchitectureMismatch {
                profile: machine_profile.architecture(),
                target: target_spec.architecture,
            },
        );
    }
    if *machine_profile != admitted_profile {
        return Err(
            CoreJitProofGradeQualificationError::EffectiveMachineProfileMismatch {
                effective: *machine_profile,
                admitted: admitted_profile,
            },
        );
    }

    let CompilerConfig {
        opt_level,
        target,
        emit_proofs,
        trace_level,
        emit_debug,
        parallel,
        cegis_superopt_budget_sec,
        enable_fsym_trust_ir_preflight,
        enable_jit_fast_regalloc,
        jit_validation_mode_override,
        jit_external_symbol_resolution,
        panic_unwind,
        relocation_model,
        function_sections,
        aarch64_isa_profile,
        aarch64_force_frame_pointers,
        never_inline,
        eh_frames_cannot_unwind,
        // Read only with `eh_frames_cannot_unwind`, which is refused below.
        eh_nounwind_callees: _,
        link_unit_definitions,
        x86_certificate_free_allocation,
    } = compiler_config;
    if *target != target_spec.architecture {
        return Err(
            CoreJitProofGradeQualificationError::CompilerTargetMismatch {
                compiler: *target,
                target: target_spec.architecture,
            },
        );
    }
    if *validation_mode != JitValidationMode::AlwaysVerify {
        return Err(CoreJitProofGradeQualificationError::ValidationMode {
            actual: *validation_mode,
        });
    }
    if *jit_validation_mode_override != Some(JitValidationMode::AlwaysVerify) {
        return Err(CoreJitProofGradeQualificationError::ValidationOverride {
            actual: *jit_validation_mode_override,
        });
    }
    if !emit_proofs {
        return Err(CoreJitProofGradeQualificationError::ProofEmissionDisabled);
    }
    if *trace_level != CompilerTraceLevel::None {
        return Err(CoreJitProofGradeQualificationError::TraceEnabled {
            actual: *trace_level,
        });
    }
    if *emit_debug {
        return Err(CoreJitProofGradeQualificationError::DebugEmissionEnabled);
    }
    if *parallel {
        return Err(CoreJitProofGradeQualificationError::ParallelCompilationEnabled);
    }
    if let Some(budget_sec) = *cegis_superopt_budget_sec {
        return Err(CoreJitProofGradeQualificationError::CegisEnabled { budget_sec });
    }
    if *enable_fsym_trust_ir_preflight {
        return Err(CoreJitProofGradeQualificationError::FsymPreflightEnabled);
    }
    if *panic_unwind {
        return Err(CoreJitProofGradeQualificationError::PanicUnwindEnabled);
    }
    if *relocation_model != RelocationModel::Static {
        return Err(CoreJitProofGradeQualificationError::RelocationModel {
            actual: *relocation_model,
        });
    }
    // An object-layout policy has no JIT meaning; like every other
    // non-default control it must not cross the proof-grade boundary silently.
    if *function_sections {
        return Err(CoreJitProofGradeQualificationError::FunctionSectionsEnabled);
    }
    // In-process JIT code has no modeled non-unwinding frame LSDA.
    if *eh_frames_cannot_unwind {
        return Err(CoreJitProofGradeQualificationError::EhFramesCannotUnwindEnabled);
    }
    // The JIT admits the host CPU's features; an explicit object profile
    // must not cross the proof-grade boundary.
    if let Some(actual) = *aarch64_isa_profile {
        return Err(CoreJitProofGradeQualificationError::ExplicitAarch64IsaProfile { actual });
    }
    if *aarch64_force_frame_pointers {
        return Err(CoreJitProofGradeQualificationError::ForcedAarch64FramePointers);
    }
    // A never-inline set changes which calls OPT-4 keeps; like every other
    // non-default control it must not cross the proof-grade boundary silently.
    if !never_inline.is_empty() {
        return Err(CoreJitProofGradeQualificationError::NeverInlineSet {
            count: never_inline.len(),
        });
    }
    // A link-unit definition set withholds body-theorem credit (OD-216); like
    // every other non-default control it must not cross the proof-grade
    // boundary silently.
    if !link_unit_definitions.is_empty() {
        return Err(
            CoreJitProofGradeQualificationError::LinkUnitDefinitionsSet {
                count: link_unit_definitions.len(),
            },
        );
    }
    // A certificate-free allocation policy is an object-compile control that
    // states certificates are not kept; it must not cross the proof-grade
    // boundary.
    if *x86_certificate_free_allocation {
        return Err(CoreJitProofGradeQualificationError::X86CertificateFreeAllocation);
    }
    if *jit_external_symbol_resolution != JitExternalSymbolResolutionPolicy::ExplicitOnly {
        return Err(
            CoreJitProofGradeQualificationError::CompilerExternalSymbolResolution {
                actual: *jit_external_symbol_resolution,
            },
        );
    }
    let fast_regalloc = CoreJitFastRegallocSelection::from_enabled(*enable_jit_fast_regalloc);
    // Intentionally spell every variant: a new optimization mode must not
    // cross the proof-grade boundary until its safety/performance policy has
    // been reviewed here.
    #[allow(clippy::needless_match)]
    let compiler_opt_level = match *opt_level {
        OptLevel::O0 => OptLevel::O0,
        OptLevel::O1 => OptLevel::O1,
        OptLevel::O2 => OptLevel::O2,
        OptLevel::O3 => OptLevel::O3,
    };

    let crate::jit::JitConfig {
        opt_level: jit_opt_level,
        verify,
        verify_dispatch,
        profile_hooks,
        emit_entry_counters,
        cache_certificates,
        external_symbol_resolution,
    } = jit_config;
    if *jit_opt_level != compiler_opt_level {
        return Err(
            CoreJitProofGradeQualificationError::JitOptimizationMismatch {
                compiler: compiler_opt_level,
                jit: *jit_opt_level,
            },
        );
    }
    if !verify {
        return Err(CoreJitProofGradeQualificationError::JitVerificationDisabled);
    }
    if *verify_dispatch != crate::pipeline::DispatchVerifyMode::ErrorOnFailure {
        return Err(
            CoreJitProofGradeQualificationError::JitDispatchVerification {
                actual: *verify_dispatch,
            },
        );
    }
    if *profile_hooks != crate::jit::ProfileHookMode::None {
        return Err(CoreJitProofGradeQualificationError::JitProfileHooks {
            actual: *profile_hooks,
        });
    }
    if *emit_entry_counters {
        return Err(CoreJitProofGradeQualificationError::JitEntryCountersEnabled);
    }
    if *cache_certificates {
        return Err(CoreJitProofGradeQualificationError::JitCertificateCacheEnabled);
    }
    if *external_symbol_resolution != JitExternalSymbolResolutionPolicy::ExplicitOnly {
        return Err(
            CoreJitProofGradeQualificationError::JitExternalSymbolResolution {
                actual: *external_symbol_resolution,
            },
        );
    }

    let reconstructed_policy = CompilePolicy::new(*target_spec, compiler_config, jit_config)?;
    if &reconstructed_policy != compile_policy {
        return Err(CoreJitProofGradeQualificationError::CompilePolicyIdentityMismatch);
    }
    let reconstructed_identity = CoreJitPlanIdentity::new(
        &plan.parts.receipt,
        &plan.native_runtime_catalog,
        &plan.native_dependency_references,
        &plan.lir_native_dependency_bindings,
        plan.retained_lir_proof_context_digest,
        reconstructed_policy.digests(),
    );
    if reconstructed_identity != plan.identity {
        return Err(CoreJitProofGradeQualificationError::PlanIdentityMismatch);
    }

    Ok(fast_regalloc)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[cfg(feature = "verify")]
struct ExpectedCoreCallOccurrence<'a> {
    callee: &'a str,
    digest: trust_cg_ir::SourceInstDigest,
    target: CoreAddressFreeFixupTarget,
}

#[cfg(feature = "verify")]
fn validate_core_aarch64_fixup_sites(
    function: &trust_cg_ir::MachFunction,
    code: &[u8],
    fixups: &crate::macho::fixup::FixupList,
    sites: &[crate::pipeline::EncodedAarch64FixupSite],
) -> Result<(), CoreAddressFreeMachineCompilationError> {
    if fixups.len() != sites.len() {
        return Err(
            CoreAddressFreeMachineCompilationError::FixupOccurrenceMismatch {
                caller: function.name.clone(),
                offset: 0,
                detail: format!(
                    "encoder returned {} fixups but {} originating sites",
                    fixups.len(),
                    sites.len()
                ),
            },
        );
    }

    // Derive the layout a second time from the final MachIR.  This walk does
    // not consume the encoder sidecar or fixup offsets, so a common-mode bug
    // that swaps two `(site, fixup)` rows cannot authenticate itself.
    let mut independently_derived = Vec::with_capacity(sites.len());
    let mut byte_offset = 0u32;
    for &block_id in &function.block_order {
        for &inst_id in &function.block(block_id).insts {
            let inst = function.inst(inst_id);
            if inst.is_pseudo() {
                continue;
            }
            let symbolic_branch = matches!(
                inst.opcode,
                trust_cg_ir::inst::AArch64Opcode::Bl
                    | trust_cg_ir::inst::AArch64Opcode::BL
                    | trust_cg_ir::inst::AArch64Opcode::B
                    | trust_cg_ir::inst::AArch64Opcode::TailCall
            ) && inst
                .operands
                .first()
                .is_some_and(|operand| operand.is_symbol());
            if symbolic_branch {
                independently_derived.push((block_id, inst_id, byte_offset, inst.opcode));
            }
            byte_offset = byte_offset
                .checked_add(4)
                .ok_or(CoreAddressFreeMachineCompilationError::IdentityLengthOverflow)?;
        }
    }
    if independently_derived.len() != sites.len() {
        return Err(
            CoreAddressFreeMachineCompilationError::FixupOccurrenceMismatch {
                caller: function.name.clone(),
                offset: 0,
                detail: format!(
                    "independent MachIR layout found {} symbolic branch sites but encoder reported {}",
                    independently_derived.len(),
                    sites.len()
                ),
            },
        );
    }

    let mut seen_offsets = HashSet::with_capacity(sites.len());
    for (fixup_index, ((fixup, site), expected_site)) in fixups
        .iter()
        .zip(sites)
        .zip(&independently_derived)
        .enumerate()
    {
        let &(expected_block, expected_inst, expected_offset, expected_opcode) = expected_site;
        if (
            site.block,
            site.inst,
            site.offset,
            site.opcode,
            site.fixup_index,
        ) != (
            expected_block,
            expected_inst,
            expected_offset,
            expected_opcode,
            fixup_index,
        ) {
            return Err(
                CoreAddressFreeMachineCompilationError::FixupOccurrenceMismatch {
                    caller: function.name.clone(),
                    offset: site.offset,
                    detail: format!(
                        "encoder site #{fixup_index} is ({:?}, {:?}, {}, {:?}, index {}), independent MachIR layout requires ({expected_block:?}, {expected_inst:?}, {expected_offset}, {expected_opcode:?}, index {fixup_index})",
                        site.block, site.inst, site.offset, site.opcode, site.fixup_index
                    ),
                },
            );
        }
        if fixup.offset != site.offset {
            return Err(
                CoreAddressFreeMachineCompilationError::FixupOccurrenceMismatch {
                    caller: function.name.clone(),
                    offset: fixup.offset,
                    detail: format!(
                        "fixup #{fixup_index} reports byte {} but its independently checked encoder site reports byte {}",
                        fixup.offset, site.offset
                    ),
                },
            );
        }
        if !seen_offsets.insert(site.offset) {
            return Err(
                CoreAddressFreeMachineCompilationError::FixupOccurrenceMismatch {
                    caller: function.name.clone(),
                    offset: site.offset,
                    detail: "more than one fixup occupies the same machine patch coordinate"
                        .to_owned(),
                },
            );
        }
        let offset_end = usize::try_from(site.offset)
            .ok()
            .and_then(|offset| offset.checked_add(4));
        if site.offset % 4 != 0 || offset_end.is_none_or(|end| end > code.len()) {
            return Err(CoreAddressFreeMachineCompilationError::FixupOutOfBounds {
                caller: function.name.clone(),
                offset: site.offset,
                code_len: code.len(),
            });
        }
        if !matches!(
            site.opcode,
            trust_cg_ir::inst::AArch64Opcode::Bl
                | trust_cg_ir::inst::AArch64Opcode::BL
                | trust_cg_ir::inst::AArch64Opcode::TailCall
        ) {
            return Err(
                CoreAddressFreeMachineCompilationError::FixupOccurrenceMismatch {
                    caller: function.name.clone(),
                    offset: site.offset,
                    detail: format!(
                        "Core direct call encoded from unsupported branch opcode {:?}",
                        site.opcode
                    ),
                },
            );
        }
        let op_bit = u32::from(!matches!(
            site.opcode,
            trust_cg_ir::inst::AArch64Opcode::TailCall
        ));
        let expected_placeholder = crate::aarch64::encoding::encode_uncond_branch(op_bit, 0);
        let start = usize::try_from(site.offset)
            .map_err(|_| CoreAddressFreeMachineCompilationError::IdentityLengthOverflow)?;
        let word = code
            .get(start..)
            .and_then(|bytes| bytes.first_chunk::<4>())
            .ok_or_else(
                || CoreAddressFreeMachineCompilationError::FixupOutOfBounds {
                    caller: function.name.clone(),
                    offset: site.offset,
                    code_len: code.len(),
                },
            )?;
        let actual_word = u32::from_le_bytes(*word);
        if site.placeholder_word != expected_placeholder || actual_word != expected_placeholder {
            return Err(
                CoreAddressFreeMachineCompilationError::FixupOccurrenceMismatch {
                    caller: function.name.clone(),
                    offset: site.offset,
                    detail: format!(
                        "expected canonical {} 0 placeholder {expected_placeholder:#010x}, encoder recorded {:#010x}, retained code contains {actual_word:#010x}",
                        if op_bit == 0 { "B" } else { "BL" },
                        site.placeholder_word
                    ),
                },
            );
        }
        if fixup.kind != crate::macho::reloc::AArch64RelocKind::Branch26
            || fixup.tls_model.is_some()
            || fixup.addend != 0
        {
            return Err(
                CoreAddressFreeMachineCompilationError::UnsupportedFixupEncoding {
                    caller: function.name.clone(),
                    offset: fixup.offset,
                    kind: fixup.kind,
                    tls: fixup.tls_model,
                    addend: fixup.addend,
                },
            );
        }
    }
    Ok(())
}

#[cfg(feature = "verify")]
// Core currently preserves the relative order of retained calls within each
// source block.  Enforce that deliberately conservative contract here: a
// future scheduler that can prove a legal split/re-layout must carry an
// explicit order certificate before this fail-closed check can be relaxed.
fn validate_core_lir_call_order(
    function: &trust_cg_ir::MachFunction,
    sites: &[crate::pipeline::EncodedAarch64FixupSite],
) -> Result<(), CoreAddressFreeMachineCompilationError> {
    let mut last_source_call_by_block = HashMap::new();
    for site in sites {
        let trust_cg_ir::LoweringProvenance::SourceInst { id: source, .. } =
            function.inst_lowering_provenance(site.inst)
        else {
            // The complete occurrence join below reports the richer missing
            // provenance diagnostic.  There is no source order to compare.
            continue;
        };
        if let Some(previous) = last_source_call_by_block.insert(source.block, source.index)
            && source.index <= previous
        {
            return Err(
                CoreAddressFreeMachineCompilationError::FixupOccurrenceMismatch {
                    caller: function.name.clone(),
                    offset: site.offset,
                    detail: format!(
                        "retained LIR calls in source block {} changed order: call index {} followed index {} in final machine layout",
                        source.block, source.index, previous
                    ),
                },
            );
        }
    }
    Ok(())
}

