/// O(1)-resident ordered commitment to the transient public proof rows.
///
/// The ordinary compiler API returns [`ProofCertificate`] strings to its
/// caller.  The consuming Core transition instead needs only their exact
/// ordered identity after applying the promotion gate.  Chaining a
/// purpose-separated digest per row avoids retaining a second module-sized
/// proof graph beside the per-function [`crate::jit_cert::JitCertificate`]s.
#[cfg(feature = "verify")]
struct CoreProofBundleAccumulator {
    count: usize,
    verified_count: usize,
    chain: trust_ir::proof::ProofDigest,
}

#[cfg(feature = "verify")]
impl CoreProofBundleAccumulator {
    fn new() -> Result<Self, CoreAddressFreeMachineCompilationError> {
        Ok(Self {
            count: 0,
            verified_count: 0,
            chain: core_address_free_encoded_digest(
                "trust-cg.core-address-free-proof-chain-seed.v2",
                |sink| core_identity_u32(sink, 2),
            )?,
        })
    }

    fn extend(
        &mut self,
        reports: &[ProofCertificate],
    ) -> Result<(), CoreAddressFreeMachineCompilationError> {
        for report in reports {
            let row = core_address_free_encoded_digest(
                "trust-cg.core-address-free-proof-row.v3",
                |sink| {
                    core_identity_u32(sink, 3)?;
                    core_identity_str(sink, &report.function_name)?;
                    core_identity_str(sink, &report.rule_name)?;
                    core_identity_str(sink, &report.category)?;
                    core_identity_str(sink, &report.strength)?;
                    let export = source_bound_export_identity(report);
                    core_identity_u8(sink, u8::from(export.is_some()))?;
                    if let Some(identity) = export {
                        core_identity_str(sink, &identity)?;
                    }
                    core_identity_u8(sink, u8::from(report.verified))
                },
            )?;
            let next_count = self
                .count
                .checked_add(1)
                .ok_or(CoreAddressFreeMachineCompilationError::IdentityLengthOverflow)?;
            self.chain = core_address_free_encoded_digest(
                "trust-cg.core-address-free-proof-chain-link.v2",
                |sink| {
                    core_identity_u32(sink, 2)?;
                    core_identity_len(sink, next_count)?;
                    core_identity_digest(sink, self.chain)?;
                    core_identity_digest(sink, row)
                },
            )?;
            self.count = next_count;
            self.verified_count += usize::from(report.verified);
        }
        Ok(())
    }

    const fn len(&self) -> usize {
        self.count
    }

    fn finish(
        self,
    ) -> Result<trust_ir::proof::ProofDigest, CoreAddressFreeMachineCompilationError> {
        core_address_free_encoded_digest("trust-cg.core-address-free-proof-bundle.v2", |sink| {
            core_identity_u32(sink, 2)?;
            core_identity_len(sink, self.count)?;
            core_identity_digest(sink, self.chain)
        })
    }
}

/// One sealed module's immutable source and verifier-request custody. The
/// identity transform retains the same module at both source endpoints. This
/// binds inputs, not the correctness of a call contract or machine lowering.
#[cfg(feature = "verify")]
struct CoreSourceVerification<'a> {
    source: trust_cg_verify::FunctionSourceModules<'a>,
    request: trust_cg_verify::FunctionVerificationRequest,
}

#[cfg(feature = "verify")]
impl<'a> CoreSourceVerification<'a> {
    fn capture(plan: &'a CoreJitCompilationPlan) -> Result<Self, CompileError> {
        let source =
            trust_cg_verify::FunctionSourceModules::capture(&plan.parts.module, &plan.parts.module)
                .map_err(|error| {
                    CompileError::Pipeline(PipelineError::NoTmbcWireImage(error.to_string()))
                })?;
        // Capture on the verifier stack, as the x86-64 certificate lane does:
        // capturing applies the request's policy as thread-local overrides,
        // which on the compiling thread would invalidate the environment
        // permit the address-free compile checks before it returns
        // (`CompilationEnvironmentChanged`). The worker runs with the
        // compiling thread's override snapshot installed, so it captures the
        // same policy.
        let request = crate::jit_cert::run_on_proof_verifier_stack(
            "trust-cg-core-address-free-proof-verifier",
            || {
                shared_aarch64_function_verifier().capture_request_with_mode(
                    trust_cg_verify::provenance_xcheck::ProvenanceXCheckMode::Enforce,
                )
            },
        );
        Ok(Self { source, request })
    }

    fn verify(
        &self,
        machine: &trust_cg_ir::MachFunction,
        lir: &trust_cg_lower::Function,
    ) -> (
        trust_cg_verify::CapturedFunctionVerificationReport,
        Vec<trust_cg_verify::SourceBoundArithmeticObligation>,
    ) {
        crate::jit_cert::run_on_proof_verifier_stack(
            "trust-cg-core-address-free-proof-verifier",
            || {
                shared_aarch64_function_verifier().verify_with_request_for_export_and_modules(
                    machine,
                    Some(lir),
                    &self.source,
                    &self.request,
                )
            },
        )
    }

    fn input_digest(
        &self,
        machine: &trust_cg_ir::MachFunction,
        lir: &trust_cg_lower::Function,
    ) -> Result<[u8; 32], crate::jit_cert::JitIdentityEncodingError> {
        crate::jit_cert::aarch64_verifier_input_digest_with_modules(
            machine,
            Some(lir),
            &self.source,
        )
    }
}

fn compile_policy_qualified_core_to_address_free_machine(
    qualified: &PolicyQualifiedCoreJitCompilationPlan,
    machine_rejection: &mut Option<CoreMachineProofRejection>,
) -> Result<PreparedCoreAddressFreeMachine, CoreAddressFreeMachineCompilationError> {
    match compile_policy_qualified_core_machine_mode(
        qualified,
        machine_rejection,
        CoreMachineEntryMode::Ordinary(std::marker::PhantomData),
    )? {
        #[cfg(feature = "verify")]
        CoreMachineCompilationOutcome::Ordinary(compiled) => Ok(compiled),
        #[cfg(feature = "verify")]
        CoreMachineCompilationOutcome::Conditional(_) => {
            Err(CompileError::CoreInstallationContract(
                "conditional peer cannot enter generic machine artifacts".into(),
            )
            .into())
        }
    }
}

fn compile_policy_qualified_core_machine_mode(
    qualified: &PolicyQualifiedCoreJitCompilationPlan,
    machine_rejection: &mut Option<CoreMachineProofRejection>,
    entry_mode: CoreMachineEntryMode<'_>,
) -> Result<CoreMachineCompilationOutcome, CoreAddressFreeMachineCompilationError> {
    // A recognized byte-entry label supplies no caller memory. Keep its
    // unbound generic artifact/report path closed; only the consuming mode
    // below can join genuine replay to actual initialized owned storage.
    #[cfg(feature = "verify")]
    if matches!(&entry_mode, CoreMachineEntryMode::Ordinary(_))
        && qualified
            .plan
            .parts
            .module
            .proof_certificates
            .iter()
            .any(|certificate| {
                certificate
                    .evidence
                    .clean_cic_kernel_recheck()
                    .is_some_and(|directive| {
                        directive.anchor
                            == trust_ir::proof::KERNEL_ANCHOR_CLEAN_BACKEND_BYTE_ENTRY_V1
                    })
            })
    {
        return Err(CompileError::CoreInstallationContract(
            "byte-entry source requires the owned context/output consumer".into(),
        )
        .into());
    }
    // A new source-family anchor is not an ordinary callable artifact. Its
    // genuine compiler replay must be joined to the four live memory owners.
    #[cfg(feature = "verify")]
    if matches!(&entry_mode, CoreMachineEntryMode::Ordinary(_))
        && qualified
            .plan
            .parts
            .module
            .proof_certificates
            .iter()
            .any(|certificate| {
                certificate
                    .evidence
                    .clean_cic_kernel_recheck()
                    .is_some_and(|directive| {
                        directive.anchor
                            == trust_ir::proof::KERNEL_ANCHOR_CLEAN_BACKEND_WORD_STATUS_ENTRY_V1
                    })
            })
    {
        return Err(CompileError::CoreInstallationContract(
            "word/status source requires the owned four-pointer/status consumer".into(),
        )
        .into());
    }
    #[cfg(not(feature = "verify"))]
    let _ = (machine_rejection, entry_mode);
    #[cfg(feature = "verify")]
    let peer_entry = match &entry_mode {
        CoreMachineEntryMode::Peer(entry) => Some(*entry),
        _ => None,
    };
    #[cfg(feature = "source-defined-call")]
    let mut entry_mode = entry_mode;
    crate::resource_limits::admit_compilation_budget().map_err(CompileError::from)?;
    let rechecked_fast_regalloc = qualify_proof_grade_core_jit_plan(&qualified.plan)?;
    if rechecked_fast_regalloc != qualified.fast_regalloc {
        return Err(CoreAddressFreeMachineCompilationError::PlanIntegrity(
            CoreJitProofGradeQualificationError::PlanIdentityMismatch,
        ));
    }

    let plan = &qualified.plan;
    let target = plan.effective_options.target_spec.architecture;
    if target != Target::Aarch64 {
        return Err(CoreAddressFreeMachineCompilationError::TargetUnsupported { target });
    }
    #[cfg(not(feature = "verify"))]
    {
        Err(CoreAddressFreeMachineCompilationError::Compile(
            CompileError::ProofsUnsupportedForTarget { target },
        ))
    }

    #[cfg(feature = "verify")]
    {
        let environment_permit = trust_cg_process_env::artifact_reuse_permit().ok_or(
            CoreAddressFreeMachineCompilationError::CompilationEnvironmentPermitUnavailable,
        )?;
        let aarch64_profile = plan
            .effective_options
            .machine_profile
            .aarch64()
            .ok_or(CoreAddressFreeMachineCompilationError::TargetUnsupported { target })?;
        ExceptionTableCensus::from_lir(&plan.parts.lir_functions)
            .refuse_proof_grade(ProofGradeRoute::ProofGradeJit, target)?;

        let pipeline = Pipeline::new(PipelineConfig {
            opt_level: plan.effective_options.compiler_config.opt_level,
            emit_debug: plan.effective_options.compiler_config.emit_debug,
            verify_dispatch: plan.effective_options.jit_config.verify_dispatch,
            // Qualification requires the retained JIT policy to request full
            // verification.  This consuming path realizes that policy once,
            // after final register allocation, below.  Enabling Pipeline's
            // earlier MachIR check as well would run the verifier twice and
            // discard the first report; the shared final report instead feeds
            // both proof promotion and JitCertificate construction.
            verify: false,
            cegis_superopt_budget_sec: plan
                .effective_options
                .compiler_config
                .cegis_superopt_budget_sec,
            target_triple: plan.effective_options.target_spec.triple(),
            enable_fsym_trust_ir_preflight: plan
                .effective_options
                .compiler_config
                .enable_fsym_trust_ir_preflight,
            enable_jit_fast_regalloc: qualified.fast_regalloc.is_enabled(),
            skip_cse_gvn: false,
            disabled_passes_override: None,
            contains4_scanner_batch_rewrite_override: None,
            relocation_model: RelocationModel::Static,
            aarch64_force_frame_pointers: plan
                .effective_options
                .compiler_config
                .aarch64_force_frame_pointers,
        })
        .with_aarch64_isa_profile(aarch64_profile)
        .with_raw_dataflow_policy(Aarch64DataflowIntegrityPolicy::ProofGradeEnforce);

        let mut defined_by_name: HashMap<&str, (trust_ir::FuncId, usize)> =
            HashMap::with_capacity(plan.parts.module.functions.len());
        let mut defined_by_id: HashMap<u32, &str> =
            HashMap::with_capacity(plan.parts.module.functions.len());
        for (module_ordinal, function) in plan
            .parts
            .module
            .functions
            .iter()
            .enumerate()
            .filter(|(_, function)| !function.blocks.is_empty())
        {
            if defined_by_name
                .insert(function.name.as_str(), (function.id, module_ordinal))
                .is_some()
                || defined_by_id
                    .insert(function.id.index(), function.name.as_str())
                    .is_some()
            {
                return Err(
                    CoreAddressFreeMachineCompilationError::DuplicateDefinedFunctionSymbol {
                        symbol: function.name.clone(),
                    },
                );
            }
        }

        // One source-owned census, not one whole-module scan per callee. Only
        // actual module definitions used by direct source calls need a scalar
        // prerequisite. No source/body/name or provider alias is inferred.
        let referenced_defined: HashSet<_> = plan
            .parts
            .module
            .functions
            .iter()
            .flat_map(|function| &function.blocks)
            .flat_map(|block| &block.body)
            .filter_map(|node| match &node.inst {
                trust_ir::Inst::Call { callee, .. }
                    if defined_by_id.contains_key(&callee.index()) =>
                {
                    Some(*callee)
                }
                _ => None,
            })
            .collect();

        let mut native_by_name: HashMap<&str, trust_cg_ir::NativeDependencyId> =
            HashMap::with_capacity(plan.native_runtime_catalog.entries().len());
        for entry in plan.native_runtime_catalog.entries() {
            if native_by_name.insert(entry.symbol(), entry.id()).is_some() {
                return Err(
                    CoreAddressFreeMachineCompilationError::MissingNativeFixupTarget {
                        caller: "<catalog>".to_owned(),
                        target: entry.symbol().to_owned(),
                    },
                );
            }
        }

        let mut functions = Vec::with_capacity(plan.parts.lir_functions.len());
        let mut fixup_entries = Vec::new();
        let mut expected_fixup_count = 0usize;
        let proof_gate_compiler = Compiler::new_for_target_spec(
            plan.effective_options.compiler_config.clone(),
            plan.effective_options.target_spec,
        );
        let mut proof_bundle = Some(CoreProofBundleAccumulator::new()?);
        let mut conditional_prepared = None;
        let mut proof_optimization_certificates = Vec::new();
        let mut code_size_bytes = 0usize;
        // Capture once, before the function loop or verifier worker. Reusing
        // these borrows avoids rehashing the module for every function, while
        // every report and certificate binds the same source endpoints.
        let verification = CoreSourceVerification::capture(plan)?;

        // The bounded fsym preflight scans each function in this module:
        // decide its module-level facts once for all of them.
        with_fsym_module_scope(&plan.parts.module, || {
            for (function_ordinal, lir_pair) in plan.parts.lir_functions.iter().enumerate() {
                let (lir_function, proof_context) = lir_pair;
                // Reuse the existing symbol index for exact module ownership. A
                // sparse FuncId or this LIR vector's ordinal is not a module index;
                // no second whole-module index/vector is needed for the pairing.
                let (caller, module_ordinal) = defined_by_name
                    .get(lir_function.name.as_str())
                    .copied()
                    .ok_or_else(|| {
                        CoreAddressFreeMachineCompilationError::MissingDefinedFunctionIdentity {
                            symbol: lir_function.name.clone(),
                        }
                    })?;
                // Build only this function's source-occurrence table.  Keeping the
                // correlation window function-local preserves streaming peak
                // memory while still requiring a one-to-one match after final
                // instruction selection, optimization, register allocation, and
                // encoding.
                let mut expected_calls = HashMap::new();
                for block_ref in lir_function.layout_order() {
                    let block = lir_function.blocks.get(&block_ref).ok_or_else(|| {
                        CoreAddressFreeMachineCompilationError::FixupOccurrenceMismatch {
                            caller: lir_function.name.clone(),
                            offset: 0,
                            detail: format!("layout references missing LIR block {}", block_ref.0),
                        }
                    })?;
                    for (index, instruction) in block.instructions.iter().enumerate() {
                        let trust_cg_lower::instructions::Opcode::Call { name, binding } =
                            &instruction.opcode
                        else {
                            continue;
                        };
                        let target = match *binding {
                            trust_cg_lower::instructions::DirectCallBinding::ExactModuleFunction {
                                function,
                            } => {
                                if !defined_by_id.contains_key(&function) {
                                    return Err(
                                        CoreAddressFreeMachineCompilationError::UnsealedLirCall {
                                            caller: lir_function.name.clone(),
                                            callee: name.clone(),
                                            binding: *binding,
                                        },
                                    );
                                }
                                CoreAddressFreeFixupTarget::ExactModuleFunction {
                                    function: trust_ir::FuncId::new(function),
                                }
                            }
                            trust_cg_lower::instructions::DirectCallBinding::NativeDependency {
                                dependency,
                                ..
                            } => {
                                let entry = plan.native_runtime_catalog.get(dependency).ok_or_else(
                                    || CoreAddressFreeMachineCompilationError::UnsealedLirCall {
                                        caller: lir_function.name.clone(),
                                        callee: name.clone(),
                                        binding: *binding,
                                    },
                                )?;
                                if entry.symbol() != name {
                                    return Err(
                                        CoreAddressFreeMachineCompilationError::UnsealedLirCall {
                                            caller: lir_function.name.clone(),
                                            callee: name.clone(),
                                            binding: *binding,
                                        },
                                    );
                                }
                                CoreAddressFreeFixupTarget::NativeDependency { dependency }
                            }
                            trust_cg_lower::instructions::DirectCallBinding::Interposable
                            | trust_cg_lower::instructions::DirectCallBinding::DeclaredExternalFunction {
                                ..
                            } => {
                                return Err(CoreAddressFreeMachineCompilationError::UnsealedLirCall {
                                    caller: lir_function.name.clone(),
                                    callee: name.clone(),
                                    binding: *binding,
                                });
                            }
                        };
                        let index = u32::try_from(index).map_err(|_| {
                            CoreAddressFreeMachineCompilationError::IdentityLengthOverflow
                        })?;
                        let source = trust_cg_ir::SourceInstId {
                            block: block_ref.0,
                            index,
                        };
                        let occurrence = ExpectedCoreCallOccurrence {
                            callee: name,
                            digest: instruction.lowering_digest(),
                            target,
                        };
                        if expected_calls.insert(source, occurrence).is_some() {
                            return Err(
                                CoreAddressFreeMachineCompilationError::FixupOccurrenceMismatch {
                                    caller: lir_function.name.clone(),
                                    offset: 0,
                                    detail: format!(
                                        "duplicate retained LIR call coordinate {source}"
                                    ),
                                },
                            );
                        }
                    }
                }
                expected_fixup_count = expected_fixup_count
                    .checked_add(expected_calls.len())
                    .ok_or(CoreAddressFreeMachineCompilationError::IdentityLengthOverflow)?;
                fixup_entries.reserve(expected_calls.len());

                let (machine_function, metrics) = pipeline
                    .prepare_function_with_metrics_for_sealed_core(
                        lir_function,
                        Some(proof_context),
                        &plan.parts.module,
                        module_ordinal,
                    )
                    .map_err(CompileError::Pipeline)?;
                validate_prepared_aarch64_dataflow_observations(
                    std::slice::from_ref(&machine_function),
                    std::slice::from_ref(lir_pair),
                    std::slice::from_ref(&metrics),
                    true,
                )?;

                let machine_code_evidence = aggregate_aarch64_jit_machine_code_evidence(
                    pipeline.aarch64_target_machine(),
                    std::iter::once((
                        machine_function.name.as_str(),
                        machine_function.function_target_features,
                        metrics.aarch64_machine_code,
                    )),
                )?;
                proof_optimization_certificates.extend(metrics.proof_optimization_certificates);

                #[cfg_attr(not(test), allow(unused_mut))]
                let (mut code, fixups, fixup_sites) = affine_bytes::encode_core_function(
                    &plan.parts.module,
                    module_ordinal,
                    lir_function,
                    &machine_function,
                )?;
                #[cfg(test)]
                crate::composed_transition::test_hooks::flip_published_byte(&mut code);
                // L09-P3: the sealed Core publishes these bytes; a function
                // its affine checks cover must carry a composed chain from
                // its TrustIR source to exactly them.
                crate::composed_transition::require_published(
                    &machine_function.name,
                    metrics.composed_transition.as_ref(),
                    &code,
                    fixups.len(),
                )
                .map_err(composed_transition_refused)?;
                code_size_bytes = code_size_bytes
                    .checked_add(code.len())
                    .ok_or(CoreAddressFreeMachineCompilationError::CodeSizeOverflow)?;
                validate_core_aarch64_fixup_sites(&machine_function, &code, &fixups, &fixup_sites)?;
                validate_core_lir_call_order(&machine_function, &fixup_sites)?;
                let fixup_manifest = crate::jit_cert::aarch64_symbolic_fixup_manifest(&fixups, 0)
                    .map_err(CompileError::from)?;
                let mut seen_sources = HashSet::with_capacity(expected_calls.len());

                for (fixup, site) in fixups.iter().zip(fixup_sites.iter()) {
                    let machine_inst = machine_function.inst(site.inst);
                    let machine_symbol = machine_inst
                        .operands
                        .first()
                        .and_then(|operand| operand.as_symbol())
                        .ok_or_else(|| {
                            CoreAddressFreeMachineCompilationError::FixupOccurrenceMismatch {
                                caller: machine_function.name.clone(),
                                offset: site.offset,
                                detail: "final BL has no symbolic target operand".to_owned(),
                            }
                        })?;
                    let provenance = machine_function.inst_lowering_provenance(site.inst);
                    let (source, source_digest) = match provenance {
                        trust_cg_ir::LoweringProvenance::SourceInst { id, digest, .. } => {
                            (id, digest)
                        }
                        trust_cg_ir::LoweringProvenance::Synthetic { reason } => {
                            return Err(
                                CoreAddressFreeMachineCompilationError::FixupOccurrenceMismatch {
                                    caller: machine_function.name.clone(),
                                    offset: site.offset,
                                    detail: format!(
                                        "final symbolic BL has no exact LIR source occurrence ({reason:?})"
                                    ),
                                },
                            );
                        }
                    };
                    let expected = expected_calls.get(&source).ok_or_else(|| {
                        CoreAddressFreeMachineCompilationError::FixupOccurrenceMismatch {
                            caller: machine_function.name.clone(),
                            offset: site.offset,
                            detail: format!(
                                "final symbolic BL cites {source}, which is not a retained direct call"
                            ),
                        }
                    })?;
                    if source_digest != expected.digest {
                        return Err(
                            CoreAddressFreeMachineCompilationError::FixupOccurrenceMismatch {
                                caller: machine_function.name.clone(),
                                offset: site.offset,
                                detail: format!(
                                    "source digest for {source} changed: expected {:?}, got {:?}",
                                    expected.digest, source_digest
                                ),
                            },
                        );
                    }
                    if !seen_sources.insert(source) {
                        return Err(
                            CoreAddressFreeMachineCompilationError::FixupOccurrenceMismatch {
                                caller: machine_function.name.clone(),
                                offset: site.offset,
                                detail: format!(
                                    "retained LIR call {source} produced more than one machine fixup"
                                ),
                            },
                        );
                    }
                    if machine_symbol != expected.callee {
                        return Err(
                            CoreAddressFreeMachineCompilationError::FixupOccurrenceMismatch {
                                caller: machine_function.name.clone(),
                                offset: site.offset,
                                detail: format!(
                                    "retained LIR call {source} names {:?}, final BL names {machine_symbol:?}",
                                    expected.callee
                                ),
                            },
                        );
                    }
                    let exact_module_flag = machine_inst
                        .flags
                        .contains(trust_cg_ir::inst::InstFlags::EXACT_MODULE_CALL);
                    let expects_exact_module = matches!(
                        expected.target,
                        CoreAddressFreeFixupTarget::ExactModuleFunction { .. }
                    );
                    if exact_module_flag != expects_exact_module {
                        return Err(
                            CoreAddressFreeMachineCompilationError::FixupOccurrenceMismatch {
                                caller: machine_function.name.clone(),
                                offset: site.offset,
                                detail: format!(
                                    "retained LIR call {source} exact-module policy is {expects_exact_module}, final BL flag is {exact_module_flag}"
                                ),
                            },
                        );
                    }
                    let (fixup_symbol, target) = match &fixup.target {
                        crate::macho::fixup::FixupTarget::ExactNamedSymbol(name) => {
                            let (function, _) = defined_by_name.get(name.as_str()).copied().ok_or_else(|| {
                                CoreAddressFreeMachineCompilationError::MissingExactModuleFixupTarget {
                                    caller: machine_function.name.clone(),
                                    target: name.clone(),
                                }
                            })?;
                            (
                                name.as_str(),
                                CoreAddressFreeFixupTarget::ExactModuleFunction { function },
                            )
                        }
                        crate::macho::fixup::FixupTarget::NamedSymbol(name) => {
                            if defined_by_name.contains_key(name.as_str()) {
                                return Err(
                                    CoreAddressFreeMachineCompilationError::InterposableModuleFixup {
                                        caller: machine_function.name.clone(),
                                        target: name.clone(),
                                    },
                                );
                            }
                            let dependency =
                                native_by_name.get(name.as_str()).copied().ok_or_else(|| {
                                    CoreAddressFreeMachineCompilationError::MissingNativeFixupTarget {
                                        caller: machine_function.name.clone(),
                                        target: name.clone(),
                                    }
                                })?;
                            (
                                name.as_str(),
                                CoreAddressFreeFixupTarget::NativeDependency { dependency },
                            )
                        }
                        other => {
                            return Err(
                                CoreAddressFreeMachineCompilationError::UnsupportedFixupTarget {
                                    caller: machine_function.name.clone(),
                                    offset: fixup.offset,
                                    target: other.clone(),
                                },
                            );
                        }
                    };
                    if fixup_symbol != machine_symbol || target != expected.target {
                        return Err(
                            CoreAddressFreeMachineCompilationError::FixupOccurrenceMismatch {
                                caller: machine_function.name.clone(),
                                offset: site.offset,
                                detail: format!(
                                    "retained LIR call {source} expects symbol {:?} and target {:?}, encoder fixup names {fixup_symbol:?} and target {target:?}",
                                    expected.callee, expected.target
                                ),
                            },
                        );
                    }
                    fixup_entries.push(CoreAddressFreeFixup {
                        caller,
                        function_ordinal,
                        offset: site.offset,
                        target,
                    });
                }
                if seen_sources.len() != expected_calls.len() {
                    let first_missing = expected_calls
                        .keys()
                        .filter(|source| !seen_sources.contains(source))
                        .min()
                        .map(ToString::to_string)
                        .unwrap_or_else(|| "unknown".to_owned());
                    return Err(
                        CoreAddressFreeMachineCompilationError::FixupBindingCoverageMismatch {
                            expected: expected_calls.len(),
                            actual: seen_sources.len(),
                            first_difference: format!(
                                "function {:?} retained call {first_missing} has no final machine fixup",
                                lir_function.name
                            ),
                        },
                    );
                }

                let (captured, obligations) = verification.verify(&machine_function, lir_function);
                if peer_entry == Some(machine_function.name.as_str()) {
                    let prepared = (|| {
                        let (final_code, link) = core_peer_link::prepare(
                            &verification,
                            caller,
                            lir_function,
                            &machine_function,
                            &code,
                            metrics.frame_layout.as_ref(),
                            &functions,
                            &fixup_entries,
                            &captured,
                            &plan.parts.lir_functions,
                        )
                        .map_err(CompileError::CoreInstallationContract)?;
                        if function_ordinal + 1 != plan.parts.lir_functions.len()
                            || expected_fixup_count != fixup_entries.len()
                        {
                            return Err(CompileError::CoreInstallationContract("conditional peer caller must close the complete function/fixup stream".into()).into());
                        }
                        let evidence = aggregate_aarch64_jit_machine_code_evidence(
                            pipeline.aarch64_target_machine(),
                            functions
                                .iter()
                                .map(|f| {
                                    (
                                        f.name.as_str(),
                                        f.function_target_features,
                                        Some(f.machine_code_evidence),
                                    )
                                })
                                .chain(std::iter::once((
                                    machine_function.name.as_str(),
                                    machine_function.function_target_features,
                                    Some(machine_code_evidence),
                                ))),
                        )?;
                        let verifier_input = verification
                            .input_digest(&machine_function, lir_function)
                            .map_err(CompileError::from)?;
                        let fixup_digest = core_address_free_fixup_inventory_digest(
                            plan.identity.artifact_cache_digest(),
                            plan.native_runtime_catalog.digest(),
                            &fixup_entries,
                        )?;
                        let inventory = CoreAddressFreeFixupInventory {
                            entries: std::mem::take(&mut fixup_entries),
                            digest: fixup_digest,
                        };
                        let symbolic_digest = trust_ir::proof::ProofDigest::sha256_domain(
                            "trust-cg.core-address-free-machine.symbolic-fixups.v1",
                            &fixup_manifest,
                        );
                        Ok::<_, CoreAddressFreeMachineCompilationError>((
                            final_code,
                            link,
                            evidence,
                            verifier_input,
                            inventory,
                            symbolic_digest,
                        ))
                    })();
                    match prepared {
                        Err(error) => {
                            *machine_rejection = Some(CoreMachineProofRejection {
                                source_function: caller,
                                machine: machine_function,
                                frame_layout: metrics.frame_layout,
                                bytes: code,
                                fixup_sites,
                                prior_functions: std::mem::take(&mut functions),
                                captured,
                                request: verification.request.clone(),
                            });
                            return Err(error);
                        }
                        Ok((
                            final_code,
                            mut link,
                            evidence,
                            verifier_input,
                            inventory,
                            symbolic_digest,
                        )) => {
                            link.bind_inventory(&inventory)
                                .map_err(CompileError::CoreInstallationContract)?;
                            conditional_prepared = Some(core_peer_entry::PreparedPeer {
                                previous: std::mem::take(&mut functions),
                                caller: machine_function,
                                source_function: caller,
                                final_code,
                                symbolic_digest,
                                verifier_input,
                                link,
                                inventory,
                                proof_bundle: proof_bundle
                                    .take()
                                    .expect("one consuming peer result"),
                                proof_optimization_certificates: std::mem::take(
                                    &mut proof_optimization_certificates,
                                ),
                                code_size_bytes,
                                machine_code_evidence: evidence,
                                caller_machine_code_evidence: machine_code_evidence,
                            });
                            drop(obligations);
                            return Ok(());
                        }
                    }
                }
                #[cfg(feature = "source-defined-call")]
                let context_owner = if let CoreMachineEntryMode::ContextOutput(context) =
                    &mut entry_mode
                {
                    if !functions.is_empty()
                        || plan.parts.lir_functions.len() != 1
                        || expected_fixup_count != 0
                        || !fixup_entries.is_empty()
                    {
                        return Err(CompileError::CoreInstallationContract(
                            "context/output requires complete empty fixup/call inventories".into(),
                        )
                        .into());
                    }
                    match context.bind(
                        &plan.parts.module,
                        &verification,
                        lir_function,
                        &machine_function,
                        &code,
                        &captured,
                    ) {
                        Ok(owner) => Some(owner),
                        Err(reason) => {
                            *machine_rejection = Some(CoreMachineProofRejection {
                                source_function: caller,
                                machine: machine_function,
                                frame_layout: metrics.frame_layout,
                                bytes: code,
                                fixup_sites,
                                prior_functions: std::mem::take(&mut functions),
                                captured,
                                request: verification.request.clone(),
                            });
                            return Err(CompileError::CoreInstallationContract(reason).into());
                        }
                    }
                } else {
                    None
                };
                #[cfg(feature = "source-defined-call")]
                let status_owner =
                    if let CoreMachineEntryMode::FourPointerStatus(status) = &mut entry_mode {
                        if !functions.is_empty()
                            || plan.parts.lir_functions.len() != 1
                            || expected_fixup_count != 0
                            || !fixup_entries.is_empty()
                        {
                            return Err(CompileError::CoreInstallationContract(
                            "four-pointer/status requires complete empty fixup/call inventories"
                                .into(),
                        )
                        .into());
                        }
                        match status.bind(
                            &plan.parts.module,
                            &verification,
                            lir_function,
                            &machine_function,
                            &code,
                            &captured,
                        ) {
                            Ok(owner) => Some(owner),
                            Err(reason) => {
                                *machine_rejection = Some(CoreMachineProofRejection {
                                    source_function: caller,
                                    machine: machine_function,
                                    frame_layout: metrics.frame_layout,
                                    bytes: code,
                                    fixup_sites,
                                    prior_functions: std::mem::take(&mut functions),
                                    captured,
                                    request: verification.request.clone(),
                                });
                                return Err(CompileError::CoreInstallationContract(reason).into());
                            }
                        }
                    } else {
                        None
                    };
                #[cfg(feature = "source-defined-call")]
                let status_report = status_owner
                    .as_ref()
                    .map(|owner| owner.report(&machine_function))
                    .transpose()
                    .map_err(CompileError::CoreInstallationContract)?;
                #[cfg(feature = "source-defined-call")]
                let context_report = context_owner
                    .as_ref()
                    .map(|owner| owner.report(&machine_function))
                    .transpose()
                    .map_err(CompileError::CoreInstallationContract)?;
                #[cfg(feature = "source-defined-call")]
                let report = status_report
                    .as_ref()
                    .or(context_report.as_ref())
                    .unwrap_or_else(|| captured.report());
                #[cfg(not(feature = "source-defined-call"))]
                let report = captured.report();
                // `affine_bytes::encode_core_function` encodes through
                // `encode_function_with_fixups_and_sites`, which runs ENC-5
                // under the proof-grade policy (enforce) on every call.
                #[cfg(feature = "source-defined-call")]
                let selected_obligations = if context_owner.is_some() || status_owner.is_some() {
                    &[][..]
                } else {
                    obligations.as_slice()
                };
                #[cfg(not(feature = "source-defined-call"))]
                let selected_obligations = obligations.as_slice();
                let mut function_proofs = proof_certificates_from_aarch64_report_with_obligations(
                    report,
                    selected_obligations,
                    crate::decode_check::DecodeCheckBacking::Enforced,
                );
                carry_request_ay_refusal_note(&mut function_proofs, captured.ay_refusal_note());
                drop(obligations);
                if let Err(error) =
                    proof_gate_compiler.ensure_proofs_promotable(Some(&function_proofs))
                {
                    *machine_rejection = Some(CoreMachineProofRejection {
                        source_function: caller,
                        machine: machine_function,
                        frame_layout: metrics.frame_layout,
                        bytes: code,
                        fixup_sites,
                        prior_functions: std::mem::take(&mut functions),
                        captured,
                        request: verification.request.clone(),
                    });
                    return Err(error.into());
                }
                proof_bundle
                    .as_mut()
                    .expect("live proof hash accumulator")
                    .extend(&function_proofs)?;
                drop(function_proofs);

                let raw_code_digest = crate::jit_cert::sha256_digest(&code);
                let verifier_input_digest = verification
                    .input_digest(&machine_function, lir_function)
                    .map_err(CompileError::from)?;
                let code_len = u64::try_from(code.len())
                    .map_err(|_| CoreAddressFreeMachineCompilationError::IdentityLengthOverflow)?;
                let certificate = crate::jit_cert::JitCertificate::from_report_for_core_artifact(
                    &machine_function,
                    report,
                    0..code_len,
                    verifier_input_digest,
                    raw_code_digest,
                )
                .with_checked_structural_return(&captured, &machine_function, Some(lir_function))
                .with_request_ay_refusal_note(captured.ay_refusal_note());
                #[cfg(feature = "source-defined-call")]
                let certificate = if let Some(owner) = &context_owner {
                    certificate.with_physically_bound_context_output(owner)
                } else if let Some(owner) = &status_owner {
                    certificate.with_physically_bound_four_pointer_status(owner)
                } else {
                    certificate
                };
                let certificate_verified = certificate.has_checked_semantics();
                let certificate_replayable = certificate.replay_check();
                if !certificate_verified || !certificate_replayable {
                    let inventory = report.emitted_opcode_inventory();
                    return Err(
                        CoreAddressFreeMachineCompilationError::MachineCertificateRejected {
                            function: machine_function.name.clone(),
                            certificate_verified,
                            certificate_replayable,
                            total: report.total(),
                            genuinely_verified: report.genuinely_verified_count(),
                            degenerate_verified: report.degenerate_verified_count(),
                            sampled_uncredited: report.sampled_uncredited_count(),
                            registry_name_lookup: report.registry_name_lookup_count(),
                            instruction_derived: report.instruction_derived_count(),
                            unverified: report.unverified_count(),
                            skipped: report.skipped_count(),
                            failed: report.failed_count(),
                            inventory_verdict: inventory
                                .promotion_rejection_reason()
                                .unwrap_or_else(|| "opcode inventory is promotable".to_owned()),
                            ay_refusal_note: certificate.ay_refusal_note().map(str::to_owned),
                        },
                    );
                }
                let certificate_digest = trust_ir::proof::ProofDigest::sha256(
                    certificate
                        .core_semantic_digest()
                        .ok_or(CoreAddressFreeMachineCompilationError::IdentityLengthOverflow)?,
                );
                // Mint only after the actual ordinary proof/certificate gates
                // accepted this callee. The constructor independently checks
                // original/LIR/word semantics and the same captured request;
                // it invokes no solver and creates no replacement budget.
                let defined_callee = if referenced_defined.contains(&caller) {
                    trust_cg_verify::aarch64_affine_lowering::DefinedAffineCallee::bind(
                        &verification.source,
                        &verification.request,
                        &captured,
                        caller,
                        lir_function,
                        &machine_function,
                        &code,
                    )
                    .map(Some)
                } else {
                    Ok(None)
                };
                let normalized_code_digest = trust_ir::proof::ProofDigest::sha256(raw_code_digest);
                let symbolic_fixup_manifest_digest = trust_ir::proof::ProofDigest::sha256_domain(
                    "trust-cg.core-address-free-machine.symbolic-fixups.v1",
                    &fixup_manifest,
                );
                functions.push(CoreAddressFreeMachineFunction {
                    source_function: caller,
                    name: machine_function.name.clone(),
                    text_align_log2: machine_function.text_align_log2,
                    code,
                    normalized_code_digest,
                    symbolic_fixup_manifest_digest,
                    certificate_digest,
                    certificate,
                    function_target_features: machine_function.function_target_features,
                    machine_code_evidence,
                    defined_callee,
                });
            }
            Ok::<(), CoreAddressFreeMachineCompilationError>(())
        })?;

        if let Some(prepared) = conditional_prepared {
            if !environment_permit.is_valid() {
                return Err(CoreAddressFreeMachineCompilationError::CompilationEnvironmentChanged);
            }
            if qualify_proof_grade_core_jit_plan(plan)? != qualified.fast_regalloc {
                return Err(CoreAddressFreeMachineCompilationError::PlanIntegrity(
                    CoreJitProofGradeQualificationError::PlanIdentityMismatch,
                ));
            }
            return Ok(CoreMachineCompilationOutcome::Conditional(prepared));
        }
        if peer_entry.is_some() {
            return Err(CompileError::CoreInstallationContract(
                "requested conditional peer entry was not produced".into(),
            )
            .into());
        }
        if fixup_entries.len() != expected_fixup_count {
            return Err(
                CoreAddressFreeMachineCompilationError::FixupBindingCoverageMismatch {
                    expected: expected_fixup_count,
                    actual: fixup_entries.len(),
                    first_difference:
                        "per-function occurrence checks passed but module totals differ".to_owned(),
                },
            );
        }

        fixup_entries.sort_unstable_by_key(|entry| (entry.function_ordinal, entry.offset));
        if fixup_entries.windows(2).any(|pair| {
            (pair[0].function_ordinal, pair[0].offset) == (pair[1].function_ordinal, pair[1].offset)
        }) {
            return Err(
                CoreAddressFreeMachineCompilationError::FixupBindingCoverageMismatch {
                    expected: expected_fixup_count,
                    actual: fixup_entries.len(),
                    first_difference: "duplicate machine patch coordinate".to_owned(),
                },
            );
        }

        let proof_bundle =
            proof_bundle.expect("ordinary compilation retains its proof hash accumulator");
        let proof_report_count = proof_bundle.len();
        let verified_proof_report_count = proof_bundle.verified_count;
        let proof_bundle_digest = proof_bundle.finish()?;
        let proof_optimization_digest =
            core_address_free_proof_optimization_digest(&proof_optimization_certificates)?;

        let fixup_inventory_digest = core_address_free_fixup_inventory_digest(
            plan.identity.artifact_cache_digest(),
            plan.native_runtime_catalog.digest(),
            &fixup_entries,
        )?;
        let fixup_inventory = CoreAddressFreeFixupInventory {
            entries: fixup_entries,
            digest: fixup_inventory_digest,
        };
        let machine_code_evidence = aggregate_aarch64_jit_machine_code_evidence(
            pipeline.aarch64_target_machine(),
            functions.iter().map(|function| {
                (
                    function.name.as_str(),
                    function.function_target_features,
                    Some(function.machine_code_evidence),
                )
            }),
        )?;
        let identity = core_address_free_machine_identity(
            plan,
            &functions,
            &fixup_inventory,
            proof_bundle_digest,
            proof_optimization_digest,
        )?;

        if !environment_permit.is_valid() {
            return Err(CoreAddressFreeMachineCompilationError::CompilationEnvironmentChanged);
        }
        let final_fast_regalloc = qualify_proof_grade_core_jit_plan(plan)?;
        if final_fast_regalloc != qualified.fast_regalloc {
            return Err(CoreAddressFreeMachineCompilationError::PlanIntegrity(
                CoreJitProofGradeQualificationError::PlanIdentityMismatch,
            ));
        }

        Ok(CoreMachineCompilationOutcome::Ordinary(
            PreparedCoreAddressFreeMachine {
                functions,
                fixup_inventory,
                proof_optimization_certificates,
                proof_report_count,
                verified_proof_report_count,
                proof_bundle_digest,
                code_size_bytes,
                machine_code_evidence,
                identity,
            },
        ))
    }
}

fn into_core_address_free_machine_artifact(
    qualified: PolicyQualifiedCoreJitCompilationPlan,
    compiled: PreparedCoreAddressFreeMachine,
) -> CoreAddressFreeMachineArtifact {
    let (artifact, source) =
        into_core_address_free_machine_artifact_with_source(qualified, compiled);
    let CoreCompilationSource {
        module,
        lir_functions,
    } = source;
    drop(module);
    drop(lir_functions);
    artifact
}

fn into_core_address_free_machine_artifact_with_source(
    qualified: PolicyQualifiedCoreJitCompilationPlan,
    compiled: PreparedCoreAddressFreeMachine,
) -> (CoreAddressFreeMachineArtifact, CoreCompilationSource) {
    let PolicyQualifiedCoreJitCompilationPlan {
        plan,
        fast_regalloc: _,
    } = qualified;
    let CoreJitCompilationPlan {
        parts,
        effective_options,
        native_runtime_catalog,
        native_dependency_references,
        lir_native_dependency_bindings,
        retained_lir_proof_context_digest,
        identity: predecessor_identity,
    } = plan;
    let CoreConsumableParts {
        module,
        target_contract,
        declared_import_manifest,
        receipt,
        lir_functions,
    } = parts;

    let source = CoreCompilationSource {
        module,
        lir_functions,
    };
    let artifact = CoreAddressFreeMachineArtifact {
        receipt,
        target_contract,
        declared_import_manifest,
        effective_options,
        native_runtime_catalog,
        native_dependency_references,
        lir_native_dependency_bindings,
        retained_lir_proof_context_digest,
        predecessor_identity,
        functions: compiled.functions,
        fixup_inventory: compiled.fixup_inventory,
        proof_optimization_certificates: compiled.proof_optimization_certificates,
        proof_report_count: compiled.proof_report_count,
        proof_bundle_digest: compiled.proof_bundle_digest,
        code_size_bytes: compiled.code_size_bytes,
        machine_code_evidence: compiled.machine_code_evidence,
        identity: compiled.identity,
    };
    (artifact, source)
}

#[cfg(feature = "verify")]
trait CoreMachineIdentitySink {
    fn write(&mut self, bytes: &[u8]) -> Result<(), CoreAddressFreeMachineCompilationError>;
}

#[derive(Default)]
#[cfg(feature = "verify")]
struct CoreMachineIdentityCount(u64);

#[cfg(feature = "verify")]
impl CoreMachineIdentitySink for CoreMachineIdentityCount {
    fn write(&mut self, bytes: &[u8]) -> Result<(), CoreAddressFreeMachineCompilationError> {
        let len = u64::try_from(bytes.len())
            .map_err(|_| CoreAddressFreeMachineCompilationError::IdentityLengthOverflow)?;
        self.0 = self
            .0
            .checked_add(len)
            .ok_or(CoreAddressFreeMachineCompilationError::IdentityLengthOverflow)?;
        Ok(())
    }
}

#[cfg(feature = "verify")]
struct CoreMachineIdentityHash<'a>(&'a mut trust_ir::proof::ProofDigestSha256DomainStream);

#[cfg(feature = "verify")]
impl CoreMachineIdentitySink for CoreMachineIdentityHash<'_> {
    fn write(&mut self, bytes: &[u8]) -> Result<(), CoreAddressFreeMachineCompilationError> {
        self.0.update(bytes)?;
        Ok(())
    }
}

#[cfg(feature = "verify")]
fn core_address_free_encoded_digest(
    domain: &'static str,
    encode: impl Fn(
        &mut dyn CoreMachineIdentitySink,
    ) -> Result<(), CoreAddressFreeMachineCompilationError>,
) -> Result<trust_ir::proof::ProofDigest, CoreAddressFreeMachineCompilationError> {
    let mut count = CoreMachineIdentityCount::default();
    encode(&mut count)?;
    let mut stream = trust_ir::proof::ProofDigest::sha256_domain_stream(domain, count.0);
    encode(&mut CoreMachineIdentityHash(&mut stream))?;
    Ok(stream.finish()?)
}

#[cfg(feature = "verify")]
fn core_identity_u8(
    sink: &mut dyn CoreMachineIdentitySink,
    value: u8,
) -> Result<(), CoreAddressFreeMachineCompilationError> {
    sink.write(&[value])
}

#[cfg(feature = "verify")]
fn core_identity_u32(
    sink: &mut dyn CoreMachineIdentitySink,
    value: u32,
) -> Result<(), CoreAddressFreeMachineCompilationError> {
    sink.write(&value.to_be_bytes())
}

#[cfg(feature = "verify")]
fn core_identity_u64(
    sink: &mut dyn CoreMachineIdentitySink,
    value: u64,
) -> Result<(), CoreAddressFreeMachineCompilationError> {
    sink.write(&value.to_be_bytes())
}

#[cfg(feature = "verify")]
fn core_identity_len(
    sink: &mut dyn CoreMachineIdentitySink,
    value: usize,
) -> Result<(), CoreAddressFreeMachineCompilationError> {
    core_identity_u64(
        sink,
        u64::try_from(value)
            .map_err(|_| CoreAddressFreeMachineCompilationError::IdentityLengthOverflow)?,
    )
}

#[cfg(feature = "verify")]
fn core_identity_bytes(
    sink: &mut dyn CoreMachineIdentitySink,
    bytes: &[u8],
) -> Result<(), CoreAddressFreeMachineCompilationError> {
    core_identity_len(sink, bytes.len())?;
    sink.write(bytes)
}

#[cfg(feature = "verify")]
fn core_identity_str(
    sink: &mut dyn CoreMachineIdentitySink,
    value: &str,
) -> Result<(), CoreAddressFreeMachineCompilationError> {
    core_identity_bytes(sink, value.as_bytes())
}

#[cfg(feature = "verify")]
fn core_identity_option_str(
    sink: &mut dyn CoreMachineIdentitySink,
    value: Option<&str>,
) -> Result<(), CoreAddressFreeMachineCompilationError> {
    match value {
        None => core_identity_u8(sink, 0),
        Some(value) => {
            core_identity_u8(sink, 1)?;
            core_identity_str(sink, value)
        }
    }
}

#[cfg(feature = "verify")]
fn core_identity_digest(
    sink: &mut dyn CoreMachineIdentitySink,
    digest: trust_ir::proof::ProofDigest,
) -> Result<(), CoreAddressFreeMachineCompilationError> {
    core_identity_u8(
        sink,
        match digest.algorithm {
            trust_ir::proof::ProofDigestAlgorithm::Sha256 => 0,
            trust_ir::proof::ProofDigestAlgorithm::TrustIrStableV1 => 1,
        },
    )?;
    sink.write(&digest.bytes)
}

#[cfg(feature = "verify")]
fn core_address_free_fixup_inventory_digest(
    plan_digest: trust_ir::proof::ProofDigest,
    catalog_digest: trust_ir::proof::ProofDigest,
    entries: &[CoreAddressFreeFixup],
) -> Result<trust_ir::proof::ProofDigest, CoreAddressFreeMachineCompilationError> {
    core_address_free_encoded_digest("trust-cg.core-address-free-fixup-inventory.v1", |sink| {
        core_identity_u32(sink, 1)?;
        core_identity_digest(sink, plan_digest)?;
        core_identity_digest(sink, catalog_digest)?;
        core_identity_len(sink, entries.len())?;
        for entry in entries {
            core_identity_u32(sink, entry.caller.index())?;
            core_identity_u64(
                sink,
                u64::try_from(entry.function_ordinal)
                    .map_err(|_| CoreAddressFreeMachineCompilationError::IdentityLengthOverflow)?,
            )?;
            core_identity_u32(sink, entry.offset)?;
            match entry.target {
                CoreAddressFreeFixupTarget::ExactModuleFunction { function } => {
                    core_identity_u8(sink, 0)?;
                    core_identity_u32(sink, function.index())?;
                }
                CoreAddressFreeFixupTarget::NativeDependency { dependency } => {
                    core_identity_u8(sink, 1)?;
                    core_identity_u32(sink, dependency.index())?;
                }
            }
        }
        Ok(())
    })
}

#[cfg(feature = "verify")]
fn core_address_free_proof_optimization_digest(
    certificates: &[ProofOptimizationCertificateCitation],
) -> Result<trust_ir::proof::ProofDigest, CoreAddressFreeMachineCompilationError> {
    core_address_free_encoded_digest(
        "trust-cg.core-address-free-proof-optimizations.v1",
        |sink| {
            core_identity_u32(sink, 1)?;
            core_identity_len(sink, certificates.len())?;
            for certificate in certificates {
                let ProofOptimizationCertificateCitation {
                    function_name,
                    certificate_id,
                    proof_hash,
                    validation_hash,
                    source_region_hash,
                    target_region_hash,
                    transform_name,
                    transform_version,
                    admission,
                    kind,
                    status,
                    rejection_code,
                    rejection_fact,
                    rejection_detail,
                    consumed_facts,
                } = certificate;
                core_identity_str(sink, function_name)?;
                core_identity_str(sink, certificate_id)?;
                core_identity_str(sink, proof_hash)?;
                core_identity_str(sink, validation_hash)?;
                core_identity_str(sink, source_region_hash)?;
                core_identity_str(sink, target_region_hash)?;
                core_identity_str(sink, transform_name)?;
                core_identity_u32(sink, *transform_version)?;
                core_identity_str(sink, admission)?;
                core_identity_str(sink, kind)?;
                core_identity_str(sink, status)?;
                core_identity_option_str(sink, rejection_code.as_deref())?;
                core_identity_option_str(sink, rejection_fact.as_deref())?;
                core_identity_option_str(sink, rejection_detail.as_deref())?;
                core_identity_len(sink, consumed_facts.len())?;
                for fact in consumed_facts {
                    let crate::pipeline::ProofOptimizationConsumedFactCitation { name, payload } =
                        fact;
                    core_identity_str(sink, name)?;
                    core_identity_option_str(sink, payload.as_deref())?;
                }
            }
            Ok(())
        },
    )
}

#[cfg(feature = "verify")]
fn core_address_free_machine_identity(
    plan: &CoreJitCompilationPlan,
    functions: &[CoreAddressFreeMachineFunction],
    fixups: &CoreAddressFreeFixupInventory,
    proof_bundle_digest: trust_ir::proof::ProofDigest,
    proof_optimization_digest: trust_ir::proof::ProofDigest,
) -> Result<CoreAddressFreeMachineIdentity, CoreAddressFreeMachineCompilationError> {
    core_address_free_machine_identity_from_parts(
        plan.identity,
        &plan.parts.receipt,
        &plan.parts.target_contract,
        &plan.native_runtime_catalog,
        &plan.native_dependency_references,
        &plan.lir_native_dependency_bindings,
        functions,
        fixups,
        proof_bundle_digest,
        proof_optimization_digest,
    )
}

#[cfg(feature = "verify")]
#[allow(clippy::too_many_arguments)]
fn core_address_free_machine_identity_from_parts(
    predecessor: CoreJitPlanIdentity,
    receipt: &IdentityTransformReceipt,
    target: &CoreTargetContract,
    catalog: &CoreNativeRuntimeCatalog,
    references: &CoreNativeDependencyReferenceMap,
    lir_bindings: &CoreLirNativeDependencyBindings,
    functions: &[CoreAddressFreeMachineFunction],
    fixups: &CoreAddressFreeFixupInventory,
    proof_bundle_digest: trust_ir::proof::ProofDigest,
    proof_optimization_digest: trust_ir::proof::ProofDigest,
) -> Result<CoreAddressFreeMachineIdentity, CoreAddressFreeMachineCompilationError> {
    let artifact_cache_digest = core_address_free_encoded_digest(
        "trust-cg.core-address-free-machine.artifact-cache.v2",
        |sink| {
            core_identity_u32(sink, 2)?;
            core_identity_digest(sink, predecessor.artifact_cache_digest())?;
            core_identity_digest(sink, receipt.receipt_digest())?;
            core_identity_digest(sink, target.digest())?;
            core_identity_digest(sink, catalog.digest())?;
            core_identity_digest(sink, references.digest())?;
            core_identity_digest(sink, lir_bindings.digest())?;
            core_identity_digest(sink, fixups.digest())?;
            core_identity_len(sink, functions.len())?;
            for function in functions {
                core_identity_u32(sink, function.source_function.index())?;
                core_identity_str(sink, &function.name)?;
                core_identity_u8(sink, function.text_align_log2)?;
                // `normalized_code_digest` is the exact SHA-256 of `code`.
                // Compose that already-computed commitment plus the explicit
                // byte length instead of streaming every machine byte through
                // a second module hash pass.
                core_identity_len(sink, function.code.len())?;
                core_identity_digest(sink, function.normalized_code_digest)?;
                core_identity_digest(sink, function.symbolic_fixup_manifest_digest)?;
                core_identity_u64(
                    sink,
                    function.machine_code_evidence.admitted_features().bits(),
                )?;
                core_identity_u64(
                    sink,
                    function.machine_code_evidence.required_features().bits(),
                )?;
            }
            Ok(())
        },
    )?;
    let verification_digest = core_address_free_encoded_digest(
        "trust-cg.core-address-free-machine.verification.v1",
        |sink| {
            core_identity_u32(sink, 1)?;
            core_identity_digest(sink, predecessor.verification_digest())?;
            core_identity_digest(sink, artifact_cache_digest)?;
            core_identity_digest(sink, proof_bundle_digest)?;
            core_identity_digest(sink, proof_optimization_digest)?;
            core_identity_len(sink, functions.len())?;
            for function in functions {
                core_identity_u32(sink, function.source_function.index())?;
                core_identity_digest(sink, function.certificate_digest)?;
            }
            Ok(())
        },
    )?;
    let full_digest =
        core_address_free_encoded_digest("trust-cg.core-address-free-machine.full.v1", |sink| {
            core_identity_u32(sink, 1)?;
            core_identity_digest(sink, predecessor.full_digest())?;
            core_identity_digest(sink, artifact_cache_digest)?;
            core_identity_digest(sink, verification_digest)?;
            Ok(())
        })?;
    Ok(CoreAddressFreeMachineIdentity {
        artifact_cache_digest,
        verification_digest,
        full_digest,
    })
}

fn core_jit_plan_identity_digest(
    domain: &'static str,
    receipt: &IdentityTransformReceipt,
    catalog: &CoreNativeRuntimeCatalog,
    references: &CoreNativeDependencyReferenceMap,
    bindings: &CoreLirNativeDependencyBindings,
    retained_lir_proof_context_digest: trust_ir::proof::ProofDigest,
    policy_digests: &[&[u8; 32]],
) -> trust_ir::proof::ProofDigest {
    let mut bytes = Vec::with_capacity(6 * 33 + policy_digests.len() * 32);
    for digest in [
        receipt.receipt_digest(),
        receipt.core_module_digest(),
        catalog.digest(),
        references.digest(),
        bindings.digest(),
        retained_lir_proof_context_digest,
    ] {
        bytes.push(match digest.algorithm {
            trust_ir::proof::ProofDigestAlgorithm::Sha256 => 0,
            trust_ir::proof::ProofDigestAlgorithm::TrustIrStableV1 => 1,
        });
        bytes.extend_from_slice(&digest.bytes);
    }
    for policy_digest in policy_digests {
        bytes.extend_from_slice(*policy_digest);
    }
    trust_ir::proof::ProofDigest::sha256_domain(domain, &bytes)
}

/// Fold per-function AArch64 machine-code evidence into one module record.
///
/// Each item names a function, the target features its own source states
/// (`MachFunction::function_target_features`, empty for an attribute-free
/// function) and its post-RA evidence. A function's evidence must carry the
/// target identity and exactly the admission this pipeline gives that
/// function: the profile plus its stated features
/// ([`crate::target::TargetMachine::for_function`]). A superset reached by
/// any other route is refused, so the fold never widens a function's
/// admission beyond what it states.
fn aggregate_aarch64_jit_machine_code_evidence<'a>(
    target_machine: &AArch64TargetMachine,
    evidence: impl IntoIterator<
        Item = (
            &'a str,
            TargetFeatureSet<AArch64IsaFeature>,
            Option<AArch64MachineCodeEvidence>,
        ),
    >,
) -> Result<AArch64MachineCodeEvidence, CompileError> {
    let expected_target = *target_machine.identity();
    let invalid = |error: TargetMachineError<AArch64IsaFeature>| {
        CompileError::Aarch64MachineCodeEvidenceInvalid {
            detail: error.to_string(),
        }
    };
    let mut required_features = OutputTargetFeatures::NONE;
    let mut function_features = TargetFeatureSet::EMPTY;
    let mut saw_function = false;

    for (function_name, stated_features, evidence) in evidence {
        saw_function = true;
        let evidence = evidence.ok_or_else(|| CompileError::Aarch64MachineCodeEvidenceMissing {
            function_name: function_name.to_owned(),
        })?;
        let expected_admitted = target_machine
            .for_function(stated_features)
            .map_err(invalid)?
            .admitted_features();
        if evidence.target() != expected_target || evidence.admitted_features() != expected_admitted
        {
            return Err(CompileError::Aarch64MachineCodeEvidencePipelineMismatch {
                function_name: function_name.to_owned(),
                expected_target,
                actual_target: evidence.target(),
                expected_admitted: AArch64IsaProfile::from_admitted_target_features(
                    expected_admitted,
                ),
                actual_admitted: AArch64IsaProfile::from_admitted_target_features(
                    evidence.admitted_features(),
                ),
            });
        }
        required_features = required_features.union(evidence.required_features());
        function_features = function_features.union(stated_features);
    }

    if !saw_function {
        return Err(CompileError::Aarch64MachineCodeEvidenceMissing {
            function_name: "<module>".to_owned(),
        });
    }

    // The module admission is the profile plus the functions' own features:
    // exactly the profile when no function states any.
    let module_machine = target_machine
        .for_function(function_features)
        .map_err(invalid)?;
    AArch64MachineCodeEvidence::try_new(&module_machine, required_features).map_err(invalid)
}

fn validate_x86_host_jit_selected_codegen_features<'a>(
    expected_pipeline_features: X86TargetFeatures,
    evidence: impl IntoIterator<Item = (&'a str, X86TargetFeatures)>,
) -> Result<X86TargetFeatures, CompileError> {
    let mut evidence = evidence.into_iter();
    let Some((reference_function, reference_features)) = evidence.next() else {
        return Err(CompileError::HostJitSelectedCodegenFeaturesMissing);
    };
    if reference_features != expected_pipeline_features {
        return Err(
            CompileError::HostJitSelectedCodegenFeaturesPipelineMismatch {
                function_name: reference_function.to_owned(),
                expected: expected_pipeline_features.metadata_feature_list(),
                actual: reference_features.metadata_feature_list(),
            },
        );
    }
    for (function_name, actual_features) in evidence {
        if actual_features != reference_features {
            return Err(CompileError::HostJitSelectedCodegenFeaturesNonUniform {
                reference_function: reference_function.to_owned(),
                reference_features: reference_features.metadata_feature_list(),
                function_name: function_name.to_owned(),
                actual_features: actual_features.metadata_feature_list(),
            });
        }
    }
    Ok(reference_features)
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/// Count the number of real (non-pseudo) machine instructions in a function.
///
/// Walks blocks in layout order and counts instructions that will actually be
/// encoded to machine code. Pseudo-instructions (Phi, Copy, StackAlloc, Nop,
/// etc.) are excluded since they have no hardware encoding.
fn count_real_instructions(func: &trust_cg_ir::MachFunction) -> usize {
    func.block_order
        .iter()
        .map(|&block_id| {
            func.blocks[block_id.0 as usize]
                .insts
                .iter()
                .filter(|&&inst_id| !func.insts[inst_id.0 as usize].is_pseudo())
                .count()
        })
        .sum()
}

/// Count branch-like instructions for coarse per-function density metrics.
///
/// The JIT path currently prepares AArch64 `MachFunction`s, so this helper
/// recognizes AArch64 branch / return opcodes directly and also counts any
/// non-pseudo terminator flagged in the IR.
fn count_branch_instructions(func: &trust_cg_ir::MachFunction) -> usize {
    func.block_order
        .iter()
        .map(|&block_id| {
            func.blocks[block_id.0 as usize]
                .insts
                .iter()
                .filter(|&&inst_id| {
                    let inst = &func.insts[inst_id.0 as usize];
                    !inst.is_pseudo()
                        && (inst.is_terminator()
                            || matches!(
                                inst.opcode,
                                trust_cg_ir::inst::AArch64Opcode::B
                                    | trust_cg_ir::inst::AArch64Opcode::BCond
                                    | trust_cg_ir::inst::AArch64Opcode::Bcc
                                    | trust_cg_ir::inst::AArch64Opcode::Cbz
                                    | trust_cg_ir::inst::AArch64Opcode::Cbnz
                                    | trust_cg_ir::inst::AArch64Opcode::Tbz
                                    | trust_cg_ir::inst::AArch64Opcode::Tbnz
                                    | trust_cg_ir::inst::AArch64Opcode::Br
                                    | trust_cg_ir::inst::AArch64Opcode::Bl
                                    | trust_cg_ir::inst::AArch64Opcode::BL
                                    | trust_cg_ir::inst::AArch64Opcode::Ret
                            ))
                })
                .count()
        })
        .sum()
}

fn collect_proof_optimization_certificates(
    metrics: &[crate::pipeline::PreparationMetrics],
) -> Vec<ProofOptimizationCertificateCitation> {
    metrics
        .iter()
        .flat_map(|metrics| metrics.proof_optimization_certificates.iter().cloned())
        .collect()
}

#[cfg(feature = "verify")]
fn collect_certified_pass_runs(
    metrics: &[crate::pipeline::PreparationMetrics],
) -> Vec<trust_cg_opt::CertifiedPassRunRecord> {
    metrics
        .iter()
        .flat_map(|metrics| metrics.certified_pass_runs.iter().cloned())
        .collect()
}

/// Every function's pass-validation verdicts, merged.
fn merge_pass_validation(
    metrics: &[crate::pipeline::PreparationMetrics],
) -> trust_cg_opt::PassValidationSummary {
    let mut summary = trust_cg_opt::PassValidationSummary::default();
    for metrics in metrics {
        summary.merge(&metrics.pass_validation);
    }
    summary
}

/// Each prepared function's composed transition record (L09-P3), in
/// preparation order.
fn collect_composed_transitions(
    metrics: &[crate::pipeline::PreparationMetrics],
) -> Vec<trust_cg_verify::composed_transition::TransitionRecord> {
    metrics
        .iter()
        .filter_map(|metrics| metrics.composed_transition.clone())
        .collect()
}

/// L09-P3: refuse unless every prepared function a TrustIR-bound
/// legalization check covers carries a record that composes at
/// exactly-decided strength or better. The proof-required routes run this
/// right after preparation, before any certificate is generated or promoted,
/// and bind the composed bytes to what they publish afterwards. Returns the
/// number of functions whose composition is required.
fn require_prepared_compositions(
    prepared_funcs: &[trust_cg_ir::MachFunction],
    metrics: &[crate::pipeline::PreparationMetrics],
) -> Result<usize, CompileError> {
    let mut required = 0;
    for (func, metrics) in prepared_funcs.iter().zip(metrics) {
        if crate::composed_transition::require_composition(
            &func.name,
            metrics.composed_transition.as_ref(),
        )
        .map_err(composed_transition_refused)?
        .is_some()
        {
            required += 1;
        }
    }
    Ok(required)
}

/// A composition refusal as the compile error of an AArch64 route.
fn composed_transition_refused(
    refusal: trust_cg_verify::composed_transition::CompositionRefusal,
) -> CompileError {
    CompileError::ComposedTransitionRefused {
        target: Target::Aarch64,
        refusal: Box::new(refusal),
    }
}

fn summarize_fsym_trust_ir_metrics(
    metrics: &[crate::pipeline::PreparationMetrics],
) -> FsymTrustIrMetrics {
    let mut summary = FsymTrustIrMetrics::default();
    for metrics in metrics {
        let Some(fsym) = &metrics.fsym_trust_ir_summary else {
            continue;
        };
        if fsym.scanned {
            summary.scanned_functions += 1;
        }
        if fsym.skipped.is_some() {
            summary.skipped_functions += 1;
        }
        summary.concrete_ub_diagnostics += fsym.diagnostic_count;
        summary.unknown_obligations += fsym.unknown_obligation_count;
        summary.warnings += fsym.warning_count;
    }
    summary
}

fn summarize_proof_optimizations(
    certificates: &[ProofOptimizationCertificateCitation],
) -> ProofOptimizationMetrics {
    let mut metrics = ProofOptimizationMetrics {
        certificate_count: certificates.len(),
        ..ProofOptimizationMetrics::default()
    };

    for certificate in certificates {
        let is_applied = certificate.status == "applied";
        let is_rejected = certificate.status == "rejected";
        let is_guard = certificate.kind == "GuardEliminated";
        let cites_non_zero_divisor = citation_mentions_fact(certificate, "NonZeroDivisor");
        let cites_valid_shift = citation_mentions_fact(certificate, "ValidShift");

        if is_applied {
            metrics.applied_count += 1;
        }
        if is_rejected {
            metrics.rejected_count += 1;
        }
        if is_applied && is_guard {
            metrics.guard_eliminated_count += 1;
            if cites_non_zero_divisor {
                metrics.non_zero_divisor_guard_eliminated_count += 1;
            }
            if cites_valid_shift {
                metrics.valid_shift_guard_eliminated_count += 1;
            }
        }
        if is_rejected && is_guard {
            metrics.guard_rejected_count += 1;
            if cites_non_zero_divisor {
                metrics.non_zero_divisor_guard_rejected_count += 1;
            }
            if cites_valid_shift {
                metrics.valid_shift_guard_rejected_count += 1;
            }
        }
    }

    metrics
}

fn citation_mentions_fact(
    certificate: &ProofOptimizationCertificateCitation,
    fact_name: &str,
) -> bool {
    certificate
        .consumed_facts
        .iter()
        .any(|fact| fact.name == fact_name)
        || certificate.rejection_fact.as_deref() == Some(fact_name)
}

/// Fail closed on exception-handling structure in the x86 JIT path.
///
/// The in-memory JIT registers no unwind tables of its own, so a JIT-compiled
/// function carrying EH structure would run without any (aborting / leaking on
/// unwind). The AOT Mach-O and ELF OBJECT paths emit theirs; x86 JIT unwinding
/// is a later lane, so this residual gate keeps the opt-in unwind feature from
/// ever producing a JIT function without unwind tables. EH structure is only
/// produced under the `TCG_ENABLE_UNWIND` frontend opt-in (default OFF), so this
/// gate is inert for the standard corpus.
fn reject_x86_jit_eh(
    lir_functions: &[(trust_cg_lower::Function, trust_cg_lower::ProofContext)],
) -> Result<(), CompileError> {
    for (lir_func, _) in lir_functions {
        if !lir_func.eh_info.is_empty() {
            return Err(CompileError::Pipeline(PipelineError::Unwind(format!(
                "x86-64 exception handling (LSDA / personality / eh_frame) is not \
                 supported in the JIT for `{}`: unwind tables are emitted only on \
                 the AOT object paths (Mach-O and ELF); the in-memory JIT has no \
                 eh_frame. Fail-closed to avoid running a function without unwind \
                 tables.",
                lir_func.name
            ))));
        }
    }
    Ok(())
}

/// What [`CompileError::ExceptionTablesUnproved`] says about the refused
/// function: its own exception-handling structure, or the whole-program
/// `panic=unwind` walk-through tables an emitter gave it.
fn exception_table_subject(function: &str, walk_through: &bool) -> String {
    if *walk_through {
        format!(
            "`{function}` has no exception-handling structure of its own, but whole-program \
             `panic=unwind` gives it walk-through exception tables (a filler LSDA and a \
             personality reference)"
        )
    } else {
        format!(
            "`{function}` has exception-handling structure (an LSDA and a personality \
             reference)"
        )
    }
}

/// A proof-grade route that could publish exception-handling tables.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum ProofGradeRoute {
    /// A certified (proof-required) object compile: AArch64 or x86-64 AOT.
    CertifiedObject,
    /// A proof-grade JIT request (AlwaysVerify, CachedVerified, emit_proofs,
    /// relocation replay, the policy-qualified core compiler).
    ProofGradeJit,
}

/// Which functions of one compilation unit carry exception-handling
/// structure: an LSDA and a personality reference.
///
/// Exception tables — the LSDA, the personality reference (the ELF
/// `DW.ref` slot, the Mach-O GOT slot or compact-unwind field) and the unwind
/// tables that register them — carry structural checks and native execution
/// tests but no proof obligation (trusted base TB-12). This census and
/// [`Self::refuse_proof_grade`] are the ONE decision every proof-grade route
/// makes about them: the certified object routes through
/// `Compiler::ensure_object_proofs_promotable`, and the proof-grade AArch64
/// JIT routes directly, so the object and JIT decisions cannot drift apart.
/// The JIT additionally refuses `panic_unwind` walk-through tables on its own
/// (in-memory registration has no proof path either); certified objects keep
/// the walk-through `.eh_frame` CFI of frames without EH, which is disclosed
/// as trusted (TB-12) in the relocation-inventory certificate, not refused.
///
/// The census does not consult the exception-table obligations of ledger
/// L03-P14 that AArch64 Darwin objects and JIT images pass at emission
/// (`trust_cg_verify::eh_obligations`): they are decided in process, which
/// the evidence policy treats as testing grade (OD-139), and no
/// Clean-checked certificate of them exists (decision record
/// OD-EH-OBLIGATIONS-TESTING-GRADE-20261012).
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub(crate) struct ExceptionTableCensus {
    /// Each function whose object form carries exception tables, in first-seen
    /// order, with whether they are walk-through tables only.
    functions: Vec<(String, bool)>,
    /// Some function of the unit fails `validate_eh_structure` — one with EH
    /// metadata, or one whose EH opcodes (a `Resume`, a `LandingPad`) have
    /// none.
    malformed: bool,
}

impl ExceptionTableCensus {
    /// The functions of `lir_functions` whose EH structure is non-empty, and
    /// whether any function of the unit is structurally malformed.
    pub(crate) fn from_lir(
        lir_functions: &[(trust_cg_lower::Function, trust_cg_lower::ProofContext)],
    ) -> Self {
        Self {
            functions: lir_functions
                .iter()
                .filter(|(function, _)| !function.eh_info.is_empty())
                .map(|(function, _)| (function.name.clone(), false))
                .collect(),
            malformed: lir_functions
                .iter()
                .any(|(function, _)| function.validate_eh_structure().is_err()),
        }
    }

    fn add(&mut self, function: &str, walk_through: bool) {
        if !self.functions.iter().any(|(name, _)| name == function) {
            self.functions.push((function.to_string(), walk_through));
        }
    }

    /// Also count every prepared machine function that carries EH metadata,
    /// which is what the AArch64 object emitters read.
    pub(crate) fn with_machine_functions(
        mut self,
        functions: &[trust_cg_ir::MachFunction],
    ) -> Self {
        for function in functions {
            if function.eh_metadata.has_eh_info() {
                self.add(&function.name, false);
            }
        }
        self
    }

    /// Also count the functions an object emitter gives an LSDA and a
    /// personality reference, `true` marking walk-through tables of a function
    /// without EH structure of its own
    /// ([`crate::x86_64::X86Pipeline::exception_table_functions`]).
    #[cfg(any(test, feature = "verify"))]
    pub(crate) fn with_functions(
        mut self,
        functions: impl IntoIterator<Item = (String, bool)>,
    ) -> Self {
        for (function, walk_through) in functions {
            self.add(&function, walk_through);
        }
        self
    }

    /// The first function whose object form carries exception tables, if any.
    #[cfg(test)]
    pub(crate) fn first(&self) -> Option<&str> {
        self.functions.first().map(|(name, _)| name.as_str())
    }

    /// Refuse the unit on `route` when any function's object form carries
    /// exception tables.
    pub(crate) fn refuse_proof_grade(
        &self,
        route: ProofGradeRoute,
        target: Target,
    ) -> Result<(), CompileError> {
        let Some((function, walk_through)) = self.functions.first().cloned() else {
            return Ok(());
        };
        Err(match route {
            ProofGradeRoute::CertifiedObject => CompileError::ExceptionTablesUnproved {
                target,
                function,
                walk_through,
            },
            ProofGradeRoute::ProofGradeJit => {
                CompileError::Jit(crate::jit::JitError::JitUnwindProofEvidenceUnavailable {
                    function,
                })
            }
        })
    }

    /// [`Self::refuse_proof_grade`] for the early LIR gates, except when an EH
    /// function's structure is malformed: the structural validation that
    /// runs next on every object route (instruction selection) then refuses
    /// it by name, the more precise diagnostic. Later gates and the promotion
    /// backstop use the strict form.
    pub(crate) fn refuse_well_formed_proof_grade(
        &self,
        route: ProofGradeRoute,
        target: Target,
    ) -> Result<(), CompileError> {
        if self.malformed {
            return Ok(());
        }
        self.refuse_proof_grade(route, target)
    }
}

/// Fail closed on exception-handling structure for AOT output formats whose
/// x86-64 emitter carries no unwind tables.
///
/// Mach-O (`__eh_frame` + `__gcc_except_tab` + compact unwind) and ELF
/// (`.eh_frame` + `.gcc_except_table` + the `DW.ref.<personality>` slot) both
/// wire the LSDA, the zPLR FDE and the personality, so an EH function targeting
/// either flows through to emission. COFF has no `.pdata`/`.xdata`
/// language-level EH path, so an EH function targeting it still fails closed
/// rather than shipping an object without unwind tables. Inert for the corpus
/// (`TCG_ENABLE_UNWIND` OFF), which produces no EH structure at all.
fn reject_x86_eh_for_unwired_aot_format(
    lir_functions: &[(trust_cg_lower::Function, trust_cg_lower::ProofContext)],
    output_format: crate::x86_64::X86OutputFormat,
) -> Result<(), CompileError> {
    use crate::x86_64::X86OutputFormat;
    let unwired = match output_format {
        X86OutputFormat::MachO | X86OutputFormat::Elf => return Ok(()),
        X86OutputFormat::Coff => "COFF (no .pdata/.xdata language-level EH path)",
        X86OutputFormat::RawBytes => "raw bytes (no object container at all)",
    };
    for (lir_func, _) in lir_functions {
        if !lir_func.eh_info.is_empty() {
            return Err(CompileError::Pipeline(PipelineError::Unwind(format!(
                "x86-64 exception handling (LSDA / personality / eh_frame) is emitted \
                 for Mach-O and ELF objects; `{}` targets {unwired}, which gets no \
                 unwind tables. Fail-closed to avoid emitting an object without \
                 unwind tables.",
                lir_func.name
            ))));
        }
    }
    Ok(())
}

fn count_x86_real_instructions(func: &trust_cg_lower::x86_64_isel::X86ISelFunction) -> usize {
    func.block_order
        .iter()
        .filter_map(|block| func.blocks.get(block))
        .map(|block| {
            block
                .insts
                .iter()
                .filter(|inst| !inst.opcode.is_pseudo())
                .count()
        })
        .sum()
}

/// Sentinel S5 hardening — map a compile [`Target`] to the [`GuardCarrierArch`]
/// whose carrier expander will materialize a surviving exact-bound `InBounds`
/// guard, so the adapter's per-arch bound cap matches the backend that will
/// actually encode the runtime check.
fn guard_carrier_arch_for_target(target: Target) -> trust_cg_lower::GuardCarrierArch {
    match target {
        Target::Aarch64 => trust_cg_lower::GuardCarrierArch::AArch64,
        Target::X86_64 => trust_cg_lower::GuardCarrierArch::X86_64,
        Target::Riscv64 => trust_cg_lower::GuardCarrierArch::Riscv64,
    }
}

/// The x86-64 C register ABI a compile for `spec` selects.
///
/// SINGLE SOURCE for that choice. The AOT x86 dispatcher's `X86PipelineConfig`
/// and the fail-closed Swift-witness check that has to agree with it both read
/// this, instead of each spelling the same `match` on
/// `target_spec.operating_system`.
pub(crate) fn x86_call_abi_for_target_spec(
    spec: TargetSpec,
) -> trust_cg_lower::x86_64_isel::X86CallAbi {
    match spec.operating_system {
        TargetOperatingSystem::Windows => trust_cg_lower::x86_64_isel::X86CallAbi::WindowsX64,
        _ => trust_cg_lower::x86_64_isel::X86CallAbi::SystemV,
    }
}

/// Fail closed BEFORE lowering when this compile's x86-64 C ABI has no
/// witnessed `swiftcc` placement.
///
/// [`guard_carrier_arch_for_target`] above maps every x86-64 triple — Darwin,
/// Linux AND `x86_64-pc-windows-msvc` — onto the single
/// `GuardCarrierArch::X86_64` variant, so the adapter's Swift return budget
/// physically cannot tell the two x86 C ABIs apart; that budget is System V's
/// (RAX,RDX / XMM0,XMM1), measured against clang's x86-64 `swiftcall`. Windows
/// x64 returns a single scalar in RAX or XMM0 and has no measured `swiftcc`
/// placement in this tree at all.
///
/// The compile driver is the only layer that knows the target OS, so the
/// refusal lives here. It is a STRICTLY COARSER rule than the adapter's
/// per-signature subset — it refuses every Swift edge, not a subset — so the
/// two cannot disagree about a signature; they can only both refuse.
pub(crate) fn reject_unwitnessed_swift_conv_for_spec(
    module: &trust_ir::Module,
    spec: TargetSpec,
) -> Result<(), trust_cg_lower::AdapterError> {
    if spec.architecture != Target::X86_64 {
        return Ok(());
    }
    trust_cg_lower::reject_unwitnessed_swift_conv_for_x86_abi(
        module,
        x86_call_abi_for_target_spec(spec),
    )
}

/// Run the x86 fail-closed guard pass.  Production supplies empty replay evidence and bindings, so
/// all carriers are retained; the structural kernel and re-check remain exercised for future wiring.
/// CT-5 / BENCH-8 guard for compiler proof-promotion verifiers.
///
/// Their explicit `SourceBoundReplay` policy may invoke current AY for a
/// checked source-bound frame or arithmetic obligation without an environment
/// opt-in. Conservatively keep
/// certificate generation and speculative discharge serial even when AY is
/// absent or explicitly disabled; that can cost parallelism but can never enter
/// the BENCH-8 parallel-solver nondeterminism class.
// Consumed only by the `verify`-gated cert lane in `compile_x86_64`.
#[cfg_attr(not(feature = "verify"), allow(dead_code))]
const fn proof_promotion_live_solver_may_run() -> bool {
    true
}

fn run_x86_guard_kernel_gate(
    isel_func: &mut trust_cg_lower::x86_64_isel::X86ISelFunction,
    _proof_ctx: &trust_cg_lower::ProofContext,
    _trust_ir_module: &trust_ir::Module,
    eliminated_total: &mut u32,
) -> Result<(), String> {
    use trust_cg_opt::x86_proof_opts::X86ProofGuardElimination;

    // Nothing to gate if ISel bound no carrier to an obligation.
    if isel_func.guard_obligations.is_empty() {
        return Ok(());
    }

    // Public Trust-IR status/lineage, ProofRef labels, and adapter-synthesized ids are diagnostic
    // metadata, not exact replay authority.  Deliberately supply neither evidence nor carrier
    // bindings.  The structural `guard_obligations` map remains on `isel_func` for reports.
    let evidence = trust_cg_lower::guard_evidence::production_guard_replay_evidence();
    let obligations = std::collections::HashMap::new();
    let mut pass = X86ProofGuardElimination::new();
    pass.enable_kernel_gate(evidence, obligations);
    pass.run_on_function(isel_func);

    // Independent fail-closed re-check (the "different path"): re-derive the
    // operand fingerprint and re-confirm discharge against the evidence.
    pass.recheck_kernel_eliminations()?;

    *eliminated_total += pass.stats().guards_eliminated;
    Ok(())
}

/// RISC-V mirror of [`run_x86_guard_kernel_gate`], with the same empty-authority policy.
fn run_riscv_guard_kernel_gate(
    isel_func: &mut crate::riscv::pipeline::RiscVISelFunction,
    _proof_ctx: &trust_cg_lower::ProofContext,
    _trust_ir_module: &trust_ir::Module,
    eliminated_total: &mut u32,
) -> Result<(), String> {
    use crate::riscv::pipeline::RiscVProofGuardElimination;

    // Nothing to gate if ISel bound no carrier to an obligation.
    if isel_func.guard_obligations.is_empty() {
        return Ok(());
    }

    // Same exact-replay boundary as x86/AArch64: retain structural metadata, grant no authority.
    let evidence = trust_cg_lower::guard_evidence::production_guard_replay_evidence();
    let obligations = std::collections::HashMap::new();
    let mut pass = RiscVProofGuardElimination::new();
    pass.enable_kernel_gate(evidence, obligations);
    pass.run_on_function(isel_func);

    // Independent fail-closed re-check (the "different path").
    pass.recheck_kernel_eliminations()?;

    *eliminated_total += pass.stats().guards_eliminated;
    Ok(())
}

/// Run the carrier-hygiene invariant (`trust_cg_verify::carrier_hygiene`) over
/// an emitted x86-64 ISel function and FAIL CLOSED on the first violation.
///
/// This is the production wiring of item 1 of the proof-gap program: the
/// pure-lattice checker that re-derives MISCOMPILE #51 / #66 (a wide-reading
/// `SAR`/`IDIV` / `SHR`/`DIV` consuming a dirty narrow carrier) now runs on
/// EVERY x86 compile, on the DEFAULT build — it is NOT gated behind the
/// `verify` feature. The checker needs no solver / SMT: it is a forward
/// abstract interpretation over the machine-IR stream.
///
/// # Soundness gate (mirrors `x86_64_function_verifier::apply_carrier_hygiene`)
///
/// The checker is seeded from the per-VReg nominal-width map ISel records
/// (`X86ISelFunction::vreg_nominal_widths()`). A function with NO recorded
/// widths did not pass through the width-recording ISel selection path and
/// carries no ground truth to check against, so it is skipped — running the
/// fail-closed checker against an empty map would false-reject every wide
/// reader as "unknown width". Production ISel output always carries the width
/// map (every GPR-carrier def is recorded), so the invariant always runs on
/// real emitted code. This matches the live function-verifier wiring exactly.
fn check_x86_carrier_hygiene(
    func: &trust_cg_lower::x86_64_isel::X86ISelFunction,
) -> Result<(), CompileError> {
    // No width metadata => not a width-recording ISel function => nothing to
    // check against. Sound: such functions are synthetic, never production
    // codegen (which always records widths).
    if func.vreg_nominal_widths().is_empty() {
        return Ok(());
    }

    let nominal = trust_cg_verify::carrier_hygiene::NominalWidths::from_value_type_widths(
        func.vreg_nominal_widths(),
    );
    let report = trust_cg_verify::carrier_hygiene::check_function(func, &nominal);
    if let Some(violation) = report.violations.into_iter().next() {
        return Err(CompileError::CarrierHygiene {
            function_name: func.name.clone(),
            block: violation.block,
            inst_index: violation.inst_index,
            opcode: violation.opcode,
            operand: violation.operand,
            required: violation.required,
            actual: violation.actual,
            detail: violation.detail,
        });
    }
    Ok(())
}

/// TV-3: block-level lowering-integrity dataflow validation over the RAW
/// pre-pass x86 ISel output.
///
/// Runs the shared arch-parametric validator
/// ([`trust_cg_verify::dataflow_integrity`]) against the EXACT LIR function the
/// ISel consumed. Production x86 compilation always ENFORCES this gate
/// (validated 0-hit over the full differential corpus in warn-only mode first,
/// per the §2.4 gate rollout): a block-level integrity violation — a real
/// instruction after an unconditional terminator (the switch/BST
/// block-collision family), code fused from two source blocks, a mis-started
/// block, or a DROPPED effectful store/call/atomic (the store-drop class) —
/// fails the compile CLOSED. The standalone rollout environment control is
/// deliberately ignored here: an ambient variable must not disable a
/// production compiler integrity gate.
///
/// MUST run on the pre-pass ISel output: the optimizer passes below do not
/// preserve TV-1 provenance stamps (see the `LoweringProvenance` schema note in
/// `trust-cg-ir`). Runs unconditionally (not behind the `verify` feature),
/// exactly like [`check_x86_carrier_hygiene`], so the AOT object path stays
/// honest on the default `default-features = false` bridge build.
/// VOL-2. Instruction selection must emit exactly the volatile accesses the
/// LIR asked for.
///
/// The optimizer bracket (VOL-1) starts AFTER selection, so it structurally
/// cannot see a selection that dropped, widened, redirected or reclassified a
/// volatile access. This is the half that can.
///
/// The two sides are independent: the LIR carries
/// `Opcode::VolatileLoad`/`VolatileStore` with a trust-ir-derived TYPE, placed
/// there by the adapter, while the machine side carries a `Volatile*` OPCODE
/// chosen by ISel. Neither is computed from the other.
///
/// An access whose LIR type this lane does not model FAILS THE COMPILE rather
/// than being skipped: a skipped access would shorten the source trace and make
/// a genuinely elided access compare as correct. The only such type today is
/// `i128`, which x86 ISel refuses outright ("splitting it into two 64-bit
/// accesses is forbidden"), so reaching this arm means something changed.
fn check_volatile_lowering_faithful(
    lir_func: &trust_cg_lower::function::Function,
    isel_func: &trust_cg_lower::x86_64_isel::X86ISelFunction,
) -> Result<(), CompileError> {
    use trust_cg_verify::x86_volatile_trace as vt;

    let (source, unmodelled) = vt::lir_volatile_trace(lir_func);
    if unmodelled > 0 {
        return Err(CompileError::VolatileTraceChanged {
            function: lir_func.name.clone(),
            violation: format!(
                "{unmodelled} volatile access(es) have a LIR type this obligation does not \
                 model, so the source trace cannot be compared and the compile fails closed"
            ),
        });
    }
    if source.is_empty() {
        return Ok(());
    }

    let machine = vt::machine_volatile_trace(isel_func);
    // Selection may restructure blocks, so order is compared only when the
    // block counts correspond; the multiset is compared unconditionally and
    // catches every hazard except intra-block reordering.
    let compare_order = source.per_block.len() == machine.per_block.len();
    vt::volatile_trace_holds(&source, &machine, compare_order).map_err(|violation| {
        CompileError::VolatileTraceChanged {
            function: lir_func.name.clone(),
            violation: format!("instruction selection: {violation}"),
        }
    })?;
    Ok(())
}

pub fn enforce_x86_dataflow_integrity(
    func: &trust_cg_lower::x86_64_isel::X86ISelFunction,
    lir: &trust_cg_lower::Function,
) -> Result<(), CompileError> {
    use trust_cg_verify::dataflow_integrity::{self, DataflowIntegrityMode};
    // `dataflow_integrity::evaluate` intentionally skips a mismatched replay
    // pair because its rollout callers may run in warn-only mode. This wrapper
    // is the production ENFORCE boundary, so accepting a mis-zipped function
    // would bypass the gate entirely. Fail closed before entering the shared
    // evaluator.
    if func.name != lir.name {
        return Err(CompileError::Pipeline(PipelineError::ISel(format!(
            "[TCG-DATAFLOW-INTEGRITY] x86 function/LIR pairing mismatch: machine function `{}` was paired with LIR function `{}`",
            func.name, lir.name
        ))));
    }
    if let Some(violation) =
        dataflow_integrity::evaluate(func, lir, "x86_64", DataflowIntegrityMode::Enforce)
    {
        return Err(CompileError::Pipeline(PipelineError::ISel(format!(
            "[TCG-DATAFLOW-INTEGRITY] fn `{}` block-level lowering-integrity violation ({:?}): {}",
            func.name, violation.kind, violation.detail
        ))));
    }
    Ok(())
}

/// Validate, fail-closed, the arch-divergent glue-pass expansions the x86-64
/// pipeline relies on (item 3 of the proof-gap program).
///
/// # What this certifies
///
/// The SMT-verified per-instruction lowering core proves *individual* opcode
/// lowerings; it does NOT prove the *glue passes* that rewrite one IR shape
/// into another before instruction selection. The overflow / checked-arith
/// expansion (`trust_cg_lower::adapter::translate_overflow`) is one such pass,
/// and it was the site of MISCOMPILE #67: the original signed-mul-overflow
/// expansion used the AArch64 `SDIV`-identity check (`q = value SDIV rhs;
/// overflow = rhs != 0 && q != lhs`), which relies on AArch64 `SDIV`-by-zero
/// returning 0. Ported verbatim to x86-64 — where `IDIV`-by-zero raises `#DE`
/// (SIGFPE) — `x.overflowing_mul(0)` crashed instead of reporting no overflow.
/// The fix (commit `9395663`) replaced it with a division-free wide-multiply.
///
/// SCOPE — now a PER-PROGRAM gate (proof-gap item 3, #67), no longer a fixed
/// canary. `validate_x86_overflow_expansions_per_program` inspects each emitted
/// `X86ISelFunction` and derives, FROM THE ACTUAL EMITTED CODE, the overflow /
/// checked-arith expansions THIS program contains, then:
///
///   1. STRUCTURAL SAFETY NET (the false-positive-free #67 invariant): a signed
///      multiply (`IMUL`) whose product feeds an `IDIV` *dividend* is the exact
///      `SDIV`-identity signature (`q = (a*b) SDIV b`) that SIGFPEs on x86-64
///      `IDIV`-by-zero / `INT_MIN/-1`. No correct lowering ever divides a
///      multiply product, so this dataflow is rejected fail-closed on sight.
///   2. ENUMERATION + EXHAUSTIVE RE-VERIFICATION: it recognizes the live
///      division-free wide-multiply signed-mul-overflow idiom (`MOVSX -> IMUL
///      ... CMP ... SETcc NE`) and the native I32/I64 flag idiom (`{ADD,SUB,
///      IMUL} ... SETcc {O,B}`), recovering each site's `(CheckedOp,
///      OverflowExpansion, width)`. Each DISTINCT triple is validated ONCE per
///      compile (deduped) via the arch-parameterized `OverflowExpansionValidator`
///      under x86-64 `IDIV` `#DE` trap semantics, discharged EXHAUSTIVELY by
///      `verify_by_evaluation` (no solver), fail-closed.
///
/// The fixed-model canary is KEPT (cheap, memoized) and folded in as a baseline
/// so even an overflow-free program re-proves the validator model is
/// arch-discriminating. Whereas the canary caught only a regression in the
/// expansion MODEL / validator, the per-program form reflects what THIS
/// program's `X86ISelFunction`s actually emit — closing the gap the old doc
/// admitted ("does NOT inspect the program's emitted `X86ISelFunction`s").
///
/// HONEST RESIDUAL: the full `OverflowExpansion` strategy *enum value* is not a
/// discrete post-ISel tag — narrow-width expansions are decomposed into generic
/// opcodes — so enumeration recognizes idiom SHAPES (it may miss an unrecognized
/// shape = a false negative in enumeration, never a false positive). The
/// structural `IMUL->IDIV` safety net (1) is exhaustive over the emitted stream
/// and is the load-bearing #67 guarantee; enumeration (2) adds semantic
/// re-proof of the recognized shapes. The complementary per-program #67
/// protections remain on by default: P3c (MIR->trust-ir op-SELECTION), the SMT
/// proof core (trust-ir->machine division-free wide-mul lowering), and
/// `e2e_x86_64_checked_arith` (clang oracle).
///
/// # Wiring form
///
/// This bounded slice uses the lighter `PassValidator::validate()` fail-closed
/// form (returning `Err` on `Rejected`) rather than threading a full
/// `CertifiedPassChainEntry` through the heavily
/// `cfg(feature = "verify")`-gated certificate plumbing.
///
/// Note on the switch-normalization validator: the x86-64 switch lowering
/// (`x86_64_isel::select_switch`) emits a *faithful 1:1 linear CMP+Jcc cascade*
/// preserving every `(case_value, target_block)` from the source switch — it
/// performs NO jump-table / binary-search normalization (those live only in the
/// AArch64 `switch.rs`). The #62 dropped/duplicated/re-targeted-case hazard the
/// `SwitchNormalizationValidator` targets therefore cannot arise on x86, so no
/// per-compile switch validator is wired here.
/// True iff the selected encoder profile lacks hardware POPCNT and an emitted
/// function contains `Popcnt`, so the encoder can perform its SWAR rewrite.
/// The caller supplies the actual output pipeline's profile, never ambient host
/// detection. Hardware POPCNT keeps the instruction and cannot emit SWAR.
/// Presence gate for `validate_x86_popcnt_expansion_canary`: a program
/// with no `Popcnt` cannot ship the (mis)expansion, so skipping the canary
/// there preserves the guarantee vacuously while removing its fixed per-process
/// cost from the majority of compiles.
fn x86_funcs_emit_popcnt_swar(
    funcs: &[trust_cg_lower::x86_64_isel::X86ISelFunction],
    target_features: X86TargetFeatures,
) -> bool {
    if target_features.contains(crate::x86_64::X86TargetFeature::Popcnt) {
        return false;
    }
    funcs.iter().any(|f| {
        f.blocks.values().any(|b| {
            b.insts
                .iter()
                .any(|i| i.opcode == trust_cg_ir::X86Opcode::Popcnt)
        })
    })
}

fn validate_x86_glue_pass_expansions(
    funcs: &[trust_cg_lower::x86_64_isel::X86ISelFunction],
    target_features: X86TargetFeatures,
) -> Result<(), CompileError> {
    // (1) Baseline model canary: re-prove the live signed-mul-overflow expansion
    // model (division-free wide multiply) is arch-discriminating under x86-64
    // IDIV trap semantics, even for a program with no overflow sites. Memoized.
    validate_x86_overflow_expansion_canary()?;
    // (1b) Popcount SWAR expansion canary: the encoder rewrites a proven `Popcnt`
    // opcode into a hand-written shift/mask software sequence on the default
    // no-POPCNT target, AFTER the per-instruction certs are generated. Re-prove
    // (memoized) that the SWAR sequence == popcount so a regression in it can't
    // ship behind an all-green proof bundle.
    //
    // Match expand_x86_generic_popcnts: a hardware-POPCNT encoder returns
    // without rewriting. The caller binds this to the selected output pipeline
    // (including the JIT fallback's identical feature profile), not host flags.
    // For the generic profile the SWAR rewrite can only fire when a `Popcnt`
    // opcode is actually emitted, so a program with no
    // Popcnt instruction cannot possibly ship the (mis)expansion — the canary's
    // guarantee is vacuously preserved by skipping it there. The first
    // Popcnt-bearing compile in the process still pays the (memoized-for-life)
    // proof, so the sequence is never validated less than exactly the compiles
    // where it can run. This removes the fixed per-process CERT-SKIP recheck
    // from the overwhelming majority of std compiles (which emit no Popcnt).
    if x86_funcs_emit_popcnt_swar(funcs, target_features) {
        validate_x86_popcnt_expansion_canary()?;
    }
    // (2) Per-program form: derive and validate the overflow expansions THIS
    // program's emitted X86ISelFunctions actually contain.
    validate_x86_overflow_expansions_per_program(funcs)
}

/// The fixed-model canary, folded in as a baseline (kept because it is cheap and
/// memoized). Re-proves that the live signed-mul-overflow expansion
/// (division-free wide multiply, the #67 fix) is equivalent to the spec under
/// x86-64 IDIV trap semantics. Width 8 => exhaustive (no solver). A regression
/// to the AArch64-only SDIV-identity expansion would be Rejected here.
///
/// The obligation is FIXED and deterministic, so it is discharged ONCE and the
/// verdict memoized instead of re-running the 8-bit exhaustive evaluation on
/// every compile.
fn validate_x86_overflow_expansion_canary() -> Result<(), CompileError> {
    use std::sync::OnceLock;
    use trust_cg_verify::pass_validators::{
        OverflowExpansion, OverflowExpansionValidator, PassValidation, PassValidator, TargetArch,
    };

    static RESULT: OnceLock<Result<(), (String, String, String)>> = OnceLock::new();
    let cached = RESULT.get_or_init(|| {
        let validator = OverflowExpansionValidator::signed_mul(
            "x86-overflow-expand",
            8,
            OverflowExpansion::DivisionFreeWideMul,
            TargetArch::X86_64,
        );
        match validator.validate() {
            PassValidation::Rejected {
                obligation_name,
                reason,
            } => Err((validator.pass_name().to_string(), obligation_name, reason)),
            _ => Ok(()),
        }
    });
    match cached {
        Ok(()) => Ok(()),
        Err((pass_name, obligation_name, reason)) => Err(CompileError::PassValidationRejected {
            pass_name: pass_name.clone(),
            obligation_name: obligation_name.clone(),
            reason: reason.clone(),
        }),
    }
}

/// Canary for the x86 generic-target popcount SWAR expansion (the post-cert
/// encoder expansion `expand_x86_popcnt_inst`). Re-proves ONCE (memoized) that
/// the fixed Hacker's-Delight shift/mask SWAR sequence computes the population
/// count, so a regression in the SWAR table (a wrong fold mask or shift amount)
/// fails the compile closed — even though the per-instruction certificate was
/// generated over the pre-expansion `Popcnt` opcode, BEFORE the encoder replaced
/// it with the ~27-31 instruction software sequence.
///
/// Width 8 keeps the base proof EXHAUSTIVE (complete over all 256 inputs, never
/// sampled) — but at width 8 the SWAR reduction-fold loop (`dst += dst >> {8,16,
/// 32}`) runs zero times, so it never exercises the multi-byte folds the emitted
/// Gpr32/Gpr64 code actually ships. We therefore also require the real emitted
/// Gpr32 width (32), whose model masks, shifts and final mask are byte-for-byte
/// `expand_x86_popcnt_inst`, so a regression in either the `>>8` or `>>16` fold
/// fails the compile closed. The Gpr64 width
/// (64) is provable too but ~30x slower (the 64-term spec pushes AY past the 30 s
/// timeout `validate()` would surface as a Rejection), so it is pinned as the
/// dedicated proof test `popcnt_swar_64_emitted_width_genuinely_verifies` (run in
/// the full-proof job) rather than per-compile.
///
/// COST (PROOF-3 + CERT-SKIP): the width-32 solver proof historically cost
/// ~16 s of live `ay` search per COLD rustc process (the `OnceLock` only
/// amortizes within one process), under a 30 s deadline — every bridge
/// compile was load-fragile (a busy machine could miss the deadline and fail
/// closed with nothing regressed). It now discharges through the CLI solver
/// funnel's CERT-SKIP tier (`trust_cg_verify::canary_cert`): a repo-committed,
/// build-embedded DRAT certificate for exactly this obligation, INDEPENDENTLY
/// re-checked by the vendored `drat-trim` in this process (~1-2 s,
/// deterministic replay — no search, no deadline) before it is credited. The
/// recorded verdict is never trusted: a source-embedded manifest binds the
/// complete certificate bytes, exact SMT2 derived here from the live SWAR
/// model, producer provenance, and authorized checker bytes. A regressed model
/// misses; any miss/mismatch/tamper/check-failure falls through to the ordinary
/// live proof lane (fail-closed, never a weaker verdict;
/// `TCG_CANARY_NO_CACHE=1` forces live). Consuming an exact certificate does not
/// require the offline AY producer to be installed.
fn validate_x86_popcnt_expansion_canary() -> Result<(), CompileError> {
    use std::sync::OnceLock;
    use trust_cg_verify::pass_validators::{
        PassValidation, PassValidator, PopcntSwarExpansionValidator,
    };

    static RESULT: OnceLock<Result<(), (String, String, String)>> = OnceLock::new();
    let cached = RESULT.get_or_init(|| {
        // Width 8 discharges exhaustively. Width 32 is always requested: its
        // committed portable certificate is checked before AY resolution, and
        // a missing/invalid cert still fails closed through the live lane.
        for width in [8, 32] {
            let validator = PopcntSwarExpansionValidator::x86_generic("x86-popcnt-expand", width);
            if let PassValidation::Rejected {
                obligation_name,
                reason,
            } = validator.validate()
            {
                return Err((validator.pass_name().to_string(), obligation_name, reason));
            }
        }
        Ok(())
    });
    match cached {
        Ok(()) => Ok(()),
        Err((pass_name, obligation_name, reason)) => Err(CompileError::PassValidationRejected {
            pass_name: pass_name.clone(),
            obligation_name: obligation_name.clone(),
            reason: reason.clone(),
        }),
    }
}

/// The checked-overflow expansion `(op, expansion, width)` triple recovered from
/// one emitted overflow site. `CheckedOp`/`OverflowExpansion` map directly onto
/// the `OverflowExpansionValidator` so each distinct triple can be re-verified.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct RecoveredOverflowExpansion {
    /// `0 = SignedAdd`, `1 = SignedSub`, `2 = SignedMul` (matches `CheckedOp`).
    op: u8,
    /// `0 = SignBitCheck`, `1 = DivisionFreeWideMul` (matches `OverflowExpansion`).
    expansion: u8,
    /// Source operand bit width (8/16/32/64).
    width: u32,
}

/// PER-PROGRAM overflow-expansion validation (proof-gap item 3, #67).
///
/// Inspects each emitted `X86ISelFunction` and, FROM THE EMITTED CODE:
///
///   1. STRUCTURAL SAFETY NET — rejects, fail-closed, any signed multiply whose
///      product feeds an `IDIV` dividend (the `SDIV`-identity #67 signature; no
///      correct lowering divides a multiply product). False-positive-free.
///   2. ENUMERATION + RE-VERIFICATION — recovers each recognized overflow site's
///      `(op, expansion, width)` triple, dedups across the whole program, and
///      re-discharges each DISTINCT triple ONCE through the arch-parameterized
///      `OverflowExpansionValidator` under x86-64 IDIV trap semantics
///      (exhaustive `verify_by_evaluation`, no solver).
fn validate_x86_overflow_expansions_per_program(
    funcs: &[trust_cg_lower::x86_64_isel::X86ISelFunction],
) -> Result<(), CompileError> {
    let mut triples: BTreeSet<RecoveredOverflowExpansion> = BTreeSet::new();
    for func in funcs {
        // (1) Structural safety net: reject the trapping IMUL->IDIV dataflow.
        if let Some((block, inst_index)) = find_signed_mul_overflow_division(func) {
            return Err(CompileError::PassValidationRejected {
                pass_name: "x86-overflow-expand".to_string(),
                obligation_name: format!(
                    "per-program[{}]: signed-mul-overflow division-free invariant \
                     (block {block}, inst {inst_index})",
                    func.name
                ),
                reason:
                    "signed multiply product feeds an IDIV dividend — this is the AArch64-only \
                     SDIV-identity overflow expansion (MISCOMPILE #67), which SIGFPEs (#DE) on \
                     x86-64 IDIV-by-zero / INT_MIN/-1; the live lowering must use the \
                     division-free wide-multiply check"
                        .to_string(),
            });
        }
        // (2) Enumerate the overflow-expansion triples emitted in this function.
        collect_overflow_expansions(func, &mut triples);
    }

    // Re-verify each DISTINCT triple ONCE (dedup is the BTreeSet) — still
    // per-program: this set reflects exactly what THIS program emitted.
    for triple in triples {
        validate_recovered_overflow_expansion(triple)?;
    }
    Ok(())
}

/// Map a recovered triple onto the `OverflowExpansionValidator` and discharge it
/// exhaustively under x86-64 IDIV trap semantics. Fail-closed on `Rejected`.
fn validate_recovered_overflow_expansion(
    triple: RecoveredOverflowExpansion,
) -> Result<(), CompileError> {
    use trust_cg_verify::pass_validators::{
        CheckedOp, OverflowExpansion, OverflowExpansionValidator, PassValidation, PassValidator,
        TargetArch,
    };

    let op = match triple.op {
        0 => CheckedOp::SignedAdd,
        1 => CheckedOp::SignedSub,
        _ => CheckedOp::SignedMul,
    };
    let expansion = match triple.expansion {
        0 => OverflowExpansion::SignBitCheck,
        _ => OverflowExpansion::DivisionFreeWideMul,
    };
    // The validator is exhaustive only at/below its 8-bit threshold; for wider
    // widths it requires a formal solver. We always discharge the proof at the
    // exhaustive width 8 (the validator's semantics are width-uniform for these
    // arch-divergent expansions: the SDIV-identity #DE trap and the
    // division-free round-trip behave identically at every width, so the 8-bit
    // exhaustive proof is the no-solver complete proof the gate relies on — the
    // same width the original canary used).
    let validator = OverflowExpansionValidator {
        pass_name: "x86-overflow-expand".to_string(),
        width: 8,
        op,
        expansion,
        arch: TargetArch::X86_64,
    };
    match validator.validate() {
        PassValidation::Rejected {
            obligation_name,
            reason,
        } => Err(CompileError::PassValidationRejected {
            pass_name: validator.pass_name().to_string(),
            obligation_name: format!("per-program(width {}): {obligation_name}", triple.width),
            reason,
        }),
        _ => Ok(()),
    }
}

/// STRUCTURAL #67 safety net: locate the AArch64-only `SDIV`-identity
/// signed-mul-overflow expansion `q = (a*b) SDIV b` emitted as x86 machine code.
/// Returns the `(block_id, inst_index)` of the offending `IDIV`, or `None`.
///
/// # The exact signature (false-positive-free)
///
/// x86-64 `IDIV` divides the implicit `RDX:RAX` accumulator by its single
/// register/memory operand (the divisor); the quotient lands in `RAX`. ISel
/// emits it as `MOV RAX, <dividend>; C{D,Q}Q; IDIV <divisor>` (see
/// `x86_64_isel::select_div`). The #67 bug computed `q = (a*b) IDIV b` — i.e.
/// the DIVIDEND moved into `RAX` is an `IMUL` product AND the DIVISOR is one of
/// that very multiply's source operands. That `(a*b)/b` shape exists ONLY to
/// recover `a` for the SDIV overflow identity; no correct program divides a
/// product by one of its own factors. A legitimate `(a*b)/c` has a divisor `c`
/// that is NOT a multiplicand, so it is never flagged.
///
/// Requiring `divisor ∈ {multiplicands of the dividend's IMUL}` is what keeps
/// this sound: it fires on the trapping overflow identity and on nothing else.
/// Scoped to a single block (the expansion is straight-line); defs are tracked
/// by each instruction's destination operand (operand[0] for the `IMUL`/`MOV`
/// forms that participate here).
fn find_signed_mul_overflow_division(
    func: &trust_cg_lower::x86_64_isel::X86ISelFunction,
) -> Option<(u32, usize)> {
    use std::collections::HashMap;
    use trust_cg_ir::regs::VReg;
    use trust_cg_ir::x86_64_ops::X86Opcode;
    use trust_cg_ir::x86_64_regs::{EAX, RAX};
    use trust_cg_lower::x86_64_isel::X86ISelOperand;

    let operand_vreg = |op: &X86ISelOperand| -> Option<VReg> {
        match op {
            X86ISelOperand::VReg(v) => Some(*v),
            _ => None,
        }
    };

    for block_id in &func.block_order {
        let Some(block) = func.blocks.get(block_id) else {
            continue;
        };
        // vreg -> source multiplicands of the IMUL that produced it (if any).
        let mut imul_factors: HashMap<VReg, Vec<VReg>> = HashMap::new();
        // vreg -> its copy origin (`MOV dst, src` aliases dst to src). select_div
        // copies the divisor (`MOV safe_rhs, rhs`) before IDIV, so the IDIV
        // operand must be resolved back through copies to recognize `(a*b)/b`.
        let mut copy_origin: HashMap<VReg, VReg> = HashMap::new();
        // The vreg currently held in the RAX/EAX accumulator (the IDIV dividend),
        // tracked across the straight-line `MOV acc, <dividend>` setup.
        let mut acc_holds: Option<VReg> = None;

        // Resolve a vreg through copy chains to its ultimate origin.
        let resolve = |v: VReg, copies: &HashMap<VReg, VReg>| -> VReg {
            let mut cur = v;
            // Bounded walk (the copy graph is acyclic in straight-line code);
            // guard against any pathological cycle with a step cap.
            for _ in 0..block.insts.len() + 1 {
                match copies.get(&cur) {
                    Some(&next) if next != cur => cur = next,
                    _ => break,
                }
            }
            cur
        };

        for (inst_index, inst) in block.insts.iter().enumerate() {
            match inst.opcode {
                // Record IMUL product -> its source multiplicands (resolved to
                // copy origins so a multiplicand fed via a copy still matches).
                X86Opcode::ImulRR
                | X86Opcode::ImulRRI
                | X86Opcode::ImulRM
                | X86Opcode::ImulRMSib => {
                    if let Some(dst) = inst.operands.first().and_then(operand_vreg) {
                        let factors: Vec<VReg> = inst
                            .operands
                            .iter()
                            .skip(1)
                            .filter_map(&operand_vreg)
                            .map(|f| resolve(f, &copy_origin))
                            .collect();
                        imul_factors.insert(dst, factors);
                    }
                }
                // `MOV dst, src`: a vreg-to-vreg copy (alias) and, when the
                // destination is the RAX/EAX accumulator, the IDIV dividend setup.
                X86Opcode::MovRR | X86Opcode::MovRR32 => {
                    let src = inst.operands.get(1).and_then(operand_vreg);
                    match inst.operands.first() {
                        Some(X86ISelOperand::PReg(dst)) if *dst == RAX || *dst == EAX => {
                            acc_holds = src;
                        }
                        Some(X86ISelOperand::VReg(dst)) => {
                            if let Some(src) = src {
                                copy_origin.insert(*dst, src);
                            }
                        }
                        _ => {}
                    }
                }
                // IDIV <divisor>: the dividend is the accumulator's current value.
                X86Opcode::Idiv => {
                    if let (Some(dividend), Some(divisor)) =
                        (acc_holds, inst.operands.first().and_then(operand_vreg))
                    {
                        let divisor = resolve(divisor, &copy_origin);
                        if let Some(factors) = imul_factors.get(&dividend) {
                            // The trapping #67 identity: q = (a*b) IDIV b, divisor
                            // is a multiplicand of the dividend product.
                            if factors.contains(&divisor) {
                                return Some((block_id.0, inst_index));
                            }
                        }
                    }
                }
                _ => {}
            }
        }
    }
    None
}

/// ENUMERATE the recognizable overflow-expansion sites emitted in `func`, adding
/// each recovered `(op, expansion, width)` triple to `out`.
///
/// Two idiom shapes are recognized (the live expansions; see
/// `trust_cg_lower::adapter::translate_overflow` and
/// `x86_64_isel::select_checked_arithmetic`):
///
///   * Native I32/I64 flag idiom: `{ADD,SUB,IMUL}RR` immediately followed by
///     `SETcc {O (signed) | B (unsigned)}`. The arith opcode selects the op; the
///     condition code selects signedness. (Unsigned/`B` sites are skipped — the
///     validator only models the signed family that #67 lives in.) Recovers
///     `(SignedAdd/Sub/Mul, SignBitCheck-or-DivisionFreeWideMul, width)`.
///   * Narrow-width signed-mul division-free wide-multiply idiom: a sign-extend
///     (`MOVSX{B,W}` / `MOVSXD`) feeding an `IMUL` whose product is `CMP`d and
///     consumed by `SETcc NE`. Recovers `(SignedMul, DivisionFreeWideMul, w)`
///     where `w` is the sign-extend source width (8/16/32).
///
/// Recognition is conservative: an unrecognized shape is simply not enumerated
/// (a false negative, never a false positive). The exhaustive #67 guarantee is
/// the structural net in `find_signed_mul_overflow_division`; this enumeration
/// adds a semantic re-proof of the recognized shapes.
fn collect_overflow_expansions(
    func: &trust_cg_lower::x86_64_isel::X86ISelFunction,
    out: &mut std::collections::BTreeSet<RecoveredOverflowExpansion>,
) {
    use trust_cg_ir::x86_64_ops::{X86CondCode, X86Opcode};
    use trust_cg_lower::x86_64_isel::X86ISelOperand;

    // CheckedOp codes: 0=SignedAdd, 1=SignedSub, 2=SignedMul.
    // OverflowExpansion codes: 0=SignBitCheck, 1=DivisionFreeWideMul.
    const SIGN_BIT_CHECK: u8 = 0;
    const DIVISION_FREE: u8 = 1;

    let setcc_overflow_cc =
        |inst: &trust_cg_lower::x86_64_isel::X86ISelInst| -> Option<X86CondCode> {
            if !matches!(inst.opcode, X86Opcode::Setcc) {
                return None;
            }
            inst.operands.iter().find_map(|op| match op {
                X86ISelOperand::CondCode(cc) => Some(*cc),
                _ => None,
            })
        };

    for block_id in &func.block_order {
        let Some(block) = func.blocks.get(block_id) else {
            continue;
        };
        let insts = &block.insts;
        for i in 0..insts.len() {
            let inst = &insts[i];
            // --- Native I32/I64 flag idiom: {ADD,SUB,IMUL}RR + SETcc {O,B} ---
            let native_op = match inst.opcode {
                X86Opcode::AddRR => Some(0u8),  // SignedAdd (if SETcc O)
                X86Opcode::SubRR => Some(1u8),  // SignedSub (if SETcc O)
                X86Opcode::ImulRR => Some(2u8), // SignedMul (if SETcc O)
                _ => None,
            };
            if let Some(op) = native_op
                && let Some(cc) = insts.get(i + 1).and_then(setcc_overflow_cc)
            {
                // Only the signed family (SETcc O) is modeled by the
                // validator; unsigned (SETcc B) carry checks are skipped.
                if matches!(cc, X86CondCode::O) {
                    let width = native_idiom_width(func, inst);
                    // add/sub use SignBitCheck; the native signed mul uses the
                    // hardware OF flag (a division-free overflow detection,
                    // modeled as DivisionFreeWideMul).
                    let expansion = if op == 2 {
                        DIVISION_FREE
                    } else {
                        SIGN_BIT_CHECK
                    };
                    out.insert(RecoveredOverflowExpansion {
                        op,
                        expansion,
                        width,
                    });
                }
            }

            // --- Narrow signed-mul division-free wide-multiply idiom ---
            // A sign-extend feeding an IMUL whose product is CMP'd and consumed
            // by SETcc NE. We key off the sign-extend opcode for the source width
            // and confirm the block contains the CMP+SETcc-NE completion.
            let sx_width = match inst.opcode {
                X86Opcode::MovsxB => Some(8u32),
                X86Opcode::MovsxW => Some(16u32),
                X86Opcode::Movsx => Some(32u32),
                _ => None,
            };
            if let Some(width) = sx_width {
                // Sign-extend destination (operand[0]) must feed an IMUL whose
                // product later reaches a SETcc NE — the division-free overflow
                // round-trip. Confirm the completing CMP + SETcc NE shape exists
                // in the block (conservative: presence is enough to recognize the
                // expansion strategy emitted; correctness of the strategy itself
                // is proven by re-verification).
                let sx_dst = inst.operands.first().and_then(|o| match o {
                    X86ISelOperand::VReg(v) => Some(*v),
                    _ => None,
                });
                if let Some(sx_dst) = sx_dst {
                    let feeds_imul = insts[i + 1..].iter().any(|n| {
                        matches!(
                            n.opcode,
                            X86Opcode::ImulRR
                                | X86Opcode::ImulRRI
                                | X86Opcode::ImulRM
                                | X86Opcode::ImulRMSib
                        ) && n
                            .operands
                            .iter()
                            .skip(1)
                            .any(|o| matches!(o, X86ISelOperand::VReg(v) if *v == sx_dst))
                    });
                    let has_ne_setcc = insts
                        .iter()
                        .any(|n| setcc_overflow_cc(n) == Some(X86CondCode::NE));
                    let has_cmp = insts.iter().any(|n| {
                        matches!(
                            n.opcode,
                            X86Opcode::CmpRR
                                | X86Opcode::CmpRI
                                | X86Opcode::CmpRI8
                                | X86Opcode::CmpRM
                        )
                    });
                    if feeds_imul && has_ne_setcc && has_cmp {
                        out.insert(RecoveredOverflowExpansion {
                            op: 2, // SignedMul
                            expansion: DIVISION_FREE,
                            width,
                        });
                    }
                }
            }
        }
    }
}

/// Best-effort source width (8/16/32/64) for a native checked-arith idiom,
/// recovered from the destination vreg's recorded nominal width when ISel left
/// one, else from the carrier register class. Defaults to 64 (the validator
/// proof is width-uniform for these arch-divergent expansions, so the exact
/// width only LABELS the recovered triple — it does not change the proof).
fn native_idiom_width(
    func: &trust_cg_lower::x86_64_isel::X86ISelFunction,
    inst: &trust_cg_lower::x86_64_isel::X86ISelInst,
) -> u32 {
    use trust_cg_ir::regs::RegClass;
    use trust_cg_lower::x86_64_isel::X86ISelOperand;

    if let Some(X86ISelOperand::VReg(dst)) = inst.operands.first() {
        if let Some(&w) = func.vreg_nominal_widths().get(dst) {
            return w;
        }
        // Narrow integers (i8/i16/i32) all share the Gpr32 carrier class, so the
        // class only distinguishes 64 vs <=32. Without a nominal width we cannot
        // narrow further; 32 is the conservative carrier label for Gpr32.
        return match dst.class {
            RegClass::Gpr64 => 64,
            _ => 32,
        };
    }
    64
}

fn count_x86_branch_instructions(func: &trust_cg_lower::x86_64_isel::X86ISelFunction) -> usize {
    use trust_cg_ir::x86_64_ops::X86Opcode;

    func.block_order
        .iter()
        .filter_map(|block| func.blocks.get(block))
        .map(|block| {
            block
                .insts
                .iter()
                .filter(|inst| {
                    matches!(
                        inst.opcode,
                        X86Opcode::Jmp
                            | X86Opcode::Jcc
                            | X86Opcode::Call
                            | X86Opcode::CallR
                            | X86Opcode::CallM
                            | X86Opcode::Ret
                            | X86Opcode::Ud2
                    )
                })
                .count()
        })
        .sum()
}

fn x86_function_has_dynamic_stack_alloc(
    func: &trust_cg_lower::x86_64_isel::X86ISelFunction,
) -> bool {
    use trust_cg_ir::x86_64_ops::X86Opcode;

    func.blocks.values().any(|block| {
        block
            .insts
            .iter()
            .any(|inst| inst.opcode == X86Opcode::StackAlloc)
    })
}

fn nonzero_duration(duration: Duration) -> Duration {
    if duration == Duration::ZERO {
        Duration::from_nanos(1)
    } else {
        duration
    }
}

fn x86_opt_level_from_codegen(opt_level: OptLevel) -> trust_cg_opt::OptLevel {
    match opt_level {
        OptLevel::O0 => trust_cg_opt::OptLevel::O0,
        OptLevel::O1 => trust_cg_opt::OptLevel::O1,
        OptLevel::O2 => trust_cg_opt::OptLevel::O2,
        OptLevel::O3 => trust_cg_opt::OptLevel::O3,
    }
}

/// Carry an x86-64 pipeline refusal into [`PipelineError`] TYPED.
///
/// This used to special-case one variant and flatten every other one into
/// `PipelineError::ISel(other.to_string())`, so a COFF writer, EH-frame, decode
/// check or ELF reparse refusal read as an instruction-selection failure (and a
/// Windows `.pdata`/`.xdata` unwind refusal as an object-format one). Keeping the
/// x86 variant keeps the layer that raised it (trust-core architecture AD-8).
fn x86_pipeline_error_to_pipeline_error(error: crate::x86_64::X86PipelineError) -> PipelineError {
    PipelineError::X86(error)
}

/// Compile one function for the x86-64 JIT on `pipeline`, retrying a refusal on
/// the Greedy `fallback_pipeline` when the fast (LinearScan) profile is active
/// (JIT-8). When both refuse, the fallback's error is surfaced; with no fallback,
/// the fast pipeline's. Either refusal is carried into [`CompileError`] TYPED
/// ([`x86_pipeline_error_to_pipeline_error`]), so the x86 variant that names the
/// refusing layer survives — both JIT compile arms (with and without block
/// counters) share this one conversion instead of each re-rendering the error
/// as an ISel string.
fn compile_x86_jit_function_with_fallback<T>(
    pipeline: &crate::x86_64::X86Pipeline,
    fallback_pipeline: Option<&crate::x86_64::X86Pipeline>,
    compile: impl Fn(&crate::x86_64::X86Pipeline) -> Result<T, crate::x86_64::X86PipelineError>,
) -> Result<T, CompileError> {
    match compile(pipeline) {
        Ok(value) => Ok(value),
        Err(fast_err) => match fallback_pipeline {
            Some(fallback) => compile(fallback)
                .map_err(|e| CompileError::Pipeline(x86_pipeline_error_to_pipeline_error(e))),
            None => Err(CompileError::Pipeline(
                x86_pipeline_error_to_pipeline_error(fast_err),
            )),
        },
    }
}

fn x86_host_jit_abi() -> trust_cg_lower::x86_64_isel::X86CallAbi {
    trust_cg_lower::x86_64_isel::X86CallAbi::host()
}

/// JIT-8 kill-switch. The x86 in-process JIT uses the LinearScan latency
/// profile ([`X86PipelineConfig::host_jit_fast`]) by default when
/// `enable_jit_fast_regalloc` is set. Set `TCG_NO_X86_JIT_LINEARSCAN` (any
/// value) to force the previous Greedy profile — a diagnostic / rollback hatch;
/// both profiles pass the same always-on regalloc translation validator, so
/// this changes only latency and code quality, never correctness.
fn x86_jit_linearscan_regalloc_enabled() -> bool {
    crate::env_lock::var_os("TCG_NO_X86_JIT_LINEARSCAN").is_none()
}

/// Effective host-dependent x86 JIT choices captured on a [`Compiler`]'s first
/// JIT-policy demand.
///
/// Keeping these together gives compilation and identity/provenance consumers
/// one immutable answer even if another thread later mutates a legacy ambient
/// kill switch. New callers should prefer typed [`CompilerConfig`] controls;
/// this snapshot is the migration boundary for the remaining environment knob.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct EffectiveX86JitCodegenProfile {
    pub(crate) target_features: X86TargetFeatures,
    pub(crate) fast_regalloc: bool,
}

fn effective_x86_jit_codegen_profile(config: &CompilerConfig) -> EffectiveX86JitCodegenProfile {
    if config.target != Target::X86_64 {
        return EffectiveX86JitCodegenProfile {
            target_features: X86TargetFeatures::generic_x86_64(),
            fast_regalloc: false,
        };
    }
    EffectiveX86JitCodegenProfile {
        target_features: X86TargetFeatures::host(),
        fast_regalloc: config.enable_jit_fast_regalloc && x86_jit_linearscan_regalloc_enabled(),
    }
}

fn emit_x86_64_absolute_jump_veneer(code: &mut Vec<u8>, target: *const u8) -> u64 {
    let start = code.len() as u64;
    code.extend_from_slice(&[0xFF, 0x25, 0x00, 0x00, 0x00, 0x00]);
    code.extend_from_slice(&(target as u64).to_le_bytes());
    code.extend_from_slice(&[0xCC, 0xCC]);
    start
}

fn emit_x86_64_profile_counter_trampoline(code: &mut Vec<u8>) -> usize {
    #[cfg(all(target_arch = "x86_64", target_os = "windows"))]
    {
        // movabs r10, imm64; lock incq [r10]
        //
        // The Windows unwinder can cover this as a stack-neutral prefix before
        // the normal RBP prologue. Avoid push/popfq here so a callable PC at
        // the function entry is still in a valid RUNTIME_FUNCTION range.
        code.extend_from_slice(&[0x49, 0xBA]);
        let imm64_offset = code.len();
        code.extend_from_slice(&[0u8; 8]);
        code.extend_from_slice(&[0xF0, 0x49, 0xFF, 0x02]);
        return imm64_offset;
    }

    #[cfg(not(all(target_arch = "x86_64", target_os = "windows")))]
    {
        // push rax; pushfq; movabs rax, imm64; lock incq [rax]; popfq; pop rax
        code.extend_from_slice(&[0x50, 0x9C, 0x48, 0xB8]);
        let imm64_offset = code.len();
        code.extend_from_slice(&[0u8; 8]);
        code.extend_from_slice(&[0xF0, 0x48, 0xFF, 0x00, 0x9D, 0x58]);
        imm64_offset
    }
}

fn x86_profile_hooks_enable_call_counters(mode: crate::jit::ProfileHookMode) -> bool {
    matches!(mode, crate::jit::ProfileHookMode::CallCounts)
}

fn x86_profile_hooks_enable_block_counters(mode: crate::jit::ProfileHookMode) -> bool {
    matches!(mode, crate::jit::ProfileHookMode::BlockCounts)
}

/// Exact references consult only canonical emitted function names. In particular,
/// neither object-name aliases nor host overrides participate in this lookup.
#[derive(Clone, Copy)]
struct X86JitFunctionAddress {
    offset: u64,
    /// Actual encoded instructions, excluding alignment, tables, pools and profiling.
    has_code: bool,
}

impl X86JitFunctionAddress {
    fn from_encoded_instructions(offset: u64, has_body_instructions: bool) -> Self {
        Self {
            offset,
            has_code: has_body_instructions,
        }
    }
}

fn resolve_x86_exact_function_offset(
    functions: &HashMap<String, X86JitFunctionAddress>,
    symbol: &str,
) -> Result<u64, crate::jit::JitError> {
    functions
        .get(symbol)
        .filter(|function| function.has_code)
        .map(|function| function.offset)
        .ok_or_else(|| {
            crate::jit::JitError::UnresolvedSymbol(format!(
                "missing or empty exact module function {symbol}"
            ))
        })
}

fn patch_x86_64_rel32_call(
    code: &mut [u8],
    disp32_offset: usize,
    target: u64,
) -> Result<(), crate::jit::JitError> {
    if disp32_offset == 0 || disp32_offset + 4 > code.len() {
        return Err(crate::jit::JitError::FixupOutOfBounds {
            offset: disp32_offset as u32,
            code_len: code.len(),
        });
    }
    let inst_end = disp32_offset + 4;
    let distance = target as i64 - inst_end as i64;
    if distance < i32::MIN as i64 || distance > i32::MAX as i64 {
        return Err(crate::jit::JitError::BranchOutOfRange {
            offset: (disp32_offset - 1) as u32,
            target,
            distance,
        });
    }
    code[disp32_offset..disp32_offset + 4].copy_from_slice(&(distance as i32).to_le_bytes());
    Ok(())
}

struct CompileArtifactCacheContext {
    cache: LocalFilesystemCompileArtifactCache,
    key: CompileArtifactCacheKey,
    boundary: CompileArtifactCacheBoundary,
    reuse_permit: trust_cg_process_env::ArtifactReusePermit,
}

fn sha256_digest(bytes: &[u8]) -> String {
    format!("sha256:{}", sha256_hex(bytes))
}

fn compiler_profile_use_sha256(
    profile_use: Option<&trust_cg_opt::pgo::ProfData>,
) -> Result<String, trust_cg_opt::pgo::ProfDataError> {
    let Some(profile) = profile_use else {
        return Ok(COMPILE_ARTIFACT_PROFILE_USE_DISABLED_SHA256.to_owned());
    };

    let profile_bytes = trust_cg_opt::pgo::encode(profile)?;
    let mut identity = Vec::new();
    identity.extend_from_slice(b"trust-cg.compile_artifact.profile_use.v1\0");
    identity.extend_from_slice(&profile_bytes);
    Ok(sha256_digest(&identity))
}

fn compiler_cache_identity_sha256<T: serde::Serialize + ?Sized>(
    component: &'static str,
    value: &T,
) -> Result<String, CompileError> {
    let bytes = serde_json::to_vec(value)
        .map_err(|source| CompileError::CompileArtifactCacheIdentityJson { component, source })?;
    Ok(sha256_digest(&bytes))
}

const X86_64_WINDOWS_COFF_UNWIND_GUARD_CACHE_IDENTITY: &str =
    "x86_64-windows-coff-unwind-metadata-v2";

fn compiler_x86_64_backend_safety_identity(
    config: &CompilerConfig,
    target_spec: TargetSpec,
) -> Result<Option<&'static str>, CompileError> {
    if config.target != Target::X86_64 {
        return Ok(None);
    }

    let output_format = x86_64_aot_output_format_for_target_spec(target_spec)?;
    if output_format == crate::x86_64::X86OutputFormat::Coff
        && target_spec.operating_system == TargetOperatingSystem::Windows
    {
        return Ok(Some(X86_64_WINDOWS_COFF_UNWIND_GUARD_CACHE_IDENTITY));
    }

    Ok(None)
}

fn compiler_codegen_options_sha256(
    config: &CompilerConfig,
    target_spec: TargetSpec,
    profile_use_sha256: &str,
) -> Result<String, CompileError> {
    let x86_64_aot_output_format = if config.target == Target::X86_64 {
        Some(compiler_x86_64_aot_output_format_name(target_spec)?)
    } else {
        None
    };
    let mut options = serde_json::json!({
        "schema": "trust-cg.compile_artifact.codegen_options.v5",
        "target": config.target.name(),
        "target_triple": compiler_target_triple(target_spec),
        "target_vendor": target_spec.vendor.triple_component(),
        "target_os": target_spec.operating_system.triple_component(),
        "target_environment": target_spec.environment.triple_component(),
        "host_target_os": compiler_host_target_os(),
        "x86_64_aot_output_format": x86_64_aot_output_format,
        "opt_level": compiler_opt_level_name(config.opt_level),
        "emit_proofs": config.emit_proofs,
        "emit_debug": config.emit_debug,
        "parallel": config.parallel,
        "cegis_superopt_budget_sec": config.cegis_superopt_budget_sec,
        "enable_fsym_trust_ir_preflight": config.enable_fsym_trust_ir_preflight,
        "enable_jit_fast_regalloc": config.enable_jit_fast_regalloc,
        "panic_unwind": config.panic_unwind,
        "relocation_model": config.relocation_model.name(),
        "profile_use_sha256": profile_use_sha256,
        "verify_feature": cfg!(feature = "verify"),
    });
    if let Some(safety_identity) = compiler_x86_64_backend_safety_identity(config, target_spec)?
        && let serde_json::Value::Object(options) = &mut options
    {
        options.insert(
            "x86_64_backend_safety_identity".to_owned(),
            serde_json::Value::String(safety_identity.to_owned()),
        );
    }
    // An explicit AArch64 ISA profile changes which instructions may be
    // selected. The key is added only when one is configured, so every
    // default cache identity is unchanged while an explicit-profile compile
    // can never reuse a target-contract object (or one of another profile).
    if let Some(profile) = config.aarch64_isa_profile
        && let serde_json::Value::Object(options) = &mut options
    {
        options.insert(
            "aarch64_isa_profile".to_owned(),
            serde_json::Value::String(profile.canonical_name()),
        );
    }
    if config.aarch64_force_frame_pointers
        && let serde_json::Value::Object(options) = &mut options
    {
        options.insert(
            "aarch64_force_frame_pointers".to_owned(),
            serde_json::Value::Bool(true),
        );
    }
    // Function sections change the object's section layout. The key is added
    // only when the policy is ON, so every default-policy cache identity is
    // unchanged while an enabled compile can never reuse a default object.
    if config.function_sections
        && let serde_json::Value::Object(options) = &mut options
    {
        options.insert(
            "function_sections".to_owned(),
            serde_json::Value::Bool(true),
        );
    }
    // A never-inline name keeps a call OPT-4 would otherwise splice. The key
    // (every name, in sorted order) is added only when the set is non-empty,
    // so every default cache identity is unchanged while a compile with a set
    // never reuses an object compiled without it (or with another set).
    if !config.never_inline.is_empty()
        && let serde_json::Value::Object(options) = &mut options
    {
        options.insert(
            "never_inline".to_owned(),
            serde_json::Value::Array(
                config
                    .never_inline
                    .iter()
                    .cloned()
                    .map(serde_json::Value::String)
                    .collect(),
            ),
        );
    }
    // OD-216: the link unit's routine definitions withhold body-theorem
    // credit, so they change the proof bundle a cached object carries. The
    // key (every name, in sorted order) is added only when the set is
    // non-empty, so every default cache identity is unchanged while a compile
    // with a set never reuses an object compiled without it (or with another).
    if !config.link_unit_definitions.is_empty()
        && let serde_json::Value::Object(options) = &mut options
    {
        options.insert(
            "link_unit_definitions".to_owned(),
            serde_json::Value::Array(
                config
                    .link_unit_definitions
                    .iter()
                    .cloned()
                    .map(serde_json::Value::String)
                    .collect(),
            ),
        );
    }
    // Non-unwinding frames keep a propagation entry only for a region that
    // holds a call which may unwind, decided from the nounwind callee set, so
    // both change the emitted exception tables. The keys are added only when
    // the policy is ON, so every default-policy cache identity is unchanged
    // while an enabled compile can never reuse a default object (or one built
    // against another callee set), or the reverse.
    if config.eh_frames_cannot_unwind
        && let serde_json::Value::Object(options) = &mut options
    {
        options.insert(
            "eh_frames_cannot_unwind".to_owned(),
            serde_json::Value::Bool(true),
        );
        options.insert(
            "eh_nounwind_callees".to_owned(),
            serde_json::Value::Array(
                config
                    .eh_nounwind_callees
                    .iter()
                    .cloned()
                    .map(serde_json::Value::String)
                    .collect(),
            ),
        );
    }
    compiler_cache_identity_sha256("codegen_options", &options)
}

fn compiler_target_facts_sha256(
    target: Target,
    target_spec: TargetSpec,
) -> Result<String, CompileError> {
    let calling_convention = compiler_calling_convention(target, target_spec);
    let num_callee_saved_gprs = if target == Target::X86_64
        && target_spec.operating_system == TargetOperatingSystem::Windows
    {
        8
    } else {
        target.num_callee_saved_gprs()
    };
    let facts = serde_json::json!({
        "schema": "trust-cg.compile_artifact.target_facts.v3",
        "target": target.name(),
        "target_triple": compiler_target_triple(target_spec),
        "target_vendor": target_spec.vendor.triple_component(),
        "target_os": target_spec.operating_system.triple_component(),
        "target_environment": target_spec.environment.triple_component(),
        "pointer_bytes": target.pointer_bytes(),
        "stack_alignment": target.stack_alignment(),
        "calling_convention": calling_convention.name,
        "num_arg_gprs": calling_convention.num_arg_gprs,
        "num_arg_fprs": calling_convention.num_arg_fprs,
        "num_ret_gprs": calling_convention.num_ret_gprs,
        "num_ret_fprs": calling_convention.num_ret_fprs,
        "num_callee_saved_gprs": num_callee_saved_gprs,
        "num_allocatable_gprs": target.num_allocatable_gprs(),
        "requires_frame_pointer": target.requires_frame_pointer(),
        "red_zone_size": calling_convention.red_zone_size,
        "shadow_space": calling_convention.shadow_space,
    });
    compiler_cache_identity_sha256("target_facts", &facts)
}

fn compiler_host_target_os() -> &'static str {
    std::env::consts::OS
}

fn x86_64_aot_output_format_for_os(
    target_os: &'static str,
) -> Result<crate::x86_64::X86OutputFormat, CompileError> {
    use crate::x86_64::X86OutputFormat;

    match target_os {
        "linux" | "android" | "freebsd" | "netbsd" | "openbsd" | "dragonfly" => {
            Ok(X86OutputFormat::Elf)
        }
        "macos" => Ok(X86OutputFormat::MachO),
        "windows" => Ok(X86OutputFormat::Coff),
        _ => Err(CompileError::X86AotObjectFormatUnsupported {
            target_os,
            required_format: "native object format",
            context: "no x86-64 AOT object emitter is wired for this OS",
        }),
    }
}

fn x86_64_aot_output_format_for_target_spec(
    target_spec: TargetSpec,
) -> Result<crate::x86_64::X86OutputFormat, CompileError> {
    x86_64_aot_output_format_for_target_spec_on_host(target_spec, compiler_host_target_os())
}

/// The x86-64 AOT object format for `target_spec` on a host whose OS is
/// `host_os`.
///
/// Only an architecture alias whose OS stayed unknown (the host OS maps to no
/// [`TargetOperatingSystem`], for example FreeBSD) consults `host_os`. A
/// spelled-out triple is authoritative: an explicit `x86_64-unknown-unknown`
/// names no operating system and is refused on every host rather than
/// inheriting the host's format, as the AArch64 pipeline refuses
/// `aarch64-unknown-unknown`.
fn x86_64_aot_output_format_for_target_spec_on_host(
    target_spec: TargetSpec,
    host_os: &'static str,
) -> Result<crate::x86_64::X86OutputFormat, CompileError> {
    use crate::x86_64::X86OutputFormat;

    match target_spec.operating_system {
        TargetOperatingSystem::Linux => Ok(X86OutputFormat::Elf),
        TargetOperatingSystem::Darwin => Ok(X86OutputFormat::MachO),
        TargetOperatingSystem::Windows => Ok(X86OutputFormat::Coff),
        TargetOperatingSystem::Unknown if target_spec.has_explicit_os_abi() => {
            Err(CompileError::X86AotObjectFormatUnsupported {
                target_os: TargetOperatingSystem::Unknown.triple_component(),
                required_format: "native object format",
                context: "an explicit triple with an unknown OS selects no object format, and \
                          an explicit target never inherits the host's; name \
                          x86_64-unknown-linux-gnu, x86_64-apple-darwin or \
                          x86_64-pc-windows-msvc (fail-closed)",
            })
        }
        TargetOperatingSystem::Unknown => x86_64_aot_output_format_for_os(host_os),
    }
}

fn compiler_x86_64_aot_output_format_name(
    target_spec: TargetSpec,
) -> Result<&'static str, CompileError> {
    use crate::x86_64::X86OutputFormat;

    match x86_64_aot_output_format_for_target_spec(target_spec)? {
        X86OutputFormat::RawBytes => Ok("raw"),
        X86OutputFormat::Elf => Ok("elf"),
        X86OutputFormat::MachO => Ok("macho"),
        X86OutputFormat::Coff => Ok("coff"),
    }
}

fn compiler_target_triple(target_spec: TargetSpec) -> String {
    compiler_target_triple_on_host(target_spec, compiler_host_target_os())
}

/// The effective triple of `target_spec` on a host whose OS is `host_os`.
///
/// A spelled-out triple is returned unchanged, so it never depends on the
/// host; only an architecture alias consults `host_os`.
fn compiler_target_triple_on_host(target_spec: TargetSpec, host_os: &str) -> String {
    if target_spec.has_explicit_os_abi() {
        return target_spec.triple();
    }
    // An architecture alias with an attached macOS deployment target resolved
    // to the Apple host; its canonical triple spells the version.
    if target_spec.apple_deployment_target().is_some() {
        return target_spec.with_default_os_abi().triple();
    }

    let arch = target_spec.architecture.name();
    match (target_spec.architecture, host_os) {
        (Target::X86_64, "linux") => "x86_64-unknown-linux-gnu".to_string(),
        (Target::X86_64, "android") => "x86_64-linux-android".to_string(),
        (Target::X86_64, "freebsd") => "x86_64-unknown-freebsd".to_string(),
        (Target::X86_64, "netbsd") => "x86_64-unknown-netbsd".to_string(),
        (Target::X86_64, "openbsd") => "x86_64-unknown-openbsd".to_string(),
        (Target::X86_64, "dragonfly") => "x86_64-unknown-dragonfly".to_string(),
        (Target::X86_64, "macos") => "x86_64-apple-darwin".to_string(),
        (Target::X86_64, "windows") => "x86_64-pc-windows-msvc".to_string(),
        (Target::Aarch64, "linux") => "aarch64-unknown-linux-gnu".to_string(),
        (Target::Aarch64, "android") => "aarch64-linux-android".to_string(),
        (Target::Aarch64, "freebsd") => "aarch64-unknown-freebsd".to_string(),
        (Target::Aarch64, "netbsd") => "aarch64-unknown-netbsd".to_string(),
        (Target::Aarch64, "openbsd") => "aarch64-unknown-openbsd".to_string(),
        (Target::Aarch64, "macos") => "aarch64-apple-darwin".to_string(),
        (Target::Aarch64, "windows") => "aarch64-pc-windows-msvc".to_string(),
        _ => format!("{arch}-unknown-unknown"),
    }
}

fn compiler_calling_convention(target: Target, target_spec: TargetSpec) -> CallingConvention {
    if target == Target::Aarch64 {
        match target_spec.operating_system {
            TargetOperatingSystem::Darwin => {
                return CallingConvention {
                    name: "darwinpcs",
                    red_zone_size: 128,
                    ..target.calling_convention()
                };
            }
            TargetOperatingSystem::Linux => {
                return CallingConvention {
                    name: "aapcs64",
                    red_zone_size: 0,
                    ..target.calling_convention()
                };
            }
            TargetOperatingSystem::Unknown | TargetOperatingSystem::Windows => {}
        }
    }
    if target == Target::X86_64 && target_spec.operating_system == TargetOperatingSystem::Windows {
        return CallingConvention {
            name: "windows_x64",
            num_arg_gprs: 4,
            num_arg_fprs: 4,
            num_ret_gprs: 2,
            num_ret_fprs: 2,
            red_zone_size: 0,
            shadow_space: 32,
        };
    }

    target.calling_convention()
}

fn compiler_opt_level_name(opt_level: OptLevel) -> &'static str {
    match opt_level {
        OptLevel::O0 => "O0",
        OptLevel::O1 => "O1",
        OptLevel::O2 => "O2",
        OptLevel::O3 => "O3",
    }
}

fn lookup_compile_artifact(
    cache: &LocalFilesystemCompileArtifactCache,
    key: &CompileArtifactCacheKey,
    boundary: CompileArtifactCacheBoundary,
    proof_bundle_sha256: Option<&str>,
    reuse_permit: &trust_cg_process_env::ArtifactReusePermit,
) -> std::io::Result<Option<CompileArtifactCacheLookup>> {
    if !reuse_permit.is_valid() {
        return Ok(None);
    }
    let lookup = match boundary {
        CompileArtifactCacheBoundary::Pipeline => match proof_bundle_sha256 {
            Some(digest) => {
                cache.lookup_for_pipeline_with_expected_proof_bundle_sha256(key, digest)
            }
            None => cache.lookup_for_pipeline(key),
        },
        CompileArtifactCacheBoundary::Service => match proof_bundle_sha256 {
            Some(digest) => cache.lookup_for_service_with_expected_proof_bundle_sha256(key, digest),
            None => cache.lookup_for_service(key),
        },
    }?;
    Ok(reuse_permit.is_valid().then_some(lookup))
}

fn store_compile_artifact(
    cache: &LocalFilesystemCompileArtifactCache,
    key: &CompileArtifactCacheKey,
    boundary: CompileArtifactCacheBoundary,
    artifact_bytes: &[u8],
    producer: &str,
    proof_bundle_sha256: Option<&str>,
    reuse_permit: &trust_cg_process_env::ArtifactReusePermit,
) -> std::io::Result<Option<CompileArtifactCacheTelemetry>> {
    if !reuse_permit.is_valid() {
        return Ok(None);
    }
    let telemetry = match boundary {
        CompileArtifactCacheBoundary::Pipeline => match proof_bundle_sha256 {
            Some(digest) => cache.store_from_pipeline_with_proof_bundle_sha256(
                key,
                artifact_bytes,
                producer,
                digest,
            ),
            None => cache.store_from_pipeline(key, artifact_bytes, producer),
        },
        CompileArtifactCacheBoundary::Service => match proof_bundle_sha256 {
            Some(digest) => cache.store_from_service_with_proof_bundle_sha256(
                key,
                artifact_bytes,
                producer,
                digest,
            ),
            None => cache.store_from_service(key, artifact_bytes, producer),
        },
    }?;
    Ok(Some(telemetry))
}

fn proof_status_label(cert: &ProofCertificate) -> &'static str {
    if cert.category.eq_ignore_ascii_case("unverified") {
        "unverified"
    } else if cert.category.eq_ignore_ascii_case("unknown") {
        "unknown"
    } else if cert.strength.starts_with("Failed:") {
        "failed"
    } else {
        "non_verified"
    }
}

fn proof_bundle_sha256(proofs: Option<&[ProofCertificate]>) -> Option<String> {
    let proofs = proofs?;
    let mut rows: Vec<_> = proofs
        .iter()
        .map(|cert| {
            (
                cert.function_name.as_str(),
                cert.rule_name.as_str(),
                cert.category.as_str(),
                cert.strength.as_str(),
                cert.verified,
                source_bound_export_identity(cert),
            )
        })
        .collect();
    rows.sort_unstable();

    let mut bytes = Vec::new();
    put_digest_str(&mut bytes, "trust-cg.compile_artifact.proof_bundle.v2");
    for (function_name, rule_name, category, strength, verified, export) in rows {
        put_digest_str(&mut bytes, function_name);
        put_digest_str(&mut bytes, rule_name);
        put_digest_str(&mut bytes, category);
        put_digest_str(&mut bytes, strength);
        bytes.push(u8::from(verified));
        bytes.push(u8::from(export.is_some()));
        if let Some(identity) = export {
            put_digest_str(&mut bytes, &identity);
        }
    }
    Some(sha256_digest(&bytes))
}

fn source_bound_export_identity(cert: &ProofCertificate) -> Option<String> {
    #[cfg(feature = "verify")]
    {
        cert.source_bound_obligation.as_ref().map(|bound| {
            format!(
                "trust-cg.source-bound-arithmetic-export.v1:{}:{:x?}:{}",
                bound.query_sha256(),
                bound.input_digest(),
                bound.instruction_index(),
            )
        })
    }
    #[cfg(not(feature = "verify"))]
    {
        let _ = cert;
        None
    }
}

fn put_digest_str(out: &mut Vec<u8>, value: &str) {
    out.extend_from_slice(&(value.len() as u64).to_le_bytes());
    out.extend_from_slice(value.as_bytes());
}

/// Rebase one function-relative RISC-V call fixup into the `.text` u32 patch
/// domain without truncation or arithmetic wraparound.
fn rebase_riscv_call_fixup(
    function: &str,
    function_offset: u64,
    fixup: &crate::riscv::pipeline::RiscVCallFixup,
) -> Result<crate::riscv::pipeline::RiscVCallFixup, CompileError> {
    let base = u32::try_from(function_offset).map_err(|_| {
        CompileError::Pipeline(PipelineError::ObjectEmission(format!(
            "RISC-V call fixup in `{function}` starts at .text offset {function_offset}, outside the u32 patch domain"
        )))
    })?;
    let rebase = |relative: u32, instruction: &str| {
        base.checked_add(relative).ok_or_else(|| {
            CompileError::Pipeline(PipelineError::ObjectEmission(format!(
                "RISC-V {instruction} call fixup in `{function}` overflows the u32 patch domain: function base {base} + relative offset {relative}"
            )))
        })
    };
    Ok(crate::riscv::pipeline::RiscVCallFixup {
        auipc_offset: rebase(fixup.auipc_offset, "AUIPC")?,
        jalr_offset: rebase(fixup.jalr_offset, "JALR")?,
        callee: fixup.callee.clone(),
    })
}

/// The symbol bindings the RISC-V module object gives its function
/// definitions: the module-local (`Internal`/`Private`) ones
/// ([`module_local_function_definitions`]) are `STB_LOCAL`, the weak and
/// link-once ones ([`weak_function_definitions`]) `STB_WEAK`, every other
/// definition `STB_GLOBAL`.
#[derive(Debug, Default)]
struct RiscvFunctionBindings {
    local: std::collections::BTreeSet<String>,
    weak: std::collections::BTreeSet<String>,
}

impl RiscvFunctionBindings {
    fn for_module(module: &trust_ir::Module) -> Self {
        Self {
            local: module_local_function_definitions(module),
            weak: weak_function_definitions(module),
        }
    }
}

/// Assemble the RISC-V module object from its laid-out `.text` and serialize
/// it through the checked ELF funnel.
///
/// `func_layout` is `(name, .text offset, size, fixups)` per defined function
/// and `relocated_calls` the call fixups the linker resolves: those whose
/// callee this module does not define, and those whose callee it defines
/// `STB_WEAK` (another object's definition may replace it), while every other
/// intra-object call is already patched into `text`.
///
/// Symbol table: one `STT_FUNC` per defined function at its offset, bound as
/// `bindings` says. ELF symbol index 0 is the null symbol (auto-emitted by
/// the writer), and the writer serializes every `STB_LOCAL` symbol first,
/// then every global and weak one, each in insertion order. The locals are
/// exactly the module-local definitions, known up front, so locals take
/// `1..=L` and the global partition (definitions, then the undefined callees
/// in first-use order) starts at `L + 1`; the indices are re-read against the
/// serialized order before the object is written.
///
/// Relocated cross-function calls: one `R_RISCV_CALL` relocation at the
/// AUIPC's section offset against the callee's symbol (an undefined
/// `STT_FUNC` symbol, section 0, for an external one); the writer creates
/// `.rela.text` with `sh_link` -> `.symtab` and `sh_info` -> `.text`. A real
/// linker patches both the AUIPC hi20 and the following JALR lo12 from this
/// single relocation, addend 0.
///
/// [`crate::elf::ElfWriter::write_checked`] refuses, among the rest, a call
/// relocation whose 8-byte AUIPC+JALR field runs past `.text`, and re-parses
/// the object against the writer's intent.
fn riscv_module_object(
    text: &[u8],
    func_layout: &[(
        String,
        u64,
        u64,
        Vec<crate::riscv::pipeline::RiscVCallFixup>,
    )],
    relocated_calls: &[crate::riscv::pipeline::RiscVCallFixup],
    bindings: &RiscvFunctionBindings,
) -> Result<Vec<u8>, CompileError> {
    use crate::elf::{ElfMachine, ElfWriter};

    const STT_FUNC: u8 = 2;
    if let Some(name) = bindings.local.intersection(&bindings.weak).next() {
        return Err(CompileError::Pipeline(PipelineError::ObjectEmission(
            format!(
                "RISC-V module object: function `{name}` is named both module-local and weak; a \
             definition has one binding (fail-closed)"
            ),
        )));
    }
    let mut writer = ElfWriter::new(ElfMachine::Riscv64);
    writer.set_e_flags(crate::elf::constants::EF_RISCV_FLOAT_ABI_DOUBLE);
    writer.add_text_section(text);

    let local_count = func_layout
        .iter()
        .filter(|(name, ..)| bindings.local.contains(name))
        .count();
    let mut symbol_index: HashMap<String, u32> = HashMap::new();
    let mut next_local_index: u32 = 1;
    let mut next_symbol_index: u32 = u32::try_from(local_count)
        .ok()
        .and_then(|count| count.checked_add(1))
        .ok_or_else(|| {
            CompileError::Pipeline(PipelineError::ObjectEmission(format!(
                "RISC-V module object: {local_count} local function symbols overflow the ELF \
                 symbol index"
            )))
        })?;
    for (name, offset, size, _fixups) in func_layout {
        // Section 1 = the `.text` section just added.
        let counter = if bindings.local.contains(name) {
            writer.add_symbol(name, 1, *offset, *size, false, STT_FUNC);
            &mut next_local_index
        } else if bindings.weak.contains(name) {
            writer.add_weak_symbol(name, 1, *offset, *size, STT_FUNC);
            &mut next_symbol_index
        } else {
            writer.add_symbol(name, 1, *offset, *size, true, STT_FUNC);
            &mut next_symbol_index
        };
        symbol_index.insert(name.clone(), *counter);
        *counter += 1;
    }
    if next_local_index as usize != local_count + 1 {
        return Err(CompileError::Pipeline(PipelineError::ObjectEmission(
            format!(
                "RISC-V module object reserved {local_count} local function symbol(s) but emitted {}; \
             an unreserved local shifts every global symbol index (fail-closed)",
                next_local_index - 1
            ),
        )));
    }

    for fixup in relocated_calls {
        let sym_idx = if let Some(&idx) = symbol_index.get(&fixup.callee) {
            idx
        } else {
            let idx = next_symbol_index;
            next_symbol_index += 1;
            // Undefined external function symbol: section 0, value/size 0.
            writer.add_symbol(&fixup.callee, 0, 0, 0, true, STT_FUNC);
            symbol_index.insert(fixup.callee.clone(), idx);
            idx
        };
        let rela = crate::elf::reloc::Elf64Rela::riscv(
            u64::from(fixup.auipc_offset),
            sym_idx,
            crate::elf::reloc::RiscvRelocType::Call,
            0,
        );
        // `.text` is the first (and only) user section: 0-based index 0.
        writer.add_relocation(0, rela);
    }

    // Every index handed out above must name its symbol in the order the
    // writer serializes (locals first): the reparse gate compares relocation
    // records only as supplied, so it cannot see a shift.
    let order = writer.symbols_in_final_order();
    for (name, &index) in &symbol_index {
        let serialized = usize::try_from(index)
            .ok()
            .and_then(|index| index.checked_sub(1))
            .and_then(|slot| order.get(slot))
            .map(|symbol| symbol.name.as_str());
        if serialized != Some(name.as_str()) {
            return Err(CompileError::Pipeline(PipelineError::ObjectEmission(
                format!(
                    "RISC-V module object: symbol index {index} was handed to `{name}` but the \
                 writer serializes {serialized:?} there (fail-closed)"
                ),
            )));
        }
    }

    // Non-executable stack marker, added last so earlier section indices (and
    // the relocations naming them) are unchanged.
    writer.add_note_gnu_stack();
    writer
        .write_checked()
        .map_err(|error| CompileError::Pipeline(PipelineError::ElfReparse(error.to_string())))
}

