// Compiler
// ---------------------------------------------------------------------------

/// Test-only batching of actual RAW checker inputs. Production observes TV-3
/// inside Pipeline before optimization; prepared functions cannot be inputs.
#[cfg(test)]
fn validate_aarch64_dataflow_integrity(
    raw_funcs: &[trust_cg_ir::MachFunction],
    lir_functions: &[(trust_cg_lower::Function, trust_cg_lower::ProofContext)],
    policy: Aarch64DataflowIntegrityPolicy,
) -> Result<bool, CompileError> {
    if raw_funcs.len() != lir_functions.len() {
        return Err(CompileError::Pipeline(PipelineError::ISel(format!(
            "AArch64 dataflow-integrity input count mismatch: {} machine functions for {} LIR functions",
            raw_funcs.len(),
            lir_functions.len()
        ))));
    }
    let mut evaluated = false;
    for (func, (lir, _)) in raw_funcs.iter().zip(lir_functions.iter()) {
        evaluated |= crate::pipeline::check_raw_aarch64_dataflow_integrity(func, lir, policy)?
            .was_evaluated();
    }
    Ok(evaluated)
}

/// Check only pairing and nonvacuity of retained RAW observations here. Legal
/// optimization merges source blocks, so rerunning TV-3 on `prepared_funcs`
/// would apply the wrong contract. Final structure/RA/proof checks are separate
/// and remain mandatory at their existing boundaries.
fn validate_prepared_aarch64_dataflow_observations(
    prepared_funcs: &[trust_cg_ir::MachFunction],
    lir_functions: &[(trust_cg_lower::Function, trust_cg_lower::ProofContext)],
    metrics: &[crate::pipeline::PreparationMetrics],
    require_enforced: bool,
) -> Result<Option<Duration>, CompileError> {
    if prepared_funcs.len() != lir_functions.len() || metrics.len() != lir_functions.len() {
        return Err(CompileError::Pipeline(PipelineError::ISel(format!(
            "AArch64 raw dataflow-integrity observation count mismatch: {} machine functions, {} LIR functions, {} preparation records",
            prepared_funcs.len(),
            lir_functions.len(),
            metrics.len()
        ))));
    }
    // An empty inventory has no raw boundary to observe: return None, never
    // positive credit. Compiler/publication nonvacuity is checked separately.
    let mut duration = None;
    for ((func, (lir, _)), metrics) in prepared_funcs.iter().zip(lir_functions).zip(metrics) {
        let observation = metrics
            .pre_optimization_dataflow_integrity
            .as_ref()
            .ok_or_else(|| {
                CompileError::Pipeline(PipelineError::ISel(format!(
                    "AArch64 raw dataflow-integrity observation missing for `{}`",
                    func.name
                )))
            })?;
        observation.validate_pair(lir, &func.name, require_enforced)?;
        if observation.was_evaluated() {
            *duration.get_or_insert(Duration::ZERO) += observation.elapsed();
        }
    }
    Ok(duration)
}

/// The Trust Codegen compiler — top-level API for compiling trust_ir to machine code.
///
/// Wraps the internal [`Pipeline`] with a clean configuration interface,
/// structured results, optional tracing, and proof certificate emission.
pub struct Compiler {
    config: CompilerConfig,
    target_spec: TargetSpec,
    /// How `target_spec`'s OS/ABI was chosen; recorded on every result.
    target_selection_origin: TargetSelectionOrigin,
    jit_validation_resolution: OnceLock<Result<JitValidationResolution, Target>>,
    x86_jit_codegen_profile: OnceLock<EffectiveX86JitCodegenProfile>,
    aarch64_jit_isa_profile: OnceLock<AArch64IsaProfile>,
    profile_use: Option<trust_cg_opt::pgo::ProfData>,
    /// AOT PGO profile-generate sink. `Some` switches [`Compiler::compile`]
    /// into generate mode: per-block counter increments are injected during
    /// function preparation (see `Pipeline::with_profile_generate_sink`), the
    /// `__tcg_pgo_counters` / `__tcg_pgo_nsites` globals are appended to the
    /// object, and every counter site is recorded here for the caller's
    /// sites sidecar. AArch64-only; other targets fail closed.
    profile_generate_sink: Option<std::sync::Arc<std::sync::Mutex<trust_cg_opt::pgo::CounterMap>>>,
    compile_artifact_cache: Option<CompileArtifactCacheConfig>,
    certified_pass_chain: Option<CertifiedPassChainAttachment>,
    production_certified_pass_chain: bool,
    #[cfg(feature = "verify")]
    production_certified_pass_runs: Vec<trust_cg_opt::CertifiedPassRunRecord>,
    /// JIT-5 content-addressed certificate cache. `None` resolves to the
    /// process-global cache ([`crate::jit_cert::JitCertCache::global`]); tests
    /// inject a fresh instance for isolated hit/miss stats.
    jit_cert_cache: Option<std::sync::Arc<crate::jit_cert::JitCertCache>>,
    /// trust-ir v41 codegen-license policy (`Function.body_gate`). Enforced
    /// on the caller's module at the top of every compile entry — before any
    /// cache lookup, so a cached artifact can never bypass a refusal — and
    /// again inside the adapter. See [`CodegenLicensePolicy`].
    codegen_license: CodegenLicensePolicy,
    /// Dependency modules inline-only bodies may be authenticated against
    /// ([`crate::lir_module_prep::InlineOnlyAuthority`]); empty by default.
    inline_only_dependencies: Vec<std::sync::Arc<trust_ir::Module>>,
    /// The bytes a call that leaves the module (runtime import, libc, TLS
    /// resolver) may use below its caller's SP, declared by the caller for
    /// the U10 module reserve bound. An assumption the bound reports, never
    /// computed; it changes no emitted byte. Default 0.
    stack_limit_external_allowance: u64,
    /// The dialect legalization contract every compile entry applies before
    /// the adapter ([`crate::dialect_legalization`]); the backend default
    /// unless replaced with [`Self::with_dialect_legalization_registry`].
    dialect_legalization_registry: DialectLegalizationRegistry,
}

/// Generate proof certificates for a MachFunction by running the function
/// verifier from trust-cg-verify. Each verified instruction produces a
/// certificate recording the proof obligation name, category, and strength.
///
/// TV-2: when `lir_source` carries the EXACT LIR function that was handed to
/// instruction selection, the verifier additionally cross-checks every
/// emitted instruction's TV-1 lowering-provenance stamp against it. Proof
/// emission forces the mode-explicit fail-closed policy; ordinary AArch64
/// rollout defaults and process overrides are not authority at this boundary.
/// `None` (e.g. callers holding only a prebuilt `MachFunction`) has no source
/// graph to cross-check and produces a failed function prerequisite. Raw
/// instruction-report conversion is available separately without claiming
/// enforced source-compilation authority.
///
/// An instruction whose obligation discharged only by sampling arrives as an
/// `Unverified` report and becomes a fail-closed entry naming its sample count.
///
/// Only available when the `verify` feature is enabled.
///
/// `decode` is the ENC-5 backing of the bytes this function is published as
/// ([`Pipeline::aarch64_decode_check_backing`] of the pipeline that encodes
/// it).
#[cfg(feature = "verify")]
fn generate_proof_certificates(
    func: &trust_cg_ir::MachFunction,
    lir_source: Option<&trust_cg_lower::Function>,
    source_modules: Option<&trust_cg_verify::FunctionSourceModules<'_>>,
    decode: crate::decode_check::DecodeCheckBacking,
) -> Vec<ProofCertificate> {
    // `TCG_TIME_WALK=1`: split this function's certificate phase into the
    // walk (including its waits on in-flight sweeps) and certificate build.
    let timing = trust_cg_process_env::var_os("TCG_TIME_WALK").is_some();
    let t0 = timing.then(Instant::now);
    let (captured, obligations) =
        crate::jit_cert::run_on_proof_verifier_stack("trust-cg-aarch64-proof-verifier", || {
            let verifier = shared_aarch64_function_verifier();
            let request = verifier.capture_request_with_mode(
                trust_cg_verify::provenance_xcheck::ProvenanceXCheckMode::Enforce,
            );
            match source_modules {
                Some(source) => verifier
                    .verify_with_request_for_export_and_modules(func, lir_source, source, &request),
                None => verifier.verify_with_request_for_export(func, lir_source, &request),
            }
        });
    let t_walk = t0.map(|t| t.elapsed());
    let t_build = timing.then(Instant::now);
    let mut certs = proof_certificates_from_aarch64_report_with_obligations(
        captured.report(),
        &obligations,
        decode,
    );
    carry_request_ay_refusal_note(&mut certs, captured.ay_refusal_note());

    if let (Some(w), Some(t)) = (t_walk, t_build) {
        eprintln!(
            "TCG_TIME_CERTS fn={} walk={:.2}ms certs_build={:.2}ms n={}",
            func.name,
            w.as_secs_f64() * 1000.0,
            t.elapsed().as_secs_f64() * 1000.0,
            certs.len()
        );
    }
    certs
}

/// Carry `note`, the AY refusal note of the function-verification request
/// whose report produced `certs`
/// ([`trust_cg_verify::FunctionVerificationRequest::ay_refusal_note`]), on
/// every one of them, so a proof-promotion refusal over any of them names the
/// resolution that request was verified under instead of resolving AY again
/// ([`Compiler::unproved_evidence_rejected`]). `None` (the request had an AY)
/// leaves them without a note.
#[cfg(feature = "verify")]
fn carry_request_ay_refusal_note(certs: &mut [ProofCertificate], note: Option<String>) {
    if let Some(note) = note {
        for cert in certs {
            cert.ay_refusal_note = Some(note.clone());
        }
    }
}

/// Test adaptation of a report without retained arithmetic export payloads,
/// under an enforced ENC-5 backing, the backing of every proof-grade AArch64
/// publication.
#[cfg(all(test, feature = "verify"))]
fn proof_certificates_from_aarch64_report(
    report: &trust_cg_verify::function_verifier::FunctionVerificationReport,
) -> Vec<ProofCertificate> {
    proof_certificates_from_aarch64_report_with_obligations(
        report,
        &[],
        crate::decode_check::DecodeCheckBacking::Enforced,
    )
}

/// `decode` is the ENC-5 backing of the bytes the report's function is
/// published as ([`Pipeline::aarch64_decode_check_backing`]).
#[cfg(feature = "verify")]
fn proof_certificates_from_aarch64_report_with_obligations(
    report: &trust_cg_verify::function_verifier::FunctionVerificationReport,
    obligations: &[trust_cg_verify::SourceBoundArithmeticObligation],
    decode: crate::decode_check::DecodeCheckBacking,
) -> Vec<ProofCertificate> {
    use trust_cg_verify::function_verifier::InstructionVerificationResult;

    let mut certs = Vec::new();
    trace_opcode_inventory(report);

    if let Some(failure) = &report.precondition_failure {
        certs.push(ProofCertificate {
            ay_refusal_note: None,
            #[cfg(feature = "verify")]
            source_bound_obligation: None,
            rule_name: "verification_precondition".to_string(),
            verified: false,
            category: "verification_precondition".to_string(),
            strength: failure.to_string(),
            function_name: report.function_name.clone(),
        });
        #[cfg(test)]
        record_lane_certificates(report, decode, &certs);
        return certs;
    }

    append_emitted_opcode_inventory_certificate(&mut certs, report);

    for inst_report in &report.instructions {
        match &inst_report.result {
            InstructionVerificationResult::Verified {
                proof_name,
                category,
                strength,
                degenerate,
            } => {
                if *degenerate {
                    // STRICT: a structural X == X checks model consistency,
                    // not lowering correctness. The genuine-identity table is
                    // classification only; its names grant no publication credit.
                    certs.push(ProofCertificate {
                        ay_refusal_note: None,
                        #[cfg(feature = "verify")]
                        source_bound_obligation: None,
                        rule_name: proof_name.clone(),
                        verified: false,
                        category: format!("{}", category),
                        strength: format!(
                            "degenerate X==X proof proves nothing; not promotable on the compile path (mirrors coverage_gate discharge_one): {}",
                            proof_name
                        ),
                        function_name: report.function_name.clone(),
                    });
                } else {
                    certs.push(ProofCertificate {
                        ay_refusal_note: None,
                        #[cfg(feature = "verify")]
                        source_bound_obligation: obligations
                            .iter()
                            .find(|obligation| {
                                matches!(
                                    obligation.kind(),
                                    trust_cg_verify::SourceBoundObligationKind::A64Alu
                                        | trust_cg_verify::SourceBoundObligationKind::A64Constant
                                        | trust_cg_verify::SourceBoundObligationKind::A64Body
                                ) && obligation.instruction_index() == inst_report.inst_index
                                    && obligation.function_name() == report.function_name
                                    && obligation.proof_category() == *category
                                    && obligation.obligation().name == *proof_name
                                    && matches!(
                                        strength,
                                        trust_cg_verify::VerificationStrength::Formal
                                    )
                                    && !degenerate
                            })
                            .cloned(),
                        rule_name: proof_name.clone(),
                        verified: true,
                        category: format!("{}", category),
                        strength: format!("{:?}", strength),
                        function_name: report.function_name.clone(),
                    });
                }
            }
            InstructionVerificationResult::Failed { proof_name, detail } => {
                certs.push(ProofCertificate {
                    ay_refusal_note: None,
                    #[cfg(feature = "verify")]
                    source_bound_obligation: None,
                    rule_name: proof_name.clone(),
                    verified: false,
                    category: String::new(),
                    strength: format!("Failed: {}", detail),
                    function_name: report.function_name.clone(),
                });
            }
            InstructionVerificationResult::Unverified { reason } => {
                certs.push(unverified_instruction_certificate(
                    &report.function_name,
                    inst_report.inst_index,
                    inst_report.opcode,
                    reason,
                    decode,
                ));
            }
            InstructionVerificationResult::Skipped { .. } => {}
        }
    }

    #[cfg(test)]
    record_lane_certificates(report, decode, &certs);
    certs
}

/// Convert non-verified verifier reports into negative proof entries.
///
/// Downstream certified-output paths only see [`CompilationResult::proofs`].
/// If we drop `Unverified` reports here, a later function-level sidecar can
/// certify the verified subset and silently omit real instructions.
#[cfg(feature = "verify")]
fn non_verified_proof_report(
    function_name: &str,
    inst_index: usize,
    status: &str,
    detail: String,
) -> ProofCertificate {
    ProofCertificate {
        ay_refusal_note: None,
        #[cfg(feature = "verify")]
        source_bound_obligation: None,
        rule_name: format!("{}_instruction_{}", status, inst_index),
        verified: false,
        category: status.to_string(),
        strength: detail,
        function_name: function_name.to_string(),
    }
}

/// Test-only: record, for a probe function, the decode-check backing its
/// certificate lane handed a certificate builder and the certificates that
/// came out (`decode_check::lane_probe`), so unit tests can check each lane's
/// wiring through the real compile.
#[cfg(all(test, feature = "verify"))]
fn record_lane_certificates(
    report: &trust_cg_verify::function_verifier::FunctionVerificationReport,
    backing: crate::decode_check::DecodeCheckBacking,
    certs: &[ProofCertificate],
) {
    crate::decode_check::lane_probe::record(&report.function_name, || {
        crate::decode_check::lane_probe::Event::Certificates {
            backing,
            certs: certs.to_vec(),
        }
    });
}

/// The per-compile decode check a `covered_elsewhere` certificate for `opcode`
/// cites as the evidence for its emitted bytes, or `None` when its credit
/// rests on no per-compile check a diagnostic mode can switch off.
///
/// * x86-64 `MovRI`: the encoding half of its credit is ENC-3, whose `MovRI`
///   arm runs `trust_cg_verify::x86_encoding_proofs::mov_imm_check_for_preg`
///   on the emitted bytes (`x86_64::decode_check`). `TCG_DECODE_CHECK=off|warn`
///   and `TCG_NO_DECODE_CHECK=1` stop it from gating the compile.
/// * AArch64 `AlignNop`: its byte exactness is ENC-5's decode of the NOP word.
///   Compatibility routes honour `TCG_DECODE_CHECK_A64=off|warn` and
///   `TCG_NO_DECODE_CHECK=1`; proof-grade publication forces enforce.
///
/// The other covered-elsewhere opcodes cite a structural argument or a check
/// no mode switches off: the CALL/JMP/RET targets (the CFG edge and the
/// relocation), AArch64 `BR`/`CBZ`/`CBNZ`/`TBZ`/`TBNZ`
/// (`aarch64_switch_binding`, run in the shared AArch64 encode on every route
/// and fail-closed), `BLR` (the call lowering's obligation) and AArch64 `RET`
/// (a named deferral, `COVERED_ELSEWHERE_NAMED_DEFERRALS`).
#[cfg(feature = "verify")]
fn covered_elsewhere_cited_decode_check(
    opcode: trust_cg_verify::function_verifier::InstructionOpcode,
) -> Option<&'static str> {
    use trust_cg_ir::inst::AArch64Opcode as A;
    use trust_cg_ir::x86_64_ops::X86Opcode as X;
    use trust_cg_verify::function_verifier::InstructionOpcode as I;
    match opcode {
        I::X86_64(X::MovRI) => Some("ENC-3"),
        I::AArch64(A::AlignNop) => Some("ENC-5"),
        _ => None,
    }
}

/// Build the certificate for an `Unverified` instruction.
///
/// An indirect call/branch target (x86-64 `CallR`/`CallM`, AArch64 `Blr`) has no
/// per-instruction value-equivalence proof — the only candidate would be the
/// `target == target` tautology — yet its correctness IS established: the
/// target-address computation is verified instruction-by-instruction and the
/// CALL/BLR control transfer is architecturally fixed. The formal `coverage_gate`
/// already allowlists this family on exactly that basis. So it earns a positive
/// (covered-elsewhere) certificate rather than a fail-closed negative one;
/// without it the universal `lang_start → FnOnce::call_once` entry path (an
/// indirect `CallR` to `main`) fails proof promotion and `call_once` is emitted
/// as a trapping `ud2` stub the entry path then executes (SIGILL). Every other
/// `Unverified` opcode stays a real fail-closed negative entry — no vacuous proof
/// is admitted.
///
/// A covered-elsewhere row whose credit cites a per-compile decode check
/// ([`covered_elsewhere_cited_decode_check`]) is positive only when `decode`
/// says that check gated this compile ([`DecodeCheckBacking::Enforced`]).
/// Otherwise the row is WITHHELD: a `verified: false` certificate of category
/// [`proof_evidence::COVERED_ELSEWHERE_WITHHELD_CATEGORY`] that names the
/// check and why it did not back the bytes, so it blocks promotion. Until
/// 2026-10-12 the x86-64 `MovRI` and AArch64 `AlignNop` rows were positive
/// whether or not their check ran (X-OPCODES-P13).
///
/// [`DecodeCheckBacking::Enforced`]: crate::decode_check::DecodeCheckBacking::Enforced
#[cfg(feature = "verify")]
fn unverified_instruction_certificate(
    function_name: &str,
    inst_index: usize,
    opcode: trust_cg_verify::function_verifier::InstructionOpcode,
    reason: &str,
    decode: crate::decode_check::DecodeCheckBacking,
) -> ProofCertificate {
    let covered_elsewhere = |strength: String| ProofCertificate {
        ay_refusal_note: None,
        #[cfg(feature = "verify")]
        source_bound_obligation: None,
        rule_name: format!("covered_elsewhere_instruction_{}", inst_index),
        verified: true,
        category: crate::proof_evidence::COVERED_ELSEWHERE_CATEGORY.to_owned(),
        strength,
        function_name: function_name.to_string(),
    };
    let structural =
        trust_cg_verify::function_verifier::is_covered_elsewhere_indirect_branch(opcode)
            || trust_cg_verify::function_verifier::is_covered_elsewhere_emission_padding(opcode);
    if structural
        && let Some(check) = covered_elsewhere_cited_decode_check(opcode)
        && let Some(why) = decode.withheld_reason(check)
    {
        return non_verified_proof_report(
            function_name,
            inst_index,
            crate::proof_evidence::COVERED_ELSEWHERE_WITHHELD_CATEGORY,
            format!(
                "{opcode}: covered_elsewhere withheld: its credit cites the per-compile {check} \
                 decode check of its emitted bytes, and {why}"
            ),
        );
    }
    if matches!(
        opcode,
        trust_cg_verify::function_verifier::InstructionOpcode::X86_64(
            trust_cg_ir::x86_64_ops::X86Opcode::MovRI
        )
    ) {
        covered_elsewhere(format!(
            "{opcode}: constant materialization — the emitted MOV r,imm bytes passed ENC-3, \
             enforced in this compile (x86_encoding_proofs::mov_imm_check_for_preg: the full \
             64-bit write to the root register against the machine-IR intent); covers the \
             encoding, not the lowerer's choice of constant; mirrors coverage_gate allowlist"
        ))
    } else if trust_cg_verify::function_verifier::is_covered_elsewhere_indirect_branch(opcode) {
        covered_elsewhere(format!(
            "{}: indirect call/branch target — correctness covered by surrounding proofs \
             (verified target-address computation + architecturally-fixed control transfer), \
             not a per-instruction tautology; mirrors coverage_gate allowlist",
            opcode
        ))
    } else if trust_cg_verify::function_verifier::is_covered_elsewhere_emission_padding(opcode) {
        covered_elsewhere(format!(
            "{}: emission-time alignment padding with no value, memory, or branch semantics; \
             byte exactness is pinned by the AArch64 decode check and offset integrity by \
             the independent EH/encoder offset cross-check",
            opcode
        ))
    } else {
        non_verified_proof_report(
            function_name,
            inst_index,
            "unverified",
            format!("Unverified {}: {}", opcode, reason),
        )
    }
}

/// `-Ztrust-ir-cg-args=opcode-inventory-trace` (standalone:
/// `TCG_TRACE_OPCODE_INVENTORY=1`): print every function's opcode-inventory
/// census lines (`EmittedOpcodeInventoryReport::census_lines`) to stderr, so a
/// census can classify every blocking row rather than the first one a refusal
/// names. Diagnostic only; it changes no verdict and no emitted byte.
#[cfg(feature = "verify")]
fn trace_opcode_inventory(report: &trust_cg_verify::function_verifier::FunctionVerificationReport) {
    if !trust_cg_verify::diag::opcode_inventory_trace_enabled() {
        return;
    }
    let lines = report.emitted_opcode_inventory().census_lines().join("\n");
    eprintln!("{lines}");
}

/// Emit a fail-closed proof entry when the verifier inventory finds uncovered
/// emitted opcodes. This makes proof-required promotion depend on complete
/// target-aware opcode coverage, not just the existence of some verified rows.
#[cfg(feature = "verify")]
fn append_emitted_opcode_inventory_certificate(
    certs: &mut Vec<ProofCertificate>,
    report: &trust_cg_verify::function_verifier::FunctionVerificationReport,
) {
    let inventory = report.emitted_opcode_inventory();
    if let Some(reason) = inventory.promotion_rejection_reason() {
        certs.push(non_verified_proof_report(
            &report.function_name,
            0,
            "opcode_inventory",
            reason,
        ));
    }
}

/// Emit a fail-closed proof entry when object emission produces relocations
/// without registered proof coverage. Instruction proofs alone do not certify
/// linker-visible object metadata, so this category blocks proof-required
/// promotion until object relocation proofs catch up.
#[cfg(feature = "verify")]
fn append_object_relocation_inventory_certificate(
    certs: &mut Vec<ProofCertificate>,
    report: &trust_cg_verify::ObjectRelocationInventoryReport,
) {
    append_object_relocation_inventory_certificate_disclosing(certs, report, None);
}

/// [`append_object_relocation_inventory_certificate`], naming in its text the
/// object content the relocation rows point into that is trusted rather than
/// proven (`trusted`), such as unwind CFI.
#[cfg(feature = "verify")]
fn append_object_relocation_inventory_certificate_disclosing(
    certs: &mut Vec<ProofCertificate>,
    report: &trust_cg_verify::ObjectRelocationInventoryReport,
    trusted: Option<&str>,
) {
    let row_evidence = object_relocation_inventory_evidence(report);
    let trusted = trusted
        .map(|trusted| format!("; trusted, not proven: {trusted}"))
        .unwrap_or_default();
    let (verified, strength) = match report.promotion_rejection_reason() {
        Some(reason) => (false, format!("{reason}{trusted}")),
        None => (
            true,
            format!(
                "object relocation inventory verified for {}; {} emitted relocation row(s) covered{trusted}; evidence={}",
                report.object_name,
                report.entries.len(),
                row_evidence
            ),
        ),
    };

    certs.push(ProofCertificate {
        ay_refusal_note: None,
        #[cfg(feature = "verify")]
        source_bound_obligation: None,
        rule_name: "object_relocation_inventory".to_string(),
        verified,
        category: "relocation_inventory".to_string(),
        strength,
        function_name: report.object_name.clone(),
    });
}

#[cfg(feature = "verify")]
fn object_relocation_inventory_evidence(
    report: &trust_cg_verify::ObjectRelocationInventoryReport,
) -> String {
    let mut rows = report
        .entries
        .iter()
        .map(|entry| {
            format!(
                "{}:{}:{:?}:{}",
                entry.index, entry.kind, entry.status, entry.detail
            )
        })
        .collect::<Vec<_>>();
    rows.sort();
    rows.join("|")
}

/// x86-64 mirror of [`generate_proof_certificates`] (#465).
///
/// Walks an [`trust_cg_lower::x86_64_isel::X86ISelFunction`] via the
/// [`trust_cg_verify::X86FunctionVerifier`] and emits a [`ProofCertificate`]
/// per verified instruction. Output shape matches the AArch64 path so the
/// public `CompilationResult::proofs` vector is target-agnostic.
/// Process-level shared x86-64 function verifier.
///
/// Construction materializes the fixed, immutable proof database and selects
/// `VerificationConfig::for_proof_promotion()`. The x86-64 walk replays one
/// live obligation per admitted function, the source-bound body theorem (when
/// the caller supplies the calling convention); otherwise it credits only
/// completely discharged reconstructions, and reports registry-name
/// candidates and sampled discharges as unverified for the certificate gate
/// to reject. Rebuilding this
/// state per function would turn an O(#obligations) setup into
/// O(#functions x #obligations); the verifier is otherwise stateless, so a
/// single process-wide instance is safe.
#[cfg(feature = "verify")]
fn shared_x86_64_function_verifier() -> &'static trust_cg_verify::X86FunctionVerifier {
    static VERIFIER: std::sync::OnceLock<trust_cg_verify::X86FunctionVerifier> =
        std::sync::OnceLock::new();
    VERIFIER.get_or_init(|| {
        trust_cg_verify::X86FunctionVerifier::with_config(
            trust_cg_verify::VerificationConfig::for_proof_promotion(),
        )
    })
}

/// Process-level shared AArch64 function verifier.
///
/// Like the x86-64 verifier above, construction materializes the immutable proof
/// database and selects the compiler-only `SourceBoundReplay` policy. Verification
/// itself takes `&self`, so rebuilding that fixed state for every function only
/// multiplies setup work without changing any report or proof authority.
#[cfg(feature = "verify")]
pub(crate) fn shared_aarch64_function_verifier()
-> &'static trust_cg_verify::function_verifier::FunctionVerifier {
    static INIT_TRACE: std::sync::Once = std::sync::Once::new();
    INIT_TRACE.call_once(|| {
        if trust_cg_process_env::var_os("TCG_TIME_SWEEP").is_some() {
            let t0 = std::time::Instant::now();
            let _ = shared_aarch64_function_verifier_inner();
            eprintln!(
                "TCG_VERIFIER_INIT first_call={:.1}ms",
                t0.elapsed().as_secs_f64() * 1000.0
            );
        }
    });
    shared_aarch64_function_verifier_inner()
}

#[cfg(feature = "verify")]
fn shared_aarch64_function_verifier_inner()
-> &'static trust_cg_verify::function_verifier::FunctionVerifier {
    static VERIFIER: std::sync::OnceLock<trust_cg_verify::function_verifier::FunctionVerifier> =
        std::sync::OnceLock::new();
    VERIFIER.get_or_init(|| {
        trust_cg_verify::function_verifier::FunctionVerifier::with_config(
            trust_cg_verify::VerificationConfig::for_proof_promotion(),
        )
    })
}

/// CT-7: warm the shared x86-64 proof verifier OFF the compile's critical
/// path.
///
/// Builds the process-wide verifier — the full `ProofDatabase`, ~100ms of
/// pure obligation-tree construction that the FIRST certificate lane
/// otherwise serializes behind (every cert worker blocks on the shared
/// `OnceLock` while one thread builds it). A front-end host (the rustc
/// bridge) calls this on a DETACHED background thread as soon as it knows
/// codegen is coming, so the build overlaps MIR lowering instead of landing
/// inside `x86_proof_certs`.
///
/// Deliberately does NOT pre-discharge registry verdicts: sweeping the whole
/// fixed registry costs tens of CPU-seconds (most rows are never touched by
/// a given program) and floods the shared verifier pool ahead of the
/// compile's own certificate work — measured as a 9x wall regression. Lazy
/// first-touch discharge through the compute-once memo stays the policy.
///
/// Pure cache warming: construction is exactly what the first cert walk
/// would run lazily, so behavior — including every fail-closed verdict — is
/// byte-identical with or without warming; only the timing moves. Safe to
/// call from any thread, any number of times.
#[cfg(feature = "verify")]
pub fn warm_x86_64_proof_verifier() {
    let _ = shared_x86_64_function_verifier();
}

/// Worker count for the flat-tape sweep pre-warm: the host's parallelism,
/// capped by an explicit `TRUST_CG_MAX_PARALLELISM`, NOT capped by the item count (one obligation is many chunks, see `lowering_proof::fan_out_chunks`),
/// and `None` when there is nothing to sweep. Deliberately independent of the deep-walk
/// verifier pool's limit (see the pre-warm comment in `compile`).
#[cfg(feature = "verify")]
fn sweep_prewarm_width(
    item_count: usize,
) -> Result<Option<usize>, trust_cg_process_env::resource_budget::ResourceBudgetError> {
    if item_count == 0 {
        return Ok(None);
    }
    let cap =
        crate::resource_limits::artifact_neutral_parallelism_limit(std::num::NonZeroUsize::MAX)?
            .get();
    // NOT `cap.min(item_count)`: one obligation is no longer one task. Its
    // 100k-sample sweep splits into chunks across whatever pool it runs on
    // (`lowering_proof::fan_out_chunks`), so even a single-kind round fills
    // the pool — and a single-kind round was exactly the third CGU of every
    // corpus compile, previously swept inline on one thread.
    Ok((cap >= 2).then_some(cap))
}

/// The ONE process-wide sweep pool: host-wide (bounded by
/// `TRUST_CG_MAX_PARALLELISM`), default stacks — see the pre-warm site for why
/// it is not the 32 MiB-stack verifier pool. Built once, on first use, by
/// whichever caller comes first (the init-time speculative sweep, normally);
/// every per-CGU pre-warm round then reuses it instead of spawning and joining
/// 20 threads per round (3-4 rounds per compile on the corpus). `None` on a
/// single-core host or when the operator pins parallelism to 1.
#[cfg(feature = "verify")]
static SWEEP_POOL: std::sync::OnceLock<
    std::sync::Mutex<Option<std::sync::Arc<rayon::ThreadPool>>>,
> = std::sync::OnceLock::new();

#[cfg(feature = "verify")]
fn sweep_pool() -> Result<
    Option<std::sync::Arc<rayon::ThreadPool>>,
    trust_cg_process_env::resource_budget::ResourceBudgetError,
> {
    let width = sweep_prewarm_width(1)?;
    let slot = SWEEP_POOL.get_or_init(|| {
        let pool = width.and_then(|width| {
            rayon::ThreadPoolBuilder::new()
                .num_threads(width)
                .thread_name(|idx| format!("trust-cg-sweep-{idx}"))
                .build()
                .ok()
                .map(std::sync::Arc::new)
        });
        // Every sweep in the process — the certificate walk's included — fans
        // its sample chunks out to this pool from now on.
        trust_cg_verify::lowering_proof::set_sweep_helper_pool(pool.clone());
        std::sync::Mutex::new(pool)
    });
    Ok(slot
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .clone())
}

/// Let the sweep pool's workers go once no more sweeps can run (the bridge
/// calls this at the end of `join_codegen`). The pool is dropped on a
/// detached thread, so its 20 workers are torn down while rustc links rather
/// than inside `exit` — measured on the corpus as 5-10ms of the after-join
/// segment with the pool alive (an 8-worker pool recovered it but cost the
/// sweeps up to 12ms). A sweep still holding the `Arc` (the speculative one,
/// if it is somehow still running) keeps the pool alive until it finishes;
/// the drop then happens on that thread. Any later `sweep_pool()` call gets
/// `None` and sweeps inline, exactly as on a single-core host.
#[cfg(feature = "verify")]
pub fn release_sweep_pool() {
    let Some(slot) = SWEEP_POOL.get() else { return };
    let pool = slot
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .take();
    trust_cg_verify::lowering_proof::set_sweep_helper_pool(None);
    if let Some(pool) = pool {
        let _ = std::thread::Builder::new()
            .name("trust-cg-sweep-release".to_owned())
            .spawn(move || drop(pool));
    }
}

/// One unit of ASYNCHRONOUS sweep pre-warm work: an owned reconstruction-arm
/// obligation and its canonical theorem, so the owners can outlive the compile
/// phase that spawned them. Registry theorems are never pre-warmed: the walk
/// no longer discharges any.
#[cfg(feature = "verify")]
type AsyncSweepItem = (
    trust_cg_verify::ProofObligation,
    trust_cg_verify::ProofObligation,
);

/// Asynchronous bounded-owner sweep: `threads / 2` (capped at 10)
/// owner jobs are spawned onto `pool`, each pulling items from one counter
/// until it is exhausted, and NOBODY waits — the caller proceeds to the
/// certificate walk, which blocks per memo cell exactly where it must.
/// Owners hold no cell while pulling and never enter a rayon wait inside
/// one, so the deadlock argument of `fan_out_chunks` is unchanged.
#[cfg(feature = "verify")]
fn spawn_bounded_owner_sweeps(
    pool: &rayon::ThreadPool,
    items: Vec<AsyncSweepItem>,
    verifier: &'static trust_cg_verify::function_verifier::FunctionVerifier,
) {
    let owners = (pool.current_num_threads() / 2)
        .clamp(1, 10)
        .min(items.len().max(1));
    spawn_owner_sweeps(pool, items, verifier, owners);
}

/// Spawn at most `owner_limit` independent prewarm owners. Evaluation owners
/// fan their sample chunks back into the same pool, so the caller passes the
/// half-pool bound above.
#[cfg(feature = "verify")]
fn spawn_owner_sweeps(
    pool: &rayon::ThreadPool,
    items: Vec<AsyncSweepItem>,
    verifier: &'static trust_cg_verify::function_verifier::FunctionVerifier,
    owner_limit: usize,
) {
    if items.is_empty() {
        return;
    }
    let owners = owner_limit
        .max(1)
        .min(pool.current_num_threads())
        .min(items.len());
    let items = std::sync::Arc::new(items);
    let next = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
    let environment =
        std::sync::Arc::new(trust_cg_process_env::EnvOverrideSnapshot::capture_current_thread());
    for _ in 0..owners {
        let (items, next, environment) = (
            std::sync::Arc::clone(&items),
            std::sync::Arc::clone(&next),
            std::sync::Arc::clone(&environment),
        );
        pool.spawn(move || {
            environment.run(|| {
                loop {
                    let i = next.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                    let Some((inst, canon)) = items.get(i) else {
                        return;
                    };
                    verifier.discharge_reconstructed_obligation_now(inst, canon)
                }
            })
        });
    }
}

/// AArch64 twin of [`warm_x86_64_proof_verifier`]: build the shared verifier's
/// proof database off the critical path. See the bridge's `codegen_crate`.
/// Gated identically to the x86 twin — `shared_aarch64_function_verifier` only
/// exists under `verify`, and an ungated wrapper would break the default-feature
/// build the moment anything called it.
#[cfg(feature = "verify")]
pub fn warm_aarch64_proof_verifier() {
    let _ = shared_aarch64_function_verifier();
}

/// Resident-set probe at a pipeline stage boundary, for compile-MEMORY work.
///
/// The compile-time trace (`TCG_TIME`) says where the seconds go; this says
/// where the bytes go, which is what a retention question needs. Off unless
/// `TCG_MEMTRACE` is set — the `ps` spawn only ever happens on the opt-in
/// path, and the probe is read-only, so it cannot perturb what it measures
/// beyond its own (tiny, reported) footprint.
///
/// The probe points bracket the stages whose live sets a batched CGU holds
/// simultaneously: merge -> adapter (LIR) -> ISel -> optimization -> module
/// assembly -> object emission. See the [MEM-STREAM] notes in
/// [`Compiler::compile_x86_64`].
pub fn memtrace(label: &str) {
    if trust_cg_process_env::var_os("TCG_MEMTRACE").is_none() {
        return;
    }
    let pid = std::process::id().to_string();
    if let Ok(out) = std::process::Command::new("ps")
        .args(["-o", "rss=", "-p", &pid])
        .output()
    {
        let kb = String::from_utf8_lossy(&out.stdout).trim().to_string();
        eprintln!("TCG_MEMTRACE {label}: rss_kb={kb}");
    }
}

/// JIT-5 config fingerprint for the x86-64 certificate cache key.
///
/// Never name-only: folds the target, opt level, alloc profile, validation
/// mode, and a compiler-rev salt (crate version) so a cached verdict can never
/// be reused across a config change or a code change. Mirrors the content-key
/// discipline of the AOT verdict cache (PROOF-2/PROOF-3); JIT-6 will extend the
/// salt with the dependency identities a soundness attestation records, for the
/// disk-backed cache.
// Consumed only by the verifying JIT cert path; non-verify builds never reach it.
#[cfg(feature = "verify")]
fn x86_jit_config_fingerprint(
    config: &CompilerConfig,
    mode: JitValidationMode,
    verification_policy: X86JitVerificationPolicy,
) -> Vec<u8> {
    format!(
        concat!(
            "trust-cg.jit.x86_64.config.v4\n",
            "target={:?}\n",
            "opt_level={:?}\n",
            "enable_jit_fast_regalloc={}\n",
            "external_symbol_resolution={}\n",
            "validation_mode={}\n",
            "provenance_xcheck={}\n",
            "compiler_rev={}\n",
        ),
        config.target,
        config.opt_level,
        config.enable_jit_fast_regalloc,
        config.jit_external_symbol_resolution.canonical_name(),
        mode.label(),
        verification_policy.provenance_xcheck_label(),
        env!("CARGO_PKG_VERSION"),
    )
    .into_bytes()
}

/// Typed, once-captured verifier policy for one x86 JIT certification batch.
///
/// Proof publication always enforces source provenance, regardless of the
/// diagnostic rollout override. The enforced mode remains part of the
/// content-addressed cache identity. Deep reconstructed-solver/DB overrides
/// still resolve inside the verifier today; while any such override is active
/// we conservatively bypass this outer cache so an override-specific verdict
/// can neither populate nor consume a default-policy entry.
///
/// `enc3` is the ENC-3 backing of the bytes the batch certifies: the mode the
/// x86 encode funnel resolved, read on the compiling thread whose environment
/// snapshot the encode workers ran under. A batch whose ENC-3 did not gate the
/// compile bypasses the outer cache too, so a certificate cached under an
/// enforced check is never reused for bytes no check gated, and a compile
/// under a relaxed check never populates the cache.
#[derive(Debug, Clone, Copy)]
#[cfg(feature = "verify")]
struct X86JitVerificationPolicy {
    provenance_xcheck: trust_cg_verify::provenance_xcheck::ProvenanceXCheckMode,
    enc3: crate::decode_check::DecodeCheckBacking,
    outer_cache_allowed: bool,
}

#[cfg(feature = "verify")]
impl X86JitVerificationPolicy {
    fn capture() -> Self {
        use trust_cg_verify::provenance_xcheck::ProvenanceXCheckMode;

        let enc3 = x86_enc3_backing_of_this_compile();
        Self {
            provenance_xcheck: ProvenanceXCheckMode::Enforce,
            enc3,
            outer_cache_allowed: !crate::jit_cert::deep_verifier_override_disables_outer_cache()
                && enc3.gates_the_compile(),
        }
    }

    const fn provenance_xcheck_label(self) -> &'static str {
        use trust_cg_verify::provenance_xcheck::ProvenanceXCheckMode;

        match self.provenance_xcheck {
            ProvenanceXCheckMode::Off => "off",
            ProvenanceXCheckMode::Warn => "warn",
            ProvenanceXCheckMode::Enforce => "enforce",
        }
    }
}

/// One-function adapter over [`generate_x86_64_proof_certificates_in_module`]
/// with a fresh request (tests; the compile lanes share one per module), under
/// an enforced ENC-3 backing, the default compile's.
#[cfg(all(test, feature = "verify"))]
fn generate_x86_64_proof_certificates(
    func: &trust_cg_lower::x86_64_isel::X86ISelFunction,
    lir_source: Option<&trust_cg_lower::Function>,
    abi: trust_cg_lower::x86_64_isel::X86CallAbi,
) -> Vec<ProofCertificate> {
    generate_x86_64_proof_certificates_in_module(
        func,
        lir_source,
        abi,
        &X86ModuleVerificationRequest::new(),
        &x86_test_module_definitions(lir_source),
        crate::decode_check::DecodeCheckBacking::Enforced,
    )
}

/// Tests: the definitions of a module that defines exactly the given LIR
/// functions (OD-210).
#[cfg(test)]
fn x86_test_module_definitions<'a>(
    functions: impl IntoIterator<Item = &'a trust_cg_lower::Function>,
) -> trust_cg_verify::X86ModuleDefinitions {
    trust_cg_verify::X86ModuleDefinitions::of_symbols(
        functions.into_iter().map(|function| function.name.as_str()),
    )
}

/// [`proof_certificates_from_x86_64_report`] for a test's report, under an
/// enforced ENC-3 backing, so its rows are judged as the default compile's
/// would be; the backing itself is pinned by
/// `covered_elsewhere_rows_citing_a_decode_check_need_it_to_gate_the_compile`.
#[cfg(all(test, feature = "verify"))]
fn x86_fixture_certificates(
    report: &trust_cg_verify::FunctionVerificationReport,
    lir_source: Option<&trust_cg_lower::Function>,
) -> Vec<ProofCertificate> {
    proof_certificates_from_x86_64_report(
        report,
        lir_source,
        crate::decode_check::DecodeCheckBacking::Enforced,
    )
}

/// The ENC-3 backing of every x86-64 function this compile encodes.
///
/// The encode funnel (`X86Pipeline::encode_function_with_all_fixups_and_block_metadata`)
/// resolves [`crate::decode_check::decode_check_mode`] once per function, on
/// the compiling thread or on a worker running under that thread's
/// `EnvOverrideSnapshot`, and the process environment is never mutated
/// (`trust_cg_process_env`). Resolving it here, on the compiling thread or
/// under the same snapshot, therefore yields the mode that funnel ran, and in
/// [`crate::decode_check::DecodeCheckMode::Enforce`] a refutation has already
/// failed the compile before any certificate is built.
#[cfg(feature = "verify")]
fn x86_enc3_backing_of_this_compile() -> crate::decode_check::DecodeCheckBacking {
    crate::decode_check::DecodeCheckBacking::from_mode(crate::decode_check::decode_check_mode())
}

/// The x86-64 certificate lane's verification request, shared by every
/// function of one module: captured at most once, on the first function whose
/// source the source-bound body lane admits (a module with none never
/// captures one).
#[cfg(feature = "verify")]
type X86ModuleVerificationRequest =
    std::sync::OnceLock<trust_cg_verify::FunctionVerificationRequest>;

/// The x86-64 AOT certificate lane for one function.
///
/// TV-2: when `lir_source` carries the EXACT LIR function that was handed to
/// instruction selection, the verifier additionally cross-checks every
/// emitted instruction's TV-1 lowering-provenance stamp against it and FAILS
/// CLOSED on a mismatch. This proof-authoritative boundary always enforces
/// the source check, independent of diagnostic environment overrides. Missing
/// or name-mismatched LIR produces unverified reports, including for empty code.
///
/// `abi` is the calling convention this compile selected for the function
/// (target spec for AOT, host for JIT). It lets the x86-64 source-bound body
/// owner apply and is bound into the verifier-input digest. The replayed body
/// theorem is retained as each credited row's `source_bound_obligation`, so
/// `--emit-proofs` can re-check it against the replay authority before
/// publishing.
///
/// Only a pair the body owner may judge
/// ([`trust_cg_verify::x86_source_bound_body::pair_admits_x86_body_owner`]:
/// its source for a pair one query states, the split's own checks for a pair
/// stated in parts) needs the module's captured request, the replay context
/// and the export payloads. Every other function takes the request-free
/// enforced walk, whose report is exactly what the request path produces when
/// no body owner applies; capturing a request and hashing the verifier input
/// per out-of-lane function more than doubled the proofs-on compile time of a
/// large module. Within the lane the input is hashed only when a replayed
/// theorem is retained for export
/// ([`trust_cg_verify::X86FunctionVerifier::verify_for_certificates`]). Both
/// walks name `module_definitions` (OD-210, OD-216).
#[cfg(feature = "verify")]
fn generate_x86_64_proof_certificates_in_module(
    func: &trust_cg_lower::x86_64_isel::X86ISelFunction,
    lir_source: Option<&trust_cg_lower::Function>,
    abi: trust_cg_lower::x86_64_isel::X86CallAbi,
    module_request: &X86ModuleVerificationRequest,
    module_definitions: &trust_cg_verify::X86ModuleDefinitions,
    enc3: crate::decode_check::DecodeCheckBacking,
) -> Vec<ProofCertificate> {
    use trust_cg_verify::provenance_xcheck::ProvenanceXCheckMode;

    let verifier = shared_x86_64_function_verifier();
    let abi = Some(x86_source_bound_abi(abi));
    let in_lane = lir_source.is_some_and(|lir| {
        trust_cg_verify::x86_source_bound_body::pair_admits_x86_body_owner(lir, func, abi)
    });
    if !in_lane {
        // The owner refuses this pair before any machine walk or replay
        // (`pair_admits_x86_body_owner`), so the request-free walk gives the
        // report the request path would; passing the ABI lets
        // `x86-body-trace` name the actual refusal (a Win64 function's
        // convention, not a missing one). It names the module's definitions
        // all the same (OD-210, amended): no verifier entry that takes an
        // ABI can name none, so a predicate that admits too little costs
        // exports, never a theorem (before, `core`'s `exp_u128` and
        // `parse_decimal_seq`, stated in parts, were refused here as
        // `Unnamed`).
        let report =
            crate::jit_cert::run_on_proof_verifier_stack("trust-cg-x86_64-proof-verifier", || {
                verifier.verify_with_lir_source_abi_and_mode_in_module(
                    func,
                    lir_source,
                    abi,
                    module_definitions,
                    ProvenanceXCheckMode::Enforce,
                )
            });
        return proof_certificates_from_x86_64_report(&report, lir_source, enc3);
    }
    // Capture on the verifier stack, as the AArch64 lane does: capturing
    // applies the request's policy as thread-local overrides, which would
    // invalidate the compiling thread's compile-artifact reuse permit and
    // silently disable the object cache for the whole module.
    let (report, exports, request_note) =
        crate::jit_cert::run_on_proof_verifier_stack("trust-cg-x86_64-proof-verifier", || {
            let request = module_request
                .get_or_init(|| verifier.capture_request_with_mode(ProvenanceXCheckMode::Enforce));
            let (report, exports) = verifier.verify_for_certificates(
                func,
                lir_source,
                abi,
                module_definitions,
                request,
            );
            (report, exports, request.ay_refusal_note())
        });
    let mut certs =
        proof_certificates_from_x86_64_report_with_obligations(&report, lir_source, &exports, enc3);
    carry_request_ay_refusal_note(&mut certs, request_note);
    certs
}

/// The verifier's calling-convention identity for the selector's ABI.
#[cfg(feature = "verify")]
pub(crate) fn x86_source_bound_abi(
    abi: trust_cg_lower::x86_64_isel::X86CallAbi,
) -> trust_cg_verify::X86SourceBoundAbi {
    match abi {
        trust_cg_lower::x86_64_isel::X86CallAbi::SystemV => {
            trust_cg_verify::X86SourceBoundAbi::SystemV
        }
        trust_cg_lower::x86_64_isel::X86CallAbi::WindowsX64 => {
            trust_cg_verify::X86SourceBoundAbi::WindowsX64
        }
    }
}

/// Mode-explicit, request-free adapter (tests pin that diagnostic mode
/// overrides cannot weaken the authoritative lanes).
#[cfg(all(test, feature = "verify"))]
fn generate_x86_64_proof_certificates_with_mode(
    func: &trust_cg_lower::x86_64_isel::X86ISelFunction,
    lir_source: Option<&trust_cg_lower::Function>,
    abi: trust_cg_lower::x86_64_isel::X86CallAbi,
    provenance_xcheck: trust_cg_verify::provenance_xcheck::ProvenanceXCheckMode,
) -> Vec<ProofCertificate> {
    let report =
        crate::jit_cert::run_on_proof_verifier_stack("trust-cg-x86_64-proof-verifier", || {
            shared_x86_64_function_verifier().verify_with_lir_source_abi_and_mode_in_module(
                func,
                lir_source,
                Some(x86_source_bound_abi(abi)),
                &x86_test_module_definitions(lir_source),
                provenance_xcheck,
            )
        });
    proof_certificates_from_x86_64_report(
        &report,
        lir_source,
        crate::decode_check::DecodeCheckBacking::Enforced,
    )
}

#[cfg(feature = "verify")]
fn generate_x86_64_captured_proof_report(
    func: &trust_cg_lower::x86_64_isel::X86ISelFunction,
    lir_source: Option<&trust_cg_lower::Function>,
    abi: trust_cg_lower::x86_64_isel::X86CallAbi,
    module: &trust_cg_verify::X86ModuleDefinitions,
    request: &trust_cg_verify::FunctionVerificationRequest,
) -> trust_cg_verify::CapturedFunctionVerificationReport {
    crate::jit_cert::run_on_proof_verifier_stack("trust-cg-x86_64-proof-verifier", || {
        shared_x86_64_function_verifier().verify_with_request_and_abi(
            func,
            lir_source,
            Some(x86_source_bound_abi(abi)),
            module,
            request,
        )
    })
}

/// Whether an x86-64 report describes a body with NO value instruction: the
/// frame envelope (`push rbp; mov rbp, rsp; pop rbp`) around either the
/// return transfer or the trap, and nothing else.
///
/// Such a function — a data static's `.static.anchor`, an empty `fn f() {}`,
/// `process::abort_immediate` (`intrinsics::abort()`), a `-> !` body that is
/// a single `match x {}` on an uninhabited type — has no instruction with
/// value semantics. "No genuinely discharged instruction proof" is then not
/// missing evidence but the absence of anything to discharge: `PUSH`/`POP`/
/// `RET` are fail-closed-allowlisted control and frame transfers with no
/// value proof by design (the frame layout is checked by frame lowering's own
/// validators, the return edge by the CFG model), and `UD2` is the skipped
/// trap, so the non-vacuous rule would reject every such function on x86-64
/// while the AArch64 certificate path applies no vacuity rule at all.
/// Measured on 2026-09-20: 102 of 622 `core` roots on x86-64 Linux were
/// static anchors refused exactly this way; on 2026-09-21 the trap-only body
/// was measured through this pipeline as `55 48 89 e5 0f 0b` (`push rbp; mov
/// rbp, rsp; ud2`) and refused the same way.
///
/// Exact opcode sequences only. A report row carries no operands, so it cannot
/// tell the frame `MOV rbp, rsp` from a value copy; any longer sequence keeps
/// the rule, and a body that emits a single value instruction — even an
/// unverified one, even an immediate move before the trap — is still
/// rejected.
///
/// One more shape is admitted, and only against its SOURCE: a direct `CALL`
/// followed by the trap (`push rbp; mov rbp, rsp; call <sym>; ud2`) when the
/// LIR function handed to instruction selection is exactly a zero-argument,
/// zero-result direct call followed by a trap. That is what the bridge emits
/// under `-Cpanic=abort` for every `-> !` panic entry (`panic_const_*`,
/// `unwrap_failed`, `panic_already_borrowed`, …): the message and location
/// arguments are gone at the source level and the callee is `abort`, so the
/// call target is a relocation the object relocation inventory certifies and
/// there is no value to forward — measured 2026-09-22 on this host as
/// `55 48 89 e5 e8 <rel32 abort> 0f 0b`, 44 `core` roots. The row shape alone
/// cannot tell that from a call whose argument set was dropped, which is why
/// the source is required: without it (or with a source whose call carries
/// arguments or results) the shape stays refused, because a forwarded
/// argument set is a value fact this pipeline emits reconstructed `MOV`
/// copies for.
///
/// This predicate is THE EXEMPTION DECISION, and it is the only one: a body it
/// admits promotes on the object lanes, a body it refuses keeps the
/// non-vacuous rule. It is deliberately left exactly as it is, because
/// narrowing OR widening it would change which functions promote. The
/// verifying JIT publishes NONE of the bodies it admits: their certificates
/// are all structural (the named exemption and `covered_elsewhere` rows), and
/// the JIT's per-function verdict
/// ([`x86_certificates_show_verified_semantics`]) requires a discharged
/// obligation.
///
/// It is ANONYMOUS: on its own it issues no certificate, so a publication cannot
/// be audited for which functions took the exemption. A body it admits is
/// therefore also offered to [`x86_64_call_only_body_certificate`], which issues
/// a NAMED `call_only_body` certificate when its own independent conjunction —
/// the verifier's per-row dispositions AND the LIR source — confirms the same
/// fact. That certificate is an audit name and nothing else: it is excluded from
/// the verifying JIT's per-function verdict
/// ([`x86_certificates_show_verified_semantics`]) and from every non-empty
/// evidence gate, and it is never consulted before this predicate, so it cannot
/// admit a body this predicate refuses.
///
/// NEITHER RULE CONTAINS THE OTHER, which is why the order is load-bearing:
/// - it admits `[Push, MovRR, Pop, Ret]` and `[Push, MovRR, Ud2]` by opcode
///   shape with NO source and NO row disposition, so a `MovRR` that copied a
///   value, a trap with some other skip reason, and a row the verifier FAILED
///   are admitted with them (a failed row still fails the function closed
///   through its own certificate); the named certificate refuses all of them;
/// - the named certificate admits `Jump* ; Trap` — the O0 two-block `-> !`
///   body whose rows are `[Jmp, Ud2]` — against its source, which this
///   predicate's opcode allowlist does not enumerate. That class is therefore
///   still REFUSED (`non_vacuous_function_evidence`), exactly as it was before
///   the named certificate existed, and it is refused without an audit name
///   because a refused function promotes nothing to audit.
///
/// The divergence is asserted in both directions, and the refusal in the
/// named-only direction measured at the module boundary, by
/// `x86_call_only_body_is_certified_on_verifier_dispositions_and_lir_source` and
/// `x86_trap_only_body_certifies_and_argument_shims_are_judged_by_their_body_theorem`.
#[cfg(feature = "verify")]
fn x86_64_report_is_empty_body(
    report: &trust_cg_verify::function_verifier::FunctionVerificationReport,
    lir_source: Option<&trust_cg_lower::Function>,
) -> bool {
    use trust_cg_ir::x86_64_ops::X86Opcode as O;
    use trust_cg_verify::function_verifier::InstructionOpcode;
    if report.precondition_failure.is_some() {
        return false;
    }
    let mut opcodes = Vec::with_capacity(report.instructions.len());
    for row in &report.instructions {
        match row.opcode {
            InstructionOpcode::X86_64(opcode) => opcodes.push(opcode),
            _ => return false,
        }
    }
    match opcodes.as_slice() {
        [O::Ret] | [O::Push, O::MovRR, O::Pop, O::Ret] | [O::Ud2] | [O::Push, O::MovRR, O::Ud2] => {
            true
        }
        _ if x86_64_opcodes_are_jumps_call_then_trap(&opcodes) => {
            lir_source.is_some_and(lir_is_zero_arg_direct_call_then_trap)
        }
        _ => false,
    }
}

/// Category (and rule name) of the structural certificate for an x86-64 body
/// whose every verifier row is a trap skip or a by-design unverified control
/// transfer AND whose LIR source is a bare diverging transfer: a documented
/// exemption from the non-vacuous rule (LIMITATIONS.md, x86-64), issued under
/// its own name so the returned certificate bundle states which functions
/// promoted on it. Shared with the CLI's lowering-sidecar builder, which skips
/// it by this name.
#[cfg(feature = "verify")]
use crate::proof_evidence::CALL_ONLY_BODY_CATEGORY;

/// x86-64 control transfers the verifier leaves `Unverified` by design: their
/// only per-instruction theorem would be the `target == target` tautology, so
/// the CFG edge and the call/branch relocation carry the evidence instead
/// (the `covered_elsewhere` family, `is_covered_elsewhere_indirect_branch`).
/// `MovRI` is in that family too but WRITES A REGISTER, so it is a value row
/// and is deliberately absent here.
#[cfg(feature = "verify")]
fn x86_64_is_control_transfer_without_value_proof(
    opcode: trust_cg_ir::x86_64_ops::X86Opcode,
) -> bool {
    use trust_cg_ir::x86_64_ops::X86Opcode as O;
    matches!(
        opcode,
        O::Call | O::CallR | O::CallM | O::Jmp | O::JmpR | O::Ret
    )
}

/// The report's `(control transfer, trap)` rows when EVERY row is one of them
/// under the verifier's OWN by-design disposition, else `None`.
///
/// Split out of [`x86_64_call_only_body_certificate`] so a vacuity refusal can
/// say which half of the gate was missing (the rows or the source) without
/// re-deriving it.
///
/// The predicate keys on the DISPOSITION, not on an opcode list: a report row
/// carries no operands, so opcodes alone could not tell a register-base `LEA`
/// (reconstruction-verified) from a symbol one. Every row must be exactly one
/// of
/// - `Skipped` with the verifier's own x86-64 trap reason (`UD2`), or
/// - `Unverified` with the verifier's own no-proof-mapping reason for a
///   control-transfer opcode (`CALL`/`CALLR`/`CALLM`/`JMP`/`JMPR`/`RET`).
///
/// Any `Verified` row (genuine or degenerate), any `Failed` row, any other
/// reason, any other opcode and any precondition failure return `None`.
/// `MovRI` (a register write whose covered-elsewhere credit covers its
/// encoding only), loads and stores (including symbol/RIP-addressed ones) and
/// ALU rows are value rows; the frame `push rbp; mov rbp, rsp` is inserted
/// after instruction selection and is not a report row.
#[cfg(feature = "verify")]
fn x86_64_report_transfer_and_trap_rows(
    report: &trust_cg_verify::function_verifier::FunctionVerificationReport,
) -> Option<(
    Vec<trust_cg_ir::x86_64_ops::X86Opcode>,
    Vec<trust_cg_ir::x86_64_ops::X86Opcode>,
)> {
    use trust_cg_verify::X86FunctionVerifier;
    use trust_cg_verify::function_verifier::{InstructionOpcode, InstructionVerificationResult};

    if report.precondition_failure.is_some() || report.instructions.is_empty() {
        return None;
    }
    let mut transfers = Vec::new();
    let mut traps = Vec::new();
    for row in &report.instructions {
        let InstructionOpcode::X86_64(opcode) = row.opcode else {
            return None;
        };
        match &row.result {
            InstructionVerificationResult::Skipped { reason }
                if X86FunctionVerifier::trap_skip_reason(opcode) == Some(reason.as_str()) =>
            {
                traps.push(opcode);
            }
            InstructionVerificationResult::Unverified { reason }
                if x86_64_is_control_transfer_without_value_proof(opcode)
                    && *reason == X86FunctionVerifier::no_proof_mapping_reason(opcode) =>
            {
                transfers.push(opcode);
            }
            _ => return None,
        }
    }
    Some((transfers, traps))
}

/// The call-then-trap body's row shape: an optional frame envelope
/// (`push rbp; mov rbp, rsp`), any number of unconditional jumps (an O0
/// entry block that only jumps to the panic block keeps its `JMP`), then
/// exactly `CALL`, `UD2`.
#[cfg(feature = "verify")]
fn x86_64_opcodes_are_jumps_call_then_trap(opcodes: &[trust_cg_ir::x86_64_ops::X86Opcode]) -> bool {
    use trust_cg_ir::x86_64_ops::X86Opcode as O;
    let body = match opcodes {
        [O::Push, O::MovRR, rest @ ..] => rest,
        rest => rest,
    };
    match body {
        [jumps @ .., O::Call, O::Ud2] => jumps.iter().all(|op| *op == O::Jmp),
        _ => false,
    }
}

/// Whether the report's rows are exactly the call-then-trap body (with or
/// without the frame envelope) that [`x86_64_report_is_empty_body`] admits
/// only against its source.
#[cfg(feature = "verify")]
fn x86_64_report_is_call_then_trap(
    report: &trust_cg_verify::function_verifier::FunctionVerificationReport,
) -> bool {
    use trust_cg_ir::x86_64_ops::X86Opcode as O;
    use trust_cg_verify::function_verifier::InstructionOpcode;
    let opcodes: Vec<O> = report
        .instructions
        .iter()
        .filter_map(|row| match row.opcode {
            InstructionOpcode::X86_64(opcode) => Some(opcode),
            _ => None,
        })
        .collect();
    let _ = O::Call;
    opcodes.len() == report.instructions.len() && x86_64_opcodes_are_jumps_call_then_trap(&opcodes)
}

/// The opcodes of a LIR function in LAYOUT order, with a `;` at each block
/// boundary (`Jump ; Call, Trap`), for a certificate's audit string and for a
/// refusal message.
///
/// It names every block, because the shapes this certificate is ABOUT are
/// multi-block: the measured `-> !` panic entries at O0 are an entry block that
/// only jumps plus the panic block, so a summary that reported the opcodes of a
/// single-block body and the BLOCK COUNT of any other
/// (`format!("{n} blocks")`) printed "2 blocks" for exactly the population the
/// audit exists to name. A block in the layout with no body is named
/// `<missing block>` in place rather than collapsing the whole summary.
#[cfg(feature = "verify")]
fn lir_layout_order_opcode_summary(func: &trust_cg_lower::Function) -> String {
    func.layout_order()
        .iter()
        .map(|block| match func.blocks.get(block) {
            Some(body) => body
                .instructions
                .iter()
                .map(|inst| {
                    let name = format!("{:?}", inst.opcode);
                    name.split(|c: char| !c.is_alphanumeric())
                        .next()
                        .unwrap_or("?")
                        .to_string()
                })
                .collect::<Vec<_>>()
                .join(", "),
            None => "<missing block>".to_string(),
        })
        .collect::<Vec<_>>()
        .join(" ; ")
}

/// Every instruction of a LIR function, flattened in LAYOUT order, or `None`
/// when a block in the layout has no body.
#[cfg(feature = "verify")]
fn lir_instructions_in_layout_order(
    func: &trust_cg_lower::Function,
) -> Option<Vec<&trust_cg_lower::instructions::Instruction>> {
    let mut flat = Vec::new();
    for block in func.layout_order() {
        let body = func.blocks.get(&block)?;
        flat.extend(body.instructions.iter());
    }
    Some(flat)
}

/// The LIR shape behind the admitted call-then-trap body: in layout order,
/// every instruction is an unconditional `Jump` except the last two, which
/// are a direct `Call` with no arguments and no results, then `Trap` (the O0
/// bridge keeps an entry block that only jumps to the panic block). Formals
/// are block parameters, not instructions, so a `#[track_caller]` location
/// the body never uses does not appear here.
#[cfg(feature = "verify")]
fn lir_is_zero_arg_direct_call_then_trap(func: &trust_cg_lower::Function) -> bool {
    use trust_cg_lower::instructions::Opcode;
    let Some(flat) = lir_instructions_in_layout_order(func) else {
        return false;
    };
    match flat.as_slice() {
        [jumps @ .., call, trap] => {
            jumps
                .iter()
                .all(|inst| matches!(inst.opcode, Opcode::Jump { .. }))
                && matches!(call.opcode, Opcode::Call { .. })
                && call.args.is_empty()
                && call.results.is_empty()
                && matches!(trap.opcode, Opcode::Trap)
        }
        _ => false,
    }
}

/// The TRAP-ONLY source shape: in layout order, unconditional `Jump`s and then
/// the `Trap`, with no call at all.
///
/// Measured through this pipeline on 2026-09-21 (`process::abort_immediate`, a
/// `match x {}` on an uninhabited type): the emitted rows are the single
/// `[Ud2]`, and at O0 the two-block spelling keeps its `[Jmp, Ud2]`.
/// [`x86_64_report_is_empty_body`] exempts the one-row spelling by opcode
/// alone; the named certificate requires the source for it too, so the
/// exemption it issues is bound to a body that provably has nothing to
/// discharge.
#[cfg(feature = "verify")]
fn lir_is_jumps_then_trap(func: &trust_cg_lower::Function) -> bool {
    use trust_cg_lower::instructions::Opcode;
    let Some(flat) = lir_instructions_in_layout_order(func) else {
        return false;
    };
    match flat.as_slice() {
        [jumps @ .., trap] => {
            jumps
                .iter()
                .all(|inst| matches!(inst.opcode, Opcode::Jump { .. }))
                && matches!(trap.opcode, Opcode::Trap)
        }
        _ => false,
    }
}

/// The LIR sources the named `call_only_body` certificate admits: a bare
/// DIVERGING transfer, either `Jump* ; Trap` or
/// `Jump* ; Call (direct, no arguments, no results) ; Trap`.
///
/// Everything else is refused, including a body that ends in `Return` rather
/// than `Trap`: `call f; ret` is a forwarding shim, not a diverging one, and
/// it discharges nothing.
///
/// Block ARGUMENTS on the jumps are not inspected here, and do not need to be:
/// a jump that carries them lowers to phi-resolution `MOV` copies, which are
/// value rows, so the row half of the gate
/// ([`x86_64_report_transfer_and_trap_rows`]) refuses the body. That is one of
/// the places the conjunction earns its keep.
#[cfg(feature = "verify")]
fn lir_is_transfer_only_diverging_body(func: &trust_cg_lower::Function) -> bool {
    lir_is_zero_arg_direct_call_then_trap(func) || lir_is_jumps_then_trap(func)
}

/// Whether an x86-64 certificate set shows VERIFIED SEMANTICS for its function
/// — the verifying JIT's PER-FUNCTION verdict.
///
/// Only DISCHARGE EVIDENCE counts
/// ([`proof_evidence::certificate_is_discharge_evidence`]). Two structural
/// categories are `verified: true` but discharge nothing, and both are excluded
/// from both halves of this verdict — neither can make the set non-empty and
/// neither is what "all verified" quantifies over:
/// - [`CALL_ONLY_BODY_CATEGORY`] names an EXEMPTION: the body has no
///   value-semantics row to discharge;
/// - [`proof_evidence::COVERED_ELSEWHERE_CATEGORY`] is a CALL/JMP/RET/`MOV r,imm`
///   row whose correctness rests on the CFG, the relocation or the encoding.
///
/// So the verifying JIT refuses every exempt body: a trap-only body
/// (`[call_only_body]`), a `call f; ud2` body (`[call_only_body,
/// covered_elsewhere]`) and an empty `ret` body (`[covered_elsewhere]`). Until
/// 2026-09-28, certification of the second and third returned Ok with
/// per-function `verified = true` under `CachedVerified` and `AlwaysVerify` on
/// their `covered_elsewhere` certificates alone.
/// `x86_verifying_jit_still_refuses_a_call_only_body` measures all three at the
/// certification boundary through the real verifier — on arm64, through the
/// uncached path only, executing no x86-64 code; that an Ok there publishes is
/// known by reading the code.
///
/// A body with real discharged rows is decided by those rows, with or without
/// structural certificates beside them.
///
/// THE ABI ENVELOPE. In a verifying mode the JIT also judges an empty void
/// body and a zero-argument `call f; ud2` panic entry by the x86-64 System V
/// envelope theorem over their final bytes and fixup manifest
/// ([`x86_64_abi_envelope_certificates`],
/// [`proof_evidence::X86_ABI_ENVELOPE_CATEGORY`]). Those certificates ARE
/// discharge evidence, so they decide those two shapes: `verified` only when
/// every part of the theorem has a Valid replay (an AY proof Clean accepted,
/// each), otherwise a named refusal (`X86_ENVELOPE_NEEDS_REPLAY`, a
/// refutation, or a mismatch). The trap-only
/// shapes (`[Ud2]`, `[Jmp, Ud2]`) get no envelope and stay refused.
#[cfg(feature = "verify")]
fn x86_certificates_show_verified_semantics(certs: &[ProofCertificate]) -> bool {
    let mut semantic = certs
        .iter()
        .filter(|cert| crate::proof_evidence::certificate_is_discharge_evidence(cert))
        .peekable();
    semantic.peek().is_some() && semantic.all(|cert| cert.verified)
}

/// The x86-64 System V ABI envelope verdict of one JIT function's FINAL
/// pre-relocation bytes and symbolic fixup manifest
/// (`trust_cg_verify::x86_source_bound_envelope`), or `None` when its LIR
/// source is not an empty void body or a zero-argument `call f; ud2` panic
/// entry under a System V convention (the owner then makes no claim).
#[cfg(feature = "verify")]
fn x86_jit_envelope_report(
    lir: &trust_cg_lower::Function,
    function_name: &str,
    code: &[u8],
    manifest: &[u8],
    abi: Option<trust_cg_verify::X86SourceBoundAbi>,
    request: &trust_cg_verify::FunctionVerificationRequest,
) -> Option<trust_cg_verify::x86_source_bound_envelope::X86EnvelopeReport> {
    trust_cg_verify::x86_source_bound_envelope::source_admits_x86_envelope_owner(lir, abi).then(
        || {
            shared_x86_64_function_verifier().verify_abi_envelope(
                lir,
                function_name,
                code,
                manifest,
                abi,
                request,
            )
        },
    )
}

/// What the certificate cache asks of an envelope report. Production passes
/// only [`X86EnvelopeReport`](trust_cg_verify::x86_source_bound_envelope::X86EnvelopeReport),
/// which codegen cannot construct; the cache predicates are generic over this
/// view so their tests can also drive them with the report states a live
/// replay reaches but a test host cannot produce on demand (a Valid replay
/// that is not bound to the request's authority, or bound to another one).
#[cfg(feature = "verify")]
trait X86EnvelopeReuse {
    fn is_valid(&self) -> bool;
    fn reusable_for(&self, request: &trust_cg_verify::FunctionVerificationRequest) -> bool;
    fn matches_input(
        &self,
        lir: &trust_cg_lower::Function,
        function_name: &str,
        code: &[u8],
        manifest: &[u8],
        abi: Option<trust_cg_verify::X86SourceBoundAbi>,
    ) -> bool;
}

#[cfg(feature = "verify")]
impl X86EnvelopeReuse for trust_cg_verify::x86_source_bound_envelope::X86EnvelopeReport {
    fn is_valid(&self) -> bool {
        self.is_valid()
    }
    fn reusable_for(&self, request: &trust_cg_verify::FunctionVerificationRequest) -> bool {
        self.reusable_for(request)
    }
    fn matches_input(
        &self,
        lir: &trust_cg_lower::Function,
        function_name: &str,
        code: &[u8],
        manifest: &[u8],
        abi: Option<trust_cg_verify::X86SourceBoundAbi>,
    ) -> bool {
        self.matches_input(lir, function_name, code, manifest, abi)
    }
}

/// Whether a verdict carrying `envelope` may be stored in the certificate
/// cache: no envelope, or one whose Valid replay was bound to this request's
/// reusable authority. A Valid but unbound replay (and every non-Valid one)
/// carries no reusable identity and is never stored.
#[cfg(feature = "verify")]
fn x86_jit_envelope_is_storable<R: X86EnvelopeReuse>(
    envelope: Option<&R>,
    request: &trust_cg_verify::FunctionVerificationRequest,
) -> bool {
    envelope.is_none_or(|envelope| envelope.is_valid() && envelope.reusable_for(request))
}

/// Whether a cached entry's envelope admits a warm hit for this function: the
/// envelope's own replay authority and exact input are re-checked (not
/// inferred from the cache key), and an entry WITHOUT an envelope serves only
/// a function whose source the envelope owner does not admit.
#[cfg(feature = "verify")]
fn x86_jit_cached_envelope_admits<R: X86EnvelopeReuse>(
    envelope: Option<&R>,
    request: &trust_cg_verify::FunctionVerificationRequest,
    lir: &trust_cg_lower::Function,
    function_name: &str,
    code: &[u8],
    manifest: &[u8],
    abi: Option<trust_cg_verify::X86SourceBoundAbi>,
) -> bool {
    match envelope {
        Some(envelope) => {
            envelope.is_valid()
                && envelope.reusable_for(request)
                && envelope.matches_input(lir, function_name, code, manifest, abi)
        }
        None => {
            !trust_cg_verify::x86_source_bound_envelope::source_admits_x86_envelope_owner(lir, abi)
        }
    }
}

/// The certificates an envelope report contributes, in
/// [`proof_evidence::X86_ABI_ENVELOPE_CATEGORY`] (discharge evidence):
/// - when EVERY part of the theorem has a Valid replay, one certificate per
///   part, each `verified: true`, strength `Formal`, carrying that part's
///   replayed theorem as its `source_bound_obligation`;
/// - a refuted part, a part with no independently checked proof
///   ([`X86_ENVELOPE_NEEDS_REPLAY`](trust_cg_verify::x86_source_bound_envelope::X86_ENVELOPE_NEEDS_REPLAY),
///   naming the first such part, how many parts were Valid and, when known,
///   why that part has no Valid replay), and a named
///   mismatch each give one `verified: false` certificate, so the function is
///   refused by name;
/// - an unsupported input contributes nothing, and the function keeps
///   whatever refusal its other certificates give it.
#[cfg(feature = "verify")]
fn x86_64_abi_envelope_certificates(
    report: &trust_cg_verify::x86_source_bound_envelope::X86EnvelopeReport,
) -> Vec<ProofCertificate> {
    x86_64_abi_envelope_outcome_certificates(report.function_name(), report.outcome())
}

/// [`x86_64_abi_envelope_certificates`] of one function's envelope outcome.
/// Credit is exactly [`X86EnvelopeOutcome::is_credited`](trust_cg_verify::x86_source_bound_envelope::X86EnvelopeOutcome::is_credited).
#[cfg(feature = "verify")]
fn x86_64_abi_envelope_outcome_certificates(
    function_name: &str,
    outcome: &trust_cg_verify::x86_source_bound_envelope::X86EnvelopeOutcome,
) -> Vec<ProofCertificate> {
    use trust_cg_verify::VerificationResult;
    use trust_cg_verify::x86_source_bound_envelope::{
        X86_ENVELOPE_NEEDS_REPLAY, X86EnvelopeOutcome,
    };
    let certificate = |rule_name: &str, verified, strength: String, export| ProofCertificate {
        ay_refusal_note: None,
        source_bound_obligation: export,
        rule_name: rule_name.to_owned(),
        verified,
        category: crate::proof_evidence::X86_ABI_ENVELOPE_CATEGORY.to_owned(),
        strength,
        function_name: function_name.to_owned(),
    };
    match outcome {
        X86EnvelopeOutcome::Unsupported(_) => Vec::new(),
        X86EnvelopeOutcome::Mismatch(mismatch) => vec![certificate(
            crate::proof_evidence::X86_ABI_ENVELOPE_CATEGORY,
            false,
            format!("Failed: x86-64 ABI envelope mismatch: {mismatch}"),
            None,
        )],
        X86EnvelopeOutcome::Built {
            theorem_name,
            parts,
            exports,
        } => {
            if outcome.is_credited() {
                return exports
                    .iter()
                    .map(|export| {
                        certificate(
                            &export.obligation().name,
                            true,
                            format!("{:?}", trust_cg_verify::VerificationStrength::Formal),
                            Some(export.clone()),
                        )
                    })
                    .collect();
            }
            if let Some((part, counterexample)) =
                parts.iter().find_map(|part| match &part.verdict {
                    Some(VerificationResult::Invalid { counterexample }) => {
                        Some((part, counterexample))
                    }
                    _ => None,
                })
            {
                return vec![certificate(
                    theorem_name,
                    false,
                    format!(
                        "Failed: the x86-64 ABI envelope theorem is refuted at `{}`: {counterexample}",
                        part.name
                    ),
                    None,
                )];
            }
            let detail = match outcome.first_unproven_part() {
                Some((part, valid)) => format!(
                    " (first part without a Valid replay: `{}`; {valid} of {} parts Valid{})",
                    part.name,
                    parts.len(),
                    part.detail
                        .as_deref()
                        .map(|why| format!("; {why}"))
                        .unwrap_or_default()
                ),
                None => String::new(),
            };
            vec![certificate(
                theorem_name,
                false,
                format!("{X86_ENVELOPE_NEEDS_REPLAY}{detail}"),
                None,
            )]
        }
    }
}

/// The NAMED certificate for a CALL-ONLY x86-64 body, or `None` when any row
/// has value semantics or the LIR source is not a bare diverging transfer.
///
/// Measured on 2026-09-21 (`core` at O0, `-Cpanic=abort`, Linux): the 46
/// `[TCG-PROOF-465]` roots left after the empty-body exemption were cold
/// diverging panic helpers whose whole body is `call abort; ud2`, optionally
/// behind a block-layout `jmp`. The same class was re-measured on 2026-09-22
/// on a Darwin host with the bridge loaded: the remaining roots disassemble to
/// the same shape and carry the same SOURCE fact — the message and the
/// `#[track_caller]` location are already gone at the source level, so the
/// body is a zero-argument direct call and a trap.
///
/// TWO INDEPENDENT FACTS are required and both are checked here.
///
/// 1. THE VERIFIER'S OWN PER-ROW DISPOSITION for every row
///    ([`x86_64_report_transfer_and_trap_rows`]): each row is either the
///    verifier's trap skip or its no-proof-mapping refusal for a
///    control-transfer opcode, and AT LEAST ONE of them is the trap skip. Any
///    `Verified` row (genuine or degenerate), any `Failed` row, any other
///    reason, any value opcode and any precondition failure keep the
///    non-vacuous rule.
///
/// 2. THE LIR SOURCE handed to instruction selection
///    ([`lir_is_transfer_only_diverging_body`]): flattened in layout order it
///    is `Jump* ; Trap` or `Jump* ; Call (direct, no args, no results) ; Trap`.
///    A report with NO source is refused outright, so the opcode-only
///    diagnostic fixtures cannot certify.
///
/// NEITHER HALF IS REDUNDANT, which is why this is a conjunction rather than a
/// choice between the two mechanisms:
/// - fact 2 alone admits a body whose rows the verifier FAILED, or verified
///   degenerately, or refused for some reason other than the by-design one —
///   the row dispositions are what say the rows carry no value theorem;
/// - fact 1 alone admits `call f; ret` (a forwarding shim with no trap at
///   all), `call f; call g; ud2`, and a call whose arguments happened to need
///   no reconstructed `MOV` — all of them with zero discharged instruction
///   theorems. The source is what says there was nothing to forward.
///
/// WHAT THE CERTIFICATE CLAIMS: the function transfers control and traps and
/// does nothing else. The frame envelope is checked by frame lowering's own
/// validators, the call/branch edges by the CFG model and the relocation
/// inventory, the trap by its fixed encoding. It claims NO discharged value
/// theorem, and it is emitted `verified: true` only under this conjunction.
///
/// WHAT IT DOES NOT BUY. It is an AUDIT NAME, and it is excluded from every
/// gate that asks "is there any evidence at all"
/// ([`proof_evidence::certificate_is_discharge_evidence`]):
/// - [`x86_certificates_show_verified_semantics`], the verifying JIT's
///   PER-FUNCTION verdict, ignores it — and ignores the `covered_elsewhere`
///   certificate a `call f; ud2` body's CALL row also carries — so a trap-only
///   or `call f; ud2` body produces NO semantic evidence and the JIT refuses to
///   publish it (until 2026-09-28 the CALL row's `covered_elsewhere`
///   certificate counted, and certification of `call f; ud2` returned Ok with
///   per-function `verified = true` — measured on arm64 through the uncached
///   path only; publication follows by reading the code);
/// - [`Compiler::gate_jit_proofs_promotable`] and the bridge's independent
///   bundle re-check ([`proof_evidence::bundle_has_discharge_evidence`]) ignore
///   it and `covered_elsewhere`, so a bundle of nothing but structural
///   certificates cannot satisfy their non-empty evidence requirement. (On the
///   AOT object lane a CGU of only diverging bodies still carries the object
///   relocation inventory certificate, which is what admitted it before this
///   category existed and still does; the exemption neither adds to nor
///   subtracts from that.)
///
/// It also does not decide WHICH bodies are exempt. Its caller
/// ([`proof_certificates_from_x86_64_report`]) asks
/// [`x86_64_report_is_empty_body`] that question first and consults this
/// conjunction only for the bodies that rule already exempts, so the AOT
/// promotion set is exactly what it was before the category existed. That
/// ordering matters because NEITHER RULE CONTAINS THE OTHER: this conjunction
/// admits `Jump* ; Trap` (rows `[Jmp, Ud2]`, the O0 two-block `-> !` body),
/// which the opcode allowlist does not enumerate, and consulting it first would
/// have replaced that class's `non_vacuous_function_evidence` refusal with a
/// `verified: true` certificate and promoted it. Naming an exemption is an
/// auditing change; widening what may be published is refused (OD-40 in
/// docs/decision-record.md), and this certificate does not do it. Both directions of the divergence, and
/// the refusal that survives in the named-only direction, are asserted by
/// `x86_call_only_body_is_certified_on_verifier_dispositions_and_lir_source` and
/// by `x86_trap_only_body_certifies_and_argument_shims_are_judged_by_their_body_theorem`.
///
/// The NAME is what the audit needs: the CLI's lowering sidecars skip it by name
/// (no `ProofDatabase` obligation) and its per-rule `.cert` audit file records
/// it as `eval-only`. The certificate carries the FUNCTION's name, so the
/// certificate bundle a compile returns — the artifact the AOT promotion gate
/// and the bridge's own re-check read, and the one `proof_bundle_sha256` covers
/// — names every function that promoted on this exemption. (The per-rule `.cert`
/// is one file per rule, so it records that the exemption was taken and names
/// the first function that took it, not all of them.)
/// [`x86_64_report_is_empty_body`], the anonymous opcode-shape escape, issues no
/// certificate at all and so leaves no audit trail of any granularity.
#[cfg(feature = "verify")]
fn x86_64_call_only_body_certificate(
    report: &trust_cg_verify::function_verifier::FunctionVerificationReport,
    lir_source: Option<&trust_cg_lower::Function>,
) -> Option<ProofCertificate> {
    let (transfers, traps) = x86_64_report_transfer_and_trap_rows(report)?;
    // The claim includes the TRAP, so the rows must show it. Both admitted
    // sources end in `Trap`, so a transfer-only row set with no trap at all
    // (`call f; ret`, a bare `jmp`, an empty body's `[Ret]`) is a shim however
    // its source reads. This is also what keeps the two halves from
    // contradicting each other when a caller hands over a (report, source) pair
    // the pipeline could not have produced: without it, a `[Ret]` report paired
    // with a diverging source would be certified as "0 trap(s) []" while the
    // certificate's text claims the function traps.
    if traps.is_empty() {
        return None;
    }
    let source = lir_source?;
    if !lir_is_transfer_only_diverging_body(source) {
        return None;
    }
    Some(ProofCertificate {
        ay_refusal_note: None,
        source_bound_obligation: None,
        rule_name: CALL_ONLY_BODY_CATEGORY.to_owned(),
        verified: true,
        category: CALL_ONLY_BODY_CATEGORY.to_owned(),
        strength: format!(
            "no value-semantics row: {} control transfer(s) {:?} left unverified by design \
             (CFG edge and relocation covered elsewhere) and {} trap(s) {:?} skipped; the LIR \
             source is a bare diverging transfer ([{}]); no instruction theorem was discharged",
            transfers.len(),
            transfers,
            traps.len(),
            traps,
            lir_layout_order_opcode_summary(source)
        ),
        function_name: report.function_name.clone(),
    })
}

/// Convert a checked x86 report without rerunning instruction verification.
/// Kept separate so opcode-only diagnostic fixtures exercise this conversion
/// without pretending that source-less reports passed authoritative Enforce.
#[cfg(feature = "verify")]
fn proof_certificates_from_x86_64_report(
    report: &trust_cg_verify::FunctionVerificationReport,
    lir_source: Option<&trust_cg_lower::Function>,
    enc3: crate::decode_check::DecodeCheckBacking,
) -> Vec<ProofCertificate> {
    proof_certificates_from_x86_64_report_with_obligations(report, lir_source, &[], enc3)
}

/// [`proof_certificates_from_x86_64_report`], attaching each retained x86-64
/// whole-body theorem to the Formal row it credits: same function, same walk
/// row, same theorem name, `X86Body` kind, non-degenerate. A row without a
/// matching payload carries none.
#[cfg(feature = "verify")]
fn proof_certificates_from_x86_64_report_with_obligations(
    report: &trust_cg_verify::FunctionVerificationReport,
    lir_source: Option<&trust_cg_lower::Function>,
    obligations: &[trust_cg_verify::SourceBoundArithmeticObligation],
    enc3: crate::decode_check::DecodeCheckBacking,
) -> Vec<ProofCertificate> {
    use trust_cg_verify::function_verifier::InstructionVerificationResult;

    let mut certs = Vec::new();

    // Sampled rows need no separate trace here: since E0.2 a reconstruction
    // discharged only by sampling is an `Unverified` row whose reason names the
    // exact obligation and its sample count, and the opcode-inventory
    // certificate below carries that reason into the refusal.
    trace_opcode_inventory(report);
    append_emitted_opcode_inventory_certificate(&mut certs, report);
    if report.genuinely_verified_count() == 0 {
        // WHICH BODIES ARE EXEMPT is decided by [`x86_64_report_is_empty_body`]
        // and by nothing else, exactly as it was before the `call_only_body`
        // category existed. The named certificate is an AUDIT NAME for an
        // exemption that rule already granted — never a second admission rule —
        // so no function promotes here that did not promote before.
        //
        // That ordering is load-bearing, because NEITHER RULE CONTAINS THE
        // OTHER. The conjunction admits `Jump* ; Trap` (the O0 two-block `-> !`
        // body, rows `[Jmp, Ud2]`), which the opcode allowlist does not
        // enumerate; consulting it first would have made that class promote
        // where the vacuity refusal previously blocked it, which is a widening
        // of the publication boundary, refused by OD-40 (docs/decision-record.md),
        // not an auditing change. The allowlist in turn admits shapes the conjunction
        // refuses (a frame-enveloped `MovRR` that may have copied a value, a
        // trap with some other skip reason, a row the verifier failed); those
        // keep promoting anonymously, as they did, and LIMITATIONS.md records
        // that the audit trail does not reach them.
        if x86_64_report_is_empty_body(report, lir_source) {
            // AUDITABLE: the conjunction independently confirms the exemption —
            // every row carries the verifier's own by-design disposition AND the
            // LIR source is a bare diverging transfer — so the exemption this
            // body took is issued BY NAME and a publication can be audited for
            // exactly which functions took it.
            if let Some(cert) = x86_64_call_only_body_certificate(report, lir_source) {
                certs.push(cert);
            }
        } else {
            // A refused transfer-only body names BOTH halves of the gate,
            // so a census can tell "the source carries values the emitted
            // rows do not" from "no source was supplied" without a
            // debugger.
            let transfer_only_rows = x86_64_report_is_call_then_trap(report)
                || x86_64_report_transfer_and_trap_rows(report).is_some();
            let source_note = match lir_source {
                Some(func) if transfer_only_rows => format!(
                    "; every emitted row is a by-design control transfer or trap but its \
                     source is not a bare diverging transfer: [{}]",
                    lir_layout_order_opcode_summary(func)
                ),
                None if transfer_only_rows => {
                    "; every emitted row is a by-design control transfer or trap and no \
                     source was supplied to bind it"
                        .to_string()
                }
                _ => String::new(),
            };
            // The rows themselves, so a census refusal is diagnosable from
            // its text alone (a report row is an opcode; operands are not
            // recorded).
            let rows = report
                .instructions
                .iter()
                .map(|row| format!("{:?}", row.opcode))
                .collect::<Vec<_>>()
                .join(", ");
            certs.push(non_verified_proof_report(
                &report.function_name,
                0,
                "non_vacuous_function_evidence",
                format!(
                    "the function has no genuinely discharged instruction proof; \
                     covered-elsewhere or skipped rows alone cannot establish proof-grade \
                     function semantics{source_note}; rows: [{rows}]"
                ),
            ));
        }
    }

    for inst_report in &report.instructions {
        match &inst_report.result {
            InstructionVerificationResult::Verified {
                proof_name,
                category,
                strength,
                degenerate,
            } => {
                if *degenerate {
                    // STRICT: a structural X == X checks model consistency,
                    // not lowering correctness. The genuine-identity table is
                    // classification only; its names grant no publication credit.
                    certs.push(ProofCertificate {
                        ay_refusal_note: None,
                        #[cfg(feature = "verify")]
                        source_bound_obligation: None,
                        rule_name: proof_name.clone(),
                        verified: false,
                        category: format!("{}", category),
                        strength: format!(
                            "degenerate X==X proof proves nothing; not promotable on the compile path (mirrors coverage_gate discharge_one): {}",
                            proof_name
                        ),
                        function_name: report.function_name.clone(),
                    });
                } else {
                    certs.push(ProofCertificate {
                        ay_refusal_note: None,
                        #[cfg(feature = "verify")]
                        source_bound_obligation: obligations
                            .iter()
                            .find(|obligation| {
                                obligation.kind()
                                    == trust_cg_verify::SourceBoundObligationKind::X86Body
                                    && obligation.instruction_index() == inst_report.inst_index
                                    && obligation.function_name() == report.function_name
                                    && obligation.obligation().name == *proof_name
                                    && matches!(
                                        strength,
                                        trust_cg_verify::VerificationStrength::Formal
                                    )
                                    && !degenerate
                            })
                            .cloned(),
                        rule_name: proof_name.clone(),
                        verified: true,
                        category: format!("{}", category),
                        strength: format!("{:?}", strength),
                        function_name: report.function_name.clone(),
                    });
                }
            }
            InstructionVerificationResult::Failed { proof_name, detail } => {
                certs.push(ProofCertificate {
                    ay_refusal_note: None,
                    #[cfg(feature = "verify")]
                    source_bound_obligation: None,
                    rule_name: proof_name.clone(),
                    verified: false,
                    category: String::new(),
                    strength: format!("Failed: {}", detail),
                    function_name: report.function_name.clone(),
                });
            }
            InstructionVerificationResult::Unverified { reason } => {
                certs.push(unverified_instruction_certificate(
                    &report.function_name,
                    inst_report.inst_index,
                    inst_report.opcode,
                    reason,
                    enc3,
                ));
            }
            InstructionVerificationResult::Skipped { .. } => {}
        }
    }

    #[cfg(test)]
    record_lane_certificates(report, enc3, &certs);
    certs
}

/// Names of the module's function DEFINITIONS that another module may preempt
/// under `relocation_model`: bodied, non-ODR definitions that
/// [`RelocationModel::definition_is_preemptible`] names (default-visibility
/// and non-local, in shared-object code). ODR linkages promise every
/// definition is equivalent, so inlining one of them cannot change behavior.
///
/// A v45 hidden or protected definition cannot be preempted at load time, so
/// it is not in this set. A `Weak`/`LinkOnce` one may still be replaced at
/// static link; [`interposable_weak_definitions`] withholds it.
fn preemptible_function_names(
    module: &trust_ir::Module,
    relocation_model: RelocationModel,
) -> std::collections::HashSet<String> {
    module
        .functions
        .iter()
        .filter(|function| {
            !function.blocks.is_empty()
                && matches!(
                    function.linkage,
                    trust_ir::Linkage::External
                        | trust_ir::Linkage::Weak
                        | trust_ir::Linkage::LinkOnce
                )
                && relocation_model.definition_is_preemptible(
                    trust_cg_lower::DefinitionBinding::for_trust_ir_linkage(function.linkage),
                    function.visibility,
                )
        })
        .map(|function| function.name.clone())
        .collect()
}

#[cfg(feature = "verify")]
fn crosscheck_elf_relocation_inventory_digest(
    object_bytes: &[u8],
    inventory_kinds: &[trust_cg_verify::ObjectRelocationKind],
) -> Result<(), CompileError> {
    let digest = crate::elf::reparse::reloc_type_digest(object_bytes).map_err(|e| {
        CompileError::Pipeline(crate::pipeline::PipelineError::RelocationInventoryDigest(
            format!("emitted object failed relocation digest parse: {e}"),
        ))
    })?;
    let mut artifact: Vec<trust_cg_verify::ObjectRelocationKind> = digest
        .into_iter()
        .map(crate::pipeline::aarch64_elf_kind_from_r_type)
        .collect();
    artifact.sort_unstable();
    let mut inventory: Vec<trust_cg_verify::ObjectRelocationKind> = inventory_kinds.to_vec();
    inventory.sort_unstable();
    if artifact != inventory {
        return Err(CompileError::Pipeline(
            crate::pipeline::PipelineError::RelocationInventoryDigest(format!(
                "object carries {artifact:?} but the proof inventory names {inventory:?}; \
                 a relocation outside the mirrored inventory must never ship"
            )),
        ));
    }
    Ok(())
}

/// Whether the object `Compiler::compile` emits for `target` and the effective
/// `target_triple` binds every reference to a bodied Internal/Private function
/// to that object's own local definition: `STB_LOCAL` in an ELF object, a
/// non-external (`N_EXT` clear) `N_SECT` symbol in a Mach-O object.
///
/// This is the one predicate that exempts an object path from the
/// `AotDirectModuleFunctionBindingUnsupported` and
/// `AotStaticFunctionIdentityBindingUnsupported` refusals (the source
/// identity census, and the adapter's withheld static-call candidates), and
/// that selects the post-emission check
/// ([`check_aarch64_module_local_function_binding`]: the ELF or the Mach-O
/// reader). It holds exactly when `Compiler::compile` dispatches to the
/// AArch64 pipeline and that pipeline emits the triple's object as ELF
/// (`target_triple_uses_elf`) or as Apple Mach-O (`target_triple_uses_macho`),
/// the two formats its emitter dispatch accepts
/// (`reject_unsupported_aarch64_object_format`). Both emitters bind an
/// Internal/Private function locally
/// (`FunctionSymbolBinding::for_trust_ir_definition`; Mach-O clears `N_EXT`
/// in `add_module_symbols_for_fixups`), resolve every text fixup and data
/// slot through the one name-to-symbol map whose function entries are those
/// definitions, and add an undefined symbol only for a name the object does
/// not define; module validation makes every function and global name
/// unique. The adapter addresses a local definition PC-relatively
/// (`RelocationModel::definition_is_preemptible`; Mach-O implements only the
/// static model, under which a local definition is never preemptible).
///
/// It holds for the x86-64 ELF module emitter too (ruling
/// OD-X86-ELF-LOCAL-BINDING-20261027): it binds a definition
/// `X86FunctionSymbolFacts` names local `STB_LOCAL` in the symbol table's
/// local partition, and every `R_X86_64_PLT32` call and `R_X86_64_64` address
/// slot it writes names a symbol out of the same `symbol_map` whose function
/// entries are those definitions, with `check_x86_elf_symbol_indices`
/// re-reading every index the emitter's own partition arithmetic handed out.
/// The post-emission check ([`check_elf_module_local_function_binding`]) then
/// re-reads the binding of every such name, and every relocation that reaches
/// one, from the emitted bytes.
///
/// The x86-64 Mach-O emitter also satisfies this predicate: the post-emission
/// checker decodes x86-64 relocations and reads back the non-external definition,
/// source-owned text references and data atoms from the emitted bytes.
///
/// The remaining COFF and RISC-V object paths keep both reference refusals.
/// The x86-64 COFF emitter binds an unreferenced definition local
/// (`IMAGE_SYM_CLASS_STATIC`, from the same
/// `X86FunctionSymbolFacts`) and the RISC-V module object binds it
/// `STB_LOCAL` ([`module_local_function_definitions`]), each re-read from the
/// object by [`check_object_function_bindings`], but none of them is checked
/// to resolve every REFERENCE to such a definition to that local symbol, so a
/// module that makes one (a `SymbolAddr` naming one included) is refused
/// before lowering. The in-process JIT resolves module-local calls through
/// its own exact-binding path and does not read this predicate. The ELF-only
/// object facts (weak undefined references, function visibility and sections)
/// are a separate admission ([`aot_object_admits_elf_symbol_facts`]), which
/// x86-64 ELF does not hold: this predicate is about BINDING, which needs no
/// `STV_*` byte.
pub(crate) fn aot_object_binds_module_local_functions(target: Target, target_triple: &str) -> bool {
    match target {
        Target::Aarch64 => {
            crate::pipeline::target_triple_uses_elf(target_triple)
                || crate::pipeline::target_triple_uses_macho(target_triple)
        }
        Target::X86_64 => {
            crate::pipeline::target_triple_uses_elf(target_triple)
                || crate::pipeline::target_triple_uses_macho(target_triple)
        }
        Target::Riscv64 => false,
    }
}

/// Whether `Compiler::compile` selects the AArch64 ELF module emitters for
/// `target` and `target_triple`, the only object path that spells weak
/// undefined references, v45 function visibility and function sections
/// ([`trust_cg_lower::ObjectSymbolPolicy::AARCH64_ELF_MODULE`]). The Mach-O
/// path binds module-local functions too
/// ([`aot_object_binds_module_local_functions`]) and admits hidden `External`
/// function definitions alone
/// ([`aot_object_admits_macho_hidden_function_definitions`]); it keeps the
/// adapter's refusals of every other fact.
pub(crate) fn aot_object_admits_elf_symbol_facts(target: Target, target_triple: &str) -> bool {
    target == Target::Aarch64 && crate::pipeline::target_triple_uses_elf(target_triple)
}

/// Whether `Compiler::compile` selects a Mach-O module emitter for `target`
/// and `target_triple` — the AArch64 one, or the x86-64 one
/// (`X86Pipeline::emit_module_macho`) — which spells one v45
/// function-visibility fact: `Hidden` on an `External` definition, as a
/// private-extern (`N_EXT | N_PEXT`) symbol
/// ([`trust_cg_lower::ObjectSymbolPolicy::AARCH64_MACHO_MODULE`],
/// [`trust_cg_lower::ObjectSymbolPolicy::X86_64_MACHO_MODULE`]). The rustc
/// bridge emits a CGU-private function this way, so that the objects one
/// rustc CGU is split into can call it while another CGU's copy (rustc gives
/// an `#[inline]` item one `Internal` copy per CGU, all under one name) can
/// never collide with it. Weak undefined references, undefined-symbol
/// visibility and function sections stay refused there. The x86-64 object
/// format follows the target spec, not this triple test: if the two ever
/// disagree, the x86-64 ELF and COFF emitters refuse the hidden definition
/// (`X86PipelineError::FunctionVisibilityUnsupported`) rather than emit it
/// default-visible.
pub(crate) fn aot_object_admits_macho_hidden_function_definitions(
    target: Target,
    target_triple: &str,
) -> bool {
    matches!(target, Target::Aarch64 | Target::X86_64)
        && crate::pipeline::target_triple_uses_macho(target_triple)
        && !crate::pipeline::target_triple_uses_elf(target_triple)
}

/// The object-symbol facts the adapter admits for the object path
/// `Compiler::compile` selects for `target` and `target_triple`: everything
/// the AArch64 ELF module emitters spell
/// ([`aot_object_admits_elf_symbol_facts`]), hidden and protected visibility
/// on a function DEFINITION and on a codegen DECLARATION for the x86-64 ELF
/// module emitter
/// ([`trust_cg_lower::ObjectSymbolPolicy::X86_64_ELF_MODULE`], rulings
/// OD-X86-ELF-DEFINITION-VISIBILITY-20261027 and
/// OD-X86-ELF-UNDEFINED-REFERENCE-20261106 — it spells both `st_other` bytes
/// but no explicit section, so it takes
/// `FunctionSymbolFactPolicy::AdmitElfSymbolVisibility` and not the wider
/// `AdmitElfSymbolFacts`), a hidden `External` function
/// definition alone on the AArch64 and x86-64 Mach-O module emitters
/// ([`aot_object_admits_macho_hidden_function_definitions`]), and nothing on
/// every other path (x86-64 COFF, RISC-V).
pub(crate) fn aot_object_symbol_policy(
    target: Target,
    target_triple: &str,
) -> trust_cg_lower::ObjectSymbolPolicy {
    if aot_object_admits_elf_symbol_facts(target, target_triple) {
        return trust_cg_lower::ObjectSymbolPolicy::AARCH64_ELF_MODULE;
    }
    if target == Target::X86_64 && crate::pipeline::target_triple_uses_elf(target_triple) {
        return trust_cg_lower::ObjectSymbolPolicy::X86_64_ELF_MODULE;
    }
    if !aot_object_admits_macho_hidden_function_definitions(target, target_triple) {
        return trust_cg_lower::ObjectSymbolPolicy::default();
    }
    match target {
        Target::Aarch64 => trust_cg_lower::ObjectSymbolPolicy::AARCH64_MACHO_MODULE,
        Target::X86_64 => trust_cg_lower::ObjectSymbolPolicy::X86_64_MACHO_MODULE,
        // No RISC-V object path writes Mach-O (the predicate above is false).
        Target::Riscv64 => trust_cg_lower::ObjectSymbolPolicy::default(),
    }
}

/// The function-symbol facts the x86-64 module emitter for `target_triple`
/// writes for `trust_ir_module`, restricted to the functions it emits
/// (`emitted`, the post-ISel function names).
///
/// Each fact is one definition's [`FunctionSymbolBinding`], derived by
/// `FunctionSymbolBinding::for_trust_ir_definition` so this path never
/// re-classifies trust-ir linkage. A binding equal to the emitters' default
/// (strong, default-visible global) is no fact at all, and WEAKNESS is never
/// one: it travels on `X86PipelineConfig::weak_function_definitions`, the one
/// place that decides it (`X86FunctionSymbolFacts::check_against` refuses a
/// fact that disagrees). What is left:
///
/// * a module-local (`Internal`/`Private`) definition, carried to every
///   object format (`output_format` other than raw bytes, which has no
///   symbol table and refuses the fact): ELF binds it `STB_LOCAL`
///   ([`aot_object_binds_module_local_functions`] is the predicate that lets
///   the module's own references to it through in the first place), Mach-O
///   a non-external `N_SECT` symbol and COFF `IMAGE_SYM_CLASS_STATIC`, where
///   every reference to it stays refused before lowering and only the
///   unreferenced definition reaches the emitter (ruling
///   OD-X86-BINDING-ONE-CARRIER-20261105);
/// * a hidden `External` definition, a private extern (`N_EXT | N_PEXT`) on
///   Mach-O and `STB_GLOBAL` + `STV_HIDDEN` on ELF;
/// * a protected `External` definition, which only the ELF emitter spells.
///
/// The adapter has already refused every non-default function visibility that
/// this compile's policy does not admit ([`aot_object_symbol_policy`]); one
/// that reaches here anyway fails closed instead of being emitted
/// default-visible, as does a weak definition with a stated visibility (no
/// x86-64 emitter spells that pair). The emitter refuses a fact its own
/// format cannot spell as well
/// (`X86PipelineError::FunctionVisibilityUnsupported`,
/// `X86PipelineError::FunctionLinkageUnsupported`): two independent gates on
/// the same boundary.
fn x86_64_function_symbol_facts<'a>(
    target_triple: &str,
    output_format: crate::x86_64::X86OutputFormat,
    trust_ir_module: &trust_ir::Module,
    emitted: impl IntoIterator<Item = &'a str>,
) -> Result<crate::x86_64::pipeline::X86FunctionSymbolFacts, CompileError> {
    use crate::pipeline::FunctionSymbolLinkage;
    let emitted: std::collections::HashSet<&str> = emitted.into_iter().collect();
    let writes_elf = crate::pipeline::target_triple_uses_elf(target_triple);
    let writes_symbol_table = output_format != crate::x86_64::X86OutputFormat::RawBytes;
    let unspellable = |function: &trust_ir::Function, reason: &str| {
        CompileError::Pipeline(PipelineError::ObjectEmission(format!(
            "x86-64 object symbol facts: emitted function `{}` has linkage `{}` and visibility \
             `{}`, which the {target_triple} object emitter does not spell: {reason} \
             (fail-closed)",
            function.name, function.linkage, function.visibility
        )))
    };
    let mut bindings = Vec::new();
    for function in trust_ir_module
        .functions
        .iter()
        .filter(|function| !function.blocks.is_empty() && emitted.contains(function.name.as_str()))
    {
        let binding =
            FunctionSymbolBinding::for_trust_ir_definition(function.linkage, function.visibility)
                .map_err(|reason| unspellable(function, reason))?;
        match (binding.linkage(), binding.visibility()) {
            // The emitters' default: no fact to carry.
            (
                FunctionSymbolLinkage::Global | FunctionSymbolLinkage::Weak,
                trust_ir::Visibility::Default,
            ) => {}
            // A module-local definition: ELF binds it STB_LOCAL, Mach-O a
            // non-external N_SECT symbol, COFF IMAGE_SYM_CLASS_STATIC. Off
            // ELF any module whose bodies REFERENCE the definition is
            // refused by the identity census before this point
            // (`aot_object_binds_module_local_functions` is false there), so
            // only an unreferenced definition carries the fact; binding it
            // local keeps another object's reference or weak definition from
            // binding to its body (the L02-P1 closure audit's ld.lld,
            // ld64.lld and lld-link reproducers, ruling
            // OD-X86-BINDING-ONE-CARRIER-20261105).
            (FunctionSymbolLinkage::Local, _) if writes_symbol_table => {
                bindings.push((function.name.clone(), FunctionSymbolBinding::LOCAL));
            }
            // Raw bytes have no symbol table, so no binding to state; the
            // emitter refuses a Local fact by name if one ever reaches it
            // (`X86FunctionSymbolFacts::check_against`).
            (FunctionSymbolLinkage::Local, _) => {}
            // A hidden External definition: a Mach-O private extern, or
            // STB_GLOBAL + STV_HIDDEN on ELF.
            (FunctionSymbolLinkage::Global, trust_ir::Visibility::Hidden) => {
                bindings.push((function.name.clone(), FunctionSymbolBinding::HIDDEN));
            }
            // A protected External definition: ELF alone (Mach-O has no
            // protected visibility).
            (FunctionSymbolLinkage::Global, trust_ir::Visibility::Protected) if writes_elf => {
                bindings.push((
                    function.name.clone(),
                    FunctionSymbolBinding::new(
                        FunctionSymbolLinkage::Global,
                        trust_ir::Visibility::Protected,
                    ),
                ));
            }
            (FunctionSymbolLinkage::Global, trust_ir::Visibility::Protected) => {
                return Err(unspellable(
                    function,
                    "only the x86-64 ELF module emitter spells STV_PROTECTED",
                ));
            }
            // A weak definition with a stated visibility: the config carries
            // weakness and the facts carry visibility, and no x86-64 emitter
            // spells the pair, so it is refused rather than split.
            (FunctionSymbolLinkage::Weak, _) => {
                return Err(unspellable(
                    function,
                    "no x86-64 object emitter spells a visibility on a weak definition",
                ));
            }
        }
    }
    // The UNDEFINED-reference facts, from the same one classification of what
    // an object only references that the AArch64 path uses
    // (`SymbolBinding::for_trust_ir_function`): weak for a bodyless
    // `ExternalWeak` function, each carrying its declaration's non-default v45
    // visibility, and — as llc 22 does — a symbol for the weak or visible ones
    // even when nothing in the object references them.
    //
    // Only the ELF emitter spells any of this
    // (OD-X86-ELF-UNDEFINED-REFERENCE-20261106); off ELF the facts stay empty,
    // so those objects are byte-identical. The ADAPTER admits an undefined
    // reference's VISIBILITY for this target
    // (`FunctionSymbolFactPolicy::AdmitElfSymbolVisibility`), so a declaration
    // stating one reaches emission; a WEAK undefined reference stays refused
    // on its own facet (`WeakUndefinedReferencePolicy::Refuse`), so
    // `weak_undefined` is still unreachable from an admitted module and the
    // call loop's GOT backstop below is a fail-closed second barrier, not the
    // gate.
    let mut weak_undefined = std::collections::BTreeSet::new();
    let mut undefined_visibility = std::collections::BTreeMap::new();
    let mut declared_undefined = std::collections::BTreeSet::new();
    if writes_elf {
        for function in &trust_ir_module.functions {
            let weak = match trust_cg_lower::SymbolBinding::for_trust_ir_function(function) {
                trust_cg_lower::SymbolBinding::Undefined { weak } => weak,
                trust_cg_lower::SymbolBinding::Defined(_) => continue,
            };
            let visible = function.visibility != trust_ir::Visibility::Default;
            if weak {
                weak_undefined.insert(function.name.clone());
            }
            if visible {
                undefined_visibility.insert(function.name.clone(), function.visibility);
            }
            if weak || visible {
                declared_undefined.insert(function.name.clone());
            }
        }
    }
    Ok(
        crate::x86_64::pipeline::X86FunctionSymbolFacts::with_definition_bindings(bindings)
            .with_undefined_references(weak_undefined, undefined_visibility, declared_undefined),
    )
}

/// Refuse `module` when one of its definitions would receive a reference the
/// backend makes by name on its own ([`trust_cg_lower::backend_symbol_shadow`]).
/// Every AOT target and the JIT apply this before lowering.
fn refuse_backend_symbol_shadow(
    module: &trust_ir::Module,
    target: impl FnOnce() -> String,
) -> Result<(), CompileError> {
    match trust_cg_lower::backend_symbol_shadow(module) {
        None => Ok(()),
        Some(trust_cg_lower::BackendSymbolShadow::ModuleLocalFunction { name, .. }) => {
            Err(CompileError::ModuleLocalFunctionShadowsRuntimeSymbol {
                target: target(),
                function: name.to_string(),
            })
        }
        Some(trust_cg_lower::BackendSymbolShadow::Data { name }) => {
            Err(CompileError::DataShadowsBackendSymbol {
                target: target(),
                global: name.to_string(),
            })
        }
    }
}

/// Refuse a module-local `sin` or `cos` that a body of `module` references
/// when the AArch64 pipeline will run the Darwin `sincos-merge` pass on it
/// (an Apple Mach-O triple, `target_triple_uses_macho`, the test the pipeline
/// reads to enable the pass).
///
/// That pass rewrites a same-argument pair of non-exact `Bl sin` / `Bl cos`
/// into one `___sincos_stret` call by callee NAME
/// ([`trust_cg_opt::sincos_merge::SINCOS_MERGE_CALLEES`]), so the module's own
/// `sin` and `cos` would be replaced by libm's (measured before this refusal:
/// a module whose Internal `sin`/`cos` add 1.0 and 2.0 returned
/// `sin(0.5) + cos(0.5)` at O2 and O3). Before the Mach-O object path bound
/// module-local functions, every such reference was refused by the identity
/// census; an unreferenced module-local `sin` or `cos` still compiles, and
/// so does one in an ELF object, where the pass is inert.
fn refuse_darwin_sincos_merge_shadow(
    module: &trust_ir::Module,
    target: Target,
    target_triple: &str,
) -> Result<(), CompileError> {
    if target != Target::Aarch64 || !crate::pipeline::target_triple_uses_macho(target_triple) {
        return Ok(());
    }
    let referenced = trust_cg_lower::module_local_function_text_references(module);
    match trust_cg_opt::sincos_merge::SINCOS_MERGE_CALLEES
        .into_iter()
        .find(|name| referenced.contains(*name))
    {
        Some(name) => Err(CompileError::ModuleLocalFunctionShadowsRuntimeSymbol {
            target: target_triple.to_string(),
            function: name.to_string(),
        }),
        None => Ok(()),
    }
}

/// What [`check_elf_module_local_function_binding`] expects of the
/// object compiled from one module.
struct ModuleLocalBindingExpectation<'m> {
    /// The module's bodied Internal/Private definitions
    /// ([`trust_cg_lower::is_module_local_function_definition`], the same
    /// classification the identity census counts references to).
    local_functions: std::collections::BTreeSet<&'m str>,
    /// The module-local functions the module's bodies reference
    /// ([`trust_cg_lower::module_local_function_text_references`]).
    text_referenced: std::collections::BTreeSet<String>,
    /// The module's own globals: data whose linkage the source chose, so a
    /// slot they label may hold a module-local function's address.
    source_globals: std::collections::BTreeSet<&'m str>,
    /// Every name the module spells for something other than a module-local
    /// function definition (its declarations, External definitions and
    /// globals of any linkage). A symbol spelled `helper@...` beside a local
    /// `helper` is the module's own symbol exactly when it is one of these
    /// names (a versioned reference such as `helper@VERS_1`, or a global
    /// that happens to contain `@`).
    declared_names: std::collections::BTreeSet<&'m str>,
}

impl<'m> ModuleLocalBindingExpectation<'m> {
    fn for_module(module: &'m trust_ir::Module) -> Self {
        Self {
            local_functions: module
                .functions
                .iter()
                .filter(|function| trust_cg_lower::is_module_local_function_definition(function))
                .map(|function| function.name.as_str())
                .collect(),
            text_referenced: trust_cg_lower::module_local_function_text_references(module),
            source_globals: module
                .globals
                .iter()
                .map(|global| global.name.as_str())
                .collect(),
            declared_names: module
                .functions
                .iter()
                .filter(|function| !trust_cg_lower::is_module_local_function_definition(function))
                .map(|function| function.name.as_str())
                .chain(module.globals.iter().map(|global| global.name.as_str()))
                .collect(),
        }
    }

    fn empty() -> Self {
        Self {
            local_functions: std::collections::BTreeSet::new(),
            text_referenced: std::collections::BTreeSet::new(),
            source_globals: std::collections::BTreeSet::new(),
            declared_names: std::collections::BTreeSet::new(),
        }
    }
}

/// Refuse an AArch64 ELF object that reaches a module-local function other
/// than through that function's own `STB_LOCAL` definition.
///
/// The object is read back by the independent ELF reader, not from writer
/// state, so this also covers an object taken from the artifact cache. For
/// every module-local function it requires:
///
/// 1. every symbol spelling its name exactly (a name containing `@`
///    included) is one defined `STB_LOCAL` `STT_FUNC` symbol in an
///    executable section (its definition), and a versioned spelling
///    `name@...` appears only as a symbol the module itself names under
///    exactly that spelling (a declaration of, or a reference to, a versioned
///    symbol of another object, or one of the module's own functions or
///    globals, whatever its binding): anything else the writer made up;
/// 2. no non-local defined symbol overlaps that definition's range (an
///    exported alias of the local body);
/// 3. every relocation whose symbol plus addend is the definition's start
///    (by name, or by address through another symbol such as the section
///    symbol) uses a local symbol;
/// 4. a data word relocated to the definition's start is labelled by no
///    non-local symbol except one of the module's own globals: a slot the
///    compiler synthesizes (the `DW.ref.<personality>` cell) must not be a
///    weak or global symbol another object could replace;
/// 5. a text relocation to the definition's start comes from a reference the
///    module's bodies make; otherwise the backend made it on its own by name
///    (a runtime call spelled like the local function).
fn check_elf_module_local_function_binding(
    target_triple: &str,
    object: &[u8],
    expected: &ModuleLocalBindingExpectation<'_>,
) -> Result<(), CompileError> {
    use crate::elf::constants::{SHF_EXECINSTR, STB_LOCAL, STT_FUNC};

    if expected.local_functions.is_empty() {
        return Ok(());
    }
    let violation =
        |function: &str, detail: String| CompileError::AotModuleLocalFunctionBindingViolated {
            target: target_triple.to_string(),
            function: function.to_string(),
            detail,
        };
    let first_local = expected
        .local_functions
        .iter()
        .next()
        .copied()
        .unwrap_or_default();
    let records = crate::elf::reparse::read_object_records(object).map_err(|error| {
        violation(
            first_local,
            format!("the emitted object does not parse as ELF: {error}"),
        )
    })?;
    // A regular section index: not SHN_UNDEF and not a reserved index
    // (SHN_ABS, SHN_COMMON, ...).
    let regular_section = |index: u16| index != 0 && index < 0xff00;
    let executable = |index: usize| {
        records
            .sections
            .get(index)
            .is_some_and(|section| section.sh_flags & SHF_EXECINSTR != 0)
    };

    // 1. The spellings of each local function's name; collect definitions.
    let mut definitions: Vec<(&str, u16, u64, u64)> = Vec::new();
    for (index, symbol) in records.symbols.iter().enumerate() {
        let name = symbol.name.as_str();
        let Some(function) = expected.local_functions.get(name).copied() else {
            // A versioned spelling of a local function's name, at any `@`
            // (the local name may itself contain one).
            let Some(function) = name
                .match_indices('@')
                .find_map(|(at, _)| expected.local_functions.get(&name[..at]).copied())
            else {
                continue;
            };
            if !expected.declared_names.contains(name) {
                return Err(violation(
                    function,
                    format!(
                        "symbol #{index} `{name}` (binding {}, section index {}) is a versioned \
                         spelling of the local function's name that the module does not name",
                        symbol.binding, symbol.section_index
                    ),
                ));
            }
            continue;
        };
        if symbol.binding != STB_LOCAL
            || symbol.symbol_type != STT_FUNC
            || !regular_section(symbol.section_index)
            || !executable(usize::from(symbol.section_index))
        {
            return Err(violation(
                function,
                format!(
                    "symbol #{index} `{}` has binding {}, type {} and section index {}; only a \
                     defined STB_LOCAL STT_FUNC symbol in an executable section may spell this \
                     name",
                    symbol.name, symbol.binding, symbol.symbol_type, symbol.section_index
                ),
            ));
        }
        definitions.push((
            function,
            symbol.section_index,
            symbol.value,
            symbol.value.saturating_add(symbol.size.max(1)),
        ));
    }

    // 2. No exported alias overlaps a local definition.
    for (index, symbol) in records.symbols.iter().enumerate() {
        if symbol.binding == STB_LOCAL || !regular_section(symbol.section_index) {
            continue;
        }
        let (start, end) = (
            symbol.value,
            symbol.value.saturating_add(symbol.size.max(1)),
        );
        if let Some((function, ..)) = definitions.iter().find(|(_, section, from, to)| {
            *section == symbol.section_index && start < *to && *from < end
        }) {
            return Err(violation(
                function,
                format!(
                    "non-local symbol #{index} `{}` (binding {}) overlaps the local definition",
                    symbol.name, symbol.binding
                ),
            ));
        }
    }

    // The local function whose definition starts at `symbol + addend`.
    let reached = |symbol: &crate::elf::reparse::ElfSymbolRecord, addend: i64| {
        if !regular_section(symbol.section_index) {
            return None;
        }
        let target = i128::from(symbol.value) + i128::from(addend);
        definitions
            .iter()
            .find(|(_, section, start, _)| {
                *section == symbol.section_index && i128::from(*start) == target
            })
            .map(|(function, ..)| *function)
    };
    for relocation in &records.relocations {
        let record = relocation.record;
        let index = record.symbol_index as usize;
        let Some(symbol) = records.symbols.get(index) else {
            return Err(violation(
                first_local,
                format!(
                    "a relocation at offset {:#x} of section {} names symbol #{index}, past \
                     the end of the symbol table",
                    record.r_offset, relocation.target_section
                ),
            ));
        };
        let Some(function) = reached(symbol, record.r_addend) else {
            continue;
        };
        let site = format!(
            "relocation type {} at offset {:#x} of section {}",
            record.reloc_type, record.r_offset, relocation.target_section
        );
        // 3. Through a local symbol only.
        if symbol.binding != STB_LOCAL {
            return Err(violation(
                function,
                format!(
                    "{site} reaches the local definition through non-local symbol #{index} `{}`",
                    symbol.name
                ),
            ));
        }
        if executable(relocation.target_section) {
            // 5. A text reference the module's bodies make.
            if !expected.text_referenced.contains(function) {
                return Err(violation(
                    function,
                    format!(
                        "{site} is a text reference no function body of the module makes; the \
                         backend referenced the name on its own (a runtime call spelled like \
                         the local function) and would run the module's body"
                    ),
                ));
            }
            continue;
        }
        // 4. A data slot holding the address: no replaceable synthesized label.
        let target_section = u16::try_from(relocation.target_section).unwrap_or(u16::MAX);
        for (label_index, label) in records.symbols.iter().enumerate() {
            let labels_slot = label.section_index == target_section
                && label.value <= record.r_offset
                && record.r_offset < label.value.saturating_add(label.size.max(1));
            if labels_slot
                && label.binding != STB_LOCAL
                && !expected.source_globals.contains(label.name.as_str())
            {
                return Err(violation(
                    function,
                    format!(
                        "{site} stores its address in a slot labelled by non-local symbol \
                         #{label_index} `{}` (binding {}), which the module does not declare; \
                         another object's definition of that symbol could replace the slot",
                        label.name, label.binding
                    ),
                ));
            }
        }
    }
    Ok(())
}

/// Refuse an ELF object in which a reference that must reach code resolves to
/// a defined location outside every executable section.
///
/// The emitters resolve every reference by name, so a runtime call or a
/// personality spelled like the module's own data would bind to that data.
/// Read back by the independent ELF reader, the object may have:
///
/// 1. no relocation of a BRANCH type (`branch_relocations`: `CALL26`/`JUMP26`
///    on AArch64, `PLT32` on x86-64, the type its emitter writes for a direct
///    call) whose symbol is defined in a non-executable section (a branch into
///    data);
/// 2. no relocated word, in a slot labelled by a symbol spelled `DW.ref.*`
///    (the unwind tables' indirect personality cell), whose symbol is
///    defined in a non-executable section (a personality that is data).
///
/// Undefined, absolute and common targets are left to the linker. This is the
/// object-level backstop behind [`refuse_backend_symbol_shadow`]
/// and the adapter's runtime-call refusal. Rule 2 also refuses a module global
/// spelled `DW.ref.*` whose initializer holds a data address.
/// The ELF relocation types an AArch64 emitter writes for a DIRECT BRANCH,
/// for [`check_elf_code_references_reach_code`] rule 1: the two that encode a
/// 26-bit immediate branch (`BL` and `B`). Every other AArch64 relocation may
/// legitimately name data.
const AARCH64_ELF_BRANCH_RELOCATIONS: [u32; 2] = [
    crate::elf::constants::R_AARCH64_CALL26,
    crate::elf::constants::R_AARCH64_JUMP26,
];

/// The ELF relocation type the x86-64 emitter writes for a DIRECT BRANCH, for
/// [`check_elf_code_references_reach_code`] rule 1: `R_X86_64_PLT32`, which
/// `emit_module_elf` writes for every `CALL` fixup and nothing else.
/// `R_X86_64_PC32` is NOT one: the same emitter writes it for a RIP-relative
/// DATA reference, which legitimately names a non-executable section.
const X86_64_ELF_BRANCH_RELOCATIONS: [u32; 1] = [crate::elf::constants::R_X86_64_PLT32];

fn check_elf_code_references_reach_code(
    target_triple: &str,
    object: &[u8],
    branch_relocations: &[u32],
) -> Result<(), CompileError> {
    use crate::elf::constants::SHF_EXECINSTR;

    let refuse = |detail: String| CompileError::AotCodeReferenceReachesData {
        target: target_triple.to_string(),
        detail,
    };
    let records = crate::elf::reparse::read_object_records(object)
        .map_err(|error| refuse(format!("the emitted object does not parse as ELF: {error}")))?;
    let regular_section = |index: u16| index != 0 && index < 0xff00;
    let executable = |index: usize| {
        records
            .sections
            .get(index)
            .is_some_and(|section| section.sh_flags & SHF_EXECINSTR != 0)
    };
    for relocation in &records.relocations {
        let record = relocation.record;
        let index = record.symbol_index as usize;
        let Some(symbol) = records.symbols.get(index) else {
            return Err(refuse(format!(
                "a relocation at offset {:#x} of section {} names symbol #{index}, past the end \
                 of the symbol table",
                record.r_offset, relocation.target_section
            )));
        };
        if !regular_section(symbol.section_index) || executable(usize::from(symbol.section_index)) {
            continue;
        }
        let site = format!(
            "relocation type {} at offset {:#x} of section {} names symbol #{index} `{}`, \
             defined in non-executable section {}",
            record.reloc_type,
            record.r_offset,
            relocation.target_section,
            symbol.name,
            symbol.section_index
        );
        // 1. A branch into data.
        if branch_relocations.contains(&record.reloc_type) {
            return Err(refuse(format!("{site}: a branch into data")));
        }
        // 2. A personality slot holding a data address.
        if !executable(relocation.target_section) {
            let target_section = u16::try_from(relocation.target_section).unwrap_or(u16::MAX);
            if let Some(label) = records.symbols.iter().find(|label| {
                label.section_index == target_section
                    && label.name.starts_with("DW.ref.")
                    && label.value <= record.r_offset
                    && record.r_offset < label.value.saturating_add(label.size.max(1))
            }) {
                return Err(refuse(format!(
                    "{site}: the personality slot `{}` would hold a data address",
                    label.name
                )));
            }
        }
    }
    Ok(())
}

/// `cputype` of an AArch64 Mach-O object (`CPU_TYPE_ARM64`).
const MACHO_CPU_TYPE_ARM64: u32 = 0x0100_000C;
/// Mach-O section attribute: debugging sections (`S_ATTR_DEBUG`). ld64 binds
/// nothing through them and drops them from the linked image.
const MACHO_S_ATTR_DEBUG: u32 = 0x0200_0000;

/// Whether a Mach-O section with `flags` holds machine instructions.
fn macho_section_is_executable(flags: u32) -> bool {
    use crate::macho::constants::{S_ATTR_PURE_INSTRUCTIONS, S_ATTR_SOME_INSTRUCTIONS};
    flags & (S_ATTR_PURE_INSTRUCTIONS | S_ATTR_SOME_INSTRUCTIONS) != 0
}

/// The signed in-place addend of an `ARM64_RELOC_UNSIGNED` record: the
/// 4-byte (`r_length` 2) or 8-byte (`r_length` 3) word at `r_address` in the
/// section's bytes, or `None` when the word is outside them.
fn macho_unsigned_in_place_addend(data: &[u8], r_address: u32, r_length: u8) -> Option<i64> {
    let start = r_address as usize;
    match r_length {
        2 => data
            .get(start..start.checked_add(4)?)
            .map(|word| i64::from(i32::from_le_bytes(word.try_into().unwrap_or([0; 4])))),
        3 => data
            .get(start..start.checked_add(8)?)
            .map(|word| i64::from_le_bytes(word.try_into().unwrap_or([0; 8]))),
        _ => None,
    }
}

/// One relocation of an AArch64 Mach-O object as the binding checks read it:
/// its section, its record, and the addend its target address carries (an
/// `ARM64_RELOC_ADDEND` prefix, the in-place word of an `ARM64_RELOC_UNSIGNED`,
/// or zero).
struct MachoResolvedRelocation {
    section: usize,
    record: crate::macho::reparse::RelocIntent,
    addend: i64,
}

/// Every non-prefix relocation of `records` (an `ARM64_RELOC_ADDEND` prefix
/// and the `ARM64_RELOC_SUBTRACTOR` half of a pair are folded into the record
/// that follows them), with its addend. A prefix that does not precede a
/// record it can apply to, or an in-place addend outside its section, is
/// refused by `refuse`.
fn macho_resolved_relocations(
    records: &crate::macho::reparse::MachoObjectRecords,
    refuse: impl Fn(String) -> CompileError,
) -> Result<Vec<MachoResolvedRelocation>, CompileError> {
    use crate::macho::constants::{
        ARM64_RELOC_ADDEND, ARM64_RELOC_BRANCH26, ARM64_RELOC_PAGE21, ARM64_RELOC_PAGEOFF12,
        ARM64_RELOC_SUBTRACTOR, ARM64_RELOC_UNSIGNED,
    };
    let mut resolved = Vec::new();
    for (section_index, relocations) in records.section_relocations.iter().enumerate() {
        let section = &records.sections[section_index];
        let mut pending_addend: Option<i64> = None;
        let mut pending_subtractor = false;
        for record in relocations {
            let kind = u32::from(record.r_type);
            let site = || {
                format!(
                    "relocation type {kind} at offset {:#x} of section {},{}",
                    record.r_address, section.segname, section.sectname
                )
            };
            if kind == ARM64_RELOC_ADDEND {
                if pending_addend.is_some() || pending_subtractor {
                    return Err(refuse(format!("{} follows another prefix", site())));
                }
                // A 24-bit signed addend in `r_symbolnum`.
                let raw = record.r_symbolnum & 0x00FF_FFFF;
                pending_addend = Some(i64::from(((raw << 8) as i32) >> 8));
                continue;
            }
            if kind == ARM64_RELOC_SUBTRACTOR {
                if pending_addend.is_some() || pending_subtractor {
                    return Err(refuse(format!("{} follows another prefix", site())));
                }
                pending_subtractor = true;
                continue;
            }
            let addend = if let Some(addend) = pending_addend.take() {
                if ![
                    ARM64_RELOC_BRANCH26,
                    ARM64_RELOC_PAGE21,
                    ARM64_RELOC_PAGEOFF12,
                ]
                .contains(&kind)
                {
                    return Err(refuse(format!(
                        "{} carries an ARM64_RELOC_ADDEND prefix it cannot take",
                        site()
                    )));
                }
                addend
            } else if kind == ARM64_RELOC_UNSIGNED {
                macho_unsigned_in_place_addend(&section.data, record.r_address, record.r_length)
                    .ok_or_else(|| {
                        refuse(format!(
                            "{} has no in-place word of length {} inside its section",
                            site(),
                            record.r_length
                        ))
                    })?
            } else {
                0
            };
            if pending_subtractor && kind != ARM64_RELOC_UNSIGNED {
                return Err(refuse(format!(
                    "{} follows an ARM64_RELOC_SUBTRACTOR",
                    site()
                )));
            }
            pending_subtractor = false;
            resolved.push(MachoResolvedRelocation {
                section: section_index,
                record: *record,
                addend,
            });
        }
        if pending_addend.is_some() || pending_subtractor {
            return Err(refuse(format!(
                "section {},{} ends with a relocation prefix",
                section.segname, section.sectname
            )));
        }
    }
    Ok(resolved)
}

/// The ISA determines the Mach-O relocation vocabulary, never the host.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum MachoBindingArch {
    Aarch64,
    X86_64,
}

impl MachoBindingArch {
    fn cpu_type(self) -> u32 {
        match self {
            Self::Aarch64 => MACHO_CPU_TYPE_ARM64,
            Self::X86_64 => 0x0100_0007,
        }
    }

    fn cpu_name(self) -> &'static str {
        match self {
            Self::Aarch64 => "CPU_TYPE_ARM64",
            Self::X86_64 => "CPU_TYPE_X86_64",
        }
    }
}

/// Resolve the ordinary x86-64 pointer, RIP-relative and branch records this
/// emitter writes, including both identities in paired difference records.
/// Their in-place addends apply to the symbol's address;
/// SIGNED_1/2/4 adjust the displacement's PC base, not that target address.
/// An unmodelled difference expression or malformed record is refused rather
/// than interpreted using the unrelated AArch64 relocation vocabulary.
fn x86_64_macho_resolved_relocations(
    records: &crate::macho::reparse::MachoObjectRecords,
    refuse: impl Fn(String) -> CompileError,
) -> Result<Vec<MachoResolvedRelocation>, CompileError> {
    let mut resolved = Vec::new();
    for (section_index, relocations) in records.section_relocations.iter().enumerate() {
        let section = &records.sections[section_index];
        if section.flags & MACHO_S_ATTR_DEBUG != 0 {
            continue;
        }
        let mut records_iter = relocations.iter();
        while let Some(record) = records_iter.next() {
            if record.r_type == 5 {
                let pair = records_iter.next().filter(|pair| {
                    !record.r_pcrel && !pair.r_pcrel && pair.r_type == 0
                        && record.r_address == pair.r_address
                        && record.r_length == pair.r_length
                        && matches!(record.r_length, 2 | 3)
                }).ok_or_else(|| refuse(format!(
                    "x86-64 SUBTRACTOR at offset {:#x} of section {},{} has no matching UNSIGNED pair",
                    record.r_address, section.segname, section.sectname
                )))?;
                let addend =
                    macho_unsigned_in_place_addend(&section.data, pair.r_address, pair.r_length)
                        .ok_or_else(|| {
                            refuse(
                                "x86-64 SUBTRACTOR pair has no complete in-place word".to_string(),
                            )
                        })?;
                resolved.push(MachoResolvedRelocation {
                    section: section_index,
                    record: *record,
                    addend: 0,
                });
                resolved.push(MachoResolvedRelocation {
                    section: section_index,
                    record: *pair,
                    addend,
                });
                continue;
            }
            let kind = record.r_type;
            let site = || {
                format!(
                    "x86-64 relocation type {kind} at offset {:#x} of section {},{}",
                    record.r_address, section.segname, section.sectname
                )
            };
            let addend = match kind {
                0 if !record.r_pcrel && matches!(record.r_length, 2 | 3) => {
                    macho_unsigned_in_place_addend(&section.data, record.r_address, record.r_length)
                }
                1 | 2 | 6 | 7 | 8 if record.r_pcrel && record.r_length == 2 => {
                    macho_unsigned_in_place_addend(&section.data, record.r_address, 2)
                }
                3 | 4 | 9 if record.r_pcrel && record.r_length == 2 => {
                    let addend = macho_unsigned_in_place_addend(&section.data, record.r_address, 2);
                    // The emitter's DW_EH_PE_pcrel personality word uses
                    // field-start addressing: GOT's field-end bias needs +4.
                    // It still identifies this symbol's GOT entry, not S+4.
                    let eh_frame_compensation =
                        section.sectname == "__eh_frame" && kind == 4 && addend == Some(4);
                    if addend != Some(0) && !eh_frame_compensation {
                        return Err(refuse(format!(
                            "{} has an unmodelled indirect addend",
                            site()
                        )));
                    }
                    Some(0)
                }
                _ => {
                    return Err(refuse(format!(
                        "{} has unmodelled kind/PC-relative/width fields",
                        site()
                    )));
                }
            }
            .ok_or_else(|| {
                refuse(format!(
                    "{} has no complete in-place word in its section",
                    site()
                ))
            })?;
            resolved.push(MachoResolvedRelocation {
                section: section_index,
                record: *record,
                addend,
            });
        }
    }
    Ok(resolved)
}

fn check_aarch64_macho_module_local_function_binding(
    target_triple: &str,
    object: &[u8],
    expected: &ModuleLocalBindingExpectation<'_>,
) -> Result<(), CompileError> {
    check_macho_module_local_function_binding(
        target_triple,
        object,
        expected,
        MachoBindingArch::Aarch64,
    )
}

fn check_x86_64_macho_module_local_function_binding(
    target_triple: &str,
    object: &[u8],
    expected: &ModuleLocalBindingExpectation<'_>,
) -> Result<(), CompileError> {
    check_macho_module_local_function_binding(
        target_triple,
        object,
        expected,
        MachoBindingArch::X86_64,
    )
}

/// Refuse a Mach-O object that reaches a module-local function other
/// than through that function's own non-external (`N_EXT` clear) definition.
///
/// This is the Mach-O counterpart of
/// [`check_elf_module_local_function_binding`]. The object is read
/// back by the independent Mach-O reader
/// ([`crate::macho::reparse::read_object_records`]), never from writer state,
/// so it also covers an object from the artifact cache. A Mach-O symbol whose
/// `N_EXT` bit is clear is invisible to the static linker outside its object
/// and to dyld, so no other object or image can supply the definition a
/// reference to it reaches. With `MH_SUBSECTIONS_VIA_SYMBOLS` ld64 splits
/// each section into atoms at its symbols and resolves a reference to a
/// symbol, or to an address, to the atom that holds it; a non-external atom
/// is kept or stripped but never coalesced or replaced. Mach-O symbols carry
/// the C `_` prefix, and Mach-O has no symbol versioning. For every
/// module-local function `f` the object may have:
///
/// 1. every symbol spelled `_f` (debugger `N_STAB` entries aside) is its one
///    definition: `N_SECT`, neither `N_EXT` nor `N_PEXT`, in an instruction
///    section; an undefined, absolute, indirect, private-external or external
///    `_f`, or a second definition, is refused;
/// 2. no external (`N_EXT`) symbol defined in that section lies inside the
///    definition, from its start up to the next symbol naming one of the
///    module's functions (an exported alias of the local body, which would
///    also start an atom that splits it);
/// 3. every external relocation whose symbol plus addend is the definition's
///    start uses a non-external symbol; addends are decoded using the selected
///    ISA's relocation vocabulary, never the host's. A section-relative
///    (`r_extern` clear) relocation outside the debug sections is not modelled
///    and is refused;
/// 4. a data word relocated to the definition's start lies in an atom whose
///    symbol (the nearest symbol at or below it in its section) is
///    non-external or one of the module's own globals;
/// 5. a relocation in an instruction section reaching the definition comes
///    from a reference the module's bodies make.
///
/// Relocations in `S_ATTR_DEBUG` sections bind nothing and are skipped.
fn check_macho_module_local_function_binding(
    target_triple: &str,
    object: &[u8],
    expected: &ModuleLocalBindingExpectation<'_>,
    arch: MachoBindingArch,
) -> Result<(), CompileError> {
    if expected.local_functions.is_empty() {
        return Ok(());
    }
    let violation =
        |function: &str, detail: String| CompileError::AotModuleLocalFunctionBindingViolated {
            target: target_triple.to_string(),
            function: function.to_string(),
            detail,
        };
    let first_local = expected
        .local_functions
        .iter()
        .next()
        .copied()
        .unwrap_or_default();
    let records = crate::macho::reparse::read_object_records(object).map_err(|error| {
        violation(
            first_local,
            format!("the emitted object does not parse as Mach-O: {error}"),
        )
    })?;
    if records.cputype != arch.cpu_type() {
        return Err(violation(
            first_local,
            format!(
                "the emitted object's cputype {:#x} is not {}",
                records.cputype,
                arch.cpu_name()
            ),
        ));
    }
    let executable = |ordinal: u8| {
        records
            .section(ordinal)
            .is_some_and(|section| macho_section_is_executable(section.flags))
    };
    // The module function a Mach-O symbol name spells, if any.
    let local_of = |name: &str| {
        name.strip_prefix('_')
            .and_then(|stem| expected.local_functions.get(stem).copied())
    };
    let module_function = |name: &str| {
        name.strip_prefix('_').is_some_and(|stem| {
            expected.local_functions.contains(stem) || expected.declared_names.contains(stem)
        })
    };

    // 1. The spellings of each local function's name; collect definitions.
    let mut definitions: Vec<(&str, u8, u64)> = Vec::new();
    for (index, symbol) in records.symbols.iter().enumerate() {
        if symbol.is_stab() {
            continue;
        }
        let Some(function) = local_of(&symbol.name) else {
            continue;
        };
        if !symbol.is_section_definition()
            || symbol.is_external()
            || symbol.is_private_external()
            || !executable(symbol.n_sect)
        {
            return Err(violation(
                function,
                format!(
                    "symbol #{index} `{}` has n_type {:#04x} and n_sect {}; only a \
                     non-external N_SECT definition in an instruction section may spell \
                     this name",
                    symbol.name, symbol.n_type, symbol.n_sect
                ),
            ));
        }
        if definitions.iter().any(|(defined, ..)| *defined == function) {
            return Err(violation(
                function,
                format!(
                    "symbol #{index} `{}` is a second definition of the local function",
                    symbol.name
                ),
            ));
        }
        definitions.push((function, symbol.n_sect, symbol.n_value));
    }

    // 2. No external symbol inside a local definition.
    for &(function, n_sect, start) in &definitions {
        let section_end = records
            .section(n_sect)
            .map_or(start, |section| section.addr.saturating_add(section.size));
        let end = records
            .symbols
            .iter()
            .filter(|symbol| {
                symbol.is_section_definition()
                    && symbol.n_sect == n_sect
                    && symbol.n_value > start
                    && module_function(&symbol.name)
            })
            .map(|symbol| symbol.n_value)
            .min()
            .unwrap_or(section_end)
            .max(start.saturating_add(1));
        if let Some((index, symbol)) = records.symbols.iter().enumerate().find(|(_, symbol)| {
            symbol.is_section_definition()
                && (symbol.is_external() || symbol.is_private_external())
                && symbol.n_sect == n_sect
                && start <= symbol.n_value
                && symbol.n_value < end
        }) {
            return Err(violation(
                function,
                format!(
                    "external symbol #{index} `{}` (n_type {:#04x}) lies inside the local \
                     definition",
                    symbol.name, symbol.n_type
                ),
            ));
        }
    }

    let relocations = match arch {
        MachoBindingArch::Aarch64 => {
            macho_resolved_relocations(&records, |detail| violation(first_local, detail))?
        }
        MachoBindingArch::X86_64 => {
            x86_64_macho_resolved_relocations(&records, |detail| violation(first_local, detail))?
        }
    };
    for relocation in &relocations {
        let section = &records.sections[relocation.section];
        if section.flags & MACHO_S_ATTR_DEBUG != 0 {
            continue;
        }
        let record = relocation.record;
        let site = format!(
            "relocation type {} at offset {:#x} of section {},{}",
            record.r_type, record.r_address, section.segname, section.sectname
        );
        if !record.r_extern {
            return Err(violation(
                first_local,
                format!(
                    "{site} is section-relative; this check models only external \
                     relocations outside the debug sections"
                ),
            ));
        }
        let index = record.r_symbolnum as usize;
        let Some(symbol) = records.symbols.get(index) else {
            return Err(violation(
                first_local,
                format!("{site} names symbol #{index}, past the end of the symbol table"),
            ));
        };
        if !symbol.is_section_definition() {
            continue;
        }
        let target = i128::from(symbol.n_value) + i128::from(relocation.addend);
        let Some(function) = definitions
            .iter()
            .find(|(_, n_sect, start)| *n_sect == symbol.n_sect && i128::from(*start) == target)
            .map(|(function, ..)| *function)
        else {
            continue;
        };
        // A TLV relocation treats its target as a descriptor, not a code
        // address, and cannot carry the identity of a local function.
        if arch == MachoBindingArch::X86_64 && record.r_type == 9 {
            return Err(violation(
                function,
                format!("{site} uses a function as a TLV descriptor"),
            ));
        }
        // 3. Through a non-external symbol only.
        if symbol.is_external() || symbol.is_private_external() {
            return Err(violation(
                function,
                format!(
                    "{site} reaches the local definition through external symbol #{index} `{}`",
                    symbol.name
                ),
            ));
        }
        if macho_section_is_executable(section.flags) {
            // 5. A text reference the module's bodies make.
            if !expected.text_referenced.contains(function) {
                return Err(violation(
                    function,
                    format!(
                        "{site} is a text reference no function body of the module makes; the \
                         backend referenced the name on its own (a runtime call spelled like \
                         the local function) and would run the module's body"
                    ),
                ));
            }
            continue;
        }
        // 4. A data word in a replaceable atom.
        let ordinal = u8::try_from(relocation.section + 1).unwrap_or(u8::MAX);
        let slot = section.addr.saturating_add(u64::from(record.r_address));
        let label_address = records
            .symbols
            .iter()
            .filter(|label| {
                label.is_section_definition() && label.n_sect == ordinal && label.n_value <= slot
            })
            .map(|label| label.n_value)
            .max();
        if let Some(label_address) = label_address
            && let Some((label_index, label)) =
                records.symbols.iter().enumerate().find(|(_, label)| {
                    label.is_section_definition()
                        && label.n_sect == ordinal
                        && label.n_value == label_address
                        && (label.is_external() || label.is_private_external())
                        && !label
                            .name
                            .strip_prefix('_')
                            .is_some_and(|stem| expected.source_globals.contains(stem))
                })
        {
            return Err(violation(
                function,
                format!(
                    "{site} stores its address in an atom labelled by external symbol \
                     #{label_index} `{}` (n_type {:#04x}), which the module does not declare; \
                     another object's definition of that symbol could replace the atom",
                    label.name, label.n_type
                ),
            ));
        }
    }
    Ok(())
}

/// Refuse an AArch64 Mach-O object in which a reference that must reach code
/// resolves to a definition outside every instruction section: the Mach-O
/// counterpart of [`check_elf_code_references_reach_code`]. Read back
/// by the independent Mach-O reader, the object may have:
///
/// 1. no `ARM64_RELOC_BRANCH26` whose symbol is defined in a section without
///    instructions (a branch into data);
/// 2. no personality reference (an `ARM64_RELOC_POINTER_TO_GOT` in
///    `__eh_frame`, or the personality word at offset 16 of a 32-byte
///    `__LD,__compact_unwind` entry) whose symbol is defined in a section
///    without instructions.
///
/// Undefined targets are left to the linker. This is the object-level
/// backstop behind [`refuse_backend_symbol_shadow`].
fn check_aarch64_macho_code_references_reach_code(
    target_triple: &str,
    object: &[u8],
) -> Result<(), CompileError> {
    check_macho_code_references_reach_code(target_triple, object, MachoBindingArch::Aarch64)
}

fn check_x86_64_macho_code_references_reach_code(
    target_triple: &str,
    object: &[u8],
) -> Result<(), CompileError> {
    check_macho_code_references_reach_code(target_triple, object, MachoBindingArch::X86_64)
}

fn check_macho_code_references_reach_code(
    target_triple: &str,
    object: &[u8],
    arch: MachoBindingArch,
) -> Result<(), CompileError> {
    use crate::macho::constants::{ARM64_RELOC_BRANCH26, ARM64_RELOC_POINTER_TO_GOT};
    const COMPACT_UNWIND_ENTRY_SIZE: u32 = 32;
    const COMPACT_UNWIND_PERSONALITY_OFFSET: u32 = 16;

    let refuse = |detail: String| CompileError::AotCodeReferenceReachesData {
        target: target_triple.to_string(),
        detail,
    };
    let records = crate::macho::reparse::read_object_records(object).map_err(|error| {
        refuse(format!(
            "the emitted object does not parse as Mach-O: {error}"
        ))
    })?;
    if records.cputype != arch.cpu_type() {
        return Err(refuse(format!(
            "the emitted object's cputype {:#x} is not {}",
            records.cputype,
            arch.cpu_name()
        )));
    }
    let relocations = match arch {
        MachoBindingArch::Aarch64 => macho_resolved_relocations(&records, refuse)?,
        MachoBindingArch::X86_64 => x86_64_macho_resolved_relocations(&records, refuse)?,
    };
    for relocation in &relocations {
        let record = relocation.record;
        if !record.r_extern {
            continue;
        }
        let section = &records.sections[relocation.section];
        let index = record.r_symbolnum as usize;
        let Some(symbol) = records.symbols.get(index) else {
            return Err(refuse(format!(
                "a relocation at offset {:#x} of section {},{} names symbol #{index}, past the \
                 end of the symbol table",
                record.r_address, section.segname, section.sectname
            )));
        };
        if !symbol.is_section_definition()
            || records
                .section(symbol.n_sect)
                .is_some_and(|defining| macho_section_is_executable(defining.flags))
        {
            continue;
        }
        let kind = u32::from(record.r_type);
        let site = format!(
            "relocation type {kind} at offset {:#x} of section {},{} names symbol #{index} `{}`, \
             defined in non-instruction section {}",
            record.r_address, section.segname, section.sectname, symbol.name, symbol.n_sect
        );
        // 1. A branch into data.
        if kind == ARM64_RELOC_BRANCH26 {
            return Err(refuse(format!("{site}: a branch into data")));
        }
        // 2. A personality that is data.
        let eh_frame_personality = section.sectname == "__eh_frame"
            && match arch {
                MachoBindingArch::Aarch64 => kind == ARM64_RELOC_POINTER_TO_GOT,
                MachoBindingArch::X86_64 => matches!(kind, 3 | 4),
            };
        let compact_unwind_personality = section.segname == "__LD"
            && section.sectname == "__compact_unwind"
            && record.r_address % COMPACT_UNWIND_ENTRY_SIZE == COMPACT_UNWIND_PERSONALITY_OFFSET;
        if eh_frame_personality || compact_unwind_personality {
            return Err(refuse(format!(
                "{site}: the personality reference would reach a data address"
            )));
        }
    }
    Ok(())
}

/// The post-emission module-local binding check for the AArch64 object
/// format `target_triple` selects: ELF
/// ([`check_elf_module_local_function_binding`]) or Mach-O
/// ([`check_aarch64_macho_module_local_function_binding`]).
fn check_aarch64_module_local_function_binding(
    target_triple: &str,
    object: &[u8],
    expected: &ModuleLocalBindingExpectation<'_>,
) -> Result<(), CompileError> {
    if crate::pipeline::target_triple_uses_elf(target_triple) {
        check_elf_module_local_function_binding(target_triple, object, expected)
    } else {
        check_aarch64_macho_module_local_function_binding(target_triple, object, expected)
    }
}

/// The post-emission code-reference backstop for the AArch64 object format
/// `target_triple` selects.
fn check_aarch64_code_references_reach_code(
    target_triple: &str,
    object: &[u8],
) -> Result<(), CompileError> {
    if crate::pipeline::target_triple_uses_elf(target_triple) {
        check_elf_code_references_reach_code(target_triple, object, &AARCH64_ELF_BRANCH_RELOCATIONS)
    } else {
        check_aarch64_macho_code_references_reach_code(target_triple, object)
    }
}

/// How [`check_object_function_bindings`] names the binding it expects.
fn describe_function_binding(binding: FunctionSymbolBinding) -> String {
    match binding.linkage() {
        FunctionSymbolLinkage::Local => "local".to_string(),
        FunctionSymbolLinkage::Weak => format!("weak, {}-visibility,", binding.visibility()),
        FunctionSymbolLinkage::Global => format!("global, {}-visibility,", binding.visibility()),
    }
}

/// The object format [`check_object_function_bindings`] reads.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum BindingCheckFormat {
    Elf,
    MachO,
    Coff,
}

/// Refuse an x86-64 (ELF, Mach-O, COFF) or RISC-V (ELF) object whose symbol
/// table does not bind each function definition it emits (`emitted`) as the
/// trust-ir module's linkage and visibility dictate: the binding
/// `FunctionSymbolBinding::for_trust_ir_definition` gives it, the one
/// classification the x86-64 emitters' facts carry
/// (`x86_64_function_symbol_facts`). Exactly one symbol spells the
/// function's name (Mach-O: with its leading `_`), defined in a section, a
/// function symbol (ELF `STT_FUNC`, COFF type `0x20`), spelled in the
/// format's own way: ELF `STB_LOCAL`/`STB_WEAK`/`STB_GLOBAL` with the
/// binding's `STV_*` (x86-64 ELF writes `STV_HIDDEN` and `STV_PROTECTED` on
/// a definition, ruling OD-X86-ELF-DEFINITION-VISIBILITY-20261027); Mach-O a
/// non-external symbol for a local one, `N_EXT | N_WEAK_DEF` for a weak one,
/// `N_EXT | N_PEXT` for a hidden global and `N_EXT` for a default one; COFF
/// `IMAGE_SYM_CLASS_STATIC` or `IMAGE_SYM_CLASS_EXTERNAL`. A binding the
/// format has no spelling for (Mach-O protected, a COFF weak or hidden
/// definition, a declaration-only linkage) is refused. A module-local
/// definition bound otherwise, or shadowed by another symbol of its name,
/// would let another object's reference or weak definition bind to the
/// module's body ([`CompileError::AotModuleLocalFunctionBindingViolated`]);
/// any other mismatch drops a requested binding
/// ([`CompileError::AotObjectSymbolDisciplineViolated`]).
///
/// The object is read back by the independent readers, not from writer
/// state, so this also covers an object taken from the artifact cache. COFF
/// and RISC-V admit only unreferenced local definitions. The x86-64 ELF and
/// Mach-O paths also read back references through their format-specific
/// module-local binding checks.
fn check_object_function_bindings<'a>(
    target_triple: &str,
    format: BindingCheckFormat,
    object: &[u8],
    module: &trust_ir::Module,
    emitted: impl IntoIterator<Item = &'a str>,
) -> Result<(), CompileError> {
    let emitted: std::collections::BTreeSet<&str> = emitted.into_iter().collect();
    let mut expected: Vec<(&str, FunctionSymbolBinding)> = Vec::new();
    for function in module
        .functions
        .iter()
        .filter(|function| !function.blocks.is_empty() && emitted.contains(function.name.as_str()))
    {
        let binding =
            FunctionSymbolBinding::for_trust_ir_definition(function.linkage, function.visibility)
                .map_err(|reason| CompileError::AotObjectSymbolDisciplineViolated {
                target: target_triple.to_string(),
                detail: format!(
                    "the {format:?} object defines function `{}` (linkage `{}`, visibility \
                         `{}`), which has no definition binding: {reason}",
                    function.name, function.linkage, function.visibility
                ),
            })?;
        expected.push((function.name.as_str(), binding));
    }
    if expected.is_empty() {
        return Ok(());
    }
    let refuse = |function: &str, binding: FunctionSymbolBinding, found: String| {
        let detail = format!(
            "the {format:?} object's symbols for `{function}` are {found}, where its trust-ir \
             linkage and visibility ask for one {} function definition",
            describe_function_binding(binding)
        );
        if binding.linkage() == FunctionSymbolLinkage::Local {
            CompileError::AotModuleLocalFunctionBindingViolated {
                target: target_triple.to_string(),
                function: function.to_string(),
                detail,
            }
        } else {
            CompileError::AotObjectSymbolDisciplineViolated {
                target: target_triple.to_string(),
                detail,
            }
        }
    };
    let unreadable = |error: String| CompileError::AotObjectSymbolDisciplineViolated {
        target: target_triple.to_string(),
        detail: format!("the emitted {format:?} object cannot be read back: {error}"),
    };
    match format {
        BindingCheckFormat::Elf => {
            use crate::elf::constants::{STB_GLOBAL, STB_LOCAL, STB_WEAK, STT_FUNC};
            let records = crate::elf::reparse::read_object_records(object)
                .map_err(|error| unreadable(error.to_string()))?;
            for (function, binding) in &expected {
                let spelled: Vec<_> = records
                    .symbols
                    .iter()
                    .filter(|symbol| symbol.name == *function)
                    .collect();
                let want = match binding.linkage() {
                    FunctionSymbolLinkage::Local => STB_LOCAL,
                    FunctionSymbolLinkage::Weak => STB_WEAK,
                    FunctionSymbolLinkage::Global => STB_GLOBAL,
                };
                let visibility = crate::pipeline::elf_symbol_visibility(binding.visibility());
                let ok = matches!(spelled.as_slice(), [symbol]
                    if symbol.binding == want
                        && symbol.symbol_type == STT_FUNC
                        && symbol.visibility == visibility
                        && symbol.defining_section().is_some());
                if !ok {
                    let found = spelled
                        .iter()
                        .map(|symbol| {
                            format!(
                                "(binding {}, type {}, visibility {}, section index {})",
                                symbol.binding,
                                symbol.symbol_type,
                                symbol.visibility,
                                symbol.section_index
                            )
                        })
                        .collect::<Vec<_>>();
                    return Err(refuse(
                        function,
                        *binding,
                        format!("[{}]", found.join(", ")),
                    ));
                }
            }
        }
        BindingCheckFormat::MachO => {
            let records = crate::macho::reparse::read_object_records(object)
                .map_err(|error| unreadable(error.to_string()))?;
            for (function, binding) in &expected {
                let mangled = format!("_{function}");
                let spelled: Vec<_> = records
                    .symbols
                    .iter()
                    .filter(|symbol| !symbol.is_stab() && symbol.name == mangled)
                    .collect();
                let weak = |symbol: &crate::macho::reparse::MachoSymbolRecord| {
                    symbol.n_desc & MACHO_N_WEAK_DEF != 0
                };
                // Mach-O spells no protected visibility and no visibility on a
                // weak definition: those bindings have no symbol to match.
                let ok = matches!(spelled.as_slice(), [symbol]
                if symbol.is_section_definition()
                    && match (binding.linkage(), binding.visibility()) {
                        (FunctionSymbolLinkage::Local, _) => !symbol.is_external(),
                        (FunctionSymbolLinkage::Weak, trust_ir::Visibility::Default) => {
                            symbol.is_external() && !symbol.is_private_external() && weak(symbol)
                        }
                        (FunctionSymbolLinkage::Global, trust_ir::Visibility::Hidden) => {
                            symbol.is_external() && symbol.is_private_external() && !weak(symbol)
                        }
                        (FunctionSymbolLinkage::Global, trust_ir::Visibility::Default) => {
                            symbol.is_external() && !symbol.is_private_external() && !weak(symbol)
                        }
                        _ => false,
                    });
                if !ok {
                    let found = spelled
                        .iter()
                        .map(|symbol| {
                            format!(
                                "(n_type {:#04x}, n_sect {}, n_desc {:#06x})",
                                symbol.n_type, symbol.n_sect, symbol.n_desc
                            )
                        })
                        .collect::<Vec<_>>();
                    return Err(refuse(
                        function,
                        *binding,
                        format!("[{}]", found.join(", ")),
                    ));
                }
            }
        }
        BindingCheckFormat::Coff => {
            use crate::coff::{IMAGE_SYM_CLASS_EXTERNAL, IMAGE_SYM_CLASS_STATIC};
            let symbols = crate::coff::reparse::read_symbols(object).map_err(unreadable)?;
            for (function, binding) in &expected {
                let spelled: Vec<_> = symbols
                    .iter()
                    .filter(|symbol| symbol.name == *function)
                    .collect();
                let want = match (binding.linkage(), binding.visibility()) {
                    (FunctionSymbolLinkage::Local, _) => Some(IMAGE_SYM_CLASS_STATIC),
                    (FunctionSymbolLinkage::Global, trust_ir::Visibility::Default) => {
                        Some(IMAGE_SYM_CLASS_EXTERNAL)
                    }
                    // The COFF emitter spells no weak definition and no
                    // function visibility.
                    _ => None,
                };
                let ok = matches!((spelled.as_slice(), want), ([symbol], Some(class))
                    if symbol.storage_class == class
                        && symbol.section_number > 0
                        && symbol.typ == crate::coff::IMAGE_SYM_DTYPE_FUNCTION);
                if !ok {
                    let found = spelled
                        .iter()
                        .map(|symbol| {
                            format!(
                                "(storage class {}, section {}, type {:#06x})",
                                symbol.storage_class, symbol.section_number, symbol.typ
                            )
                        })
                        .collect::<Vec<_>>();
                    return Err(refuse(
                        function,
                        *binding,
                        format!("[{}]", found.join(", ")),
                    ));
                }
            }
        }
    }
    Ok(())
}

/// The AArch64 `NOP` word (`0xd503201f`), the only padding the module
/// emitters write between functions (`pad_aarch64_text_for_function_alignment`).
const AARCH64_TEXT_PADDING_WORD: u32 = 0xd503_201f;

/// Mach-O `n_desc` flag of a weak (coalescable) definition (`N_WEAK_DEF`).
const MACHO_N_WEAK_DEF: u16 = 0x0080;

/// The emitted functions of one AArch64 module object, for
/// [`check_aarch64_object_symbol_discipline`]: each function's IR name, in
/// emission order, with the symbol binding its trust-ir linkage and
/// visibility dictate ([`FunctionSymbolBinding::for_trust_ir_definition`],
/// read from the SOURCE module rather than from the writer's symbol plan).
struct ObjectSymbolDisciplineExpectation {
    functions: Vec<(String, FunctionSymbolBinding)>,
}

impl ObjectSymbolDisciplineExpectation {
    /// The expectation for `emitted` (the functions the module emitters place
    /// in the object) compiled from `module`. An emitted function with no
    /// bodied trust-ir definition, or whose linkage is declaration-only or
    /// contradicts its visibility, has no binding to expect and is refused.
    fn for_emitted(
        target_triple: &str,
        module: &trust_ir::Module,
        emitted: &[trust_cg_ir::MachFunction],
    ) -> Result<Self, CompileError> {
        let violation = |detail: String| CompileError::AotObjectSymbolDisciplineViolated {
            target: target_triple.to_string(),
            detail,
        };
        let definitions: HashMap<&str, &trust_ir::Function> = module
            .functions
            .iter()
            .filter(|function| !function.blocks.is_empty())
            .map(|function| (function.name.as_str(), function))
            .collect();
        let functions = emitted
            .iter()
            .map(|function| {
                let source = definitions.get(function.name.as_str()).ok_or_else(|| {
                    violation(format!(
                        "emitted function `{}` has no bodied trust-ir definition to bind",
                        function.name
                    ))
                })?;
                let binding = FunctionSymbolBinding::for_trust_ir_definition(
                    source.linkage,
                    source.visibility,
                )
                .map_err(|reason| {
                    violation(format!(
                        "emitted function `{}` (linkage `{}`, visibility `{}`) has no \
                                 symbol binding: {reason}",
                        function.name, source.linkage, source.visibility
                    ))
                })?;
                Ok((function.name.clone(), binding))
            })
            .collect::<Result<_, CompileError>>()?;
        Ok(Self { functions })
    }
}

/// One instruction section of an object, as [`check_aarch64_object_symbol_discipline`]
/// reads it.
struct DisciplineCodeSection<'o> {
    /// `segname,sectname` (Mach-O) or the section name (ELF).
    label: String,
    /// The section's bytes.
    bytes: std::borrow::Cow<'o, [u8]>,
}

/// One symbol defined in an instruction section.
struct DisciplineTextSymbol {
    /// Index in the object's symbol table.
    index: usize,
    /// The symbol's name as stored.
    name: String,
    /// Index into the code-section list.
    section: usize,
    /// Byte offset inside that section.
    offset: u64,
    /// ELF `st_size`; Mach-O symbols have none.
    size: Option<u64>,
}

/// An object read for [`check_aarch64_object_symbol_discipline`]: its
/// instruction sections, every symbol defined in one of them (debugger
/// entries, ELF section and file symbols aside), and, per expected function,
/// why its one symbol is not the definition the expectation names (`None`
/// when it is).
struct DisciplineObject<'o> {
    code_sections: Vec<DisciplineCodeSection<'o>>,
    text_symbols: Vec<DisciplineTextSymbol>,
    /// The object spelling of each expected function's name (`_f` on Mach-O).
    object_names: Vec<String>,
    /// Per expected function, a refusal reason for its symbol(s), if any.
    definition_faults: Vec<Option<String>>,
}

/// Read a Mach-O object for the symbol-discipline check.
fn discipline_macho_object<'o>(
    object: &'o [u8],
    expected: &ObjectSymbolDisciplineExpectation,
) -> Result<DisciplineObject<'o>, String> {
    let mut records = crate::macho::reparse::read_object_records(object)
        .map_err(|error| format!("the emitted object does not parse as Mach-O: {error}"))?;
    if records.cputype != MACHO_CPU_TYPE_ARM64 {
        return Err(format!(
            "the emitted object's cputype {:#x} is not CPU_TYPE_ARM64",
            records.cputype
        ));
    }
    // Code-section list index by 1-based section ordinal. The bytes move out
    // of the records; their sizes stay for the symbol bounds below.
    let mut code_index = std::collections::BTreeMap::new();
    let mut code_sections = Vec::new();
    for (position, section) in records.sections.iter_mut().enumerate() {
        if macho_section_is_executable(section.flags) {
            if section.data.len() as u64 != section.size {
                return Err(format!(
                    "instruction section {},{} has {} file byte(s) for size {}",
                    section.segname,
                    section.sectname,
                    section.data.len(),
                    section.size
                ));
            }
            code_index.insert(position + 1, code_sections.len());
            code_sections.push(DisciplineCodeSection {
                label: format!("{},{}", section.segname, section.sectname),
                bytes: std::borrow::Cow::Owned(std::mem::take(&mut section.data)),
            });
        }
    }
    let mut text_symbols = Vec::new();
    for (index, symbol) in records.symbols.iter().enumerate() {
        if !symbol.is_section_definition() {
            continue;
        }
        let Some(&code) = code_index.get(&usize::from(symbol.n_sect)) else {
            continue;
        };
        let section = records
            .section(symbol.n_sect)
            .ok_or_else(|| format!("symbol #{index} names a missing section"))?;
        let offset = symbol
            .n_value
            .checked_sub(section.addr)
            .filter(|offset| *offset <= section.size)
            .ok_or_else(|| {
                format!(
                    "symbol #{index} `{}` (n_value {:#x}) lies outside its section {},{}",
                    symbol.name, symbol.n_value, section.segname, section.sectname
                )
            })?;
        text_symbols.push(DisciplineTextSymbol {
            index,
            name: symbol.name.clone(),
            section: code,
            offset,
            size: None,
        });
    }
    // Every symbol (debugger entries aside) by name, built once so the
    // per-function lookups below stay linear in the object.
    let mut spelled: HashMap<&str, Vec<(usize, &crate::macho::reparse::MachoSymbolRecord)>> =
        HashMap::new();
    for (index, symbol) in records.symbols.iter().enumerate() {
        if !symbol.is_stab() {
            spelled
                .entry(symbol.name.as_str())
                .or_default()
                .push((index, symbol));
        }
    }
    let mut object_names = Vec::with_capacity(expected.functions.len());
    let mut definition_faults = Vec::with_capacity(expected.functions.len());
    for (name, binding) in &expected.functions {
        let object_name = format!("_{name}");
        let (external, private_external, weak) = match (binding.linkage(), binding.visibility()) {
            (FunctionSymbolLinkage::Local, _) => (false, false, false),
            (FunctionSymbolLinkage::Global, trust_ir::Visibility::Hidden) => (true, true, false),
            (
                FunctionSymbolLinkage::Global,
                trust_ir::Visibility::Default | trust_ir::Visibility::Protected,
            ) => (true, false, false),
            (FunctionSymbolLinkage::Weak, trust_ir::Visibility::Hidden) => (true, true, true),
            (
                FunctionSymbolLinkage::Weak,
                trust_ir::Visibility::Default | trust_ir::Visibility::Protected,
            ) => (true, false, true),
        };
        let spellings = spelled
            .get(object_name.as_str())
            .map_or(&[][..], Vec::as_slice);
        let fault = match spellings {
            [] => Some("has no symbol".to_string()),
            [(index, symbol)] => {
                let in_code = symbol.is_section_definition()
                    && code_index.contains_key(&usize::from(symbol.n_sect));
                let symbol_weak = symbol.n_desc & MACHO_N_WEAK_DEF != 0;
                (!in_code
                    || symbol.is_external() != external
                    || symbol.is_private_external() != private_external
                    || symbol_weak != weak)
                    .then(|| {
                        format!(
                            "symbol #{index} `{object_name}` has n_type {:#04x}, n_sect {} and \
                             n_desc {:#06x}; its binding ({:?}, visibility `{}`) requires an \
                             N_SECT definition in an instruction section with N_EXT {}, N_PEXT \
                             {} and N_WEAK_DEF {}",
                            symbol.n_type,
                            symbol.n_sect,
                            symbol.n_desc,
                            binding.linkage(),
                            binding.visibility(),
                            if external { "set" } else { "clear" },
                            if private_external { "set" } else { "clear" },
                            if weak { "set" } else { "clear" },
                        )
                    })
            }
            many => Some(format!(
                "is spelled by {} symbols (#{})",
                many.len(),
                many.iter()
                    .map(|(index, _)| index.to_string())
                    .collect::<Vec<_>>()
                    .join(", #")
            )),
        };
        object_names.push(object_name);
        definition_faults.push(fault);
    }
    Ok(DisciplineObject {
        code_sections,
        text_symbols,
        object_names,
        definition_faults,
    })
}

/// Read an ELF object for the symbol-discipline check.
fn discipline_elf_object<'o>(
    object: &'o [u8],
    expected: &ObjectSymbolDisciplineExpectation,
) -> Result<DisciplineObject<'o>, String> {
    use crate::elf::constants::{
        EM_AARCH64, SHF_EXECINSTR, SHT_NOBITS, STB_GLOBAL, STB_LOCAL, STB_WEAK, STT_FILE, STT_FUNC,
        STT_SECTION, STV_DEFAULT, STV_HIDDEN, STV_PROTECTED,
    };
    let records = crate::elf::reparse::read_object_records(object)
        .map_err(|error| format!("the emitted object does not parse as ELF: {error}"))?;
    if records.machine != EM_AARCH64 {
        return Err(format!(
            "the emitted object's e_machine {} is not EM_AARCH64",
            records.machine
        ));
    }
    let mut code_index = std::collections::BTreeMap::new();
    let mut code_sections = Vec::new();
    for (index, section) in records.sections.iter().enumerate() {
        if section.sh_flags & SHF_EXECINSTR == 0 {
            continue;
        }
        if section.sh_type == SHT_NOBITS && section.size != 0 {
            return Err(format!(
                "instruction section {index} `{}` is SHT_NOBITS",
                section.name
            ));
        }
        let bytes = usize::try_from(section.offset)
            .ok()
            .zip(usize::try_from(section.size).ok())
            .and_then(|(start, size)| object.get(start..start.checked_add(size)?))
            .ok_or_else(|| {
                format!(
                    "instruction section {index} `{}` ({} byte(s) at {:#x}) lies outside the \
                     object",
                    section.name, section.size, section.offset
                )
            })?;
        code_index.insert(index, code_sections.len());
        code_sections.push(DisciplineCodeSection {
            label: section.name.clone(),
            bytes: std::borrow::Cow::Borrowed(bytes),
        });
    }
    let mut text_symbols = Vec::new();
    for (index, symbol) in records.symbols.iter().enumerate() {
        if matches!(symbol.symbol_type, STT_SECTION | STT_FILE) {
            continue;
        }
        let Some(&code) = symbol
            .defining_section()
            .and_then(|section| code_index.get(&section))
        else {
            continue;
        };
        if symbol.value > code_sections[code].bytes.len() as u64 {
            return Err(format!(
                "symbol #{index} `{}` (st_value {:#x}) lies outside its section `{}`",
                symbol.name, symbol.value, code_sections[code].label
            ));
        }
        text_symbols.push(DisciplineTextSymbol {
            index,
            name: symbol.name.clone(),
            section: code,
            offset: symbol.value,
            size: Some(symbol.size),
        });
    }
    // Every symbol by name, built once so the per-function lookups below stay
    // linear in the object.
    let mut spelled: HashMap<&str, Vec<(usize, &crate::elf::reparse::ElfSymbolRecord)>> =
        HashMap::new();
    for (index, symbol) in records.symbols.iter().enumerate() {
        spelled
            .entry(symbol.name.as_str())
            .or_default()
            .push((index, symbol));
    }
    let mut object_names = Vec::with_capacity(expected.functions.len());
    let mut definition_faults = Vec::with_capacity(expected.functions.len());
    for (name, binding) in &expected.functions {
        let bind = match binding.linkage() {
            FunctionSymbolLinkage::Local => STB_LOCAL,
            FunctionSymbolLinkage::Global => STB_GLOBAL,
            FunctionSymbolLinkage::Weak => STB_WEAK,
        };
        let visibility = match binding.visibility() {
            trust_ir::Visibility::Default => STV_DEFAULT,
            trust_ir::Visibility::Hidden => STV_HIDDEN,
            trust_ir::Visibility::Protected => STV_PROTECTED,
        };
        let spellings = spelled.get(name.as_str()).map_or(&[][..], Vec::as_slice);
        let fault = match spellings {
            [] => Some("has no symbol".to_string()),
            [(index, symbol)] => {
                let in_code = symbol
                    .defining_section()
                    .is_some_and(|section| code_index.contains_key(&section));
                (!in_code
                    || symbol.symbol_type != STT_FUNC
                    || symbol.binding != bind
                    || symbol.visibility != visibility)
                    .then(|| {
                        format!(
                            "symbol #{index} `{name}` has binding {}, type {}, visibility {} and \
                             section index {}; its binding ({:?}, visibility `{}`) requires an \
                             STT_FUNC definition in an instruction section with binding {bind} \
                             and visibility {visibility}",
                            symbol.binding,
                            symbol.symbol_type,
                            symbol.visibility,
                            symbol.section_index,
                            binding.linkage(),
                            binding.visibility(),
                        )
                    })
            }
            many => Some(format!(
                "is spelled by {} symbols (#{})",
                many.len(),
                many.iter()
                    .map(|(index, _)| index.to_string())
                    .collect::<Vec<_>>()
                    .join(", #")
            )),
        };
        object_names.push(name.clone());
        definition_faults.push(fault);
    }
    Ok(DisciplineObject {
        code_sections,
        text_symbols,
        object_names,
        definition_faults,
    })
}

/// Refuse an AArch64 ELF or Mach-O object whose instruction sections a
/// consumer cannot partition into the module's functions by symbol alone.
///
/// The object is read back by the independent reader of its format, so the
/// check also covers an object taken from the artifact cache. A function's
/// EXTENT is `[its symbol, the next symbol in its section or the section
/// end)`. The object must have:
///
/// 1. for every emitted function, exactly one symbol spelling its name
///    (debugger entries aside), defined in an instruction section, with the
///    binding its trust-ir linkage and visibility dictate: Mach-O `N_EXT`,
///    `N_PEXT` and `N_WEAK_DEF` exactly as the module emitter spells each
///    [`FunctionSymbolBinding`], ELF `STT_FUNC` with the matching `STB_*`
///    and `STV_*` (this re-reads the hidden `N_PEXT` / `STV_HIDDEN`
///    definitions as well as the local ones);
/// 2. no other symbol defined in an instruction section (ELF section and file
///    symbols aside): no label, mapping symbol, data symbol or alias;
/// 3. in every instruction section, symbols at distinct addresses, the first
///    at the section start, so no text precedes every symbol;
/// 4. on ELF, each function's `st_size` nonzero and ending at or before the
///    next symbol (or the section end), with only padding (`NOP`) words after
///    it;
/// 5. when `layout` is given (a fresh object, the layout the emitter
///    reports) and every function symbol lies in one section: each
///    function's symbol at its reported start, every reported body inside
///    the section, and every byte outside the bodies a padding (`NOP`) word.
///
/// Together these put every byte of an instruction section in exactly one
/// function's extent: a veneer, literal pool or stub the emitters added
/// outside every body is refused (rule 2 for a labelled one, rule 3 or 5 for
/// an unlabelled one; the module emitters add none, and jump tables are
/// encoded inside their function's body). Rule 1 is the post-emission
/// binding re-read for EVERY definition (`N_PEXT` hidden ones included); the
/// local-definition rules about relocations stay in
/// [`check_aarch64_module_local_function_binding`].
fn check_aarch64_object_symbol_discipline(
    target_triple: &str,
    object: &[u8],
    expected: &ObjectSymbolDisciplineExpectation,
    layout: Option<&[crate::pipeline::TextFunctionExtent]>,
) -> Result<(), CompileError> {
    let violation = |detail: String| CompileError::AotObjectSymbolDisciplineViolated {
        target: target_triple.to_string(),
        detail,
    };
    let read = if crate::pipeline::target_triple_uses_elf(target_triple) {
        discipline_elf_object(object, expected)
    } else {
        discipline_macho_object(object, expected)
    };
    let DisciplineObject {
        code_sections,
        text_symbols,
        object_names,
        definition_faults,
    } = read.map_err(violation)?;

    // 1. One definition per function, with its binding.
    for ((name, _), fault) in expected.functions.iter().zip(&definition_faults) {
        if let Some(fault) = fault {
            return Err(violation(format!("emitted function `{name}` {fault}")));
        }
    }
    // 2. Every symbol in an instruction section is one of those definitions.
    let function_names: std::collections::BTreeSet<&str> =
        object_names.iter().map(String::as_str).collect();
    if let Some(stray) = text_symbols
        .iter()
        .find(|symbol| !function_names.contains(symbol.name.as_str()))
    {
        return Err(violation(format!(
            "symbol #{} `{}` at offset {:#x} of instruction section `{}` is not the \
             definition of an emitted function",
            stray.index, stray.name, stray.offset, code_sections[stray.section].label
        )));
    }

    let is_padding = |bytes: &[u8]| {
        let (words, rest) = bytes.as_chunks::<4>();
        rest.is_empty()
            && words
                .iter()
                .all(|word| u32::from_le_bytes(*word) == AARCH64_TEXT_PADDING_WORD)
    };
    // 3 and 4, per instruction section (symbols grouped in one pass).
    let mut by_section: Vec<Vec<&DisciplineTextSymbol>> = vec![Vec::new(); code_sections.len()];
    for symbol in &text_symbols {
        by_section[symbol.section].push(symbol);
    }
    for (section, mut symbols) in code_sections.iter().zip(by_section) {
        let size = section.bytes.len() as u64;
        symbols.sort_by_key(|symbol| (symbol.offset, symbol.index));
        if size == 0 {
            continue;
        }
        let Some(first) = symbols.first() else {
            return Err(violation(format!(
                "instruction section `{}` holds {size} byte(s) and no symbol",
                section.label
            )));
        };
        if first.offset != 0 {
            return Err(violation(format!(
                "instruction section `{}` has {:#x} byte(s) of text before its first symbol \
                 `{}`",
                section.label, first.offset, first.name
            )));
        }
        for (position, symbol) in symbols.iter().enumerate() {
            let following = symbols.get(position + 1);
            let next = following.map_or(size, |next| next.offset);
            if next == symbol.offset {
                return Err(violation(match following {
                    Some(other) => format!(
                        "symbols #{} `{}` and #{} `{}` share offset {:#x} of instruction \
                         section `{}`",
                        symbol.index,
                        symbol.name,
                        other.index,
                        other.name,
                        symbol.offset,
                        section.label
                    ),
                    None => format!(
                        "symbol #{} `{}` sits at the end of instruction section `{}`: its extent \
                         is empty",
                        symbol.index, symbol.name, section.label
                    ),
                }));
            }
            let Some(st_size) = symbol.size else {
                continue;
            };
            let end = symbol.offset.saturating_add(st_size);
            if st_size == 0 || end > next {
                return Err(violation(format!(
                    "symbol #{} `{}` at offset {:#x} of instruction section `{}` has st_size \
                     {st_size}, but its extent ends at {next:#x}",
                    symbol.index, symbol.name, symbol.offset, section.label
                )));
            }
            let tail = &section.bytes[end as usize..next as usize];
            if !is_padding(tail) {
                return Err(violation(format!(
                    "bytes {end:#x}..{next:#x} of instruction section `{}`, after `{}`'s \
                     st_size and before the next symbol, are not padding",
                    section.label, symbol.name
                )));
            }
        }
    }

    // 5. The emitter's reported layout, when every function shares one section.
    let Some(layout) = layout else {
        return Ok(());
    };
    let sections: std::collections::BTreeSet<usize> =
        text_symbols.iter().map(|symbol| symbol.section).collect();
    let [code] = sections.into_iter().collect::<Vec<_>>()[..] else {
        return Ok(());
    };
    let section = &code_sections[code];
    let size = section.bytes.len() as u64;
    let offsets: HashMap<&str, u64> = text_symbols
        .iter()
        .map(|symbol| (symbol.name.as_str(), symbol.offset))
        .collect();
    let mut bodies: Vec<(u64, u64)> = Vec::with_capacity(layout.len());
    for extent in layout {
        let object_name = if crate::pipeline::target_triple_uses_elf(target_triple) {
            extent.name.clone()
        } else {
            format!("_{}", extent.name)
        };
        let Some(&offset) = offsets.get(object_name.as_str()) else {
            return Err(violation(format!(
                "the emitter reports a body for `{}` with no symbol in instruction section `{}`",
                extent.name, section.label
            )));
        };
        let end = extent
            .offset
            .checked_add(extent.len)
            .filter(|end| *end <= size);
        if offset != extent.offset || end.is_none() {
            return Err(violation(format!(
                "`{}`'s symbol is at offset {offset:#x} of instruction section `{}` ({size} \
                 byte(s)), but the emitter placed its {}-byte body at {:#x}",
                extent.name, section.label, extent.len, extent.offset
            )));
        }
        bodies.push((extent.offset, extent.offset + extent.len));
    }
    bodies.sort_unstable();
    let mut cursor = 0u64;
    for (start, end) in bodies.into_iter().chain([(size, size)]) {
        if start < cursor {
            return Err(violation(format!(
                "reported bodies overlap at offset {start:#x} of instruction section `{}`",
                section.label
            )));
        }
        if !is_padding(&section.bytes[cursor as usize..start as usize]) {
            return Err(violation(format!(
                "bytes {cursor:#x}..{start:#x} of instruction section `{}` lie outside every \
                 reported body and are not padding",
                section.label
            )));
        }
        cursor = end;
    }
    Ok(())
}

impl Compiler {
    /// Whether this compiler's object path binds references to bodied
    /// Internal/Private functions locally, and so admits direct calls to and
    /// materialized addresses of them. True for AArch64 and x86-64 ELF and
    /// Mach-O objects; see
    /// [`CompileError::AotDirectModuleFunctionBindingUnsupported`].
    pub fn object_binds_module_local_functions(&self) -> bool {
        aot_object_binds_module_local_functions(
            self.config.target,
            &compiler_target_triple(self.target_spec),
        )
    }

    /// Create a new compiler with the given configuration.
    ///
    /// `config.target` names only an architecture. For x86-64 and AArch64 the
    /// OS/ABI -- and with it the object format (Mach-O/ELF/COFF) and calling
    /// convention -- is derived from the HOST
    /// ([`TargetSpec::default_for_architecture`]); the derivation is recorded
    /// as [`TargetSelectionOrigin::HostDerived`] on [`Self::target_selection`]
    /// and on every [`CompilationResult`]. Use [`Self::new_for_target_spec`]
    /// with a full triple for host-independent output.
    pub fn new(config: CompilerConfig) -> Self {
        let target_spec = TargetSpec::default_for_architecture(config.target);
        let target_selection_origin = architecture_only_target_origin(config.target);
        Self {
            config,
            target_spec,
            target_selection_origin,
            jit_validation_resolution: OnceLock::new(),
            x86_jit_codegen_profile: OnceLock::new(),
            aarch64_jit_isa_profile: OnceLock::new(),
            profile_use: None,
            profile_generate_sink: None,
            compile_artifact_cache: None,
            certified_pass_chain: None,
            production_certified_pass_chain: false,
            #[cfg(feature = "verify")]
            production_certified_pass_runs: Vec::new(),
            jit_cert_cache: None,
            codegen_license: CodegenLicensePolicy::default(),
            inline_only_dependencies: Vec::new(),
            stack_limit_external_allowance: 0,
            dialect_legalization_registry: DialectLegalizationRegistry::trust_cg_default(),
        }
    }

    /// Create a compiler with an explicit target OS/ABI spec.
    ///
    /// Specs parsed from architecture aliases keep Trust Codegen's compatibility
    /// defaults. A spelled-out triple is authoritative even when all of its
    /// non-architecture components are `unknown`; concrete triples such as
    /// `x86_64-pc-windows-msvc` are likewise preserved exactly. An alias's
    /// derived OS/ABI is recorded exactly as for [`Self::new`].
    pub fn new_for_target_spec(mut config: CompilerConfig, target_spec: TargetSpec) -> Self {
        let target_selection_origin = if target_spec.has_explicit_os_abi() {
            TargetSelectionOrigin::Explicit
        } else {
            architecture_only_target_origin(target_spec.architecture)
        };
        let target_spec = target_spec.with_default_os_abi();
        config.target = target_spec.architecture;
        Self {
            config,
            target_spec,
            target_selection_origin,
            jit_validation_resolution: OnceLock::new(),
            x86_jit_codegen_profile: OnceLock::new(),
            aarch64_jit_isa_profile: OnceLock::new(),
            profile_use: None,
            profile_generate_sink: None,
            compile_artifact_cache: None,
            certified_pass_chain: None,
            production_certified_pass_chain: false,
            #[cfg(feature = "verify")]
            production_certified_pass_runs: Vec::new(),
            jit_cert_cache: None,
            codegen_license: CodegenLicensePolicy::default(),
            inline_only_dependencies: Vec::new(),
            stack_limit_external_allowance: 0,
            dialect_legalization_registry: DialectLegalizationRegistry::trust_cg_default(),
        }
    }

    /// Attach a decoded `.profdata` artifact for profile-use mode.
    pub fn with_profile_use(mut self, profile: trust_cg_opt::pgo::ProfData) -> Self {
        self.profile_use = Some(profile);
        self
    }

    /// Enable AOT PGO profile-generate mode: inject a per-basic-block counter
    /// increment into every compiled function, define the module-level
    /// `__tcg_pgo_counters` (zeroed u64 array) and `__tcg_pgo_nsites`
    /// (u64 LE site count) globals in the emitted object, and record every
    /// `(function, block_id, counter_index)` site into `sink` in slot order.
    ///
    /// AArch64 AOT objects only — [`Compiler::compile`] fails closed on any
    /// other target rather than silently emitting an uninstrumented object.
    pub fn with_profile_generate(
        mut self,
        sink: std::sync::Arc<std::sync::Mutex<trust_cg_opt::pgo::CounterMap>>,
    ) -> Self {
        self.profile_generate_sink = Some(sink);
        self
    }

    /// Replace the dialect legalization registry every compile entry applies
    /// before the adapter. Dialects, ops and nominal types the registry does
    /// not declare are refused by exact name; its digest is recorded in every
    /// legalization report, and the legalized module (not the registry) keys
    /// the compile-artifact cache.
    pub fn with_dialect_legalization_registry(
        mut self,
        registry: DialectLegalizationRegistry,
    ) -> Self {
        self.dialect_legalization_registry = registry;
        self
    }

    /// The dialect legalization registry this compiler applies.
    pub fn dialect_legalization_registry(&self) -> &DialectLegalizationRegistry {
        &self.dialect_legalization_registry
    }

    /// Legalize `module`'s dialect constructs for this compile's target under
    /// `proof_required` (see [`crate::dialect_legalization::legalize_module`]).
    fn legalize_dialects<'m>(
        &self,
        module: &'m trust_ir::Module,
        proof_required: bool,
    ) -> Result<Legalized<'m>, DialectPipelineError> {
        legalize_module(
            module,
            &self.dialect_legalization_registry,
            LegalizationOptions::new(self.config.target, proof_required),
        )
    }

    /// Attach a production compile artifact cache for object-code emission.
    pub fn with_compile_artifact_cache(mut self, cache: CompileArtifactCacheConfig) -> Self {
        self.compile_artifact_cache = Some(cache);
        self
    }

    /// Attach an explicit JIT certificate cache (JIT-5). Used by tests to
    /// observe isolated hit/miss stats; production callers leave it unset and
    /// share the process-global cache.
    pub fn with_jit_cert_cache(
        mut self,
        cache: std::sync::Arc<crate::jit_cert::JitCertCache>,
    ) -> Self {
        self.jit_cert_cache = Some(cache);
        self
    }

    /// The JIT certificate cache this compiler uses: the injected instance if
    /// present, otherwise the process-global cache.
    pub fn jit_cert_cache(&self) -> std::sync::Arc<crate::jit_cert::JitCertCache> {
        self.jit_cert_cache
            .clone()
            .unwrap_or_else(crate::jit_cert::JitCertCache::global)
    }

    /// Attach an already checker-validated certified pass chain to future
    /// [`CompilationResult`] values produced by this compiler.
    #[cfg(feature = "verify")]
    pub fn with_certified_pass_chain(
        mut self,
        chain: trust_cg_verify::CertifiedPassChain,
    ) -> Result<Self, trust_cg_verify::CertifiedPassChainError> {
        self.certified_pass_chain = Some(CertifiedPassChainAttachment::from_checked_chain(&chain)?);
        Ok(self)
    }

    /// Check caller-supplied certified pass entries and attach the validated
    /// chain to future [`CompilationResult`] values produced by this compiler.
    #[cfg(feature = "verify")]
    pub fn with_checked_certified_pass_entries<I>(
        self,
        entries: I,
    ) -> Result<Self, trust_cg_verify::CertifiedPassChainError>
    where
        I: IntoIterator<Item = trust_cg_verify::CertifiedPassChainEntry>,
    {
        let chain = trust_cg_verify::CertifiedPassChain::from_entries(entries)?;
        self.with_certified_pass_chain(chain)
    }

    /// Enable the non-default production certified-pass execution path.
    ///
    /// When enabled and the caller has not supplied a certified pass chain,
    /// the compiler runs certified pass wrappers, converts their neutral
    /// run records into checker-backed chain entries, validates the chain, and
    /// attaches it to [`CompilationResult`].
    #[cfg(feature = "verify")]
    pub fn with_production_certified_pass_chain(mut self) -> Self {
        self.production_certified_pass_chain = true;
        self
    }

    /// Add certified run records emitted by production paths outside the
    /// machine-IR optimization pipeline, such as VNN tensor fusion emitters.
    ///
    /// The records are appended after the opt-pipeline records and are checked
    /// through the same fail-closed production chain attachment path.
    #[cfg(feature = "verify")]
    pub fn with_additional_production_certified_pass_runs<I>(mut self, runs: I) -> Self
    where
        I: IntoIterator<Item = trust_cg_opt::CertifiedPassRunRecord>,
    {
        self.production_certified_pass_chain = true;
        self.production_certified_pass_runs.extend(runs);
        self
    }

    /// Create a compiler with the legacy default O2 object-code configuration.
    ///
    /// This currently targets [`Target::Aarch64`] for compatibility. Use
    /// [`Compiler::for_host`] for in-process JIT compilation.
    pub fn default_o2() -> Self {
        Self::new(CompilerConfig::default())
    }

    /// Create a compiler with the low-latency JIT profile for `target`.
    pub fn jit_fast(target: Target) -> Self {
        Self::new(CompilerConfig::jit_fast(target))
    }

    /// Create a compiler with the host-safe low-latency JIT profile.
    ///
    /// The returned compiler uses [`Target::host`] rather than the legacy
    /// [`CompilerConfig::default`] target. If the current host backend is not
    /// wired through [`Compiler::compile_module_to_jit`] yet, compilation will
    /// fail with [`CompileError::JitTargetUnsupported`] instead of emitting
    /// executable memory for a different ISA.
    pub fn for_host() -> Self {
        Self::new(CompilerConfig::for_host_jit())
    }

    /// Returns the compiler's current configuration.
    pub fn config(&self) -> &CompilerConfig {
        &self.config
    }

    /// Set the trust-ir v41 codegen-license policy this compiler enforces.
    ///
    /// The default recognizes `clean-kernel-tv` — evidence-bound: a body
    /// wearing it compiles only with its kernel-replayed TranslationValidation
    /// certificate (WS7.5(b)) — and REFUSES claim-less (`body_gate: None`)
    /// bodies (DG-73); `Ungated` is refused under every policy.
    /// The policy is not part of [`CompilerConfig`] (and so not of any cache
    /// identity) because enforcement runs BEFORE every cache lookup — at the
    /// top of [`Compiler::compile`], of the JIT entry, and of
    /// [`Compiler::plan_core_module_for_jit_compilation`] (Core admission
    /// lowers under the default floor; the plan re-decides under this policy).
    #[must_use]
    pub fn with_codegen_license(mut self, license: CodegenLicensePolicy) -> Self {
        self.codegen_license = license;
        self
    }

    /// The codegen-license policy this compiler enforces.
    pub fn codegen_license(&self) -> &CodegenLicensePolicy {
        &self.codegen_license
    }

    /// Supply the dependency modules the compiled module's inline-only
    /// (`AvailableExternally`) bodies may be authenticated against
    /// ([`crate::lir_module_prep::InlineOnlyAuthority`]): a body is
    /// authenticated when an import row of the module that
    /// `Module::verify_import` accepts against one of them names a dependency
    /// exporting an equal definition. An authenticated body's premise is
    /// discharged (`InlineOnlyBodyEvidence::authenticated`), and only such a
    /// body is spliced by a compile that makes a proof claim. Supplying
    /// dependencies disables compile-artifact reuse for this compiler, since
    /// they are not part of any artifact key.
    pub fn with_inline_only_dependencies(
        mut self,
        dependencies: Vec<std::sync::Arc<trust_ir::Module>>,
    ) -> Self {
        self.inline_only_dependencies = dependencies;
        self
    }

    /// Declare the bytes any call leaving the module may use below its
    /// caller's SP, for the U10 module reserve bound
    /// ([`StackLimitModuleReport::bound`]). It is reported as the bound's
    /// external assumption and changes no emitted byte.
    #[must_use]
    pub fn with_stack_limit_external_allowance(mut self, bytes: u64) -> Self {
        self.stack_limit_external_allowance = bytes;
        self
    }

    /// Returns the effective target spec used for OS/ABI-sensitive codegen.
    pub fn target_spec(&self) -> TargetSpec {
        self.target_spec
    }

    /// The AArch64 optional-ISA profile governing object emission: the
    /// explicit [`CompilerConfig::aarch64_isa_profile`] when configured,
    /// otherwise the target contract ([`AArch64IsaProfile::for_aot_target`]).
    /// In-process JIT compilation never uses it (see
    /// [`Self::effective_aarch64_jit_isa_profile`]).
    pub fn aarch64_object_isa_profile(&self) -> AArch64IsaProfile {
        self.config
            .aarch64_isa_profile
            .unwrap_or_else(|| AArch64IsaProfile::for_aot_target(self.target_spec))
    }

    /// Refuse explicit AArch64 object policies on a non-AArch64 target.
    fn ensure_aarch64_isa_profile_applies(&self) -> Result<(), CompileError> {
        if self.config.aarch64_force_frame_pointers && self.config.target != Target::Aarch64 {
            return Err(CompileError::Aarch64FramePointersUnsupported {
                target: compiler_target_triple(self.target_spec),
                reason: "the explicit frame policy is modeled only for AArch64 objects",
            });
        }
        match self.config.aarch64_isa_profile {
            Some(profile) if self.config.target != Target::Aarch64 => {
                Err(CompileError::Aarch64IsaProfileUnsupported {
                    target: compiler_target_triple(self.target_spec),
                    profile,
                    reason: "an AArch64 ISA profile admits AArch64 instructions only",
                })
            }
            _ => Ok(()),
        }
    }

    /// Refuse the non-unwinding exception-frame policy on a target whose LSDA
    /// emission does not model it. Only the AArch64 pipeline omits the
    /// propagation filler for such frames; silently keeping it elsewhere
    /// would let an exception search past a frame that must stop it.
    fn ensure_eh_frames_cannot_unwind_applies(&self) -> Result<(), CompileError> {
        if self.config.eh_frames_cannot_unwind && self.config.target != Target::Aarch64 {
            return Err(CompileError::EhFramesCannotUnwindUnsupported {
                target: compiler_target_triple(self.target_spec),
                reason: "only the AArch64 LSDA emitter models non-unwinding exception frames",
            });
        }
        Ok(())
    }

    /// The effective target triple (the one handed to the lowering pipeline)
    /// and whether it was named by the caller or derived from the host.
    pub fn target_selection(&self) -> CompilerTargetSelection {
        CompilerTargetSelection {
            triple: compiler_target_triple(self.target_spec),
            origin: self.target_selection_origin,
        }
    }

    /// Host-dependent x86 JIT policy captured once on first demand.
    /// Compile-service identities bind this exact snapshot, and object-only
    /// compilers avoid feature probing and legacy environment reads entirely.
    pub(crate) fn effective_x86_jit_codegen_profile(&self) -> EffectiveX86JitCodegenProfile {
        *self
            .x86_jit_codegen_profile
            .get_or_init(|| effective_x86_jit_codegen_profile(&self.config))
    }

    /// Host-dependent AArch64 ISA policy captured once on first JIT demand.
    ///
    /// Execution and reusable-artifact identity consumers must use this exact
    /// snapshot. Object-only compilers stay on the generic baseline and do not
    /// probe the host.
    pub(crate) fn effective_aarch64_jit_isa_profile(&self) -> AArch64IsaProfile {
        *self.aarch64_jit_isa_profile.get_or_init(|| {
            if self.config.target == Target::Aarch64 {
                AArch64IsaProfile::for_host_jit()
            } else {
                AArch64IsaProfile::BASELINE
            }
        })
    }

    /// Validation authority captured once on first demand.
    ///
    /// The public `CompilerConfig` resolver remains available for callers that
    /// intentionally take a fresh ambient snapshot. A `Compiler` itself uses
    /// one immutable resolution for identity, validation, and execution.
    pub(crate) fn resolved_jit_validation_mode(&self) -> Result<JitValidationMode, CompileError> {
        let captured = self
            .jit_validation_resolution
            .get_or_init(|| self.config.jit_validation_resolution());
        let resolution = (*captured)
            .map_err(|target| CompileError::JitUncertifiedBytesRequireOptIn { target })?;
        if let Some(via_env) = resolution.warning_via_env {
            warn_jit_unchecked_engaged(self.config.target, via_env);
        }
        Ok(resolution.mode)
    }

    /// Side-effect-free validation authority captured by this compiler.
    /// Identity and provenance code use this accessor; only an execution
    /// attempt emits the loud Unchecked warning.
    pub(crate) fn captured_jit_validation_mode(&self) -> Result<JitValidationMode, CompileError> {
        let captured = self
            .jit_validation_resolution
            .get_or_init(|| self.config.jit_validation_resolution());
        (*captured)
            .map(|resolution| resolution.mode)
            .map_err(|target| CompileError::JitUncertifiedBytesRequireOptIn { target })
    }

    fn compile_artifact_cache_context(
        &self,
        source_module: &trust_ir::Module,
        lowered_module: &trust_ir::Module,
    ) -> Result<Option<CompileArtifactCacheContext>, CompileError> {
        let Some(cache_config) = &self.compile_artifact_cache else {
            return Ok(None);
        };
        // Supplied inline-only dependencies decide which bodies a proof
        // claim may splice, and no artifact key names them: never reuse.
        if !self.inline_only_dependencies.is_empty() {
            return Ok(None);
        }
        // A linked compile (WS7.9) admits cross-crate inheritances the floor
        // otherwise refuses inside the adapter, after any cache lookup. No
        // artifact key names the authentication, so an object published here
        // could later be served to an unlinked compile of the same module:
        // never reuse or publish.
        if self.codegen_license.authenticated_imports().is_some() {
            return Ok(None);
        }

        // The RISC-V compile path does not yet consume or publish an object
        // cache context. Do not encode TMBC, hash modules, or serialize policy
        // for a context that dispatch will immediately discard. Receipt-backed
        // RISC-V replay must wire the consumer before removing this bypass.
        if self.config.target == Target::Riscv64 {
            return Ok(None);
        }

        // Profile-generate compilation has an observable side effect beyond
        // object bytes: it must populate the caller-owned CounterMap sink. A
        // native-object hit cannot replay that side effect today, so both
        // lookup and publication remain ineligible in generate mode.
        if self.profile_generate_sink.is_some() {
            return Ok(None);
        }

        // Proof policy does not weaken compiler identity. Package-version and
        // build-host defaults can collide across same-version TrustCG source
        // revisions, so every persistent replay requires source-lock and
        // pinned-toolchain identities.
        if !cache_config
            .dependency_identity
            .is_artifact_reuse_eligible()
        {
            return Ok(None);
        }

        // A cache admission policy is not permission to expand compilation
        // work. Proof-bearing tiers are eligible only when the caller already
        // requested proof generation explicitly through CompilerConfig.
        if cache_config.proof_policy.requires_proof_bundle_digest() && !self.config.emit_proofs {
            return Ok(None);
        }

        // Legacy TCG_*/TRUST_CG_* switches are not represented by
        // `CompilerConfig`, yet many of them change lowering, optimization,
        // regalloc, proof policy, or layout. Reusing an object keyed only by
        // the explicit config in that state can return bytes produced under a
        // different compiler policy. Unknown controls therefore disable reuse
        // automatically until they migrate into an explicit, keyed policy.
        let Some(reuse_permit) = trust_cg_process_env::artifact_reuse_permit() else {
            return Ok(None);
        };

        // A module still carrying a construct ahead of its trust-ir wire tag
        // has no tMBC image and therefore no cache key. The cache is reuse,
        // not admission: such a module compiles, but is never looked up or
        // published.
        if trust_ir_build::wire_identity_blocker(source_module).is_some()
            || trust_ir_build::wire_identity_blocker(lowered_module).is_some()
        {
            return Ok(None);
        }

        let source_bytes = crate::pipeline::encode_tmbc(source_module)?;
        let source_module_sha256 = sha256_digest(&source_bytes);
        let lowered_module_sha256 = if std::ptr::eq(source_module, lowered_module) {
            source_module_sha256.clone()
        } else {
            sha256_digest(&crate::pipeline::encode_tmbc(lowered_module)?)
        };
        let profile_use_sha256 = compiler_profile_use_sha256(self.profile_use.as_ref())?;
        let codegen_options_sha256 =
            compiler_codegen_options_sha256(&self.config, self.target_spec, &profile_use_sha256)?;
        let target_facts_sha256 =
            compiler_target_facts_sha256(self.config.target, self.target_spec)?;
        let key = CompileArtifactCacheKey::new(
            source_module_sha256,
            lowered_module_sha256,
            codegen_options_sha256,
            self.config.target,
            compiler_target_triple(self.target_spec),
            target_facts_sha256,
            cache_config.proof_policy,
            cache_config.dependency_identity.clone(),
        )
        .with_profile_use_sha256(profile_use_sha256);

        Ok(Some(CompileArtifactCacheContext {
            cache: cache_config.backend(),
            key,
            boundary: cache_config.boundary,
            reuse_permit,
        }))
    }

    /// Whether this compile makes a proof claim about its output: every
    /// emitted function must carry promotable proof evidence. It is
    /// `emit_proofs`. Besides the promotion checks it gates, it is the AOT
    /// seam's input to ruling OD-225: a compile that claims proofs runs
    /// neither shared LIR pass (`lir_module_prep::unvalidated_lir_passes_run`).
    fn requires_verified_proof_promotion(&self) -> bool {
        self.config.emit_proofs
    }

    /// A proof-promotion refusal for missing or unverified evidence. When the
    /// function-verification request that evidence came from had no AY bound
    /// (this build records an AY, the identity rule admitted none to that
    /// request), every solver-backed obligation it held went unproved for that
    /// reason alone, so the refusal also carries `ay_refusal_note`: that
    /// request's own `TCG-AY-IDENTITY-*` refusal
    /// ([`ProofCertificate::ay_refusal_note`],
    /// [`trust_cg_verify::FunctionVerificationRequest::ay_refusal_note`]). An
    /// installed AY that cannot run (for example beneath a group-writable
    /// cache directory) must not read as an ordinary proof gap.
    ///
    /// Nothing is resolved here: a fresh resolution describes the cache at
    /// the time of the refusal, and with a cache path another user can
    /// re-point it disagreed with the request's in both directions (no note
    /// on a request that had no AY; "no AY is admitted" for a request AY ran
    /// for; X-HOST-P13 fourth closure audit). Evidence no request produced,
    /// and a build that records no AY (stock Rust), carry no note, and the
    /// reason is unchanged. It changes no verdict; checks that pin a reason
    /// exactly compare [`trust_cg_verify::ay_bridge::without_solver_refusal_note`].
    fn unproved_evidence_rejected(
        &self,
        reason: String,
        ay_refusal_note: Option<&str>,
    ) -> CompileError {
        CompileError::ProofPromotionRejected {
            target: self.config.target,
            reason: trust_cg_verify::ay_bridge::with_request_refusal_note(reason, ay_refusal_note),
        }
    }

    fn ensure_proofs_promotable(
        &self,
        proofs: Option<&[ProofCertificate]>,
    ) -> Result<(), CompileError> {
        if !self.requires_verified_proof_promotion() {
            return Ok(());
        }
        // L09-P3 route tests only: reach the publication checks that follow.
        #[cfg(test)]
        if crate::composed_transition::test_hooks::promotion_waived() {
            return Ok(());
        }

        let proofs = proofs.ok_or_else(|| CompileError::ProofPromotionRejected {
            target: self.config.target,
            reason: "proof promotion requires public proof reports, but none were emitted"
                .to_owned(),
        })?;

        if proofs.is_empty() {
            return Err(CompileError::ProofPromotionRejected {
                target: self.config.target,
                reason: "proof promotion requires at least one public proof report".to_owned(),
            });
        }

        if let Some(cert) = proofs
            .iter()
            .find(|cert| crate::proof_evidence::certificate_blocks_promotion(cert))
        {
            let status = proof_status_label(cert);
            return Err(self.unproved_evidence_rejected(
                format!(
                    "{status} proof entry {} in {}: {}",
                    cert.rule_name, cert.function_name, cert.strength
                ),
                cert.ay_refusal_note.as_deref(),
            ));
        }

        Ok(())
    }

    /// JIT-5 unconditional fail-closed promotion gate for a verifying JIT mode.
    ///
    /// Unlike [`Self::ensure_proofs_promotable`] (which follows the explicit
    /// object compile proof request), this always rejects the compile when the
    /// certificate set carries no discharged evidence or contains any unverified
    /// entry — so `CachedVerified`/`AlwaysVerify` publish only functions with
    /// proof-grade semantic evidence even
    /// when no compile-artifact cache is attached.
    ///
    /// "No discharged evidence" is [`proof_evidence::bundle_has_discharge_evidence`],
    /// not `is_empty`: a named structural exemption
    /// ([`CALL_ONLY_BODY_CATEGORY`]) records that a body had NOTHING to
    /// discharge, and a [`proof_evidence::COVERED_ELSEWHERE_CATEGORY`] row that
    /// its obligation rests elsewhere, so a stream of nothing but those is the
    /// same absence of evidence as an empty stream and must fail the same way.
    ///
    /// `functions` is the per-function verdict of the same stream: a function
    /// whose own certificates show no verified semantics is refused even when
    /// another function's evidence passed the checks above.
    ///
    /// The note a refusal appends is the one its rows carry, read here and
    /// nowhere else: every row of one x86-64 JIT module came from the one
    /// function-verification request of that module and carries its note
    /// (`carry_request_ay_refusal_note`, cache hits included), so the first
    /// row with a note names that request. Both refusals that name no single
    /// row (no discharged evidence; an unverified function) take it from the
    /// rows, so a caller cannot pass one without the other and a unit test of
    /// this function pins both (LD-66, sixth closure audit).
    // Reached only from the verifying JIT cert path (feature = "verify").
    #[cfg_attr(not(feature = "verify"), allow(dead_code))]
    fn gate_jit_proofs_promotable(
        &self,
        proofs: &[ProofCertificate],
        functions: &[JitFunctionValidation],
    ) -> Result<(), CompileError> {
        let request_note = proofs
            .iter()
            .find_map(|cert| cert.ay_refusal_note.as_deref());
        if !crate::proof_evidence::bundle_has_discharge_evidence(proofs) {
            let how = if proofs.is_empty() {
                "the stream is empty".to_owned()
            } else {
                format!(
                    "{} certificate(s) present, all of them named structural exemptions or \
                     covered-elsewhere rows, none a discharged obligation",
                    proofs.len()
                )
            };
            return Err(self.unproved_evidence_rejected(
                format!(
                    "JIT validation requires at least one verified proof report, but the \
                     emitted stream produced none (every function needs non-vacuous evidence); \
                     {how}"
                ),
                request_note,
            ));
        }
        // A verifying JIT mode's per-function verdict and its publication
        // decision must agree, regardless of host solver/checker availability.
        if let Some(cert) = proofs.iter().find(|cert| !cert.verified) {
            let status = proof_status_label(cert);
            return Err(self.unproved_evidence_rejected(
                format!(
                    "{status} proof entry {} in {} would publish a JIT function without required evidence: {}",
                    cert.rule_name, cert.function_name, cert.strength
                ),
                cert.ay_refusal_note.as_deref(),
            ));
        }
        if let Some(function) = functions.iter().find(|function| !function.verified) {
            return Err(self.unproved_evidence_rejected(
                format!(
                    "JIT validation requires non-vacuous proof evidence for every \
                     function; `{}` produced no verified per-function evidence",
                    function.function
                ),
                request_note,
            ));
        }
        Ok(())
    }

    /// JIT-5: certify each x86-64 JIT function under the resolved validation
    /// mode, consulting the content-addressed certificate cache on
    /// `CachedVerified`, and fail-close the compile before publish if any
    /// executed byte would be uncertified.
    ///
    /// Returns `(proofs, per_function_validation)`. `proofs` is `None` only on
    /// the Unchecked path (no certs). The per-function validation records feed
    /// [`JitValidationProvenance`].
    fn x86_jit_certify_functions(
        &self,
        validation_mode: JitValidationMode,
        isel_funcs: &[trust_cg_lower::x86_64_isel::X86ISelFunction],
        lir_functions: &[(trust_cg_lower::Function, trust_cg_lower::ProofContext)],
        normalized_module_code: &[u8],
        per_func_emitted_ranges: &[std::ops::Range<usize>],
        per_func_symbolic_fixup_manifests: &[Vec<u8>],
        module_definitions: &trust_cg_verify::X86ModuleDefinitions,
    ) -> Result<(Option<Vec<ProofCertificate>>, Vec<JitFunctionValidation>), CompileError> {
        let must_verify = validation_mode.requires_jit_verification();
        // Preserve an explicit CompilerConfig proof request even when the JIT
        // validation mode itself does not require verification.
        let explicit_proof_request = self.requires_verified_proof_promotion();

        if !must_verify && !explicit_proof_request {
            // Unchecked (dev-only) or a non-verifying legacy path: no certs.
            return Ok((None, Vec::new()));
        }

        if lir_functions.len() != isel_funcs.len()
            || per_func_emitted_ranges.len() != isel_funcs.len()
            || per_func_symbolic_fixup_manifests.len() != isel_funcs.len()
        {
            return Err(CompileError::Jit(
                crate::jit::JitError::CertificationInputCountMismatch {
                    functions: isel_funcs.len(),
                    lir_functions: lir_functions.len(),
                    ranges: per_func_emitted_ranges.len(),
                    fixup_manifests: per_func_symbolic_fixup_manifests.len(),
                },
            ));
        }

        // Test-only: record the exact certification inputs (normalized bytes,
        // ranges, symbolic fixup manifests) so tests can pin what the real JIT
        // encode path hands this boundary.
        #[cfg(all(test, feature = "verify"))]
        x86_envelope_jit_tests::record_certify_inputs(
            isel_funcs,
            lir_functions,
            normalized_module_code,
            per_func_emitted_ranges,
            per_func_symbolic_fixup_manifests,
        );

        #[cfg(not(feature = "verify"))]
        {
            // Verifying modes are unreachable without the `verify` feature —
            // `JitValidationMode::ensure_supported` fails closed in
            // `to_jit_config` — and explicit promotion cannot produce proofs here.
            let _ = (
                isel_funcs,
                lir_functions,
                normalized_module_code,
                per_func_emitted_ranges,
                per_func_symbolic_fixup_manifests,
                module_definitions,
            );
            Err(CompileError::ProofsUnsupportedForTarget {
                target: self.config.target,
            })
        }

        #[cfg(feature = "verify")]
        {
            let cache = self.jit_cert_cache();
            // Only CachedVerified may satisfy the obligation from cache;
            // AlwaysVerify and the legacy path always re-discharge.
            let verification_policy = X86JitVerificationPolicy::capture();
            let verification_request = shared_x86_64_function_verifier()
                .capture_request_with_mode(verification_policy.provenance_xcheck);
            // The request's one AY resolution, carried into every refusal over
            // its evidence (never resolved again at the refusal).
            let request_ay_refusal_note = verification_request.ay_refusal_note();
            let cache_prerequisites_met = must_verify
                && validation_mode.uses_certificate_cache()
                && cache.is_enabled()
                && crate::jit_cert::jit_cert_cache_allowed_for_request()
                && verification_policy.outer_cache_allowed;
            // Actual discharges and every per-function key share this owned
            // request. Missing identity permits fresh verification, never reuse.
            // The config fingerprint exists only paired with that authority, so
            // no cache key can be formed without it.
            let cache_identity = cache_prerequisites_met
                .then(|| verification_request.reuse_identity())
                .flatten()
                .map(|verification_authority_id| {
                    (
                        x86_jit_config_fingerprint(
                            &self.config,
                            validation_mode,
                            verification_policy,
                        ),
                        verification_authority_id,
                    )
                });

            // Every certificate this lane builds takes the ENC-3 backing the
            // policy captured, through this one conversion. (The cached branch
            // below is reachable only when that backing gates the compile:
            // `outer_cache_allowed`.)
            let certificates_of =
                |report: &trust_cg_verify::FunctionVerificationReport,
                 lir_func: &trust_cg_lower::Function| {
                    proof_certificates_from_x86_64_report(
                        report,
                        Some(lir_func),
                        verification_policy.enc3,
                    )
                };
            let mut all_certs: Vec<ProofCertificate> = Vec::new();
            let mut per_fn: Vec<JitFunctionValidation> = Vec::with_capacity(isel_funcs.len());
            // The x86-64 JIT selects every function under the host ABI; the
            // verifier binds that convention into each report and digest.
            let call_abi = x86_host_jit_abi();
            let source_bound_abi = Some(x86_source_bound_abi(call_abi));

            // TV-2: `isel_funcs` is built 1:1 in `lir_functions` order, so the
            // zip pairs each ISel function with the LIR function its ISel
            // consumed; the verifier additionally name-guards the pairing.
            for (i, (func, (lir_func, _))) in
                isel_funcs.iter().zip(lir_functions.iter()).enumerate()
            {
                let range = &per_func_emitted_ranges[i];
                let code_bytes = normalized_module_code.get(range.clone()).ok_or_else(|| {
                    CompileError::Jit(crate::jit::JitError::InvalidFunctionRange {
                        function: func.name.clone(),
                        start: range.start as u64,
                        end: range.end as u64,
                        code_len: normalized_module_code.len(),
                    })
                })?;
                let manifest = per_func_symbolic_fixup_manifests[i].as_slice();
                let verifier_input = crate::jit_cert::x86_verifier_input_digest(
                    func,
                    lir_func,
                    source_bound_abi,
                    Some(module_definitions),
                )?;
                let verifier_input_sha256 = crate::jit_cert::digest_hex(&verifier_input);
                let cache_key = cache_identity.as_ref().map(|(config_fp, authority_id)| {
                    crate::jit_cert::JitCertCacheKey::new_for_verified_function_digest(
                        code_bytes,
                        &verifier_input,
                        manifest,
                        config_fp,
                        authority_id,
                    )
                });
                let (fn_certs, verified, cache_hit) = if let Some(key) = cache_key {
                    if let Some(v) = cache.peek(&key).filter(|value| {
                        value.verification_report.as_ref().is_some_and(|report| {
                            report.reusable_for(&verification_request)
                                && report.matches_x86_input_in_module(
                                    func,
                                    Some(lir_func),
                                    source_bound_abi,
                                    Some(module_definitions),
                                )
                        }) && x86_jit_cached_envelope_admits(
                            value.x86_envelope_report.as_ref(),
                            &verification_request,
                            lir_func,
                            &func.name,
                            code_bytes,
                            manifest,
                            source_bound_abi,
                        )
                    }) {
                        // Warm hit: the key binds the normalized emitted bytes,
                        // complete verifier input, symbolic fixups, and typed
                        // policy. Reuse WITHOUT re-running the verifier.
                        cache.record_hit();
                        let certs = v.x86_proof_certs.clone();
                        let verified = x86_certificates_show_verified_semantics(&certs);
                        (certs, verified, true)
                    } else {
                        // Miss: full verification, then populate. Never skips.
                        cache.record_miss();
                        let report = generate_x86_64_captured_proof_report(
                            func,
                            Some(lir_func),
                            call_abi,
                            module_definitions,
                            &verification_request,
                        );
                        let mut certs = certificates_of(report.report(), lir_func);
                        let envelope = x86_jit_envelope_report(
                            lir_func,
                            &func.name,
                            code_bytes,
                            manifest,
                            source_bound_abi,
                            &verification_request,
                        );
                        certs.extend(
                            envelope
                                .as_ref()
                                .map(x86_64_abi_envelope_certificates)
                                .unwrap_or_default(),
                        );
                        let verified = x86_certificates_show_verified_semantics(&certs);
                        if verified
                            && report.reusable_for(&verification_request)
                            && report.matches_x86_input_in_module(
                                func,
                                Some(lir_func),
                                source_bound_abi,
                                Some(module_definitions),
                            )
                            && x86_jit_envelope_is_storable(
                                envelope.as_ref(),
                                &verification_request,
                            )
                        {
                            cache.store(
                                key,
                                crate::jit_cert::CachedFunctionVerdict {
                                    x86_proof_certs: certs.clone(),
                                    aarch64_cert: None,
                                    verification_report: Some(report),
                                    x86_envelope_report: envelope,
                                },
                            );
                        }
                        (certs, verified, false)
                    }
                } else {
                    // AlwaysVerify / explicit CompilerConfig proof request:
                    // full verify, never cached.
                    cache.record_uncached_verifier_run();
                    let report = generate_x86_64_captured_proof_report(
                        func,
                        Some(lir_func),
                        call_abi,
                        module_definitions,
                        &verification_request,
                    );
                    let mut certs = certificates_of(report.report(), lir_func);
                    // The envelope is judged only in a verifying JIT mode. An
                    // explicit proof request under an unchecked mode keeps the
                    // certificates it had.
                    if must_verify {
                        certs.extend(
                            x86_jit_envelope_report(
                                lir_func,
                                &func.name,
                                code_bytes,
                                manifest,
                                source_bound_abi,
                                &verification_request,
                            )
                            .as_ref()
                            .map(x86_64_abi_envelope_certificates)
                            .unwrap_or_default(),
                        );
                    }
                    let verified = x86_certificates_show_verified_semantics(&certs);
                    (certs, verified, false)
                };

                per_fn.push(JitFunctionValidation {
                    function: func.name.clone(),
                    verified,
                    verifier_input_sha256,
                    // Filled once from the exact sealed, post-relocation range
                    // after publication; hashing normalized bytes here would be
                    // duplicate work and report the wrong integrity domain.
                    bytes_sha256: String::new(),
                    cache_hit,
                });
                // Every certificate of this function, a cache hit's included,
                // was judged under this one request.
                let mut fn_certs = fn_certs;
                carry_request_ay_refusal_note(&mut fn_certs, request_ay_refusal_note.clone());
                all_certs.extend(fn_certs);
            }

            let proofs = Some(all_certs);
            // Fail-closed promotion gate. `ensure_proofs_promotable` covers an
            // explicit CompilerConfig proof request;
            // `gate_jit_proofs_promotable` is the unconditional verifying-mode
            // gate.
            self.ensure_proofs_promotable(proofs.as_deref())?;
            if must_verify {
                // Also the per-function verdict: a function without verified
                // evidence of its own is refused with the note its rows carry.
                self.gate_jit_proofs_promotable(proofs.as_deref().unwrap_or(&[]), &per_fn)?;
            }
            Ok((proofs, per_fn))
        }
    }

    /// The object promotion gate every certified object route calls before
    /// it emits. `exception_tables` is the unit's census: exception tables
    /// carry no proof obligation, so a proof-required compile refuses them
    /// first ([`ExceptionTableCensus::refuse_proof_grade`], the decision the
    /// proof-grade JIT routes make too), before any certificate check.
    fn ensure_object_proofs_promotable(
        &self,
        proofs: Option<&[ProofCertificate]>,
        exception_tables: &ExceptionTableCensus,
    ) -> Result<(), CompileError> {
        // L09-P3 route tests only: reach the publication checks that follow.
        #[cfg(test)]
        if crate::composed_transition::test_hooks::promotion_waived() {
            return Ok(());
        }
        if self.requires_verified_proof_promotion() {
            exception_tables
                .refuse_proof_grade(ProofGradeRoute::CertifiedObject, self.config.target)?;
        }
        self.ensure_proofs_promotable(proofs)?;
        if !self.requires_verified_proof_promotion() {
            return Ok(());
        }

        let proofs = proofs.ok_or_else(|| CompileError::ProofPromotionRejected {
            target: self.config.target,
            reason: "object proof promotion requires public proof reports, but none were emitted"
                .to_owned(),
        })?;
        let has_verified_inventory = proofs
            .iter()
            .any(|cert| cert.verified && cert.category == "relocation_inventory");
        if !has_verified_inventory {
            return Err(CompileError::ProofPromotionRejected {
                target: self.config.target,
                reason:
                    "object proof promotion requires a verified relocation_inventory certificate"
                        .to_owned(),
            });
        }

        Ok(())
    }

    #[cfg(feature = "verify")]
    fn certified_pass_chain_attachment_from_runs(
        &self,
        compilation_unit: &str,
        runs: &[trust_cg_opt::CertifiedPassRunRecord],
    ) -> Result<Option<CertifiedPassChainAttachment>, CompileError> {
        if let Some(chain) = &self.certified_pass_chain {
            return Ok(Some(chain.clone()));
        }
        if !self.production_certified_pass_chain {
            return Ok(None);
        }

        let mut all_runs =
            Vec::with_capacity(runs.len() + self.production_certified_pass_runs.len());
        all_runs.extend_from_slice(runs);
        all_runs.extend(self.production_certified_pass_runs.iter().cloned());

        for run in &all_runs {
            if !run.is_verified() {
                return Err(CompileError::CertifiedPassExecutionFailed {
                    pass_name: run.pass_name.clone(),
                    function_name: run.function_name.clone(),
                    detail: format!(
                        "status={}, local_checker_status={}, failure_count={}",
                        run.status.as_str(),
                        run.local_checker.status.as_str(),
                        run.failure_count
                    ),
                });
            }
        }

        let requests = all_runs
            .iter()
            .enumerate()
            .map(|(index, run)| {
                self.certified_pass_check_request(compilation_unit, index as u64, run)
            })
            .collect::<Result<Vec<_>, CompileError>>()?;
        let chain = trust_cg_verify::CertifiedPassChain::check_requests(requests)?;
        Ok(Some(CertifiedPassChainAttachment::from_checked_chain(
            &chain,
        )?))
    }

    /// Build a verified `Lean5PassCertificateCheckRequest` from a neutral
    /// `CertifiedPassRunRecord` using the same code path the production
    /// certified pass chain takes when assembling its checker-backed entries.
    ///
    /// This is exposed to support out-of-crate integration tests that need
    /// to synthesize certified-pass requests in-process when reference
    /// `reports/fixtures/` JSON is not present in the open-source tree.
    /// The signature is intentionally not part of the supported public API
    /// surface (see `#[doc(hidden)]`); production callers should use
    /// `with_production_certified_pass_chain`.
    #[cfg(feature = "verify")]
    #[doc(hidden)]
    pub fn certified_pass_check_request(
        &self,
        compilation_unit: &str,
        certificate_index: u64,
        run: &trust_cg_opt::CertifiedPassRunRecord,
    ) -> Result<
        trust_cg_verify::certified_pass_checker::Lean5PassCertificateCheckRequest,
        CompileError,
    > {
        use trust_cg_verify::certified_pass_checker::{
            CheckerArtifactRef, Lean5CheckerMode, Lean5CheckerPolicy, PlaceholderTransportEvidence,
        };

        let run_record_bytes = serde_json::to_vec(run).map_err(|source| {
            CompileError::CompileArtifactCacheIdentityJson {
                component: "certified_pass_run_record",
                source,
            }
        })?;
        let run_record_digest = sha256_hex(&run_record_bytes);
        let run_record_digest_ref = format!("sha256:{run_record_digest}");
        let run_record_uri = format!("trust-cg-opt://certified-pass-run/{run_record_digest}.json");
        let proof_digest = sha256_hex(
            format!(
                "{}:{}:{}",
                run.pass_instance_id, run.obligation_hash, run_record_digest
            )
            .as_bytes(),
        );
        let proof_digest_ref = format!("sha256:{proof_digest}");
        let proof_uri = format!(
            "builtin://trust-cg-opt/certified-pass-run/{}/placeholder-lean5",
            run.pass_instance_id
        );

        let canonical_obligation = CheckerArtifactRef {
            kind: "canonical_obligation".to_string(),
            uri: run_record_uri,
            digest: run_record_digest_ref,
            media_type: Some("application/json".to_string()),
            placeholder_transport: None,
        };
        let proof_artifact = CheckerArtifactRef {
            kind: "lean_module".to_string(),
            uri: proof_uri,
            digest: proof_digest_ref,
            media_type: Some("text/plain".to_string()),
            placeholder_transport: Some(PlaceholderTransportEvidence {
                accepted: true,
                note: "Transport check for an trust-cg-opt local certified pass run; semantic Lean replay is not part of this bounded slice.".to_string(),
            }),
        };
        let artifacts = vec![canonical_obligation, proof_artifact];
        let certificate_artifacts = serde_json::to_value(&artifacts).map_err(|source| {
            CompileError::CompileArtifactCacheIdentityJson {
                component: "certified_pass_checker_artifacts",
                source,
            }
        })?;

        let certificate = serde_json::json!({
            "format_version": "trust-cg.certified_pass.v1",
            "pass": {
                "name": run.pass_name.as_str(),
                "version": run.pass_version.to_string(),
                "implementation_commit": "workspace-local",
                "instance_id": run.pass_instance_id.as_str(),
                "pipeline_ordinal": certificate_index + 1,
                "target_profile": {
                    "triple": compiler_target_triple(self.target_spec),
                    "cpu": "unspecified",
                    "features": []
                },
                "options_hash": format!(
                    "sha256:{}",
                    sha256_hex(compiler_opt_level_name(self.config.opt_level).as_bytes())
                )
            },
            "provenance": {
                "source": {
                    "program_id": format!(
                        "trust-cg://{}/{}/before/{}",
                        compilation_unit, run.function_name, run.pass_instance_id
                    ),
                    "node_ids": [],
                    "expression_digest": run.obligation_hash.as_str()
                },
                "rewrite": {
                    "program_id": format!(
                        "trust-cg://{}/{}/after/{}",
                        compilation_unit, run.function_name, run.pass_instance_id
                    ),
                    "node_ids": [],
                    "expression_digest": run.obligation_hash.as_str()
                }
            },
            "contract": {
                "mode": "local_pass_certificate_summary",
                "semantic_policy": {
                    "source": "trust-cg-opt certified wrapper",
                    "fail_closed": true
                }
            },
            "domain": {
                "kind": "machine-ir",
                "certified_pass_run": run
            },
            "obligation_hash": run.obligation_hash.as_str(),
            "checker": {
                "kind": "lean5",
                "name": "trust-cg-cert-check",
                "version": "0.1.0",
                "proof_family": "trust-cg-opt-local-certified-pass-run-v1",
                "invocation": {
                    "mode": "in_process",
                    "command": ["trust-cg-codegen", "production-certified-pass-chain"],
                    "working_directory_policy": "process"
                },
                "limits": {
                    "timeout_ms": 1000
                },
                "replay_inputs": certificate_artifacts.clone(),
                "trust_base": [
                    "lean5-kernel",
                    "trust-cg-opt-local-certified-pass-run",
                    "placeholder-transport-fixture"
                ]
            },
            "result": {
                "status": "verified",
                "checked_at_unix": 0,
                "duration_ms": 0,
                "local_checker": &run.local_checker,
                "certificate_count": run.certificate_count,
                "failure_count": run.failure_count
            },
            "artifacts": {
                "refs": certificate_artifacts
            },
            "chain": {
                "compilation_unit": compilation_unit,
                "certificate_index": certificate_index,
                "must_be_verified": true
            }
        });

        Ok(
            trust_cg_verify::certified_pass_checker::Lean5PassCertificateCheckRequest {
                format_version: "trust-cg.lean5_pass_check.request.v1".to_string(),
                certificate,
                obligation_hash: run.obligation_hash.clone(),
                policy: Lean5CheckerPolicy {
                    checker: "lean5".to_string(),
                    mode: Lean5CheckerMode::PlaceholderTransport,
                    timeout_ms: 1000,
                    fail_closed: true,
                    expected_lean_version: Some("Lean 5.0.0-placeholder".to_string()),
                    lean5_binary: None,
                },
                artifacts,
            },
        )
    }

    /// Construct a verified `CertifiedPassRunRecord` for the gamma-vnncomp
    /// demo chain. Exposed as `#[doc(hidden)]` for cross-crate integration
    /// tests that synthesize the gamma demo certified pass requests in
    /// process (the open-source baseline does not ship the corresponding
    /// `reports/fixtures/gamma_vnncomp_demo_*_request.json` JSON).
    #[cfg(feature = "verify")]
    #[doc(hidden)]
    pub fn gamma_vnncomp_demo_run_record(
        pass_name: &str,
        pass_instance_id: &str,
        local_checker_name: &str,
        function_name: &str,
    ) -> trust_cg_opt::CertifiedPassRunRecord {
        use trust_cg_opt::{
            CertifiedPassCheckerRecord, CertifiedPassRunRecord, CertifiedPassRunStatus,
        };
        CertifiedPassRunRecord {
            format_version: "trust-cg.opt.certified_pass_run.v1".to_string(),
            pass_name: pass_name.to_string(),
            pass_version: 1,
            pass_instance_id: pass_instance_id.to_string(),
            function_name: function_name.to_string(),
            changed: false,
            status: CertifiedPassRunStatus::Verified,
            certificate_count: 0,
            failure_count: 0,
            obligation_hash: format!(
                "trust-cg-opt-certified-pass-run-v1:gamma-vnncomp-demo:{pass_instance_id}"
            ),
            local_checker: CertifiedPassCheckerRecord {
                kind: "trust-cg-opt-local".to_string(),
                name: local_checker_name.to_string(),
                version: "1".to_string(),
                status: CertifiedPassRunStatus::Verified,
            },
            summary: serde_json::json!({
                "changed": false,
                "certificates": [],
                "failures": []
            }),
        }
    }

    /// The per-function refusal CENSUS of [`Self::compile`]: each function of
    /// `module` that the codegen license, the module-local binding census or
    /// the adapter refuses, with its error, instead of the compile's first
    /// refusal alone.
    ///
    /// Diagnostic only: nothing is lowered past the adapter, no object, proof
    /// certificate or cache entry is produced, and the census neither admits
    /// nor refuses a module (`compile` still decides). The stages are
    /// `compile`'s, in its order, each run over the whole module:
    ///
    /// 1. the codegen license ([`CodegenLicensePolicy::verdict`]), on the
    ///    caller's module, before any rewrite, as `compile` decides it;
    /// 2. the binding census, after dialect legalization as in `compile`: on
    ///    an object path that cannot bind module-local functions
    ///    ([`Self::object_binds_module_local_functions`] false), each body's
    ///    direct edges to a module-local definition
    ///    ([`CompileError::AotDirectModuleFunctionBindingUnsupported`]) and
    ///    materialized module-local identities
    ///    ([`CompileError::AotStaticFunctionIdentityBindingUnsupported`]),
    ///    with an identity materialized in a global initializer attributed to
    ///    the function it names
    ///    ([`trust_cg_lower::module_local_function_identity_attribution`]);
    ///    and on every path, a module-local function named like a symbol the
    ///    backend references by name
    ///    ([`CompileError::ModuleLocalFunctionShadowsRuntimeSymbol`]);
    /// 3. the adapter, on every body the license admits, under exactly the
    ///    configuration `compile` uses
    ///    ([`trust_cg_lower::census_module_translation_with_access_model_and_license`]),
    ///    as [`CompileError::Adapter`].
    ///
    /// Rows are ordered by the function's position in `module`, then by stage;
    /// a function has at most one license row and one adapter row, and a body
    /// the license refuses is not translated.
    ///
    /// What the census does not list is `compile`'s RESIDUAL, which the caller
    /// reports from `compile` itself: a refusal of the module or the
    /// configuration as a whole (the AArch64 ISA profile, the non-unwinding
    /// exception-frame policy off AArch64, the resource budget,
    /// dialect legalization, the relocation model, prerequisite validation
    /// and the other module-level adapter gates, data named like a backend
    /// symbol; a failure here ends the stages that need its result), the
    /// second and later backend-symbol shadows (that check names one), and
    /// every refusal after the adapter (OPT-4, instruction selection, register
    /// allocation, emission and the post-emission object checks). An empty
    /// census therefore does not mean `compile` succeeds.
    pub fn preflight(&self, module: &trust_ir::Module) -> Vec<(trust_ir::FuncId, CompileError)> {
        let target = compiler_target_triple(self.target_spec);
        let position: HashMap<trust_ir::FuncId, usize> = module
            .functions
            .iter()
            .enumerate()
            .map(|(index, function)| (function.id, index))
            .collect();
        let function_named = |name: &str| {
            module
                .functions
                .iter()
                .find(|function| function.name == name)
                .map(|function| function.id)
        };
        // (position in the module, stage, function, refusal)
        let mut rows: Vec<(usize, u8, trust_ir::FuncId, CompileError)> = Vec::new();
        let mut push = |stage: u8, id: trust_ir::FuncId, error: CompileError| {
            let at = position.get(&id).copied().unwrap_or(usize::MAX);
            rows.push((at, stage, id, error));
        };

        // 1. The codegen license, on the caller's module, decided once for
        // every function (trust-ir's license layer runs once). A finding it
        // attributes to no one function refuses the module as a whole, which
        // is `compile`'s residual.
        let mut license_refused = BTreeSet::new();
        if let Ok(refusals) = self.codegen_license.census_module(module) {
            for (id, error) in refusals {
                license_refused.insert(id);
                push(1, id, CompileError::from(error));
            }
        }

        let Ok(Legalized {
            module: lowered_module,
            ..
        }) = self.legalize_dialects(module, self.requires_verified_proof_promotion())
        else {
            return Self::preflight_rows(rows);
        };
        let lowered_module = lowered_module.as_ref();

        // 2. The binding census.
        if !self.object_binds_module_local_functions() {
            let attribution =
                trust_cg_lower::module_local_function_identity_attribution(lowered_module);
            for (id, census) in attribution.bodies {
                if census.direct_edges != 0 {
                    push(
                        2,
                        id,
                        CompileError::AotDirectModuleFunctionBindingUnsupported {
                            target: target.clone(),
                            call_count: census.direct_edges,
                        },
                    );
                }
                let materialized = census.materialized_identities + census.symbol_addresses;
                if materialized != 0 {
                    push(
                        2,
                        id,
                        CompileError::AotStaticFunctionIdentityBindingUnsupported {
                            target: target.clone(),
                            candidate_count: materialized,
                        },
                    );
                }
            }
            let mut initializer_targets = attribution.global_initializer_targets;
            for (id, count) in attribution.global_initializer_symbol_addresses {
                *initializer_targets.entry(id).or_default() += count;
            }
            for (id, candidate_count) in initializer_targets {
                push(
                    2,
                    id,
                    CompileError::AotStaticFunctionIdentityBindingUnsupported {
                        target: target.clone(),
                        candidate_count,
                    },
                );
            }
        }
        for shadow in [
            refuse_backend_symbol_shadow(lowered_module, || target.clone()),
            refuse_darwin_sincos_merge_shadow(lowered_module, self.config.target, &target),
        ] {
            if let Err(CompileError::ModuleLocalFunctionShadowsRuntimeSymbol {
                target: shadow_target,
                function,
            }) = shadow
                && let Some(id) = function_named(&function)
            {
                push(
                    2,
                    id,
                    CompileError::ModuleLocalFunctionShadowsRuntimeSymbol {
                        target: shadow_target,
                        function,
                    },
                );
            }
        }

        // 3. The adapter, on every body the license admits. Native recorded
        // prototypes use the same target context as compile; the public
        // contextless diagnostic helper retains its blanket refusal.
        let adapter_refusals = (|| {
            let access_model = self.aot_object_access_model().ok()?;
            self.adapter_aarch64_abi().ok()?;
            let native = self.native_scalar_c_abi(lowered_module).ok()?;
            let arch = guard_carrier_arch_for_target(self.config.target);
            let policy = aot_object_symbol_policy(self.config.target, &target);
            Some(match native {
                Some(native) => native.census_module_translation(
                    lowered_module,
                    arch,
                    access_model,
                    &self.codegen_license,
                    policy,
                ),
                None => trust_cg_lower::census_module_translation_with_access_model_and_license(
                    lowered_module,
                    arch,
                    access_model,
                    &self.codegen_license,
                    policy,
                ),
            })
        })();
        if let Some(Ok(refusals)) = adapter_refusals {
            for (id, error) in refusals {
                // The adapter's own license verdict on a body stage 1 refused
                // is the same refusal.
                if !license_refused.contains(&id) {
                    push(3, id, CompileError::from(error));
                }
            }
        }
        Self::preflight_rows(rows)
    }

    /// Order [`Self::preflight`]'s rows by module position, then stage
    /// (stable, so each stage keeps its own order), and drop the sort keys.
    fn preflight_rows(
        mut rows: Vec<(usize, u8, trust_ir::FuncId, CompileError)>,
    ) -> Vec<(trust_ir::FuncId, CompileError)> {
        rows.sort_by_key(|(position, stage, ..)| (*position, *stage));
        rows.into_iter()
            .map(|(_, _, id, error)| (id, error))
            .collect()
    }

    /// A proof-grade lane's verdict on trust-ir `Inst::BoxDeref`: the ONE
    /// acceptance check
    /// ([`trust_cg_lower::admit_box_derefs`]) at
    /// [`trust_cg_lower::BoxValidityFloor::Refuse`], so a license that opted
    /// into the named-premise floor cannot carry a Box deref into a compile
    /// that emits proof certificates. A compile that emits none is decided
    /// by the license's own floor in the ingestion admission.
    fn refuse_box_derefs_for_proof_claim(
        &self,
        module: &trust_ir::Module,
        proof_claim: bool,
    ) -> Result<(), CompileError> {
        if proof_claim {
            trust_cg_lower::admit_box_derefs(module, trust_cg_lower::BoxValidityFloor::Refuse)
                .map_err(CompileError::from_admission)?;
        }
        Ok(())
    }

    /// Compile a trust_ir module to an object file.
    ///
    /// Translates each function in the module through the full pipeline:
    /// trust_ir adapter -> ISel -> optimization -> regalloc -> frame lowering
    /// -> encoding -> object emission.
    ///
    /// All functions are compiled into a single object file with each
    /// function as a separate symbol in the text section. Cross-function calls
    /// are represented as relocations for the linker.
    ///
    /// Returns the compiled object code, metrics, optional trace, and
    /// optional proof certificates.
    pub fn compile(&self, module: &trust_ir::Module) -> Result<CompilationResult, CompileError> {
        self.ensure_aarch64_isa_profile_applies()?;
        self.ensure_eh_frames_cannot_unwind_applies()?;
        crate::resource_limits::admit_compilation_budget()?;
        let total_start = Instant::now();
        let tracing = self.config.trace_level != CompilerTraceLevel::None;
        let mut trace_entries = Vec::new();

        // WS7.3 INGESTION ADMISSION: trust-ir's own codegen validator plus the
        // v41 codegen LICENSE, decided on the caller's module before any cache
        // lookup or rewrite (a cached artifact must never bypass a refusal; a
        // clone must never launder `Ungated` to `None`). Every finding refuses
        // (`crate::ingest`).
        // trust-ir v74 `Inst::BoxDeref` on a proof-grade compile: refused
        // whatever floor the license names. The only evidence the pinned
        // format admits is a named assumption, and certificates emitted
        // beside code compiled under one would read as covering it.
        self.refuse_box_derefs_for_proof_claim(
            module,
            self.config.emit_proofs || self.requires_verified_proof_promotion(),
        )?;
        let received = crate::ingest::admit_module(
            module,
            &self.codegen_license,
            &self.dialect_legalization_registry,
        )?;

        // Phase 0: Pre-adapter dialect legalization (#433, trust_ir #428,
        // ledger L05-P11).
        //
        // Every `Inst::DialectOp` and `Ty::Dialect` is resolved by exact name
        // against this compiler's legalization registry and either kept for
        // the adapter's typed arm or rewritten into core trust_ir; unknown
        // dialects, ops and types are refused here. A proof-required compile
        // (`emit_proofs`) admits only rules whose evidence this compile
        // checks. The legalized module then takes exactly the core path
        // below (validation, adapter, instruction proofs, object). Modules
        // with no dialect construct borrow the input unchanged. Static-call
        // recovery is fused into the adapter below, so it neither changes
        // this cache identity nor adds a second TrustIR scan or clone.
        let dialect_start = Instant::now();
        let Legalized {
            module: prepared_module,
            report: dialect_legalization,
        } = self.legalize_dialects(module, self.requires_verified_proof_promotion())?;
        if tracing {
            trace_entries.push(TraceEntry {
                phase: "dialect_lower".to_string(),
                duration: dialect_start.elapsed(),
                detail: Some(format!(
                    "{} rewrites",
                    dialect_legalization
                        .as_ref()
                        .map_or(0, DialectLegalizationReport::rewritten_op_sites)
                )),
            });
        }
        let lowered_module = prepared_module.as_ref();
        // The dialect rewrite produced core IR nothing else checks: admit the
        // module that is LOWERED too (WS7.3). A borrowed (op-free) module is
        // the received one and keeps its admission.
        let rewritten_admission;
        let admitted = if std::ptr::eq(lowered_module, module) {
            &received
        } else {
            rewritten_admission = crate::ingest::admit_rewritten(
                &received,
                lowered_module,
                &self.dialect_legalization_registry,
            )?;
            &rewritten_admission
        };
        // Run the complete source-identity census before even constructing a
        // cache context.  A cache hit, object writer, or proof emitter must not
        // bypass the same local-binding refusal as the adapter path. The
        // AArch64 ELF and Mach-O object paths bind these references to the
        // local definition (STB_LOCAL / N_EXT clear), which the post-emission
        // check below re-reads from the object bytes; every other object path
        // refuses them here.
        let binds_module_local_functions = self.object_binds_module_local_functions();
        if !binds_module_local_functions {
            let local_identity_census =
                trust_cg_lower::module_local_function_identity_census(lowered_module);
            if local_identity_census.direct_edges != 0 {
                return Err(CompileError::AotDirectModuleFunctionBindingUnsupported {
                    target: compiler_target_triple(self.target_spec),
                    call_count: local_identity_census.direct_edges,
                });
            }
            // A `SymbolAddr` naming a module-local function materializes that
            // function's address as surely as a `FnDef` does: the object
            // resolves the string through the definition's own symbol.
            let materialized = local_identity_census.materialized_identities
                + local_identity_census.symbol_addresses;
            if materialized != 0 {
                return Err(CompileError::AotStaticFunctionIdentityBindingUnsupported {
                    target: compiler_target_triple(self.target_spec),
                    candidate_count: materialized,
                });
            }
        }
        // Every object writer resolves the backend's by-name runtime calls and
        // personality through the object's own symbols first (a local
        // function or datum, on ELF, Mach-O and COFF alike): refuse a
        // definition those references would reach, on every target.
        refuse_backend_symbol_shadow(lowered_module, || compiler_target_triple(self.target_spec))?;
        refuse_darwin_sincos_merge_shadow(
            lowered_module,
            self.config.target,
            &compiler_target_triple(self.target_spec),
        )?;
        let cache_context = self.compile_artifact_cache_context(module, lowered_module)?;

        // Phase 1: Translate trust_ir module to internal LIR functions.
        // Sentinel S5 hardening: tell the adapter which target's carrier expander
        // will materialize a surviving exact-bound `InBounds` guard, so the
        // per-arch bound cap matches what that backend can actually encode.
        // The symbol-access model follows the OBJECT FORMAT of the target
        // triple and the configured relocation model: AArch64 ELF selects its
        // TLS models and GOT-indirect preemptible definitions from the
        // relocation model; other ELF targets keep the local-exec dialect and
        // everything else keeps Darwin TLV (both accept only `static`).
        let adapter_start = Instant::now();
        let adapter_arch = guard_carrier_arch_for_target(self.config.target);
        // The adapter arch above is the ISA alone. The Swift return budget it
        // selects is System V's; refuse every Swift edge when this compile's
        // x86-64 C ABI is one with no witnessed swiftcc placement, rather than
        // let an unmeasured ABI inherit SysV's numbers.
        reject_unwitnessed_swift_conv_for_spec(lowered_module, self.target_spec)?;
        let access_model = self.aot_object_access_model()?;
        // The adapter derives the AArch64 convention from the object access
        // model; resolving it here first keeps an unsupported triple a typed
        // refusal instead of a silent default.
        self.adapter_aarch64_abi()?;
        // trust-ir `ExternalWeak` declarations need a weak UNDEFINED symbol and
        // a GOT-indirect address, and v45 hidden/protected or sectioned
        // function definitions need an emitter that spells `STV_*` on a
        // function symbol and places a body in a named section. Only the
        // AArch64 ELF module emitters do, so only that object path admits
        // them all; the AArch64 and x86-64 Mach-O module emitters admit
        // exactly one, hidden (`N_PEXT`) `External` definitions
        // (`aot_object_admits_macho_hidden_function_definitions`), and x86-64
        // ELF/COFF and RISC-V keep the adapter's refusals
        // (`aot_object_symbol_policy`). The module-local refusals above are
        // lifted by a separate predicate
        // (`aot_object_binds_module_local_functions`), which the AArch64
        // Mach-O module emitter and the x86-64 ELF and Mach-O ones satisfy too:
        // emitted-byte checks bind references to their local definitions.
        let object_symbols = aot_object_symbol_policy(
            self.config.target,
            &compiler_target_triple(self.target_spec),
        );
        // Exact recovered calls currently have a complete JIT resolution path,
        // but only the AArch64 and x86-64 ELF and Mach-O writers are
        // checked to resolve every reference to a module-local function to
        // its local symbol (the COFF and RISC-V writers
        // bind only the unreferenced definition local). Minting an exact LIR
        // edge would emit a
        // preemptible relocation on at least one format. Merely keeping
        // the source CallIndirect is not sufficient either: its originating
        // in-module FnDef is itself materialized through an ordinary global
        // relocation, so interposition could still replace the proven target.
        //
        // Always run the diagnostic-only adapter census on AOT.  It retains the
        // indirect edge and identifies only candidates that satisfy the full
        // static-call contract.  Reject those modules before optimization or
        // object emission unless the object path binds module-local functions
        // (`aot_object_binds_module_local_functions`): on AArch64 ELF and
        // Mach-O the retained CallIndirect reaches the local definition
        // through its PC-relative (or local-symbol ABS64 / UNSIGNED) address,
        // and the post-emission check re-reads that binding.  JIT uses the sealed validation entry
        // point below and may devirtualize in its closed offset namespace.
        // A recorded foreign prototype is consumed only with the same native
        // ABI owner the machine pipeline uses. Module target claims alone do
        // not select the compilation ABI (notably System V versus Win64).
        let native_scalar_c_abi = self.native_scalar_c_abi(lowered_module)?;
        let (mut lir_functions, static_call_stats) = match native_scalar_c_abi.as_ref() {
            Some(native) => trust_cg_lower::translate_admitted_module_for_native_scalar_c_abi(
                admitted,
                adapter_arch,
                access_model,
                object_symbols,
                native,
            )?,
            None => trust_cg_lower::translate_admitted_module_for_arch_with_access_model_and_stats(
                admitted,
                adapter_arch,
                access_model,
                object_symbols,
            )?,
        };
        if tracing {
            trace_entries.push(TraceEntry {
                phase: "adapter".to_string(),
                duration: adapter_start.elapsed(),
                detail: Some(format!(
                    "{} functions, {}",
                    lir_functions.len(),
                    static_call_stats.trace_detail()
                )),
            });
        }

        memtrace("aot/after_adapter");
        // A type-declaration-only AArch64 object has no executable body.
        // Keep the complete admitted/object-checked path below, but never
        // mistake missing/withheld original functions or globals for this
        // case, and never manufacture proof evidence over an empty body set.
        let type_only_aarch64_object = self.config.target == Target::Aarch64
            && !self.config.emit_proofs
            && !self.requires_verified_proof_promotion()
            && self.certified_pass_chain.is_none()
            && !self.production_certified_pass_chain
            && module.functions.is_empty()
            && lowered_module.functions.is_empty()
            && module.globals.is_empty()
            && lowered_module.globals.is_empty()
            && (!lowered_module.structs.is_empty()
                || !lowered_module.enums.is_empty()
                || !lowered_module.records.is_empty()
                || !lowered_module.closure_types.is_empty());
        if lir_functions.is_empty() && !type_only_aarch64_object {
            return Err(CompileError::EmptyModule);
        }
        if !binds_module_local_functions && static_call_stats.authorization_withheld_calls != 0 {
            return Err(CompileError::AotStaticFunctionIdentityBindingUnsupported {
                target: compiler_target_triple(self.target_spec),
                candidate_count: static_call_stats.authorization_withheld_calls,
            });
        }

        // OPT-4: shared trust-ir-level (LIR) inlining, at the pre-dispatch seam.
        //
        // Runs on the adapter's `lir_functions` ONCE, before the per-target ISel
        // dispatch below, so x86-64 / aarch64 / riscv64 all inherit it. Nothing
        // downstream validates the substitution: every per-instruction lowering
        // proof, TV gate and body theorem takes the INLINED LIR as its source,
        // so it checks the lowering of a splice, not the splice, and the pass's
        // own checks (below) are structural. So a compile that claims proofs
        // runs neither this pass nor the range pass after it (ruling OD-225,
        // `lir_module_prep::unvalidated_lir_passes_run`): its proofs' source is
        // the adapter's LIR exactly. The
        // pass has two conservative tiers: pure single-block scalar leaves are
        // straight-line spliced, while separately eligible small multi-block
        // leaves are fresh-renamed and CFG-spliced. The latter rejects EH,
        // stack slots, in-module calls, and discharge-bearing guards, then
        // checks instruction conservation, CFG well-formedness, and value
        // freshness. Any structural mismatch fails the compile CLOSED; a wrong
        // argument-to-parameter mapping passes these checks. Kill switches:
        // `TCG_NO_INLINE` for both tiers, `TCG_NO_MB_INLINE` for only the CFG
        // tier. Skipped at O0 and in a compile that claims proofs.
        //
        // A definition the object writers bind weak (`STB_WEAK` /
        // `N_WEAK_DEF`; AArch64, x86-64 and RISC-V) without the
        // one-definition rule (`Weak`/`LinkOnce`) is interposable: the static
        // linker, and dyld for a Mach-O image, may select another definition,
        // so its body is never spliced into a caller here (the x86-64 COFF
        // emitter refuses such a definition).
        //
        // A bodied trust-ir `AvailableExternally` function is an inline-only
        // template here, as in the JIT step (`crate::lir_module_prep`): its
        // body may be spliced into a by-name call, and a call not spliced
        // stays a call to the undefined symbol the linker binds. A body
        // another object may replace at load time under this relocation
        // model (a default-visibility symbol in `pic` code) is withheld, and
        // so is every body in a compile that emits proofs (no inliner runs
        // there). Each body spliced or withheld is disclosed on
        // `CompilationResult::inline_only_bodies`.
        let mut inline_only_bodies = crate::lir_module_prep::InlineOnlyBodyEvidence::default();
        let makes_proof_claim = self.requires_verified_proof_promotion();
        if self.config.opt_level != OptLevel::O0 && makes_proof_claim {
            inline_only_bodies =
                crate::lir_module_prep::InlineOnlyBodyEvidence::withheld_for_proof_claim(
                    lowered_module,
                );
            if tracing {
                trace_entries.push(TraceEntry {
                    phase: crate::lir_module_prep::PROOF_CLAIM_SKIP_PHASE.to_string(),
                    duration: Duration::ZERO,
                    detail: Some(crate::lir_module_prep::PROOF_CLAIM_SKIP_DETAIL.to_string()),
                });
            }
        }
        if crate::lir_module_prep::unvalidated_lir_passes_run(
            self.config.opt_level,
            makes_proof_claim,
        ) {
            let inline_start = Instant::now();
            // Under a shared-object relocation model a preemptible definition
            // may be replaced by another module's definition at load time: a
            // call to it must stay a call (the linker routes it through the
            // PLT), never a spliced copy of this module's body. A name the
            // caller marked never-inline stays a call too.
            let mut interposable = inliner_interposable_function_names(
                lowered_module,
                access_model.relocation_model(),
                self.config.target,
            );
            interposable.extend(self.config.never_inline.iter().cloned());
            let dependencies: Vec<&trust_ir::Module> = self
                .inline_only_dependencies
                .iter()
                .map(std::sync::Arc::as_ref)
                .collect();
            let candidates = crate::lir_module_prep::admit_inline_only_bodies_with_authority(
                lowered_module,
                adapter_arch,
                access_model,
                admitted.license(),
                crate::lir_module_prep::InlineOnlyAdmission::for_proof_claim(makes_proof_claim),
                crate::lir_module_prep::InlineOnlyAuthority {
                    dependencies: &dependencies,
                },
            );
            let had_candidates = !candidates.bodies.is_empty() || !candidates.withheld.is_empty();
            let report = trust_cg_opt::ir_inline::inline_module_with_inline_only_bodies(
                &mut lir_functions,
                &candidates.bodies,
                &interposable,
            )
            .map_err(|e| CompileError::IrInline {
                detail: e.to_string(),
            })?;
            drop(candidates.bodies);
            inline_only_bodies = crate::lir_module_prep::InlineOnlyBodyEvidence::from_splices(
                report.inline_only_uses,
                candidates.withheld,
                candidates.authenticated,
            );
            if tracing {
                let inline_stats = report.stats;
                let mut detail = format!(
                    "{} sites / {} rounds",
                    inline_stats.sites, inline_stats.rounds
                );
                if had_candidates {
                    let spliced: usize = inline_only_bodies.spliced.iter().map(|u| u.sites).sum();
                    detail.push_str(&format!(
                        " / {} inline-only site(s) from {} body(ies), {} withheld",
                        spliced,
                        inline_only_bodies.spliced.len(),
                        inline_only_bodies.withheld.len()
                    ));
                }
                trace_entries.push(TraceEntry {
                    phase: "ir_inline".to_string(),
                    duration: inline_start.elapsed(),
                    detail: Some(detail),
                });
            }

            // Target-independent LIR range simplification belongs after
            // inlining (which can expose new masked operands) and before the
            // first target dispatch. Downstream ISel proof checks and the TV
            // gate check the lowering of the simplified LIR on every AOT
            // target, not the simplification: the pass deletes `Assert`s and
            // folds branches from its own interval facts with no check, which
            // is why a compile that claims proofs never reaches this point
            // (ruling OD-225).
            let range_start = Instant::now();
            let range_stats = trust_cg_opt::lir_unsigned_range::simplify_module(&mut lir_functions);
            if tracing {
                trace_entries.push(TraceEntry {
                    phase: "lir_unsigned_range".to_string(),
                    duration: range_start.elapsed(),
                    detail: Some(format!(
                        "{} uadd / {} umul / {} cmp / {} select / {} assert / {} branch",
                        range_stats.checked_adds_simplified,
                        range_stats.checked_muls_simplified,
                        range_stats.comparisons_folded,
                        range_stats.selects_folded,
                        range_stats.asserts_removed,
                        range_stats.branches_folded,
                    )),
                });
            }
        }

        memtrace("aot/after_ir_inline");
        // AOT PGO profile-generate is wired through the AArch64 preparation
        // pipeline only. Fail closed for any other target rather than
        // returning an object that silently carries no instrumentation.
        if self.profile_generate_sink.is_some() && self.config.target != Target::Aarch64 {
            return Err(CompileError::ProfileGenerateTargetUnsupported {
                target: self.config.target,
            });
        }

        // Native target dispatch follows the shared validated LIR pipeline.
        // Each backend applies its own ABI, instruction and output admission.
        match self.config.target {
            Target::Aarch64 => {}
            Target::X86_64 => {
                let object_globals = module_object_globals(lowered_module)?;
                let mut result = self.compile_x86_64(
                    lir_functions,
                    object_globals,
                    total_start,
                    tracing,
                    trace_entries,
                    cache_context,
                    lowered_module,
                )?;
                result.inline_only_bodies = inline_only_bodies;
                result.dialect_legalization = dialect_legalization;
                return Ok(result);
            }
            Target::Riscv64 => {
                let mut result = self.compile_riscv(
                    lir_functions,
                    total_start,
                    tracing,
                    trace_entries,
                    lowered_module,
                )?;
                result.inline_only_bodies = inline_only_bodies;
                result.dialect_legalization = dialect_legalization;
                return Ok(result);
            }
        }
        // Exception tables carry no proof obligation: a proof-required object
        // compile refuses them before any preparation, inventory or
        // certificate work (the census gate `ensure_object_proofs_promotable`
        // re-applies after preparation and before promotion).
        let mut exception_tables = ExceptionTableCensus::from_lir(&lir_functions);
        if self.requires_verified_proof_promotion() {
            exception_tables.refuse_well_formed_proof_grade(
                ProofGradeRoute::CertifiedObject,
                Target::Aarch64,
            )?;
        }

        // Build the internal pipeline. On AArch64 ELF the module's own data
        // definitions admit the `ADRP+LDR/STR #:lo12:` fusion at their
        // guaranteed alignment; the pipeline ignores the table elsewhere.
        let pipeline = self
            .build_pipeline(self.aarch64_object_isa_profile())
            .with_elf_lo12_symbol_alignments(crate::pipeline::elf_lo12_symbol_alignments(
                &module_object_globals(lowered_module)?,
            ));
        // A non-unwinding frame's table also reads the runtime routines this
        // backend calls on its own where LLVM has no call
        // (`backend_expansion_nounwind_callees`), a function of the module.
        let pipeline = if self.config.eh_frames_cannot_unwind {
            pipeline.with_eh_frames_cannot_unwind(Some(std::sync::Arc::new(
                crate::pipeline::backend_expansion_nounwind_callees(
                    lowered_module,
                    &self.config.eh_nounwind_callees,
                ),
            )))
        } else {
            pipeline
        };

        // Phase 2+: Prepare each function through ISel, optimization,
        // regalloc, frame lowering, and branch resolution. All functions
        // are then combined into a single Mach-O .o via compile_module()
        // so cross-function BL instructions get proper BRANCH26 relocations.
        //
        // When parallel compilation is enabled and there are 2+ functions,
        // use rayon to prepare functions concurrently. Each function's
        // pipeline (ISel -> opt -> regalloc -> frame -> branch resolution)
        // is fully independent with no shared mutable state.
        let parallel_worker_count = if self.config.parallel {
            crate::resource_limits::worker_count_for_items(lir_functions.len())?
        } else {
            None
        };
        let use_parallel = parallel_worker_count.is_some();
        let trust_ir_functions_for_lir = trust_ir_functions_for_lir(lowered_module, &lir_functions);
        // The bounded fsym preflight scans each function in this module:
        // decide its module-level facts once for all of them.
        let (prepared_funcs, preparation_metrics) = with_fsym_module_scope(lowered_module, || {
            let mut prepared_funcs: Vec<trust_cg_ir::MachFunction>;
            let mut preparation_metrics: Vec<crate::pipeline::PreparationMetrics>;

            if use_parallel {
                // Parallel path: each function is prepared independently via rayon.
                // Collect results with optional trace entries, then unpack.
                let preparation_environment =
                    trust_cg_process_env::EnvOverrideSnapshot::capture_current_thread();
                let worker_count = parallel_worker_count.unwrap_or(1);
                let pool = crate::resource_limits::build_rayon_pool(worker_count)
                    .map_err(|err| CompileError::Pipeline(PipelineError::WorkerPool(err)))?;
                let results: Vec<
                    Result<
                        (
                            trust_cg_ir::MachFunction,
                            crate::pipeline::PreparationMetrics,
                            Option<TraceEntry>,
                        ),
                        CompileError,
                    >,
                > = pool.install(|| {
                    lir_functions
                        .par_iter()
                        .zip(trust_ir_functions_for_lir.par_iter())
                        .map(|((lir_func, proof_ctx), trust_ir_func)| {
                            preparation_environment.run(|| {
                                let func_start = Instant::now();
                                let (ir_func, metrics) = if let Some(trust_ir_func) = *trust_ir_func
                                {
                                    pipeline
                                        .prepare_function_with_metrics_and_trust_ir_module(
                                            lir_func,
                                            Some(proof_ctx),
                                            lowered_module,
                                            trust_ir_func,
                                        )
                                        .map_err(CompileError::Pipeline)?
                                } else {
                                    pipeline
                                        .prepare_function_with_metrics(lir_func, Some(proof_ctx))
                                        .map_err(CompileError::Pipeline)?
                                };
                                let entry = if tracing {
                                    Some(TraceEntry {
                                        phase: "prepare_function".to_string(),
                                        duration: func_start.elapsed(),
                                        detail: Some(ir_func.name.clone()),
                                    })
                                } else {
                                    None
                                };
                                Ok((ir_func, metrics, entry))
                            })
                        })
                        .collect()
                });

                prepared_funcs = Vec::with_capacity(results.len());
                preparation_metrics = Vec::with_capacity(results.len());
                for result in results {
                    let (ir_func, metrics, trace_entry) = result?;
                    if let Some(entry) = trace_entry {
                        trace_entries.push(entry);
                    }
                    preparation_metrics.push(metrics);
                    prepared_funcs.push(ir_func);
                }
            } else {
                // Sequential path: single function or parallel disabled.
                prepared_funcs = Vec::with_capacity(lir_functions.len());
                preparation_metrics = Vec::with_capacity(lir_functions.len());
                for ((lir_func, proof_ctx), trust_ir_func) in
                    lir_functions.iter().zip(trust_ir_functions_for_lir.iter())
                {
                    let func_start = Instant::now();

                    let (ir_func, metrics) = if let Some(trust_ir_func) = *trust_ir_func {
                        pipeline.prepare_function_with_metrics_and_trust_ir_module(
                            lir_func,
                            Some(proof_ctx),
                            lowered_module,
                            trust_ir_func,
                        )?
                    } else {
                        pipeline.prepare_function_with_metrics(lir_func, Some(proof_ctx))?
                    };

                    if tracing {
                        trace_entries.push(TraceEntry {
                            phase: "prepare_function".to_string(),
                            duration: func_start.elapsed(),
                            detail: Some(ir_func.name.clone()),
                        });
                    }

                    preparation_metrics.push(metrics);
                    prepared_funcs.push(ir_func);
                }
            }
            Ok::<_, CompileError>((prepared_funcs, preparation_metrics))
        })?;

        let raw_dataflow_duration = validate_prepared_aarch64_dataflow_observations(
            &prepared_funcs,
            &lir_functions,
            &preparation_metrics,
            self.config.emit_proofs || self.requires_verified_proof_promotion(),
        )?;
        if let Some(duration) = raw_dataflow_duration.filter(|_| tracing) {
            trace_entries.push(TraceEntry {
                phase: "dataflow_integrity".to_string(),
                duration,
                detail: Some(format!(
                    "{} raw pre-optimization AArch64 functions (summed worker time)",
                    prepared_funcs.len()
                )),
            });
        }

        let function_count = prepared_funcs.len();
        // ELF and Mach-O objects carry each definition's trust-ir linkage: an
        // `Internal`/`Private` function stays out of the symbol table's
        // external partition and a `Weak`/`LinkOnce` (or ODR) one is a weak
        // definition (`STB_WEAK` / `N_WEAK_DEF`). Weak declarations, and v45
        // hidden/protected visibility and explicit sections on functions,
        // reach only the ELF emitters; the adapter refuses them for Mach-O
        // first.
        let symbol_linkage = aarch64_module_symbol_linkage(
            lowered_module,
            &prepared_funcs,
            &trust_ir_functions_for_lir,
        )?;
        let proof_optimization_certificates =
            collect_proof_optimization_certificates(&preparation_metrics);
        #[cfg(feature = "verify")]
        let certified_pass_runs = collect_certified_pass_runs(&preparation_metrics);
        let fsym_trust_ir_metrics = summarize_fsym_trust_ir_metrics(&preparation_metrics);
        let pass_validation = merge_pass_validation(&preparation_metrics);
        let composed_transitions = collect_composed_transitions(&preparation_metrics);
        // L09-P3: an `--emit-proofs` object requires every function a
        // TrustIR-bound legalization check covers to carry a composing record
        // before any certificate is generated or promoted; the object's bytes
        // are bound to its chain after emission (`check_composed_publication`).
        if self.config.emit_proofs {
            require_prepared_compositions(&prepared_funcs, &preparation_metrics)?;
        }
        // U10: the positive acknowledgment of every stack-limit request, and
        // the module reserve bound, from the final functions and their net
        // certificates (`docs/u10-prologue-stack-limit.md` §5-§6).
        let stack_limits = {
            let certificates: Vec<_> = preparation_metrics
                .iter()
                .map(|metrics| metrics.stack_limit_certificate.as_ref())
                .collect();
            aarch64_stack_limit_report(
                &prepared_funcs,
                &certificates,
                self.stack_limit_external_allowance,
            )
        };

        // Surface the per-phase breakdown the AOT path already measures.
        //
        // `prepare_function_with_metrics*` times isel/optimization/verification/
        // regalloc/frame_lowering/branch_resolution individually, but until now
        // this path used `preparation_metrics` only for certificates, pass runs
        // and frame layouts -- the timings were collected and dropped, leaving a
        // single lumped `prepare_function` trace entry. That is why the
        // compile-time attribution work could not say WHERE backend time goes
        // (e.g. the fixed ~9.5ms every Rust program pays for `std::rt::lang_start`,
        // ~7.4ms of it in this pipeline).
        //
        // Aggregate across functions and emit one entry per phase. Cost is a
        // handful of adds over an already-materialized vector, and only when
        // tracing is on.
        if tracing {
            let mut totals = crate::pipeline::PhaseTimings::default();
            let add = |dst: &mut Option<Duration>, src: Option<Duration>| {
                if let Some(d) = src {
                    *dst = Some(dst.unwrap_or(Duration::ZERO) + d);
                }
            };
            for m in &preparation_metrics {
                add(&mut totals.isel, m.timings.isel);
                add(&mut totals.optimization, m.timings.optimization);
                add(&mut totals.verification, m.timings.verification);
                add(&mut totals.regalloc, m.timings.regalloc);
                add(&mut totals.frame_lowering, m.timings.frame_lowering);
                add(&mut totals.branch_resolution, m.timings.branch_resolution);
                add(&mut totals.encoding, m.timings.encoding);
                add(&mut totals.unattributed, m.timings.unattributed);
            }
            for (phase, duration) in [
                ("prepare::isel", totals.isel),
                ("prepare::optimization", totals.optimization),
                ("prepare::verification", totals.verification),
                ("prepare::regalloc", totals.regalloc),
                ("prepare::frame_lowering", totals.frame_lowering),
                ("prepare::branch_resolution", totals.branch_resolution),
                ("prepare::encoding", totals.encoding),
                ("prepare::unattributed", totals.unattributed),
            ] {
                if let Some(duration) = duration {
                    trace_entries.push(TraceEntry {
                        phase: phase.to_string(),
                        duration,
                        detail: Some(format!("{function_count} functions")),
                    });
                }
            }
        }

        // Materialize the production object's relocation-bearing inputs before
        // proof promotion. Relocation authority covers more than encoded text
        // fixups: global-data slots, TLS descriptors, and unwind FDEs are emitted
        // from these inputs. Keeping the inventory and emitter on the same inputs
        // prevents known sidecar rows from being omitted. This is not an
        // exact-object digest binding: every non-empty production registry remains
        // fail-closed until an independently checked report is bound to the bytes.
        let mut object_globals = module_object_globals(lowered_module)?;
        // AOT PGO generate mode: define the counter array + site count the
        // injected increments and the dump runtime both reference. All sites
        // are known here — every function has been prepared above.
        if let Some(sink) = &self.profile_generate_sink {
            let n_sites = {
                let guard = match sink.lock() {
                    Ok(guard) => guard,
                    Err(poisoned) => poisoned.into_inner(),
                };
                guard.sites.len()
            };
            object_globals.push(ObjectGlobal {
                name: PGO_COUNTER_ARRAY_SYMBOL.to_string(),
                data: vec![0u8; n_sites * 8],
                mutable: true,
                is_external: true,
                symbol_refs: Vec::new(),
                is_thread_local: false,
                is_import: false,
                is_weak: false,
                align: 8,
                visibility: trust_ir::Visibility::Default,
                retained: false,
                section: None,
                comdat: false,
            });
            object_globals.push(ObjectGlobal {
                name: PGO_NSITES_SYMBOL.to_string(),
                data: (n_sites as u64).to_le_bytes().to_vec(),
                mutable: false,
                is_external: true,
                symbol_refs: Vec::new(),
                is_thread_local: false,
                is_import: false,
                is_weak: false,
                align: 8,
                visibility: trust_ir::Visibility::Default,
                retained: false,
                section: None,
                comdat: false,
            });
        }
        let module_frame_layouts: Vec<Option<crate::frame::FrameLayout>> = preparation_metrics
            .iter()
            .map(|metrics| metrics.frame_layout.clone())
            .collect();

        // The prepared functions' EH metadata is what the object emitters
        // read; refuse it before the relocation inventory and the
        // certificate lane run.
        exception_tables = exception_tables.with_machine_functions(&prepared_funcs);
        if self.requires_verified_proof_promotion() {
            exception_tables
                .refuse_proof_grade(ProofGradeRoute::CertifiedObject, Target::Aarch64)?;
        }

        crate::aarch64_prepared_dump::observe(crate::aarch64_prepared_dump::PreparedModule {
            module: lowered_module,
            lir: &lir_functions,
            machine: &prepared_funcs,
            metrics: &preparation_metrics,
            config: &self.config,
            target: &self.target_spec,
        });

        // Proof certificates are generated before cache lookup/store so a
        // proof-policy cache partition cannot promote object bytes whose public
        // proof surface contains failed, unverified, or unknown entries.
        //
        // The certificate lane is the single largest phase of a proofs-ON
        // compile and, until this entry existed, the ONLY untraced one: an
        // empty `fn main() {}` reported `total=98.4ms` against itemised phases
        // summing to 4.3ms, so 94ms had nowhere to land and every attribution
        // attempt was guesswork. The x86 path in `compile_x86_64_module` has
        // carried an `x86_proof_certs` entry for a while; this is its AArch64
        // twin, which the object path never got.
        // KIND-PARALLEL PRE-WARM of reconstruction-arm evaluation sweeps.
        //
        // Uncovered reconstructed obligations require 100k-sample evaluation
        // sweeps, a process-wide compute-once cost, so per-function fanout only
        // makes workers queue on the same memo cells. We instead enumerate the
        // walk's own distinct reconstructed obligations and parallelize across
        // kinds. Registry theorems are not warmed: the walk never discharges
        // them (substring and representative credit are withdrawn), so neither
        // portable replay nor sweeps of them could feed any verdict.
        //
        // Verdict-identical by construction: every evaluation ends in its
        // content-keyed memo, each cell is computed once, and the ordinary walk
        // reads it. Width and scheduling never affect output.
        #[cfg(feature = "verify")]
        if trust_cg_process_env::var_os("TCG_TIME_SWEEP").is_some() {
            eprintln!(
                "TCG_PREWARM_GATE fns={} emit_proofs={} parallel={} live_solver_may_run={}",
                prepared_funcs.len(),
                self.config.emit_proofs,
                self.config.parallel,
                proof_promotion_live_solver_may_run()
            );
        }
        // NOT gated on `config.parallel`. That flag governs the FUNCTION-level
        // regalloc+encode fanout, which is memory-bounded and which the bridge's
        // legacy path pins to `false` for every CGU but the first. A kind-parallel
        // sweep pre-warm is the opposite shape — read-only CPU over the shared
        // verifier — and it is worth the MOST on exactly the single-function CGU
        // (measured: a `main` CGU with fns=1 paid 41ms of first-touch sweeps that
        // the gated version skipped). Width is bounded by
        // `verification_worker_count_for_items`, which honours
        // `TRUST_CG_MAX_PARALLELISM` and returns None when there is nothing to
        // spread, and by the solver-serialisation rule below.
        #[cfg(feature = "verify")]
        if (self.config.emit_proofs || self.requires_verified_proof_promotion())
            && !proof_promotion_live_solver_may_run()
        {
            let prewarm_start = Instant::now();
            let verifier = shared_aarch64_function_verifier();
            let funcs: Vec<&trust_cg_ir::MachFunction> = prepared_funcs.iter().collect();
            let recon = verifier.reconstructed_obligations_for_functions(&funcs);
            let t_enum = prewarm_start.elapsed();
            let total = recon.len();
            if trust_cg_process_env::var_os("TCG_TIME_SWEEP").is_some() {
                eprintln!(
                    "TCG_PREWARM fns={} reconstructed={} width={:?}",
                    funcs.len(),
                    recon.len(),
                    sweep_prewarm_width(total)?
                );
            }
            // NOT on the shared 32 MiB-stack verifier pool, deliberately. That
            // pool is sized for the per-function certificate WALK, whose
            // `try_eval` recursion genuinely needs the large stack, and it is
            // therefore kept narrow (2 workers by default; 1 in the bridge) to
            // bound total stack memory. The sweeps here are a different shape:
            // every corpus obligation compiles to a FLAT tape (29/29 on
            // h3_box_leak — the recursive fallback never runs), the only
            // recursion is the one-time `FlatProg::compile` tree walk, and the
            // deepest obligation in the entire registry nests 68 levels (`BSR_I64`),
            // which a default 2 MiB worker stack absorbs with orders of magnitude
            // to spare. So this pool is WIDE (host parallelism, bounded by the
            // operator's TRUST_CG_MAX_PARALLELISM) and default-stack: the memory
            // argument that narrows the walk pool does not apply to it, and
            // narrowing it would serialize ~20-30 independent kinds behind one
            // or two workers — measured as +30..+64ms on the corpus.
            // Width comes from the HOST (bounded by the operator's
            // TRUST_CG_MAX_PARALLELISM), not from
            // `verification_worker_count_for_items`: that now derives from the
            // walk pool's limit, which is 1 inside the bridge — so asking it here
            // returned None and silently disabled the pre-warm entirely.
            // The pool sizes itself (`sweep_pool`); this is only the go/no-go.
            if sweep_prewarm_width(total)?.is_some() {
                let t_run0 = Instant::now();
                if let Some(pool) = sweep_pool()? {
                    // Asynchronous: the owners start on the pool and the WALK
                    // starts now, blocking only on the cells it reaches while
                    // they are in flight — so the sweeps overlap the walk
                    // instead of preceding it. A kind the walk reaches before
                    // any owner claimed it is swept by the walk, fanned out to
                    // the same pool (`set_sweep_helper_pool`).
                    spawn_bounded_owner_sweeps(&pool, recon, verifier);
                }
                if trust_cg_process_env::var_os("TCG_TIME_SWEEP").is_some() {
                    eprintln!(
                        "TCG_PREWARM_SPLIT enumerate={:.1}ms run={:.1}ms",
                        t_enum.as_secs_f64() * 1000.0,
                        t_run0.elapsed().as_secs_f64() * 1000.0
                    );
                }
            }
            if tracing {
                trace_entries.push(TraceEntry {
                    phase: "proof_prewarm".to_string(),
                    duration: prewarm_start.elapsed(),
                    detail: Some(format!("{total} reconstructed obligations")),
                });
            }
        }
        #[cfg(feature = "verify")]
        let proof_certs_start = Instant::now();
        // CT-7 pool width for the cert lane — the SAME policy `compile_x86_64`
        // has used since CT-7 and which this path never got. `use_parallel` /
        // `parallel_worker_count` come from `worker_count_for_items`, whose
        // 16-items-per-worker floor is calibrated for the memory-hungry
        // regalloc+encode fanout; applying it here left every CGU under 32
        // functions generating certificates SERIALLY, and the certificate lane
        // is the dominant proofs-ON compile cost. Per-function verification is
        // pure read-only CPU over the shared `&'static` verifier, but its deep
        // SMT walk needs a 32 MiB stack. The shared verifier resource policy
        // therefore uses a small process-wide pool (or the explicit operator
        // limit) rather than the memory-heavy regalloc heuristic. Width never
        // affects output — the lane collects into a function-ordered vector.
        //
        // The compiler verifier's SourceBoundReplay policy can replay a checked
        // frame or arithmetic obligation through AY, so the lane stays serial
        // rather than invoking a solver from several threads.
        #[cfg(feature = "verify")]
        let cert_worker_count = if self.config.parallel && !proof_promotion_live_solver_may_run() {
            crate::resource_limits::verification_worker_count_for_items(prepared_funcs.len())?
        } else {
            None
        };
        #[cfg(feature = "verify")]
        let mut proofs = if self.config.emit_proofs || self.requires_verified_proof_promotion() {
            let source_modules =
                trust_cg_verify::FunctionSourceModules::capture(module, lowered_module).map_err(
                    |error| {
                        CompileError::Pipeline(PipelineError::NoTmbcWireImage(error.to_string()))
                    },
                )?;
            let proof_environment =
                trust_cg_process_env::EnvOverrideSnapshot::capture_current_thread();
            // ENC-5 runs when `pipeline` encodes the module below; a
            // certificate citing it is positive only if it is enforced there.
            let a64_decode = pipeline.aarch64_decode_check_backing();
            let all_certs: Vec<ProofCertificate> = if let Some(worker_count) = cert_worker_count {
                let pool = crate::resource_limits::build_rayon_pool(worker_count)
                    .map_err(|err| CompileError::Pipeline(PipelineError::WorkerPool(err)))?;
                pool.install(|| {
                    // TV-2: `prepared_funcs` is built 1:1 in `lir_functions`
                    // order (both branches above), so the zip pairs each
                    // MachFunction with the LIR function its ISel consumed;
                    // the verifier additionally name-guards the pairing.
                    prepared_funcs
                        .par_iter()
                        .zip(lir_functions.par_iter())
                        .flat_map(|(func, (lir_func, _))| {
                            proof_environment.run(|| {
                                generate_proof_certificates(
                                    func,
                                    Some(lir_func),
                                    Some(&source_modules),
                                    a64_decode,
                                )
                            })
                        })
                        .collect()
                })
            } else {
                let mut certs = Vec::new();
                for (func, (lir_func, _)) in prepared_funcs.iter().zip(lir_functions.iter()) {
                    certs.extend(generate_proof_certificates(
                        func,
                        Some(lir_func),
                        Some(&source_modules),
                        a64_decode,
                    ));
                }
                certs
            };
            Some(all_certs)
        } else {
            None
        };
        #[cfg(feature = "verify")]
        if tracing {
            trace_entries.push(TraceEntry {
                phase: "proof_certs".to_string(),
                duration: proof_certs_start.elapsed(),
                detail: Some(format!(
                    "{} certs over {} fns",
                    proofs.as_deref().map(<[_]>::len).unwrap_or(0),
                    prepared_funcs.len()
                )),
            });
        }
        #[cfg(not(feature = "verify"))]
        let proofs: Option<Vec<ProofCertificate>> = None;

        #[cfg(feature = "verify")]
        let mut elf_inventory_kinds: Option<Vec<trust_cg_verify::ObjectRelocationKind>> = None;
        #[cfg(feature = "verify")]
        let mut elf_unwind_rows: Option<
            Vec<crate::pipeline::AArch64ElfUnwindRelocationRow>,
        > = None;
        #[cfg(feature = "verify")]
        let mut macho_inventory_kinds: Option<Vec<trust_cg_verify::ObjectRelocationKind>> = None;
        #[cfg(feature = "verify")]
        if let Some(proofs) = proofs.as_mut()
            && let Some(inventory) = pipeline.module_relocation_inventory_with_symbol_linkage(
                &prepared_funcs,
                &object_globals,
                &module_frame_layouts,
                &symbol_linkage,
                format!("{}-module.o", compiler_target_triple(self.target_spec)),
            )?
        {
            // Walk-through `.eh_frame` CFI is part of every promoted object
            // with frames; it is trusted, not proven, and the certificate says
            // so.
            append_object_relocation_inventory_certificate_disclosing(
                proofs,
                &inventory.report,
                inventory.trusted_unwind_tables.as_deref(),
            );
            // Retain the inventory rows for the ARTIFACT-LEVEL digest (ELF and
            // Mach-O alike) and the ELF unwind-row cross-check against the
            // emitted object bytes below.
            let kinds = inventory.report.entries.iter().map(|e| e.kind).collect();
            if crate::pipeline::target_triple_uses_elf(&compiler_target_triple(self.target_spec)) {
                elf_inventory_kinds = Some(kinds);
                elf_unwind_rows = Some(inventory.elf_unwind_rows);
            } else {
                macho_inventory_kinds = Some(kinds);
            }
        }

        self.ensure_object_proofs_promotable(proofs.as_deref(), &exception_tables)?;
        let proof_bundle_sha256 = proof_bundle_sha256(proofs.as_deref());

        // Phase 8-9: Encode all functions and emit a single Mach-O .o file
        // with proper cross-function BRANCH26 relocations.
        // When parallel mode is active, use parallel encoding to avoid the
        // sequential bottleneck of encoding functions one-by-one.
        let module_start = Instant::now();
        let mut compile_artifact_cache_telemetry = Vec::new();
        let cached_object = if let Some(context) = &cache_context {
            match lookup_compile_artifact(
                &context.cache,
                &context.key,
                context.boundary,
                proof_bundle_sha256.as_deref(),
                &context.reuse_permit,
            )? {
                Some(CompileArtifactCacheLookup::Hit { entry, telemetry }) => {
                    compile_artifact_cache_telemetry.push(telemetry);
                    Some(entry.artifact_bytes)
                }
                Some(CompileArtifactCacheLookup::Miss { telemetry })
                | Some(CompileArtifactCacheLookup::Rejected { telemetry }) => {
                    compile_artifact_cache_telemetry.push(telemetry);
                    None
                }
                None => None,
            }
        } else {
            None
        };
        // Exception-handling routing.
        //
        // [TCG-EH-A64-BATCH] (X1 follow-up to FUZZ-7), resolved: a
        // MULTI-function EH module used to fail closed here because the generic
        // module emitter had no unwind-table emission — the object would have
        // carried landing-pad code with no `__gcc_except_tab` /
        // `__compact_unwind` (silently skipped cleanup Drops, the FUZZ-7
        // [TCG-EH-WALK] class). The module emitters now build WHOLE-MODULE
        // unwind tables for Mach-O (per-function `__LD,__compact_unwind`
        // entries + DWARF FDE fallbacks + LSDAs — the x86 EH-Lane-5 analogue,
        // `Pipeline::emit_module_macho_with_unwind`), consuming the frame
        // layouts captured during preparation. Formats the port does not cover
        // (generic ELF) and missing layouts still FAIL CLOSED inside the
        // emitter — never a silent table drop.
        //
        // A SINGLE-function EH module used to detour through the standalone
        // `compile_function` pipeline here. That path re-ran ISel/opt/regalloc
        // from scratch AND — the actual defect — emitted the object WITHOUT
        // `object_globals`, so a module-owned internal global (`str.*` literal
        // blobs, `const.alloc*` CTFE images, `vtable.*`) referenced by an EH
        // function was left an UNDEFINED extern in the object and had to be
        // synthesized by the link harness from module text. Single-function EH
        // modules now flow through the same whole-module emitters as everything
        // else (`encode_module_function_with_fixups_and_eh` mirrors the proven
        // single-function LSDA/compact-unwind sequence exactly), so every
        // module-owned global it references is DEFINED in the object.
        //
        // Which preparation and emission path produced the object, recorded
        // in the `compile_module` trace entry so a caller can tell the
        // parallel emitter's output from the sequential one's.
        let emission_path = if cached_object.is_some() {
            "cached object".to_string()
        } else if let Some(workers) = parallel_worker_count {
            format!("parallel preparation and emission, {workers} workers")
        } else {
            "sequential preparation and emission".to_string()
        };
        // The AArch64 ELF and Mach-O exemption from the module-local identity
        // refusals is backed by the object bytes: every symbol and relocation
        // spelling a bodied Internal/Private function must be its local
        // definition (STB_LOCAL / N_EXT clear), for a fresh object before it
        // is cached and for a cached one alike.
        let module_local_binding = if binds_module_local_functions {
            ModuleLocalBindingExpectation::for_module(lowered_module)
        } else {
            ModuleLocalBindingExpectation::empty()
        };
        // Every AArch64 ELF and Mach-O object, fresh or cached, must also be
        // partitionable into the module's functions by symbol, each symbol
        // with the binding its trust-ir linkage and visibility dictate; a
        // fresh object is also held to the layout its emitter reports.
        let symbol_discipline = ObjectSymbolDisciplineExpectation::for_emitted(
            &compiler_target_triple(self.target_spec),
            lowered_module,
            &prepared_funcs,
        )?;
        let check_local_binding =
            |object: &[u8], layout: Option<&[crate::pipeline::TextFunctionExtent]>| {
                let target = compiler_target_triple(self.target_spec);
                check_aarch64_module_local_function_binding(
                    &target,
                    object,
                    &module_local_binding,
                )?;
                if binds_module_local_functions {
                    check_aarch64_code_references_reach_code(&target, object)?;
                }
                check_aarch64_object_symbol_discipline(
                    &target,
                    object,
                    &symbol_discipline,
                    layout,
                )?;
                Ok::<(), CompileError>(())
            };
        // L09-P3: an `--emit-proofs` object publishes a function a
        // TrustIR-bound legalization check covers only with a composed chain
        // ending at exactly the bytes the object carries for it (read back
        // from the object, cached or fresh).
        let check_composed_publication = |object: &[u8]| -> Result<usize, CompileError> {
            if !self.config.emit_proofs {
                return Ok(0);
            }
            let records: Vec<(
                &str,
                Option<&trust_cg_verify::composed_transition::TransitionRecord>,
            )> = prepared_funcs
                .iter()
                .zip(&preparation_metrics)
                .map(|(func, metrics)| (func.name.as_str(), metrics.composed_transition.as_ref()))
                .collect();
            #[cfg(test)]
            let flipped =
                crate::composed_transition::test_hooks::flip_object_function_byte(object, &records);
            #[cfg(test)]
            let object = flipped.as_deref().unwrap_or(object);
            crate::composed_transition::require_object_publication(object, &records)
                .map_err(composed_transition_refused)
        };
        let composed_publications;
        let obj_bytes = if let Some(bytes) = cached_object {
            check_local_binding(&bytes, None)?;
            composed_publications = check_composed_publication(&bytes)?;
            bytes
        } else {
            let emission = if use_parallel {
                pipeline.compile_module_parallel_emission_with_symbol_linkage(
                    &prepared_funcs,
                    &object_globals,
                    &module_frame_layouts,
                    &symbol_linkage,
                )?
            } else {
                pipeline.compile_module_emission_with_symbol_linkage(
                    &prepared_funcs,
                    &object_globals,
                    &module_frame_layouts,
                    &symbol_linkage,
                )?
            };
            let emission = emission.into_emission();
            check_local_binding(&emission.object, Some(&emission.text_extents))?;
            composed_publications = check_composed_publication(&emission.object)?;
            let bytes = emission.object;
            if let Some(context) = &cache_context
                && let Some(telemetry) = store_compile_artifact(
                    &context.cache,
                    &context.key,
                    context.boundary,
                    &bytes,
                    "trust-cg-codegen::Compiler::compile",
                    proof_bundle_sha256.as_deref(),
                    &context.reuse_permit,
                )?
            {
                compile_artifact_cache_telemetry.push(telemetry);
            }
            bytes
        };

        // ARTIFACT-LEVEL relocation-row digest (recorded follow-up to the
        // aarch64 ELF Certified composition): the inventory above was built by
        // MIRRORING emitter bookkeeping, and the reparse gate proves only
        // bytes == writer intent — so a writer-side relocation the mirror
        // never anticipated would pass both while shipping uninventoried.
        // Parse the relocation records back OUT of the artifact itself and
        // require the multiset to equal the inventory rows; any drift (in
        // EITHER direction, cached artifacts included) fails the compile
        // closed.
        #[cfg(feature = "verify")]
        if let Some(kinds) = elf_inventory_kinds.as_deref() {
            crosscheck_elf_relocation_inventory_digest(&obj_bytes, kinds)?;
        }
        // The Mach-O digest also checks each record's modeled shape, the
        // SUBTRACTOR+UNSIGNED pairing and the ADDEND prefixes.
        #[cfg(feature = "verify")]
        if let Some(kinds) = macho_inventory_kinds.as_deref() {
            crate::pipeline::crosscheck_aarch64_macho_relocation_inventory_digest(
                &obj_bytes, kinds,
            )?;
        }
        // The `.eh_frame` / `DW.ref` rows are compared record by record
        // (section, offset, type, symbol, addend), not only by kind: an
        // unwind row naming the wrong function, LSDA or slot fails closed.
        #[cfg(feature = "verify")]
        if let Some(rows) = elf_unwind_rows.as_deref() {
            crate::pipeline::crosscheck_aarch64_elf_unwind_relocation_rows(&obj_bytes, rows)?;
        }

        if tracing {
            trace_entries.push(TraceEntry {
                phase: "compile_module".to_string(),
                duration: module_start.elapsed(),
                detail: Some(format!("{function_count} functions, {emission_path}")),
            });
        }

        // Count actual non-pseudo instructions across all prepared functions.
        // Each AArch64 instruction is exactly 4 bytes, so code_size = count * 4.
        // This is the real instruction count, not the Mach-O object size / 4
        // which would incorrectly include headers, symbol tables, and relocations.
        let total_instruction_count: usize =
            prepared_funcs.iter().map(count_real_instructions).sum();
        let total_code_size = total_instruction_count * 4;

        // Query actual pass count from the optimization pipeline rather than
        // using hardcoded estimates (fixes #272).
        let opt_passes_per_func = {
            use trust_cg_opt::pipeline::{OptLevel as OptOptLevel, OptimizationPipeline};
            let opt_level = match self.config.opt_level {
                OptLevel::O0 => OptOptLevel::O0,
                OptLevel::O1 => OptOptLevel::O1,
                OptLevel::O2 => OptOptLevel::O2,
                OptLevel::O3 => OptOptLevel::O3,
            };
            OptimizationPipeline::new(opt_level).pass_count()
        };

        let metrics = CompilationMetrics {
            code_size_bytes: total_code_size,
            instruction_count: total_instruction_count,
            function_count,
            optimization_passes_run: opt_passes_per_func * function_count,
            proof_optimizations: summarize_proof_optimizations(&proof_optimization_certificates),
            fsym_trust_ir: fsym_trust_ir_metrics,
            pass_validation,
            composed_transitions,
            composed_publications,
        };

        let trace = if tracing {
            Some(CompilerTrace {
                entries: trace_entries,
                total_duration: total_start.elapsed(),
            })
        } else {
            None
        };

        #[cfg(feature = "verify")]
        let certified_pass_chain = self.certified_pass_chain_attachment_from_runs(
            &lowered_module.name,
            &certified_pass_runs,
        )?;
        #[cfg(not(feature = "verify"))]
        let certified_pass_chain = self.certified_pass_chain.clone();

        Ok(CompilationResult {
            aarch64_frame_inputs: crate::aot_frame_inputs::observe_aarch64_frames(
                &prepared_funcs,
                &preparation_metrics,
                module,
                prepared_module,
                &lir_functions,
                &obj_bytes,
            ),
            object_code: obj_bytes,
            metrics,
            trace,
            proofs,
            certified_pass_chain,
            proof_optimization_certificates,
            compile_artifact_cache_telemetry,
            target_selection: self.target_selection(),
            inline_only_bodies,
            stack_limits,
            dialect_legalization,
        })
    }

    /// x86-64 compile path (#340, #464).
    ///
    /// Routes trust_ir functions through the [`crate::x86_64::X86Pipeline`]
    /// (ISel -> regalloc -> frame lowering -> encoding) and then emits a
    /// single multi-function Mach-O / ELF object via
    /// [`crate::x86_64::X86Pipeline::compile_module`]. Cross-function calls
    /// are wired via symbol-table entries and `X86_64_RELOC_BRANCH` /
    /// `R_X86_64_PLT32` relocations.
    ///
    /// Mirrors the AArch64 dispatcher at
    /// [`Self::compile_aarch64`]: each function is run through ISel
    /// independently, then the entire set is handed to `compile_module` for
    /// combined emission.
    ///
    /// Note: `CompilationMetrics::instruction_count` is reported from the
    /// x86-64 ISel functions (non-pseudo insts summed across all functions),
    /// and `code_size_bytes` is the raw encoded code length (no Mach-O
    /// header/symbol-table overhead). Because x86-64 uses variable-length
    /// encoding, `code_size_bytes` is NOT `instruction_count * 4`.
    fn compile_x86_64(
        &self,
        lir_functions: Vec<(trust_cg_lower::Function, trust_cg_lower::ProofContext)>,
        object_globals: Vec<ObjectGlobal>,
        total_start: Instant,
        tracing: bool,
        mut trace_entries: Vec<TraceEntry>,
        cache_context: Option<CompileArtifactCacheContext>,
        trust_ir_module: &trust_ir::Module,
    ) -> Result<CompilationResult, CompileError> {
        use crate::x86_64::{X86OutputFormat, X86Pipeline, X86PipelineConfig};
        use trust_cg_lower::x86_64_isel::X86CallAbi;

        // #465: x86-64 proof certificates are now produced via the shared
        // public `ProofCertificate` shape. The previous early-return guard
        // (`CompileError::ProofsUnsupportedForTarget`) was removed once
        // `all_x86_64_proofs` (#434) and `all_x86_64_eflags_proofs` (#458)
        // landed in the `ProofDatabase` and a parallel x86-64 function
        // verifier (`trust_cg_verify::x86_64_function_verifier`) was wired to
        // walk an `X86ISelFunction`. Proof emission is gated on the
        // `verify` feature flag, same as the AArch64 path. Without it, an
        // explicit proof request is rejected with a typed error; it is never
        // silently honored as a no-op with `proofs: None`.
        #[cfg(not(feature = "verify"))]
        if self.config.emit_proofs {
            return Err(CompileError::ProofsUnsupportedForTarget {
                target: Target::X86_64,
            });
        }

        let target_spec = self.target_spec;
        let output_format = x86_64_aot_output_format_for_target_spec(target_spec)?;
        // SINGLE SOURCE with the fail-closed Swift-witness check that runs
        // before lowering; see `x86_call_abi_for_target_spec`.
        let call_abi: X86CallAbi = x86_call_abi_for_target_spec(target_spec);

        let function_count = lir_functions.len();
        if function_count == 0 {
            return Err(CompileError::DispatcherEmptyModule {
                dispatcher: "x86_64",
            });
        }

        // The x86-64 Mach-O emitter produces the LSDA (`__gcc_except_tab`), the
        // zPLR-augmented FDE and the personality wiring, and the ELF module
        // emitter now produces its GNU/Linux counterparts (`.gcc_except_table`,
        // a zPLR `.eh_frame` with an FDE for every function, and the
        // `DW.ref.<personality>` slot), so an EH function targeting either flows
        // through to emission. COFF still gets no LSDA, so an EH function
        // targeting it FAILS CLOSED here rather than shipping an object with no
        // unwind tables. EH structure is only produced under the
        // `TCG_ENABLE_UNWIND` frontend opt-in (default OFF; `panic=abort` and the
        // default path never produce it), so this gate is inert for the standard
        // corpus and preserves the "unwind opt-in never miscompiles" contract on
        // x86.
        reject_x86_eh_for_unwired_aot_format(&lir_functions, output_format)?;
        refuse_coff_weak_function_definitions(trust_ir_module, output_format)?;
        // Taken before ISel consumes the LIR. Exception tables carry no proof
        // obligation, so a proof-required compile refuses them here, before
        // any backend work; the census grows by the walk-through filler
        // tables once the module is assembled, and the promotion gate
        // re-applies it.
        #[cfg_attr(not(feature = "verify"), allow(unused_mut))]
        let mut exception_tables = ExceptionTableCensus::from_lir(&lir_functions);
        if self.requires_verified_proof_promotion() {
            exception_tables
                .refuse_well_formed_proof_grade(ProofGradeRoute::CertifiedObject, Target::X86_64)?;
        }

        // CT-5: exploit the idle cores. The per-function backend work — register
        // allocation + machine-code encoding (`compile_module_*_parallel`) and,
        // under the `verify` feature, per-function proof-certificate generation —
        // is independent per function and is the dominant compile-time cost, yet
        // this dispatcher historically ran it single-threaded. When
        // `CompilerConfig::parallel` is set (the default), fan it out across a
        // bounded rayon pool. The module emitters gate the actual pool build on
        // `worker_count_for_items`, so a single-function module stays serial.
        //
        // DETERMINISM: every parallelized stage collects into a function-ordered
        // Vec (`par_iter().map()/.flat_map().collect()` is indexed), so the
        // emitted object bytes AND the ordered proof bundle are byte-identical to
        // the serial path regardless of thread scheduling. The proof-certificate
        // lane remains serial under the shared BENCH-8 guard
        // (`proof_promotion_live_solver_may_run`): the x86-64 walk replays one
        // source-bound body theorem live per admitted function; regalloc and
        // encoding still use the configured parallelism.
        let use_parallel = self.config.parallel;

        // Phase 1: Run ISel per function. Each X86ISelFunction is
        // independent (no shared mutable state), so this is straightforward
        // sequential work; parallelization is a follow-up (mirrors the
        // AArch64 `prepared_funcs` vector).
        //
        // [MEM-STREAM] This loop CONSUMES `lir_functions`. On a batched CGU the
        // whole-module LIR is the single largest intermediate the backend holds
        // (measured: ~24 KB/function, ~57 MB on a 2400-function crate), and it
        // is dead the moment a function's ISel output has passed the TV-3
        // dataflow-integrity gate — which is why that gate, previously a second
        // whole-module loop below, now runs INSIDE this one. Each LIR function
        // is dropped as soon as it has been lowered AND checked, so the LIR and
        // ISel forms of the module are never both fully resident.
        //
        // The one consumer that still needs the whole-CGU LIR after this point
        // is the `verify`-gated proof-certificate lane, which pairs each
        // POST-OPTIMIZATION ISel function with the LIR function it came from.
        // When that lane will run, the LIR is retained instead of dropped (and
        // the lane re-checks the retained count, so a future edit that releases
        // it cannot silently produce an empty certificate bundle).
        let isel_start = Instant::now();
        let mut isel_funcs: Vec<trust_cg_lower::x86_64_isel::X86ISelFunction> =
            Vec::with_capacity(function_count);
        let retain_lir_for_certs =
            self.config.emit_proofs || self.requires_verified_proof_promotion();
        let mut retained_lir: Vec<(trust_cg_lower::Function, trust_cg_lower::ProofContext)> =
            Vec::with_capacity(if retain_lir_for_certs {
                function_count
            } else {
                0
            });
        // The policy is unconditional and non-bypassable: without validator replay every carrier
        // is kept and later expanded to a runtime check.
        let kernel_gate_on = guard_kernel_gate_enabled();
        let mut x86_guard_elim_eliminated: u32 = 0;
        for (lir_func, proof_ctx) in lir_functions {
            use trust_cg_lower::x86_64_isel::X86InstructionSelector;
            lir_func.validate_eh_structure().map_err(|reason| {
                CompileError::Pipeline(PipelineError::Unwind(format!(
                    "invalid x86 exception-handling structure in `{}`: {reason}",
                    lir_func.name
                )))
            })?;
            let sig = trust_cg_lower::function::Signature {
                params: lir_func.signature.params.clone(),
                returns: lir_func.signature.returns.clone(),
            };
            let mut isel =
                X86InstructionSelector::with_abi(lir_func.name.clone(), sig.clone(), call_abi);
            // Keep parity with X86Pipeline::compile_trust_ir_function: StackAddr
            // lowering needs the adapter's fixed/runtime stack-slot metadata.
            isel.set_stack_slots(lir_func.stack_slots.clone());
            isel.seed_value_types(&lir_func.value_types);
            isel.seed_function_value_use_counts(&lir_func);
            isel.seed_pure_callees(&lir_func.pure_callees);
            // The indirect-return (`sret`) convention: which parameter of THIS
            // function is the hidden return buffer, and which callees take one.
            // Both are ABI facts the frontend stated; neither is inferable from
            // the LIR's shape.
            isel.seed_sret_param(lir_func.abi_sret_param)
                .map_err(|e| CompileError::Pipeline(PipelineError::ISel(e.to_string())))?;
            isel.seed_sret_arg_callees(&lir_func.sret_arg_callees);
            isel.seed_sret_arg_indirect_callees(&lir_func.sret_arg_indirect_callees);
            let block_order = lir_func.layout_order();
            // Seed the whole-function Iconst origin map so constant-divisor
            // recognition (magic unsigned div/rem strength reduction) and
            // cross-block constant rematerialization can see every `Iconst`.
            isel.seed_iconst_origins(
                block_order
                    .iter()
                    .map(|b| lir_func.blocks[b].instructions.as_slice()),
            );
            for block_ref in &block_order {
                isel.ensure_block(*block_ref);
            }
            isel.lower_formal_arguments(&sig, lir_func.entry_block)
                .map_err(|e| CompileError::Pipeline(PipelineError::ISel(e.to_string())))?;
            for block_ref in &block_order {
                let basic_block = &lir_func.blocks[block_ref];
                if *block_ref != lir_func.entry_block && !basic_block.params.is_empty() {
                    isel.define_block_params(&basic_block.params);
                }
                isel.select_block(*block_ref, &basic_block.instructions)
                    .map_err(|e| CompileError::Pipeline(PipelineError::ISel(e.to_string())))?;
            }
            let mut isel_func = isel
                .finalize_with_eh_info(&lir_func.eh_info)
                .map_err(|e| CompileError::Pipeline(PipelineError::Unwind(e.to_string())))?;

            // Sentinel S5: kernel-gated proof-driven bounds-check elimination.
            if kernel_gate_on {
                run_x86_guard_kernel_gate(
                    &mut isel_func,
                    &proof_ctx,
                    trust_ir_module,
                    &mut x86_guard_elim_eliminated,
                )
                .map_err(|reason| {
                    CompileError::Pipeline(PipelineError::IsaGuardKernelRecheckRejected {
                        isa: "x86",
                        function: lir_func.name.clone(),
                        reason,
                    })
                })?;
            }

            // TV-3: block-level lowering-integrity validation on the RAW
            // pre-pass ISel output. MUST run here (before the optimizer passes
            // below), which do not preserve TV-1 provenance stamps. Default
            // ENFORCE on x86. [MEM-STREAM] It used to be a second whole-module
            // loop after ISel; running it per function, immediately after the
            // guard gate, checks exactly the same pairs in exactly the same
            // order against exactly the same (raw, post-guard-gate) ISel output
            // — and is what lets this function's LIR be released below.
            enforce_x86_dataflow_integrity(&isel_func, &lir_func)?;
            // VOL-2: selection emitted exactly the volatile accesses the LIR
            // asked for. Must run on the RAW pre-pass output, like the check
            // above, so a selection defect is not attributed to the optimizer.
            check_volatile_lowering_faithful(&lir_func, &isel_func)?;

            isel_funcs.push(isel_func);
            // [MEM-STREAM] Release this function's LIR unless the certificate
            // lane below still needs it.
            if retain_lir_for_certs {
                retained_lir.push((lir_func, proof_ctx));
            }
        }
        let _ = x86_guard_elim_eliminated;
        // Only the `verify`-gated certificate lane reads the retained LIR;
        // without that feature the retention decision is always "release" and
        // the vector is empty.
        #[cfg(feature = "verify")]
        let lir_functions = retained_lir;
        #[cfg(not(feature = "verify"))]
        drop(retained_lir);
        memtrace("x86/after_isel");

        if tracing {
            trace_entries.push(TraceEntry {
                phase: "x86_isel".to_string(),
                duration: isel_start.elapsed(),
                detail: Some(format!("{} functions", function_count)),
            });
        }

        let x86_opt_level = x86_opt_level_from_codegen(self.config.opt_level);
        // Raw dataflow validation above is the final consumer of the
        // pre-optimization graph. Transfer ownership into optimization rather
        // than retaining and deep-cloning an otherwise-dead copy of every
        // instruction, operand, block, and side table.
        let mut optimized_isel_funcs = isel_funcs;
        let opt_start = Instant::now();
        let optimization_passes_run: usize = {
            let pipeline = X86Pipeline::new(X86PipelineConfig {
                opt_level: x86_opt_level,
                output_format: X86OutputFormat::RawBytes,
                emit_frame: true,
                call_abi,
                // The machine passes follow the same certificate policy as
                // the object pipeline below (the O2 fixpoint bound reads it).
                allocation_quality: x86_object_allocation_quality(
                    self.config.emit_proofs,
                    self.config.x86_certificate_free_allocation,
                ),
                ..X86PipelineConfig::default()
            });
            let mut total = 0usize;
            for func in optimized_isel_funcs.iter_mut() {
                // VOL-1: bracket the optimizer with the volatile ACCESS TRACE
                // obligation and fail the compile CLOSED if it moved one. This
                // is the only place such a change can be caught: a volatile MOV
                // encodes byte-identically to the plain form, so no downstream
                // decode check can tell that an access went missing.
                let before = trust_cg_verify::x86_volatile_trace::machine_volatile_trace(func);
                total += pipeline.run_x86_optimization_passes(func).total_pass_runs();
                check_volatile_trace_preserved(&func.name.clone(), &before, func)?;
            }
            total
        };
        if tracing {
            trace_entries.push(TraceEntry {
                phase: "x86_optimization".to_string(),
                duration: opt_start.elapsed(),
                detail: Some(format!("{} pass runs", optimization_passes_run)),
            });
            // DIAGNOSTIC (default off, `TCG_TIME_X86PM=1`): split the
            // `x86_optimization` row above into its per-pass constituents.
            if let Some(report) = trust_cg_opt::x86_pass_timing_report() {
                eprint!("{report}");
            }
        }
        memtrace("x86/after_opt");

        // PROOF-GAP item 1 + 3: fail-closed gates that run UNCONDITIONALLY (NOT
        // behind the `verify` feature), so they keep the AOT object path honest
        // on the DEFAULT build (the rustc bridge uses `default-features =
        // false`). Carrier hygiene is a pure lattice check. The glue-pass
        // validator is exhaustive only inside its lanes (≤ 2 inputs, ≤ 8 bits);
        // its width-32 popcount canary is discharged by the committed portable
        // DRAT certificate when this host's checker identity is qualified in
        // `canary_certs/manifest.v1`, and otherwise by the live solver — where
        // an unqualified host is named in the refusal rather than filed as a
        // solver gap (`canary_cert::cert_skip_miss_reason`).
        //   * carrier-hygiene: PER-PROGRAM — checks each emitted function for the
        //     #51/#66 dirty-narrow-carrier hazard (a real per-program gate).
        //   * glue-pass validator: PER-PROGRAM (proof-gap item 3, #67) — derives
        //     the overflow expansions THIS program's emitted X86ISelFunctions
        //     contain (structural IMUL->IDIV safety net + idiom enumeration) and
        //     re-verifies each distinct one; the fixed model canary is folded in
        //     as a memoized baseline. See `validate_x86_glue_pass_expansions`.
        for func in &optimized_isel_funcs {
            check_x86_carrier_hygiene(func)?;
        }

        // Count non-pseudo ISel instructions after x86 optimization. This is
        // the x86 analogue of counting prepared AArch64 machine instructions.
        let instruction_count: usize = optimized_isel_funcs
            .iter()
            .map(count_x86_real_instructions)
            .sum();

        // One authoritative native-output pipeline owns the module assembly.
        // Its encoded result is shared by metrics, the optional relocation
        // proof inventory, and final object emission; none of those consumers
        // may independently re-run regalloc, frame lowering, or encoding.
        let macho_build_version = if output_format == X86OutputFormat::MachO {
            crate::apple_deployment::MachOBuildVersion::for_target_triple(&compiler_target_triple(
                target_spec,
            ))
            .map_err(PipelineError::from)?
        } else {
            crate::apple_deployment::MachOBuildVersion::DEFAULT
        };
        let object_pipeline = X86Pipeline::new(X86PipelineConfig {
            opt_level: x86_opt_level,
            output_format,
            emit_frame: true,
            call_abi,
            panic_unwind: self.config.panic_unwind,
            macho_build_version,
            weak_function_definitions: weak_function_definitions(trust_ir_module),
            allocation_quality: x86_object_allocation_quality(
                self.config.emit_proofs,
                self.config.x86_certificate_free_allocation,
            ),
            ..X86PipelineConfig::default()
        });

        validate_x86_glue_pass_expansions(
            &optimized_isel_funcs,
            object_pipeline.config.target_features,
        )?;

        #[cfg(feature = "verify")]
        let proof_certs_start = Instant::now();
        // CT-8 (encode reuse): when the proof-cert lane runs, the module is
        // regalloc'd + encoded + assembled ONCE here; the relocation
        // inventory reads the assembly, and the final object emission below
        // REUSES it (Phase-2 emit only) instead of re-running the full
        // encode — previously a redundant third full encode. The assemble
        // duration is attributed to the `x86_compile_module` trace phase
        // (not the cert lane), so the proof-lane number stays honest.
        #[cfg(feature = "verify")]
        let (proofs, assembled_for_emit, proof_lane_assemble_duration): (
            Option<Vec<ProofCertificate>>,
            Option<crate::x86_64::pipeline::X86AssembledModule>,
            Duration,
        ) = if self.config.emit_proofs || self.requires_verified_proof_promotion() {
            // [MEM-STREAM] fail-closed re-check of the LIR retention decision
            // taken at ISel time. This lane is the only consumer of the
            // whole-CGU LIR after ISel; if it were ever entered with the LIR
            // released, the zip below would silently yield ZERO per-function
            // certificates and the bundle would look "clean" while proving
            // nothing. Refuse instead.
            if lir_functions.len() != optimized_isel_funcs.len() {
                return Err(CompileError::ProofLaneLirIncomplete {
                    retained: lir_functions.len(),
                    required: optimized_isel_funcs.len(),
                });
            }
            let proof_environment =
                trust_cg_process_env::EnvOverrideSnapshot::capture_current_thread();
            // Resolved on this thread before the assembly below runs ENC-3
            // under the same environment (`x86_enc3_backing_of_this_compile`).
            let enc3 = x86_enc3_backing_of_this_compile();
            let mut all_certs: Vec<ProofCertificate> = Vec::new();
            let assemble_start = Instant::now();
            let assembled = object_pipeline
                .assemble_module_after_x86_passes(&optimized_isel_funcs, use_parallel)
                .map_err(|e| CompileError::Pipeline(x86_pipeline_error_to_pipeline_error(e)))?;
            let assemble_duration = assemble_start.elapsed();
            // Every table the emitter will write for this assembly — the
            // Mach-O `panic=unwind` walk-through filler LSDAs included — is
            // refused before the inventory and certificate lanes run.
            exception_tables = exception_tables.with_functions(
                object_pipeline
                    .exception_table_functions(&assembled)
                    .map_err(|e| CompileError::Pipeline(x86_pipeline_error_to_pipeline_error(e)))?,
            );
            if self.requires_verified_proof_promotion() {
                exception_tables
                    .refuse_proof_grade(ProofGradeRoute::CertifiedObject, Target::X86_64)?;
            }
            let relocation_report = object_pipeline
                .relocation_inventory_report_for_assembled(
                    &assembled,
                    &object_globals,
                    format!("{}-module.o", compiler_target_triple(self.target_spec)),
                )
                .map_err(|e| CompileError::Pipeline(x86_pipeline_error_to_pipeline_error(e)))?;
            append_object_relocation_inventory_certificate(&mut all_certs, &relocation_report);
            // TV-2: `optimized_isel_funcs` preserves the 1:1 construction
            // order of `lir_functions`, so the zip pairs each ISel function
            // with the LIR function it consumed; the verifier additionally
            // name-guards the pairing.
            //
            // CT-5: per-function certificate generation is the other dominant
            // compile-time cost (the "cert lane"). It runs the shared, read-only
            // `&'static` x86 function verifier (a `ProofDatabase` lookup +
            // structural reconstruction, memoized under a sharded process-wide
            // compute-once memo — no per-function shared mutable state), so it
            // parallelizes cleanly.
            // `par_iter().flat_map().collect()` preserves function order, so the
            // ordered cert bundle (and its `proof_bundle_sha256` cache key) is
            // byte-identical to the serial path.
            //
            // SOLVER SERIALIZATION (BENCH-8): the shared guard keeps certificate
            // generation serial so several function workers cannot drive AY
            // concurrently. (The x86-64 walk replays only the source-bound body
            // theorem, once per admitted function, before its per-instruction
            // pre-pass; the guard is shared with AArch64.)
            //
            // CT-7: the cert lane's pool width comes from
            // `verification_worker_count_for_items` (the shared large-stack
            // verifier policy), NOT the regalloc+encode cap. All functions and
            // their nested instruction pre-passes submit to one process-wide
            // 32 MiB-stack pool, so the safe default is small while an explicit
            // operator limit remains available. Width never affects output
            // (function-ordered collect).
            let cert_worker_count = if use_parallel && !proof_promotion_live_solver_may_run() {
                crate::resource_limits::verification_worker_count_for_items(
                    optimized_isel_funcs.len(),
                )?
            } else {
                None
            };
            // One verification request serves the whole module; it is
            // captured only if some function is admitted by the x86-64
            // source-bound body lane.
            let module_request = X86ModuleVerificationRequest::new();
            // OD-210: the module's own definitions of the runtime routines a
            // body theorem would trust (its `I128` divisions', its C memory
            // routines'): such a theorem is refused, whatever else the link
            // binds. OD-216: and the definitions the frontend names for the
            // rest of its link unit (the crate's other codegen units).
            let module_definitions =
                trust_cg_verify::X86ModuleDefinitions::of_trust_ir_module(trust_ir_module)
                    .with_link_unit(self.config.link_unit_definitions.iter().map(String::as_str));
            let per_func_certs: Vec<ProofCertificate> = if let Some(worker_count) =
                cert_worker_count
            {
                let pool = crate::resource_limits::build_rayon_pool(worker_count)
                    .map_err(|err| CompileError::Pipeline(PipelineError::WorkerPool(err)))?;
                pool.install(|| {
                    optimized_isel_funcs
                        .par_iter()
                        .zip(lir_functions.par_iter())
                        .flat_map(|(func, (lir_func, _))| {
                            proof_environment.run(|| {
                                generate_x86_64_proof_certificates_in_module(
                                    func,
                                    Some(lir_func),
                                    call_abi,
                                    &module_request,
                                    &module_definitions,
                                    enc3,
                                )
                            })
                        })
                        .collect()
                })
            } else {
                let mut certs = Vec::new();
                for (func, (lir_func, _)) in optimized_isel_funcs.iter().zip(lir_functions.iter()) {
                    certs.extend(generate_x86_64_proof_certificates_in_module(
                        func,
                        Some(lir_func),
                        call_abi,
                        &module_request,
                        &module_definitions,
                        enc3,
                    ));
                }
                certs
            };
            all_certs.extend(per_func_certs);
            (Some(all_certs), Some(assembled), assemble_duration)
        } else {
            (None, None, Duration::ZERO)
        };
        #[cfg(feature = "verify")]
        if tracing {
            // CT-7: attribute the proof-certificate lane (relocation-inventory
            // rows + per-function verification/discharge) in the TCG_TIME
            // trace so proofs-on compile-time claims are falsifiable per
            // phase. CT-8: the module ENCODE the lane shares with the final
            // object emission is subtracted here and reported under
            // `x86_compile_module` instead (it is module-encode work, not
            // cert work).
            trace_entries.push(TraceEntry {
                phase: "x86_proof_certs".to_string(),
                duration: proof_certs_start
                    .elapsed()
                    .saturating_sub(proof_lane_assemble_duration),
                detail: Some(format!(
                    "{} certs",
                    proofs.as_deref().map(<[_]>::len).unwrap_or(0)
                )),
            });
        }
        #[cfg(not(feature = "verify"))]
        let (proofs, assembled_for_emit, proof_lane_assemble_duration): (
            Option<Vec<ProofCertificate>>,
            Option<crate::x86_64::pipeline::X86AssembledModule>,
            Duration,
        ) = (None, None, Duration::ZERO);
        self.ensure_object_proofs_promotable(proofs.as_deref(), &exception_tables)?;
        let proof_bundle_sha256 = proof_bundle_sha256(proofs.as_deref());

        // If proofs did not need relocation inventory, assemble now. This is
        // the ONLY proof-off backend traversal: the same native-format value
        // supplies code-size metrics and is consumed by final object emission.
        // EH sidecars, COFF `.rdata` pools, call/global fixups, and serial vs.
        // parallel assembly therefore cannot drift between a metrics probe and
        // the bytes returned to the caller.
        let encode_start = Instant::now();
        let assembled_for_emit = match assembled_for_emit {
            Some(assembled) => assembled,
            None => object_pipeline
                .assemble_module_after_x86_passes(&optimized_isel_funcs, use_parallel)
                .map_err(|e| CompileError::Pipeline(x86_pipeline_error_to_pipeline_error(e)))?,
        };
        let total_code_size = assembled_for_emit.code_size();
        memtrace("x86/after_assemble");

        // Final native object bytes from the authoritative assembly.
        // Cross-function CALL fixups become X86_64_RELOC_BRANCH relocations on
        // Mach-O, R_X86_64_PLT32 on ELF, and IMAGE_REL_AMD64_REL32 on COFF.
        let mut compile_artifact_cache_telemetry = Vec::new();
        let cached_object = if let Some(context) = &cache_context {
            match lookup_compile_artifact(
                &context.cache,
                &context.key,
                context.boundary,
                proof_bundle_sha256.as_deref(),
                &context.reuse_permit,
            )? {
                Some(CompileArtifactCacheLookup::Hit { entry, telemetry }) => {
                    compile_artifact_cache_telemetry.push(telemetry);
                    Some(entry.artifact_bytes)
                }
                Some(CompileArtifactCacheLookup::Miss { telemetry })
                | Some(CompileArtifactCacheLookup::Rejected { telemetry }) => {
                    compile_artifact_cache_telemetry.push(telemetry);
                    None
                }
                None => None,
            }
        } else {
            None
        };
        // Every function definition the object emits is bound as its
        // trust-ir linkage dictates (module-local ones local), read back from
        // the object bytes, fresh before it is cached and cached alike.
        let check_function_bindings = |object: &[u8]| {
            let format = match output_format {
                X86OutputFormat::Elf => BindingCheckFormat::Elf,
                X86OutputFormat::MachO => BindingCheckFormat::MachO,
                X86OutputFormat::Coff => BindingCheckFormat::Coff,
                X86OutputFormat::RawBytes => return Ok(()),
            };
            check_object_function_bindings(
                &compiler_target_triple(target_spec),
                format,
                object,
                trust_ir_module,
                optimized_isel_funcs.iter().map(|func| func.name.as_str()),
            )
        };
        let obj_bytes = if let Some(bytes) = cached_object {
            check_function_bindings(&bytes)?;
            bytes
        } else {
            // The symbol-table facts the trust-ir module states for the
            // functions this object defines: a module-local definition binds
            // STB_LOCAL on ELF, non-external on Mach-O and static on COFF, a
            // hidden `External` one is a Mach-O private extern or STV_HIDDEN
            // on ELF (see `x86_64_function_symbol_facts`).
            let function_symbols = x86_64_function_symbol_facts(
                &compiler_target_triple(self.target_spec),
                output_format,
                trust_ir_module,
                optimized_isel_funcs.iter().map(|func| func.name.as_str()),
            )?;
            let bytes = object_pipeline
                .emit_assembled_module_with_function_symbols(
                    assembled_for_emit,
                    &object_globals,
                    &function_symbols,
                )
                .map_err(|e| CompileError::Pipeline(x86_pipeline_error_to_pipeline_error(e)))?;
            check_function_bindings(&bytes)?;
            if let Some(context) = &cache_context
                && let Some(telemetry) = store_compile_artifact(
                    &context.cache,
                    &context.key,
                    context.boundary,
                    &bytes,
                    "trust-cg-codegen::Compiler::compile_x86_64",
                    proof_bundle_sha256.as_deref(),
                    &context.reuse_permit,
                )?
            {
                compile_artifact_cache_telemetry.push(telemetry);
            }
            bytes
        };
        // The x86-64 ELF exemption from the module-local identity refusals is
        // backed by the OBJECT BYTES, for a fresh object and a cached one
        // alike: every symbol and relocation spelling a bodied
        // Internal/Private function must be its local definition
        // (`STB_LOCAL`), and no non-local alias may overlap it
        // (`check_elf_module_local_function_binding`, the same reader the
        // AArch64 ELF path uses). This is the x86-64 half of ruling
        // OD-X86-ELF-LOCAL-BINDING-20261027.
        //
        // The predicate that admitted the module's own references to those
        // definitions reads the TRIPLE, while the emitter writes the format
        // `x86_64_aot_output_format_for_target_spec` derives from the target
        // SPEC. They agree for every triple this compiler accepts; a
        // disagreement is refused here rather than left to a symbol table
        // that would then bind a local definition global (or refuse the fact
        // at emission, depending on which way they disagree).
        let binds_module_local_functions = self.object_binds_module_local_functions();
        let target_triple = compiler_target_triple(target_spec);
        if binds_module_local_functions
            != matches!(output_format, X86OutputFormat::Elf | X86OutputFormat::MachO)
        {
            return Err(CompileError::Pipeline(PipelineError::ObjectEmission(
                format!(
                    "x86-64 object symbol binding: the module-local binding predicate says \
                     {binds_module_local_functions} for `{target_triple}` but the emitter writes \
                     {output_format:?}; the ELF and Mach-O emitters' references to a module-local \
                     definition are read back as reaching its local symbol (fail-closed)"
                ),
            )));
        }
        if matches!(output_format, X86OutputFormat::Elf) {
            let module_local_binding = if binds_module_local_functions {
                ModuleLocalBindingExpectation::for_module(trust_ir_module)
            } else {
                ModuleLocalBindingExpectation::empty()
            };
            check_elf_module_local_function_binding(
                &target_triple,
                &obj_bytes,
                &module_local_binding,
            )?;
            if binds_module_local_functions {
                // The price of the exemption: a reference that must reach
                // code may not resolve into data (a runtime call or
                // personality spelled like one of the module's own data
                // definitions), re-read from the bytes.
                check_elf_code_references_reach_code(
                    &target_triple,
                    &obj_bytes,
                    &X86_64_ELF_BRANCH_RELOCATIONS,
                )?;
            }
        }
        if matches!(output_format, X86OutputFormat::MachO) {
            let expected = ModuleLocalBindingExpectation::for_module(trust_ir_module);
            check_x86_64_macho_module_local_function_binding(
                &target_triple,
                &obj_bytes,
                &expected,
            )?;
            check_x86_64_macho_code_references_reach_code(&target_triple, &obj_bytes)?;
        }
        memtrace("x86/after_emit");
        if tracing {
            // Fold a proof lane's earlier shared assembly into this phase; a
            // proof-off assembly is already inside `encode_start.elapsed()`.
            // Thus every backend traversal is reported exactly once under the
            // module phase and none is hidden in the metrics path.
            let encode_duration = encode_start.elapsed() + proof_lane_assemble_duration;
            trace_entries.push(TraceEntry {
                phase: "x86_compile_module".to_string(),
                duration: encode_duration,
                detail: Some(format!("{} functions", function_count)),
            });
            // DIAGNOSTIC (default off, `TCG_TIME_X86FN=1`): split the
            // `x86_compile_module` row above into its per-function backend
            // stages (regalloc, post-regalloc fixups, frame lowering, the
            // TV-4/TV-5 recheck, encoding) and rank the slowest functions.
            if let Some(report) = crate::x86_64::backend_timing::report() {
                eprint!("{report}");
            }
        }

        let metrics = CompilationMetrics {
            code_size_bytes: total_code_size,
            instruction_count,
            function_count,
            optimization_passes_run,
            proof_optimizations: ProofOptimizationMetrics::default(),
            fsym_trust_ir: FsymTrustIrMetrics::default(),
            pass_validation: trust_cg_opt::PassValidationSummary::default(),
            composed_transitions: Vec::new(),
            composed_publications: 0,
        };

        let trace = if tracing {
            Some(CompilerTrace {
                entries: trace_entries,
                total_duration: total_start.elapsed(),
            })
        } else {
            None
        };

        Ok(CompilationResult {
            aarch64_frame_inputs: Vec::new(),
            object_code: obj_bytes,
            metrics,
            trace,
            proofs,
            certified_pass_chain: self.certified_pass_chain.clone(),
            proof_optimization_certificates: Vec::new(),
            compile_artifact_cache_telemetry,
            target_selection: self.target_selection(),
            inline_only_bodies: Default::default(),
            stack_limits: None,
            dialect_legalization: None,
        })
    }

    /// ITEM 2 — RISC-V production path through `Compiler::compile`.
    ///
    /// This is the SMALLEST SOUND increment that makes proof-driven bounds-check
    /// elimination reachable for `Target::Riscv64`. It mirrors the per-function
    /// ISel+gate loop of [`Self::compile_x86_64`] using the minimal, fail-closed
    /// RISC-V selector ([`crate::riscv::isel::select_function`]) and the existing
    /// S5 carrier/pass/expansion in [`crate::riscv::pipeline`].
    ///
    /// # Soundness boundary (fail-closed)
    ///
    /// The RISC-V backend has real liveness + linear-scan + spilling regalloc
    /// (phase 1), structured multi-block control flow (phase 2), self-recursive
    /// LP64D-ABI calls (phase 3), and — as of phase 4 — multi-function module
    /// emission with cross-function direct calls. This path accepts ONLY the
    /// function class the pipeline compiles correctly (integer args in `a0..a7`,
    /// a small opcode set + `Jump`/`Brif`/`Icmp`/`Trap` structured control flow
    /// over multiple blocks + the `GuardBoundsCheck` carrier + direct
    /// self/cross-function calls) and returns a clear `CompileError` for
    /// everything else (indirect/variadic calls, `Switch`, FP/vector, non-entry
    /// block params) — it NEVER silently miscompiles. The elimination decision
    /// flows through the SAME shared Certified-Elimination Kernel as x86/AArch64,
    /// with the same fail-closed independent re-check.
    ///
    /// Multiple accepted functions are concatenated into one `.text` section with
    /// a per-function `STT_FUNC` symbol. Intra-function branches are PC-relative
    /// and resolved within each function's own byte range (phase 2). A direct call
    /// to ANOTHER function in the same module is lowered to an `AUIPC`+`JALR`
    /// pcrel pair and resolved PC-relatively at module-emit time against the
    /// callee's `.text` offset — intra-object, no linker needed. A direct call to
    /// an EXTERNAL symbol (not defined in this module) is left as the placeholder
    /// `AUIPC`+`JALR` pair and recorded as an `R_RISCV_CALL` relocation in
    /// `.rela.text` for a real linker to patch. An in-module callee outside the
    /// signed-32-bit AUIPC reach fails closed.
    fn compile_riscv(
        &self,
        lir_functions: Vec<(trust_cg_lower::Function, trust_cg_lower::ProofContext)>,
        total_start: Instant,
        tracing: bool,
        mut trace_entries: Vec<TraceEntry>,
        trust_ir_module: &trust_ir::Module,
    ) -> Result<CompilationResult, CompileError> {
        use crate::riscv::isel::select_function;
        use crate::riscv::pipeline::{
            RiscVPipeline, RiscVPipelineConfig, validate_riscv_elf_symbol_name,
        };

        // RISC-V proof emission is not yet implemented; honor `emit_proofs` as a
        // typed error rather than silently returning `proofs: None`.
        if self.config.emit_proofs {
            return Err(CompileError::ProofsUnsupportedForTarget {
                target: Target::Riscv64,
            });
        }

        // trust-ir v41 `Global.section`: the RISC-V object path places no
        // per-global sections. Refuse by name rather than drop the request.
        if let Some(global) = trust_ir_module
            .globals
            .iter()
            .find(|global| global.section.is_some())
        {
            return Err(CompileError::Pipeline(
                PipelineError::ExplicitSectionUnsupported {
                    global: global.name.clone(),
                    section: global.section.clone().unwrap_or_default(),
                    format: "RISC-V ELF",
                    code: crate::object_sections::SectionRefusal::TargetUnsupported,
                    reason: "the RISC-V object path places no per-global sections".to_string(),
                },
            ));
        }

        let function_count = lir_functions.len();
        if function_count == 0 {
            return Err(CompileError::DispatcherEmptyModule {
                dispatcher: "RISC-V",
            });
        }

        // Same unconditional empty-authority policy as x86/AArch64.
        let kernel_gate_on = guard_kernel_gate_enabled();
        let mut riscv_guard_elim_eliminated: u32 = 0;

        // Phase 1: select each function (fail-closed), run the kernel gate, then
        // compile to raw machine-code bytes via the existing RISC-V pipeline.
        let isel_start = Instant::now();
        let pipeline = RiscVPipeline::new(RiscVPipelineConfig {
            emit_elf: false,
            emit_frame: true,
        });

        let mut per_func_code: Vec<(String, Vec<u8>, Vec<crate::riscv::pipeline::RiscVCallFixup>)> =
            Vec::with_capacity(function_count);
        for (lir_func, proof_ctx) in &lir_functions {
            let mut isel_func = select_function(lir_func).map_err(|e| {
                CompileError::Pipeline(PipelineError::ISel(format!(
                    "RISC-V minimal ISel rejected `{}`: {e}. The RISC-V production path \
                     supports integer-ABI functions with structured control flow \
                     (Jump/Brif/Icmp/Trap over multiple blocks; guard-bearing bounds-check \
                     shapes) and direct cross-function/self calls, but NOT indirect/variadic \
                     calls, Switch, FP/vector, or non-entry block params; use a different \
                     target for those.",
                    lir_func.name
                )))
            })?;

            // Sentinel S5: kernel-gated proof-driven bounds-check elimination.
            if kernel_gate_on {
                run_riscv_guard_kernel_gate(
                    &mut isel_func,
                    proof_ctx,
                    trust_ir_module,
                    &mut riscv_guard_elim_eliminated,
                )
                .map_err(|reason| {
                    CompileError::Pipeline(PipelineError::IsaGuardKernelRecheckRejected {
                        isa: "RISC-V",
                        function: lir_func.name.clone(),
                        reason,
                    })
                })?;
            }

            // Cross-function direct calls are lowered to an AUIPC+JALR pcrel pair
            // carrying a Symbol placeholder; the per-function encoder cannot
            // resolve the callee's address, so it reports each as a
            // `RiscVCallFixup` the module emitter resolves below (intra-object
            // patch or external relocation).
            let (code, fixups) =
                pipeline
                    .compile_function_with_fixups(&isel_func)
                    .map_err(|e| {
                        CompileError::Pipeline(PipelineError::ISel(format!(
                            "RISC-V pipeline failed on `{}`: {e}",
                            lir_func.name
                        )))
                    })?;
            per_func_code.push((lir_func.name.clone(), code, fixups));
        }
        let _ = riscv_guard_elim_eliminated;

        // Validate every definition and relocation-target name BEFORE layout,
        // call resolution, or writer mutation: the ELF string table turns an
        // empty name into its null sentinel and truncates an embedded NUL into
        // a different symbol identity, so an object built from either names
        // something other than what the module meant.
        for (name, _code, fixups) in &per_func_code {
            validate_riscv_elf_symbol_name(name, "defined function").map_err(|error| {
                CompileError::Pipeline(PipelineError::ObjectEmission(error.to_string()))
            })?;
            for fixup in fixups {
                validate_riscv_elf_symbol_name(&fixup.callee, "call relocation target").map_err(
                    |error| {
                        CompileError::Pipeline(PipelineError::ObjectEmission(error.to_string()))
                    },
                )?;
            }
        }

        if tracing {
            trace_entries.push(TraceEntry {
                phase: "riscv_isel".to_string(),
                duration: isel_start.elapsed(),
                detail: Some(format!("{} functions", function_count)),
            });
        }

        // Phase 2: concatenate all functions into one .text section (4-byte
        // aligned per function) and emit a single ELF .o with a per-function
        // STT_FUNC symbol at its offset, then resolve cross-function direct calls.
        //
        // CROSS-FUNCTION CALLS (phase 4): each function reports its cross-function
        // calls as `RiscVCallFixup`s (AUIPC+JALR pcrel pair, function-relative
        // offsets). After laying out .text, we resolve each fixup:
        //  * callee DEFINED in this module + within signed-32-bit AUIPC reach ->
        //    patch the AUIPC hi20 / JALR lo12 in `.text` PC-relatively. No
        //    relocation: the object is self-contained and runs without a linker.
        //  * callee NOT in this module (external) -> record one R_RISCV_CALL
        //    relocation at the AUIPC's section offset against an undefined
        //    STT_FUNC symbol, leaving the AUIPC+JALR placeholders for a real
        //    linker to patch (the ELF writer already supports .rela.text).
        //  * otherwise (in-module but unreachable) -> FAIL CLOSED with a typed
        //    error; never emit a zero/wrong call target.
        let encode_start = Instant::now();
        let mut text: Vec<u8> = Vec::new();
        // (name, section_offset, size, fixups-with-section-relative-offsets).
        let mut func_layout: Vec<(
            String,
            u64,
            u64,
            Vec<crate::riscv::pipeline::RiscVCallFixup>,
        )> = Vec::with_capacity(per_func_code.len());
        for (name, code, fixups) in &per_func_code {
            // 4-byte align each function start (RISC-V instruction alignment).
            while !text.len().is_multiple_of(4) {
                text.push(0);
            }
            let offset = text.len() as u64;
            text.extend_from_slice(code);
            // Rebase each fixup's function-relative offsets to section-relative.
            // RiscVCallFixup deliberately uses u32 offsets because AUIPC+JALR
            // patching is confined to that address domain. Never truncate or
            // wrap a large module offset onto an unrelated instruction.
            let rebased: Vec<crate::riscv::pipeline::RiscVCallFixup> = fixups
                .iter()
                .map(|fixup| rebase_riscv_call_fixup(name, offset, fixup))
                .collect::<Result<_, CompileError>>()?;
            func_layout.push((name.clone(), offset, code.len() as u64, rebased));
        }

        // Map each DEFINED function name to its section offset (for intra-object
        // call resolution). Defined-symbol collisions are impossible here (the LIR
        // module already has unique function names).
        let defined_offsets: HashMap<String, u64> = func_layout
            .iter()
            .map(|(name, off, _size, _fx)| (name.clone(), *off))
            .collect();

        // Patch intra-object calls IN PLACE, and collect external calls for a
        // relocation pass after the symbol table is built. A call to a
        // definition this object binds `STB_WEAK` is relocated too: the
        // linker may keep another object's definition of that name, and the
        // call must reach the one it keeps.
        let bindings = RiscvFunctionBindings::for_module(trust_ir_module);
        let mut external_calls: Vec<crate::riscv::pipeline::RiscVCallFixup> = Vec::new();
        for (caller, _off, _size, fixups) in &func_layout {
            for fx in fixups {
                if bindings.weak.contains(&fx.callee) {
                    external_calls.push(fx.clone());
                } else if let Some(&callee_off) = defined_offsets.get(&fx.callee) {
                    let callee_off = u32::try_from(callee_off).map_err(|_| {
                        CompileError::Pipeline(PipelineError::ObjectEmission(format!(
                            "RISC-V intra-object call from `{caller}` targets `{}` at .text offset {callee_off}, outside the u32 patch domain",
                            fx.callee
                        )))
                    })?;
                    crate::riscv::pipeline::riscv_patch_intra_object_call(
                        &mut text,
                        fx.auipc_offset,
                        fx.jalr_offset,
                        callee_off,
                    )
                    .map_err(|e| {
                        CompileError::Pipeline(PipelineError::ObjectEmission(format!(
                            "RISC-V intra-object call from `{caller}` to `{}` could not be \
                             resolved: {e}",
                            fx.callee
                        )))
                    })?;
                } else {
                    external_calls.push(fx.clone());
                }
            }
        }

        let total_code_size = text.len();
        let instruction_count = total_code_size / 4;

        let obj_bytes = riscv_module_object(&text, &func_layout, &external_calls, &bindings)?;
        check_object_function_bindings(
            &compiler_target_triple(self.target_spec),
            BindingCheckFormat::Elf,
            &obj_bytes,
            trust_ir_module,
            func_layout.iter().map(|(name, ..)| name.as_str()),
        )?;

        if tracing {
            trace_entries.push(TraceEntry {
                phase: "riscv_emit".to_string(),
                duration: encode_start.elapsed(),
                detail: Some(format!("{} functions", function_count)),
            });
        }

        let metrics = CompilationMetrics {
            code_size_bytes: total_code_size,
            instruction_count,
            function_count,
            optimization_passes_run: 0,
            proof_optimizations: ProofOptimizationMetrics::default(),
            fsym_trust_ir: FsymTrustIrMetrics::default(),
            pass_validation: trust_cg_opt::PassValidationSummary::default(),
            composed_transitions: Vec::new(),
            composed_publications: 0,
        };

        let trace = if tracing {
            Some(CompilerTrace {
                entries: trace_entries,
                total_duration: total_start.elapsed(),
            })
        } else {
            None
        };

        Ok(CompilationResult {
            aarch64_frame_inputs: Vec::new(),
            object_code: obj_bytes,
            metrics,
            trace,
            proofs: None,
            certified_pass_chain: self.certified_pass_chain.clone(),
            proof_optimization_certificates: Vec::new(),
            compile_artifact_cache_telemetry: Vec::new(),
            target_selection: self.target_selection(),
            inline_only_bodies: Default::default(),
            stack_limits: None,
            dialect_legalization: None,
        })
    }

    fn compile_x86_64_to_jit(
        &self,
        lir_functions: Vec<(trust_cg_lower::Function, trust_cg_lower::ProofContext)>,
        extern_symbols: &HashMap<String, *const u8>,
        external_symbol_resolution: JitExternalSymbolResolutionPolicy,
        profile_hooks: crate::jit::ProfileHookMode,
        validation_mode: JitValidationMode,
        total_start: Instant,
        tracing: bool,
        mut trace_entries: Vec<TraceEntry>,
        module_definitions: &trust_cg_verify::X86ModuleDefinitions,
    ) -> Result<JitCompilationResult, CompileError> {
        use crate::x86_64::{X86OutputFormat, X86Pipeline, X86PipelineConfig};
        use trust_cg_lower::x86_64_isel::{X86CallAbi, X86InstructionSelector};

        let profile_call_counters_enabled = x86_profile_hooks_enable_call_counters(profile_hooks);
        let profile_block_counters_enabled = x86_profile_hooks_enable_block_counters(profile_hooks);
        if profile_hooks != crate::jit::ProfileHookMode::None
            && !profile_call_counters_enabled
            && !profile_block_counters_enabled
        {
            return Err(CompileError::Jit(
                crate::jit::JitError::ProfileHooksUnsupported,
            ));
        }

        #[cfg(not(feature = "verify"))]
        if self.config.emit_proofs {
            return Err(CompileError::ProofsUnsupportedForTarget {
                target: Target::X86_64,
            });
        }

        let function_count = lir_functions.len();
        if function_count == 0 {
            return Err(CompileError::EmptyModule);
        }

        // The AOT Mach-O and ELF object paths emit unwind tables, but the
        // in-memory JIT has no eh_frame, so a JIT function carrying EH structure
        // still fails closed (x86 JIT unwinding is a later lane).
        reject_x86_jit_eh(&lir_functions)?;

        let call_abi = x86_host_jit_abi();
        debug_assert!(
            matches!(call_abi, X86CallAbi::SystemV | X86CallAbi::WindowsX64),
            "x86 host JIT ABI must be known"
        );

        // The x86 JIT uses Rayon’s shared workers for several consecutive
        // phases. Transfer the request's complete override snapshot once so
        // ISel, optimization, validation, and encoding cannot silently fall
        // back to worker-global/default compile controls.
        let codegen_environment =
            trust_cg_process_env::EnvOverrideSnapshot::capture_current_thread();
        let isel_start = Instant::now();
        let isel_results: Vec<
            Result<
                (
                    trust_cg_lower::x86_64_isel::X86ISelFunction,
                    crate::pipeline::PhaseTimings,
                ),
                CompileError,
            >,
        > = lir_functions
            .par_iter()
            .map(|(lir_func, _proof_ctx)| {
                codegen_environment.run(|| {
                    let func_isel_start = Instant::now();
                    lir_func.validate_eh_structure().map_err(|reason| {
                        CompileError::Pipeline(PipelineError::Unwind(format!(
                            "invalid x86 exception-handling structure in `{}`: {reason}",
                            lir_func.name
                        )))
                    })?;
                    let sig = trust_cg_lower::function::Signature {
                        params: lir_func.signature.params.clone(),
                        returns: lir_func.signature.returns.clone(),
                    };
                    let mut isel = X86InstructionSelector::with_abi(
                        lir_func.name.clone(),
                        sig.clone(),
                        call_abi,
                    );
                    isel.set_stack_slots(lir_func.stack_slots.clone());
                    isel.seed_value_types(&lir_func.value_types);
                    isel.seed_function_value_use_counts(lir_func);
                    isel.seed_pure_callees(&lir_func.pure_callees);
                    // See the serial path above: the indirect-return convention
                    // is stated by the frontend, never inferred here.
                    isel.seed_sret_param(lir_func.abi_sret_param)
                        .map_err(|e| CompileError::Pipeline(PipelineError::ISel(e.to_string())))?;
                    isel.seed_sret_arg_callees(&lir_func.sret_arg_callees);
                    isel.seed_sret_arg_indirect_callees(&lir_func.sret_arg_indirect_callees);
                    let block_order = lir_func.layout_order();
                    // Seed the whole-function Iconst origin map (see the serial
                    // path above) — constant-divisor magic strength reduction and
                    // cross-block constant rematerialization both consume it.
                    isel.seed_iconst_origins(
                        block_order
                            .iter()
                            .map(|b| lir_func.blocks[b].instructions.as_slice()),
                    );
                    for block_ref in &block_order {
                        isel.ensure_block(*block_ref);
                    }
                    isel.lower_formal_arguments(&sig, lir_func.entry_block)
                        .map_err(|e| CompileError::Pipeline(PipelineError::ISel(e.to_string())))?;
                    for block_ref in &block_order {
                        let basic_block = &lir_func.blocks[block_ref];
                        if *block_ref != lir_func.entry_block && !basic_block.params.is_empty() {
                            isel.define_block_params(&basic_block.params);
                        }
                        isel.select_block(*block_ref, &basic_block.instructions)
                            .map_err(|e| {
                                CompileError::Pipeline(PipelineError::ISel(e.to_string()))
                            })?;
                    }
                    let mut timings = crate::pipeline::PhaseTimings::default();
                    timings.isel = Some(nonzero_duration(func_isel_start.elapsed()));
                    let isel_func = isel.finalize_with_eh_info(&lir_func.eh_info).map_err(|e| {
                        CompileError::Pipeline(PipelineError::Unwind(e.to_string()))
                    })?;
                    Ok((isel_func, timings))
                })
            })
            .collect();

        let mut isel_funcs = Vec::with_capacity(function_count);
        let mut phase_timings = Vec::with_capacity(function_count);
        for res in isel_results {
            let (func, timings) = res?;
            isel_funcs.push(func);
            phase_timings.push(timings);
        }

        // TV-3: block-level lowering-integrity validation on the RAW pre-pass
        // JIT ISel output (same fail-closed gate as the AOT path; the JIT is a
        // first-class G4 consumer). MUST run before the optimizer passes below.
        for (func, (lir_func, _)) in isel_funcs.iter().zip(lir_functions.iter()) {
            enforce_x86_dataflow_integrity(func, lir_func)?;
            check_volatile_lowering_faithful(lir_func, func)?;
        }

        if tracing {
            trace_entries.push(TraceEntry {
                phase: "x86_jit_isel".to_string(),
                duration: isel_start.elapsed(),
                detail: Some(format!("{} functions", function_count)),
            });
        }

        let x86_opt_level = x86_opt_level_from_codegen(self.config.opt_level);
        // As in AOT, raw validation is complete and no later JIT phase reads
        // the unoptimized graph. Move it into the mutating optimizer so peak
        // memory does not include two complete ISel graphs.
        let mut optimized_isel_funcs = isel_funcs;
        let opt_start = Instant::now();
        // JIT-8: give the x86 in-process JIT a latency-tuned allocation profile.
        // The production JIT (`CompilerConfig::for_host_jit` / `jit_fast`) sets
        // `enable_jit_fast_regalloc`; under it we select `host_jit_fast()` (the
        // LinearScan allocator core) instead of the default Greedy profile,
        // cutting JIT-compile latency toward the aarch64 `jit_fast` numbers
        // (~11% lower total JIT-compile time on the uuf50-218 BCP kernel).
        //
        // This is a latency/code-quality trade only — the always-on regalloc
        // translation validator proves every allocation, so a lower-quality
        // allocation fails closed rather than miscompiling, and the JIT-5
        // CachedVerified cert path still covers every emitted byte. AOT is
        // unaffected (it never sets `enable_jit_fast_regalloc`).
        // `TCG_NO_X86_JIT_LINEARSCAN` forces the previous Greedy profile.
        let effective_codegen_profile = self.effective_x86_jit_codegen_profile();
        let use_fast_jit_regalloc = effective_codegen_profile.fast_regalloc;
        let jit_base_config = if use_fast_jit_regalloc {
            X86PipelineConfig::host_jit_fast_with_features(
                effective_codegen_profile.target_features,
            )
        } else {
            X86PipelineConfig::host_jit_with_features(effective_codegen_profile.target_features)
        };
        let selected_pipeline_target_features = jit_base_config.target_features;
        let pipeline = X86Pipeline::new(X86PipelineConfig {
            opt_level: x86_opt_level,
            output_format: X86OutputFormat::RawBytes,
            emit_frame: true,
            call_abi,
            ..jit_base_config
        });
        // JIT-8 Greedy fallback: LinearScan spills harder than Greedy and a rare
        // high-register-pressure function (e.g. v16i8 bool-vector selects) can
        // exceed the x86 spill-replay scratch budget and fail closed under
        // LinearScan while Greedy allocates it. To preserve completeness with no
        // regression, when the fast profile is active we keep a Greedy pipeline
        // and retry any function LinearScan cannot compile. Fallback output is
        // byte-identical to the pre-JIT-8 Greedy path (the optimizer passes are
        // regalloc-mode-independent), both paths pass the always-on validator,
        // and if BOTH fail we surface the Greedy error — the exact fail-closed
        // behavior callers saw before JIT-8.
        let fallback_pipeline = if use_fast_jit_regalloc {
            Some(X86Pipeline::new(X86PipelineConfig {
                opt_level: x86_opt_level,
                output_format: X86OutputFormat::RawBytes,
                emit_frame: true,
                call_abi,
                ..X86PipelineConfig::host_jit_with_features(selected_pipeline_target_features)
            }))
        } else {
            None
        };

        // VOL-1 can FAIL the compile, so this parallel fold collects a Result
        // rather than a usize: a moved volatile access must stop the compile,
        // not be counted and forgotten.
        let optimization_passes_run: usize = optimized_isel_funcs
            .par_iter_mut()
            .zip(phase_timings.par_iter_mut())
            .map(|(func, timings)| {
                codegen_environment.run(|| {
                    let func_opt_start = Instant::now();
                    let before = trust_cg_verify::x86_volatile_trace::machine_volatile_trace(func);
                    let passes = pipeline.run_x86_optimization_passes(func).total_pass_runs();
                    check_volatile_trace_preserved(&func.name.clone(), &before, func)?;
                    timings.optimization = Some(nonzero_duration(func_opt_start.elapsed()));
                    Ok::<usize, CompileError>(passes)
                })
            })
            .collect::<Result<Vec<usize>, CompileError>>()?
            .into_iter()
            .sum();

        if tracing {
            trace_entries.push(TraceEntry {
                phase: "x86_jit_optimization".to_string(),
                duration: opt_start.elapsed(),
                detail: Some(format!("{} pass runs", optimization_passes_run)),
            });
        }

        // PROOF-GAP item 1 + 3 (JIT path): same unconditional fail-closed gates
        // as the AOT path. Carrier hygiene (#51 / #66) runs per-function over
        // the post-optimization stream that is actually encoded; the glue-pass
        // validator (#67) is now PER-PROGRAM over the same emitted functions
        // (structural IMUL->IDIV net + idiom enumeration, deduped + re-verified).
        // Pure-lattice / exhaustive — no solver.
        optimized_isel_funcs
            .par_iter()
            .try_for_each(|func| codegen_environment.run(|| check_x86_carrier_hygiene(func)))?;
        validate_x86_glue_pass_expansions(&optimized_isel_funcs, pipeline.config.target_features)?;

        // JIT-5: proof-certificate generation + fail-closed promotion gate is
        // deferred to AFTER encoding so the content-addressed certificate cache
        // can key on the exact per-function emitted (pre-fixup) bytes — the
        // bytes-hash binding that makes a warm hit sound (a reused verdict is
        // bound to the machine bytes it vouched for). The gate still runs before
        // `publish`, so no function lacking required semantic evidence is placed
        // in executable memory
        // on a verifying mode. See the `proofs` / `jit_validation` block below.

        let encode_start = Instant::now();
        struct Encoded {
            body_offset: u64,
            published_len: usize,
            call_fixups: Vec<crate::x86_64::pipeline::X86CallFixup>,
            global_ref_fixups: Vec<crate::x86_64::pipeline::X86GlobalRefFixup>,
            machine_code_evidence: X86MachineCodeEvidence,
        }

        struct CompResult {
            has_body_instructions: bool,
            func_code: Vec<u8>,
            const_pool: Vec<u8>,
            call_fixups: Vec<crate::x86_64::pipeline::X86CallFixup>,
            global_ref_fixups: Vec<crate::x86_64::pipeline::X86GlobalRefFixup>,
            machine_code_evidence: X86MachineCodeEvidence,
            counter_patch_sites: Vec<crate::x86_64::pipeline::X86BlockCounterPatchSite>,
            func_encode_elapsed: Duration,
        }

        let compilation_results: Vec<Result<CompResult, CompileError>> = optimized_isel_funcs
            .par_iter()
            .map(|func| {
                codegen_environment.run(|| {
                    let func_encode_start = Instant::now();
                    if profile_block_counters_enabled {
                        // JIT-8: try the fast (LinearScan) pipeline, then fall back
                        // to Greedy for any function it cannot allocate.
                        let (profiled, has_body_instructions) =
                            compile_x86_jit_function_with_fallback(
                                &pipeline,
                                fallback_pipeline.as_ref(),
                                |p| {
                                    p.compile_function_with_jit_block_counters_after_x86_passes(
                                        func,
                                    )
                                },
                            )?;
                        Ok(CompResult {
                            has_body_instructions,
                            func_code: profiled.code,
                            const_pool: profiled.const_pool,
                            call_fixups: profiled.call_fixups,
                            global_ref_fixups: profiled.global_ref_fixups,
                            machine_code_evidence: profiled.machine_code_evidence,
                            counter_patch_sites: profiled.counter_patch_sites,
                            func_encode_elapsed: func_encode_start.elapsed(),
                        })
                    } else {
                        // JIT-8: try the fast (LinearScan) pipeline, then fall back
                        // to Greedy for any function it cannot allocate.
                        let (
                            func_code,
                            const_pool,
                            call_fixups,
                            global_ref_fixups,
                            machine_code_evidence,
                            has_body_instructions,
                        ) = compile_x86_jit_function_with_fallback(
                            &pipeline,
                            fallback_pipeline.as_ref(),
                            |p| p.compile_function_with_fixups_and_evidence_after_x86_passes(func),
                        )?;
                        Ok(CompResult {
                            has_body_instructions,
                            func_code,
                            const_pool,
                            call_fixups,
                            global_ref_fixups,
                            machine_code_evidence,
                            counter_patch_sites: Vec::new(),
                            func_encode_elapsed: func_encode_start.elapsed(),
                        })
                    }
                })
            })
            .collect();

        let mut code = Vec::new();
        let mut encoded = Vec::with_capacity(function_count);
        let mut func_offsets: HashMap<String, X86JitFunctionAddress> =
            HashMap::with_capacity(function_count);
        let mut symbol_offsets: HashMap<String, u64> = HashMap::with_capacity(function_count * 2);
        let mut canonical_symbols = Vec::with_capacity(function_count);
        let mut function_ranges = Vec::with_capacity(function_count);
        let mut windows_unwind_functions = Vec::with_capacity(function_count);
        let mut counters: HashMap<String, Box<AtomicU64>> = HashMap::new();
        let mut counter_patch_sites: Vec<(usize, *const AtomicU64)> = Vec::new();
        // JIT-5: ranges of each normalized pre-fixup function image inside the
        // single module byte buffer, in `optimized_isel_funcs` order. Keeping
        // ranges instead of cloning every function avoids a second whole-module
        // allocation at the JIT's peak-memory point. The explicit unchecked
        // path allocates neither ranges nor manifests because it never performs
        // certificate lookup or generation.
        let collect_certification_inputs =
            validation_mode.requires_jit_verification() || self.config.emit_proofs;
        let mut per_func_emitted_ranges: Vec<std::ops::Range<usize>> =
            if collect_certification_inputs {
                Vec::with_capacity(function_count)
            } else {
                Vec::new()
            };
        let mut per_func_symbolic_fixup_manifests: Vec<Vec<u8>> = if collect_certification_inputs {
            Vec::with_capacity(function_count)
        } else {
            Vec::new()
        };

        for (idx, (func, comp_res)) in optimized_isel_funcs
            .iter()
            .zip(compilation_results)
            .enumerate()
        {
            let comp_res = comp_res?;
            if symbol_offsets.contains_key(func.name.as_str()) {
                return Err(CompileError::Jit(crate::jit::JitError::DuplicateSymbol(
                    func.name.clone(),
                )));
            }
            let alias = format!("_{}", func.name);
            if symbol_offsets.contains_key(alias.as_str()) {
                return Err(CompileError::Jit(crate::jit::JitError::DuplicateSymbol(
                    alias,
                )));
            }

            let certificate_start = code.len();
            let text_offset = certificate_start as u64;
            if profile_call_counters_enabled {
                let counter = Box::new(AtomicU64::new(0));
                let counter_ptr = counter.as_ref() as *const AtomicU64;
                let imm64_offset = emit_x86_64_profile_counter_trampoline(&mut code);
                counter_patch_sites.push((imm64_offset, counter_ptr));
                counters.insert(func.name.clone(), counter);
            }
            let body_offset = code.len() as u64;

            if profile_block_counters_enabled {
                let func_base = code.len();
                for site in &comp_res.counter_patch_sites {
                    let key = format!("{}::block{}", func.name, site.block.0);
                    if counters.contains_key(&key) {
                        return Err(CompileError::Jit(crate::jit::JitError::DuplicateSymbol(
                            key,
                        )));
                    }
                    let counter = Box::new(AtomicU64::new(0));
                    let counter_ptr = counter.as_ref() as *const AtomicU64;
                    counter_patch_sites.push((func_base + site.imm64_offset, counter_ptr));
                    counters.insert(key, counter);
                }
            }

            // `compile_function_with_fixups_and_evidence_after_x86_passes` runs
            // regalloc + frame lowering + branch resolution + encoding behind a
            // single call and hands back ONE elapsed duration, so this path
            // cannot attribute that time to a phase.
            //
            // It used to divide the region by four and write the identical
            // quotient into all four fields. That made those rows exactly equal
            // in every JIT breakdown by construction -- an artifact of the
            // split, not a measurement -- while looking like real per-phase
            // data to `jit_compile_breakdown_table` and to the downstream `ty`
            // A/B benchmarks. Report it as unattributed instead: the total
            // stays correct and the breakdown stops inventing a ranking.
            //
            // The AOT `prepare_function_with_metrics*` family already times all
            // four separately; porting those timers here is what shrinks this.
            phase_timings[idx].unattributed = Some(nonzero_duration(comp_res.func_encode_elapsed));
            code.extend_from_slice(&comp_res.func_code);
            let function_code_end = code.len() as u64;
            code.extend_from_slice(&comp_res.const_pool);
            let function_end = code.len() as u64;

            if collect_certification_inputs {
                per_func_emitted_ranges.push(certificate_start..code.len());
                let certificate_body_offset = if profile_block_counters_enabled {
                    0
                } else {
                    body_offset - text_offset
                };
                per_func_symbolic_fixup_manifests.push(
                    crate::jit_cert::x86_symbolic_fixup_manifest(
                        &comp_res.call_fixups,
                        &comp_res.global_ref_fixups,
                        certificate_body_offset,
                    )?,
                );
            }

            canonical_symbols.push(func.name.clone());
            func_offsets.insert(
                func.name.clone(),
                X86JitFunctionAddress::from_encoded_instructions(
                    text_offset,
                    comp_res.has_body_instructions,
                ),
            );
            symbol_offsets.insert(func.name.clone(), text_offset);
            symbol_offsets.insert(format!("_{}", func.name), text_offset);
            function_ranges.push((func.name.clone(), text_offset..function_end));
            windows_unwind_functions.push(
                crate::jit::WindowsJitUnwindFunction::new(
                    func.name.clone(),
                    text_offset,
                    function_code_end,
                )
                .with_dynamic_stack_alloc(x86_function_has_dynamic_stack_alloc(func)),
            );
            encoded.push(Encoded {
                body_offset: if profile_block_counters_enabled {
                    text_offset
                } else {
                    body_offset
                },
                published_len: (function_end - text_offset) as usize,
                call_fixups: comp_res.call_fixups,
                global_ref_fixups: comp_res.global_ref_fixups,
                machine_code_evidence: comp_res.machine_code_evidence,
            });
        }

        // Derive one artifact-level profile from the ACTUAL target-feature
        // evidence returned by every function's final machine-code pipeline.
        // This gate runs before certification and publication, so neither a
        // pipeline/evidence mismatch nor a nonuniform multi-function artifact
        // can reach executable memory.
        let selected_target_features = validate_x86_host_jit_selected_codegen_features(
            selected_pipeline_target_features,
            optimized_isel_funcs
                .iter()
                .zip(&encoded)
                .map(|(function, encoded)| {
                    (
                        function.name.as_str(),
                        encoded.machine_code_evidence.target_features,
                    )
                }),
        )?;
        let selected_codegen_profile =
            HostJitSelectedCodegenProfile::from_validated_x86_target_features(
                compiler_target_triple(self.target_spec),
                selected_target_features,
            )?;

        let function_code_size: usize = encoded.iter().map(|func| func.published_len).sum();

        // JIT-5: certify the normalized, pre-relocation module image while it
        // is still available as one borrowed buffer. The cache identity also
        // binds complete verifier semantics and symbolic fixups, so relocation
        // holes cannot alias. Certification here avoids retaining a cloned
        // copy while the linker appends veneers and pointer slots below.
        let (proofs, mut per_function_validation): (
            Option<Vec<ProofCertificate>>,
            Vec<JitFunctionValidation>,
        ) = self.x86_jit_certify_functions(
            validation_mode,
            &optimized_isel_funcs,
            &lir_functions,
            &code,
            &per_func_emitted_ranges,
            &per_func_symbolic_fixup_manifests,
            module_definitions,
        )?;

        let mut veneers: HashMap<String, u64> = HashMap::new();
        let mut extern_ref_slots: HashMap<String, u64> = HashMap::new();
        for func in &encoded {
            for fixup in &func.call_fixups {
                let disp32_offset = func.body_offset as usize + fixup.offset;
                let target = if fixup.exact_module {
                    resolve_x86_exact_function_offset(&func_offsets, &fixup.callee)
                        .map_err(CompileError::Jit)?
                } else if let Some(&ptr) = extern_symbols
                    .get(&fixup.callee)
                    .filter(|pointer| !pointer.is_null())
                {
                    *veneers
                        .entry(fixup.callee.clone())
                        .or_insert_with(|| emit_x86_64_absolute_jump_veneer(&mut code, ptr))
                } else if let Some(function) = func_offsets.get(&fixup.callee) {
                    function.offset
                } else if let Some(ptr) = crate::jit::resolve_external_symbol(
                    &fixup.callee,
                    extern_symbols,
                    external_symbol_resolution,
                ) {
                    *veneers
                        .entry(fixup.callee.clone())
                        .or_insert_with(|| emit_x86_64_absolute_jump_veneer(&mut code, ptr))
                } else if let Some(&offset) = symbol_offsets.get(&fixup.callee) {
                    offset
                } else {
                    return Err(CompileError::Jit(crate::jit::JitError::UnresolvedSymbol(
                        fixup.callee.clone(),
                    )));
                };
                patch_x86_64_rel32_call(&mut code, disp32_offset, target)
                    .map_err(CompileError::Jit)?;
            }
            for fixup in &func.global_ref_fixups {
                let disp32_offset = func.body_offset as usize + fixup.offset;
                let target = match fixup.kind {
                    crate::x86_64::pipeline::X86SymbolRefFixupKind::ExactFunctionAddr => {
                        resolve_x86_exact_function_offset(&func_offsets, &fixup.symbol)
                            .map_err(CompileError::Jit)?
                    }
                    crate::x86_64::pipeline::X86SymbolRefFixupKind::GlobalRef => {
                        let Some(&target) = symbol_offsets.get(&fixup.symbol) else {
                            return Err(CompileError::Jit(crate::jit::JitError::UnresolvedSymbol(
                                fixup.symbol.clone(),
                            )));
                        };
                        target
                    }
                    crate::x86_64::pipeline::X86SymbolRefFixupKind::ExternRefGot => {
                        if let Some(&slot) = extern_ref_slots.get(&fixup.symbol) {
                            slot
                        } else {
                            let ptr = crate::jit::resolve_external_symbol(
                                &fixup.symbol,
                                extern_symbols,
                                external_symbol_resolution,
                            )
                            .ok_or_else(|| {
                                CompileError::Jit(crate::jit::JitError::UnresolvedSymbol(
                                    fixup.symbol.clone(),
                                ))
                            })?;
                            while code.len() % 8 != 0 {
                                code.push(0xCC);
                            }
                            let slot = code.len() as u64;
                            code.extend_from_slice(&(ptr as u64).to_le_bytes());
                            extern_ref_slots.insert(fixup.symbol.clone(), slot);
                            slot
                        }
                    }
                    crate::x86_64::pipeline::X86SymbolRefFixupKind::TlsTlv => {
                        // Fail closed: a Mach-O `@TLVP` thread-local descriptor
                        // load cannot be resolved in the in-process JIT — it
                        // needs dyld's TLV runtime plus the linker's load->LEA
                        // relaxation, neither of which the JIT fixup path runs.
                        // (TLS is exercised only through the AOT object emitter.)
                        return Err(CompileError::Jit(crate::jit::JitError::UnresolvedSymbol(
                            format!(
                                "{} (@TLVP thread-local descriptor: unsupported in the in-process JIT; use AOT object emission)",
                                fixup.symbol
                            ),
                        )));
                    }
                };
                patch_x86_64_rel32_call(&mut code, disp32_offset, target)
                    .map_err(CompileError::Jit)?;
            }
        }
        if tracing {
            trace_entries.push(TraceEntry {
                phase: "x86_jit_encode".to_string(),
                duration: encode_start.elapsed(),
                detail: Some(format!("{} functions", function_count)),
            });
        }

        let publish_start = Instant::now();
        let mut buffer = crate::jit::publish_raw_executable_buffer_with_profile_data(
            &code,
            canonical_symbols,
            symbol_offsets,
            function_ranges,
            counters,
            counter_patch_sites,
            windows_unwind_functions,
        )
        .map_err(CompileError::Jit)?;
        buffer
            .attach_host_jit_selected_codegen_profile(selected_codegen_profile.clone())
            .map_err(CompileError::Jit)?;

        // The cache/certificate identity above intentionally uses the stable
        // pre-relocation byte image plus a symbolic-fixup manifest. Public
        // provenance separately reports the exact sealed bytes callers will
        // execute, including resolved displacements and profile pointers.
        let published_code = buffer.code_slice();
        if per_function_validation.is_empty() && !validation_mode.requires_jit_verification() {
            // Unchecked is an explicit development mode, but it must remain a
            // usable mode and its lack of semantic coverage must be visible per
            // function. Avoid hashing verifier inputs here: doing proof work on
            // the opt-out path would defeat its latency purpose.
            per_function_validation = buffer
                .function_ranges()
                .iter()
                .map(|(name, _)| JitFunctionValidation {
                    function: name.clone(),
                    verified: false,
                    verifier_input_sha256: String::new(),
                    bytes_sha256: String::new(),
                    cache_hit: false,
                })
                .collect();
        }
        if per_function_validation.len() != buffer.function_ranges().len() {
            return Err(CompileError::Jit(
                crate::jit::JitError::ValidationRangeCountMismatch {
                    validation_count: per_function_validation.len(),
                    range_count: buffer.function_ranges().len(),
                },
            ));
        }
        for (record, (name, range)) in per_function_validation
            .iter_mut()
            .zip(buffer.function_ranges())
        {
            if record.function != *name {
                return Err(CompileError::Jit(
                    crate::jit::JitError::ValidationFunctionNameMismatch {
                        validation_function: record.function.clone(),
                        range_function: name.clone(),
                    },
                ));
            }
            let start = usize::try_from(range.start).ok();
            let end = usize::try_from(range.end).ok();
            record.bytes_sha256 = match (start, end) {
                (Some(start), Some(end)) if start <= end && end <= published_code.len() => {
                    crate::jit_diagnostics::sha256_hex(&published_code[start..end])
                }
                _ => {
                    return Err(CompileError::Jit(
                        crate::jit::JitError::InvalidFunctionRange {
                            function: name.clone(),
                            start: range.start,
                            end: range.end,
                            code_len: published_code.len(),
                        },
                    ));
                }
            };
        }
        if tracing {
            trace_entries.push(TraceEntry {
                phase: "x86_jit_publish".to_string(),
                duration: publish_start.elapsed(),
                detail: Some(format!("{} bytes", code.len())),
            });
        }

        // JIT-5: expose semantic verifier identities, exact per-function byte
        // hashes, and the full published-image hash together so callers can
        // audit proof coverage and publication integrity without conflating
        // normalized relocation identity with post-link bytes.
        let validation = Some(JitValidationProvenance {
            mode: validation_mode,
            published_image_sha256: buffer.published_image_sha256().to_string(),
            functions: per_function_validation,
        });

        let per_function_metrics: Vec<FunctionQualityMetrics> = optimized_isel_funcs
            .iter()
            .zip(phase_timings)
            .zip(&encoded)
            .map(|((func, phase_timings), encoded)| FunctionQualityMetrics {
                name: func.name.clone(),
                code_size_bytes: encoded.published_len,
                instruction_count: count_x86_real_instructions(func),
                spill_slot_count: 0,
                branch_count: count_x86_branch_instructions(func),
                x86_machine_code: encoded.machine_code_evidence,
                aarch64_machine_code: None,
                phase_timings,
                static_stack_frame: None,
                stack_limit: None,
            })
            .collect();

        let instruction_count: usize = optimized_isel_funcs
            .iter()
            .map(count_x86_real_instructions)
            .sum();
        let metrics = CompilationMetrics {
            code_size_bytes: function_code_size,
            instruction_count,
            function_count,
            optimization_passes_run,
            proof_optimizations: ProofOptimizationMetrics::default(),
            fsym_trust_ir: FsymTrustIrMetrics::default(),
            pass_validation: trust_cg_opt::PassValidationSummary::default(),
            composed_transitions: Vec::new(),
            composed_publications: 0,
        };

        let trace = if tracing {
            Some(CompilerTrace {
                entries: trace_entries,
                total_duration: total_start.elapsed(),
            })
        } else {
            None
        };

        buffer.attach_proof_optimization_certificates(Vec::new());

        Ok(JitCompilationResult {
            buffer,
            metrics,
            trace,
            proofs,
            proof_optimization_certificates: Vec::new(),
            per_function_metrics,
            host_jit_selected_codegen_profile: Some(selected_codegen_profile),
            aarch64_machine_code: None,
            validation,
            inline_only_bodies: Default::default(),
            stack_limits: None,
            dialect_legalization: None,
        })
    }

    /// Compile a pre-built IR function (skipping trust_ir adapter and ISel).
    ///
    /// Useful when you already have an `IrMachFunction` and want to run
    /// optimization, regalloc, frame lowering, encoding, and Mach-O emission.
    pub fn compile_ir_function(
        &self,
        ir_func: &mut trust_cg_ir::MachFunction,
    ) -> Result<CompilationResult, CompileError> {
        if self.config.target != Target::Aarch64 {
            return Err(CompileError::PrebuiltIrTargetUnsupported {
                target: self.config.target,
            });
        }
        if self.requires_verified_proof_promotion() {
            return Err(CompileError::ProofPromotionRejected {
                target: self.config.target,
                reason: "direct single-function prebuilt-IR emission cannot yet produce an exact relocation inventory for the object it emits: the single-function Mach-O path always adds compact-unwind relocations (and may add DWARF eh_frame relocations), while the module inventory models a different emission plan. Refusing proof promotion until inventory is derived from the exact emitted object/plan (fail-closed)".to_string(),
            });
        }
        let start = Instant::now();
        let pipeline = self.build_pipeline(self.aarch64_object_isa_profile());

        let (obj_bytes, optimization_stats) = pipeline.compile_ir_function_with_stats(ir_func)?;
        #[cfg(not(feature = "verify"))]
        let _ = optimization_stats;

        // Count actual non-pseudo instructions from the function, not obj size / 4
        // which would include Mach-O headers, symbol tables, and relocations.
        let code_insts = count_real_instructions(ir_func);
        // Query actual pass count from the optimization pipeline (fixes #272).
        let opt_passes = {
            use trust_cg_opt::pipeline::{OptLevel as OptOptLevel, OptimizationPipeline};
            let opt_level = match self.config.opt_level {
                OptLevel::O0 => OptOptLevel::O0,
                OptLevel::O1 => OptOptLevel::O1,
                OptLevel::O2 => OptOptLevel::O2,
                OptLevel::O3 => OptOptLevel::O3,
            };
            OptimizationPipeline::new(opt_level).pass_count()
        };

        let metrics = CompilationMetrics {
            code_size_bytes: code_insts * 4,
            instruction_count: code_insts,
            function_count: 1,
            optimization_passes_run: opt_passes,
            proof_optimizations: ProofOptimizationMetrics::default(),
            fsym_trust_ir: FsymTrustIrMetrics::default(),
            pass_validation: optimization_stats.pass_validation.clone(),
            composed_transitions: Vec::new(),
            composed_publications: 0,
        };

        let trace = if self.config.trace_level != CompilerTraceLevel::None {
            Some(CompilerTrace {
                entries: vec![TraceEntry {
                    phase: "compile_ir_function".to_string(),
                    duration: start.elapsed(),
                    detail: Some(ir_func.name.clone()),
                }],
                total_duration: start.elapsed(),
            })
        } else {
            None
        };

        // Proof promotion for this boundary is rejected before compilation
        // above until an exact single-function object inventory exists.
        let proofs: Option<Vec<ProofCertificate>> = None;

        #[cfg(feature = "verify")]
        let certified_pass_chain = self.certified_pass_chain_attachment_from_runs(
            &ir_func.name,
            &optimization_stats.certified_pass_runs,
        )?;
        #[cfg(not(feature = "verify"))]
        let certified_pass_chain = self.certified_pass_chain.clone();

        Ok(CompilationResult {
            aarch64_frame_inputs: Vec::new(),
            object_code: obj_bytes,
            metrics,
            trace,
            proofs,
            certified_pass_chain,
            proof_optimization_certificates: Vec::new(),
            compile_artifact_cache_telemetry: Vec::new(),
            target_selection: self.target_selection(),
            inline_only_bodies: Default::default(),
            stack_limits: None,
            dialect_legalization: None,
        })
    }

    /// Consume one admitted identity-Core owner into a sealed closed-host-JIT
    /// compilation plan.
    ///
    /// Planning validates the attached admission receipts, moves the exact
    /// module and already-replayed strict LIR once, reuses the admitted target
    /// and feature profile, canonically binds the explicit compiler/JIT policy,
    /// refuses unkeyed `TCG_*` / `TRUST_CG_*` controls, and forces future
    /// external-symbol lookup to
    /// [`JitExternalSymbolResolutionPolicy::ExplicitOnly`] regardless of the
    /// compatibility compiler config.
    ///
    /// This function accepts no address map and invokes no instruction
    /// selection, target codegen, linker, JIT, or executable-memory API. The
    /// returned [`CoreJitCompilationPlan`] exposes neither TrustIR nor LIR. On
    /// any failure, [`CoreJitPlanningFailure`] returns the still-sealed
    /// [`CoreAdmittedModule`] so a corrected compiler can retry it.
    ///
    /// ```compile_fail
    /// use trust_cg_codegen::{Compiler, CoreAdmittedModule};
    ///
    /// fn consume_twice(compiler: &Compiler, core: CoreAdmittedModule) {
    ///     let _first = compiler.plan_core_module_for_jit_compilation(core);
    ///     // The admitted owner and its retained LIR were moved above.
    ///     let _second = compiler.plan_core_module_for_jit_compilation(core);
    /// }
    /// ```
    ///
    /// ```compile_fail
    /// use std::collections::HashMap;
    /// use trust_cg_codegen::{Compiler, CoreAdmittedModule};
    ///
    /// fn inject_raw_addresses(compiler: &Compiler, core: CoreAdmittedModule) {
    ///     let addresses: HashMap<String, *const u8> = HashMap::new();
    ///     // Planning has no raw-address parameter or resolution side door.
    ///     let _ = compiler.plan_core_module_for_jit_compilation(core, &addresses);
    /// }
    /// ```
    pub fn plan_core_module_for_jit_compilation(
        &self,
        mut core: CoreAdmittedModule,
    ) -> Result<CoreJitCompilationPlan, CoreJitPlanningFailure> {
        let (effective_options, native_runtime_catalog, native_dependency_references) =
            match self.preflight_core_module_for_jit_compilation(&core) {
                Ok(preflight) => preflight,
                Err(error) => return Err(CoreJitPlanningFailure { error, core }),
            };

        let lir_native_dependency_bindings = match core
            .bind_declared_external_calls(&native_runtime_catalog, &native_dependency_references)
        {
            Ok(bindings) => bindings,
            Err(error) => {
                return Err(CoreJitPlanningFailure {
                    error: error.into(),
                    core,
                });
            }
        };
        let retained_lir_proof_context_digest = match core.retained_lir_proof_context_digest() {
            Ok(digest) => digest,
            Err(error) => {
                return Err(CoreJitPlanningFailure {
                    error: error.into(),
                    core,
                });
            }
        };
        // Every fallible check retained ownership of `core`; the binding
        // transition itself validates completely before its infallible rewrite.
        // This is the only ownership split and moves retained LIR exactly once.
        let parts = core.into_consumable_parts();
        let identity = CoreJitPlanIdentity::new(
            &parts.receipt,
            &native_runtime_catalog,
            &native_dependency_references,
            &lir_native_dependency_bindings,
            retained_lir_proof_context_digest,
            effective_options.compile_policy_digests(),
        );

        Ok(CoreJitCompilationPlan {
            parts,
            effective_options,
            native_runtime_catalog,
            native_dependency_references,
            lir_native_dependency_bindings,
            retained_lir_proof_context_digest,
            identity,
        })
    }

    fn preflight_core_module_for_jit_compilation(
        &self,
        core: &CoreAdmittedModule,
    ) -> Result<
        (
            CoreJitEffectiveOptions,
            CoreNativeRuntimeCatalog,
            CoreNativeDependencyReferenceMap,
        ),
        CoreJitPlanningError,
    > {
        // trust-ir v41 codegen LICENSE under THIS compiler's policy, decided
        // on the admitted module before anything else. Admission applied only
        // the floor (claim-less bodies deferred, `CoreAdmissionFloor`); this
        // is where the compiler's policy — by default refusing claim-less
        // bodies (DG-73) — reaches the Core JIT path.
        self.codegen_license
            .enforce_module(core.admitted_module())
            .map_err(CoreJitPlanningError::CodegenLicense)?;
        let environment = trust_cg_process_env::artifact_reuse_environment_safety();
        if !environment.is_reuse_safe() {
            return Err(CoreJitPlanningError::UnkeyedAmbientCompilerControls {
                controls: environment.unkeyed_controls().to_vec(),
            });
        }
        let environment_permit = trust_cg_process_env::artifact_reuse_permit()
            .ok_or(CoreJitPlanningError::CompilerEnvironmentPermitUnavailable)?;

        self.ensure_core_jit_attachments_supported()?;
        if self.config.relocation_model != RelocationModel::Static {
            return Err(CoreJitPlanningError::RelocationModelUnsupported {
                model: self.config.relocation_model,
            });
        }
        if let Some(profile) = self.config.aarch64_isa_profile {
            return Err(CoreJitPlanningError::Aarch64IsaProfileUnsupported { profile });
        }
        if self.config.aarch64_force_frame_pointers {
            return Err(CoreJitPlanningError::Compile(
                CompileError::Aarch64FramePointersUnsupported {
                    target: compiler_target_triple(self.target_spec),
                    reason: "Core JIT does not model forced object frame records",
                },
            ));
        }
        if self.config.eh_frames_cannot_unwind {
            return Err(CoreJitPlanningError::Compile(
                CompileError::EhFramesCannotUnwindUnsupported {
                    target: compiler_target_triple(self.target_spec),
                    reason: "Core JIT unwind registration does not model non-unwinding \
                             exception frames",
                },
            ));
        }
        let admitted_target = core.target_contract().target_spec();
        if admitted_target != self.target_spec {
            return Err(CoreJitPlanningError::TargetMismatch {
                admitted: admitted_target,
                compiler: self.target_spec,
            });
        }
        let machine_profile = core.target_contract().host_jit_machine_profile();
        if machine_profile.architecture() != self.config.target {
            return Err(CoreJitPlanningError::MachineProfileArchitectureMismatch {
                profile: machine_profile.architecture(),
                compiler: self.config.target,
            });
        }
        // With unkeyed ambient controls refused, the configured mode is the
        // only permitted resolution. A Compiler that cached a different answer
        // during an earlier ambient override is not silently reused.
        let configured_validation_mode = self.config.jit_validation_mode();
        let validation_mode = self.captured_jit_validation_mode()?;
        if validation_mode != configured_validation_mode {
            return Err(CoreJitPlanningError::CapturedValidationPolicyMismatch {
                captured: validation_mode,
                configured: configured_validation_mode,
            });
        }

        let mut effective_config = self.config.clone();
        effective_config.jit_external_symbol_resolution =
            JitExternalSymbolResolutionPolicy::ExplicitOnly;
        let jit_config = effective_config.to_jit_config_with_validation_mode(
            crate::jit::ProfileHookMode::None,
            validation_mode,
        )?;
        debug_assert_eq!(
            jit_config.external_symbol_resolution,
            JitExternalSymbolResolutionPolicy::ExplicitOnly
        );
        let compile_policy = CompilePolicy::new(admitted_target, &effective_config, &jit_config)?;
        let effective_options = CoreJitEffectiveOptions {
            target_spec: admitted_target,
            machine_profile,
            validation_mode,
            compiler_config: effective_config,
            jit_config,
            compile_policy,
        };

        // Integrity is borrowed so a failed check cannot detach or discard the
        // retained LIR before planning has succeeded.
        core.check_consumption_integrity()?;
        let native_runtime_catalog = CoreNativeRuntimeCatalog::try_from_declared_import_manifest(
            core.declared_import_manifest(),
        )?;
        let native_dependency_references =
            core.native_dependency_reference_map(&native_runtime_catalog)?;

        // A transient thread-local control between initial inspection and the
        // completed policy seal permanently invalidates this transaction.
        if !environment_permit.is_valid() {
            return Err(CoreJitPlanningError::CompilerEnvironmentChanged);
        }

        Ok((
            effective_options,
            native_runtime_catalog,
            native_dependency_references,
        ))
    }

    fn ensure_core_jit_attachments_supported(&self) -> Result<(), CoreJitPlanningError> {
        let unsupported = if self.profile_use.is_some() {
            Some("profile-use input")
        } else if self.profile_generate_sink.is_some() {
            Some("profile-generation sink")
        } else if self.compile_artifact_cache.is_some() {
            Some("compile artifact cache")
        } else if self.certified_pass_chain.is_some() {
            Some("caller-supplied certified pass chain")
        } else if self.production_certified_pass_chain {
            Some("production certified pass chain")
        } else if self.jit_cert_cache.is_some() {
            Some("caller-supplied JIT certificate cache")
        } else if !self.inline_only_dependencies.is_empty() {
            Some("inline-only dependency authority")
        } else {
            #[cfg(feature = "verify")]
            if !self.production_certified_pass_runs.is_empty() {
                return Err(CoreJitPlanningError::UnsupportedCompilerAttachment {
                    attachment: "additional production certified pass runs",
                });
            }
            None
        };
        if let Some(attachment) = unsupported {
            return Err(CoreJitPlanningError::UnsupportedCompilerAttachment { attachment });
        }
        Ok(())
    }

    /// Compile a trust_ir module to executable memory for JIT execution.
    ///
    /// This compatibility API performs dialect lowering and TrustIR-to-LIR
    /// translation on every call. The configured architecture and exact OS/ABI
    /// target must match the host process. Admitted Core consumers should use
    /// [`Self::plan_core_module_for_jit_compilation`] first and await the
    /// separate compile/fixup/install ownership transitions.
    pub fn compile_module_to_jit(
        &self,
        module: &trust_ir::Module,
        extern_symbols: &std::collections::HashMap<String, *const u8>,
    ) -> Result<JitCompilationResult, CompileError> {
        self.compile_module_to_jit_with_profile_hooks(
            module,
            extern_symbols,
            crate::jit::ProfileHookMode::None,
        )
    }

    /// Compile a trust_ir module to executable memory with explicit JIT profiling
    /// hooks.
    ///
    /// This keeps the existing [`Self::compile_module_to_jit`] zero-overhead
    /// default intact while giving CLI/profile-generate callers a public route
    /// to target-specific block-counter JIT support. AArch64 delegates to the
    /// raw JIT block-trampoline path; x86-64 injects block counters in the
    /// compiler pipeline before publishing executable memory.
    pub fn compile_module_to_jit_with_profile_hooks(
        &self,
        module: &trust_ir::Module,
        extern_symbols: &std::collections::HashMap<String, *const u8>,
        profile_hooks: crate::jit::ProfileHookMode,
    ) -> Result<JitCompilationResult, CompileError> {
        self.ensure_host_jit_target()?;
        crate::resource_limits::admit_compilation_budget()?;
        // JIT-5: use the validation mode captured when this Compiler was
        // constructed (including the TCG_JIT_UNCHECKED gate), then thread that
        // one immutable answer into both certificate machineries and identity.
        let validation_mode = self.resolved_jit_validation_mode()?;
        let jit_config = self
            .config
            .to_jit_config_with_validation_mode(profile_hooks, validation_mode)?;

        let total_start = Instant::now();
        let tracing = self.config.trace_level != CompilerTraceLevel::None;
        let mut trace_entries = Vec::new();

        // WS7.3 INGESTION ADMISSION: trust-ir's own codegen validator plus the
        // v41 codegen LICENSE, decided on the caller's module before any cache
        // lookup or rewrite (see `Self::compile`).
        // trust-ir v74 `Inst::BoxDeref` on a proof-grade compile: refused
        // whatever floor the license names. The only evidence the pinned
        // format admits is a named assumption, and certificates emitted
        // beside code compiled under one would read as covering it.
        self.refuse_box_derefs_for_proof_claim(
            module,
            self.config.emit_proofs
                || self.requires_verified_proof_promotion()
                || validation_mode.requires_jit_verification(),
        )?;
        let received = crate::ingest::admit_module(
            module,
            &self.codegen_license,
            &self.dialect_legalization_registry,
        )?;

        // Phase 0: Pre-adapter dialect legalization (#433, trust_ir #428,
        // ledger L05-P11), as in `compile`. A compile that makes a proof claim
        // (`emit_proofs`, or a JIT validation mode that requires proof-grade
        // evidence) admits only legalization rules whose evidence this compile
        // checks. Unknown dialects fail before the adapter and core-only
        // modules remain borrowed. Static-call recovery is fused into the
        // shared adapter below (the same path used by object builds), avoiding
        // another TrustIR pass.
        let dialect_start = Instant::now();
        let Legalized {
            module: lowered_module,
            report: dialect_legalization,
        } = self.legalize_dialects(
            module,
            self.requires_verified_proof_promotion() || validation_mode.requires_jit_verification(),
        )?;
        if tracing {
            trace_entries.push(TraceEntry {
                phase: "dialect_lower".to_string(),
                duration: dialect_start.elapsed(),
                detail: Some(format!(
                    "{} rewrites",
                    dialect_legalization
                        .as_ref()
                        .map_or(0, DialectLegalizationReport::rewritten_op_sites)
                )),
            });
        }
        let lowered_module = lowered_module.as_ref();
        // Admit the module that is LOWERED too (WS7.3; see `Self::compile`).
        let rewritten_admission;
        let admitted = if std::ptr::eq(lowered_module, module) {
            &received
        } else {
            rewritten_admission = crate::ingest::admit_rewritten(
                &received,
                lowered_module,
                &self.dialect_legalization_registry,
            )?;
            &rewritten_admission
        };
        // The JIT resolves a by-name reference through the module's own
        // functions before the host's symbols (`resolve_raw_internal_fixup`),
        // so a module-local `fmod` would receive `frem`'s call: refuse, as
        // every object path does.
        refuse_backend_symbol_shadow(lowered_module, || compiler_target_triple(self.target_spec))?;
        // trust-ir v41 `Global.section` is an OBJECT-placement request the JIT
        // cannot honor: refused by name, by the one JIT rule every JIT lane
        // calls (`refuse_jit_object_sections`).
        crate::object_sections::refuse_jit_object_sections(module)
            .map_err(CompileError::Pipeline)?;

        // Phase 1: Translate trust_ir module to internal LIR functions.
        // Sentinel S5 hardening: per-arch exact-bound carrier cap (see above).
        // TLS dialect follows the target triple's object format (see above).
        let adapter_start = Instant::now();
        let adapter_arch = guard_carrier_arch_for_target(self.config.target);
        // The adapter arch above is the ISA alone. The Swift return budget it
        // selects is System V's; refuse every Swift edge when this compile's
        // x86-64 C ABI is one with no witnessed swiftcc placement, rather than
        // let an unmeasured ABI inherit SysV's numbers.
        reject_unwitnessed_swift_conv_for_spec(lowered_module, self.target_spec)?;
        let tls_dialect =
            if crate::pipeline::target_triple_uses_elf(&compiler_target_triple(self.target_spec)) {
                trust_cg_lower::TlsDialect::ElfLocalExec
            } else {
                trust_cg_lower::TlsDialect::MachOTlv
            };
        self.adapter_aarch64_abi()?;
        let (lir_functions, static_call_stats, static_call_validation) =
            trust_cg_lower::translate_admitted_module_for_arch_with_tls_and_validation(
                admitted,
                adapter_arch,
                tls_dialect,
                tracing,
            )?;
        if tracing {
            trace_entries.push(TraceEntry {
                phase: "adapter".to_string(),
                duration: adapter_start.elapsed(),
                detail: Some(format!(
                    "{} functions, {}",
                    lir_functions.len(),
                    static_call_stats.unwrap_or_default().trace_detail()
                )),
            });
        }

        if lir_functions.is_empty() {
            return Err(CompileError::EmptyModule);
        }
        static_call_validation.replay_exact_module_bindings(&lir_functions)?;
        drop(static_call_validation);
        let mut lir_functions = lir_functions;

        // The shared pre-ISel LIR module step (OPT-4 inlining, inline-only
        // bodies, unsigned-range simplification): the AOT seam's passes, after
        // exact-binding replay and before any target dispatch, so both JIT
        // targets inherit it. Every downstream lowering proof takes the step's
        // output as its source and checks the lowering of it, not the step.
        // So a compile that makes a proof claim (`emit_proofs`, or a JIT
        // validation mode that requires proof-grade evidence for every
        // published function: `CachedVerified`, x86-64's default, and
        // `AlwaysVerify`) runs neither pass (ruling OD-225), and with them
        // splices no inline-only body. Its admission says so. See
        // `crate::lir_module_prep`, "Proof claims".
        let inline_only_admission = crate::lir_module_prep::InlineOnlyAdmission::for_proof_claim(
            self.requires_verified_proof_promotion() || validation_mode.requires_jit_verification(),
        );
        let dependencies: Vec<&trust_ir::Module> = self
            .inline_only_dependencies
            .iter()
            .map(std::sync::Arc::as_ref)
            .collect();
        let preparation = crate::lir_module_prep::prepare_jit_lir_module_never_inlining(
            &mut lir_functions,
            lowered_module,
            adapter_arch,
            tls_dialect,
            self.config.opt_level,
            inline_only_admission,
            admitted.license(),
            crate::lir_module_prep::JitExternBindings::Map(extern_symbols),
            crate::lir_module_prep::InlineOnlyAuthority {
                dependencies: &dependencies,
            },
            &self.config.never_inline,
        )?;
        if tracing && preparation.ran {
            trace_entries.push(TraceEntry {
                phase: "ir_inline".to_string(),
                duration: preparation.inline_duration,
                detail: Some(preparation.inline_trace_detail()),
            });
            trace_entries.push(TraceEntry {
                phase: "lir_unsigned_range".to_string(),
                duration: preparation.range_duration,
                detail: Some(preparation.range_trace_detail()),
            });
        }
        if tracing && preparation.skipped_for_proof_claim {
            trace_entries.push(TraceEntry {
                phase: crate::lir_module_prep::PROOF_CLAIM_SKIP_PHASE.to_string(),
                duration: Duration::ZERO,
                detail: Some(crate::lir_module_prep::PROOF_CLAIM_SKIP_DETAIL.to_string()),
            });
        }

        let mut result = self.compile_replayed_lir_module_to_jit(
            module,
            lowered_module,
            lir_functions,
            extern_symbols,
            profile_hooks,
            validation_mode,
            jit_config,
            total_start,
            tracing,
            trace_entries,
        )?;
        result.inline_only_bodies = preparation.inline_only;
        result.dialect_legalization = dialect_legalization;
        Ok(result)
    }

    /// Continue host-JIT compilation from the exact TrustIR module and the
    /// owned LIR whose exact-module calls were replayed by the caller.
    ///
    /// This boundary is deliberately private: the raw public path above must
    /// perform dialect lowering, adapter translation, and exact-call replay
    /// before any owned LIR can reach target-specific compilation. A future
    /// consuming admitted-Core entry may share this downstream pipeline, but
    /// exposing a raw pretranslated-LIR entry would make those checks
    /// bypassable.
    fn compile_replayed_lir_module_to_jit(
        &self,
        original_module: &trust_ir::Module,
        trust_ir_module: &trust_ir::Module,
        lir_functions: Vec<(trust_cg_lower::Function, trust_cg_lower::ProofContext)>,
        extern_symbols: &HashMap<String, *const u8>,
        profile_hooks: crate::jit::ProfileHookMode,
        validation_mode: JitValidationMode,
        jit_config: crate::jit::JitConfig,
        total_start: Instant,
        tracing: bool,
        mut trace_entries: Vec<TraceEntry>,
    ) -> Result<JitCompilationResult, CompileError> {
        if self.config.target == Target::X86_64 {
            return self.compile_x86_64_to_jit(
                lir_functions,
                extern_symbols,
                jit_config.external_symbol_resolution,
                profile_hooks,
                validation_mode,
                total_start,
                tracing,
                trace_entries,
                // OD-210: the module's own definitions of the runtime
                // routines a body theorem would trust; OD-216: and its link
                // unit's, as the frontend names them.
                &trust_cg_verify::X86ModuleDefinitions::of_trust_ir_module(trust_ir_module)
                    .with_link_unit(self.config.link_unit_definitions.iter().map(String::as_str)),
            );
        }

        // Exception-handling functions and `panic_unwind` walk frames publish
        // with in-memory unwind tables (`crate::jit_unwind`). That path has no
        // proof obligation, so every proof-grade request refuses it by name
        // before preparation: EH structure through the census every
        // proof-grade route shares, walk frames here.
        let requires_unwind_tables = !lir_functions.is_empty()
            && (self.config.panic_unwind
                || lir_functions
                    .iter()
                    .any(|(lir_func, _)| !lir_func.eh_info.is_empty()));
        if validation_mode.requires_jit_verification()
            || self.config.emit_proofs
            || self.requires_verified_proof_promotion()
        {
            ExceptionTableCensus::from_lir(&lir_functions)
                .refuse_proof_grade(ProofGradeRoute::ProofGradeJit, self.config.target)?;
            if self.config.panic_unwind
                && let Some((lir_func, _)) = lir_functions.first()
            {
                return Err(CompileError::Jit(
                    crate::jit::JitError::JitUnwindProofEvidenceUnavailable {
                        function: lir_func.name.clone(),
                    },
                ));
            }
        }

        // Build the internal pipeline.
        let aarch64_jit_isa_profile = self.effective_aarch64_jit_isa_profile();
        let pipeline = self
            .build_pipeline(aarch64_jit_isa_profile)
            .with_proof_grade_aarch64_publication_if(validation_mode.requires_jit_verification());

        // Phase 2+: Prepare each function through ISel, optimization,
        // regalloc, frame lowering, and branch resolution. The prepared
        // functions are then handed to the JIT compiler for in-memory code
        // generation and cross-function fixup resolution.
        //
        // When parallel compilation is enabled and there are 2+ functions,
        // use rayon to prepare functions concurrently. Each function's
        // pipeline (ISel -> opt -> regalloc -> frame -> branch resolution)
        // is fully independent with no shared mutable state.
        let parallel_worker_count = if self.config.parallel {
            crate::resource_limits::worker_count_for_items(lir_functions.len())?
        } else {
            None
        };
        let use_parallel = parallel_worker_count.is_some();
        let trust_ir_functions_for_lir =
            trust_ir_functions_for_lir(trust_ir_module, &lir_functions);
        // The bounded fsym preflight scans each function in this module:
        // decide its module-level facts once for all of them.
        // Each function is prepared SEALED: the final-stream check its
        // preparation ran and passed is kept beside it (by ordinal), and the
        // link below does not run that identical check a second time
        // (`TCG_NO_SEALED_JIT_LINK` restores the second run). `prepared_funcs`
        // is immutable from here to the link, so each check still describes
        // exactly the stream the encoder receives; the bytes are the same.
        let (prepared_funcs, prepared_checks, preparation_metrics) =
            with_fsym_module_scope(trust_ir_module, || {
                let mut prepared_funcs: Vec<trust_cg_ir::MachFunction>;
                let mut prepared_checks: Vec<crate::pipeline::Aarch64FinalStreamCheck>;
                let mut preparation_metrics: Vec<crate::pipeline::PreparationMetrics>;

                if use_parallel {
                    // Parallel path: each function is prepared independently via rayon.
                    // Collect results with optional trace entries, then unpack.
                    let preparation_environment =
                        trust_cg_process_env::EnvOverrideSnapshot::capture_current_thread();
                    let worker_count = parallel_worker_count.unwrap_or(1);
                    let pool = crate::resource_limits::build_rayon_pool(worker_count)
                        .map_err(|err| CompileError::Pipeline(PipelineError::WorkerPool(err)))?;
                    let results: Vec<
                        Result<
                            (
                                trust_cg_ir::MachFunction,
                                crate::pipeline::Aarch64FinalStreamCheck,
                                crate::pipeline::PreparationMetrics,
                                Option<TraceEntry>,
                            ),
                            CompileError,
                        >,
                    > = pool.install(|| {
                        lir_functions
                            .par_iter()
                            .zip(trust_ir_functions_for_lir.par_iter())
                            .map(|((lir_func, proof_ctx), trust_ir_func)| {
                                preparation_environment.run(|| {
                                    let func_start = Instant::now();
                                    let (checked, metrics) =
                                        if let Some(trust_ir_func) = *trust_ir_func {
                                            pipeline
                                                .prepare_function_checked_with_trust_ir_module(
                                                    lir_func,
                                                    Some(proof_ctx),
                                                    trust_ir_module,
                                                    trust_ir_func,
                                                )
                                                .map_err(CompileError::Pipeline)?
                                        } else {
                                            pipeline
                                                .prepare_function_checked(lir_func, Some(proof_ctx))
                                                .map_err(CompileError::Pipeline)?
                                        };
                                    let (ir_func, check) = checked.into_parts();
                                    let entry = if tracing {
                                        Some(TraceEntry {
                                            phase: "prepare_function".to_string(),
                                            duration: func_start.elapsed(),
                                            detail: Some(ir_func.name.clone()),
                                        })
                                    } else {
                                        None
                                    };
                                    Ok((ir_func, check, metrics, entry))
                                })
                            })
                            .collect()
                    });

                    prepared_funcs = Vec::with_capacity(results.len());
                    prepared_checks = Vec::with_capacity(results.len());
                    preparation_metrics = Vec::with_capacity(results.len());
                    for result in results {
                        let (ir_func, check, metrics, trace_entry) = result?;
                        if let Some(entry) = trace_entry {
                            trace_entries.push(entry);
                        }
                        preparation_metrics.push(metrics);
                        prepared_funcs.push(ir_func);
                        prepared_checks.push(check);
                    }
                } else {
                    // Sequential path: single function or parallel disabled.
                    prepared_funcs = Vec::with_capacity(lir_functions.len());
                    prepared_checks = Vec::with_capacity(lir_functions.len());
                    preparation_metrics = Vec::with_capacity(lir_functions.len());
                    for ((lir_func, proof_ctx), trust_ir_func) in
                        lir_functions.iter().zip(trust_ir_functions_for_lir.iter())
                    {
                        let func_start = Instant::now();

                        let (checked, metrics) = if let Some(trust_ir_func) = *trust_ir_func {
                            pipeline.prepare_function_checked_with_trust_ir_module(
                                lir_func,
                                Some(proof_ctx),
                                trust_ir_module,
                                trust_ir_func,
                            )?
                        } else {
                            pipeline.prepare_function_checked(lir_func, Some(proof_ctx))?
                        };
                        let (ir_func, check) = checked.into_parts();

                        if tracing {
                            trace_entries.push(TraceEntry {
                                phase: "prepare_function".to_string(),
                                duration: func_start.elapsed(),
                                detail: Some(ir_func.name.clone()),
                            });
                        }

                        preparation_metrics.push(metrics);
                        prepared_funcs.push(ir_func);
                        prepared_checks.push(check);
                    }
                }
                Ok::<_, CompileError>((prepared_funcs, prepared_checks, preparation_metrics))
            })?;

        let raw_dataflow_duration = validate_prepared_aarch64_dataflow_observations(
            &prepared_funcs,
            &lir_functions,
            &preparation_metrics,
            self.config.emit_proofs || self.requires_verified_proof_promotion(),
        )?;
        if let Some(duration) = raw_dataflow_duration.filter(|_| tracing) {
            trace_entries.push(TraceEntry {
                phase: "dataflow_integrity".to_string(),
                duration,
                detail: Some(format!(
                    "{} raw pre-optimization AArch64 functions (summed worker time)",
                    prepared_funcs.len()
                )),
            });
        }

        let function_count = prepared_funcs.len();
        let proof_optimization_certificates =
            collect_proof_optimization_certificates(&preparation_metrics);
        let fsym_trust_ir_metrics = summarize_fsym_trust_ir_metrics(&preparation_metrics);
        let pass_validation = merge_pass_validation(&preparation_metrics);
        let composed_transitions = collect_composed_transitions(&preparation_metrics);
        // L09-P3: a proof-required JIT requires every function a
        // TrustIR-bound legalization check covers to carry a composing record
        // before any certificate is generated or promoted; the installed
        // bytes are bound to its chain once the buffer exists.
        if validation_mode.requires_jit_verification()
            || self.config.emit_proofs
            || self.requires_verified_proof_promotion()
        {
            require_prepared_compositions(&prepared_funcs, &preparation_metrics)?;
        }
        // U10: the positive acknowledgment of every stack-limit request, and
        // the module reserve bound, from the final functions and their net
        // certificates (`docs/u10-prologue-stack-limit.md` §5-§6).
        let stack_limits = {
            let certificates: Vec<_> = preparation_metrics
                .iter()
                .map(|metrics| metrics.stack_limit_certificate.as_ref())
                .collect();
            aarch64_stack_limit_report(
                &prepared_funcs,
                &certificates,
                self.stack_limit_external_allowance,
            )
        };
        // Fold the already-captured post-RA evidence before executable memory
        // is published. This is intentionally not a second instruction-stream
        // scan: preparation performed the mandatory final validation walk and
        // retained its typed result in `PreparationMetrics`.
        let aarch64_machine_code = aggregate_aarch64_jit_machine_code_evidence(
            pipeline.aarch64_target_machine(),
            prepared_funcs
                .iter()
                .zip(preparation_metrics.iter())
                .map(|(func, metrics)| {
                    (
                        func.name.as_str(),
                        func.function_target_features,
                        metrics.aarch64_machine_code,
                    )
                }),
        )?;

        #[cfg(feature = "verify")]
        let proofs = if self.config.emit_proofs || self.requires_verified_proof_promotion() {
            let source_modules =
                trust_cg_verify::FunctionSourceModules::capture(original_module, trust_ir_module)
                    .map_err(|error| {
                    CompileError::Pipeline(PipelineError::NoTmbcWireImage(error.to_string()))
                })?;
            let proof_environment =
                trust_cg_process_env::EnvOverrideSnapshot::capture_current_thread();
            // The `JitCompiler` built from `jit_config` below encodes these
            // functions, so ENC-5's backing is its pipeline's, not the
            // preparation pipeline's.
            let a64_decode = crate::jit::JitCompiler::aarch64_decode_check_backing_for(&jit_config);
            let all_certs: Vec<ProofCertificate> =
                if use_parallel && !proof_promotion_live_solver_may_run() {
                    let worker_count = parallel_worker_count.unwrap_or(1);
                    let pool = crate::resource_limits::build_rayon_pool(worker_count)
                        .map_err(|err| CompileError::Pipeline(PipelineError::WorkerPool(err)))?;
                    pool.install(|| {
                        // TV-2: `prepared_funcs` is built 1:1 in `lir_functions`
                        // order, so the zip pairs each MachFunction with the LIR
                        // function its ISel consumed; the verifier additionally
                        // name-guards the pairing.
                        prepared_funcs
                            .par_iter()
                            .zip(lir_functions.par_iter())
                            .flat_map(|(func, (lir_func, _))| {
                                proof_environment.run(|| {
                                    generate_proof_certificates(
                                        func,
                                        Some(lir_func),
                                        Some(&source_modules),
                                        a64_decode,
                                    )
                                })
                            })
                            .collect()
                    })
                } else {
                    let mut certs = Vec::new();
                    for (func, (lir_func, _)) in prepared_funcs.iter().zip(lir_functions.iter()) {
                        certs.extend(generate_proof_certificates(
                            func,
                            Some(lir_func),
                            Some(&source_modules),
                            a64_decode,
                        ));
                    }
                    certs
                };
            Some(all_certs)
        } else {
            None
        };
        #[cfg(not(feature = "verify"))]
        let proofs: Option<Vec<ProofCertificate>> = None;
        self.ensure_proofs_promotable(proofs.as_deref())?;

        // Final phase: encode all prepared functions into executable memory,
        // resolve internal cross-function branches, and bind external symbols.
        let jit_start = Instant::now();
        let jit = crate::jit::JitCompiler::new_with_aarch64_isa_profile(
            jit_config,
            aarch64_jit_isa_profile,
        )
        .with_certificate_cache(self.jit_cert_cache());
        // Frame layouts recorded by this call's own preparation are the only
        // authority for the JIT's FDEs.
        let unwind_request = requires_unwind_tables.then(|| {
            crate::jit_unwind::Aarch64JitUnwindRequest::new(
                preparation_metrics
                    .iter()
                    .map(|metrics| metrics.frame_layout.clone())
                    .collect(),
                self.config.panic_unwind,
            )
        });
        // The module's data globals are placed in the JIT-owned data image
        // (the same object-global conversion the AOT emitters consume), so
        // `GlobalAddr` bodies address real storage instead of failing on an
        // unresolvable page relocation. Thread-locals, explicit sections and
        // weak imports are refused by name when a body names them.
        let object_globals = module_object_globals(trust_ir_module)?;
        let (mut buffer, encoding_timings) = jit
            .compile_with_lir_globals_and_encoding_metrics(
                &prepared_funcs,
                &lir_functions,
                original_module,
                trust_ir_module,
                &object_globals,
                (!sealed_jit_link_disabled()).then_some(prepared_checks.as_slice()),
                extern_symbols,
                self.config.emit_proofs || self.requires_verified_proof_promotion(),
                unwind_request.as_ref(),
            )
            .map_err(CompileError::Jit)?;
        buffer.attach_proof_optimization_certificates(proof_optimization_certificates.clone());

        // L09-P3: on a proof-required JIT route a function a TrustIR-bound
        // legalization check covers is published only with a composed chain
        // ending at exactly the bytes the buffer installed for it (its whole
        // installed range). This binding needs no certificate, so it runs
        // before the certificate and replay gates below.
        let mut composed_publications = 0;
        if validation_mode.requires_jit_verification()
            || self.config.emit_proofs
            || self.requires_verified_proof_promotion()
        {
            let code = buffer.code_slice();
            let ranges = buffer.function_ranges();
            for (func, metrics) in prepared_funcs.iter().zip(&preparation_metrics) {
                let Some(composed) = crate::composed_transition::require_composition(
                    &func.name,
                    metrics.composed_transition.as_ref(),
                )
                .map_err(composed_transition_refused)?
                else {
                    continue;
                };
                let published = ranges
                    .iter()
                    .find(|(name, _)| *name == func.name)
                    .and_then(|(_, range)| code.get(range.start as usize..range.end as usize))
                    .unwrap_or_default();
                #[cfg(test)]
                let mut flipped = published.to_vec();
                #[cfg(test)]
                crate::composed_transition::test_hooks::flip_published_byte(&mut flipped);
                #[cfg(test)]
                let published = flipped.as_slice();
                composed
                    .check_published(published)
                    .map_err(composed_transition_refused)?;
                composed_publications += 1;
            }
        }

        // JIT-5: fail-closed gate for the aarch64 JitCertificate path. Under a
        // verifying mode (CachedVerified / AlwaysVerify) every published
        // function must carry proof-grade verifier evidence whose normalized
        // bytes are cache-bound; exact published bytes are integrity-bound
        // separately. `ensure_proofs_promotable` above
        // only covers the compiler.rs ProofCertificate path (a no-op unless
        // object proofs were explicitly requested), so gate the buffer
        // certificates explicitly here.
        if validation_mode.requires_jit_verification() {
            let ranges: Vec<String> = buffer
                .function_ranges()
                .iter()
                .map(|(name, _)| name.clone())
                .collect();
            for name in &ranges {
                let certificate = buffer.certificate(name);
                let verified = certificate
                    .map(|c| c.has_checked_semantics())
                    .unwrap_or(false);
                if !verified {
                    // The certificate's request, when it had no AY bound,
                    // names that refusal (`JitCertificate::ay_refusal_note`).
                    return Err(self.unproved_evidence_rejected(
                        format!(
                            "aarch64 JIT function {name} has no non-vacuous proof-grade \
                             machine-IR certificate under {} mode",
                            validation_mode.label()
                        ),
                        certificate.and_then(|c| c.ay_refusal_note()),
                    ));
                }
            }
            // L11-P2: the publisher re-read the sealed mapping and replayed
            // it against every certified function before handing it out. The
            // replay re-reads bytes against verified certificates and runs no
            // solver, so no request's AY resolution bears on it.
            let replayed = buffer
                .installed_replay()
                .is_some_and(|record| record.covers_exactly(ranges.iter().map(String::as_str)));
            if !replayed {
                return Err(self.unproved_evidence_rejected(
                    format!(
                        "aarch64 JIT buffer has no installed-artifact replay covering every \
                         published function under {} mode",
                        validation_mode.label()
                    ),
                    None,
                ));
            }
        }

        if tracing {
            trace_entries.push(TraceEntry {
                phase: "compile_raw".to_string(),
                duration: jit_start.elapsed(),
                detail: Some(format!("{} functions", function_count)),
            });
        }

        let per_function_metrics: Vec<FunctionQualityMetrics> = prepared_funcs
            .iter()
            .zip(preparation_metrics)
            .map(|(func, prep_metrics)| {
                let static_stack_frame = prep_metrics.static_stack_frame();
                let mut phase_timings = prep_metrics.timings;
                phase_timings.encoding = encoding_timings.get(func.name.as_str()).copied();
                FunctionQualityMetrics {
                    name: func.name.clone(),
                    code_size_bytes: count_real_instructions(func) * 4,
                    instruction_count: count_real_instructions(func),
                    spill_slot_count: prep_metrics.spill_slot_count,
                    branch_count: count_branch_instructions(func),
                    x86_machine_code: X86MachineCodeEvidence::default(),
                    aarch64_machine_code: prep_metrics.aarch64_machine_code,
                    phase_timings,
                    static_stack_frame,
                    stack_limit: stack_limits.as_ref().and_then(|report| {
                        report
                            .functions
                            .iter()
                            .find(|summary| summary.name == func.name)
                            .cloned()
                    }),
                }
            })
            .collect();

        // Count actual non-pseudo instructions across all prepared functions.
        // Each AArch64 instruction is exactly 4 bytes, so code_size = count * 4.
        // This is the real instruction count, not the allocated JIT buffer size
        // which may include page alignment and veneer trampolines.
        let total_instruction_count: usize =
            prepared_funcs.iter().map(count_real_instructions).sum();
        let total_code_size = total_instruction_count * 4;

        // Query actual pass count from the optimization pipeline rather than
        // using hardcoded estimates (fixes #272).
        let opt_passes_per_func = {
            use trust_cg_opt::pipeline::{OptLevel as OptOptLevel, OptimizationPipeline};
            let opt_level = match self.config.opt_level {
                OptLevel::O0 => OptOptLevel::O0,
                OptLevel::O1 => OptOptLevel::O1,
                OptLevel::O2 => OptOptLevel::O2,
                OptLevel::O3 => OptOptLevel::O3,
            };
            OptimizationPipeline::new(opt_level).pass_count()
        };

        let metrics = CompilationMetrics {
            code_size_bytes: total_code_size,
            instruction_count: total_instruction_count,
            function_count,
            optimization_passes_run: opt_passes_per_func * function_count,
            proof_optimizations: summarize_proof_optimizations(&proof_optimization_certificates),
            fsym_trust_ir: fsym_trust_ir_metrics,
            pass_validation,
            composed_transitions,
            composed_publications,
        };

        let trace = if tracing {
            Some(CompilerTrace {
                entries: trace_entries,
                total_duration: total_start.elapsed(),
            })
        } else {
            None
        };

        // JIT-5: validation provenance for the aarch64 JitCertificate path.
        // Each published function's semantic verdict is read off the buffer's
        // normalized-bytes-bound certificate; exact sealed range integrity is
        // recorded independently. On the Unchecked default
        // path there are no certificates, so `functions` records uncovered
        // bytes honestly without paying to format/hash verifier inputs.
        let published_function_ranges = buffer.function_ranges();
        if published_function_ranges.len() != prepared_funcs.len() {
            return Err(CompileError::Jit(
                crate::jit::JitError::ValidationRangeCountMismatch {
                    validation_count: prepared_funcs.len(),
                    range_count: published_function_ranges.len(),
                },
            ));
        }
        for ((published_name, _), prepared_func) in
            published_function_ranges.iter().zip(prepared_funcs.iter())
        {
            if *published_name != prepared_func.name {
                return Err(CompileError::Jit(
                    crate::jit::JitError::ValidationFunctionNameMismatch {
                        validation_function: prepared_func.name.clone(),
                        range_function: published_name.clone(),
                    },
                ));
            }
        }

        let validation = {
            let image_sha = buffer.published_image_sha256().to_string();
            let code = buffer.code_slice();
            let functions = published_function_ranges
                .iter()
                .map(|(name, range)| {
                    let certificate = buffer.certificate(name);
                    let verified = certificate.is_some_and(|c| c.has_checked_semantics());
                    let verifier_input_sha256 = certificate
                        .map(|c| c.verifier_input_sha256().to_string())
                        .unwrap_or_default();
                    let start = range.start as usize;
                    let end = (range.end as usize).min(code.len());
                    let bytes_sha256 = if start <= end && end <= code.len() {
                        crate::jit_diagnostics::sha256_hex(&code[start..end])
                    } else {
                        String::new()
                    };
                    JitFunctionValidation {
                        function: name.clone(),
                        verified,
                        verifier_input_sha256,
                        bytes_sha256,
                        cache_hit: certificate.is_some_and(|c| c.served_from_cache()),
                    }
                })
                .collect();
            Some(JitValidationProvenance {
                mode: validation_mode,
                published_image_sha256: image_sha,
                functions,
            })
        };

        Ok(JitCompilationResult {
            buffer,
            metrics,
            trace,
            proofs,
            proof_optimization_certificates,
            per_function_metrics,
            host_jit_selected_codegen_profile: None,
            aarch64_machine_code: Some(aarch64_machine_code),
            validation,
            inline_only_bodies: Default::default(),
            stack_limits,
            dialect_legalization: None,
        })
    }

    /// Build the internal [`Pipeline`] from the compiler configuration.
    fn build_pipeline(&self, aarch64_isa_profile: AArch64IsaProfile) -> Pipeline {
        let pipeline = Pipeline::new(PipelineConfig {
            opt_level: self.config.opt_level,
            emit_debug: self.config.emit_debug,
            verify_dispatch: crate::pipeline::DispatchVerifyMode::FallbackOnFailure,
            verify: false,
            cegis_superopt_budget_sec: self.config.cegis_superopt_budget_sec,
            target_triple: compiler_target_triple(self.target_spec),
            enable_fsym_trust_ir_preflight: self.config.enable_fsym_trust_ir_preflight,
            enable_jit_fast_regalloc: self.config.enable_jit_fast_regalloc,
            // The CompilerConfig-driven AOT/host-JIT path keeps the default
            // redundancy-elimination behaviour; only the explicit TY kernel
            // PipelineConfig opts into skipping CSE/GVN.
            skip_cse_gvn: false,
            disabled_passes_override: None,
            contains4_scanner_batch_rewrite_override: None,
            relocation_model: self.config.relocation_model,
            aarch64_force_frame_pointers: self.config.aarch64_force_frame_pointers,
        })
        .with_aarch64_isa_profile(aarch64_isa_profile)
        .with_function_sections(self.config.function_sections)
        .with_eh_frames_cannot_unwind(
            self.config
                .eh_frames_cannot_unwind
                .then(|| std::sync::Arc::new(self.config.eh_nounwind_callees.clone())),
        )
        // A proof-required compile publishes only proof-grade AArch64 bytes:
        // no environment downgrade of the final-stream nets and no ambient
        // late-layout control. Verifying JIT routes select the same policy.
        .with_proof_grade_aarch64_publication_if(self.config.emit_proofs)
        // ADMISSION MUST NOT DEPEND ON PROOF EMISSION.
        //
        // This selector used to read `self.config.emit_proofs ||
        // self.requires_verified_proof_promotion()` (the latter is literally
        // `self.config.emit_proofs`, see `requires_verified_proof_promotion`),
        // so turning certificates OFF also turned the raw TV-3
        // dataflow-integrity validator off: the aarch64 arch default is
        // `Warn`, and `Ambient { audit_default_warn: false }` with no
        // `TCG_DATAFLOW_INTEGRITY` and no trace does not even EVALUATE it
        // (`pipeline::check_raw_aarch64_dataflow_integrity`). The observable
        // consequence was that a compile with `-Ztrust-ir-cg-args=
        // no-proof-certs` ADMITTED functions that the same compile with
        // certificates REFUSED: measured on `library/core` at trust-cg
        // `9da5e237`, 353 failed roots without certs against 363 with them,
        // the 10-root difference being exactly the `[TCG-REGALLOC-063]`
        // code-after-unconditional-terminator (switch-BST block-collision)
        // rejections. Those ten objects were EMITTED in the no-certs mode.
        //
        // A certificate is evidence ABOUT a compile; it may never be the thing
        // that decides whether the compile is allowed. The validator is a
        // correctness gate on the ISel→shared-IR boundary, so it runs at
        // proof grade in both modes and the refusal set is now identical with
        // certificates on and off. `ProofGradeEnforce` names the STRENGTH of
        // the check (enforce, ambient-override-free), not the reason for it.
        .with_raw_dataflow_policy(Aarch64DataflowIntegrityPolicy::ProofGradeEnforce);

        let pipeline =
            if self.production_certified_pass_chain && self.certified_pass_chain.is_none() {
                pipeline.with_certified_pass_execution()
            } else {
                pipeline
            };

        let pipeline = if let Some(profile) = self.profile_use.clone() {
            pipeline.with_profile_use(profile)
        } else {
            pipeline
        };

        if let Some(sink) = self.profile_generate_sink.clone() {
            pipeline.with_profile_generate_sink(sink)
        } else {
            pipeline
        }
    }

    /// Symbol-access model for AOT object emission.
    ///
    /// AArch64 ELF honors every [`RelocationModel`]; other ELF architectures
    /// keep the fixed local-exec TLS dialect and Mach-O/COFF keep Darwin TLV,
    /// and those routes refuse `pie`/`pic` rather than emit code for a link
    /// contract their emitters do not implement.
    /// The AArch64 calling convention the TrustIR adapter uses for its
    /// ABI-dependent call-boundary decisions (caller-side narrow-argument
    /// extension, Swift aggregate register fit).
    ///
    /// Resolved from the same target triple, by the same function, as the
    /// pipeline's [`crate::pipeline::Pipeline::resolved_aarch64_abi`], so the
    /// adapter and instruction selection classify every call under one
    /// convention. Non-AArch64 targets have none. An AArch64 triple with no
    /// modeled convention is refused here rather than classified as Darwin.
    fn adapter_aarch64_abi(
        &self,
    ) -> Result<Option<trust_cg_lower::AArch64AbiVariant>, CompileError> {
        if self.config.target != Target::Aarch64 {
            return Ok(None);
        }
        trust_cg_lower::AArch64AbiVariant::from_target_triple(&compiler_target_triple(
            self.target_spec,
        ))
        .map(Some)
        .map_err(|error| CompileError::Pipeline(PipelineError::TargetAbiUnresolved(error)))
    }

    fn aot_object_access_model(&self) -> Result<trust_cg_lower::ObjectAccessModel, CompileError> {
        let triple = compiler_target_triple(self.target_spec);
        let elf = crate::pipeline::target_triple_uses_elf(&triple);
        if elf && self.config.target == Target::Aarch64 {
            return Ok(trust_cg_lower::ObjectAccessModel::elf(
                self.config.relocation_model,
            ));
        }
        if self.config.relocation_model != RelocationModel::Static {
            return Err(CompileError::RelocationModelUnsupported {
                target: triple,
                model: self.config.relocation_model,
                reason: "only AArch64 ELF object emission implements the `pie` and `pic` \
                         access models",
            });
        }
        // AArch64 Mach-O objects are loaded by dyld, which coalesces
        // default-visibility weak definitions across images: address those
        // through the GOT (see `ObjectAccessModel::macho_dyld`).
        if !elf
            && self.config.target == Target::Aarch64
            && crate::pipeline::target_triple_uses_macho(&triple)
        {
            return Ok(trust_cg_lower::ObjectAccessModel::macho_dyld());
        }
        Ok(if elf {
            trust_cg_lower::TlsDialect::ElfLocalExec
        } else {
            trust_cg_lower::TlsDialect::MachOTlv
        }
        .into())
    }

    /// The same compiler-owned native prototype context for preflight and
    /// compilation. The module decides only whether there is a record to
    /// consume; its target metadata never selects the native pipeline.
    fn native_scalar_c_abi(
        &self,
        module: &trust_ir::Module,
    ) -> Result<Option<trust_cg_lower::NativeAbiContext>, CompileError> {
        if !module
            .func_types
            .iter()
            .any(|signature| signature.abi.is_some())
        {
            return Ok(None);
        }
        let triple = compiler_target_triple(self.target_spec);
        match self.config.target {
            Target::Aarch64 => Ok(Some(trust_cg_lower::NativeAbiContext::aarch64(triple)?)),
            Target::X86_64
                if x86_call_abi_for_target_spec(self.target_spec)
                    == trust_cg_lower::x86_64_isel::X86CallAbi::SystemV =>
            {
                Ok(Some(trust_cg_lower::NativeAbiContext::x86_system_v(
                    triple,
                )?))
            }
            _ => Ok(None),
        }
    }

    fn ensure_host_jit_target(&self) -> Result<(), CompileError> {
        if self.config.aarch64_force_frame_pointers {
            return Err(CompileError::Aarch64FramePointersUnsupported {
                target: compiler_target_triple(self.target_spec),
                reason: "in-process JIT does not model forced object frame records",
            });
        }
        if self.config.eh_frames_cannot_unwind {
            return Err(CompileError::EhFramesCannotUnwindUnsupported {
                target: compiler_target_triple(self.target_spec),
                reason: "in-process JIT unwind registration does not model non-unwinding \
                         exception frames",
            });
        }
        if let Some(profile) = self.config.aarch64_isa_profile {
            return Err(CompileError::Aarch64IsaProfileUnsupported {
                target: compiler_target_triple(self.target_spec),
                profile,
                reason: "in-process JIT code admits exactly the host CPU's detected features",
            });
        }
        if self.config.relocation_model != RelocationModel::Static {
            return Err(CompileError::RelocationModelUnsupported {
                target: compiler_target_triple(self.target_spec),
                model: self.config.relocation_model,
                reason: "in-process JIT code is never linked, so it has no relocation model; \
                         only `static` is accepted",
            });
        }
        let host = Target::host();
        if self.config.target != host {
            return Err(CompileError::JitTargetMismatch {
                target: self.config.target,
                host,
            });
        }

        // Executable-memory compilation is an exact host ABI operation, not
        // merely an architecture match. DarwinPCS/AAPCS64 and the x86 object
        // ABIs differ in stack arguments, TLS, unwind, and symbol semantics.
        let host_spec = TargetSpec::host_for_architecture(host);
        if self.target_spec != host_spec {
            return Err(CompileError::JitTargetSpecMismatch {
                requested: self.target_spec,
                host: host_spec,
            });
        }

        match self.config.target {
            Target::Aarch64 | Target::X86_64 => Ok(()),
            Target::Riscv64 => Err(CompileError::JitTargetUnsupported {
                target: self.config.target,
            }),
        }
    }
}

