    /// adapter's report-reuse row). The entry is called only by the strict
    /// adapter's wrapper; the wrapper by Core admission's helper and that
    /// unit row; the helper, private to Core admission, by admission and its
    /// unit rows.
    const PINNED_CORE_TOKEN_MENTIONS: [((&str, &str), usize); 13] = [
        (
            (
                "crates/trust-cg-codegen/src/core_admission.rs",
                "CoreQualificationFollows",
            ),
            1,
        ),
        (
            (
                "crates/trust-cg-codegen/src/core_admission.rs",
                "caller_runs_core_qualification",
            ),
            1,
        ),
        (
            (
                "crates/trust-cg-codegen/src/core_admission.rs",
                "translate_validated_core_module_for_target",
            ),
            5,
        ),
        (
            (
                "crates/trust-cg-codegen/src/core_admission.rs",
                "translate_validated_core_module_under_core_qualification",
            ),
            2,
        ),
        (
            (
                "crates/trust-cg-codegen/src/strict_adapter.rs",
                "CoreQualificationFollows",
            ),
            2,
        ),
        (
            (
                "crates/trust-cg-codegen/src/strict_adapter.rs",
                "caller_runs_core_qualification",
            ),
            1,
        ),
        (
            (
                "crates/trust-cg-codegen/src/strict_adapter.rs",
                "translate_validated_core_module_under_core_qualification",
            ),
            2,
        ),
        (
            (
                "crates/trust-cg-codegen/src/strict_adapter.rs",
                "translate_validated_module_strict_for_core_qualification",
            ),
            1,
        ),
        (
            (
                "crates/trust-cg-lower/src/adapter.rs",
                "CoreQualificationFollows",
            ),
            6,
        ),
        (
            (
                "crates/trust-cg-lower/src/adapter.rs",
                "caller_runs_core_qualification",
            ),
            2,
        ),
        (
            (
                "crates/trust-cg-lower/src/adapter.rs",
                "translate_validated_module_strict_for_core_qualification",
            ),
            2,
        ),
        (
            (
                "crates/trust-cg-lower/src/lib.rs",
                "CoreQualificationFollows",
            ),
            1,
        ),
        (
            (
                "crates/trust-cg-lower/src/lib.rs",
                "translate_validated_module_strict_for_core_qualification",
            ),
            1,
        ),
    ];

    fn pinned_core_token_mentions() -> std::collections::BTreeMap<(String, &'static str), usize> {
        PINNED_CORE_TOKEN_MENTIONS
            .into_iter()
            .map(|((path, name), count)| {
                let name = CORE_TOKEN_NAMES
                    .into_iter()
                    .find(|listed| *listed == name)
                    .expect("a pinned name is listed");
                ((path.to_string(), name), count)
            })
            .collect()
    }

    /// Drift: `trust_cg_lower::CoreQualificationFollows` lets a translation
    /// skip the backend-symbol refusal, because Core's own qualification
    /// refuses every backend call. Its constructor is `unsafe`, and closed-JIT
    /// Core admission's private helper is the one place that constructs it.
    /// Every mention of the token, its constructor, the entry that takes it
    /// and the two helpers that forward it is pinned per file, across every
    /// Rust source of the checkout, tests included (this file's own names are
    /// string literals and do not count). A new construction (by the
    /// constructor, or by `transmute` or any other means that names the token
    /// or the entry) or a new caller of a helper fails here.
    #[test]
    fn only_core_admission_constructs_the_core_qualification_token() {
        assert_eq!(
            core_token_mentions(&workspace_rust_sources()),
            pinned_core_token_mentions(),
            "a Rust source names the Core qualification token, its constructor, the entry that \
             takes it or a helper that forwards it outside the pinned sites"
        );
    }

    /// The token row on plants: the verifier's `transmute` forgery and a new
    /// non-Core caller of the strict adapter's wrapper in `jit.rs`, a second
    /// caller of Core admission's helper, a raw-identifier spelling and an
    /// unsafe construction in `fuzz/`, each appended to a copy of the real
    /// sources, change the census; comments and literals do not.
    #[test]
    fn the_core_token_row_sees_every_planted_construction() {
        let sources = workspace_rust_sources();
        let pinned = pinned_core_token_mentions();
        let planted = |path: &str, plant: &str| {
            let mut sources = sources.clone();
            match sources.iter_mut().find(|(file, _)| file == path) {
                Some((_, text)) => text.push_str(plant),
                None => sources.push((path.to_string(), plant.to_string())),
            }
            core_token_mentions(&sources)
        };
        for (label, path, plant) in [
            (
                "transmute forgery",
                "crates/trust-cg-codegen/src/jit.rs",
                "\npub fn forged() -> trust_cg_lower::CoreQualificationFollows {\n    \
                 unsafe { std::mem::transmute::<(), trust_cg_lower::CoreQualificationFollows>(()) }\n}\n",
            ),
            (
                "non-Core wrapper caller",
                "crates/trust-cg-codegen/src/jit.rs",
                "\npub fn wrapper(report: &trust_ir_build::ModuleValidationReport<'_>, token: T) {\n    \
                 let _ = crate::strict_adapter::translate_validated_core_module_under_core_qualification(\n        \
                 report, crate::target::TargetSpec::default(), token);\n}\n",
            ),
            (
                "second Core helper caller",
                "crates/trust-cg-codegen/src/core_admission.rs",
                "\npub fn second(report: &trust_ir_build::ModuleValidationReport<'_>) {\n    \
                 let _ = translate_validated_core_module_for_target(report, TargetSpec::default());\n}\n",
            ),
            (
                "raw identifier",
                "crates/trust-cg-codegen/src/jit.rs",
                "\nfn raw() { let _ = unsafe { r#CoreQualificationFollows::r#caller_runs_core_qualification() }; }\n",
            ),
            (
                "entry through a renaming import",
                "fuzz/fuzz_targets/plant.rs",
                "\nuse trust_cg_lower::translate_validated_module_strict_for_core_qualification as harmless;\n",
            ),
        ] {
            assert_ne!(planted(path, plant), pinned, "{label}");
        }
        for (label, plant) in [
            (
                "line comment",
                "\n// CoreQualificationFollows::caller_runs_core_qualification()\n",
            ),
            (
                "doc comment",
                "\n/// [`CoreQualificationFollows`]\nfn documented() {}\n",
            ),
            (
                "string literal",
                "\nconst NAME: &str = \"caller_runs_core_qualification\";\n",
            ),
        ] {
            assert_eq!(
                planted("crates/trust-cg-codegen/src/jit.rs", plant),
                pinned,
                "{label}"
            );
        }
    }

    /// Drift: the shared module-local data classification agrees, for every
    /// trust-ir linkage, with the compiler's object-global mapping binding a
    /// defined global neither external nor imported (`STB_LOCAL`).
    #[test]
    fn module_local_data_classification_matches_the_object_global_binding() {
        use trust_ir::Linkage;
        for linkage in [
            Linkage::External,
            Linkage::Internal,
            Linkage::Private,
            Linkage::Weak,
            Linkage::LinkOnce,
            Linkage::WeakOdr,
            Linkage::LinkOnceOdr,
            Linkage::AvailableExternally,
            Linkage::ExternalWeak,
        ] {
            let mut module = trust_ir::Module::new("data_classification");
            let global = trust_ir::Global {
                name: "g".into(),
                ty: trust_ir::Ty::I64,
                mutable: true,
                initializer: Some(trust_ir::Constant::Int(1)),
                linkage,
                tls: None,
                align: Some(8),
                section: None,
                visibility: trust_ir::Visibility::Default,
                retained: false,
            };
            let classified = trust_cg_lower::is_module_local_data_definition(&global);
            module.globals.push(global);
            let binds_local = module_object_globals(&module)
                .ok()
                .and_then(|globals| globals.into_iter().next())
                .is_some_and(|object| !object.is_external && !object.is_import);
            assert_eq!(classified, binds_local, "{linkage}");
        }
    }

    /// Drift: the shared data-definition classification
    /// (`trust_cg_lower::is_data_definition`) agrees with the compiler's
    /// object-global mapping emitting the global as a definition (not an
    /// import) for every trust-ir linkage, with and without an initializer,
    /// thread-local or not. A combination the mapping refuses is never a
    /// definition.
    #[test]
    fn data_definition_classification_matches_the_object_global_mapping() {
        use trust_ir::Linkage;
        for linkage in [
            Linkage::External,
            Linkage::Internal,
            Linkage::Private,
            Linkage::Weak,
            Linkage::LinkOnce,
            Linkage::WeakOdr,
            Linkage::LinkOnceOdr,
            Linkage::AvailableExternally,
            Linkage::ExternalWeak,
        ] {
            for initialized in [true, false] {
                for tls in [None, Some(trust_ir::TlsModel::GeneralDynamic)] {
                    let global = trust_ir::Global {
                        name: "g".into(),
                        ty: trust_ir::Ty::I64,
                        mutable: true,
                        initializer: initialized.then_some(trust_ir::Constant::Int(1)),
                        linkage,
                        tls,
                        align: Some(8),
                        section: None,
                        visibility: trust_ir::Visibility::Default,
                        retained: false,
                    };
                    let classified = trust_cg_lower::is_data_definition(&global);
                    let mut module = trust_ir::Module::new("data_definition");
                    module.globals.push(global);
                    let defined = module_object_globals(&module)
                        .ok()
                        .and_then(|globals| globals.into_iter().next())
                        .is_some_and(|object| !object.is_import);
                    assert_eq!(
                        classified, defined,
                        "{linkage} initialized={initialized} tls={tls:?}"
                    );
                }
            }
        }
    }

    /// What one relocation in [`code_reference_check_object`] reaches.
    #[derive(Clone, Copy)]
    enum CodeTarget {
        /// An undefined global symbol.
        Undefined,
        /// A local function in `.text`.
        Function,
        /// A local object in `.data`.
        DataObject,
        /// The `.data` section symbol.
        DataSection,
    }

    /// A small AArch64 ELF object: `caller` in `.text` with, when `branch`
    /// is set, one branch relocation of that type to its target; a local
    /// function `fn_target` in `.text`; a local object `data_target` in
    /// `.data`; and, when `slot` is set, an 8-byte cell in its own data
    /// section labelled `slot.0` (bound local) holding `ABS64` of its target.
    fn code_reference_check_object(
        branch: Option<(crate::elf::AArch64RelocType, CodeTarget)>,
        slot: Option<(&str, CodeTarget)>,
    ) -> Vec<u8> {
        use crate::elf::constants::{
            SHF_ALLOC, SHF_EXECINSTR, SHF_WRITE, SHT_PROGBITS, STT_FUNC, STT_NOTYPE, STT_OBJECT,
            STT_SECTION, STV_DEFAULT,
        };
        use crate::elf::{AArch64RelocType, Elf64Rela, ElfMachine, ElfSymbol, ElfWriter};
        let mut writer = ElfWriter::new(ElfMachine::AArch64);
        let code: Vec<u8> = [0x9400_0000u32, 0xd65f_03c0, 0xd65f_03c0]
            .iter()
            .flat_map(|word| word.to_le_bytes())
            .collect();
        let text = writer
            .add_section(".text", &code, SHT_PROGBITS, SHF_ALLOC | SHF_EXECINSTR, 4)
            .unwrap();
        let data = writer
            .add_section(".data", &[0u8; 8], SHT_PROGBITS, SHF_ALLOC | SHF_WRITE, 8)
            .unwrap();
        let slot_section = slot.map(|(label, _)| {
            writer
                .add_section(
                    &format!(".data.{label}"),
                    &[0u8; 8],
                    SHT_PROGBITS,
                    SHF_ALLOC | SHF_WRITE,
                    8,
                )
                .unwrap()
        });
        let symbol =
            |name: &str, section: u16, value: u64, size: u64, global: bool, kind: u8| ElfSymbol {
                name: name.to_string(),
                section,
                value,
                size,
                is_global: global,
                sym_type: kind,
                is_weak: false,
                visibility: STV_DEFAULT,
            };
        writer
            .add_checked_symbol(symbol("caller", text, 0, 4, true, STT_FUNC))
            .unwrap();
        let function = writer
            .add_checked_symbol(symbol("fn_target", text, 4, 4, false, STT_FUNC))
            .unwrap();
        let object = writer
            .add_checked_symbol(symbol("data_target", data, 0, 8, false, STT_OBJECT))
            .unwrap();
        let data_section = writer
            .add_checked_symbol(symbol("", data, 0, 0, false, STT_SECTION))
            .unwrap();
        let undefined = writer
            .add_checked_symbol(symbol("undefined_target", 0, 0, 0, true, STT_NOTYPE))
            .unwrap();
        let slot_label = slot.zip(slot_section).map(|((label, _), section)| {
            writer
                .add_checked_symbol(symbol(label, section, 0, 8, false, STT_OBJECT))
                .unwrap()
        });
        let indices = [function, object, data_section, undefined]
            .map(|index| writer.final_symbol_index(index).unwrap());
        if let Some(label) = slot_label {
            writer.final_symbol_index(label).unwrap();
        }
        let resolve = |target: CodeTarget| match target {
            CodeTarget::Function => indices[0],
            CodeTarget::DataObject => indices[1],
            CodeTarget::DataSection => indices[2],
            CodeTarget::Undefined => indices[3],
        };
        if let Some((kind, target)) = branch {
            writer.add_relocation(
                usize::from(text) - 1,
                Elf64Rela::aarch64(0, resolve(target), kind, 0),
            );
        }
        if let Some(((_, target), section)) = slot.zip(slot_section) {
            writer.add_relocation(
                usize::from(section) - 1,
                Elf64Rela::aarch64(0, resolve(target), AArch64RelocType::Abs64, 0),
            );
        }
        writer.write_checked().unwrap()
    }

    /// The code-reference check behind the data refusal reads the object
    /// bytes. A `CALL26`/`JUMP26` to an undefined symbol or a local function,
    /// a `DW.ref.*` slot holding a function's or an undefined symbol's
    /// address, and an ordinary data slot holding a data address pass. A
    /// `CALL26` or `JUMP26` whose symbol (a local object, or the data section
    /// symbol) lies in `.data`, a `DW.ref.*` slot holding a data address, and
    /// bytes that are not ELF are refused.
    #[test]
    fn code_reference_check_refuses_a_branch_or_personality_into_data() {
        use crate::elf::AArch64RelocType;
        let triple = "aarch64-unknown-linux-gnu";
        let slot = "DW.ref.__gxx_personality_v0";
        for (label, object) in [
            (
                "call undefined",
                code_reference_check_object(
                    Some((AArch64RelocType::Call26, CodeTarget::Undefined)),
                    None,
                ),
            ),
            (
                "call function",
                code_reference_check_object(
                    Some((AArch64RelocType::Call26, CodeTarget::Function)),
                    None,
                ),
            ),
            (
                "tail call function",
                code_reference_check_object(
                    Some((AArch64RelocType::Jump26, CodeTarget::Function)),
                    None,
                ),
            ),
            (
                "personality function",
                code_reference_check_object(None, Some((slot, CodeTarget::Function))),
            ),
            (
                "personality undefined",
                code_reference_check_object(None, Some((slot, CodeTarget::Undefined))),
            ),
            (
                "data pointer",
                code_reference_check_object(None, Some(("user_table", CodeTarget::DataObject))),
            ),
        ] {
            check_elf_code_references_reach_code(triple, &object, &AARCH64_ELF_BRANCH_RELOCATIONS)
                .unwrap_or_else(|error| panic!("{label}: {error}"));
        }
        for (object, needle) in [
            (
                code_reference_check_object(
                    Some((AArch64RelocType::Call26, CodeTarget::DataObject)),
                    None,
                ),
                "`data_target`, defined in non-executable section",
            ),
            (
                code_reference_check_object(
                    Some((AArch64RelocType::Jump26, CodeTarget::DataSection)),
                    None,
                ),
                "a branch into data",
            ),
            (
                code_reference_check_object(None, Some((slot, CodeTarget::DataObject))),
                "the personality slot `DW.ref.__gxx_personality_v0` would hold a data address",
            ),
            (b"not an object".to_vec(), "does not parse as ELF"),
        ] {
            let error = check_elf_code_references_reach_code(
                triple,
                &object,
                &AARCH64_ELF_BRANCH_RELOCATIONS,
            )
            .expect_err("a code reference reaching data");
            assert!(
                matches!(
                    &error,
                    CompileError::AotCodeReferenceReachesData { detail, .. } if detail.contains(needle)
                ),
                "{needle}: {error}"
            );
        }
    }

    /// The module inliner withholds a body exactly when one of the two
    /// shared replacement predicates names it, each in its own scope: load
    /// time (`RelocationModel::definition_is_preemptible`, not for the ODR
    /// forms) on every target, static link
    /// (`trust_cg_lower::definition_is_link_replaceable`) on AArch64 only.
    /// Structural purity reads the same predicates on every target (the
    /// adapter's `structural_purity_reads_the_shared_replacement_predicates`).
    #[test]
    fn inliner_interposable_set_reads_the_shared_replacement_predicates() {
        use trust_ir::{Linkage, Visibility};
        let linkages = [
            Linkage::External,
            Linkage::Internal,
            Linkage::Private,
            Linkage::Weak,
            Linkage::LinkOnce,
            Linkage::WeakOdr,
            Linkage::LinkOnceOdr,
        ];
        let mut module = trust_ir::Module::new("inliner_replacement");
        let ft = module
            .add_func_type(trust_ir::FuncTy {
                params: vec![],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let mut rows = Vec::new();
        for linkage in linkages {
            for visibility in [
                Visibility::Default,
                Visibility::Hidden,
                Visibility::Protected,
            ] {
                if matches!(linkage, Linkage::Internal | Linkage::Private)
                    && visibility != Visibility::Default
                {
                    continue;
                }
                let id = trust_ir::FuncId::new(module.functions.len() as u32);
                let name = format!("f_{linkage:?}_{visibility:?}");
                let mut function =
                    trust_ir::Function::new(id, name.clone(), ft, trust_ir::BlockId::new(0));
                function.linkage = linkage;
                function.visibility = visibility;
                function.blocks = vec![trust_ir::Block {
                    id: trust_ir::BlockId::new(0),
                    params: vec![],
                    body: vec![trust_ir::InstrNode::new(trust_ir::Inst::Return {
                        values: vec![],
                    })],
                }];
                module
                    .try_add_function(function)
                    .expect("Module::try_add_function: test fixture");
                rows.push((name, linkage, visibility));
            }
        }
        assert_eq!(rows.len(), 17);
        for target in [Target::Aarch64, Target::X86_64, Target::Riscv64] {
            for model in RelocationModel::ALL {
                let excluded = inliner_interposable_function_names(&module, model, target);
                let mut expected = std::collections::HashSet::new();
                for (name, linkage, visibility) in &rows {
                    let preempted = !matches!(linkage, Linkage::WeakOdr | Linkage::LinkOnceOdr)
                        && model.definition_is_preemptible(
                            trust_cg_lower::DefinitionBinding::for_trust_ir_linkage(*linkage),
                            *visibility,
                        );
                    let replaced = trust_cg_lower::definition_is_link_replaceable(*linkage);
                    if preempted || replaced {
                        expected.insert(name.clone());
                    }
                }
                assert_eq!(excluded, expected, "{target:?} {model}");
            }
        }
        // Independent spot checks of the scope: AArch64 `pic` withholds the
        // default-visibility External body and all six Weak/LinkOnce bodies
        // (7; the default ODR forms stay inlinable); x86-64 and RISC-V
        // `static` withhold the six Weak/LinkOnce bodies they bind weak.
        assert_eq!(
            inliner_interposable_function_names(&module, RelocationModel::Pic, Target::Aarch64)
                .len(),
            7
        );
        assert_eq!(
            inliner_interposable_function_names(&module, RelocationModel::Static, Target::X86_64)
                .len(),
            6
        );
        assert_eq!(
            inliner_interposable_function_names(&module, RelocationModel::Static, Target::Riscv64)
                .len(),
            6
        );
    }

    /// Admission must not depend on proof emission.
    ///
    /// REGRESSION PIN. `build_pipeline` used to select the raw
    /// dataflow-integrity policy from `config.emit_proofs`, which made the
    /// TV-3 boundary validator — and therefore the `[TCG-REGALLOC-063]`
    /// refusals it raises — a function of whether certificates were being
    /// emitted. Measured on `library/core` at trust-cg `9da5e237`: 363 failed
    /// roots with certificates, 353 without, the difference being ten
    /// code-after-unconditional-terminator rejections that the no-certs mode
    /// silently EMITTED. A certificate is evidence about a compile; it may
    /// never decide whether the compile is admitted.
    ///
    /// The test asserts both halves: the policy is IDENTICAL in the two modes
    /// (so the refusal sets cannot diverge) and it is the ENFORCING policy (so
    /// the divergence is not "fixed" by silencing the gate in both modes).
    #[test]
    fn raw_dataflow_policy_is_independent_of_proof_emission() {
        let policy_with = |emit_proofs: bool| {
            let compiler = Compiler::new(CompilerConfig {
                target: Target::Aarch64,
                emit_proofs,
                ..CompilerConfig::default()
            })
            .with_codegen_license(permit_unlicensed());
            compiler
                .build_pipeline(AArch64IsaProfile::for_aot_target(compiler.target_spec))
                .raw_dataflow_policy()
        };

        assert_eq!(
            policy_with(false),
            policy_with(true),
            "turning proof certificates off changed the admission policy",
        );
        for emit_proofs in [false, true] {
            assert_eq!(
                policy_with(emit_proofs),
                crate::pipeline::Aarch64DataflowIntegrityPolicy::ProofGradeEnforce,
                "with emit_proofs={emit_proofs} the raw dataflow-integrity gate must ENFORCE: \
                 an identical policy that checks nothing would satisfy the equality above \
                 while losing the gate in both modes",
            );
        }
    }

    #[test]
    fn x86_exact_function_address_jit_catalog_rejects_profile_and_pool_only_images() {
        use crate::x86_64::pipeline::{X86Pipeline, X86PipelineConfig};
        use trust_cg_lower::function::Signature;
        use trust_cg_lower::instructions::Block;
        use trust_cg_lower::x86_64_isel::{X86ISelConstPoolEntry, X86ISelFunction};

        let pipeline = X86Pipeline::new(X86PipelineConfig {
            emit_frame: false,
            opt_level: trust_cg_opt::OptLevel::O0,
            ..Default::default()
        });
        for with_pool in [false, true] {
            let mut function = X86ISelFunction::new(
                "empty".into(),
                Signature {
                    params: vec![],
                    returns: vec![],
                },
            );
            function.ensure_block(Block(0));
            if with_pool {
                function.const_pool_entries.push(X86ISelConstPoolEntry {
                    data: vec![0x5a; 8],
                    align: 8,
                });
            }
            let (code, pool, _, _, _, has_instructions) = pipeline
                .compile_function_with_fixups_and_evidence_after_x86_passes(&function)
                .unwrap();
            assert!(code.is_empty());
            assert_eq!(!pool.is_empty(), with_pool);
            assert!(!has_instructions);
            let (profiled, has_profiled_instructions) = pipeline
                .compile_function_with_jit_block_counters_after_x86_passes(&function)
                .unwrap();
            assert!(
                !profiled.code.is_empty(),
                "control must contain actual profiling trampoline bytes"
            );
            assert!(!has_profiled_instructions);
            assert_eq!(!profiled.const_pool.is_empty(), with_pool);
            for has_body_instructions in [has_instructions, has_profiled_instructions] {
                // Same catalog constructor and resolver as the real pre-publication
                // JIT fixup loop; no executable memory is published on this ARM host.
                let catalog = HashMap::from([(
                    "empty".into(),
                    X86JitFunctionAddress::from_encoded_instructions(64, has_body_instructions),
                )]);
                assert!(resolve_x86_exact_function_offset(&catalog, "empty").is_err());
            }
        }
    }

    #[test]
    fn x86_exact_function_address_resolution_uses_only_canonical_function_names() {
        let functions = HashMap::from([
            (
                "foo".to_string(),
                X86JitFunctionAddress {
                    offset: 64,
                    has_code: true,
                },
            ),
            (
                "_foo".to_string(),
                X86JitFunctionAddress {
                    offset: 128,
                    has_code: true,
                },
            ),
            (
                "empty".to_string(),
                X86JitFunctionAddress {
                    offset: 256,
                    has_code: false,
                },
            ),
        ]);
        assert_eq!(
            resolve_x86_exact_function_offset(&functions, "foo").unwrap(),
            64
        );
        assert_eq!(
            resolve_x86_exact_function_offset(&functions, "_foo").unwrap(),
            128
        );
        let only_foo = HashMap::from([("foo".to_string(), functions["foo"])]);
        assert!(resolve_x86_exact_function_offset(&only_foo, "_foo").is_err());
        assert!(resolve_x86_exact_function_offset(&functions, "host_only").is_err());
        assert!(resolve_x86_exact_function_offset(&functions, "empty").is_err());

        // Cross-host byte check, not execution: RIP is the end of the LEA.
        for symbol in ["foo", "_foo"] {
            let mut code = vec![0x48, 0x8d, 0x05, 0, 0, 0, 0, 0xc3];
            let target = resolve_x86_exact_function_offset(&functions, symbol).unwrap();
            patch_x86_64_rel32_call(&mut code, 3, target).unwrap();
            let displacement = i32::from_le_bytes(code[3..7].try_into().unwrap());
            assert_eq!(7 + i64::from(displacement), target as i64);
            assert_eq!(&code[..3], &[0x48, 0x8d, 0x05]);
        }
    }

    fn test_aarch64_target_machine(
        target: TargetSpec,
        profile: AArch64IsaProfile,
    ) -> AArch64TargetMachine {
        AArch64TargetMachine::try_new(target, profile.into()).unwrap()
    }

    #[test]
    fn aarch64_jit_machine_code_evidence_fold_unions_existing_requirements() {
        use crate::target::AArch64IsaFeature;

        let machine = test_aarch64_target_machine(
            TargetSpec::parse("aarch64-apple-darwin").unwrap(),
            AArch64IsaProfile::APPLE_ARM64,
        );
        let lse = AArch64MachineCodeEvidence::try_new(
            &machine,
            OutputTargetFeatures::try_from_output([AArch64IsaFeature::Lse]).unwrap(),
        )
        .unwrap();
        let fp16 = AArch64MachineCodeEvidence::try_new(
            &machine,
            OutputTargetFeatures::try_from_output([AArch64IsaFeature::Fp16]).unwrap(),
        )
        .unwrap();

        let aggregate = aggregate_aarch64_jit_machine_code_evidence(
            &machine,
            [
                ("lse", TargetFeatureSet::EMPTY, Some(lse)),
                ("fp16", TargetFeatureSet::EMPTY, Some(fp16)),
            ],
        )
        .unwrap();
        assert_eq!(aggregate.target(), *machine.identity());
        assert_eq!(aggregate.admitted_features(), machine.admitted_features());
        assert_eq!(
            aggregate.required_features(),
            OutputTargetFeatures::try_from_output([
                AArch64IsaFeature::Lse,
                AArch64IsaFeature::Fp16,
            ])
            .unwrap()
        );
    }

    /// Per-function target features (L03-P9): each function's evidence must
    /// admit exactly the profile plus the features that function states. A
    /// stating function folds into a module admission of the profile plus the
    /// union of stated sets; evidence admitting more than its function states
    /// (even within the target's function ceiling) is refused, as is a
    /// stated set outside the ceiling.
    #[test]
    fn aarch64_jit_machine_code_evidence_fold_binds_each_functions_stated_features() {
        use crate::target::{AArch64IsaFeature, AdmittedTargetFeatures};

        let target = TargetSpec::parse("aarch64-apple-darwin").unwrap();
        let ceiling = [
            AArch64IsaFeature::Lse,
            AArch64IsaFeature::Crc,
            AArch64IsaFeature::Fp16,
        ]
        .into_iter()
        .fold(
            AdmittedTargetFeatures::NONE,
            AdmittedTargetFeatures::with_aarch64_feature,
        );
        let machine = AArch64TargetMachine::try_new_with_function_ceiling(
            target,
            AArch64IsaProfile::BASELINE.into(),
            ceiling,
        )
        .unwrap();
        let crc = TargetFeatureSet::from_aarch64_features([AArch64IsaFeature::Crc]);
        let evidence = |stated: TargetFeatureSet<AArch64IsaFeature>,
                        required: &[AArch64IsaFeature]| {
            AArch64MachineCodeEvidence::try_new(
                &machine.for_function(stated).unwrap(),
                OutputTargetFeatures::try_from_output(required.iter().copied()).unwrap(),
            )
            .unwrap()
        };

        let aggregate = aggregate_aarch64_jit_machine_code_evidence(
            &machine,
            [
                (
                    "states_crc",
                    crc,
                    Some(evidence(crc, &[AArch64IsaFeature::Crc])),
                ),
                (
                    "states_nothing",
                    TargetFeatureSet::EMPTY,
                    Some(evidence(TargetFeatureSet::EMPTY, &[])),
                ),
            ],
        )
        .unwrap();
        assert_eq!(
            aggregate.admitted_features(),
            machine.for_function(crc).unwrap().admitted_features()
        );
        assert!(
            aggregate
                .required_features()
                .requires(AArch64IsaFeature::Crc)
        );

        // Evidence admitting `crc` for a function that states nothing: the
        // admission lies within the ceiling, but this function was never
        // given it.
        let widened = aggregate_aarch64_jit_machine_code_evidence(
            &machine,
            [(
                "states_nothing",
                TargetFeatureSet::EMPTY,
                Some(evidence(crc, &[])),
            )],
        )
        .unwrap_err();
        assert!(matches!(
            widened,
            CompileError::Aarch64MachineCodeEvidencePipelineMismatch {
                function_name,
                expected_admitted,
                actual_admitted,
                ..
            } if function_name == "states_nothing"
                && expected_admitted == AArch64IsaProfile::BASELINE
                && actual_admitted
                    == AArch64IsaProfile::from_admitted_target_features(
                        machine.for_function(crc).unwrap().admitted_features()
                    )
        ));

        // A stated set beyond the ceiling is refused before any comparison.
        let dotprod = TargetFeatureSet::from_aarch64_features([AArch64IsaFeature::DotProd]);
        let outside = aggregate_aarch64_jit_machine_code_evidence(
            &machine,
            [(
                "states_dotprod",
                dotprod,
                Some(evidence(TargetFeatureSet::EMPTY, &[])),
            )],
        )
        .unwrap_err();
        assert!(
            matches!(
                outside,
                CompileError::Aarch64MachineCodeEvidenceInvalid { .. }
            ),
            "{outside:?}"
        );
    }

    /// A macOS deployment target changes the object's LC_BUILD_VERSION, so
    /// the artifact-cache identity binds it through the canonical triple; the
    /// unversioned triple keeps its pre-existing identity.
    #[test]
    fn compile_artifact_cache_identity_binds_the_macos_deployment_target() {
        let config = CompilerConfig {
            target: Target::Aarch64,
            ..CompilerConfig::default()
        };
        let options = |triple: &str| {
            let spec = TargetSpec::parse(triple).unwrap();
            (
                compiler_codegen_options_sha256(&config, spec, "").unwrap(),
                compiler_target_facts_sha256(Target::Aarch64, spec).unwrap(),
                compiler_target_triple(spec),
            )
        };
        let unversioned = options("aarch64-apple-darwin");
        let twelve = options("aarch64-apple-macos12.0");
        let thirteen = options("aarch64-apple-macos13.0");
        assert_eq!(unversioned.2, "aarch64-apple-darwin");
        assert_eq!(twelve.2, "aarch64-apple-macos12.0");
        assert_ne!(unversioned.0, twelve.0);
        assert_ne!(twelve.0, thirteen.0);
        assert_ne!(unversioned.1, twelve.1);
        assert_eq!(twelve, options("arm64-apple-macosx12.0"));
    }

    /// The adapter's ABI-dependent decisions use the convention the pipeline
    /// resolves from the same triple, never a Darwin default.
    #[test]
    fn adapter_aarch64_abi_follows_the_target_triple() {
        use trust_cg_lower::AArch64AbiVariant;

        let resolved = |triple: &str| {
            Compiler::new_for_target_spec(
                CompilerConfig::default(),
                TargetSpec::parse(triple).unwrap(),
            )
            .with_codegen_license(permit_unlicensed())
            .adapter_aarch64_abi()
        };
        assert_eq!(
            resolved("aarch64-unknown-linux-gnu").unwrap(),
            Some(AArch64AbiVariant::Aapcs64)
        );
        assert_eq!(
            resolved("aarch64-apple-darwin").unwrap(),
            Some(AArch64AbiVariant::Darwin)
        );
        assert_eq!(resolved("x86_64-unknown-linux-gnu").unwrap(), None);
        let refused = resolved("aarch64-unknown-unknown").unwrap_err();
        assert!(
            refused.to_string().contains("[TCG-TARGET-ABI]"),
            "unexpected refusal: {refused}"
        );
    }

    #[test]
    fn aarch64_jit_machine_code_evidence_fold_rejects_missing_or_mismatched_evidence() {
        let target = TargetSpec::parse("aarch64-apple-darwin").unwrap();
        let machine = test_aarch64_target_machine(target, AArch64IsaProfile::APPLE_ARM64);
        let baseline =
            AArch64MachineCodeEvidence::try_new(&machine, OutputTargetFeatures::NONE).unwrap();

        let missing = aggregate_aarch64_jit_machine_code_evidence(
            &machine,
            [
                ("present", TargetFeatureSet::EMPTY, Some(baseline)),
                ("missing", TargetFeatureSet::EMPTY, None),
            ],
        )
        .unwrap_err();
        assert!(matches!(
            missing,
            CompileError::Aarch64MachineCodeEvidenceMissing { function_name }
                if function_name == "missing"
        ));

        let other_target = test_aarch64_target_machine(
            TargetSpec::parse("aarch64-unknown-linux-gnu").unwrap(),
            AArch64IsaProfile::APPLE_ARM64,
        );
        let other_target_evidence =
            AArch64MachineCodeEvidence::try_new(&other_target, OutputTargetFeatures::NONE).unwrap();
        let target_mismatch = aggregate_aarch64_jit_machine_code_evidence(
            &machine,
            [(
                "wrong_target",
                TargetFeatureSet::EMPTY,
                Some(other_target_evidence),
            )],
        )
        .unwrap_err();
        assert!(matches!(
            target_mismatch,
            CompileError::Aarch64MachineCodeEvidencePipelineMismatch {
                function_name,
                expected_target,
                actual_target,
                ..
            } if function_name == "wrong_target"
                && expected_target == target
                && actual_target == *other_target.identity()
        ));

        let other_admission = test_aarch64_target_machine(target, AArch64IsaProfile::BASELINE);
        let other_admission_evidence =
            AArch64MachineCodeEvidence::try_new(&other_admission, OutputTargetFeatures::NONE)
                .unwrap();
        let admission_mismatch = aggregate_aarch64_jit_machine_code_evidence(
            &machine,
            [(
                "wrong_admission",
                TargetFeatureSet::EMPTY,
                Some(other_admission_evidence),
            )],
        )
        .unwrap_err();
        assert!(matches!(
            admission_mismatch,
            CompileError::Aarch64MachineCodeEvidencePipelineMismatch {
                function_name,
                expected_admitted,
                actual_admitted,
                ..
            } if function_name == "wrong_admission"
                && expected_admitted == AArch64IsaProfile::APPLE_ARM64
                && actual_admitted == AArch64IsaProfile::BASELINE
        ));
    }

    #[test]
    fn explicit_jit_validation_policies_do_not_query_the_legacy_environment() {
        for explicit in [
            JitValidationMode::Unchecked,
            JitValidationMode::CachedVerified,
            JitValidationMode::AlwaysVerify,
        ] {
            let mut config = CompilerConfig::jit_fast(Target::X86_64);
            config.jit_validation_mode_override = Some(explicit);
            let resolution = config
                .jit_validation_resolution_with(|| {
                    panic!("an explicit validation override consulted TCG_JIT_UNCHECKED")
                })
                .expect("an explicit validation override is a complete policy");
            assert_eq!(resolution.mode, explicit);
            assert_eq!(
                resolution.warning_via_env,
                (explicit == JitValidationMode::Unchecked
                    && !arch_default_jit_validation_mode(config.target).is_unchecked())
                .then_some(false)
            );
        }

        let mut proof_compatibility = CompilerConfig::jit_fast(Target::X86_64);
        proof_compatibility.jit_validation_mode_override = None;
        proof_compatibility.emit_proofs = true;
        let resolution = proof_compatibility
            .jit_validation_resolution_with(|| {
                panic!("emit_proofs compatibility policy consulted TCG_JIT_UNCHECKED")
            })
            .expect("emit_proofs is a complete AlwaysVerify policy");
        assert_eq!(resolution.mode, JitValidationMode::AlwaysVerify);
        assert_eq!(resolution.warning_via_env, None);

        let implicit_unchecked_target = if cfg!(feature = "verify") {
            Target::Aarch64
        } else {
            Target::X86_64
        };
        let implicit_unchecked = CompilerConfig::jit_fast(implicit_unchecked_target);
        assert!(
            arch_default_jit_validation_mode(implicit_unchecked.target).is_unchecked(),
            "test target must have an Unchecked architecture default"
        );
        let resolution = implicit_unchecked
            .jit_validation_resolution_with(|| {
                panic!("an already-Unchecked architecture default consulted TCG_JIT_UNCHECKED")
            })
            .expect("an Unchecked architecture default needs no escape hatch");
        assert_eq!(resolution.mode, JitValidationMode::Unchecked);
        assert_eq!(resolution.warning_via_env, None);
    }

    #[test]
    fn compiler_captures_ambient_jit_policy_once() {
        let validation = crate::env_lock::with_env_overrides(&[(JIT_UNCHECKED_ENV, "1")], || {
            let compiler = Compiler::new(CompilerConfig::jit_fast(Target::X86_64))
                .with_codegen_license(permit_unlicensed());
            assert_eq!(
                compiler.captured_jit_validation_mode().unwrap(),
                JitValidationMode::Unchecked
            );
            compiler
        });
        assert_eq!(
            validation.captured_jit_validation_mode().unwrap(),
            JitValidationMode::Unchecked,
            "an existing Compiler must retain its captured validation policy"
        );

        crate::env_lock::with_env_overrides_removed(&["TCG_NO_X86_JIT_LINEARSCAN"], || {
            let enabled = Compiler::new(CompilerConfig::jit_fast(Target::X86_64))
                .with_codegen_license(permit_unlicensed());
            assert!(enabled.effective_x86_jit_codegen_profile().fast_regalloc);
            crate::env_lock::with_env_overrides(&[("TCG_NO_X86_JIT_LINEARSCAN", "1")], || {
                let disabled = Compiler::new(CompilerConfig::jit_fast(Target::X86_64))
                    .with_codegen_license(permit_unlicensed());
                assert!(!disabled.effective_x86_jit_codegen_profile().fast_regalloc);
                assert!(
                    enabled.effective_x86_jit_codegen_profile().fast_regalloc,
                    "an existing Compiler must retain its captured policy"
                );
            });
        });
    }

