    #[cfg(all(feature = "verify", target_arch = "aarch64"))]
    fn admitted_core_exact_call_test_module(
        host_target: &crate::core_admission::CoreHostJitTarget,
    ) -> trust_ir::Module {
        use trust_ir::{
            Block, BlockId, FuncId, FuncTy, Function, Inst, InstrNode, Linkage, Ty, ValueId,
        };

        let mut module = trust_ir::Module::new("core-address-free-exact-call-fixture");
        module.target_info = Some(host_target.trust_ir_target_info().clone());
        let signature = module
            .add_func_type(FuncTy {
                params: vec![Ty::I64],
                returns: vec![Ty::I64],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");

        // Keep the caller first. The test checks the retained LIR order too:
        // a later callee refusal must follow the caller's binding checks.
        let mut entry = Function::new(FuncId::new(0), "entry", signature, BlockId::new(0));
        entry.linkage = Linkage::Internal;
        let mut entry_block = Block::new(BlockId::new(0));
        entry_block.params.push((ValueId::new(0), Ty::I64));
        entry_block.body.push(
            InstrNode::new(Inst::Call {
                callee: FuncId::new(1),
                args: vec![ValueId::new(0)],
            })
            .with_result(ValueId::new(1)),
        );
        entry_block.body.push(InstrNode::new(Inst::Return {
            values: vec![ValueId::new(1)],
        }));
        entry.blocks.push(entry_block);
        module
            .try_add_function(entry)
            .expect("Module::try_add_function: test fixture");

        let mut callee = Function::new(FuncId::new(1), "callee", signature, BlockId::new(0));
        callee.linkage = Linkage::Internal;
        let mut callee_block = Block::new(BlockId::new(0));
        callee_block.params.push((ValueId::new(0), Ty::I64));
        callee_block.body.push(InstrNode::new(Inst::Return {
            values: vec![ValueId::new(0)],
        }));
        callee.blocks.push(callee_block);
        module
            .try_add_function(callee)
            .expect("Module::try_add_function: test fixture");
        module
    }

