    #[test]
    fn proof_grade_aarch64_dataflow_rejects_violation_independent_of_ambient_mode() {
        use trust_cg_ir::{
            AArch64Opcode, BlockId as MachBlockId, InstId, LoweringProvenance, MachFunction,
            MachInst, MachOperand, Signature as MachSignature, SourceInstDigest, SourceInstId,
        };
        use trust_cg_lower::function::{BasicBlock, Signature};
        use trust_cg_lower::instructions::{Block, Instruction, Opcode};

        let mut lir = trust_cg_lower::Function::new("proof_dataflow", Signature::default());
        let block = Block(0);
        lir.block_order.push(block);
        lir.blocks.insert(
            block,
            BasicBlock {
                params: vec![],
                instructions: vec![Instruction {
                    opcode: Opcode::Return,
                    args: vec![],
                    results: vec![],
                }],
                source_locs: vec![],
            },
        );
        let lir_functions = vec![(lir, trust_cg_lower::ProofContext::default())];

        let mut machine = MachFunction::new(
            "proof_dataflow".to_owned(),
            MachSignature::new(vec![], vec![]),
        );
        machine.insts.push(MachInst::new(
            AArch64Opcode::B,
            vec![MachOperand::Block(MachBlockId(1))],
        ));
        machine
            .insts
            .push(MachInst::new(AArch64Opcode::AddRR, vec![]));
        machine.blocks[0].insts = vec![InstId(0), InstId(1)];
        machine.set_inst_lowering_provenance(
            InstId(1),
            LoweringProvenance::SourceInst {
                id: SourceInstId { block: 0, index: 0 },
                digest: SourceInstDigest(0),
                trust_ir_inst: None,
            },
        );
        let prepared = vec![machine];

        let error =
            trust_cg_process_env::with_env_overrides(&[("TCG_DATAFLOW_INTEGRITY", "off")], || {
                validate_aarch64_dataflow_integrity(
                    &prepared,
                    &lir_functions,
                    Aarch64DataflowIntegrityPolicy::ProofGradeEnforce,
                )
            })
            .expect_err(
                "proof-grade mode must reject code after a terminator even under ambient off",
            );
        assert!(
            error.to_string().contains("InstructionAfterTerminator")
                || error.to_string().contains("unconditional terminator"),
            "{error}"
        );
    }

