    #[test]
    fn prepared_aarch64_diagnostic_preserves_objects_when_output_succeeds_or_fails() {
        let module = const_i64_module("prepared-diagnostic", "constant", 43);
        let compiler = Compiler::new_for_target_spec(
            CompilerConfig {
                emit_proofs: false,
                parallel: false,
                ..CompilerConfig::default()
            },
            TargetSpec::parse("aarch64-unknown-linux-gnu").unwrap(),
        )
        .with_codegen_license(permit_unlicensed());
        let key = "TCG_DUMP_AARCH64_PREPARED";
        let baseline =
            trust_cg_process_env::with_env_overrides_removed(&[key], || compiler.compile(&module))
                .unwrap();
        let dir = tempfile::tempdir().unwrap();
        let captured = trust_cg_process_env::with_env_overrides(
            &[(key, dir.path().to_str().unwrap())],
            || compiler.compile(&module),
        )
        .unwrap();
        assert_eq!(baseline.object_code, captured.object_code);
        let paths: Vec<_> = dir
            .path()
            .read_dir()
            .unwrap()
            .map(|p| p.unwrap().path())
            .collect();
        assert_eq!(paths.len(), 1);
        assert!(paths[0].join("snapshot.json").is_file());
        let bad = dir.path().join("sentinel");
        std::fs::write(&bad, b"keep").unwrap();
        let after_error =
            trust_cg_process_env::with_env_overrides(&[(key, bad.to_str().unwrap())], || {
                compiler.compile(&module)
            })
            .unwrap();
        assert_eq!(baseline.object_code, after_error.object_code);
        assert_eq!(std::fs::read(bad).unwrap(), b"keep");
    }

    /// One function outside the x86-64 source-bound body lane: `fn(a: i128,
    /// n: i128) -> i128 { a << n }`. The lane refuses an `I128` shift by a
    /// variable amount by name (the selector's register-pair lowering does
    /// not reduce the amount modulo 128), so the function's rows stay
    /// sampled evidence whatever proof tools the host has.
    #[cfg(feature = "verify")]
    fn wide_shift_module(module_name: &str, function_name: &str) -> trust_ir::Module {
        use trust_ir::{BinOp, Ty};
        use trust_ir_build::ModuleBuilder;

        let mut mb = ModuleBuilder::new(module_name);
        let ty = mb.add_func_type(vec![Ty::I128, Ty::I128], vec![Ty::I128]);
        let mut fb = mb.function(function_name, ty);
        let entry = fb.create_block();
        let a = fb.add_block_param(entry, Ty::I128);
        let n = fb.add_block_param(entry, Ty::I128);
        fb.switch_to_block(entry);
        let shifted = fb.binop(BinOp::Shl, Ty::I128, a, n);
        fb.ret(vec![shifted]);
        fb.build();
        mb.build().expect("ModuleBuilder::build: test fixture")
    }

    #[test]
    fn riscv_compiler_route_marks_lp64d_elf_abi() {
        let compiler = Compiler::new(CompilerConfig {
            opt_level: OptLevel::O0,
            target: Target::Riscv64,
            parallel: false,
            ..CompilerConfig::default()
        })
        .with_codegen_license(permit_unlicensed());
        let result = compiler
            .compile(&const_i64_module("riscv_lp64d_flags", "answer", 42))
            .expect("RISC-V compiler route should emit an ELF object");

        assert_eq!(&result.object_code[..4], b"\x7fELF");
        let e_flags = u32::from_le_bytes(
            result.object_code[48..52]
                .try_into()
                .expect("ELF64 e_flags has four bytes"),
        );
        assert_eq!(e_flags, crate::elf::constants::EF_RISCV_FLOAT_ABI_DOUBLE);
    }

    fn riscv_external_call_module(external_name: &str) -> trust_ir::Module {
        use trust_ir::{
            Block as TrustIrBlock, BlockId, FuncId, FuncTy, Function as TrustIrFunction, Inst,
            InstrNode, Module as TrustIrModule,
        };

        let mut module = TrustIrModule::new("riscv_external_call");
        let function_type = module
            .add_func_type(FuncTy {
                params: vec![],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        module
            .try_add_function(TrustIrFunction::new(
                FuncId::new(1),
                external_name,
                function_type,
                BlockId::new(0),
            ))
            .expect("Module::try_add_function: test fixture");

        let mut caller =
            TrustIrFunction::new(FuncId::new(0), "caller", function_type, BlockId::new(0));
        caller.blocks = vec![TrustIrBlock {
            id: BlockId::new(0),
            params: vec![],
            body: vec![
                InstrNode::new(Inst::Call {
                    callee: FuncId::new(1),
                    args: vec![],
                }),
                InstrNode::new(Inst::Return { values: vec![] }),
            ],
        }];
        module
            .try_add_function(caller)
            .expect("Module::try_add_function: test fixture");
        // An FFI boundary needs a pinned target (`TargetInfoRequired`; every
        // ingestion entry refuses what trust-ir's validator refuses, WS7.3).
        module.target_info = Some(trust_ir::TargetInfo {
            triple: "riscv64gc-unknown-linux-gnu".into(),
            pointer_size: 8,
            endianness: trust_ir::Endianness::Little,
            abi: None,
            struct_passing: trust_ir::StructPassingPolicy::NativeC,
        });
        module
    }

    /// The RISC-V module ELF carries `.note.GNU-stack`, and an external call
    /// still relocates against the named callee.
    #[test]
    fn riscv_module_elf_marks_stack_non_executable() {
        let compiler = Compiler::new(CompilerConfig {
            opt_level: OptLevel::O0,
            target: Target::Riscv64,
            parallel: false,
            ..CompilerConfig::default()
        })
        .with_codegen_license(permit_unlicensed());
        for module in [
            const_i64_module("riscv_note", "answer", 42),
            riscv_external_call_module("external_callee"),
        ] {
            let object = compiler
                .compile(&module)
                .expect("RISC-V compiler route should emit an ELF object")
                .object_code;
            let records = crate::elf::reparse::read_object_records(&object).expect("reparse ELF");
            let note = records
                .sections
                .iter()
                .find(|section| section.name == ".note.GNU-stack")
                .expect("module ELF must carry the GNU non-executable-stack marker");
            assert_eq!(
                (note.sh_type, note.sh_flags, note.size),
                (crate::elf::constants::SHT_PROGBITS, 0, 0)
            );
        }
    }

    /// Definition and call-relocation symbol names are validated before the
    /// module ELF writer is touched: an empty name or an embedded NUL would
    /// silently become a different `.strtab` identity.
    #[test]
    fn riscv_module_elf_rejects_invalid_definition_and_call_target_names() {
        let compiler = Compiler::new(CompilerConfig {
            opt_level: OptLevel::O0,
            target: Target::Riscv64,
            parallel: false,
            ..CompilerConfig::default()
        })
        .with_codegen_license(permit_unlicensed());

        for invalid in ["", "bad\0name"] {
            let definition_error = compiler
                .compile(&const_i64_module("invalid_definition", invalid, 42))
                .expect_err("module ELF must reject invalid definition names")
                .to_string();
            assert!(
                definition_error.contains("defined function"),
                "{definition_error}"
            );
            assert!(
                definition_error.contains("must not be empty")
                    || definition_error.contains("embedded NUL"),
                "{definition_error}"
            );

            let call_error = compiler
                .compile(&riscv_external_call_module(invalid))
                .expect_err("module ELF must reject invalid call relocation targets")
                .to_string();
            assert!(
                call_error.contains("call relocation target"),
                "{call_error}"
            );
            assert!(
                call_error.contains("must not be empty") || call_error.contains("embedded NUL"),
                "{call_error}"
            );
        }
    }

    #[test]
    fn riscv_call_fixup_rebase_rejects_u32_truncation_and_wraparound() {
        let fixup = crate::riscv::pipeline::RiscVCallFixup {
            auipc_offset: 4,
            jalr_offset: 8,
            callee: "callee".to_string(),
        };

        let rebased = rebase_riscv_call_fixup("caller", u64::from(u32::MAX) - 8, &fixup)
            .expect("boundary-fitting call fixup should rebase exactly");
        assert_eq!(rebased.auipc_offset, u32::MAX - 4);
        assert_eq!(rebased.jalr_offset, u32::MAX);

        let wrap = rebase_riscv_call_fixup("caller", u64::from(u32::MAX) - 4, &fixup)
            .expect_err("JALR rebase must not wrap past u32::MAX");
        assert!(wrap.to_string().contains("JALR call fixup"), "{wrap}");

        let truncation = rebase_riscv_call_fixup("caller", u64::from(u32::MAX) + 1, &fixup)
            .expect_err("function base must not truncate into the u32 patch domain");
        assert!(
            truncation
                .to_string()
                .contains("outside the u32 patch domain"),
            "{truncation}"
        );
    }

    /// The RISC-V module object is serialized through the checked ELF
    /// funnel: an external call whose 8-byte AUIPC+JALR `R_RISCV_CALL` field
    /// runs past `.text` is refused, where the unchecked serializer this path
    /// used to call laid it down for the linker to patch bytes beyond the
    /// section. The same call inside `.text` still relocates against its
    /// callee.
    #[test]
    fn riscv_module_object_refuses_a_call_relocation_past_text() {
        use crate::riscv::pipeline::RiscVCallFixup;

        // `addi x0, x0, 0` + `jalr x0, 0(ra)`: one 8-byte function.
        let text = [0x13, 0, 0, 0, 0x67, 0x80, 0, 0];
        let layout = [("caller".to_string(), 0u64, 8u64, Vec::new())];
        let call = |auipc_offset: u32| RiscVCallFixup {
            auipc_offset,
            jalr_offset: auipc_offset + 4,
            callee: "external_callee".to_string(),
        };

        for auipc_offset in [4, 16] {
            let error = riscv_module_object(
                &text,
                &layout,
                &[call(auipc_offset)],
                &RiscvFunctionBindings::default(),
            )
            .expect_err("a call field past .text must be refused");
            let message = error.to_string();
            assert!(
                message.contains("ELF reparse gate")
                    && message.contains(&format!("R_TYPE {}", crate::elf::constants::R_RISCV_CALL))
                    && message.contains("beyond its 0x8-byte section"),
                "{message}"
            );
        }

        let object = riscv_module_object(
            &text,
            &layout,
            &[call(0)],
            &RiscvFunctionBindings::default(),
        )
        .expect("a call field inside .text is well formed");
        let records = crate::elf::reparse::read_object_records(&object).expect("reparse ELF");
        let [relocation] = records.relocations.as_slice() else {
            panic!("expected one relocation: {:?}", records.relocations);
        };
        assert_eq!(relocation.record.r_offset, 0);
        assert_eq!(
            relocation.record.reloc_type,
            crate::elf::constants::R_RISCV_CALL
        );
        let symbol = &records.symbols[relocation.record.symbol_index as usize];
        assert_eq!(symbol.name, "external_callee");
        assert!(symbol.is_undefined_reference());
    }

