    /// A spelled-out triple compiles identically on every host: its effective
    /// triple and its x86-64 object format are functions of the triple alone.
    /// Only an architecture alias consults the host OS.
    #[test]
    fn explicit_targets_select_the_same_triple_and_object_format_on_every_host() {
        use crate::x86_64::X86OutputFormat;

        const HOSTS: [&str; 11] = [
            "linux",
            "macos",
            "windows",
            "android",
            "freebsd",
            "netbsd",
            "openbsd",
            "dragonfly",
            "illumos",
            "solaris",
            "",
        ];
        let x86_formats = [
            ("x86_64-unknown-linux-gnu", Some(X86OutputFormat::Elf)),
            ("x86_64-apple-darwin", Some(X86OutputFormat::MachO)),
            ("x86_64-pc-windows-msvc", Some(X86OutputFormat::Coff)),
            ("x86_64-unknown-unknown", None),
        ];
        for host in HOSTS {
            for triple in [
                "aarch64-unknown-unknown",
                "aarch64-unknown-linux-gnu",
                "aarch64-apple-darwin",
                "arm64-apple-macosx12.0",
                "x86_64-unknown-unknown",
                "x86_64-unknown-linux-gnu",
                "x86_64-apple-darwin",
                "x86_64-pc-windows-msvc",
            ] {
                let spec = TargetSpec::parse(triple).unwrap();
                assert_eq!(
                    compiler_target_triple_on_host(spec, host),
                    spec.triple(),
                    "{triple} on host `{host}`"
                );
            }
            for (triple, expected) in x86_formats {
                let spec = TargetSpec::parse(triple).unwrap();
                match (
                    x86_64_aot_output_format_for_target_spec_on_host(spec, host),
                    expected,
                ) {
                    (Ok(actual), Some(expected)) => {
                        assert_eq!(actual, expected, "{triple} on host `{host}`");
                    }
                    (
                        Err(CompileError::X86AotObjectFormatUnsupported {
                            target_os,
                            required_format,
                            context,
                        }),
                        None,
                    ) => {
                        assert_eq!(target_os, "unknown", "{triple} on host `{host}`");
                        assert_eq!(required_format, "native object format");
                        assert!(context.contains("never inherits the host"), "{context}");
                    }
                    (other, expected) => {
                        panic!("{triple} on host `{host}`: expected {expected:?}, got {other:?}")
                    }
                }
            }
        }

        // Contrast: an architecture alias is the only host-derived request.
        let x86_alias = TargetSpec::unknown_for_architecture(Target::X86_64);
        assert_eq!(
            x86_64_aot_output_format_for_target_spec_on_host(x86_alias, "freebsd").unwrap(),
            X86OutputFormat::Elf
        );
        assert_eq!(
            x86_64_aot_output_format_for_target_spec_on_host(x86_alias, "macos").unwrap(),
            X86OutputFormat::MachO
        );
        assert!(matches!(
            x86_64_aot_output_format_for_target_spec_on_host(x86_alias, "solaris"),
            Err(CompileError::X86AotObjectFormatUnsupported {
                target_os: "solaris",
                ..
            })
        ));
        let aarch64_alias = TargetSpec::unknown_for_architecture(Target::Aarch64);
        assert_eq!(
            compiler_target_triple_on_host(aarch64_alias, "linux"),
            "aarch64-unknown-linux-gnu"
        );
        assert_eq!(
            compiler_target_triple_on_host(aarch64_alias, "macos"),
            "aarch64-apple-darwin"
        );
        assert_eq!(
            compiler_target_triple_on_host(aarch64_alias, "solaris"),
            "aarch64-unknown-unknown"
        );
    }

    /// Both explicit unknown-OS triples keep their spelled-out identity and
    /// are refused before any byte is emitted. With the row above, which
    /// shows neither consults the host, the refusal is the same on every host.
    #[test]
    fn explicit_unknown_os_triples_fail_closed_through_the_compiler() {
        let module = const_i64_module("explicit_unknown_os", "answer", 7);
        let refuse = |triple: &str| {
            let compiler = Compiler::new_for_target_spec(
                CompilerConfig {
                    opt_level: OptLevel::O0,
                    parallel: false,
                    ..CompilerConfig::default()
                },
                TargetSpec::parse(triple).unwrap(),
            )
            .with_codegen_license(permit_unlicensed());
            assert_eq!(
                compiler.target_selection(),
                CompilerTargetSelection {
                    triple: triple.to_string(),
                    origin: TargetSelectionOrigin::Explicit,
                }
            );
            compiler
                .compile(&module)
                .expect_err("an explicit unknown-OS triple must fail closed")
        };
        match refuse("x86_64-unknown-unknown") {
            CompileError::X86AotObjectFormatUnsupported {
                target_os,
                required_format,
                ..
            } => {
                assert_eq!(target_os, "unknown");
                assert_eq!(required_format, "native object format");
            }
            other => panic!("expected the x86-64 object-format refusal, got {other:?}"),
        }
        match refuse("aarch64-unknown-unknown") {
            CompileError::Pipeline(PipelineError::TargetAbiUnresolved(
                trust_cg_lower::abi::AArch64AbiTargetError::Unrecognized(triple),
            )) => assert_eq!(triple, "aarch64-unknown-unknown"),
            other => panic!("expected the AArch64 target-ABI refusal, got {other:?}"),
        }
    }

