    #[test]
    fn test_compile_module_to_jit_rejects_non_host_target() {
        use std::collections::HashMap;
        use trust_ir_build::ModuleBuilder;

        let target = match Target::host() {
            Target::Aarch64 => Target::X86_64,
            Target::X86_64 | Target::Riscv64 => Target::Aarch64,
        };
        let compiler = Compiler::jit_fast(target);
        let module = ModuleBuilder::new("jit_target_mismatch")
            .build()
            .expect("ModuleBuilder::build: test fixture");
        let err = compiler
            .compile_module_to_jit(&module, &HashMap::new())
            .unwrap_err();

        assert!(
            matches!(
                err,
                CompileError::JitTargetMismatch {
                    target: actual_target,
                    host
                } if actual_target == target && host == Target::host()
            ),
            "expected JitTargetMismatch for {target:?}, got {err}"
        );
    }

    #[cfg(any(target_arch = "aarch64", target_arch = "x86_64"))]
    #[test]
    fn test_host_jit_rejects_same_architecture_non_host_abi() {
        let requested = match Target::host() {
            Target::Aarch64 if cfg!(target_os = "macos") => {
                TargetSpec::parse("aarch64-unknown-linux-gnu").unwrap()
            }
            Target::Aarch64 => TargetSpec::parse("aarch64-apple-darwin").unwrap(),
            Target::X86_64 if cfg!(target_os = "macos") => {
                TargetSpec::parse("x86_64-unknown-linux-gnu").unwrap()
            }
            Target::X86_64 => TargetSpec::parse("x86_64-apple-darwin").unwrap(),
            Target::Riscv64 => unreachable!("test is limited to wired JIT hosts"),
        };
        let compiler = Compiler::new_for_target_spec(CompilerConfig::for_host_jit(), requested)
            .with_codegen_license(permit_unlicensed());
        let err = compiler
            .ensure_host_jit_target()
            .expect_err("same-architecture cross-ABI JIT must fail closed");
        assert!(matches!(
            err,
            CompileError::JitTargetSpecMismatch {
                requested: actual,
                host,
            } if actual == requested && host == TargetSpec::host_for_architecture(Target::host())
        ));
    }

    /// X-DARWIN-P12: host-derived OS/ABI selection is explicit and recorded,
    /// and an explicit cross-target never inherits the host's.
    #[test]
    fn target_selection_records_host_derivation_and_explicit_targets() {
        use trust_ir_build::ModuleBuilder;

        let host_os = std::env::consts::OS;
        let derived = Compiler::new(CompilerConfig {
            target: Target::Aarch64,
            ..CompilerConfig::default()
        })
        .with_codegen_license(permit_unlicensed());
        let selection = derived.target_selection();
        assert_eq!(
            selection.origin,
            TargetSelectionOrigin::HostDerived { host_os },
            "Compiler::new names only an architecture"
        );
        assert_eq!(
            selection.triple,
            compiler_target_triple(TargetSpec::host_for_architecture(Target::Aarch64))
        );

        for (spec, origin) in [
            (
                TargetSpec::parse("aarch64-unknown-linux-gnu").unwrap(),
                TargetSelectionOrigin::Explicit,
            ),
            (
                TargetSpec::parse("aarch64-apple-darwin").unwrap(),
                TargetSelectionOrigin::Explicit,
            ),
            (
                TargetSpec::parse("aarch64").unwrap(),
                TargetSelectionOrigin::HostDerived { host_os },
            ),
            (
                TargetSpec::parse("riscv64").unwrap(),
                TargetSelectionOrigin::ArchitectureDefault,
            ),
        ] {
            let compiler = Compiler::new_for_target_spec(CompilerConfig::default(), spec)
                .with_codegen_license(permit_unlicensed());
            assert_eq!(compiler.target_selection().origin, origin, "{spec:?}");
        }

        // The record travels with the artifact, and an explicit target that
        // differs from the host keeps its own triple and object format.
        let mut builder = ModuleBuilder::new("target_selection_record");
        let signature = builder.add_func_type(vec![], vec![trust_ir::Ty::I64]);
        let mut function = builder.function("answer", signature);
        let entry = function.create_block();
        function.switch_to_block(entry);
        let value = function.iconst(trust_ir::Ty::I64, 42);
        function.ret(vec![value]);
        function.build();
        let module = builder.build().expect("ModuleBuilder::build: test fixture");
        let explicit_cross = if cfg!(target_os = "macos") {
            "aarch64-unknown-linux-gnu"
        } else {
            "aarch64-apple-darwin"
        };
        let compiler = Compiler::new_for_target_spec(
            CompilerConfig::default(),
            TargetSpec::parse(explicit_cross).unwrap(),
        )
        .with_codegen_license(permit_unlicensed());
        let result = compiler.compile(&module).expect("explicit target compiles");
        assert_eq!(
            result.target_selection,
            CompilerTargetSelection {
                triple: explicit_cross.to_owned(),
                origin: TargetSelectionOrigin::Explicit,
            }
        );
        let elf = result.object_code.starts_with(b"\x7fELF");
        assert_eq!(
            elf,
            explicit_cross.contains("linux"),
            "object format follows the target"
        );
        let result = derived
            .compile(&module)
            .expect("host-derived target compiles");
        assert_eq!(result.target_selection, derived.target_selection());
    }

