    /// The post-emission Mach-O relocation digest runs inside
    /// `Compiler::compile` over the exact object bytes it returns, including
    /// a compile-artifact cache HIT, where neither an emitter nor the ENC-9
    /// reparse gate runs. A cached aarch64 Mach-O object that gained one
    /// relocation, or whose relocation changed kind or shape, fails the
    /// compile with `RelocationInventoryDigest`. Deleting the digest call
    /// fails this test. (The digest compares kinds: a relocation moved to
    /// another address with its kind and shape kept is not detected.)
    #[cfg(feature = "verify")]
    #[test]
    fn aarch64_macho_compile_digest_refuses_tampered_cached_object_relocations() {
        use trust_ir::{
            Block as TrustIrBlock, BlockId, FuncId, FuncTy, Function as TrustIrFunction, Inst,
            InstrNode, Module as TrustIrModule,
        };

        let root = temp_cache_root("macho-digest-wiring");
        // A bare `ret`: no constant or copy row, so the proofs-on compile
        // promotes and reaches emission; its compact-unwind entry is the
        // object's relocation.
        let mut module = TrustIrModule::new("compiler_macho_digest");
        let ft = module
            .add_func_type(FuncTy {
                params: vec![],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let mut func = TrustIrFunction::new(FuncId::new(0), "unit", ft, BlockId::new(0));
        func.blocks = vec![TrustIrBlock {
            id: BlockId::new(0),
            params: vec![],
            body: vec![InstrNode::new(Inst::Return { values: vec![] })],
        }];
        module
            .try_add_function(func)
            .expect("Module::try_add_function: test fixture");
        let target_spec = TargetSpec::parse("aarch64-apple-darwin").unwrap();
        let config = CompilerConfig {
            opt_level: OptLevel::O0,
            emit_proofs: true,
            parallel: false,
            ..CompilerConfig::default()
        };
        let cache_config = test_cache_config(&root, CompileArtifactProofPolicy::Unchecked);
        let compile = || {
            Compiler::new_for_target_spec(config.clone(), target_spec)
                .with_codegen_license(permit_unlicensed())
                .with_compile_artifact_cache(cache_config.clone())
                .compile(&module)
        };

        let first = compile().expect("a proofs-on aarch64 Mach-O compile populates the cache");
        let entry = first
            .compile_artifact_cache_telemetry
            .iter()
            .find(|event| event.status == CompileArtifactCacheStatus::Stored)
            .expect("the first compile stores its object")
            .cache_path
            .clone();
        let object = first.object_code.clone();
        // Replace the cached object and re-seal its manifest, so the cache
        // accepts the entry as a HIT and only the digest can refuse it.
        let tamper = |bytes: &[u8]| {
            std::fs::write(entry.join("artifact.bin"), bytes).unwrap();
            let manifest_path = entry.join("manifest.json");
            let mut manifest: serde_json::Value =
                serde_json::from_slice(&std::fs::read(&manifest_path).unwrap()).unwrap();
            manifest["artifact"]["sha256"] = serde_json::Value::String(format!(
                "sha256:{}",
                crate::jit_diagnostics::sha256_hex(bytes)
            ));
            manifest["artifact"]["size_bytes"] = serde_json::json!(bytes.len());
            std::fs::write(
                &manifest_path,
                serde_json::to_vec_pretty(&manifest).unwrap(),
            )
            .unwrap();
        };
        let replays = |what: &str| {
            let result = compile().unwrap_or_else(|error| panic!("{what}: {error}"));
            assert_eq!(
                result
                    .compile_artifact_cache_telemetry
                    .iter()
                    .map(|event| event.status)
                    .collect::<Vec<_>>(),
                vec![CompileArtifactCacheStatus::Hit],
                "{what}"
            );
            result
        };
        let refused = |what: &str, reason: &str| match compile() {
            Err(CompileError::Pipeline(
                crate::pipeline::PipelineError::RelocationInventoryDigest(message),
            )) => assert!(message.contains(reason), "{what}: {message}"),
            Err(other) => panic!("{what}: expected RelocationInventoryDigest, got {other}"),
            Ok(_) => panic!("{what}: a tampered cached object must not ship"),
        };

        // Control: an untouched entry replays as a hit and passes the digest.
        assert_eq!(replays("untampered cache hit").object_code, object);

        // The first section carrying relocations: (header, reloff, nreloc).
        let rd = |bytes: &[u8], off: usize| {
            u32::from_le_bytes(bytes[off..off + 4].try_into().unwrap()) as usize
        };
        let (header, reloff, nreloc) = {
            let mut found = None;
            let mut command = 32;
            'commands: for _ in 0..rd(&object, 16) {
                if rd(&object, command) == 0x19 {
                    for index in 0..rd(&object, command + 64) {
                        let header = command + 72 + index * 80;
                        if rd(&object, header + 60) > 0 {
                            found =
                                Some((header, rd(&object, header + 56), rd(&object, header + 60)));
                            break 'commands;
                        }
                    }
                }
                command += rd(&object, command + 4);
            }
            found.expect("the object carries at least its compact-unwind relocation")
        };

        // (a) One extra relocation: the section's table is re-laid at the end
        // of the object with a copy of its first record at `r_address + 16`.
        let mut extra = object.clone();
        while !extra.len().is_multiple_of(8) {
            extra.push(0);
        }
        let new_reloff = u32::try_from(extra.len()).unwrap();
        extra.extend_from_slice(&object[reloff..reloff + nreloc * 8]);
        let mut added: [u8; 8] = object[reloff..reloff + 8].try_into().unwrap();
        let address = u32::from_le_bytes(added[..4].try_into().unwrap()) + 16;
        added[..4].copy_from_slice(&address.to_le_bytes());
        extra.extend_from_slice(&added);
        extra[header + 56..header + 60].copy_from_slice(&new_reloff.to_le_bytes());
        extra[header + 60..header + 64]
            .copy_from_slice(&u32::try_from(nreloc + 1).unwrap().to_le_bytes());
        tamper(&extra);
        refused(
            "a cached object with one uninventoried relocation",
            "must never ship",
        );

        tamper(&object);
        replays("restored cache entry");

        // (b) Same count, another kind: the first record's r_type becomes
        // ARM64_RELOC_AUTHENTICATED_POINTER (11), which no inventory row names.
        let mut rekinded = object.clone();
        let word = reloff + 4;
        let value = u32::from_le_bytes(rekinded[word..word + 4].try_into().unwrap());
        rekinded[word..word + 4]
            .copy_from_slice(&((value & 0x0FFF_FFFF) | (11 << 28)).to_le_bytes());
        tamper(&rekinded);
        refused(
            "a cached object whose relocation changed kind",
            "AArch64MachOOther(11)",
        );

        // (c) Same kind, another shape: the first record turns pc-relative.
        let mut pcrel = object.clone();
        pcrel[word..word + 4].copy_from_slice(&(value | (1 << 24)).to_le_bytes());
        tamper(&pcrel);
        refused(
            "a cached object whose relocation changed shape",
            "value-proof lane",
        );

        std::fs::remove_dir_all(root).unwrap();
    }

    #[cfg(not(target_os = "windows"))]
    #[test]
    fn test_x86_compile_runtime_count_alloca_threads_stack_slot_metadata() {
        let module = runtime_count_alloca_module("x86_runtime_count_alloca");
        let compiler = Compiler::new(CompilerConfig {
            opt_level: OptLevel::O0,
            target: Target::X86_64,
            parallel: false,
            ..CompilerConfig::default()
        })
        .with_codegen_license(permit_unlicensed());

        let result = compiler
            .compile(&module)
            .expect("x86 Compiler dispatcher should compile runtime-count Alloca");

        assert_eq!(result.metrics.function_count, 1);
        assert!(result.metrics.code_size_bytes > 0);
        let output_format = x86_64_aot_output_format_for_target_spec(compiler.target_spec())
            .expect("x86 compiler target spec should select an object format");
        let expected_unwind_sections: &[&[u8]] = match output_format {
            crate::x86_64::X86OutputFormat::Elf => &[b".eh_frame", b".rela.eh_frame"],
            crate::x86_64::X86OutputFormat::MachO => &[b"__eh_frame"],
            crate::x86_64::X86OutputFormat::Coff => &[b".pdata", b".xdata"],
            crate::x86_64::X86OutputFormat::RawBytes => {
                panic!("x86 compiler AOT target should not emit raw bytes")
            }
        };
        for section in expected_unwind_sections {
            assert!(
                result
                    .object_code
                    .windows(section.len())
                    .any(|window| window == *section),
                "runtime-sized x86 StackAddr object should carry DWARF unwind fallback section {}",
                String::from_utf8_lossy(section)
            );
        }
    }

    #[cfg(not(target_os = "windows"))]
    #[test]
    fn test_x86_public_dispatch_opt_level_metrics_follow_x86_schedule() {
        use trust_ir::Ty;
        use trust_ir_build::ModuleBuilder;

        let build_module = || {
            let mut mb = ModuleBuilder::new("x86_opt_level_metrics");
            let ty = mb.add_func_type(vec![], vec![Ty::I64]);
            let mut fb = mb.function("const_fn", ty);
            let entry = fb.create_block();
            fb.switch_to_block(entry);
            let value = fb.iconst(Ty::I64, 42);
            fb.ret(vec![value]);
            fb.build();
            mb.build().expect("ModuleBuilder::build: test fixture")
        };

        let compile_at = |opt_level| {
            let compiler = Compiler::new(CompilerConfig {
                opt_level,
                target: Target::X86_64,
                parallel: false,
                ..CompilerConfig::default()
            })
            .with_codegen_license(permit_unlicensed());
            compiler
                .compile(&build_module())
                .expect("x86 public Compiler dispatcher should compile const module")
        };

        let o0 = compile_at(OptLevel::O0);
        let o1 = compile_at(OptLevel::O1);
        let o2 = compile_at(OptLevel::O2);

        assert_eq!(o0.metrics.function_count, 1);
        assert_eq!(o0.metrics.optimization_passes_run, 0);
        // O1 = LICM, copy-prop, peephole, DCE, if-convert, branch-layout.
        // O2 adds vectorize, SROA, strength-reduce, loop-unroll, const-fold,
        // const-guard-elim, CSE, the dominated-compare bounds-check
        // elimination, loop rotation, and conditional-swap (SROA added in c70e396,
        // bounds-check-elim in f6f73d3, loop rotation defaulted on in
        // c033ba54, full unroll + const-guard-elim defaulted on 2026-07-20,
        // conditional-swap defaulted on in bbc02c7f, straight-line
        // block-merge added 2026-08-09).
        // See `X86Pipeline::x86_o1_pass_manager` / `x86_o2_pass_manager`.
        assert_eq!(o1.metrics.optimization_passes_run, 6);
        // 19 since 2026-09-29: a SECOND vectorizer run immediately after SROA,
        // where an owning-container reduction first has a recognisable shape, and
        // frame-slot value forwarding between the block merge and copy-prop.
        // 20 since b05256f78 (2026-10-01): xorshift demanded bits is DEFAULT ON
        // and REGISTERED after the bounds-check elimination, before DCE. This
        // metric is the sum of `run_x86_optimization_passes(..).total_pass_runs()`
        // over the one function: the schedule that
        // `x86_opt_level_o0_preserves_o2_rewrites_isel_shape` (`== 20`) and the
        // two pass-name pins in `x86_64/pipeline.rs` fix. The opt-out
        // (`TCG_NO_X86_XORSHIFT_DEMANDED_BITS`) unregisters it: 19.
        assert_eq!(o2.metrics.optimization_passes_run, 20);
        assert!(o0.metrics.code_size_bytes > 0);
        assert!(o1.metrics.code_size_bytes > 0);
        assert!(o2.metrics.code_size_bytes > 0);
    }

    #[cfg(not(target_os = "windows"))]
