    #[cfg(feature = "verify")]
    #[test]
    fn test_proof_required_rejects_erroneous_source_bound_frame_by_name() {
        use trust_cg_ir::regs::{SpecialReg, X0, X29, X30};
        use trust_cg_ir::{AArch64Opcode, MachFunction, MachInst, MachOperand, Signature, Type};
        use trust_cg_lower::function::{BasicBlock, Signature as LirSignature};
        use trust_cg_lower::instructions::{Instruction, Opcode, Value};

        let mut lir = trust_cg_lower::Function::new(
            "framed_answer",
            LirSignature {
                params: vec![],
                returns: vec![trust_cg_lower::Type::I64],
            },
        );
        lir.blocks.insert(
            lir.entry_block,
            BasicBlock {
                instructions: vec![
                    Instruction {
                        opcode: Opcode::Iconst {
                            imm: 42,
                            ty: trust_cg_lower::Type::I64,
                        },
                        args: vec![],
                        results: vec![Value(0)],
                    },
                    Instruction {
                        opcode: Opcode::Return,
                        args: vec![Value(0)],
                        results: vec![],
                    },
                ],
                ..BasicBlock::default()
            },
        );
        let machine = |constant: i64| {
            let pair = |offset| {
                vec![
                    MachOperand::PReg(X29),
                    MachOperand::PReg(X30),
                    MachOperand::Special(SpecialReg::SP),
                    MachOperand::Imm(offset),
                ]
            };
            let mut func =
                MachFunction::new(lir.name.clone(), Signature::new(vec![], vec![Type::I64]));
            for inst in [
                MachInst::new(AArch64Opcode::StpPreIndex, pair(-16)),
                MachInst::new(
                    AArch64Opcode::AddRI,
                    vec![
                        MachOperand::PReg(X29),
                        MachOperand::Special(SpecialReg::SP),
                        MachOperand::Imm(0),
                    ],
                ),
                MachInst::new(
                    AArch64Opcode::Movz,
                    vec![
                        MachOperand::PReg(X0),
                        MachOperand::Imm(constant),
                        MachOperand::Imm(0),
                    ],
                ),
                MachInst::new(AArch64Opcode::LdpPostIndex, pair(16)),
                MachInst::new(AArch64Opcode::Ret, vec![MachOperand::PReg(X30)]),
            ] {
                let id = func.push_inst(inst);
                func.append_inst(func.entry, id);
            }
            func
        };
        let compiler = Compiler::new(CompilerConfig {
            emit_proofs: true,
            ..CompilerConfig::default()
        })
        .with_codegen_license(permit_unlicensed());
        trust_cg_process_env::with_env_overrides(&[("TCG_REFINE_SOLVER", "0")], || {
            let certs = generate_proof_certificates(
                &machine(43),
                Some(&lir),
                None,
                crate::decode_check::DecodeCheckBacking::Enforced,
            );
            assert_eq!(certs.len(), 1);
            assert_eq!(certs[0].category, "verification_precondition");
            assert!(!certs[0].verified);
            assert!(
                certs[0]
                    .strength
                    .contains("[TCG-SOURCE-BOUND-FRAME-MISMATCH]")
            );
            for rejection in [
                compiler.ensure_proofs_promotable(Some(&certs)),
                compiler.gate_jit_proofs_promotable(&certs, &[]),
            ] {
                let Err(CompileError::ProofPromotionRejected { reason, .. }) = rejection else {
                    panic!("erroneous supported target must be rejected");
                };
                assert!(
                    reason.contains("[TCG-SOURCE-BOUND-FRAME-MISMATCH]"),
                    "{reason}"
                );
            }
            // The correct body is merely unreplayed here: rejected, but never
            // named as an erroneous target.
            let certs = generate_proof_certificates(
                &machine(42),
                Some(&lir),
                None,
                crate::decode_check::DecodeCheckBacking::Enforced,
            );
            assert!(certs.iter().all(|cert| {
                cert.category != "verification_precondition"
                    && !cert.strength.contains("[TCG-SOURCE-BOUND-FRAME-MISMATCH]")
            }));
        });
    }

